(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("apocrypha-kjv-b",[{"sp": "HDR", "t": "ΕΣΔΡΑΣ Αʹ"}, {"sp": "N", "st": "1 Esd 1:1", "t": "ΚΑΙ ἤγαγεν Ἰωσείας τὸ πάσχα ἐν Ἰερουσαλὴμ τῷ κυρίῳ αὐτοῦ, καὶ ἔθυσαν τὸ πάσχα τῇ τεσσαρεσκαιδεκάτῃ ἡμέρᾳ τοῦ μηνὸς τοῦ πρώτου,"}, {"sp": "N", "st": "1 Esd 1:2", "t": "στήσας τοὺς ἱερεῖς κατʼ ἐφημερίας ἐστολισμένους ἐν τῷ ἱερῷ τοῦ κυρίου."}, {"sp": "N", "st": "1 Esd 1:3", "t": "καὶ εἶπεν τοῖς Λευείταις, ἱεροδούλοις τοῦ Ἰσραήλ, ἁγιάσαι αὐτοὺς τῷ κυρίῳ ἐν τῇ θέσει τῆς ἁγίας κιβωτοῦ τοῦ κυρίου ἐν τῷ οἴκῳ ᾧ ᾠκοδόμησεν Σαλωμὼν ὁ τοῦ Δαυεὶδ ὁ βασιλεύς·"}, {"sp": "N", "st": "1 Esd 1:4", "t": "Οὐκ ἔσται ὑμῖν ἄραι ἐπʼ ὤμῶν αὐτήν· καὶ νῦν λατρεύετε τῷ κυρίῳ θεῷ ὑμῶν, καὶ θεραπεύετε τὸ ἔθνος αὐτοῦ Ἰσραήλ, καὶ ἑτοιμάσατε κατὰ τὰς πατριὰς καὶ τὰς φυλὰς ὑμῶυ )(⁵)κατὰ τὴν γραφὴν Δαυεὶδ βασιλέως Ἰσραὴλ καὶ κατὰ τὴν μεγαλειότητα Σαλωμὼν τοῦ υἱοῦ αὐτοῦ·"}, {"sp": "N", "st": "1 Esd 1:5", "t": "καὶ στάντες ἐν τῷ ἁγίῳ κατὰ τὴν μεριδαρχίαν τὴν πατρικὴν ὑμῶν τῶν Λευειτῶν τῶν ἔμπροσθεν τῶν ἀδελφῶν ὑμῶν υἱῶν Ἰσραὴλ"}, {"sp": "N", "st": "1 Esd 1:6", "t": "ἐν τάξει, (5) θύσατε τὸ πάσχα, καὶ τὰς θυσίας ἑτοιμάσατε τοῖς ἀδελφοῖς ὑμῶν, καὶ ποιήσατε τὸ πάσχα κατὰ τὸ πρόσταγμα τοῦ κυρίου τὸ δοθὲν τῷ Μωυσῆ."}, {"sp": "N", "st": "1 Esd 1:7", "t": "καὶ ἐδωρήσατο Ἰωσείας τῷ λαῷ τῷ εὑρεθέντι ἀρνῶν καὶ ἐρίφων τριάκοντα χιλιάδας, μόσχ χους τρισχιλίους· (8) ταῦτα ἐκ τῶν βασιλικῶν ἐδόθη κατʼ ἐπαγγελίαν τῷ λαῷ καὶ τοῖς ἱερεῦσιν καὶ Λευείταις."}, {"sp": "N", "st": "1 Esd 1:8", "t": "καὶ ἔδωκεν Κελκείας καὶ Ζαχαρίας καὶ Ἠσύηλος οἱ ἐπιστάται τοῦ ἱεροῦ τοῖς ἱερεῦσιν εἰς πάσχα πρόβατα δισχίλια ἑξακόσια, μόσχους τριακοσίους."}, {"sp": "N", "st": "1 Esd 1:9", "t": "καὶ Ἰεχονίας καὶ Σαμαίας καὶ Ναθαναὴλ ὁ ἀδελφὸς καὶ Σαβίας καὶ Οχίηλος καὶ Ἰωρὰμ χιλίαρχοι ἔδωκαν τοῖς Λευείταις εἰς πάσχα πρόβατα χίλια, μόσχους ἑπτακοσίους."}, {"sp": "N", "st": "1 Esd 1:10", "t": "καὶ ταῦτα τὰ γενόμενα· εὐπρεπῶς ἔστησαν οἱ ἱερεῖς καὶ οἱ Λευεῖται, ἔχοντες τὰ ἄζυμα, κατὰ τὰς φυλὰς (¹¹)καὶ κατὰ τὰς μεριδαρχίας τῶν πατέρων ἔμπροσθεν τοῦ λαοῦ, προσενεγκεῖν τῷ κυρίῳ κατὰ τὰ γεγραμμένα ἐν βιβλίῳ Μωυσῆ· καὶ οὕτω τὸ πρωινόν."}, {"sp": "N", "st": "1 Esd 1:11", "t": "καὶ ὤπτησαν τὸ πάσχα ἐν πυρὶ ὡς καθήκει, καὶ τὰς θυσίας ἥψησαν ἐν τοῖς χαλκίοις καὶ λέβησιν μετʼ εὐωδίας, (¹³)καὶ ἀπήνεγκαν πᾶσι τοῖς ἐκ τοῦ λαοῦ."}, {"sp": "N", "st": "1 Esd 1:12", "t": "μετὰ δὲ ταῦτα ἡτοι μασαν ἑαυτοῖς τε καὶ τοῖς ἱερεῦσιν ἀδελφοῖς αὐτῶν υἱοῖς Ἀαρών."}, {"sp": "N", "st": "1 Esd 1:13", "t": "οἱ γὰρ ἱερεῖς ἀνέφερον τὰ στέατα ἕως ἀωρίας· καὶ οἱ Λευεῖται ἡτοίμασαν ἑαυτοῖς καὶ τοῖς ἱερεῦσιν ἀδελφοῖς αὐτῶν υἱοῖς Ἀαρών."}, {"sp": "N", "st": "1 Esd 1:14", "t": "καὶ οἱ ἱεροψάλται υἱοὶ Ἀσὰφ ἦσαν ἐπὶ τῆς τάξεως αὐτῶν κατὰ τὰ ὑπὸ Δαυεὶδ τεταγμένα, καὶ Ἀσὰφ καὶ Ζαχαρίας καὶ Ἐβδεινοῦς οἱ παρὰ τοῦ βασιλέως."}, {"sp": "N", "st": "1 Esd 1:15", "t": "καὶ οἱ θυρωροὶ ἐφʼ ἑκάστου πυλῶος· οὐκ ἔστιν παραβῆναι ἕκαστον τὴν ἑαυτοῦ ἐφημερίαν· οἱ γὰρ ἀδελφοὶ αὐτῶν οἱ Λευεῖται ἡτοίμασαν ἑαυτοῖς."}, {"sp": "N", "st": "1 Esd 1:16", "t": "καὶ συνετελέσθη τὰ τῆς θυσίας τοῦ κυρίου (¹8)ἐν ἐκείνῃ τῇ ἡμέρα, ἀχθῆναι τὸ πάσχα καὶ προσαχθῆναι τὰς θυσίας ἐπὶ τὸ τοῦ κυρίου θυσιαστήριον κατὰ τὴν ἐπιταγὴν τοῦ βασλέως Ἰωσείου."}, {"sp": "N", "st": "1 Esd 1:17", "t": "καὶ ἠγάγοσαν οἱ υἱοὶ Ἰσραὴλ οἱ εὑρεθέντες ἐν τῷ καιρῷ τούτῳ τὸ πάσχα καὶ τὴν ἑορτὴν τῶν ἀζύμων ἡμέρας ἑπτά."}, {"sp": "N", "st": "1 Esd 1:18", "t": "καὶ οὐκ ἤχθη τὸ πάσχα τοιοῦτο ἐν τῷ Ἰσραὴλ ἀπὸ τῶν χρόνων Σαμουὴλ τοῦ προφήτου·"}, {"sp": "N", "st": "1 Esd 1:19", "t": "καὶ πάντες οἱ βασιλεῖς τοῦ Ἰσραὴλ οὐκ ἠγάγοσαν πάσχα τοιοῦτον οἷον ἥγαγεν Ἰωσείας καὶ οἱ ἱερεῖς καὶ οἱ Λευεῖται καὶ οἱ Ἰουδαῖοι καὶ πᾶς Ἰσραὴλ ὁ εὑρεθεὶς ἐν τῇ κατοικήσει αὐτῶν ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 1:20", "t": "ὀκτωκαιδεκάτῳ ἔτει βασιλεύοντος Ἰωσείου ἤχθη τὸ πάσχα τοῦτο."}, {"sp": "N", "st": "1 Esd 1:21", "t": "καὶ ὠρθώθη τὰ ἔργα Ἰωσείου ἐνώπιον τοῦ κυρίου αὐτοῦ ἐν καρδίᾳ πλήρει εὐσεβείας."}, {"sp": "N", "st": "1 Esd 1:22", "t": "καὶ τὰ κατʼ αὐτὸν δὲ ἀναγέγραπται ἐν τοῖς ἔμπροσθεν χρόνοις, περὶ τῶν ἡμαρτηκότων καὶ ἠσεβηκότων εἰς τὸν κύριον παρὰ πᾶν ἔθνος καὶ βασιλείαν, καὶ ἃ ἐλύπησαν αὐτὸν ἔστιν· καὶ οἱ λόγοι τοῦ κυρίου ἀνέστησαν ἐπὶ Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 1:23", "t": "Καὶ μετὰ πᾶσαν τὴν πρᾶξιν ταύτην Ἰωσείου συνέβη Φαραὼ βασιλέα Αἰγύπτου ἐλθόντα πόλεμον ἐγεῖραι ἐν Καρκαμὺς ἐπὶ τοῦ Εὐφράτου· καὶ ἐξῆλθεν εἰς ἀπάντησιν αὐτῷ Ἰωσείας."}, {"sp": "N", "st": "1 Esd 1:24", "t": "καὶ διεπέμψατο βασιλεὺς Αἰγύπτου πρὸς αὐτὸν λέγων Τί ἐμοὶ καὶ σοί ἐστιν, βασιλεῦ τῆς Ἰουδαίας;"}, {"sp": "N", "st": "1 Esd 1:25", "t": "οὐχὶ πρὸς σέ ἐξαπέσταλμαι ὑπὸ Κυρίου τοῦ θεοῦ, ἐπὶ γὰρ τοῦ Εὐφράτου ὁ πόλεμός μού ἐστιν· καὶ νῦν Κύριος μετʼ ἐμοῦ ἐστιν, καὶ Κύριος μετʼ ἐμοῦ ἐπισπεύδων ἐστίν· ἀπόστηθι, καὶ μὴ ἐναντιου τῷ κυρίῳ."}, {"sp": "N", "st": "1 Esd 1:26", "t": "καὶ οὐκ ἀπέστρεψεν ἑαυτὸν Ἰωσείας ἐπὶ τὸ ἄρμα αὐτοῦ, ἀλλὰ πολεμεῖν αὐτὸν ἐπιχειρεῖ, οὐ προσέχων ῥήμασιν Ἰερεμίου προφήτου ἐκ στόματος Κυρίου·"}, {"sp": "N", "st": "1 Esd 1:27", "t": "ἀλλὰ συνεστήσατο πρὸς αὐτὸν πόλεμον ἐν τῷ πεδίῳ Μετααδδοῦς· καὶ κατέβησαν οἱ ἄρχοντες πρὸς βασιλέα Ἰωσείαν."}, {"sp": "N", "st": "1 Esd 1:28", "t": "καὶ εἶπεν ὁ βασιλεὺς τοῖς παισὶν αὐτοῦ Ἀποστήσατέ με ἀπὸ τῆς μάχης. ἠσθένησα γὰρ λίαν. καὶ εὐθέως ἀπέστησαν αὐτὸν οἱ παῖδες αὐτοῦ ἀπὸ τῆς παρατάξεως,"}, {"sp": "N", "st": "1 Esd 1:29", "t": "καὶ ἀνέβη ἐπὶ τὸ ἄρμα τὸ δευτέριον αὐτοῦ· καὶ ἀποκατασταθεὶς εἰς Ἰερουσαλὴμ μετήλλαξεν τὸν βίον αὐτοῦ, καὶ ἐτάφη ἐν τῷ πατρικῷ τάφῳ."}, {"sp": "N", "st": "1 Esd 1:30", "t": "καὶ ἐν ὅλῃ τῇ Ἰουδαίᾳ ἐπένθησαν τὸν Ἰωσείαν· καὶ ἐθρήνησεν Ἱερεμίας ὁ προφήτης ὑπέρ Ἰωσείου, καὶ οἱ προκαθήμενοι σὺν γυναιξὶν ἐθρηνοῦσαν αὐτὸν ἕως τῆς ἡμέρας ταύτης· καὶ ἐξεδόθη τοῦτο γενέσθαι αἰεὶ εἰς πᾶν τὸ γένος Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 1:31", "t": "ταῦτα δὲ ἀναγέγραπται ἐν τῇ βύβλῳ τῶν ἱστορουμέναων περὶ τῶν βασιλέων τῆς Ἰουδαίας, καὶ τὸ καθʼ ἔν πραχθέν τῆς πράξεως Ἰωσείου καὶ τῆς δόξης αὐτοῦ καὶ τῆς συνέσεως αὐτοῦ ἐν τῷ νόμῳ Κυρίου· τά τε πραχθέντα ὑπʼ αὐτοῦ καὶ τὰ νῦν ἱστόρηται ἐν τῷ βυβλίῳ τῶν βασιλέων Ἰσραὴλ καὶ Ἰούδα."}, {"sp": "N", "st": "1 Esd 1:32", "t": "Καὶ ἀναλαβόντες οἱ ἐκ τοῦ ἔθνους τὸν Ἰεχονίαν υἱὸν Ἰωσείου ἀνέδειξαν βασιλέα ἀντὶ Ἰωσείου τοῦ πατρὸς αὐτοῦ, ὄντα ἐτῶν εἴκοσι τριῶν."}, {"sp": "N", "st": "1 Esd 1:33", "t": "καὶ ἐβασίλευσεν ἐν Ἰσραὴλ καὶ Ἰερουσαλὴμ μῆνας τρεῖς· καὶ ἀπεκατέστησεν αὐτὸν βασιλεὺς Αἰγύπτου βασιλεύειν ἐν Ἰερουσαλήμ,"}, {"sp": "N", "st": "1 Esd 1:34", "t": "καὶ ἐζημίωσεν τὸ ἔθνος ἀργυρίου ταλάντοις ἑκατὸν καὶ χρυσίου ταλάντῳ ἑνί."}, {"sp": "N", "st": "1 Esd 1:35", "t": "καὶ ἀνέδειξεν ὁ βασιλεὺς Αἰγύππου βασιλέα Ἰωακειμ τὸν ἀδελφὸν αὐτοῦ βασιλέα τῆς Ἰουδαίας καὶ Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 1:36", "t": "καὶ ἔδησεν Ἰωακεὶμ τοὺς μεγιστᾶνας, Ζάριον δὲ τὸν ἀδελφὸν αὐτοῦ συλλαβὼν ἀνήγαγεν ἐξ Αἰγύπτου."}, {"sp": "N", "st": "1 Esd 1:37", "t": "Ἐτῶν δὲ ἦν εἶκοσι πέντε Ἰωακεὶμ ὅτε ἐβασίλευσεν τῆς Ἰουδαίας καὶ Ἰερουσαλήμ, καὶ ἐποίησεν τὸ πονηρὸν ἐνώπιον Κυρίου."}, {"sp": "N", "st": "1 Esd 1:38", "t": "τʼ αὐτὸν δὲ ἀνέβη Ναβουχοδονοσὸρ βασιλεὺς Βαβυλῶνος, καὶ ἔδησεν αὐτὸν ἐν χαλκείῳ δεσμῷ καὶ ἀπήγαγεν εἰς Βαβυλῶνα."}, {"sp": "N", "st": "1 Esd 1:39", "t": "καὶ ἀπὸ τῶν ἱερῶν σκευῶν τοῦ κυρίου λαβὼν Ναβουχοδονοσὸρ καὶ ἀπενέγκας ἀπηρείσατο ἐν τῷ ναῷ αὐτοῦ ἐν Βαβυλῶνι."}, {"sp": "N", "st": "1 Esd 1:40", "t": "τὴ δὲ ἱστορηθέντα περὶ αὐτοῦ καὶ τῆς αὐτοῦ ἀκαθαρσίας καὶ δυσσεβείας ἀναγέγραπται ἐν τῇ βίβλῳ τῶν χρόνων τῶν βασιλέων."}, {"sp": "N", "st": "1 Esd 1:41", "t": "Καὶ ἐβασίλευσεν ἀντʼ αὐτοῦ Ἰωακεὶμ ὁ υἱὸς αὐτοῦ· ὅτε γὰρ ἀνεδείχθη, ἦν ἐτῶν ὀκτώ."}, {"sp": "N", "st": "1 Esd 1:42", "t": "βασιλεύει δὲ μῆνας τρεῖς καὶ ἡμέρας δέκα ἐν Ἰερουσαλήμ, καὶ ἐποίησεν τὸ πονηρὸν ἔναντι Κυρίου."}, {"sp": "N", "st": "1 Esd 1:43", "t": "Καὶ μετʼ ἐνιαυτὸν ἀποστείλας Ναβουχοδονοσὸρ μετήγαγεν αὐτὸν εἰς Βαβυλῶνα ἄμα τοῖς ἱεροῖς σκεύεσιν τοῦ κυρίου,"}, {"sp": "N", "st": "1 Esd 1:44", "t": "καὶ ἀνέδειξε Σεδεκίαν βασιλέα τῆς Ἰουδαίας καὶ Ἰερουσαλήμ. Σεδεκίαν ὄντα ἐτῶν εἶκοσι ἑνός· βασιλεύει δὲ ἔτη ἕνδεκα."}, {"sp": "N", "st": "1 Esd 1:45", "t": "καὶ ἐποίησεν τὸ πονηρὸν ἐνώπιον Κυρίου, καὶ οὐκ ἐνετράπη ἀπὸ τῶν ὸηθέντων λόγων ὑπὸ Ἰερεμίωυ τοῦ προφήτου ἐκ στόματος τοῦ κυρίου."}, {"sp": "N", "st": "1 Esd 1:46", "t": "καὶ ὁρκισθεὶς ἀπὸ τοῦ βασιλέως Ναβουχοδονοσὸρ τῷ ὀνόματι τοῦ κυρίου, ἐφιορκήσας ἀπέστη, καὶ σκληρύνας αὐτοῦ τὸν τράχηλον καὶ τὴν καρδίαν αὐτοῦ παρέβη τὰ νόμιμα Κυρίου θεοῦ Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 1:47", "t": "καὶ οἱ ἡγούμενοι δὲ τοῦ λαοῦ καὶ τῶν ἱερέων πολλὰ ἠσέβησαν καὶ ἠνόμησαν ὑπέρ πάσας τὰς ἀκαθαρσίας πάντων τῶν ἐθνῶν, καὶ ἐμίαναν τὸ ἱερὸν τοῦ κυρίου τὸ ἁγιαζόμενον ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 1:48", "t": "καὶ ἀπέστειλεν ὁ βασιλεὺς τῶν πατέρων αὐτῶν διὰ τοῦ ἀγγέλου αὐτοῦ μετακαλέσαι αὐτούς, καθὸ ἐφείδετο αὐτῶν καὶ τοῦ σκηνώματος αὐτῦ."}, {"sp": "N", "st": "1 Esd 1:49", "t": "αὐτοὶ δὲ ἐμυκτήρισαν ἐν τοῖς ἀγγέλοις αὐτοῦ, καὶ ᾖ ἡμέρᾳ ἐλάλησεν Κύριος, ἦσαν ἐκπαίζοντες τοὺς προφήτας αὐτοῦ· (52)ἕως οὗ θυμῶντα αὐτὸν ἐπὶ τῷ ἔθνει αὐτοῦ διὰ τὰ δυσσεβήματα προστάξαι ἀναβιβάσαι ἐπʼ αὐτοὺς τοὺς βασιλεῖς τῶν Χαλδαίων."}, {"sp": "N", "st": "1 Esd 1:50", "t": "οὗτοι ἀπέκτειναν τοὺς νεανίσκους αὐτῶν ἐν ῥομφαίᾳ περικυκλῶ τοῦ ἁγίου ἱεροῦ, καὶ οὐκ ἐφείσαντο νεανίσκου καὶ παρθένου καὶ πρεσβύτου καὶ νεαντέρου, (54)ἀλλὰ πάοτας παρέδωκασ εἰς τὰς χεῖρας αὐτῶν,"}, {"sp": "N", "st": "1 Esd 1:51", "t": "καὶ πάντα τὰ ἱερὰ σκεύη τοῦ κυρίου, τὰ μεγάλα καὶ τὰ μικρά, καὶ τὰς κιβωτοὺς τοῦ κυρίου καὶ τὰς βασιλικὰς ἀποθήκας ἀναλαβόντες ἀπήνεγκαν εἰς Βαβυλώνα."}, {"sp": "N", "st": "1 Esd 1:52", "t": "καὶ ἐνεπύρισαν τὸν οἶκον τοῦ κυρίου, καὶ ἔλυσαν τὰ τείχη Ἰερουσαλήμ, καὶ τοὺς πύργους αὐτῆς ἐνεπύρισαν ἐν πυρί,"}, {"sp": "N", "st": "1 Esd 1:53", "t": "καὶ συνετέλεσαν πάντα τὰ ἔνδοξα αὐτῆς ἀχρεῶσαι· καὶ τοὺς ἐπιλοίπους ἀπήγαγεν μετὰ όομφαίας εἰς Βαβυλώνα."}, {"sp": "N", "st": "1 Esd 1:54", "t": "καὶ ἦσαν παῖδες αὐτῷ καὶ τοῖς υἱοῖς αὐτοῦ μέχρι οὗ βασιλεῦσαι Ιέρσας, εἰς ἀναπλήρωσιν τοῦ ῥήματος τοῦ κυρίου ἐν στόματι Ἰερεμίου"}, {"sp": "N", "st": "1 Esd 1:55", "t": "Ἕως τοῦ εὐδοκῆσαι τὴν γῆν τὰ σάββατα αὐτῆς, πάντα τὸν χρόνον τῆς ἐρημώσεως αὐτῆς σαββατιεῖ εἰς συνπλήρωσιν ἐτῶν ἑβδομήκοντα."}, {"sp": "N", "st": "1 Esd 2:1", "t": "Κύρου Ιερσῶν ἔτους πρώτου, εἰς συντέλειαν ῥήΒασιλεύοντος ματος Κυρίου ἐν στόματι Ἰερεμίου,"}, {"sp": "N", "st": "1 Esd 2:2", "t": "ἤγειρεν Κύριος τὸ πνεῦμα Κύρου βασιλέως Περσῶν, καὶ ἐκήρυξεν ὅλῃ τῇ βασιλείᾳ αὐτοῦ καὶ ἄμα διὰ γραπτῶν λέγων"}, {"sp": "N", "st": "1 Esd 2:3", "t": "Τάδε λέγει ὁ βασιλεὺς Περσῶν Κῦρος Ἐμὲ ἀνέδειξεν βασιλέα τῆς οἰκουμένης ὁ κύριος τοῦ Ἰσραήλ, Κύριος ὁ ὕψιστος,"}, {"sp": "N", "st": "1 Esd 2:4", "t": "καὶ ἐσήμηνέν μοι οἰκοδομῆσαι αὐτῷ οἶκον ἐν Ἰερουσαλὴμ τῇ ἐν τῇ Ἰουδαίᾳ."}, {"sp": "N", "st": "1 Esd 2:5", "t": "εἴ τίς ἐστιν οὗν ὑμῶν ἐκ τοῦ ἔθνους αὐτοῦ, ἔστω ὁ κύριος αὐτοῦ μετʼ αὐτοῦ, καὶ ἀναβὰς εἰς τὴν Ἰερουσαλὴμ τὴν ἐν τῇ Ἰουδαίᾳ οἰκοδομείτω τὸν οἶκον τοῦ κυρίου τοῦ Ἰσραήλ· οὗτος ὁ κύριος ὁ κατασκηνώας ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 2:6", "t": "ὅσοι οὗν κατὰ τοὺς τόπους οἰκοῦσιν, βοηθείτωσαν αὐτῷ οἱ ἐν τῷ τόπῳ αὐτοῦ ἐν χρυσίῳ καὶ ἐν ἀργυρίῳ (7)καὶ ἐν δόσεσιν, μεθʼ ἵππων καὶ κτηνῶν, σὺν τοῖς ἄλλοις τοῖς κατʼ εὐχὰς προστεθειμένοις εἰς τὸ ἱερὸν τοῦ κυρίου τὸ ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 2:7", "t": "Καὶ καταστήσαντες οἱ ἀρχίφυλοι τῶν πατριῶν τῆς Ἰούδα καὶ Βενιαμεὶν φυλῆς, καὶ οἱ ἱερεῖς καὶ οἱ Λευεῖται, καὶ πάντων ὧν ἤγειρεν Κύριος τὸ πνεῦμα ἀναβῆναι οἰκοδομῆσαι οἶκον τῷ κυρίῳ τὸν ἐν Ἰερουσαλήμ·"}, {"sp": "N", "st": "1 Esd 2:8", "t": "καὶ οἱ περικύκλω αὐτῶν (9)ἐβοήθησαν ἐν πᾶσιν, ἐν ἀργυρίῳ καὶ χρυσίῳ, ἵπποις, κτήνεσιν καὶ εὐχαῖς ὡς πλείσταις πολλῶν ὧν ὁ νοῦς ἠγέρθη."}, {"sp": "N", "st": "1 Esd 2:9", "t": "καὶ ὁ βασιλεὺς Κῦρος ἐξήνεγκεν τὰ ἅγια σκεύη τοῦ κυρίου, ἃ μετήγαγεν Ναβουχοδονοσὸρ ἐξ Ἰερουσαλὴμ καὶ ἀπηρείσατο αὐτὰ ἐν τῷ εἰδωλίῳ αὐτοῦ."}, {"sp": "N", "st": "1 Esd 2:10", "t": "ἐξενέγκας δὲ αὐτὰ Κῦρος ὁ βασιλεὺς Περσῶν παρέδωκεν αὐτὰ Μιθριδάτῃ τῷ ἑαυτοῦ γαζοφύλακι·"}, {"sp": "N", "st": "1 Esd 2:11", "t": "διὰ δὲ τούτου παρεδόθησαν Σαναμασσάρῳ προστάτῃ τῆς Ἰουδαίας."}, {"sp": "N", "st": "1 Esd 2:12", "t": "ὁ δὲ τούτων ἀριθμὸς ἦν, σπονδεῖα χρυσᾶ χίλια, σπονδεῖα ἀργυρᾶ χίλια, θυίσκαι ἀργυραῖ εἴκοσι ἐννέα, φιάλαι χρυσαῖ τριάκοντα, ἀργυραῖ βυ΄ δέκα, καὶ ἄλλα σκεύη χίλια."}, {"sp": "N", "st": "1 Esd 2:13", "t": "τὰ δὲ πάντα σκεύη ἐκομίσθη, χρυσᾶ καὶ ἀργυρᾶ, πεντακισχίλια τετρακόσια ἑξήκοντα ἐννέα·"}, {"sp": "N", "st": "1 Esd 2:14", "t": "ἀνηνέχθη δὲ ὑπὸ Σαμανασσάρου ἅμα τοῖς ἐκ τῆς αἰχμαλωσίας ἐκ Βαβυλῶνος εἰς Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 2:15", "t": "Ἐν δὲ τοῖς ἐπὶ Ἀρταξέρξου τοῦ Περσῶν βασιλέως χρόνοις κατέγραψεν αὐτῶν κατὰ τῶν κατοικούντων ἐν τῇ Ἰουδαίᾳ καὶ Ἰερουσαλὴμ Βήλεμος καὶ Μιθραδάτης καὶ Ταβέλλιος καὶ Ῥάθυμος καὶ Βεέλτεθμος καὶ Σαμέλλιος ὁ γραμματεὺς καὶ οἱ λοιποὶ οἱ τούτοις συντασσόμενοι, οἰκοῦντες δὲ ἐν Σαμαρείᾳ καὶ τοῖς ἄλλοις τόποις, τὴν ὑπογεγραμμένην ἐπιστολήν"}, {"sp": "N", "st": "1 Esd 2:16", "t": "Βασιλεῖ Ἀρταξέρξῃ (17)κυρίῳ οἱ παῖδές σου Ῥάθυμος ὁ τὰ προσπίπτοντα καὶ Σαμέλλιος ὁ γραμματεὺς καὶ οἱ ἐπίλοιποι τῆς βουλῆς αὐτῶν καὶ οἱ ἐν κοίλῃ Συρίᾳ καὶ Φοινίκῃ."}, {"sp": "N", "st": "1 Esd 2:17", "t": "καὶ νῦν γνωστὸν ἔστω τῷ κυρίῳ βασιλεῖ ὅτι Ἰουδαῖοι ἀναβάντες παρʼ ὑμῶν πρὸς ἡμᾶς, ἐλθόντες εἰς Ἰερουσαλήμ, τὴν πόλιν τὴν ἀποστάτιν καὶ πονηρὰν οἰκοῦσιν, τάς τε ἀγορὰς αὐτῆς καὶ τὰ τείχη θεραπεύουσιν καὶ ναὸν ὑποβάλλονται."}, {"sp": "N", "st": "1 Esd 2:18", "t": "ἐὰν οὖν ἡ πόλις αὕτη οἰκοδομηθῇ καὶ τὰ τείχη συντελεσθῇ, φορολογίαν οὐ μὴ ὑπομείνωσιν δοῦναι, ἀλλὰ καὶ βασιλεῦσιν ἀντιστήσονται· (20)καὶ ἐπεὶ ἐνεργεῖται τὰ κατὰ τὸν ναόν, καλῶς ἔχειν ὑπολαμβάνομεν μὴ ὑπεριδεῖν τὸ τοιοῦτο (21)ἀλλὰ προσφωνῆσαι τῷ κυρίῳ βασιλεῖ ὅπως, ἂν φαίνηταί σοι, ἐπισκεφθῇ ἐν τοῖς ἀπὸ τῶν πατέρων σου βιβλίοις."}, {"sp": "N", "st": "1 Esd 2:19", "t": "καὶ εὑρήσεις ἐν τοῖς ὑπομνηματισμοῖς τὰ γεγραμμένα περὶ τούτων, καὶ γνώσῃ ὅτι ἡ πόλις ἦν ἐκείνη ἀποστάτις καὶ βασιλεῖς καὶ πόλεις ἐνοχλοῦσα, (²³)καὶ οἱ Ἰουδαῖοι ἀποστάται καὶ πολιορκίας συνεσταμένοι ἐν αὐτῇ ἔτι ἐξ αἰῶνος, δι᾿ ἣν αἰτίαν ἡ πόλις αὕτη ἠρημώθη."}, {"sp": "N", "st": "1 Esd 2:20", "t": "νῦν οὖν ὑποδεικνύομέν σοι, κύριε βασιλεῦ, ὅτι ἐὰν ἡ πόλις αὕτη οἰκοδομηθῇ καὶ τὰ ταύτης τείχη ἀνασταθῇ, ἔξοδός σοι οὐκέτι ἔσται εἰς κοί λην Συρίαν καὶ Φοινίκην."}, {"sp": "N", "st": "1 Esd 2:21", "t": "τότε ἀντέγραψεν ὁ βασιλεὺς Ῥαθύμῳ τῷ γράφοντι τὰ προσπίπτοντα καὶ Βεελτέθμῳ καὶ Σαμελλίῳ γραμματεῖ καὶ τοῖς λοιποῖς τοῖς συντασσομένοις καὶ οἰκοῦσιν ἐν Σαμαρείᾳ καὶ Συρίᾳ καὶ Φοινίκῃ τὰ ὑπογεγραμμένα"}, {"sp": "N", "st": "1 Esd 2:22", "t": "Ἀνέγνων τὴν ἐπιστολὴν ἣν πεπόμφατε πρὸς μέ. ἐπέταξα οὖν ἐπισκέψασθαι· καὶ εὑρέθη ὅτι ἐστὶν ἡ πόλις ἐκείνη ἐξ αἰῶνος βασιλεῦσιν ἀντιπαρατάσσουσα,"}, {"sp": "N", "st": "1 Esd 2:23", "t": "καὶ οἱ ἄνθρωποι ἀποστάσεις καὶ πολέμους ἐν αὐτῇ συντελοῦντες, καὶ βασιλεῖς ἰσχυροὶ καὶ σκληροὶ ἦσαν ἐν Ἰερουσαλὴμ κυριεύοντες καὶ φορολογοῦντες κοίλην Συρίαν καὶ Φοινίκην."}, {"sp": "N", "st": "1 Esd 2:24", "t": "νῦν οὖν ἐπέταξα ἀποκωλῦσαι τοὺς ἀνθρώπους ἐκείνους τοῦ οἰκοδομῆσαι τὴν πόλιν, καὶ προνοηθῆναι ὅπως μηθὲν παρὰ ταῦτα γένηται (29)καὶ μὴ προβῇ ἐπὶ πλεῖον τὰ τῆς κακίας εἰς τὸ βασιλεῖς ἐνοχλῆσαι."}, {"sp": "N", "st": "1 Esd 2:25", "t": "τότε ἀναγνωσθέντων τῶν παρὰ τοῦ βασιλέως Ἀρταξέρξου γραφέντων ὁ Ῥάθυμος καὶ Σαμέλλιος ὁ γραμματεὺς καὶ οἱ τούτοις συντασσόμενοι, ἀναζεύξαντες κατὰ σπουδὴν εἰς Ἰερουσαλὴμ μεθʼ ἵππου καὶ ὄχλου παρατάξεως, (³¹)ἤρξαντο κωλύειν τοὺς οἰκοδομοῦντας· καὶ ἤργει ἡ οἰκοδομὴ τοῦ ἱεροῦ τοῦ ἐν Ἰερουσαλὴμ μέχρι τοῦ δευτέρου ἔτους τῆς βασιλείας Δαρείου τοῦ Περσῶν βασιλέως."}, {"sp": "N", "st": "1 Esd 3:1", "t": "Καὶ βασιλεὺς Δαρεῖος ἐποίησεν δοχὴν μεγάλην πᾶσιν τοῖς ὑπʼ αὐτόν, καὶ πᾶσιν τοῖς οἰκογενέσιν αὐτοῦ, καὶ πᾶσιν τοῖς μεγιστᾶσιν τῆς Μηδείας καὶ τῆς Περσίδος,"}, {"sp": "N", "st": "1 Esd 3:2", "t": "καὶ πᾶσιν τοῖς σατράπαις καὶ στρατηγοῖς καὶ τοπάρχαις τοῖς ὑπʼ αὐτὸν ἀπὸ τῆς Ἰνδικῆς μέχρι Αἰθιοπίας ἐν ταῖς ἑκατὸν εἴκοσι ἑπτὰ σατραπείαις."}, {"sp": "N", "st": "1 Esd 3:3", "t": "καὶ ἐφάγοσαν καὶ ἐπίοσαν, καὶ ἐμπλησθέντες ἀνέλυσαν· ὁ δὲ Δαρεῖος ὁ βασιλεὺς ἀνέλυσεν εἰς τὸν κοιτῶνα καὶ ἐκοιμήθη, καὶ ἔξυπνος ἐγένετο."}, {"sp": "N", "st": "1 Esd 3:4", "t": "τότε οἱ τρεῖς νεανίσκοι οἱ σωματοφύλακες, οἱ φυλάσσοντες τὸ σῶμα τοῦ βασιλέως, εἶπαν ἕτερος πρὸς τὸν ἕτερον"}, {"sp": "N", "st": "1 Esd 3:5", "t": "Εἴπωμεν ἕκαστος ἡμῶν ἕνα λόγον ὃς ὑπερισχύσει· καὶ οὗ ἂν φανῇ τὸ ῥῆμα αὐτοῦ σοφώτερον τοῦ ἑτέ. ρου, δώσει αὐτῷ Δαρεῖος ὁ βασιλεὺς δωρεὰς μεγάλας καὶ ἐπινίκια μεγάλα,"}, {"sp": "N", "st": "1 Esd 3:6", "t": "καὶ πορφύραν περιβαλέσθαι καὶ ἐν χρυσώμασιν πίνειν καὶ ἐπὶ χρυσῷ καθεύδειν καὶ ἅρμα χρυσοχάλινον καὶ κίδαριν βυσσίνην καὶ μανιάκην περὶ τὸν τράχηλον,"}, {"sp": "N", "st": "1 Esd 3:7", "t": "καὶ δεύτερος καθιεῖται Δαρείου διὰ τὴν σοφίαν αὐτοῦ, καὶ συγγενὴς Δαρείου κληθήσεται."}, {"sp": "N", "st": "1 Esd 3:8", "t": "καὶ τότε γράψαντες ἕκαστος τὸν ἑαυτοῦ λόγον ἐσφραγίσαντο καὶ ἔθηκαν ὑπὸ τὸ προσκεφάλαιον Δαρείου τοῦ βασιλέως, (9)καὶ εἶπαν"}, {"sp": "N", "st": "1 Esd 3:9", "t": "Ὅταν ἐγερθῇ ὁ βασιλεύς, δώσουσιν αὐτῷ τὸ γράμμα· καὶ ὃν ἂν κρίνῃ ὁ βασιλεὺς καὶ οἱ τρεῖς μεγιστᾶνες τῆς Περσίδος ὅτι οὗ ὁ λόγος αὐτοῦ σοφώτερος, αὐτῷ δοθήσεται τὸ νῖκος, καθὼς γέγραπται."}, {"sp": "N", "st": "1 Esd 3:10", "t": "ὁ εἷς ἔγραψεν Ὑπερισχύει ὁ οἶνος."}, {"sp": "N", "st": "1 Esd 3:11", "t": "ὁ ἕτερος ἔγραψεν Ὑπερισχύει ὁ βασιλεύς."}, {"sp": "N", "st": "1 Esd 3:12", "t": "ὁ τρίτος ἔγραψεν Ὑπερισχύουσιν αἱ γυναῖκες, ὑπὲρ δὲ πάντα νικᾷ ἡ ἀλήθεια."}, {"sp": "N", "st": "1 Esd 3:13", "t": "καὶ ὅτε ἐξηγέρθη ὁ βασιλεύς, λαβόντες τὸ γράμμα ἔδωκαν αὐτῷ, καὶ ἀνέγνω."}, {"sp": "N", "st": "1 Esd 3:14", "t": "καὶ ἐξαποστείλας ἐκάλεσεν πάντας τοὺς μεγιστᾶνας τῆς Περσίδος καὶ τῆς Μηδείας καὶ σατράπας καὶ στρατηγοὺς καὶ τοπάρχας καὶ ὑπάτους, (¹⁵)καὶ ἐκάθισεν ἐν τῷ χρηματιστηρίῳ, καὶ ἀνεγνώσθη τὸ γράμμα ἐνώπιον αὐτῶν."}, {"sp": "N", "st": "1 Esd 3:15", "t": "καὶ εἶπεν Καλέσατε τοὺς νεανίσκους, καὶ αὐτοὶ δηλώσουσιν τοὺς λόγους αὐτῶν· καὶ ἐκλήθησαν, καὶ εἰσήλθοσαν."}, {"sp": "N", "st": "1 Esd 3:16", "t": "καὶ εἶπαν αὐτοῖς Ἀπαγγείλατε ἡμῖν περὶ τῶν γεγραμμένων. Καὶ ἤρξατο ὁ πρῶτος ὁ εἴπας περὶ τῆς ἰσχύος τοῦ οἴνου. (18)καὶ ἔφη οὕτως"}, {"sp": "N", "st": "1 Esd 3:17", "t": "Ἄνδρες, ῶς ὑπερισχύει ὁ οἶνος. πάντας τοὺς ἀνθρώπους τοὺς πιόντας αὐτὸν πλανᾷ τὴν διάνοιαν,"}, {"sp": "N", "st": "1 Esd 3:18", "t": "τοῦ τε βασιλέως καὶ τοῦ ὀρφανοῦ ποιεῖ τὴν διάνοιαν μίαν, τὴν τε τοῦ οἰκέτου καὶ τὴν τοῦ ἐλευθέρου, τὴν τε τοῦ πένητος καὶ τὴν τοῦ πλουσίου·"}, {"sp": "N", "st": "1 Esd 3:19", "t": "καὶ πᾶσαν διάνοιαν μεταστρέφει εἰς εὐωχίαν καὶ εὐφροσύνην, καὶ οὐ μέμνηται πᾶσαν λύπην καὶ πᾶν ὀφείλημα·"}, {"sp": "N", "st": "1 Esd 3:20", "t": "καὶ πάσας καρδίας ποιεῖ πλουσίας, καὶ οὐ μέμνηται βασιλέα οὐδὲ σατράπην· καὶ πάντα διὰ ταλάντων ποιεῖ λαλεῖν,"}, {"sp": "N", "st": "1 Esd 3:21", "t": "καὶ οὐ μέμνηται ὅταν πίνωσιν φιλιάζειν φίλοις καὶ ἀδελφοῖς, καὶ μετʼ οὐ πολὺ σ πῶνται μαχαιρας·"}, {"sp": "N", "st": "1 Esd 3:22", "t": "καὶ ὅταν ἀπὸ τοῦ οἴνου ἐγερθῶσιν, οὐ μέμνηται ἃ ἔπραξαν."}, {"sp": "N", "st": "1 Esd 3:23", "t": "ὦ ἄνδρες. οὐχ ὑπερισχύει ὁ οἶνος ὅτι οὕτως ἀναγκάζει ποιεῖν; καὶ ἐσίγησεν οὕταως εἴπας."}, {"sp": "N", "st": "1 Esd 4:1", "t": "Καὶ ἤρξατο ὁ δεύτερος λαλεῖν ὁ εἴπας περὶ τῆς ἰσχύος τοῦ βασιλέως"}, {"sp": "N", "st": "1 Esd 4:2", "t": "Ὦ ἄνδρες, οὐχ ὑπερι σχύουσιν οἱ ἄνθραωποι, τὴν γῆν καὶ τὴν θάλασσαν κατακρατοῦντες καὶ πάντα τὰ ἐν αὐτοῖς;"}, {"sp": "N", "st": "1 Esd 4:3", "t": "ὁ δὲ βασιλεὺς ὑπερισχύει καὶ κυριεύει αὐτῶν καὶ δεσπόζει αὐτῶν, καὶ πᾶν ὃ ἐὰν εἴπῃ αὐτοῖς ἐνακούουσιν."}, {"sp": "N", "st": "1 Esd 4:4", "t": "ἐὰν εἴπῃ αὐτοῖς ποιῆσαι πόλεμον ἕτερος πρὸς τὸν ἕτερον, ποιοῦσιν· ἐὰν δὲ ἐξαποστείλῃ αὐτοὺς πρὸς τοὺς πολεμίους, βαδίζουσιν καὶ κατεργάζονται τὰ ὄρη καὶ τὰ τείχη καὶ τοὺς πύργους."}, {"sp": "N", "st": "1 Esd 4:5", "t": "φονεύουσιν καὶ φονεύονται, καὶ τὸν λόγον τοῦ βασιλέως οὐ παραβαίνουσιν· ἐὰν δὲ νικήσωσιν, τῷ βασιλεῖ κομίζουσιν πάντα, καὶ ἐὰν προνομεύσαωσιν καὶ τὰ ἄλλα πάντα."}, {"sp": "N", "st": "1 Esd 4:6", "t": "καὶ ὅσοι οὐ στρατεύονται οὐδὲ πολεμοῦσιν ἀλλὰ γεωργοῦσιν τὴν γῆν, πάλιν ὅταν σπείρωσι, θερίσαντες ἀναφέρουσιν τῷ βασιλεῖ· καὶ ἕτερος τὸν ἕτερον ἀναγκάζοντες ἀναφέρουσι τοὺς φόρους τῷ βασιλεῖ."}, {"sp": "N", "st": "1 Esd 4:7", "t": "καὶ αὐτὸς εἰ μόνος ἐστίν, ἐὰν εἴπῃ ἀποκτεῖναι, ἀποκτέννουσιν· εἶπεν ἀφεῖναι, ἀφίουσιν·"}, {"sp": "N", "st": "1 Esd 4:8", "t": "εἶπε πατάξαι, τύπτουσιν· εἶπεν ἐρημῶσαι, ἐρημοῦσιν· εἶπεν οἰκοδομῆσαι, οἰκοδομοῦσιν·"}, {"sp": "N", "st": "1 Esd 4:9", "t": "εἶπεν ἐκκόψαι, ἐκκόπτουσιν· εἶπεν φυτεῦσαι, φυτεύουσιν·"}, {"sp": "N", "st": "1 Esd 4:10", "t": "καὶ πᾶς ὁ λαὸς αὐτοῦ καὶ αἱ δυνάμεις αὐτοῦ ἐνακούουσιν. πρὸς δὲ τούτοις αὐτὸς ἀνάκειται, ἐσθίει καὶ πίνει καὶ καθεύδει."}, {"sp": "N", "st": "1 Esd 4:11", "t": "αὐτοὶ δὲ τηροῦσιν κύκλῳ περὶ αὐτόν, καὶ οὐ δύνανται ἕκαστος ἀπελθεῖν καὶ ποιεῖν τὰ ἔργα αὐτοῦ, οὐδὲ παρακούουσιν αὐτοῦ."}, {"sp": "N", "st": "1 Esd 4:12", "t": "ὦ ἄνδρες, πῶς οὐχ ὑπερισχύει ὁ βασιλεὺς ὅτι οὕτως ἐπακουστός ἐστιν; καὶ ἐσίγησεν."}, {"sp": "N", "st": "1 Esd 4:13", "t": "Ὁ δὲ τρίτος ὁ εἴπας περὶ τῶν γυναικῶν καὶ τῆς ἀληθείας, οὗτός ἐστιν Ζοροβαβέλ, ἤρξατο λαλεῖν"}, {"sp": "N", "st": "1 Esd 4:14", "t": "Ἄνδρες, οὐ μέγας ὁ βασιλεύς, καὶ πολλοὶ οἱ ἄνθρωποι, καὶ ὁ οἶνος ἰσχύεις τίς οὖν ὁ δεσπόζων αὐτῶν, ἢ τίς ὁ κυριεύων; (¹⁵)οὐχ αἱ γυναῖκες;"}, {"sp": "N", "st": "1 Esd 4:15", "t": "αἱ γυναῖκες ἐγέννησαν τὸν βασιλέα καὶ πάντα τὸν λαὸν ὃς κυριεύει τῆς θαλάσσης καὶ τῆς γῆς·"}, {"sp": "N", "st": "1 Esd 4:16", "t": "καὶ ἐξ αὐτῶν ἐγένοντο, καὶ αὗται ἐξέθρεψαν αὐτοὺς τοὺς φυτεύσαντας τοὺς ἀμπελῶνας ἐξ ὦν ὁ οἶνος γίνεται,"}, {"sp": "N", "st": "1 Esd 4:17", "t": "καὶ αὗται ποιοῦσιν τὰς στολὰς τῶν ἀνθρώπων, καὶ αὗται ποιοῦσιν δόξαν τοῖς ἀνθρώποις, καὶ οὐ δύνανται οἱ ἄνθρωποι εἶναι χωρὶς τῶν γυναικῶν."}, {"sp": "N", "st": "1 Esd 4:18", "t": "ἐὰν δὲ συναγάγωσιν χρυσίον καὶ ἀργύριον καὶ πᾶν πρᾶγμα ὡραῖον, καὶ ἴδωσιν γυναῖκα μίαν καλὴν τῷ εἴδει καὶ τῷ κάλλει, ¹⁹καὶ ταῦτα πάντα ἀφέντες εἰς αὐτὴν κέχηναν, καὶ χάσκοντες τὸ στόμα θεωροῦσιν αὐτήν, καὶ πάντες αὐτὴν αἱρετίζουσιν μᾶλλον ἢ τὸ χρυσίον καὶ τὸ ἀργύριον καὶ πᾶν πρᾶγμα ὡραῖον."}, {"sp": "N", "st": "1 Esd 4:20", "t": "ἄνθρωπος τὸν ἑαυτοῦ πατέρα ἐνκαταλείπει ὃς ἐξέθρεψεν αὐτὸν καὶ τὴν ἰδίαν χώραν, καὶ πρὸς τὴν ἰδίαν γυναῖκα κολλᾶται,"}, {"sp": "N", "st": "1 Esd 4:21", "t": "καὶ μετὰ τῆς γυναικὸς ἀφίησι τὴν ψυχήν, καὶ οὔτε τὸν πατέρα μέμνηται οὔτε τὴν μητέρα οὔτε τὴν χώραν."}, {"sp": "N", "st": "1 Esd 4:22", "t": "καὶ ἐντεῦθεν δεῖ ὑμᾶς γνῶναι ὅτι αἱ γυναῖκες κυριεύουσιν ὑμῶν· οὐχὶ πονεῖτε καὶ μοχθεῖτε, καὶ πάντα ταῖς γυναιξὶν δίδοτε καὶ φέρετε;"}, {"sp": "N", "st": "1 Esd 4:23", "t": "καὶ λαμβάνει ἄνθρωπος τὴν ῥομφαίαν αὐτοῦ καὶ ἐκπορεύεται ἐξοδεύειν καὶ λῃστεύειν καὶ κλέπτειν, καὶ εἰς τὴν θάλασσαν πλεῖν καὶ ποταμούς,"}, {"sp": "N", "st": "1 Esd 4:24", "t": "καὶ τὸν λέοντα θεωρεῖ, καὶ ἐν σκότει βαδίζει· καὶ ὅταν κλέψῃ καὶ ἁρπάσῃ καὶ λωποδυτήσῃ, τῇ ἐρωμένῃ ἀποφέρει."}, {"sp": "N", "st": "1 Esd 4:25", "t": "καὶ πλεῖον ἀγαπᾷ ἄνθρωπος τὴν ἰδίαν γυναῖκα μᾶλλον ἢ τὸν πατέρα καὶ τὴν μητέρα."}, {"sp": "N", "st": "1 Esd 4:26", "t": "καὶ πολλοὶ ἀπενοήθησαν ταῖς ἰδίαις διανοίαις διὰ τὰς γυναῖκας, καὶ δοῦλοι ἐγένοντο δι᾿ αὐτάς·"}, {"sp": "N", "st": "1 Esd 4:27", "t": "καὶ πολλοὶ ἀπώλοντο καὶ ἐσφάλησαν καὶ ἡμάρτοσαν διὰ τὰς γυναῖκας."}, {"sp": "N", "st": "1 Esd 4:28", "t": "καὶ νῦν οὐ πιστεύετέ μοι; οὐχὶ μέγας ὁ βασιλεὺς τῇ ἐξουσίᾳ αὐτοῦ; οὐχὶ πᾶσαι αἱ χῶραι εὐλαβοῦνται ἅψασθαι αὐτοῦ;"}, {"sp": "N", "st": "1 Esd 4:29", "t": "ἐθεώρουν αὐτὸν καὶ Ἀπάμην τὴν θυγατέρα Βαρτάκου τοῦ θαυμαστοῦ τὴν παλλακὴν τοῦ βασιλέως καθημένην ἐν δεξιᾷ τοῦ βασιλέως,"}, {"sp": "N", "st": "1 Esd 4:30", "t": "καὶ ἀφαιροῦσαν τὸ διάδημα ἀπὸ τῆς κεφαλῆς τοῦ βασιλέως καὶ ἐπιτιθοῦσαν αὑτῇ· καὶ ἐράπιζεν τὸν βασιλέα τῇ ἀριστερᾷ."}, {"sp": "N", "st": "1 Esd 4:31", "t": "καὶ πρὸς τούτοις ὁ βασιλεὺς χάσκων τὸ στόμα ἐθεώρει αὐτήν· καὶ ἐὰν γελάσῃ αὐτῷ, γελᾷ· ἐὰν δὲ πικρανθῇ ἐπʼ αὐτόν, κολακεύει αὐτὴν ὅπως διαλλαγῇ αὐτῷ."}, {"sp": "N", "st": "1 Esd 4:32", "t": "ὦ ἄνδρες, πῶς οὐκ ἰσχυραὶ αἱ γυναῖκες ὅτι οὕτως πράσσουσιν;"}, {"sp": "N", "st": "1 Esd 4:33", "t": "καὶ τότε ὁ βασιλεὺς καὶ οἱ μεγιστᾶνες ἔβλεπον εἷς τὸν ἕτερον. καὶ ἤρξατο λαλεῖν περὶ τῆς ἀληθείας"}, {"sp": "N", "st": "1 Esd 4:34", "t": "Ἄνδρες. οὐκ ἰσχυραὶ αἱ γυναῖκες; μεγάλη ἡ γῆ, καὶ ὑψηλὸς ὁ οὐρανός, καὶ ταχὺς τῷ δρόμῳ ὁ ἥλιος, ὅτι στρέφεται ἐν τῷ κύκλῳ τοῦ οὐρανοῦ καὶ πάλιν ἀποτρέχει εἰς τὸν ἑαυτοῦ τόπον ἐν μιᾷ ἡμέρᾳ."}, {"sp": "N", "st": "1 Esd 4:35", "t": "οὐχὶ μέγας ὃς ταῦτα ποιεῖ; καὶ ἡ ἀλήθεια μεγάλη καὶ ἰσχυροτέρα παρὰ πάντα."}, {"sp": "N", "st": "1 Esd 4:36", "t": "πᾶσα ἡ γῆ τὴν ἀλήθειαν καλεῖ, καὶ ὁ οὐρανὸς αὐτὴν εὐλογεῖ, καὶ πάντα τὰ ἔργα σείεται καὶ τρέμει, καὶ οὐκ ἔστιν μετʼ αὐτοῦ ἄδικον οὐθέν."}, {"sp": "N", "st": "1 Esd 4:37", "t": "ἄδικος ὁ οἶνος, ἄδικος ὁ βασιλεύς, ἄδικοι αἱ γυναῖκες, ἄδικοι πάντες οἱ υἱοὶ τῶν ἀνθρώπων καὶ ἄδικα πάντα τὰ ἔργα αὐτῶν, πάντα τὰ τοιαῦτα· καὶ οὐκ ἔστιν ἐν αὐτοῖς ἀλήθεια, καὶ ἐν τῇ ἀδικίᾳ αὐτῶν ἀπολοῦνται."}, {"sp": "N", "st": "1 Esd 4:38", "t": "καὶ ἡ ἀλήθεια μένει καὶ ἰσχύει εἰς τὸν αἰῶνα, καὶ ζῇ καὶ κρατεῖ εἰς τὸν αἰῶνα τοῦ αἰῶνος."}, {"sp": "N", "st": "1 Esd 4:39", "t": "καἰ οὐκ ἔστιν παρʼ αὐτὴν λαμβάνειν πρόσωπα οὐδὲ διάφορα, ἀλλὰ τὰ δίκαια ποιεῖ ἀπὸ πάντων τῶν ἀδίκων καὶ πονηρῶν· καὶ πάντες εὐδοκοῦσι τοῖς ἔργοις αὐτῆς,"}, {"sp": "N", "st": "1 Esd 4:40", "t": "καὶ οὐκ ἔστιν ἐν τῇ κρίσει αὐτῆς οὐθὲν ἄδικον. καὶ αὕτη ἡ ἰσχὺς καὶ τὸ βασίλειον καὶ ἡ ἐξουσία καὶ ἡ μεγαλειότης τῶν πάντων αἰώνων· εὐλογητὸς ὁ θεὸς τῆς ἀληθείας."}, {"sp": "N", "st": "1 Esd 4:41", "t": "καὶ ἐσιώπησεν τοῦ λαλεῖν· καὶ πᾶς ὁ λαὸς τότε ἐφώνησεν καὶ τότε εἶπον Μεγάλη ἡ ἀλήθεια καὶ ὑπερισχύει."}, {"sp": "N", "st": "1 Esd 4:42", "t": "Τότε ὁ βασιλεὺς εἶπεν αὐτῷ Αἴτησαι ὃ θέλεις πλείω τῶν γεγραμμένων, καὶ δώσομέν σοι, ὃν τρόπον εὑρέθης σοφώτερος· καὶ ἐχόμενός μου καθήσῃ, καὶ συγγενής μου κληθήσῃ."}, {"sp": "N", "st": "1 Esd 4:43", "t": "τότε εἶπεν τῷ βασιλεῖ Μνήσθητι τὴν εὐχὴν ἣν ηὔξω οἰκοδομῆσαι τὴν Ἰερουσαλὴμ ἐν τῇ ἡμέρᾳ ᾗ τὸ βασίλειόν σου παρέλαβες,"}, {"sp": "N", "st": "1 Esd 4:44", "t": "καὶ πάντα τὰ σκεύη τὰ λημφθέντα ἐξ Ἰερουσαλὴμ καὶ ἐκπέμψαι ἃ ἐχώρισεν Κῦρος, ὅτε ηὔξατο ἐκκόψαι Βαβυλῶνα, καὶ ηὔξατο ἐξαποστεῖλαι ἐκεῖ"}, {"sp": "N", "st": "1 Esd 4:45", "t": "καὶ σὺ εὔξω οἰκοδομῆσαι τὸν ναὸν ὃν ἐνεπύρισαν οἱ Ἰουδαῖοι, ὅτε ἐρημώθη ἡ Ἰουδαία ὑπὸ τῶν Χαλδαίων."}, {"sp": "N", "st": "1 Esd 4:46", "t": "καὶνῦν τοῦτό ἐστιν ὅσα ἀξιῶ, κύριε βασιλεῦ, καὶ ὁ αἰτοῦμαί σε, καὶ αὕτη ἐστὶν ἡ μεγαλωσύνη ἡ παρὰ σοῦ· δέομαι οὖν ἵνα ποιήσῃς τὴν εὐχὴν ἣν ηὔξω τῷ βασιλεῖ τοῦ οὐρανοῦ ποιῆσαι ἐκ στόματός σου."}, {"sp": "N", "st": "1 Esd 4:47", "t": "Τότε ἀναστὰς Δαρεῖος ὁ βασιλεὺς κατεφίλησεν αὐτόν, καὶ ἔγραψεν αὐτῷ τὰς ἐπιστολὰς πρὸς πάντας οἰκονόμους καὶ τοπάρχας καὶ στρατηγοὺς καὶ σατράπας, ἵνα προπέμψωσιν αὐτὸν καὶ τοὺς μετʼ αὐτοῦ πάντας ἀναβαίνοντας οἰκοδομῆσαι τὴν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 4:48", "t": "καὶ πᾶσι τοῖς τοπάρχαις ἐν κοίλῃ Συρίᾳ καὶ Φοινίκῃ καὶ τοῖς ἐν τῷ Λβάνῳ καὶ ἔγραψεν ἐπιστολάς, μεταφέρειν ξύλα κέδρινα ἀπὸ τοῦ Λιβάνου εἰς Ἰερουσαλήμ, καὶ ὅπως οἰκοδομήσωσιν μετʼ αὐτοῦ τὴν πόλιν."}, {"sp": "N", "st": "1 Esd 4:49", "t": "καὶ ἔγραψεν πᾶσι τοῖς Ἰουδαίοις τοῖς ἀναβαίνουσιν ἀπὸ τῆς βασιλείας εἰς τὴν Ἰουδαίαν ὑπέρ τῆς ἐλευθερίας, πάντα δυνατὸν καὶ σατράπην καὶ τοπάρχην καὶ οἰκονόμον μὴ ἐπελεύσεσθαι ἐπὶ τὰς θύρας αὐτῶν,"}, {"sp": "N", "st": "1 Esd 4:50", "t": "καὶ πᾶσαν τὴν χώραν ἣν κρατήσουσιν ἀφορολόγητον αὐτοῖς ὑπάρχειν· καὶ ἵνα οἱ Χαλδαῖοι ἀφίουσι τὰς κώμας ἃς διακρατοῦσιν τῶν Ἰουδαίων·"}, {"sp": "N", "st": "1 Esd 4:51", "t": "καὶ εἰς τὴν οἰκοδομὴν τοῦ ἱεροῦ δοθῆναι κατʼ ἐνιαυτὸν τάλαντα εἴκοσι μέχρι τοῦ οἰκοδομηθῆναι."}, {"sp": "N", "st": "1 Esd 4:52", "t": "καὶ ἐπὶ τὸ θυσιαστήριον ὁλοκαυτώματα καρποῦσθαι καθʼ ἡμέραν, καθὰ ἔχουσιν ἐντολὴν ἑπτὰ καὶ δέκα προσφέρειν, ἄλλα τάλαντα, δέκα κατʼ ἐνιαυτόν·"}, {"sp": "N", "st": "1 Esd 4:53", "t": "καὶ πᾶσιν τοῖς προσβαίνουσιν ἀπὸ τῆς Βαβυλωνίας κτίσαι τὴν πόλιν, ὑπάρχειν τὴν ἐλευθερίαν αὐτοῖς τε καὶ τοῖς τέκνοις αὐτῶν, καὶ πᾶσι τοῖς ἱερεῦσι τοῖς προσβαίνουσιν."}, {"sp": "N", "st": "1 Esd 4:54", "t": "ἔγραψεν δὲ καὶ τὴν χορηγίαν καὶ τὴν ἱερατικὴν στολὴν ἐν τίνι λατρεύουσιν ἐν αὐτῇ."}, {"sp": "N", "st": "1 Esd 4:55", "t": "καὶ τοῖς Λευείταις ἔγραψεν δοῦναι τὴν χορηγίαν ἕως τῆς ἡμέρας ᾖ ἐπιτελεσθῇ ὁ οἶκος καὶ Ἰερουσαλὴμ οἰκοδομηθῆναι."}, {"sp": "N", "st": "1 Esd 4:56", "t": "καὶ πᾶσι τοῖς φρουροῦσι τὴν πόλιν, ἔγραψε δοῦναι αὐτοῖς κλήρους καὶ ὀψώνια."}, {"sp": "N", "st": "1 Esd 4:57", "t": "καὶ ἐξαπέστειλεν πάντα τὰ σκεύη ἃ ἐχώρισεν Κῦρος ἀπὸ Βαβυλῶνος· καὶ πάντα ὅσα εἶπεν Κῦρος ποιῆσαι, καὶ αὐτὸς ἐπέταξεν ποιῆσαι καὶ ἐξαποστεῖλαι εἰς Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 4:58", "t": "Καὶ ὅτε ἐξῆλθεν ὁ νεανίσκος, ἄρας τὸ πρόσωπον εἰς τὸν οὐρανὸν ἐναντίον Ἰερουσαλὴμ εὐλόγησεν τῷ βασιλεῖ τοῦ οὐρανοῦ (59)λέγων"}, {"sp": "N", "st": "1 Esd 4:59", "t": "Παρὰ σοῦ νίκη, καὶ παρὰ σοῦ ἡ σοφία, καὶ σὴ ἡ δόξα, καὶ ἐγὼ σὸς οἰκέτης."}, {"sp": "N", "st": "1 Esd 4:60", "t": "εὐλογητὸς εἶ, ὃς ἔδωκάς μοι σοφίαν· καὶ σοὶ ὁμολογῶ, δέσποτα τῶν πατέρων."}, {"sp": "N", "st": "1 Esd 4:61", "t": "καὶ ἔλαβεν τὰς ἐπιστολὰς καὶ ἐξῆλθεν εἰς Βαβυλῶνα καὶ ἀπήγγειλεν τοῖς ἀδελφοῖς αὐτοῦ πᾶσιν."}, {"sp": "N", "st": "1 Esd 4:62", "t": "καὶ εὐλόγησαν τὸν θεὸν τῶν πατέρων αὐτῶν, ὅτι ἔδωκεν αὐτοῖς ἄνεσιν καὶ ἄφεσιν"}, {"sp": "N", "st": "1 Esd 4:63", "t": "ἀναβῆναι καὶ οἰκοδομῆσαι Ἰερουσαλὴμ καὶ τὸ ἱερὸν οὗ ὠνομάσθη τὸ ὄνομα αὐτοῦ ἐπʼ αὐτῷ· καὶ ἐκωθωνίζοντο μετὰ μουσικῶν καὶ χαρᾶς ἡμέρας ἑπτά."}, {"sp": "N", "st": "1 Esd 5:1", "t": "Μετὰ δὲ ταῦτα ἐξελέγησαν ἀναβῆναι ἀρχηγοὶ οἴκου πατριῶν κατὰ φυλὰς αὐτῶν, καὶ αἰ γυναῖκες αὐτῶν καὶ οἱ υἱοὶ καὶ αἱ θυγατέρες καὶ οἱ παῖδες αὐτῶν, καὶ αἱ παιδίσκαι καὶ τὰ κτήνη αὐτῶν."}, {"sp": "N", "st": "1 Esd 5:2", "t": "καὶ Δαρεῖος συναπέστειλεν μετʼ αὐτῶν ἱππεῖς χιλίους ἕως τοῦ ἀποκαταστῆσαι αὐτοὺς εἰς Ἰερουσαλὴμ μετ᾿ εἰρήνης καὶ μετὰ μουσικῶν, τυμπάνων καὶ αὐλῶν."}, {"sp": "N", "st": "1 Esd 5:3", "t": "καὶ πάντες οἱ ἀδελφοὶ αὐτῶν παίζοντες· καὶ ἐποίησεν αὐτοῖς συναναβῆναι μετʼ ἐκείνων."}, {"sp": "N", "st": "1 Esd 5:4", "t": "Καὶ ταῦτα τὰ ὀνόματα τῶν ἀνδρῶν τῶν ἀναβαινόντων κατὰ πατριὰς αὐτῶν εἰς τὰς φυλὰς ἐπὶ τὴν μεριδαρχίαν αὐτῶν."}, {"sp": "N", "st": "1 Esd 5:5", "t": "οἱ ἱερεῖς υἱοὶ Φινεές υἱοὶ Ἀαρών, Ἰησοῦς ὁ τοῦ Ἰωσεδὲκ τοῦ Σαραίου, καὶ Ἰωακεὶμ ὁ τοῦ Ζοροβαβὲλ τοῦ Σαλαθιὴλ ἐκ τοῦ οἴκου τοῦ Δαυείδ, ἐκ τῆς γενεᾶς Φάρες, φυλῆς δὲ Ἰούδα,"}, {"sp": "N", "st": "1 Esd 5:6", "t": "ὃς ἐλάλησεν ἐπὶ Δαρείου τοῦ βασιλέως Περκῶν λόγους σοφοὺς ἐν τῷ δευτέρῳ ἔτει τῆς βασιλείας αὐτοῦ μηνὶ Νισὰν τοῦ πρώτου μηνός."}, {"sp": "N", "st": "1 Esd 5:7", "t": "εἰσὶν δὲ οὗτοι οἱ ἐκ τῆς Ἰουδαίας οἱ ἀναβάντες ἐκ τῆς αἰχμαλωσίας τῆς παροικίας, οὓς μετοίκισεν Ναβουχοδονοσὸρ βασιλεὺς Βαβυλῶνος εἰς Βαβυλῶνα,"}, {"sp": "N", "st": "1 Esd 5:8", "t": "καὶ ἐπέστρεψεν εἰς Ἰερουσαλὴμ (8)καὶ τὴν λοιπὴν Ἰουδαίαν ἕκαστος εἰς τὴν ἰδίαν πόλιν, οἱ ἐλθόντες μετὰ Ζοροβαβὲλ καὶ Ἰησοῦ, Νεεμίου, Ζαραίου, Ῥησαίου, Ἐνήνιος. Μαρδοχαίου, Βεελσάρου, Ἀσφαράσου, Βορολείου, Ῥοείμου, Βαανά, τῶν προηγουμένων αὐτῶν."}, {"sp": "N", "st": "1 Esd 5:9", "t": "ἀριθμὸς τῶν ἀπὸ τοῦ ἔθνους καὶ οἱ προηγούμενοι αὐτῶν· υἱοὶ Φορός, ἑβδομήκοντα δύο χιλιάδες·"}, {"sp": "N", "st": "1 Esd 5:10", "t": "υἱοὶ Ἀρές, ἑπτακόσιοι πεντήκοντα ἕξ,"}, {"sp": "N", "st": "1 Esd 5:11", "t": "υἱοὶ Φθαλειμωάβ, εἰς τοὺς υἱοὺς Ἰησοῦ καὶ Ῥοβοάβ, δισχλιοι ὀκτακόσιοι δύο·"}, {"sp": "N", "st": "1 Esd 5:12", "t": "υἱοὶ Ἰωλάμου, δύο· υἱοὶ Ζατόν, ἐννακόσιοι ἑβδομήκοντα· υἱοὶ Χορβέ, ἑπτακόσιοι πέντε· υἱοὶ Βανεί, ἑξακόσιοι τεσσεράκοντα ὀκτώ·"}, {"sp": "N", "st": "1 Esd 5:13", "t": "υἱοὶ Βηβαί, ἑξακόσιοι τριάκοντα τρεῖς· υἱοὶ Ἀργαί, χίλιοι τριακόσιοι εἴκοσι δύο·"}, {"sp": "N", "st": "1 Esd 5:14", "t": "υἱοὶ Ἀδωνεικάμ, τριάκοντα ἑπτά· υἱοὶ Βοσαί, δισχίλιοι ἐξακόσιοι ἕξ· υἱοὶ Ἀδειλίου, τετρακόσιοι πεντήκοντα τέσσαρες·"}, {"sp": "N", "st": "1 Esd 5:15", "t": "υἱοὶ Ἀζὴρ Ἐζεκίου, υἱοὶ Κειλὰν καὶ Ἀζητάς, ἐξήκοντα ἑπτά· υἱοὶ Ἀζάρου, τετρακόσιοι τριάκοντα δύο·"}, {"sp": "N", "st": "1 Esd 5:16", "t": "υἱοὶ Ἁννείς, ἑκατὸν εἷς· υἱοὶ Ἀρόμ, υἱοὶ Βασσαί, τριακόσιοι εἴκοσι τρεῖς· υἱοὶ Ἀρσειφουρείθ,"}, {"sp": "N", "st": "1 Esd 5:17", "t": "υἱοὶ Βαιτηροῦς, τρισχίλιοι πέντε· υἱοὶ ἐκ Ῥαγεθλωμῶν, ἑκατὸν εἴκοσι τρεῖς·"}, {"sp": "N", "st": "1 Esd 5:18", "t": "οἱ ἐκ Νετέβας, πεντήκοντα πέντε· οἱ ἐξ Ἐνάτου, ἑκατὸν πεντήκοντα ὀκτώ· οἱ ἐκ Βαιτασμῶν Ζαμμώθ·"}, {"sp": "N", "st": "1 Esd 5:19", "t": "οἱ ἐκ Καρταθειαρειός, εἴκοσι πέντε· οἱ ἐκ Πείρας καὶ Βηρόγ, ἑπτακόσιοι·"}, {"sp": "N", "st": "1 Esd 5:20", "t": "οἱ Καδιάσαι καὶ Ἁμμίδιοι, τετρακόσιοι εἴκοσι δύο· οἱ ἐκ Κειράμας Κάββης, ἑξακόσιοι εἵκοσι εἷς·"}, {"sp": "N", "st": "1 Esd 5:21", "t": "οἱ ἐκ Μακαλῶν, ἑκατὸν εἴκοσι δύο· οἱ ἐκ Βετολιώ, πεντήκοντα δύοΝειφεῖς, ἑκατὸν πεντήκοντα ἕξ·"}, {"sp": "N", "st": "1 Esd 5:22", "t": "υἱοὶ Καλαμωκάλου καὶ Ὠνοῦς, ἑπτακόσιοι εἵκοσι πέντε· (²³)υἱοὶ Ἰερέχου, διακόσιοι τεσσεράκοντα πέντε·"}, {"sp": "N", "st": "1 Esd 5:23", "t": "υἱοὶ Σαμά, τρισχίλιοι τριακόσιοι εἰς·"}, {"sp": "N", "st": "1 Esd 5:24", "t": "οἱ ἱερεῖς (24)οἱ υοὶ Ἰέδδου τοῦ υἱοῦ Ἰησοῦ, εἰς τοὺς υἱοὺς Σαναβείς, ὀκτακόσιοι ἑβδομήκοντα δύο· υἱοὶ Ερμήρου, διακόσιοι πεντήκοντα δύο·"}, {"sp": "N", "st": "1 Esd 5:25", "t": "υἱοὶ Φασσόρου, χίλιοι διακόσιοί τεσσεράκοντα ἑπτά· υἱοὶ Χαρμή, διακόσιοι δέκα ἑπτά·"}, {"sp": "N", "st": "1 Esd 5:26", "t": "οἱ Λευεῖται υἱοὶ Ἰησουείς, Κοδοήλου καὶ Βάννου καὶ Σουδίου, ἑβδομήκοντα τέσσαρες·"}, {"sp": "N", "st": "1 Esd 5:27", "t": "υἱοὶ ἱεροψάλται υἱοὶ Ἀσάφ, ἑκατὸν εἴκοσι ὀκτώ·"}, {"sp": "N", "st": "1 Esd 5:28", "t": "οἱ θυρωροί, τετρακόσιοι· οἱ Ἰσμαήλου, υἱοὶ Λακουβάτου, χίλιοι· υἱοὶ Τωβείς, πάντες ἑκατὸν τριάκοντα ἐννέα·"}, {"sp": "N", "st": "1 Esd 5:29", "t": "οἱ ἱερόδουλοι, υἱοὶ Ἠσαύ, υἱοὶ Γασειφά, υἱοὶ Γαβαώθ, υἱοὶ Κηράς. υἱοὶ Σουά, υἱοὶ Φαλαίου, υἱοὶ Λαβανά,"}, {"sp": "N", "st": "1 Esd 5:30", "t": "υἱοὶ Ἀκούδ, υἱοὶ Οὐτά, υἱοὶ Κητάβ, υἱοὶ Ἁκκαβά, υἱοὶ Συβαεί, υἱοὶ Ἀνάν, υἱοὶ Κουά, υἱοὶ Κεδδούρ,"}, {"sp": "N", "st": "1 Esd 5:31", "t": "υἱοὶ Ἰαείρου, υἱοὶ Δαισάν, υἱοὶ Νοεβά, υἱοὶ Χασεβά, υἱοὶ Καζηρά, υἱοὶ Ὀζείου, υἱοὶ Φινόε, υἱοὶ Ἀσαρά, υἱοὶ Βασθαί, υἱοὶ Ἀσσανά, υἱοὶ Μανεί, υἱοὶ Ναφεισεί, υἱοὶ Ἀκούφ, υἱοὶ Ἀχειβά, υἱοὶ Ἀσούρ, υἱοὶ Φαρακέμ, υἱοὶ Βασαλέμ,"}, {"sp": "N", "st": "1 Esd 5:32", "t": "υἱοὶ Δεδδά, υἱοὶ Βαχούς, υἱοὶ Σεράρ, υἱοὶ Θόμθει, υἱοὶ Νασεί, υἱοὶ Ἁτεφά·"}, {"sp": "N", "st": "1 Esd 5:33", "t": "υἱοὶ παίδων Σαλωμών, υἱοὶ Ἁσσαφείωθ, υἱοὶ Φαρειδά, υἱοὶ Ἰειηλεί, υἱοὶ Λοζών, υἱοὶ Ἰσδαήλ, υἱοὶ Σαφυεί,"}, {"sp": "N", "st": "1 Esd 5:34", "t": "υἱοὶ Ἁγιά, υἱοὶ Φακαρὲθ Σαβειή, υἱοὶ Σαρωθεί, υἱοὶ Μεισαιάς, υἱοὶ Γάς, υἱοὶ Ἀδδούς, υἱοὶ Σουβάς, υἱοὶ Ἀφερρά, υἱοὶ Βαρωδείς, υἱοὶ Σαφάγ, υἱοὶ Ἀλλών·"}, {"sp": "N", "st": "1 Esd 5:35", "t": "πάντες οἱ ἱερόδουλοι καὶ οἱ υἱοὶ τῶν παίδων Σαλωμὼν τριακόσιοι ἑβδομήκοντα δύο,"}, {"sp": "N", "st": "1 Esd 5:36", "t": "οὗτοι ἀναβάντες ἀπὸ Θερμέλεθ καὶ Θελερσάς· ἡγούμενος αὐτῶν Χαρααθαλὰν καὶ Ἀλλάρ."}, {"sp": "N", "st": "1 Esd 5:37", "t": "καὶ οὐκ ἠ ναντο ἀπαγγεῖλαι τὰς πατριὰς αὐτῶν καὶ γενεάς, ὡς ἐκ τοῦ Ἰσραήλ εἰσιν· υἱοὶ Ἀσὰν τοῦ υἱοῦ τοῦ Βαενάν, υἱοὶ Νεκωδάν, ἑξακόσιοι πεντήκοντα δύο,"}, {"sp": "N", "st": "1 Esd 5:38", "t": "καὶ ἐκ τῶν ἱερέων οἱ ἐμποιούμενοι ἱεραωσύνης, καὶ οὐχ εὑρέθησαν· υρὶ Ὁββειά, υἱοὶ Ἀκβώς, υἱοὶ Ἰαδδοὺς τοῦ λαβόντος Αὐγίαν γυναῖκα τῶν θυγατέρων Φαηζελδαίου, (39)καὶ ἐκλήθη ἐπὶ τῷ ὀνόματι αὐτοῦ."}, {"sp": "N", "st": "1 Esd 5:39", "t": "καὶ τούτων ζητηθείσης τῆς γενικῆς γραφῆς ἐν τῷ καταλοχισμῷ καὶ μὴ εὑρεθείσης, ἐχωρίσθησαν τοῦ ἱερατεύειν."}, {"sp": "N", "st": "1 Esd 5:40", "t": "καὶ εἶπεν αὐτοῖς Ναιμίας καὶ Ἀτθαρίας μὴ μετέχειν τῶν ἁγίων ἕως ἀναστῇ ἱερεὺς ἐνδεδυμένος τὴν δήλωσιν καὶ τὴν ἀλήθειαν."}, {"sp": "N", "st": "1 Esd 5:41", "t": "Οἱ δὲ πάντες ἤσαν Ἰσραὴλ ἀπὸ δωδεκαετοῦς, χωρὶς παίδων καὶ παιδισκῶν, μυριάδες τέσσαρες δισχίλιοι τριακόσιοι ἕξήκοντα. (42)Παῖδες τούτων καὶ παιδίσκαι ἑπτακισχίλιοι τριακόσιοι τριάκοντα ἑπτά· ψάλται καὶ ψαλτῳδοί, διακόσιοι τεσσεράκοντα πέντε."}, {"sp": "N", "st": "1 Esd 5:42", "t": "κάμηλοι τετρακόσιοι τριάκοντα πέντε, καὶ ἵπποι ἑπτακισχίλιοι τριάκοντα ἕξ, ἡμίονοι διακόσιοι τεσσεράκοντα πέντε, ὑποζύγια πεντακισχίλια πεντακόσια εἴκοσι πέντε."}, {"sp": "N", "st": "1 Esd 5:43", "t": "Καὶ ἐκ τῶν ἡγουμένων κατὰ τὰς πατριὰς ἐν τῷ παραγίνεσθαι αὐτοὺς εἰς τὸ ἱερὸν τοῦ θεοῦ τὸ ἐν Ἰερουσαλὴμ εδξαντο ἐγεῖραι τὸν οἶκον ἐπὶ τοῦ τόπου αὐτοῦ κατὰ τὴν αὐτῶν δύναμιν,"}, {"sp": "N", "st": "1 Esd 5:44", "t": "καὶ δοῦναι εἰς τὸ ἱερὸν γαζοφυλάκιον τῶν ἔργων χρυσίου μνᾶς χιλίας καὶ ἀργυρίου μνᾶς πεντακισχιλίας καὶ στολὰς ἱερατικὰς ἑκατόν."}, {"sp": "N", "st": "1 Esd 5:45", "t": "καὶ κατοικίσθησαν οἱ ἱερεῖς καὶ οἱ Λευεῖται καὶ οἱ ἐκ τοῦ λαοῦ αὐτοῦ ἐν Ἰερουσαλὴμ καὶ τῇ χώρᾳ, οἵ τε ἱεροψάλται καὶ οἱ θυρωροὶ καὶ πᾶς Ἰσραὴλ ἐν ταῖς κώμαις αὐτῶν."}, {"sp": "N", "st": "1 Esd 5:46", "t": "Ἐνστάντος δέ τοῦ ἑβδόμου μηνός, καὶ ὄντων τῶν υἱῶν Ἰσραὴλ ἑκάστου ἐν τοῖς ἰδίοις, συνήχθησαν ὁμοθυμαδὸν εἰς τὸ εὐρύχωρον τοῦ πρώτου πυλῶνος τοῦ πρὸς τῆ ἀνατολῇ."}, {"sp": "N", "st": "1 Esd 5:145", "t": "καὶ καταστὰς Ἰησοῦς ὁ τοῦ Ἰωσεδὲκ καὶ οἱ ἀδελφοὶ αὐτοῦ οἱ ἱερεῖς καὶ Ζοροβαβὲλ ὁ τοῦ Σαλαθιὴλ καὶ οἱ τούτου ἀδελφοὶ ἡτοίμασαν τὸ θυσιαστήριον τοῦ θεοῦ Ἰσραήλ,"}, {"sp": "N", "st": "1 Esd 5:48", "t": "προσενέγκαι ἐπʼ αὐτοῦ ὁλοκαυτώσεις ἀκολούθως τοῖς ἐν τῇ Μωσέως βίβλῳ τοῦ ἀνθρώπου τοῦ θεοῦ διηγορευμένοις."}, {"sp": "N", "st": "1 Esd 5:49", "t": "καὶ ἐπισυνήχθησαν αὐτοῖς ἐκ τῶν ἄλλων ἐθνῶν τῆς γῆς καὶ κατωρθώθησαν ἐπὶ τὸ θυσιαστήριον ἐπὶ τοῦ τόπου αὐτῶν· ὅτι ἐν ἔχθρᾳ ἦσαν αὐτοῖς· κατίσχυσαν αὐτοὺς πάντα τὰ ἔθνη τὰ ἐπὶ τῆς γῆς· καὶ ἀνέφερον θυσίας κατὰ τὸν καιρὸν καὶ ὁλοκαυτώματα Κυρίῳ τὸ πρωινὸν καὶ τὸ δειλινόν."}, {"sp": "N", "st": "1 Esd 5:50", "t": "καὶ ἠγάγοσαν τὴν τῆς σκηνοπηγίας ἑορτὴν ὡς ἐπιτέτακται ἐν τῷ νόμῳ, καὶ θυσίας καθʼ ἡμέραν, ὡς προσῆκον ἦν·"}, {"sp": "N", "st": "1 Esd 5:51", "t": "καὶ μετὰ ταῦτα προσφορὰς ἐνδελεχισμοῦ, καὶ θυσίας σαββάτων καὶ νουμηνιῶν καὶ ἑορτῶν πασῶν ἡγιασμένων."}, {"sp": "N", "st": "1 Esd 5:52", "t": "καὶ ὅσοι εὔξαντο εὐχὴν τῷ θεῷ ἀπὸ τῆς νουμηνίας τοῦ πρώτου μηνός, ἤρξατο προσφέρειν θυσίας τῷ θεῷ, καὶ ὁ ναὸς τοῦ θεοῦ οὔπω ᾠκοδόμητο."}, {"sp": "N", "st": "1 Esd 5:53", "t": "καὶ ἔδωκαν ἀργύριον τοῖς λατόμοις καὶ τέκτοσι, καὶ ποτὰ καὶ βρωτὰ καὶ χάρα τοῖς Σειδωνίοις καὶ Τυρίοις εἰς τὸ παράγειν αὐτοὺς ἐκ τοῦ Λιβάνου ξύλα κέδρινα, διαφέρειν σχεδίας εἰς τὸν Ἰόππης λιμένα, καὶ τὸ πρόσταγμα τὸ γραφὲν αὐτοῖς παρὰ Κύρου τοῦ Περσῶν βασιλέως."}, {"sp": "N", "st": "1 Esd 5:54", "t": "καὶ τῷ δευτέρῳ ἔτει παραγενόμενος εἰς τὸ ἱερὸν τοῦ θεοῦ εἰς Ἰερουσαλὴμ μηνὸς δευτέρου ἤρξατο Ζοροβαβὲλ ὁ τοῦ Σαλαθιὴλ καὶ Ἰησοῦς ὁ τοῦ Ἰωσεδὲκ καὶ οἱ ἀδελφοὶ αὐτῶν καὶ οἱ ἱερεῖς οἱ Λευεῖται καὶ πάντες οἱ παραγενόμενοι ἐκ τῆς αἰχμαλωσίας εἰς Ἰερουσαλήμ,"}, {"sp": "N", "st": "1 Esd 5:55", "t": "καὶ ἐθεμελίωσαν τὸν ναὸν τοῦ θεοῦ τῇ νουμηνίᾳ τοῦ δευτέρου μηνὸς τοῦ δευτέρου ἔτους ἐν τῷ ἐλθεῖν εἰς τὴν Ἰουδαίαν καὶ Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 5:56", "t": "καὶ ἔστησαν τοὺς Λευείτας ἀπὸ εἰκοσαετοῦς ἐπὶ τῶν ἔργων τοῦ κυρίου· καὶ ἔστη Ἰησοῦς καὶ οἱ υἱοὶ καὶ οἱ ἀδελφοί, καὶ ὁ Δαμαδιὴλ ὁ ἀδελφός, καὶ οἱ υἱοὶ Ἰησοῦ Ἠμαδαβούν, καὶ οἱ υἱοὶ Ἰούδα τοῦ Εἰλιαδοὺν σὺν τοῖς υἱοῖς καὶ ἀδελφοῖς, πάντες οἱ Λευεῖται ὁμοθυμαδὸν ἐργοδιῶκται, ποιοῦντες εἰς τὰ ἔργα ἐν τῷ οἴκῳ τοῦ κυρίου· καὶ οἰκοδόμησαν οἱ οἰκοδόμοι τὸν ναὸν τοῦ κυρίου."}, {"sp": "N", "st": "1 Esd 5:57", "t": "Καὶ ἔστησαν οἱ ἱερεῖς ἐστολισμένοι μετὰ μουσικῶν καὶ σαλπίγγων, καὶ οἱ Λευεῖται υἱοὶ Ἀσὰφ ἔχοντες τὰ κύμβαλα (60)ὑμνοῦντες τῷ κυρίῳ καὶ εὐλογοῦντες κατὰ Δαυεὶδ βασιλέα τοῦ Ἰσραήλ·"}, {"sp": "N", "st": "1 Esd 5:58", "t": "καὶ ἐφώνησαν δι᾿ ὕμνων εὐλογοῦντες τῷ κυρίῳ, ὅτι ἡ χρηστότης αὐτοῦ καὶ ἡ δόξα εἰς τοὺς αἰῶνας παντὶ Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 5:59", "t": "καὶ πᾶς ὁ λαὸς ἐσάλπισαν καὶ ἐβόησαν φωνῇ μεγάλῃ, ὑμνοῦντες τῷ κυρίῳ ἐπὶ τῇ ἐγέρσει τοῦ οἴκου Κυρίου."}, {"sp": "N", "st": "1 Esd 5:60", "t": "καὶ ἤλθοσαν ἐκ τῶν ἱερέων τῶν Λευειτῶν καὶ τῶν προκαθημένων κατὰ τὰς πατριὰς αὐτῶν οἱ πρεσβύτεροι ἑωρακότες τὸν πρὸ τοῦ οἶκον(64)πρὸς τὴν τούτου οἰκοδομὴν μετὰ κραυγῆς καὶ κλαυθμοῦ μεγάλου,"}, {"sp": "N", "st": "1 Esd 5:61", "t": "καὶ πολλοὶ διὰ σαλπίγγων, καὶ χαρὰ μεγάλῃ τῇ φωνῇ·"}, {"sp": "N", "st": "1 Esd 5:62", "t": "ὥστε τὸν λαὸν μὴ ἀκούειν τῶν σαλπίγγων διὰ τὸν κλαυθμὸν τοῦ λαοῦ· ὁ γὰρ ὄχλος ἦν ὁ σαλπίζων μεγάλως, ὥστε μακρόθεν ἀκούεσθαι."}, {"sp": "N", "st": "1 Esd 5:63", "t": "Καὶ ἀκούσαντες οἱ ἐχθροὶ τῆς φυλῆς Ἰούδα καὶ Βενιαμεὶν ἤλθοσαν ἐπιγνῶναι τίς ἡ φωνὴ τῶν σαλπίγγων,"}, {"sp": "N", "st": "1 Esd 5:64", "t": "καὶ ἐπέγνωσαν ὅτι οἱ ἐκ τῆς αἰχμαλωσίας οἰκοδομοῦσιν τὸν ναὸν τῷ κυρίῳ θεῷ Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 5:65", "t": "καὶ προσελθόντες τῷ Ζοροβάβελ καὶ Ἰησοῦ καὶ τοῖς ἡγουμένοις τῶν πατριῶν λέγουσιν αὐτοῖς Συνοικοδομήσομεν ὑμῖν·"}, {"sp": "N", "st": "1 Esd 5:66", "t": "ὁμοίως γὰρ ὑμῖν ἀκούομεν τοῦ κυρίου ὑμῶν, καὶ αὐτῷ ἐπιθύσομεν ἀπὸ ἡμερῶν Ἀσβακαφὰθ βασιλέως Ἀσσυρίων, ὃς μετήγαγεν ἡμᾶς ἐνταῦθα."}, {"sp": "N", "st": "1 Esd 5:67", "t": "καὶ εἶπεν αὐτοῖς Ζοροβαβὲλ καὶ Ἰησοῦς καὶ οἱ ἡγούμενοι τῶν πατριῶν τοῦ Ἰσραήλ (⁷¹)Οὐχ ὑμῖν τοῦ οἰκοδομῆσαι τὸν οἶκον Κυρίῳ θεῷ ἡμῶν·"}, {"sp": "N", "st": "1 Esd 5:68", "t": "ἡμεῖς γὰρ μόνοι οἰκοδομήσομεν τῷ κυρίῳ τοῦ Ἰσραήλ, ἀκολούθως οἷς προσέταξεν ἡμῖν Κῦρος ὁ βασιλεὺς Περσῶν."}, {"sp": "N", "st": "1 Esd 5:69", "t": "τὰ δὲ ἔθνη τῆς γῆς ἐπικοιμώμενα τοῖς ἐν τῆ Ἰουδαίᾳ καὶ πολιορκοῦντες εἶργον τοῦ οἰκοδομεῖν,"}, {"sp": "N", "st": "1 Esd 5:70", "t": "καὶ βουλὰς καὶ δημαγογοῦντες καὶ συστάσεις ποιούμενοι ἀπεκώλυσαν τοῦ ἀποτελεσθῆναι τὴν οἰκοδομὴν πάντα τὸν χρόνον τῆς ζωῆς τοῦ βασιλέως Κύρου· καὶ εἴρχθησαν τῆς οἰκοδομῆς ἔτη δύο ἕως τῆς Δαρείου βασιλείας."}, {"sp": "N", "st": "1 Esd 6:1", "t": "Ἐν δὲ τῷ δευτέρῳ ἔτει τῆς Δαρείου βασιλείας ἐπροφήτευσεν Ἁγγαῖος καὶ Ζαχαρίας ὁ τοῦ Ἐδδεὶν οἱ προφῆται ἐπὶ τοὺς Ἰουδαίους τοὺς ἐν τῇ Ἰουδαίᾳ καὶ Ἰερουσαλήμ, ἐπὶ τῷ ὀνόματι Κυρίου θεοῦ Ἰσραὴλ ἐπʼ αὐτούς."}, {"sp": "N", "st": "1 Esd 6:2", "t": "τότε στὰς Ζροβαβὲλ ὁ τοῦ Σαλαθιὴλ καὶ Ἰησοῦς ὁ τοῦ Ἰωσεδὲκ ἤρξαντο οἰκοδομεῖν τὸν οἶκον τοῦ κυρίου τὸν ἐν Ἰερουσαλήμ, (3)συνόντων τῶν προφητῶν τοῦ κυρίου βοηθούντων αὐτοῖς."}, {"sp": "N", "st": "1 Esd 6:3", "t": "ἐν αὐτῷ τῷ χρόνῳ παρῆν πρὸς αὐτοὺς Σισίννης ὁ ἔπαρχος Συρίας καὶ Φοινίκης καὶ Σαθραβουζάνης καὶ οἱ συνέταιροι· (4)καὶ εἶπεν αὐτοῖς"}, {"sp": "N", "st": "1 Esd 6:4", "t": "Τίνος ὑμῖν συντάξαντος τὸν οἶκον τοῦτον οἰκοδομεῖτε καὶ τὴν στέγην ταύτην καὶ τἄλλα πάντα ἐπιτελεῖτε; καὶ τίνες εἰσὶν οἱ οἰκοδόμοι οἱ ταῦτα τελοῦντες;"}, {"sp": "N", "st": "1 Esd 6:5", "t": "καὶ ἔσχοσαν χάριν ἐπισκοπῆς γενόμενοι ἐπὶ τὴν αἰχμαλωσίαν παρὰ τοῦ κυρίου οἱ πρεσβύτεροι τῶν Ἰουδαίων,"}, {"sp": "N", "st": "1 Esd 6:6", "t": "καὶ οὐκ ἐκωλύθησαν τῆς οἰκοδομῆς μέχρις οὗ ἀποσημανθῆναι Δαρείῳ περὶ αὐτῶν καὶ προσφωνηθῆναι."}, {"sp": "N", "st": "1 Esd 6:7", "t": "Ἀντίγραφον ἐπιστολῆς ἧς ἔγραψεν Δαρείῳ καὶ ἀπέστειλαν Σισίννης ὁ ἔπαρχος Συρίας καὶ Φοινίκης καὶ Σαθραβουρζάνης καὶ οἱ συνέταιροι οἱ ἐν Συρίᾳ καὶ Φοινίκῃ ἡγεμόνες Βασιλεῖ Δαρείῳ χαίρειν."}, {"sp": "N", "st": "1 Esd 6:8", "t": "πάντα γνωστὰ ἔστω τῷ κυρίῳ ἡμῶν τῷ βασιλεῖ ὅτι παραγενόμενοι εἰς τὴν χώραν τῆς Ἰουδαίας καὶ Ἰερουσαλὴμ τὴν πόλιν κατελάβομεν τῆς αἰχμαλωσίας τοὺς πρεσβυτέρους τῶν Ἰουδαίων ἐν Ἰερουσαλὴμ τῇ πόλει οἰκοδομοῦντας οἶκον τῷ κυρίῳ μέγαν καινόν, (9)διὰ λίθων ξυστῶν πολυτελῶν, ξύλων τιθεμένων ἐν τοῖς οἴκοις,"}, {"sp": "N", "st": "1 Esd 6:9", "t": "καὶ τὰ ἔργα ἐκεῖνα ἐπὶ σπουδῆς γινόμενα, καὶ εὐοδούμενον τὸ ἔργον ἐν ταῖς χερσὶν αὐτῶν, καὶ ἐν πάση δόξῃ καὶ ἐπιμελείᾳ συντελούμενα."}, {"sp": "N", "st": "1 Esd 6:10", "t": "τότε ἐπυνθανόμεθα τῶν πρεσβυτέρων τούτων λέγοντες Τίνος ὑμῖν προστάξαντος οἰκοδομεῖτε τὸν οἶκον τοῦτον καὶ τὰ ἔργα ταῦτα ἐθεμελιοῦτε;"}, {"sp": "N", "st": "1 Esd 6:11", "t": "ἐπερωτήσαμεν οὖν αὐτοὺς ἕνεκεν τοῦ γνωρίσαι σοι καὶ γράψαι σοι τοὺς ἀνθρώπους τοὺς ἀφηγουμένους, καὶ τὴν ὀνοματογραφίαν ᾐτοῦμεν αὐτοὺς τῶν προκαθηγουμένων."}, {"sp": "N", "st": "1 Esd 6:12", "t": "οἱ δὲ ἀπεκρίθησαν ἡμῖν λέγοντες Ἐσμὲν παῖδες τοῦ κυρίου τοῦ κτίσαντος τὸν οὐρανὸν καὶ τὴν γῆν."}, {"sp": "N", "st": "1 Esd 6:13", "t": "καὶ οἰκοδομεῖτο ὁ οἶκος ἔμπροσθεν ἐτῶν πλειόνων διὰ βασιλέως τοῦ Ἰσραὴλ μεγάλου καὶ ἰσχυροῦ, καὶ ἐπετελέσθη."}, {"sp": "N", "st": "1 Esd 6:14", "t": "καὶ ἐπεὶ οἱ πατέρες ἡμῶν παραπικράναντες ἥμαρτον εἰς τὸν κύριον τοῦ Ἰσραὴλ τὸν οὐράνιον, παρέδωκεν αὐτοὺς εἰς χεῖρας Ναβουχοδονοσὸρ βασιλέως Βαβυλῶνος, βασιλέως τῶν Χαλδαίων·"}, {"sp": "N", "st": "1 Esd 6:15", "t": "τόν τε οἶκον καθελόντες ἐνεπύρισαν, καὶ τὸν λαὸν ᾐχμαλώτευσαν εἰς Βαβυλῶνα."}, {"sp": "N", "st": "1 Esd 6:16", "t": "ἐν δὲ τῷ πρώτῳ ἔτει βασιλεύοντος Κύρου χώρας Βαβυλωνίας ἔγραψεν βασιλεὺς Κῦρος οἰκοδομῆσαι τὸν οἶκον τοῦτον,"}, {"sp": "N", "st": "1 Esd 6:17", "t": "καὶ τὰ ἱερὰ σκεύη τὰ χρυσᾶ καὶ τὰ ἀργυρᾶ, ἃ ἐξήνεγκεν Ναβουχοδονοσὸρ ἐκ τοῦ οἵκου τοῦ ἐν Ἰερουσαλὴμ καὶ ἀπηρείσατο αὐτὰ ἐν τῷ αὐτοῦ ναῷ, πάλιν ἐξήνεγκεν αὐτὰ Κῦρος ὁ βασιλεὺς ἐκ τοῦ ναοῦ τοῦ ἐν Βαβυλωνία, καὶ παρεδόθη Ζοροβαβὲλ καὶ Σαβανασσάρῳ τῷ ἐπάρχῳ."}, {"sp": "N", "st": "1 Esd 6:18", "t": "καὶ ἐπετάγη αὐτῷ, καὶ ἀπήνεγκεν πάντα τὰ σκεύη ταῦτα ἀποθεῖναι ἐν τῷ ναῷ τῷ ἐν Ἰερουσαλήμ, καὶ τὸν ναὸν τοῦ κυρίου οἰκοδομηθῆναι ἐπὶ τοῦ τόπου."}, {"sp": "N", "st": "1 Esd 6:19", "t": "τότε ὁ Σαναβάσσαρος παραγενόμενος εἰσεβάλλετο τοὺς θεμελίους τοῦ οἴκου Κυρίου τοῦ ἐν Ἰερουσαλήμ, καὶ ἀπʼ ἐκείνου μέχρι τοῦ νῦν οἰκοδομούμενος οὐκ ἔλαβεν συντέλειαν."}, {"sp": "N", "st": "1 Esd 6:20", "t": "νῦν οὗν κρίνεται, βασιλεῦ· ἐπισκεπήτω ἐν τοῖς βασιλικοῖς βιβλιοφυλακίοις τοῦ κυρίου βασιλέως τοῖς ἐν Βαβυλῶνι,"}, {"sp": "N", "st": "1 Esd 6:21", "t": "καὶ ἐὰν εὑρίσκηται μετὰ τῆς γνώμης Κύρου τοῦ βασιλέως γενομένην τὴν οἰκοδομὴν τοῦ κυρίου τοῦ ἐν Ἰερουσαλήμ, καὶ κρίνηται τῷ κυρίῳ βασιλεῖ ἡμῶν, προσφωνησάτω ἡμῖν περὶ τούτων."}, {"sp": "N", "st": "1 Esd 6:22", "t": "Τότε ὁ βασιλεὺς Δαρεῖος προσέταξεν ἐπισκέψασθαι ἐν τοῖς βιβλιοφυλακίοις τοῖς κειμένοις ἐν Βαβυλῶνι, καὶ εὑρέθη ἐν Ἐκβατάνοις τῇ βάρει τῇ ἐν Μηδείᾳ χώρᾳ τόπος ἐν ᾧ ὑπομνημάτιστο τάδε"}, {"sp": "N", "st": "1 Esd 6:23", "t": "Ἔτους πρώτου βασιλεύοντος Κύρου βασιλεὺς Κῦρος προσέταξεν τὸν οἶκον τοῦ κυρίου τὸν ἐν Ἰερουσαλὴμ οἰκοδομῆσαι, ὅπου ἐπιθύουσιν διὰ πυρὸς ἐνδελεχοῦς,"}, {"sp": "N", "st": "1 Esd 6:24", "t": "οὗ τὸ ὕψος πήχεων ἐξήκοντα, πλάτος πήχεων ἑξήκοντα, διὰ δόμων λιθίνων ξυστῶν τριῶν καὶ δόμου ξυλίνου ἐγχωρίου καινοῦ ἑνός, καὶ τὸ δαπάνημα δοθῆναι ἐκ τοῦ οἴκου Κύρου τοῦ βασιλέως."}, {"sp": "N", "st": "1 Esd 6:25", "t": "καὶ τὰ ἱερὰ σκεύη τοῦ οἴκου Κυρίου τά τε χρυσᾶ καὶ ἀργυρᾶ, ἃ ἐξήνεγκεν Ναβουχοδονοσὸρ ἐκ τοῦ οἴκου τοῦ ἐν Ἰερουσαλήμ, ἀπήνεγκεν εἰς Βαβυλῶνα, ἀποκατασταθῆναι εἰς τὸν οἶκον τὸν ἐν Ἰερουσαλὴμ οὖ ἦν κείμενα, ὅπως τεθῇ ἐκεῖ·"}, {"sp": "N", "st": "1 Esd 6:26", "t": "προσέταξεν δὲ ἐπιμεληθῆναι Σισίννῃ ἐπάρχῳ Συρίας καὶ Φοινίκης καὶ Σαθραβουζάνῃ καὶ τοῖς συνεταίροις καὶ τοῖς ἀποτεταγμένοις ἐν Συρίᾳ καὶ Φοινίκῃ ἡγεμόσιν ἀπέχεσθαι τοῦ τόπου, ἐᾶσαι δὲ τὸν παῖδα Κυρίου Ζοροβαβέλ, ὕπαρχον δὲ τῆς Ἰουδαίας, καὶ τοὺς πρεσβυτέρους τῶν Ἰουδαίων τὸν οἶκον τοῦ κυρίου ἐκεῖνον οἰκοδομεῖν ἐπὶ τοῦ τόπου."}, {"sp": "N", "st": "1 Esd 6:27", "t": "κἀγὼ δὲ ἐπέταξα ὁλοσχερῶς οἰκοδομῆσαι, καὶ ἀτενίσαι ἴνα συνποιῶσιν τοῖς ἐκ τῆς αἰχμαλωσίας τῆς Ἰουδαίας μέχρι τοῦ ἐπιτελεσθῆναι τὸν οἶκον τοῦ κυρίου·"}, {"sp": "N", "st": "1 Esd 6:28", "t": "καὶ ἀπὸ τῆς φορολογίας κοίλης Συρίας καὶ Φοινίκης ἐπιμελῶς σύνταξιν δίδοσθαι τούτοις τοῖς ἀνθρώποις εἰς θυσίαν τῷ κυρίῳ, Ζοροβαβὲλ ἐπάρχῳ, εἰς ταύρους καὶ κριοὺς καὶ ἄρνας,"}, {"sp": "N", "st": "1 Esd 6:29", "t": "ὁμοίως δὲ καὶ πυρὸν καὶ ἅλα καὶ οἶνον καὶ ἔλαιον ἐνδελεχῶς κατʼ ἐνιαυτόν, καθὼς ἂν οἱ ἱερεῖς οἱ ἐν Ἰερουσαλὴμ ὑπαγορεύσαωσιν ἀναλίσκεσθαι καθʼ ἡμέραν ἀναμφισβητήτως,"}, {"sp": "N", "st": "1 Esd 6:30", "t": "ὅπως προσφέρωνται σπονδαὶ τῷ θεῷ τῷ ὑψίστῳ ὑπέρ τοῦ βασιλέως καὶ τῶν παίδων, καὶ προσεύχωνται περὶ τῆς αὐτῶν ζωῆς·"}, {"sp": "N", "st": "1 Esd 6:31", "t": "καὶ προστάξαι ἴνα ὅσοι ἐὰν παραβῶσίν τι τῶν γεγραμμένων καὶ ἀκυρώσωσιν, λημφθῆναι ξύλον ἐκ τῶν ἰδίων αὐτοῦ καὶ ἐπʼ αὐτοῦ κρεμασθῆναι, καὶ τὰ ὑπάρχοντα αὐτοῦ εἶναι βασιλικά."}, {"sp": "N", "st": "1 Esd 6:32", "t": "διὰ ταῦτα καὶ ὁ κύριος, οὗ τὸ ὄνομα αὐτοῦ ἐπικέκληται ἐκεῖ, ἀφανίσαι πάντα βασιλέα καὶ ἔθνος ὃς ἐκτενεῖ χεῖρα αὐτοῦ κωλῦσαι ἢ κακοποιῆσαι τὸν οἶκον Κυρίου ἐκεῖνον τὸν ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 6:33", "t": "ἐγὼ βασιλεὺς Δαρεῖος δεδογμάτικα ἐπιμελῶς κατὰ ταῦτα γίγνεσθαι."}, {"sp": "N", "st": "1 Esd 7:1", "t": "Τότε Σισίννης ἔπαρχος κοίλης Συρίας καὶ Φοινίκης καὶ Σαθραβουζάνης καὶ οἱ συνέταιροι, κατακολουθήσαντες τοῖς ὑπὸ τοῦ βασιλέως Δαρείου προσταγεῖσιν,"}, {"sp": "N", "st": "1 Esd 7:2", "t": "ἐπεστάτουν τῶν ἱερῶν ἔργων ἐπιμελέστερον συνεργοῦντες τοῖς πρεσβυτέροις τῶν Ἰουδαίων καὶ ἱεροστάταις."}, {"sp": "N", "st": "1 Esd 7:3", "t": "καὶ εὔοδα ἐγίνετο πὰ ἱερὰ ἔργα,(προφητευόντων Ἀγγαίου καὶ Ζαχαρίου τῶν προφητῶν·"}, {"sp": "N", "st": "1 Esd 7:4", "t": "καὶ συνετέλεσαν ταῦτα διὰ προστάγματος τοῦ κυρίου θεοῦ Ἰσραήλ, καὶ μετὰ τῆς γνώμης τοῦ Κύρου καὶ Δαρείου καὶ Ἀρταξέρξου βασιλέως Περσῶν."}, {"sp": "N", "st": "1 Esd 7:5", "t": "συνετελέσθη ὁ οἶκος ἕως τρίτης καὶ εἰκάδος μηνὸς Ἄδὰρ τοῦ ἕκτου ἔτους βασιλέως Δαρείου."}, {"sp": "N", "st": "1 Esd 7:6", "t": "καὶ ἐποίησαν οἱ υἱοὶ Ἰσραὴλ καὶ οἱ ἱερεῖς καὶ οἱ Λευεῖται καὶ οἱ λοιποὶ οἱ ἐκ τῆς αἰχμαλωσίας οἱ προστεθέντες ἀκολούθως τοῖς ἐν τῇ Μωσέως βίβλῳ."}, {"sp": "N", "st": "1 Esd 7:7", "t": "καὶ προσήνεγκαν εἰς τὸν ἐνκαινισμὸν τοῦ ἱεροῦ τοῦ κυρίου ταύρους ἑκατόν, κριοὺς διακοσίους, ἄρνας τετρακοσίας,"}, {"sp": "N", "st": "1 Esd 7:8", "t": "χιμάρους ὑπὲρ ἁμαρτίας παντὸς τοῦ Ἰσραὴλ δώδεκα, πρὸς ἀριθμὸν ἐκ τῶν φυλάρχων τοῦ Ἰσραὴλ δώδεκα."}, {"sp": "N", "st": "1 Esd 7:9", "t": "καὶ ἔστησαν οἱ ἱερεῖς καὶ οἱ Λευεῖται ἐσπολισμένοι κατὰ φυλὰς ἐπὶ τῶν ἔργων Κυρίου θεοῦ Ἰσραὴλ ἀκολούθως τῇ Μωυσέως βίβλῳ, καὶ οἱ θυρωροὶ ἐφʼ ἑκάστου πυλῶνος."}, {"sp": "N", "st": "1 Esd 7:10", "t": "Καὶ ἠγάγοσαν οἱ υἱοὶ Ἰσραὴλ τῶν ἐκ τῆς αἰχμαλωσίας τὸ πάσχα ἐν τῇ τεσσαρεσκαιδεκάτῃ τοῦ πρώτου μηνός, ὅτε ἡγνίσθησαν οἱ ἱερεῖς καὶ οἱ Λευεῖται ἅμα"}, {"sp": "N", "st": "1 Esd 7:11", "t": "καὶ πάντες οἱ υἱοὶ τῆς αἰχμαλωσίας· ὅτι ἡγνίσθησαν. ὅτι οἱ Λευεῖται ἅμα πάντες ἡγνίσθησαν,"}, {"sp": "N", "st": "1 Esd 7:12", "t": "καὶ ἔθυσαν τὸ πάσχα πᾶσιν τοῖς υἱοῖς τῆς αἰχμαλωσίας καὶ τοῖς ἀδελφοῖς αὐτῶν τοῖς ἱερεῦσιν καὶ ἑαυτοῖς."}, {"sp": "N", "st": "1 Esd 7:13", "t": "καὶ ἐφάγοσαν οἱ υἱοὶ Ἰσραὴλ οἱ ἐκ τῆς αἰχμαλωσίας, πάντες οἱ χωρισθέντες ἀπὸ τῶν βδελυγμάτων τῶν ἐθνῶν τῆς γῆς, ζητοῦντες τὸν κύριον."}, {"sp": "N", "st": "1 Esd 7:14", "t": "καὶ ἠγάγοσαν τὴν ἑορτὴν τῶν ἀζύμων ἑπτὰ ἡμέρας εὐφραινόμενοι ἔναντι Κυρίου,"}, {"sp": "N", "st": "1 Esd 7:15", "t": "ὅτι μετέστρεψεν τὴν βουλὴν τοῦ βασιλέως Ἀσσυρίων ἐπʼ αὐτούς, κατισχῦσαι τὰς χεῖρας αὐτῶν ἐπὶ τὰ ἔργα Κυρίου θεοῦ Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 8:1", "t": "Καὶ μεταγενέστερος τούτων ἐστίν, βασιλεύοντος Ἀρταξέρξου τοῦ βασιλέως Περσῶν, προσέβη Ἔσρας Ἀζαραίου τοῦ Ζεχρίου τοῦ Χελκείου τοῦ Σαλήμου"}, {"sp": "N", "st": "1 Esd 8:2", "t": "τοῦ Σαδδουλούκου τοῦ Ἀχειτὼβ τοῦ Ἀμαρθείου τοῦ Ὀζείου τοῦ Βοκκὰ τοῦ Ἀβεισαὶ τοῦ Φεινεὲς τοῦ Ἐλεαζὰρ τοῦ Ἀαρὼν τοῦ πρώτου ἱερέως."}, {"sp": "N", "st": "1 Esd 8:3", "t": "οὗτος Ἔσρας ἀνέβη ἐκ Βαβυλῶνος ὡς γραμματεὺς εὐφυὴς ὢν ἐν τῷ Μωυσέως νόμῳ τῷ ἐκδεδομένῳ ὑπὸ τοῦ θεοῦ τοῦ Ἰσραήλ,"}, {"sp": "N", "st": "1 Esd 8:4", "t": "καὶ ἔδωκεν αὐτῷ ὁ βασιλεὺς δόξαν, εὑρόντος χάριν ἐναντίον αὐτοῦ ἐπὶ πάντα τὰ ἀξιώματα αὐτοῦ."}, {"sp": "N", "st": "1 Esd 8:5", "t": "καὶ συνανέβησαν ἐκ τῶν υἱῶν Ἰσραὴλ καὶ τῶν ἱερέων καὶ Λευειτῶν καὶ ἱεροψαλτῶν καὶ θυρωρῶν καὶ ἱεροδούλων εἰς Ἰερουσαλήμ,"}, {"sp": "N", "st": "1 Esd 8:6", "t": "ἔτους ἑβδόμου βασιλεύοντος Ἀρταξέρξου ἐν τῷ πέμπτῳ μηνί· οὗτος ἐνιαυτὸς ὁ δεύτερος βασιλεῖ· ἐξελθόντος γὰρ ἐκ Βαβυλῶνος τῇ νουμηνίᾳ τοῦ πρώτου μηνὸς (⁷)παρεγένοντο εἰς Ἰερουσαλὴμ κατὰ τὴν δοθεῖσαν αὐτοῖς εὐοδίαν παρὰ τοῦ κυρίου ἐπʼ αὐτῷ."}, {"sp": "N", "st": "1 Esd 8:7", "t": "ὁ γὰρ Ἀψάρος πολλὴν ἐπιστήμην περιεῖχεν, εἰς τὸ μηδὲν παραλείπειν τῶν ἐκ τοῦ νόμου Κυρίου καὶ ἐκ τῶν ἐντολῶν πάντα τὸν Ἰσραήλ, δικαιώματα καὶ κρίματα."}, {"sp": "N", "st": "1 Esd 8:8", "t": "Προσπεσόντος παρὰ Ἀρταξέρξου βασιλέως πρὸς Ἔσραν τὸν ἱερέα καὶ ἀναγνώστην τοῦ νόμου Κυρίου, οὗ ἐστιν ἀντίγραφον τὸ ὑποκείμενον"}, {"sp": "N", "st": "1 Esd 8:9", "t": "Βασιλεὺς Ἀρταξέρξης Ἔσρᾳ τῷ ἱερεῖ καὶ ἀναγνώστῃ τοῦ νόμου Κυρίου χαίρειν."}, {"sp": "N", "st": "1 Esd 8:10", "t": "καὶ τὰ φιλάνθρωπα ἐγὼ κρίνας προσέταξα τοὺς βουλομένους ἐκ τοῦ ἔθνους τῶν Ἰουδαίων αἱρετίζοντας καὶ τῶν ἱερέων καὶ τῶν Λευειτῶν καὶ τῶνδε ἐν τῇ ἡμετέρᾳ βασιλείᾳ συμπορεύεσθαί σοι εἰς Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 8:11", "t": "ὅσοι οὖν ἐνθυμοῦνται, συνεξορμάσθωσαν, καθάπερ δέδοκται ἐμοί τε καὶ τοῖς ἑπτὰ φίλοις συμβουλευταῖς·"}, {"sp": "N", "st": "1 Esd 8:12", "t": "ὅπως ἐπισκέψωνται κατὰ τὴν Ἰουδαίαν καὶ κατὰ Ἰερουσαλὴμ ἀκολούθως ᾧ ἔχει νόμῳ Κυρίου,"}, {"sp": "N", "st": "1 Esd 8:13", "t": "καὶ ἀπενεγκεῖν δῶρα τῷ κυρίῳ ἃ ηὐξάμην ἐγώ τε καὶ οἱ φίλοι εἰς Ἰερουσαλήμ, καὶ πᾶν χρυσίον καὶ ἀργύριον ὃ ἐὰν εὑρεθῇ ἐν τῇ χώρᾳ τῆς Βαβυλωνίας τῷ κυρίῳ εἰς Ἰερουσαλὴμ (¹⁵)σὺν τῷ δεδωρημένῳ ὑπὸ τοῦ ἔθνους εἰς τὸ ἱερὸν τοῦ κυρίου αὐτῶν τὸ ἐν Ἰερουσαλὴμ"}, {"sp": "N", "st": "1 Esd 8:14", "t": "συναχθῆναι, τό τε χρυσίον καὶ ἀργύριον εἰς ταύρους καὶ κριοὺς καὶ ἄρνας καὶ τὰ τούτοις ἀκόλουθα,"}, {"sp": "N", "st": "1 Esd 8:15", "t": "ὥστε προσενεγκεῖν θυσίας ἐπὶ τὸ θυσιαστήριον τοῦ κυρίου αὐτῶν τὸ ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 8:16", "t": "καὶ πάντα ὅσα ἂν βούλῃ μετὰ τῶν ἀδελφῶν σου ποιῆσαι χρυσίῳ καὶ ἀργυρίῳ, ἐπιτέλει κατὰ τὸ θέλημα τοῦ θεοῦ σου·"}, {"sp": "N", "st": "1 Esd 8:17", "t": "καὶ κατὰ τὰ ἱερὰ σκεύη σου τὰ διδόμενα εἰς τὴν χρείαν τοῦ ἱεροῦ τοῦ θεοῦ σου τοῦ ἐν Ἰερουσαλήμ. (19)καὶ τὰ λοιπὰ ὅσα ἂν ὑποπίπτῃ σοι εἰς τὴν χρείαν τοῦ ἱεροῦ τοῦ θεοῦ σου"}, {"sp": "N", "st": "1 Esd 8:18", "t": "δώσεις ἐκ τοῦ βασιλικοῦ γαζοφυλακίου."}, {"sp": "N", "st": "1 Esd 8:19", "t": "καὶ ἐγὼ ἰδοὺ Ἀρταξέρξης ὁ βασιλεὺς προσέταξα τοῖς γαζοφύλαξι Συρίας καὶ Φοινίκης, ἵνα ὅσα ἂν ἀποστείλῃ Ἔσδρας ὁ ἱερεὺς καὶ ἀναγνώστης τοῦ νόμου τοῦ θεοῦ τοῦ ὑψίστου ἐπιμελῶς διδῶσιν αὐτῷ ἕως ἀργυρίου ταλάντων ἑκατόν,"}, {"sp": "N", "st": "1 Esd 8:20", "t": "ὁμοίως δὲ καὶ ἕως πυροῦ κόρων ἑκατὸν καὶ οἴνου μετρητῶν ἑκατόν."}, {"sp": "N", "st": "1 Esd 8:21", "t": "κατὰ τὸν τοῦ θεοῦ νόμον ἐπιτελεσθήτω τῷ θεῷ τῷ ὑψίστῳ, ἕνεκα τοῦ μὴ γενέσθαι ὀργὴν εἰς τὴν βασιλείαν τοῦ βασιλέως καὶ τῶν υἱῶν."}, {"sp": "N", "st": "1 Esd 8:22", "t": "καὶ ὑμῖν δὲ λέγεται ὅπως πᾶσι τοῖς ἱερεῦσιν καὶ τοῖς Λευείταις καὶ ἱεροψάλταις καὶ θυρωροῖς καὶ ἱεροδούλοις καὶ πραγματικοῖς τοῦ ἱεροῦ τούτου (25)μηδεμία φορολογία μηδὲ ἄλλη ἐπιβουλὴ γίνηται, μηδένα ἔχειν ἐξουσίαν ἐπιβαλεῖν τούτοις."}, {"sp": "N", "st": "1 Esd 8:23", "t": "καὶ σύ, Ἔσρα, κατὰ τὴν σοφίαν τοῦ θεοῦ ἀνάδειξον κριτὰς καὶ δικαστάς, ὅπως δικάζωσιν ἐν ὅλη Συρίᾳ καὶ Φοινίκῃ πάντας τοὺς ἐπισταμένους τὸν νόμον τοῦ θεοῦ σου· καὶ τοὺς μὴ ἐπισταμένους διδάξεις."}, {"sp": "N", "st": "1 Esd 8:24", "t": "καὶ πάντες ὅσοι ἐὰν παραβαίνωσι καὶ τὸν νόμον τοῦ θεοῦ σου καὶ τοῦ βασιλικοῦ ἐπιμελῶς κολασθήσονται, ἐάν τε καὶ θανάτῳ ἐάν τε καὶ τιμωρίᾳ, μὴ ἀργυρίῳ ζημίᾳ ἢ ἀπαγωγῇ."}, {"sp": "N", "st": "1 Esd 8:25", "t": "εὐλογητὸς μόνος ὁ κύριος ὁ δοὺς ταῦτα εἰς τὴν καρδίαν μου τοῦ βασιλέως, δοξάσαι τὸν οἶκον αὐτοῦ τὸν ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 8:26", "t": "καὶ ἐμέ ἐτίμησεν ἔναντι τῶν βασιλευόντων καὶ πάντων τῶν φίλων καὶ μεγιστάνων αὐτοῦ."}, {"sp": "N", "st": "1 Esd 8:27", "t": "καὶ ἐγὼ εὐθαρσὴς ἐγενόμην κατὰ τὴν ἀντίλημψιν Κυρίου θεοῦ μου, καὶ συνήγαγον ἐκ τοῦ Ἰσραὴλ ἄνδρας ὥστε συναναβῆναί μοι."}, {"sp": "N", "st": "1 Esd 8:28", "t": "Καὶ οὗτοι οἱ προηγούμενοι κατὰ τὰς πατριὰς αὐτῶν καὶ τὰς μεριδαρχίας, οἱ ἀναβάντες μετʼ ἐμοῦ ἐκ Βαβυλῶνος ἐν τῇ βασιλείᾳ Ἀρταξέρξου τοῦ βασιλέως."}, {"sp": "N", "st": "1 Esd 8:29", "t": "ἐκ τῶν υἱῶν Φορός, Γαροσότομος· ἐκ τῶν υἱῶν Ἰεταμάρου, Γάμηλος· τῶν υἱῶν Δαυείδ,"}, {"sp": "N", "st": "1 Esd 8:30", "t": "Φαρές, Ζαχαρίας. καὶ μετʼ αὐτοῦ ἀπὸ γραφῆς ἄνδρες ἑκατὸν πεντήκοντα·"}, {"sp": "N", "st": "1 Esd 8:31", "t": "ἐκ τῶν Μααθμωάβ, Ἐλιαλωνίας Ζαραίου, καὶ μετʼ αὐτοῦ ἄνδρες διακόσιοι·"}, {"sp": "N", "st": "1 Esd 8:32", "t": "ἐκ τῶν υἱῶν Ζαθοής, Εἰεχονίας Ἰεθήλου, καὶ μετʼ αὐτοῦ ἄνδρες διακόσιοι· τῶν υἱῶν Ἀδείν, Οὐβὴν Ἰωνάθου, καὶ μετʼ αὐτοῦ ἄνδρες διακόσιοι πεντήκοντα·"}, {"sp": "N", "st": "1 Esd 8:33", "t": "ἐκ τῶν υἱῶν Λάμ, Ἐσίας Γοθολίου, καὶ μετʼ αὐτοῦ ἄνδρες ἑβδομήκοντα·"}, {"sp": "N", "st": "1 Esd 8:34", "t": "ἐκ τῶν υἱῶν Σοφοτίου, Ζαραίος Μειχαήλου, καὶ μετʼ αὐτοῦ ἄνδρες ἑβδομήκοντα·"}, {"sp": "N", "st": "1 Esd 8:35", "t": "ἐκ τῶν υἱῶν Ἰωάβ, Ἀβαδίας Ἰεζήλου, καὶ μετʼ αὐτοῦ ἄνδρες διακόσιοι δέκα δύο·"}, {"sp": "N", "st": "1 Esd 8:36", "t": "ἐκ τῶν υἱῶν Βανιάς, Σαλειμὼθ Ἰωσαφίου, καὶ μετʼ αὐτοῦ ἄνδρες ἑκατὸν ἐξήκοντα·"}, {"sp": "N", "st": "1 Esd 8:37", "t": "ἐκ τῶν Βαιήρ, Ζαχαριαὶ Βημαί, καὶ μετʼ αὐτοῦ ἄνδρες εἵκοσι ὀκτώ·"}, {"sp": "N", "st": "1 Esd 8:38", "t": "υἱοὶ Ἀστάθ, Ἰωάνης Ἀκατάν, καὶ μετʼ αὐτοῦ ἄνδρες ἑκατὸν δέκα·"}, {"sp": "N", "st": "1 Esd 8:39", "t": "ἐκ τῶν υἱῶν Ἀδωνιακαὶμ οἱ ἔσχατοι, καὶ ταῦτα τὰ ὀνόματα αὐτῶν· Ἐλειφάλα τοῦ Γεουὴλ καὶ Σαμαίας, καὶ μετʼ αὐτῶν ἄνδρες ἑβδομήκοντα·"}, {"sp": "N", "st": "1 Esd 8:40", "t": "ἐκ τῶν υἱῶν Βαναὶ Οὐτοὺ Ἰστακάλκου, καὶ μετʼ αὐτοῦ ἄνδρες ἑβδομήκοντα."}, {"sp": "N", "st": "1 Esd 8:41", "t": "Καὶ > συναγαγὼν αὐτοὺς ἐπὶ τὸν λεγόμενον Ποταμόν, καὶ παρενεβάλομεν αὐτόθι ἡμέρας τρεῖς, καὶ κατέμαθον αὐτούς."}, {"sp": "N", "st": "1 Esd 8:42", "t": "καὶ ἐκ τῶν ἱερέων καὶ ἐκ τῶν Λευειτῶν οὐχ εὑρὼν ἐκεῖ"}, {"sp": "N", "st": "1 Esd 8:43", "t": "ἀπέστειλα πρὸς Ἐλεάζαρον καὶ Ἰδούηλον καὶ Μαασμᾶν καὶ Ἐναατὰν καὶ Σαμαίαν καὶ Ἰώριβον, Ναθάν, Ἐννατάν, Ζαχαρίαν καὶ Μεσολαβών, τοὺς ἡγουμένους καὶ ἐπιστήμονας,"}, {"sp": "N", "st": "1 Esd 8:44", "t": "καὶ εἶπα αὐτοῖς ἐλθεῖν πρὸς Λααδαῖον τὸν ἡγούμενον τὸν ἐν τῷ τόπῳ γαζοφυλακίου,"}, {"sp": "N", "st": "1 Esd 8:45", "t": "ἐντειλάμενος αὐτοῖς διαλεγῆναι Λοδαίῳ καὶ τοῖς ἀδελφοῖς αὐτοῦ καὶ τοῖς ἐν τῷ τόπῳ γαζοφύλαξιν ἀποστεῖλαι ἡμῖν τοὺς ἱερατεύσαντας ἐν τῷ οἴκῳ τοῦ κυρίου ἡμῶν,"}, {"sp": "N", "st": "1 Esd 8:46", "t": "ἄνδρα ἐπιστήμονα, τῶν υἱῶν Μοολεὶ τοῦ Λευεὶ τοῦ Ἰσραὴλ Ἀσεβηβίαν, καὶ τοὺς υἱοὺς καὶ τοὺς ἀδελφοὺς δέκα·"}, {"sp": "N", "st": "1 Esd 8:47", "t": "οἱ ἐκ τῶν υἱῶν Χανουναίου καὶ οἱ υἱοὶ αὐτῶν, εἵκοσι ἄνδρες·"}, {"sp": "N", "st": "1 Esd 8:48", "t": "καὶ ἐκ τῶν ἱεροδούλων ὧν ἔδωκεν Δαυείδ, καὶ οἱ ήγούμενοι εἰς τὴν ἐργασίαν τῶν Λευειτῶν, ἱερόδουλοι, διακόσιοι εἴκοσι· πάντων ἐσημάνθη ὀνοματογραφία."}, {"sp": "N", "st": "1 Esd 8:49", "t": "καὶ εὐξάμην ἐκεῖ νηστείαν τοῖς νεανίσκοις ἔναντι κυρίου ἡμῶν,"}, {"sp": "N", "st": "1 Esd 8:50", "t": "ζητῆσαι παρʼ αὐτοῦ εὐοδίαν ἡμῖν τε καὶ τοῖς τέκνοις ἡμῶν καὶ κτήνεσιν."}, {"sp": "N", "st": "1 Esd 8:51", "t": "ἐνετράπην γὰρ ἱππεῖς καὶ πεζοὺς προπομπὴν ἕνεκεν ἀσφαλείας τῆς πρὸς τοὺς ἐναντίους ἡμῖν."}, {"sp": "N", "st": "1 Esd 8:52", "t": "εἴπαμεν γὰρ τῷ βασιλεῖ ὅτι Ἰσχὺς τοῦ κυρίου ἡμῶν ἔσται μετὰ τῶν ἐπιζητούντων αὐτὸν εἰς πᾶσαν ἐπανόρθωσιν."}, {"sp": "N", "st": "1 Esd 8:53", "t": "καὶ πάλιν ἐδεήθημεν τοῦ κυρίου ἡμῶν πάντα ταῦτα, καὶ ἐτύχομεν εὐιλάτου."}, {"sp": "N", "st": "1 Esd 8:54", "t": "καὶ ἐχώρισα τῶν φυλάρχων τῶν ἱερέων ἄνδρας δέκα δύο, καὶ Ἐσερεβίαν καὶ Ἀσσαμίαν, καὶ μετʼ αὐτῶν ἐκ τῶν ἀδελφῶν αὐτῶν ἄνδρας δέκα."}, {"sp": "N", "st": "1 Esd 8:55", "t": "καὶ ἔστησα αὐτοῖς τὸ ἀργύριον καὶ τὸ χρυσίον καὶ τὰ ἱερὰ σκεύη τοῦ οἴκου τοῦ κυρίου ἡμῶν· οὕτως ἐδωρήσατο ὁ βασιλεὺς καὶ οἱ σύμβουλοι αὐτοῦ καὶ μεγιστᾶνες καὶ πᾶς Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 8:56", "t": "καὶ παρέδωκεν αὐτοῖς στήσας τάλαντα ἀργυρίου ἑξακόσια πεντήκοντα, καὶ σκεύη ἀργυρᾶ ταλάντων ἑκατόν, καὶ χρυσίου ταλάντων ἑκατόν, (58)χρυσώματα εἴκοσι, καὶ σκεύη χαλκᾶ ἀπὸ χαλκοῦ χρηστοῦ στίλβοντα σκεύη δέκα."}, {"sp": "N", "st": "1 Esd 8:57", "t": "καὶ εἶπα αὐτοῖς Καὶ ὑμεῖς ἅγιοί ἐστε τῷ κυρίῳ, καὶ τὰ σκεύη τὰ ἅγια καὶ τὸ ἀργύριον καὶ τὸ χρυσίον εὐχὴ τῷ κυρίῳ, κυρίῳ τῶν πατέρων ἡμῶν."}, {"sp": "N", "st": "1 Esd 8:58", "t": "ἀγρυπνεῖτε καὶ φυλάσσετε ἕως τοῦ παραδοῦναι αὐτὰ ὑμᾶς τοῖς φυλάρχοις τῶν ἱερέων καὶ τῶν Λευειτῶν καὶ τοῖς ἡγουμένοις τῶν πατριῶν τοῦ Ἰσραὴλ ἐν Ἰερουσαλὴμ ἐν τοῖς παστοφορίοις τοῦ οἵκου τοῦ κυρίου ἡμῶν."}, {"sp": "N", "st": "1 Esd 8:59", "t": "καὶ οἱ παραλαβόντες οἱ ἱερεῖς καὶ οἱ Λευεῖται τὸ ἀργύριον καὶ τὸ χρυσίον καὶ τὰ σκεύη τὰ ἐν Ἰερουσαλὴμ ἤνεγκαν εἰς τὸ ἱερὸν τοῦ κυρίου."}, {"sp": "N", "st": "1 Esd 8:60", "t": "Καὶ ἀναζεύξαντες ἀπὸ τοῦ τόπου Θερὰ τῇ δωδεκάτῃ τοῦ πρώτου μηνὸς ἕως ἤλθοσαν εἰς Ἰερουσαλὴμ κατὰ τὴν κραταιὰν χεῖρα τοῦ κυρίου ἡμῶν τὴν ἐφʼ ἡμῖν· καὶ ἐρύσατο ἡμᾶς ἀπὸ τῆς εἰσόδου ἀπὸ παντὸς ἐχθροῦ· καὶ ἦλθον εἰς Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 8:61", "t": "καὶ γενομένης αὐτόθι ἡμέρας τρίτης, σταθὲν τὸ ἀργύριον καὶ τὸ χρυσίον παρεδόθη ἐν τῷ οἴκῳ Κυρίου Μαρμωθὶ Οὐρεία ἱερεῖ,"}, {"sp": "N", "st": "1 Esd 8:62", "t": "καὶ μετʼ αὐτοῦ Ἐλεαζὰρ ὁ τοῦ Φεινεές· καὶ ἦσαν μετʼ αὐτῶν Ἰωσαβεὲς Ἰησοῦς καὶ Μωὲθ Σαβάννου, οἱ Λευεῖται, πρὸς ἀριθμὸν καὶ ὁλκὴν πάντα· (65)καὶ ἐγράφη πᾶσα ἡ ὁλκὴ αὐτῇ τῇ ὥρᾳ."}, {"sp": "N", "st": "1 Esd 8:63", "t": "οἱ δὲ παραγενόμενοι ἐκ τῆς αἰχμαλωσίας προσήνεγκαν θυσίας τῷ θεῷ τοῦ Ἰσραὴλ Κυρίῳ ἐνενήκοντα ἕξ, (67)ἄρνας ἑβδομήκοντα ἕξ, τράγους ὑπὲρ σωτηρίου δέκα δύοἅπαντα θυσίαν τῷ κυρίῳ."}, {"sp": "N", "st": "1 Esd 8:64", "t": "καὶ ἀπέδωκαν τὰ προστάγματα τοῦ βασιλέως τοῖς βασιλικοῖς οἰκονόμοις καὶ τοῖς ἐπάρχοις Συρίας καὶ Φοινίκης, καὶ ἐδόξασαν τὸ ἔθνος καὶ τὸ ἱερὸν τοῦ κυρίου."}, {"sp": "N", "st": "1 Esd 8:65", "t": "Καὶ τούτων τελεσθέντων προσήλθοσάν μοι οἱ ἡγούμενοι λέγοντες"}, {"sp": "N", "st": "1 Esd 8:66", "t": "Οὐκ ἐχώρισαν καὶ οἱ ἄρχοντες καὶ οἱ ἱερεῖς καὶ οἱ Λευεῖται (70)καὶ ἀλλογενῆ ἔθνη τῆς γῆς ἀκαθαρσίας αὐτῶν, Χαναναίων καὶ Χετταίων καὶ Φερεζαίων καὶ Ἰεβουσαίων καὶ Μωαβειτῶν καὶ Αἰγυπτίων καὶ Ἰδουμαίων."}, {"sp": "N", "st": "1 Esd 8:67", "t": "συνῴκισάν τινας τῶν θυγατερῶν αὐτῶν, καὶ αὐτοὶ καὶ οἱ υἱοὶ αὐτῶν· καὶ ἐπεμίγη τὸ σπέρμα τὸ ἅγιον εἰς τὰ ἀλλογενῆ ἔθνη τῆς γῆς. καὶ μετεῖχον οἱ προηγούμενοι καὶ οἱ μεγιστᾶνες τῆς ἀνομίας ταύτης ἀπὸ τῆς ἀρχῆς τοῦ πράγματος."}, {"sp": "N", "st": "1 Esd 8:68", "t": "καὶ ἅμα τῷ ἀκοῦσαί με ταῦτα ἔρρηξα τὰ ἱμάτια καὶ τὴν ἱερὰν ἐσθῆτα κατέτεινον τοῦ τριχώματος τῆς κεφαλῆς καὶ τοῦ πώγωνος, καὶ ἐκάθισα σύννους καὶ περίλυπος."}, {"sp": "N", "st": "1 Esd 8:69", "t": "καὶ ἐπισυνήχθησαν πρὸς μὲ ὅσοι ποτέ ἐπεκινοῦντο τῷ ῥήματι Κυρίου τοῦ Ἰσραὴλ ἐμοῦ πενθοῦντος ἐπὶ τῇ ἀνομίᾳ, καὶ ἐκαθήμην περίλυπος ἕως τῆς δειλινῆς θυσίας."}, {"sp": "N", "st": "1 Esd 8:70", "t": "καὶ ἐξεγερθεὶς ἐκ τῆς νηστείας, διερρηγμένα ἔχων τὰ ἱμάτια καὶ τὴν ἱερὰν ἐσθῆτα, κάμψας τὰ γόνατα καὶ ἐκτείνας τὰς χεῖρας πρὸς τὸν κύριον ἔλεγον"}, {"sp": "N", "st": "1 Esd 8:71", "t": "Κύριε, ᾔσχυμμαι, ἐντέτραμμαι κατὰ πρόσαωπόν σου."}, {"sp": "N", "st": "1 Esd 8:72", "t": "αἱ γὰρ ἁμαρτίαι ἡμῶν ἐπλεόνασαν ὑπέρ τὰς κεφαλὰς ἡμῶν, αἱ δὲ ἄγνοιαι ἡμῶν ὑπερήνεγκαν ἕως τοῦ οὐρανοῦ"}, {"sp": "N", "st": "1 Esd 8:73", "t": "ἀπὸ τῶν χρόνων τῶν πατέρων ἡμῶν, καί ἐσμεν ἐν μεγάλῃ ἁμαρτίᾳ ἕως τῆς ἡμέρας ταύτης."}, {"sp": "N", "st": "1 Esd 8:74", "t": "καὶ διὰ τὰς ἁμαρτίας ἡμῶν καὶ τῶν πατέρων ἡμῶν παρεδόθημεν σὺν τοῖς ἀδελφοῖς ἡμῶν, σὺν τοῖς βασιλεῦσιν ἡμῶν καὶ σὺν τοῖς ἱερεῦσιν ἡμῶν, τοῖς βασιλεῦσιν τῆς γῆς, εἰς ῥομφαίαν καὶ αἰχμαλωσίαν καὶ προνομὴν μετὰ αἰσχύνης μέχρι τῆς σήμερον ἡμέρας."}, {"sp": "N", "st": "1 Esd 8:75", "t": "καὶ νῦν κατὰ πόσον τι ἡμῖν ἐγενήθη ἔλεος παρὰ τοῦ κυρίου Κυρίου, καταλειφθῆναι ἡμῖν ῥίζαν καὶ ὄνομα ἐν τῷ τόπῳ τούτῳ ἁγιάσματος,"}, {"sp": "N", "st": "1 Esd 8:76", "t": "καὶ τοῦ ἀνακαλύψαι φωστῆρα ἡμῶν ἐν τῷ οἴκῳ τοῦ κυρίου ἡμῶν, δοῦναι ἡμῖν τροφὴν ἐν τῷ καιρῷ τῆς δουλείας ἡμῶν· (81)καὶ ἐν τῷ δουλεύειν ἡμᾶς οὐκ ἐνκατελείφθημεν ὑπὸ τοῦ κυρίου ἡμῶν,"}, {"sp": "N", "st": "1 Esd 8:77", "t": "ἀλλὰ ἐποίησεν ἡμᾶς ἐν χάριτι ἐνώπιον τῶν βασιλέων Περσῶν, δοῦναι ἡμῖν τροφὴν"}, {"sp": "N", "st": "1 Esd 8:78", "t": "καὶ δοξάσαι τὸ ἱερὸν ἡμῶν καὶ ἐγεῖραι τὴν ἔρημον Σειών, δοῦναι ἡμῖν στερέωμα ἐν τῇ Ἰουδαίᾳ καὶ Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Esd 8:79", "t": "καὶ νῦν τί ἐροῦμεν, Κύριε. ἔχοντες αὐτά; παρέβησαν τὰ προστάγματά σου ἃ ἔδωκας ἐν χειρὶ τῶν παίδων σου τῶν προφητῶν (84) λέγων"}, {"sp": "N", "st": "1 Esd 8:80", "t": "ὅτι Ἡ γῆ εἰς ἣν εἰσέρχεσθε κληρονομῆσαι, ἔστιν γῆ μεμολυσμένη μολυσμῷ τῶν ἀλλογενῶν ῆς γῆς, καὶ τῆς ἀκαθαρσίας αὐτῶν ἐνέπλησαν αὐτήν·"}, {"sp": "N", "st": "1 Esd 8:81", "t": "καὶ νῦν τὰς θυγατέρας ὑμῶν μὴ συνοικίσητε τοῖς υἱοῖς αὐτῶν, καὶ τὰς θυγατέρας αὐτῶν μὴ λάβητε τοῖς υἱοῖς ὑμῶν,"}, {"sp": "N", "st": "1 Esd 8:82", "t": "καὶ οὐ ζητήσετε εἰρηνεῦσαι τὰ πρὸς αὐτοὺς τὸν ἅπαντα χρόνον, ἵνα ἰσχύσαντες φάγητε τὰ ἀγαθὰ τῆς γῆς καὶ κατακληρονομήσητε τοῖς υἱοῖς ὑμῶν ἕως αἰῶνος."}, {"sp": "N", "st": "1 Esd 8:83", "t": "καὶ τὰ συμβαίνοντα πάντα ἡμῖν γίνεται διὰ τὰ ἔργα ἡμῶν τὰ πονηρὰ καὶ τὰς μεγάλας ἁμαρτίας. σύ γάρ, Κύριε, ὁ κουφίσας τὰς ἁμαρτίας ἡμῶν,"}, {"sp": "N", "st": "1 Esd 8:84", "t": "ἔδωκας ἡμῖν τοιαύτην ῥίζαν· πάλιν ἀνεκάμψαμεν παραβῆναι τὸν νόμον σου εἰς τὸ ἐπιμιγῆναι τῇ ἀκαθαρσίᾳ τῶν ἐθνῶν τῆς γῆς."}, {"sp": "N", "st": "1 Esd 8:85", "t": "οὐχὶ ὠργίσθης ἡμῖν ἀπολέσαι ἡμᾶς ἕως τοῦ μὴ καταλιπεῖν ῥίζαν καὶ σπέρμα καὶ ὄνομα ἡμῶν."}, {"sp": "N", "st": "1 Esd 8:86", "t": "κύριε τοῦ Ἰσραήλ, ἀληθινὸς εἶ· κατελείφθημεν γὰρ ῥίζα ἐν τῇ σήμερον."}, {"sp": "N", "st": "1 Esd 8:87", "t": "ἰδού ἐσμεν ἐνώπιόν σου ἐν ταῖς ἀνομίαις ἡμῶν· οὐ γὰρ ἔστιν στῆναι ἔτι ἔμπροσθέν σου ἐπὶ τούτοις."}, {"sp": "N", "st": "1 Esd 8:88", "t": "Καὶ ὅτε προσευχόμενος Ἔσρας ἀνθωμολογεῖτο κλαίων χαμαιπετὴς ἔμπροσθεν τοῦ ἱεροῦ, ἐπισυνήχθησαν πρὸς αὐτὸν ἀπὸ Ἰερουσαλὴμ ὄχλος πολὺς σφόδρα, ἄνδρες καὶ γυναῖκες, νεανίαι· κλαυθμὸς γὰρ ἦν μέγας ἐν τῷ πλήθει"}, {"sp": "N", "st": "1 Esd 8:89", "t": "καὶ φωνήσας Ἰεχονίας Ἰεήλου τῶν υἱῶν Ἰσραὴλ εἶπεν Ἐσρᾳ Ἡμεῖς ἡμάρτομεν εἰς τὸν κύριον· καὶ κατῴκησαν γυναῖκες ἀλλογενεῖς ἐκ τῶν ἐθνῶν τῆς γῆς· (94)καὶ νῦν ἐστιν ἐπάνω πᾶς Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 8:90", "t": "ἐν τούτῳ γενέσθω ἡμῖν ὀρκωμοσία πρὸς τὸν κύριον, ἐκβαλεῖν πάσας τὰς γυναῖκας ἡμῶν τὰς ἐκ τῶν ἀλλογενῶν σὺν τοῖς τέκνοις αὐτῶν, (95)ὡς ἐκρίθη σοι, καὶ ὅσοι πειθαρχήσουσιν τοῦ νόμου τοῦ κυρίου."}, {"sp": "N", "st": "1 Esd 8:91", "t": "ἀναστὰς ἐπιτέλει· (96)πρὸς σὲ γὰρ τὸ πρᾶγμα, καὶ ἡμεῖς μετὰ σοῦ ἰσχὺν ποιεῖν."}, {"sp": "N", "st": "1 Esd 8:92", "t": "καὶ ἀναστὰς Ἔσρας ὥρκισεν τοὺς φυλάρχους τῶν ἱερέων καὶ τῶν Λευειτῶν παντὸς τοῦ Ἰσραὴλ ποιῆσαι κατὰ ταῦτα, καὶ ὤμοσαν."}, {"sp": "N", "st": "1 Esd 9:1", "t": "Καὶ ἀναστὰς Ἔσρας ἀπὸ τῆς αὐλῆς τοῦ ἱεροῦ ἐπορεύθη εἰς τὸ παστοφόριον Ἰωνᾶ τοῦ Νασείβου,"}, {"sp": "N", "st": "1 Esd 9:2", "t": "καὶ αὐλισθεὶς ἐκεῖ ἄρτου οὐκ ἐγεύσατο οὐδὲ ὕδωρ ἔπιεν, πενθῶν ὑπὲρ τῶν ἀνομιῶν τῶν μεγάλων τοῦ πλήθους."}, {"sp": "N", "st": "1 Esd 9:3", "t": "καὶ ἐγένετο κήρυγμα ἐν ὁλῃ τῇ Ἰουδαίᾳ καὶ Ἰερουσαλὴμ πᾶσι τοῖς ἐκ τῆς αἰχμαλωσίας, συναχθῆναι εἰς Ἰερουσαλήμ·"}, {"sp": "N", "st": "1 Esd 9:4", "t": "καἰ ὅσοι ἅν μὴ ἀπαντἠσουσιν ἐν δυσὶν ἢ τρισὶν ἡμέραις κατὰ τὸ κρίμα τῶν προκαθημένων πρεσβυτέρων, ἀνιερωθήσονται τὰ κτήνη αὐτῶν, καὶ αὐτὸς ἀλλοτριωθήσεται ἀπὸ τοῦ πλήθους τῆς αἰχμαλωσίας."}, {"sp": "N", "st": "1 Esd 9:5", "t": "Καὶ ἐπισυνήχθησαν οἱ ἐκ τῆς φυλῆς Ἰούδα καὶ Βενιαμεὶν ἐν τρισὶν ἡμέραις εἰς Ἰερουσαλήμ· οὗτος ὁ μὴν ἔνατος τῇ εἰκάδι τοῦ μηνός."}, {"sp": "N", "st": "1 Esd 9:6", "t": "καὶ συνεκάθισαν πᾶν τὸ πλῆθος ἐν τῇ εὐρυχώρῳ τοῦ ἱεροῦ τρέμοντες τὸν ἐνεστῶτα χειμῶνα."}, {"sp": "N", "st": "1 Esd 9:7", "t": "καὶ ἀναστὰς Ἐσρας εἶπεν αὐτοῖς Ὑμεῖς ἠνομήσατε καὶ συνοικήσατε γυναιξὶν ἀλλογενέσιν, προσθεῖναι ἁμαρτίαν τῷ Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 9:8", "t": "καὶ νῦν δότε ὁμολογίαν δόξαν τῷ κυρίῳ θεῷ τῶν πατέρων ἡμῶν,"}, {"sp": "N", "st": "1 Esd 9:9", "t": "καὶ ποιήσατε τὸ θέλημα αὐτοῦ καὶ χωρίσθητε ἀπὸ τῶν ἐθνῶν τῆς γῆς καὶ ἀπὸ τῶν ἀλλογενῶν."}, {"sp": "N", "st": "1 Esd 9:10", "t": "καὶ ἐφώνησαν πᾶν τὸ πλῆθος καὶ εἶπον μεγάλῃ τῇ φωνῇ Οὕτως ὡς εἴρηκας ποιήσομεν."}, {"sp": "N", "st": "1 Esd 9:11", "t": "ἀλλὰ τὸ πλῆθος πολὺ καὶ ὥρα χειμερινή, καὶ οὐκ ἰσχύσομεν στῆναι αἴθριοι καὶ οὐχ εὕρομεν· καὶ τὸ ἔργον ἡμῖν οὐκ ἔστιν ἡμέρας μιᾶς οὐδὲ δύο, ἐπὶ πλεῖον γὰρ ἡμάρτομεν ἐν τούτοις."}, {"sp": "N", "st": "1 Esd 9:12", "t": "στήτωσαν δὲ οἱ προηγούμενοι τοῦ πλήθους, καὶ πάντες οἱ ἐκ τῶν κατοικιῶν ἡμῶν ὅσοι ἔχουσιν γυναῖκας ἀλλογενεῖς (13)παραγενηθήτωσαν λαβόντες χρόνον·"}, {"sp": "N", "st": "1 Esd 9:13", "t": "ἑκάστου τόπου τοὺς πρεσβυτέρους καὶ τοὺς κριτάς, ἕως τοῦ λῦσαι τὴν ὀργὴν Κυρίου ἀφʼ ἡμῶν τοῦ πράγματος τούτου."}, {"sp": "N", "st": "1 Esd 9:14", "t": "Ἰνάθας Ἀζαήλου καὶ Ἑζείας Θοκάνου ἐπεδέξαντο κατὰ ταῦτα, καὶ Μοσόλλαμος καὶ Λευεὶς καὶ Σαββαταῖος συνεβράβευσαν αὐτοῖς."}, {"sp": "N", "st": "1 Esd 9:15", "t": "καὶ ἐποί ησαν κατὰ πάντα ταῦτα οἱ ἐκ τῆς αἰχμαλωσίας."}, {"sp": "N", "st": "1 Esd 9:16", "t": "Καὶ ἐπελέξατο αὐτῷ Ἐσρας ὁ ἱερεὺς ἄνδρας ἡγουμένους τῶν πατριῶν αὐτῶν πάντας κατʼ ὄνομα, καὶ συνεκλείσθησαν τῇ νουμηνίᾳ τοῦ μηνὸς τοῦ δεκάτου ἐτάσαι τὸ πρᾶγμα."}, {"sp": "N", "st": "1 Esd 9:17", "t": "καὶ ἤχθη ἐπὶ πέρας τὰ κατὰ τοὺς ἄνδρας τοὺς ἐπισυναχθέντας γυναῖκας ἀλλογενεῖς ἕως τῆς νουμηνίας τοῦ πρώτου μηνός."}, {"sp": "N", "st": "1 Esd 9:18", "t": "καὶ εὑρέθησαν τῶν ἱερέων οἱ ἐπισυναχθέντες ἀλλογενεῖς γυναῖκας ἔχοντες"}, {"sp": "N", "st": "1 Esd 9:19", "t": "ἐκ τῶν υἱῶν Ἰησοῦ τοῦ Ἰωσεδὲκ καὶ τῶν ἀδελφῶν αὐτοῦ Μαεήλας καὶ Ἐλεάζαρος καὶ Ἰώριβος καὶ Ἰώδανος·"}, {"sp": "N", "st": "1 Esd 9:20", "t": "καὶ ἐπέβαλον τὰς χεῖρας ἐκβαλεῖν τὰς γυναῖκας αὐτῶν, καὶ εἰς ἐξιλασμὸν κριοὺς ὑπέρ τῆς ἀγνοίας αὐτῶν·"}, {"sp": "N", "st": "1 Esd 9:21", "t": "καὶ ἐκ τῶν υἱῶν Ἐμήρ, Ἁνανίας καὶ Ζαβδαῖος καὶ Μάνης καὶ Θαμαῖος καὶ Ἰερεὴλ καὶ Ἀζαρίας·"}, {"sp": "N", "st": "1 Esd 9:22", "t": "καὶ ἐκ τῶν υἱῶν Φαισούρ, Ἐλιωναίς, Ἀσσείας, Ἰσμάηλος καὶ Ναθαναῆλος καὶ Ὠκαίληδος καὶ Σάλθας·"}, {"sp": "N", "st": "1 Esd 9:23", "t": "καὶ ἐκ τῶν Λευειτῶν, Ἰώζαβδος καὶ Σενσεὶς καὶ Κῶνος, οὗτος Καλειταίς, καὶ Παθαῖος· καὶ Ὠούδας καὶ Ἰωανᾶς,"}, {"sp": "N", "st": "1 Esd 9:24", "t": "ἐκ τῶν ἱεροψαλτῶν Ἐλιάσεβος, Βάκχουρος,"}, {"sp": "N", "st": "1 Esd 9:25", "t": "ἐκ τῶν θυρωρῶν Σάλλουμος καὶ Τολβάνης·"}, {"sp": "N", "st": "1 Esd 9:26", "t": "ἐκ τοῦ Ἰσραὴλ ἐκ τῶν υἱῶν Φορός, Ἰερμὰ καὶ Ἰεζείας καὶ Μελχείας καὶ Μίληλος καὶ Ἐλεάζαρος καὶ Ἁσεβείας καὶ Βανναίας·"}, {"sp": "N", "st": "1 Esd 9:27", "t": "ἐκ τῶν υἱῶν Ἠλά, καὶ Ματὰν καὶ Ζαχαρίας. Ἰεζόρικλος καὶ Ὠαβδεῖος καὶ Ἰερεμὼθ καὶ Ἀηδείας·"}, {"sp": "N", "st": "1 Esd 9:28", "t": "καὶ ἐκ τῶν υἱῶν Ζαμόθ, Ἐλιαδᾶς, Ἐλειάσειμος, Ὀθονίας, Ἰαρειμὼθ καὶ Σάβαθος καὶ Ζεραλίας·"}, {"sp": "N", "st": "1 Esd 9:29", "t": "καὶ ἐκ τῶν υἱῶν Βηβαί, Ἰωάννης καὶ Ἀνανίας καὶ Ζάβδος καὶ Ἐμαθθίς·"}, {"sp": "N", "st": "1 Esd 9:30", "t": "καὶ ἐκ τῶν υἱῶν Μανί, Ὤλαμος, Μάμουχος Ἰεδαῖος, Ἰάσουβος καὶ Ἀσάηλος καὶ Ἰερεμώθ·"}, {"sp": "N", "st": "1 Esd 9:31", "t": "καὶ ἐκ τῶν υἱῶν Ἀδδείν, Λάθος καὶ Μοοσσείας, Λακκοῦνος καὶ Ναῖδος, καὶ Βεσκασπασμὺς καὶ Σεσθὴλ καὶ Βαλνοῦς καὶ Μανασσήας·"}, {"sp": "N", "st": "1 Esd 9:32", "t": "καὶ ἐκ τῶν υἱῶν Ἁννάν, Ἐλιωδᾶς καὶ Ἀσαίας καὶ Μελχείας καὶ Σαββαίας καὶ Σίμων Χοσάμαος·"}, {"sp": "N", "st": "1 Esd 9:33", "t": "καὶ ἐκ τῶν υἱῶν Ἁσόμ, Μαλτανναῖος καὶ Ματταθίας καὶ Σαβανναιοῦς καὶ Ἐλειφαλὰτ καὶ Μανασσὴ καὶ Σεμεεί·"}, {"sp": "N", "st": "1 Esd 9:34", "t": "καὶ ἐκ τῶν υἱῶν Βαανεί, Ἰερεμίας, Μομδεῖος, Μάηρος, Ἰουνά, Μαμδαὶ καὶ Πεδίας καὶ Ἀνως, Καραβασειὼν καὶ Ἐνάσειβος καὶ Μαμτάναιμος, Ἐλιασείς, Βαννούς, Ἐδιαλείς, Σομεείς, Σελεμίας, Ναθανίας· καὶ ἐκ τῶν υἱῶν Ἐζωρά, Σεσεἰς, Ἐζρεἰλ, Ἀζάηλος, Σάματος. Ζαμβρεί, Φόσηπος·"}, {"sp": "N", "st": "1 Esd 9:35", "t": "ἐκ τῶν Ὀομά, Ζειτίας, Ζαβαδαίας, Ἠδός, Οὐήλ, Βαναίας."}, {"sp": "N", "st": "1 Esd 9:36", "t": "πάντες οὗτοι συνῷκησαν γυναιξὶν ἀλλογενέσιν, καὶ ἀπέλυσαν αὐτὰς σὺν τέκνοις."}, {"sp": "N", "st": "1 Esd 9:37", "t": "Καὶ κατῴκησαν οἱ ἱερεῖς καὶ οἱ Λευεῖται καὶ οἱ ἐκ τοῦ Ἰσραὴλ ἐν Ἰερουσαλὴμ καὶ ἐν τῇ χώρᾳ τῇ νουμηνίᾳ τοῦ ἑβδόμου μηνός, καὶ οἱ υἱοὶ Ἰσραὴλ ἐν ταῖς κατοικίαις αὐτῶν."}, {"sp": "N", "st": "1 Esd 9:38", "t": "Καὶ συνήχθη πᾶν τὸ πλῆθος ὁμοθυμαδὸν ἐπὶ τὸ εὐρύχωρον τοῦ πρὸς ἀνατολὰς ἱεροῦ πυλῶνος,"}, {"sp": "N", "st": "1 Esd 9:39", "t": "καὶ εἶπεν Ἐσρᾳ τῷ ἱερεῖ καὶ ἀναγνώστῃ κομίσαι τὸν νόμον Μωσέως τὸν παραδοθέντα ὑπὸ τοῦ θεοῦ Ἰσραήλ."}, {"sp": "N", "st": "1 Esd 9:40", "t": "καὶ ἐκόμισεν Ἔσρας ὁ ἀρχιερεὺς τὸν νόμον παντὶ τῷ πλήθει ἀπὸ ἀνθρώπου ἕως γυναικὸς καὶ πᾶσιν τοῖς ἱερεῦσι, ἀκοῦσαι τὸν νόμον, νουμηνίᾳ τοῦ ἑβδόμου μηνός·"}, {"sp": "N", "st": "1 Esd 9:41", "t": "καὶ ἀνεγίνωσκεν ἐν τῷ πρὸ τοῦ ἱεροῦ πυλῶνος εὐρυχώρου ἀπὸ ὄρθρου ἕως μεσημβρινοῦ ἐνώπιον τῶν ἀνδρῶν καὶ γυναικῶν· καὶ ἐπέδωκαν πάντα τὸν νοῦν εἰς τὸν νόμον."}, {"sp": "N", "st": "1 Esd 9:42", "t": "καὶ ἔστη Ἔσρας ὁ ἱερεὺς καὶ ἀναγνώστης τοῦ νόμου ἐπὶ τοῦ ξυλίνοῦ νοῦ βήματος τοῦ κατασ κευασθέντος·"}, {"sp": "N", "st": "1 Esd 9:43", "t": "καὶ ἔστησεν αὐτῷ Ματταθίας, Σαμμού, Ἀνανίας, Ἀζαρίας, Οὐρείας, Ἐζεκίας, Βαάλσαμος ἐκ δεξιῶν."}, {"sp": "N", "st": "1 Esd 9:44", "t": "καὶ ἐξ εὐωνύμων Φαλαδαῖος, Μεισαήλ, Μελχείας, Λωθάσουβος, Ναβαρείας, Ζαχαρίας."}, {"sp": "N", "st": "1 Esd 9:45", "t": "καὶ ἀναλαβὼν Ἔσρας τὸ βιβλίον τοῦ πλήθους ἐνώπιον, προεκάθητο γὰρ ἐπιδόξως ἐνώπιον πάντων,"}, {"sp": "N", "st": "1 Esd 9:46", "t": "καὶ ἐν τῷ λῦσαι τὸν νόμον πάντες ὀρθοὶ ἔστησαν· καὶ εὐλόγησεν Ἀζαρίας τῷ ὑψίστῳ θεῷ Παντοκράτορι,"}, {"sp": "N", "st": "1 Esd 9:47", "t": "καὶ ἐφώνησεν πᾶν τὸ πλῆθος Ἀμήν, ἀμήν· καὶ ἄραντες ἄνω τὰς χεῖρας προσπεσόντες ἐπὶ τὴν γῆν προσεκύνησαν τῷ θεῷ."}, {"sp": "N", "st": "1 Esd 9:48", "t": "Ἰησοῦς καὶ Ἀννιοὺθ καὶ Σαραβίας, Ἰάδεινος, Ἰαρσούβοος, Ἀβταῖος, Aὑταίας, Μαιάννας καὶ Καλείτας, Ἀζαρίας, Κατέθζαβδος, Ἅννιας, Φαλίας, οἱ Λευεῖται, (49)ἐδίδασκον τὸν νόμον Κυρίου, καὶ πρὸς τὸ πλῆθος ἀνεγίνωσκον τὸν νόμον τοῖ κυρίου, ἐμφυσιοῦντες ἅμα τὴν ἀνάγνωσιν."}, {"sp": "N", "st": "1 Esd 9:49", "t": "Καὶ εἶπεν Ἀτταρατὴ Ἔσρᾳ τῷ ἀρχιερεῖ καὶ ἀναγνώστῃ καὶ τοῖς Λευείταις τοῖς διδάσκουσι τὸ πλῆθος ἐπὶ πάντας"}, {"sp": "N", "st": "1 Esd 9:50", "t": "Ἡ ἡμέρα αὕτη ἐστὶν ἁγία τῷ κυρίῳ· καὶ πάντες ἔκλαιον ἐν τῷ ἀκοῦσαι τὸν νόμον·"}, {"sp": "N", "st": "1 Esd 9:51", "t": "βαδίσαντες οὖν φάγετε λιπάσματα καὶ ἀποστείλατε ἀποστολὰς τοῖς μὴ ἔχουσιν."}, {"sp": "N", "st": "1 Esd 9:52", "t": "ἁγία γὰρ ἡ ἡμέρα τῷ κυρίη, καὶ μὴ λυπεῖσθε· ὁ γὰρ κύριος δοξάσει ὑμᾶς."}, {"sp": "N", "st": "1 Esd 9:53", "t": "καὶ οἱ Λευεῖται ἐκέλευον τῷ δήμῳ πάντα λέγοντες Ἡ ἡμέρα αὕτη ἁγία, μὴ λυπεῖσθε."}, {"sp": "N", "st": "1 Esd 9:54", "t": "καὶ ᾤχοντο πάντες φαγεῖν καὶ πιεῖν καὶ εὐφραίνεσθαι, καὶ δοῦναι ἀποστολὰς τοῖς μὴ ἔχουσιν, καὶ εὐφρανθῆναι μεγάλως·"}, {"sp": "N", "st": "1 Esd 9:55", "t": "ὅτι καὶ ἐνεφυσιώθησαν ἐν τοῖς ῥήμασιν οἷς ἐδιδάχθησαν. καὶ ἐπισυνήχθησαν."}, {"sp": "HDR", "t": "The Second Book of Esdras"}, {"sp": "N", "t": "<i>No Greek text of this book is included. The Second Book of Esdras survives in Latin, not in Greek.</i>"}, {"sp": "HDR", "t": "ΤΩΒΕΙΤ"}, {"sp": "N", "st": "Tob 1:1", "t": "BΙBΛΟΣ λόγων Τωβεὶτ τοῦ Τωβιὴλ τοῦ Ἁνανιὴλ τοῦ Ἀδουὴλ τοῦ Γαβαήλ, ἐκ τοῦ σπέρματος Ἀσιήλ, ἐκ τῆς φυλῆς Νεφθαλείμ,"}, {"sp": "N", "st": "Tob 1:2", "t": "ὃς ᾐχμαλωτεύθη ἐν ἡμέραις Ἐνεμεσσάρου τοῦ βασιλέως Ἀσσυρίων ἐκ Θίσβης, ἥ ἐστιν ἐκ δεξιῶν Κυδιὼς τῆς Νεφθαλεὶμ ἐν τῇ Γαλειλαίᾳ ὑπεράνω Ἀσήρ."}, {"sp": "N", "st": "Tob 1:3", "t": "Ἐγὼ Τωβεὶτ ὁδοῖς ἀληθείας ἐπορευόμην καὶ δικαιοσύνῃ πάσας τὰς ἡμέρας τῆς ζωῆς μου. καὶ ἐλεημοσύνας πολλὰς ἐποίησα τοῖς ἀδελφοῖς μου καὶ τῷ ἔθνει τοῖς προπορευθεῖσιν μετ᾿ ἐμοῦ εἰς χώραν Ἀσσυρίων εἰς Νινευή."}, {"sp": "N", "st": "Tob 1:4", "t": "καὶ ὅτε ἤμην ἐν τῇ χώρᾳ μου ἐν τῇ γῇ Ἰσραήλ, νεωτέρου μου ὄντος, πᾶσα φυλὴ τοῦ Νεφθαλεὶμ τοῦ πατρός μου ἀπέστη ἀπὸ τοῦ οἴκου Ἰεροσολύμων, τῆς ἐκλεγείσης ἀπὸ πασῶν τῶν φυλῶν Ἰσραὴλ εἰς τὸ θυσιάζειν πάσας τὰς φυλάς· καὶ ἡγιάσθη ὁ ναὸς τῆς κατασκηνώσεως τοῦ ὑψίστου καὶ ᾠκοδομήθη εἰς πάσας τὰς γενεὰς τοῦ αἰῶνος·"}, {"sp": "N", "st": "Tob 1:5", "t": "καὶ πᾶσαι αἱ φυλαὶ αἱ συναποστᾶσαι ἔθυον τῇ Βάαλ τῇ δαμάλει, καὶ ὁ οἶκος Νεφθαλεὶμ τοῦ πατρός μου."}, {"sp": "N", "st": "Tob 1:6", "t": "κἀγὼ μόνος (⁶)ἐπορευόμην πλεονάκις ἐν Ἰεροσολύμοις ταῖς ἑορταῖς, καθὼς γέγραπται παντὶ τῷ Ἰσραὴλ ἐν προστάγματι αἰωνίῳ, τὰς ἀπαρχὰς καὶ τὰς δεκάτας τῶν γενημάτων καὶ τὰς προκουρίας ἔχων·"}, {"sp": "N", "st": "Tob 1:7", "t": "καὶ ἐδίδουν αὐτὰς τοῖς ἱερεῦσιν τοῖς υἱοῖς Ἀαρὼν πρὸς τὸ θυσιαστήριον τῶν γενημάτων· τὴν δεκάτην ἐδίδουν τοῖς υἱοῖς Λευεὶ τοῖς θεραπεύουσιν εἰς Ἰερουσαλήμ, καὶ τὴν δευτέραν δεκάτην ἀπεπρατιζόμην, καὶ ἐπορευόμην καὶ ἐδαπάνων αὐτὰ ἐν Ἰεροσολύμοις καθʼ ἕκαστον ἐνιαυτόν· ⁸καὶ τὴν τρίτην ἐδίδουν οἷς καθήκει, καθὼς ἐνετείλατο Δεββώρα ἡ μήτηρ τοῦ πατρός μου, διότι ὀρφανὸς κατελείφθην ὑπὸ τοῦ πατρός μου."}, {"sp": "N", "st": "Tob 1:9", "t": "καὶ ὅτε ἐγενόμην ἀνήρ, ἔλαβον Ἄνναν γυναῖκα ἐκ τοῦ σπέρματος τῆς πατριᾶς ἡμῶν, καὶ ἐγέννησα ἐξ αὐτῆς Τωβίαν."}, {"sp": "N", "st": "Tob 1:10", "t": "καὶ ὅτε ἠχμαλωτίσθημεν εἰς Νινευή, πάντες οἱ ἀδελφοί μου καὶ οἱ ἐκ τοῦ γένους ἤσθιον ἐκ τῶν ἄρτων τῶν ἐθνῶν·"}, {"sp": "N", "st": "Tob 1:11", "t": "ἐγὼ δὲ συνετήρησα τὴν ψυχήν μου μὴ φαγεῖν,"}, {"sp": "N", "st": "Tob 1:12", "t": "καθότι ἐμεμνήμην τοῦ θεοῦ ἐν ὅλῃ τῇ ψυχῇ μου."}, {"sp": "N", "st": "Tob 1:13", "t": "καὶ ἔδωκεν ὁ ὕψιστος χάριν καὶ μορφὴν ἐνώπιον Ἐνεμεσσάρου, καὶ ἤμην αὐτοῦ ἀγοραστής."}, {"sp": "N", "st": "Tob 1:14", "t": "ἐπορευόμην εἰς τὴν Μηδίαν, καὶ παρεθέμην Γαβαήλῳ τῷ ἀδελφῷ Γαβρία ἐν Ῥάγοις τῆς Μηδίας ἀργυρίρυ τάλαντα δέκα."}, {"sp": "N", "st": "Tob 1:15", "t": "Καὶ ὅτε ἀπέθανεν Ἐνεμεσσάρ, ἐβασίλευσεν Ἀχηρεὶλ ὁ υἱὸς αὐτοῦ ἀντʼ αὐτοῦ, καὶ αἱ ὁδοὶ αὐτοῦ ἠκαταστάτησαν καὶ οὐκέτι ἠδυνάσθην πορευθῆναι εἰς τὴν Μηδείαν."}, {"sp": "N", "st": "Tob 1:16", "t": "καὶ ἐν ταῖς ἡμέραις Ἐνεμεσσάρου ἐλεημοσύνας πολλὰς ἐποίουν τοῖς ἀδελφοῖς μου·"}, {"sp": "N", "st": "Tob 1:17", "t": "τοὺς ἄρτους μου ἐδίδουν τοῖς πεινῶσιν καὶ ἱμάτια τοῖς γυμνοῖς, καὶ εἵ τινα ἐκ τοῦ γένους μου ἐθεώρουν τεθνηκότα καὶ ῥεριμμένον ὀπίσω τοῦ τείχους Νινευή, ἔθαπτον αὐτόν."}, {"sp": "N", "st": "Tob 1:18", "t": "καὶ εἵ τινα ἀπέκτεινεν Ἀχηρεὶλ ὁ βασιλεύς, ὅτε ἦλθεν φεύγων ἐκ τῆς Ἰουδαίας, ἔθαψα αὐτοὺς κλέπτων· πολλοὺς γὰρ ἀπέκτεινεν ἐν τῷ θυμῷ αὐτοῦ· καὶ ἐζητήθη ὑπὸ τοῦ βασιλέως τὰ σώματα, καὶ οὐχ εὑρέθη."}, {"sp": "N", "st": "Tob 1:19", "t": "πορευθεὶς δὲ εἰς τῶν ἐν Νινευὴ ὑπέδειξε τῷ βασιλεῖ περὶ ἐμοῦ ὅτι θάπτω αὐτούς, καὶ ἐκρύβην· ἐπιγνοὺς δὲ ὅτι ζητοῦμαι ἀποθανεῖν, φοβηθεὶς ἀνεχώρησα."}, {"sp": "N", "st": "Tob 1:20", "t": "καὶ διηρπάγη πάντα τὰ ὑπάρχοντά μου, (23) καὶ οὐ κατελείφθη μοι οὐδὲν πλὴν Ἅννας τῆς γυναικός μου καὶ Τωβεὶτ τοῦ υἱοῦ μου."}, {"sp": "N", "st": "Tob 1:21", "t": "καὶ οὐ διῆλθον ἡμέραι πεντήκοντα ἕως οὗ ἀπέκτειναν αὐτὸυ οἱ δύο υἱοὶ αὐτοῦ, καὶ ἔφυγον εἰς τὰ ὄρη Ἀραράθ· καὶ ἐβασίλευσεν Σαχερδονὸς ὁ υἱὸς αὐτοῦ ἀντʼ αὐτοῦ, καὶ ἔταξεν Ἀχιάχαρον τὸν Ἀναὴλ υἱὸν τοῦ ἀδελφοῦ μου ἐπὶ πᾶσαυ τὴν ἐκλογιστείαν τῆς βασιλείας αὐτοῦ καὶ ἐπὶ πᾶσαν τὴν διοίκησιν."}, {"sp": "N", "st": "Tob 1:22", "t": "καὶ ἠξίωσεν Ἀχιάχαρος περὶ ἐμοῦ, καὶ ἦλθον εἰς Νινευή. Ἀχιάχαρος δὲ ἦν ὁ οἰνοχόος καὶ ἐπὶ τοῦ δακτυλίου καὶ διοικητὴς καὶ ἐκλογιστής, καὶ κατέστησεν αὐτὸν ὁ Σαχερδονός, υἱὸς ἐκ δευτέρας· ἦν δὲ ἐξάδελφός μου."}, {"sp": "N", "st": "Tob 2:1", "t": "Ὅτε δὲ κατῆλθον εἰς τὸν οἶκόν μου καὶ ἀπεδόθη μοι Ἅννα ἡ γυνὴ μου καὶ Τωβίας ὁ υἱός μου, ἐν τῇ πεντηκοστῇ ἑορτῇ ἥ ἐστιν ἁγία ἑπτὰ ἑβδομάδων, ἐγενήθη ἄριστον καλόν μοι· ἀνέπεσα τοῦ φαγεῖν."}, {"sp": "N", "st": "Tob 2:2", "t": "καὶ ἐθεασάμην ὄψα πολλά, καὶ εἶπα τῷ υἱῷ μου Βάδισον καὶ ἄγαγε ὃν ἐὰν εὕρῃς τῶν ἀδελφῶν ἡμῶν ἐνδεῆ ὃς μέμνηται τοῦ κυρίου, καὶ ἰδοὺ μένω σε."}, {"sp": "N", "st": "Tob 2:3", "t": "καὶ ἐλθὼν εἶπεν Πάτερ, εἰς ἐκ τοῦ γένους ἡμῶν ἐστραγγαλωμένος ἔρριπται ἐν τῇ ἀγορῷ."}, {"sp": "N", "st": "Tob 2:4", "t": "κἀγὼ πρὶν ἢ γεύσασθαί με ἀναπηδήσας (4)ἀνειλόμην αὐτὸν εἰς τι οἴκημα ἕως οὗ ἔδυ ὁ ἥλιος."}, {"sp": "N", "st": "Tob 2:5", "t": "καὶ ἐπιστρέψας ἐλουσάμην, καὶ ἤσθιον τὸν ἄρτον μου ἐν λύπῃ·"}, {"sp": "N", "st": "Tob 2:6", "t": "καὶ ἐμνήσθην τῆς προφητείας Ἀμώς, καθὼς εἶπεν Στραφήσονται αἱ ἑορταὶ ὑμῶν εἰς πένθος, καὶ πᾶσαι αἱ εὐφροσύναι ὑμῶν εἰς θρῆνον."}, {"sp": "N", "st": "Tob 2:7", "t": "καὶ ἔκλαυσα. (7)καὶ ὅτε ἔδυ ὁ ἥλιος. ᾠχόμην καὶ ὀρύξας ἔθαψα αὐτόν."}, {"sp": "N", "st": "Tob 2:8", "t": "καὶ οἱ πλησίον ἐπεγέλων λέγοντες Οὐκέτι φοβεῖται φονευθῆναι περὶ τοῦ πράγματος τούτου· καὶ ἀπέδρα, καὶ ἰδοὺ πάλιν θάπτει τοὺς νεκρούς."}, {"sp": "N", "st": "Tob 2:9", "t": "καὶ ἐν αὐτῇ τῇ νυκτὶ ἀνέλυσα θάψας, καὶ ἐκοιμήθην μεμιαμμένος παρὰ τὸν τοῖχον τῆς αὐλῆς, καὶ τὸ πρόσωπόν μου ἀκάλυπτον ἦν."}, {"sp": "N", "st": "Tob 2:10", "t": "καὶ οὐκ ᾔδειν ὅτι στρουθία ἐν τῷ τοίχῳ ἐστίν· καὶ τῶν ὀφθαλμῶν μου ἀνεῳγότων, ἀφώδευσαν τὰ στρουθία θερμὸν εἰς τοὺς ὀφθαλμούς μου, καὶ ἐγενήθη λευκώματα εἰς τοὺς ὀφθαλμούς μου· καὶ ἐπορεύθην πρὸς ἰατρούς, καὶ οὐκ ὠφέλησάν με· Ἀχιάχαρος δὲ ἔτρεφέν με ἕως οὗ ἐπορεύθην εἰς τὴν Ἐλλυμαίδα."}, {"sp": "N", "st": "Tob 2:11", "t": "Καὶ ἡ γυνή μου Ἅννα ἠριθεύετο ἐν τοῖς γυναικείοις·"}, {"sp": "N", "st": "Tob 2:12", "t": "καὶ ἀπέστελλε τοῖς κυρίοις, καὶ ἀπέδωκαν αὐτῇ καὶ αὐτοὶ τὸν μισθόν, προσδόντες καὶ ἔριφον."}, {"sp": "N", "st": "Tob 2:13", "t": "ὅτε δὲ ἦλθεν πρὸς μέ, ἤρξατο κράζειν· καὶ εἶπα αὐτῇ Πόθεν τὸ ἐρίφιον; μὴ κλεψιμαῖόν ἐστιν; ἀπόδος αὐτὸ τοῖς κυρίοις· οὐ γὰρ θεμιτόν ἐστιν φαγεῖν κλεψιμαῖον."}, {"sp": "N", "st": "Tob 2:14", "t": "ἡ δὲ εἶπεν Δῶρον δέδοταί μοι ἐπὶ τῷ μισθῷ. καὶ οὐκ ἐπίστευον αὐτῇ, καὶ ἔλεγον ἀποδιδόναι αὐτὸ τοῖς κυρίοις, καὶ ἠρυθρίων πρὸς αὐτήν· (²²)ἡ δὲ ἀποκριθεῖσα εἶπέν μοι Ποῦ εἰσιν αἱ ἐλεημοσύναι σου καὶ αἱ δικαιοσύναι σου; ἰδοὺ γνωστὰ πάντα μετὰ σοῦ."}, {"sp": "N", "st": "Tob 3:1", "t": "Καὶ λυπηθεὶς ἔκλαυσα, καὶ προσευξάμην μετʼ ὀδύνης (²)λέγων"}, {"sp": "N", "st": "Tob 3:2", "t": "Δίκαιος εἶ, Κύριε, καὶ πάντα τὰ ἔργα σου καὶ πᾶσαι αἱ ὁδοί σου ἐλεημοσύναι καὶ ἀλήθεια, καὶ κρίσιν ἀληθινὴν καὶ δικαίαν σὺ κρίνεις εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Tob 3:3", "t": "μνήσθητί μου καὶ ἐπίβλεψον ἐπʼ ἐμέ· μὴ ἐκδικῇς ταῖς ἁμαρτίαις μου καὶ τοῖς ἀγνοήμασίν μου καὶ τῶν πατέρων μου, ἃ ἥμαρτον ἐνώπιόν σου."}, {"sp": "N", "st": "Tob 3:4", "t": "παρήκουσαν γὰρ τῶν ἐντολῶν σου· ἔδωκας ἡμᾶς εἰς διαρπαγὴν καὶ αἰχμαλωσίαν καὶ θάνατον καὶ παραβολὴν ὀνειδισμοῦ πᾶσιν τοῖς ἔθνεσιν ἐν οἷς ἐσκορπίσμεθα."}, {"sp": "N", "st": "Tob 3:5", "t": "καὶ νῦν πολλαὶ αἱ κρίσεις σού εἰσιν ἀληθιναί, ἐξ ἐμοῦ ποιῆσαι περὶ τῶν ἁμαρτιῶν μου καὶ τῶν πατέρων μου, ὅτι οὐκ ἐποιήσαμεν τὰς ἐντολάς σου· οὐ γὰρ ἐπορεύθημεν ἐν ἀληθεία ἐνώπιόν σου."}, {"sp": "N", "st": "Tob 3:6", "t": "καὶ νῦν κατὰ τὸ ἀρεστόν σου ποίησον μετʼ ἐμοῦ· ἐπίταξον ἀναλαβεῖν τὸ πνεῦμά μου, ὅπως ἀπολυθῶ καὶ γένωμαι γῆ· διότι λυσιτελεῖ μοι ἀποθανεῖν ἡ ζῆν, ὅτι ὀνειδισμοὺς ψευδεῖς ἤκουσα, λύπη ἐστὶν πολλὴ ἐν ἐμοί ἐπίταξον ἀπολυθῆναί με τῆς ἀνάγκης δή εἰς τὸν αἰώνιον τόπον, μὴ ἀποστρέψῃς τὸ πρόσωπόν σου ἀπʼ ἐμοῦ."}, {"sp": "N", "st": "Tob 3:7", "t": "Ἐν τῇ αὐτῇ ἡμέρᾳ συνέβη τῇ θυγατρὶ Ῥαγουὴλ Σάρρᾳ ἐν Ἐκβατάνοις τῆς Μηδείας, καὶ ταύτην ὀνειδισθῆναι ὑπὸ παιδισκῶν πατρὸς αὐτῆς,"}, {"sp": "N", "st": "Tob 3:8", "t": "ὅτι ἦν δεδομένη ἀνδράσιν ἑπτά, καὶ Ἀσμόδαυς τὸ πονηρὸν δαιμόνιον ἀπέκτεινεν αὐτοὺς πρὶν ἢ γενέσθαι αὐτοὺς μετʼ αὐτῆς ὡς ἐν γυναιξίν· (9)καὶ εἶπαν αὐτῇ Οὐ συνίεις ἀποπνίγουσά σου τοὺς ἄνδρας; ἤδη ἑπτὰ ἔσχες. καὶ ἑνὸς αὐτῶν οὐκ ὠνάσθης."}, {"sp": "N", "st": "Tob 3:9", "t": "τί ἡμᾶς μαστιγοῖς; εἰ ἀπέθανον, βάδιζε μετʼ αὐτῶν· μὴ ἴδοιμέν σου υἱὸν ἡ θυγατέρα εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Tob 3:10", "t": "ταῦτα ἀκούσασα ἐλυπήθη σφόδρα ὥστε ἀπάγξασθαι· καὶ εἶπεν Μία μέν εἰμι τῷ πατρί μου· ἐὰν ποιήσω τοῦτο, ὄνειδος αὐτῷ ἔσται, καὶ τὸ γῆρας αὐτοῦ κατάξω μετʼ ὀδύνης εἰς ἄδου."}, {"sp": "N", "st": "Tob 3:11", "t": "καὶ ἐδεήθη πρὸς τῆ θυρίδι καὶ εἶπεν Εὐλογητὸς εἶ, Κύριε ὁ θεός μου, καὶ εὐλογητὸν τὸ ὄνομά σου τὸ ἅγιον καὶ ἔντιμον εἰς τοὺς αἰῶνας· εὐλογήσαισάν σε πάντα τὰ ἔργα σου εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Tob 3:12", "t": "καὶ νῦν, Κύριε, τοὺς ὀφθαλμούς μου καὶ τὸ πρόσωπόν μου εἰς σὲ δέδωκα."}, {"sp": "N", "st": "Tob 3:13", "t": "εἰπὸν ἀπολῦσαί με ἀπὸ τῆς γῆς καὶ μὴ ἀκοῦσαί με μηκέτι ὀνειδισμόν."}, {"sp": "N", "st": "Tob 3:14", "t": "σὺ γινώσκεις, Κύριε, ὅτι καθαρά εἰμι ἀπὸ πάσης ἁμαρτίας καὶ ἀνδρός,"}, {"sp": "N", "st": "Tob 3:15", "t": "καὶ οὐκ ἐμόλυνα τὸ ὄνομά μου οὐδὲ τὸ ὄνομα τοῦ πατρός μου ἐν τῇ γῇ τῆς αἰχμαλωσίας μου. μονογενής εἰμι τῷ πατρί μου, καὶ οὐχ ὑπάρχει αὐτῷ παιδίον ὃ κληρονομήσει αὐτόν, οὐδὲ ἀδελφὸς ἐγγὺς οὐδὲ ὑπάρχων αὐτῷ υἱὸς ἵνα συντηρήσω ἐμαυτὴν αὐτῷ γυναῖκα. ἤδη ἀπώλοντό μοι ἑπτά· ἵνα τί μοι ζῆν; καὶ εἰ μὴ δοκεῖ σοι ἀποκτεῖναί με, ἐπίταξον ἐπιβλέψαι ἐπʼ ἐμὲ καὶ ἐλεῆσαί με, καὶ μηκέτι ἀκοῦσαί με ὀνειδισμόν."}, {"sp": "N", "st": "Tob 3:16", "t": "Καὶ εἰσηκούσθη προσευχὴ ἀμφοτέρων ἐνώπιον τῆς δόξης τοῦ μεγάλου Ῥαφαήλ,"}, {"sp": "N", "st": "Tob 3:17", "t": "καὶ ἀπεστάλη ἰάσασθαι τοὺς δύο, τοῦ Τωβεὶτ λεπίσαι τὰ λευκώματα, καὶ Σάρραν τὴν τοῦ Ῥαγουὴλ δοῦναι Τωβίᾳ τῷ υἱῷ Τωβεὶτ γυναῖκα, καὶ δῆσαι Ἀσμόδαυν τὸ πονηρὸν δαιμόνιον, διότι Τωβίᾳ ἐπιβάλλει κληρονομῆσαι αὐτήν. ἐν αὐτῷ τῷ καιρῷ ἐπιστρέψας Τωβεὶτ εἰσῆλθεν εἰς τὸν οἶκον αὐτοῦ, καὶ Σάρρα ἡ τοῦ Ῥαγουὴλ κατέβη ἐκ τοῦ ὑπερῴου αὐτῆς."}, {"sp": "N", "st": "Tob 4:1", "t": "Ἐν τῇ ἡμέρᾳ ἐκείνῃ ἐμνήσθη Τωβεὶτ περὶ τοῦ ἀργυρίου οὗ παρέθετο Ταβαὴλ ἐν Ῥάγοις τῆς Μηδίας."}, {"sp": "N", "st": "Tob 4:2", "t": "καὶ εἶπεν ἐν ἑαυτῷ Ἐγὼ ᾐτησάμην θάνατον, τί οὐ καλῶ Τωβίαν τὸν υἱόν μου ἴνα αὐτῷ ὑποδείξω πρὶν ἀποθανεῖν με"}, {"sp": "N", "st": "Tob 4:3", "t": "καὶ καλέσας αὐτὸν εἶπεν Παιδίον, (3)ἐὰν ἀποθάνω θάψον με, καὶ μὴ ὑπερίδῃς τὴν μητέρα σου· τίμα αὐτὴν πάσας τὰς ἡμέρας τῆς ζωῆς σου, καὶ ποίει τὸ ἀρεστὸν αὐτῇ καὶ μὴ λυπήσῃς αὐτήν."}, {"sp": "N", "st": "Tob 4:4", "t": "μνήσθητι, παιδίον, ὅτι πολλοὺς κινδύνους ἑόρακεν ἐπὶ σοὶ ἐν τῇ κοιλίᾳ· (¹⁵)ὅταν ἀποθάνῃ, θάψον αὐτὴν παρʼ ἐμοὶ ἐν ἑνὶ τάφῳ."}, {"sp": "N", "st": "Tob 4:5", "t": "πάσας τὰς ἡμέρας. παιδίον, Κυρίου τοῦ θεοῦ ἡμῶν μνημόνευε· μὴ θελήσῃς παραβῆναι τὰς ἐντολὰς αὐτοῦ. δικαιοσύνην ποίει πάσας τὰς ἡμέρας τῆς ζωῆς σου, καὶ μὴ πορευθῇς ταῖς ὁδοῖς τῆς ἀδικίας."}, {"sp": "N", "st": "Tob 4:6", "t": "διότι ποιοῦντός σου τὴν ἀλήθειαν εὐοδίαι ἔσονται ἐν τοῖς ἔργοις σου καὶ πᾶσι τοῖς ποιοῦσι τὴν δικαιοσύνην."}, {"sp": "N", "st": "Tob 4:7", "t": "ἐκ τῶν ὑπαρχόντων σοι ποίει ἐλεημοσύνην, καὶ μὴ φθονεσάτω σου ὁ ὀφθαλμὸς ἐν τῷ ποιεῖν σε ἐλεημοσύνην· καὶ μὴ ἀποστρέψῃς τὸ πρόσωπόν σου ἀπὸ παντὸς πτωχοῦ, καὶ ἀπὸ σοῦ οὐ μὴ ἀποστραφῇ τὸ πρόσωπον τοῦ θεοῦ."}, {"sp": "N", "st": "Tob 4:8", "t": "ὡς σοὶ ὑπάρχει κατὰ τὸ πλῆθος, ποίησον ἐξ αὐτῶν ἐλεημοσύνην· ἐὰν ὀλίγον σοι ὑπάρχῃ, κατὰ τὸ ὀλίγον μὴ φοβοῦ ποιεῖν ἐλεημοσύνην."}, {"sp": "N", "st": "Tob 4:9", "t": "θέμα γὰρ ἀγαθὸν θησαυρίζεις σεαυτῷ εἰς ἡμέραν ἀνάγκης."}, {"sp": "N", "st": "Tob 4:10", "t": "διότι ἐλεημοσύνη ἐκ θανάτου ῥύεται, καὶ οὐκ ἐάσει ἐλθεῖν εἰς τὸ σκότος."}, {"sp": "N", "st": "Tob 4:11", "t": "δῶρον γὰρ ἀγαθόν ἐστιν ἐλεημοσύνη πᾶσι τοῖς ποιοῦσιν αὐτὴν ἐνώπιον τοῦ ὑψίστου."}, {"sp": "N", "st": "Tob 4:12", "t": "πρόσεχε σεαυτῷ, παιδίον, ἀπὸ πάσης πορνείας, καὶ γυναῖκα πρῶτον λάβε ἀπὸ τοῦ σπέρματος τῶν πατέρων σου· μὴ λάβῃς γυναῖκα ἀλλοτρίαν ἣ οὐκ ἔστιν ἐκ τῆς φυλῆς τοῦ πατρός σου, διότι υἱοὶ προφητῶν ἐσμεν. Νῶε, Ἀβραάμ, Ἰσαάκ, Ἰακώβ, οἱ πατέρες ἡμῶν ἀπὸ τοῦ αἰῶνος, μνήσθητι, παιδίον, ὅτι αὐτοὶ πάντες ἔλαβον γυναῖκας ἐκ τῶν ἀδελφῶν αὐτῶν, καὶ εὐλογήθησαν ἐν τοῖς τέκνοις αὐτῶν, καὶ τὸ σπέρμα αὐτῶν κληρονομήσει γῆν."}, {"sp": "N", "st": "Tob 4:13", "t": "καὶ νῦν, παιδίον, ἀγάπα τοὺς ἀδελφούς σου, (14)καὶ μὴ ὑπερηφανεύου τῇ καρδίᾳ σου ἀπὸ τῶν ἀδελφῶν σου καὶ τῶν υἱῶν καὶ θυγατέρων τοῦ λαοῦ σου, λαβεῖν σεαυτῷ ἐξ αὐτῶν γυναῖκα. διότι ἐν τῇ ὑπερηφανίᾳ ἀπωλία καὶ ἀκαταστασία πολλή, καὶ ἐν τῇ ἀχρεότητι ἐλάττωσις καὶ ἔνδεια μεγάλη· ἡ γὰρ ἀχρεότης μήτηρ ἐστὶν τοῦ λιμοῦ."}, {"sp": "N", "st": "Tob 4:14", "t": "μισθὸς παντὸς ἀνθρώπου ὃς ἐὰν ἐργάσηται παρὰ σοὶ μὴ αὐλισθήτω, ἀλλὰ ἀπόδος αὐτῷ παραυτίκα· ἐὰν δουλεύσῃς τῷ θεῷ, ἀποδοθήσεταί σοι. πρόσεχε σεαυτῷ, παιδίον, ἐν πᾶσι τοῖς ἔργοις σου, καὶ ἴσθι πεπαιδευμένος ἐν πάσῃ ἀναστροφῇ σου."}, {"sp": "N", "st": "Tob 4:15", "t": "καὶ ὁ μισεῖς μηδενὶ ποιήσῃς. οἶνον εἰς μέθην μὴ πίῃς. καὶ μὴ πορευθήτω μετὰ σοῦ μέθη ἐν τῇ ὁδῷ σου."}, {"sp": "N", "st": "Tob 4:16", "t": "ἐκ τοῦ ἄρτου σου δίδου πεινῶντι, καὶ ἐκ τῶν ἱματίων σου τοῖς γυμνοῖς· πᾶυ ὃ ἐὰν περισσεύσῃ σοι ποίει ἐλεημοσύνην, καὶ μὴ φθονεσάτω σου ὁ ὀφθαλμὸς ἐν τῷ ποιεῖν σε ἐλεημοσύνην."}, {"sp": "N", "st": "Tob 4:17", "t": "ἔκχεον τοὺς ἄρτους σου ἐπὶ τὸν τάφον τῶν δικαίων, καὶ μὴ δῷς τοῖς ἁμαρτωλοῖς."}, {"sp": "N", "st": "Tob 4:18", "t": "συμβουλίαν παρὰ παντὸς φρονίμου ζήτησον, καὶ μὴ καταφρονήσῃς ἐπὶ πάσης συμβουλίας χρησίμης."}, {"sp": "N", "st": "Tob 4:19", "t": "καὶ ἐν παντὶ καιρῷ εὐλόγει Κύριον τὸν θεόν, καὶ παρʼ αὐτοῦ αἴτησον ὅπως αἱ ὁδοί σου εὐθεῖαι γένωνται καὶ πᾶσαι αἱ τρίβοι καὶ βουλαὶ εὐοδωθῶσιν. διότι πᾶν ἔθνος οὐκ ἔχει βουλήν, ἀλλὰ αὐτὸς ὁ κύριος δίδωσιν πάντα τὰ ἀγαθὰ καὶ ὃ ἐὰν θέλῃ ταπεινοῖ, καθὼς βούλονται. καὶ νῦν, παιδίον, μνημόνευε τῶν ἐντολῶν μου, καὶ μὴ ἐξαλειφθήτωσαν ἐκ τῆς καρδίας σου."}, {"sp": "N", "st": "Tob 4:20", "t": "καὶ νῦν ἐπιδεικνύω σοι τὰ δέκα τάλαντα τοῦ ἀργυρίου ἃ παρεθέμην Γαβαήλῳ τῷ τοῦ Γαβρεία ἐν Ῥάγοις τῆς Μηδείας."}, {"sp": "N", "st": "Tob 4:21", "t": "καὶ μὴ φοβοῦ, παιδίον, ὅτι ἐπτωχεύσαμεν· ὑπάρχει σοι πολλά, ἐὰν φοβηθῇς τὸν θεὸν καὶ ἀποστῇς ἀπὸ πάσης ἁμαρτίας καὶ ποιήσῃς τὸ ἀρεστὸν ἐνώπιον αὐτοῦ."}, {"sp": "N", "st": "Tob 5:1", "t": "Καὶ ἀποκριθεὶς Tωβίας εἶπεν αὐτῷ Πάτερ, ποιήσω πάντα ὅσα ἐντέταλσαί μοι."}, {"sp": "N", "st": "Tob 5:2", "t": "ἀλλὰ πῶς δυνήσομαι λαβεῖν τὸ ἀργύριον, καὶ οὐ γινώσκω αὐτόν ;"}, {"sp": "N", "st": "Tob 5:3", "t": "καὶ ἔδωκεν αὐτῷ τὸ χειρόγραφον, καὶ εἶπεν αὐτῷ (⁴)Zήτησον σεαυτῷ ἄνθρωπον ὃς συμπορεύσεταί σοι, καὶ δώσω αὐτῷ μισθὸν ἕως ζῶ, καὶ λάβε πορευθεὶς τὸ ἀργύριον."}, {"sp": "N", "st": "Tob 5:4", "t": "καὶ ἐπορεύθη ζητῆσαι ἄνθρωπον, καὶ εὗρεν Ῥαφαὴλ ὃς ἦν ἄγγελος, καὶ οὐκ ἤδει·"}, {"sp": "N", "st": "Tob 5:5", "t": "καὶ εἶπεν αὐτῷ Εἰ δύναμαι πορευθήναι μετὰ σοῦ ἐν Ῥάγοις τῆς Μηδείας, καὶ εἰ ἔμπειρος εἶ τῶν τόπων ;"}, {"sp": "N", "st": "Tob 5:6", "t": "καὶ εἶπεν αὐτῷ ὁ ἄγγελος Πορεύσομαι μετὰ σοῦ, καὶ τῆς ὁδοῦ ἐμπειρῶ, καὶ παρὰ Γαβαὴλ τὸν ἀδελφὸν ἡμῶν ηὐλίσθην."}, {"sp": "N", "st": "Tob 5:7", "t": "καὶ εἶπεν αὐτῷ Τωβίας Ὑπόμεινον με, καὶ ἐρῶ τῷ πατρί."}, {"sp": "N", "st": "Tob 5:8", "t": "καὶ εἶπεν αὐτῷ Πορεύου καὶ μὴ χρονίσῃς."}, {"sp": "N", "st": "Tob 5:9", "t": "Καὶ εἰσελθὼν εἶπεν τῷ πατρί Ἰδοὺ εὕρηκα ὃς συνπορεύσεταί μοι. ὁ δὲ εἶπεν Φώνησον αὐτὸν πρὸς μέ, ἵνα ἐπιγνῶ ποίας φυλῆς ἐστιν, καὶ εἰ πιστὸς τοῦ πορευθῆναι μετὰ σοῦ."}, {"sp": "N", "st": "Tob 5:10", "t": "καῑ ἐκάλεσεν αὐτόν· καὶ εἰσῆλθεν, καὶ ἠσπάσαντο ἀλλήλους."}, {"sp": "N", "st": "Tob 5:11", "t": "καὶ εἶπεν αὐτῷ Τωβείτ Ἀδελφέ, ἐκ ποίας φυλῆς καὶ ἐκ ποίας πατρίδος σὺ εἶ; ὑπόδειξόν μοι."}, {"sp": "N", "st": "Tob 5:12", "t": "καὶ εἶπεν αὐτῷ Φυλὴν καὶ πατριὰν σὺ ζητεῖς, ἢ μίσθιον ὃς συμπορεύσεται μετὰ τοῦ υἱοῦ σου; καὶ εἶπεν αὐτῷ Τωβείτ Βούλομαι, ἀδελφέ, ἐπιγνῶναι τὸ γένος σου καὶ τὸ ὄνομα."}, {"sp": "N", "st": "Tob 5:13", "t": "ὃς δὲ εἶπεν Ἐγὼ Ἀζαρίας Ἀνανίου τοῦ μεγάλου, τῶν ἀδελφῶν σου."}, {"sp": "N", "st": "Tob 5:14", "t": "καὶ εἶπεν αὐτῷ Ὑγιαίνων ἔλθοις, ἀδελφέ· καὶ μὴ μοι ὀργισθῇς ὅτι ἐζήτησα τὴν φυλὴν σου καὶ τὴν πατριάν σου ἐπιγνῶναι. καὶ σὺ τυγχάνεις ἀδελφός μου ἐκ τῆς καλῆς καὶ ἀγαθῆς γενεᾶς· ἐπεγίνωσκον γὰρ ἐγὼ Ἀνανίαν καὶ Ἰαθὰν τοὺς υἱοὺς Σεμεοῦ τοῦ μεγάλου, ὡς ἐπορευόμεθα κοινῶς εἰς Ἰεροσόλυμα προσκυνεῖν, ἀναφέροντες τὰ πρωτότοκα καὶ τὰς δεκάτας τῶν γενημάτων, καὶ οὐκ ἐπλανήθησαν ἐν τῇ πλάνῃ τῶν ἀδελφῶν ἡμῶν· ἐκ ῥίζης καλῆς εἶ. ἀδελφέ."}, {"sp": "N", "st": "Tob 5:15", "t": "ἀλλ᾿ εἰπόν μοι τίνα σοι ἔσομαι μισθὸν διδόναι; δραχμὴν τῆς ἡμέρας καὶ τὰ δέοντά σοι ὡς καὶ τῷ υἱῷ μου;"}, {"sp": "N", "st": "Tob 5:16", "t": "καὶ ἔτι προσθήσω σοι ἐπὶ τὸν μισθόν, ἐὰν ὑγιαίνοντες ἐπιστρέψητε."}, {"sp": "N", "st": "Tob 5:17", "t": "εὐδόκησαν οὕτως· καὶ εἶπεν πρὸς Τωβίαν Ἕτοιμος γίνου πρὸς τὴν ὁδόν· καὶ εὐοδωθείητε. καὶ ἡτοίμασεν ὁ υἱὸς αὐτοῦ τὰ πρὸς τὴν ὁδόν· καὶ εἶπεν αὐτῷ ὁ πατὴρ αὐτοῦ Πορεύου μετὰ τοῦ ἀνθρώπου· ὁ δὲ ἐν τῷ οὐρανῷ οἰκῶν θεὸς εὐοδώσει τὴν ὁδὸν ὑμῶν, καὶ ὁ ἄγγελος αὐτοῦ συνπορευθήτω ὑμῖν. καὶ ἐξῆλθαν ἀμφότεροι ἀπελθεῖν, καὶ ὁ κύων τοῦ παιδαρίου μετʼ αὐτῶν."}, {"sp": "N", "st": "Tob 5:18", "t": "Ἔκλαυσεν δὲ Ἄννα ἡ μήτηρ αὐτοῦ, καὶ εἶπεν πρὸς Γωβείτ Τί ἐξαπέστειλας τὸ παιδίον ἡμῶν ; ἤ οὐχὶ ἡ ῥάβδος τῆς χειρὸς ἡμῶν ἐστιν ἐν τῷ εἰσπορεύεσθαι αὐτὸν καὶ ἐκπορεύεσθαι ἐνώπιον ἡμῶν;"}, {"sp": "N", "st": "Tob 5:19", "t": "ἀργύριον τῷ ἀργυρίῳ μὴ φθάσαι, ἀλλὰ περίψημα τοῦ παιδίου ἡμῶν γένοιτο."}, {"sp": "N", "st": "Tob 5:20", "t": "ὡς γὰρ δέδοται ἡμῖν ζῆν παρὰ τοῦ κυρίου, τοῦτο ἱκανὸν ἡμῖν ὑπάρχει."}, {"sp": "N", "st": "Tob 5:21", "t": "καὶ εἶπεν αὐτῇ Τωβείτ Μὴ λόγον ἔχε, ἀδελφή· ὑγιαίνων ἐλεύσεται, καὶ οἱ ὀφθαλμοί σου ὄψονται αὐτόν."}, {"sp": "N", "st": "Tob 5:22", "t": "ἄγγελος γὰρ ἀγαθὸς συνπορεύσεται αὐτῷ, καὶ εὐοδωθήσεται ἡ ὁδὸς αὐτοῦ, καὶ ὑποστρέψει ὑγιαίνων."}, {"sp": "N", "st": "Tob 6:1", "t": "καὶ ἐπαύσατο κλαίουσα."}, {"sp": "N", "st": "Tob 6:2", "t": "Οἱ δὲ πορευόμενοι τὴν ὁδὸν ἦλθον ἑσπέρας ἐπὶ τὸν Τίγριν ποταμόν, καὶ ηὐλίζοντο ἐκεῖ"}, {"sp": "N", "st": "Tob 6:3", "t": "τὸ δὲ παιδάριον κατέβη περικλύσασθαι, καὶ ἀνεπήδησεν ἰχθὺς ἀπὸ τοῦ ποταμοῦ καὶ ἐβουλήθη καταπεῖν τὸ παιδάριον."}, {"sp": "N", "st": "Tob 6:4", "t": "ὁ δὲ ἄγγελος εἶπεν αὐτῷ Ἐπιλαβοῦ τοῦ ἰχθύος· καὶ ἐκράτησεν τὸν ἰχθὺν τὸ παιδάριον, καὶ ἀνέβαλεν αὐτὸν ἐπὶ τὴν γῆν."}, {"sp": "N", "st": "Tob 6:5", "t": "καὶ εἶπεν αὐτῷ ὁ ἄγγελος Ἀνάτεμε τὸν ἰχθύν, καὶ λαβὼν τὴν καρδίαν καὶ τὸ ἧπαρ καὶ τὴν χολὴν θὲς ἀσφαλῶς."}, {"sp": "N", "st": "Tob 6:6", "t": "καὶ ἐποίησεν τὸ παιδάριον ὡς εἶπεν αὐτῷ ὁ ἄγγελος, τὸν δὲ ἰχθὺν ὀπτήσαντες ἔφαγον· καὶ ὥδευον ἀμφότεροι ἕως ἤγγισαν ἐν Ἐκβατάνοις."}, {"sp": "N", "st": "Tob 6:7", "t": "καὶ εἶπεν τὸ παιδάριον τῷ ἀγγέλῳ Ἀζαρία ἀδελφέ, τί ἐστιν τὸ ἧπαρ καὶ ἡ καρδία καὶ ἡ χολὴ τοῦ ἰχθύος;"}, {"sp": "N", "st": "Tob 6:8", "t": "καὶ εἶπεν αὐτῷ Ἡ καρδία καὶ τὸ ἧπαρ, ἐάν τινα ὀχλῇ δαιμόνιον ἢ πνεῦμα πονηρόν· ταῦτα δὲ καπνίσαι ἐνώπιον ἀνθρώπου ἢ γυναικός, καὶ οὐ μηκέτι ὀχληθῇ."}, {"sp": "N", "st": "Tob 6:9", "t": "ἡ δὲ χολὴ ἐνχρῖσαι ἄνθρωπον ὃς ἔχει λευκώματα ἐν τοῖς ὀφθαλμοῖς, καὶ ἰαθήσεται."}, {"sp": "N", "st": "Tob 6:10", "t": "Ὡς δὲ προσήγγισαν τῇ Ῥάγῃ,"}, {"sp": "N", "st": "Tob 6:11", "t": "εἶπεν ὁ ἄγγελος τῷ παιδαρίῳ Ἀδελφέ, σήμερον αὐλισθησόμεθα παρὰ Ῥαγουηλῷ· καὶ αὐτὸς συγγενής σού ἐστιν, καὶ ἔστιν αὐτῷ θυγάτηρ ὀνόματι Σάρρα."}, {"sp": "N", "st": "Tob 6:12", "t": "λαλήσω περὶ αὐτῆς τοῦ δοθῆναί σοι αὐτὴν εἰς γυναῖκα, ὅτι σοὶ ἐπιβάλλει ἡ κληρονομία αὐτῆς, καὶ σὺ μόνος εἶ ἐκ τοῦ γένους αὐτῆς· καὶ τὸ κοράσιον καλὸν καὶ φρόνιμόν ἐστιν."}, {"sp": "N", "st": "Tob 6:13", "t": "καὶ νῦν ἄκουσόν μου καὶ λαλήσω τῷ πατρὶ αὐτῆς, καὶ ὅταν ὑποστρέψαμεν ἐκ Ῥάγων, ποιήσωμεν τὸν γάμον. διότι ἐπίσταμαι Ῥαγουὴλ ὅτι οὐ μὴ δῷ αὐτὴν. ἀνδρὶ ἑτέρῳ κατὰ τὸν νόμον Μωυσῆ, ἢ ὀφειλέσει θάνατον, ὅτι τὴν κληρονομίαν σοὶ καθήκει λαβεῖν ἢ πάντα ἄνθρωπον."}, {"sp": "N", "st": "Tob 6:14", "t": "τότε εἶπεν τὸ παιδάριον τῷ ἀγγέλῳ Ἀζαρία ἀδελφέ, ἀκήκοα ἐγὼ τὸ κοράσιον δεδόσθαι ἑπτὰ ἀνδράσιν, καὶ πάντας ἐν τῷ νυμφῶνι ἀπολωλότας."}, {"sp": "N", "st": "Tob 6:15", "t": "καὶ νῦν ἐγὼ μόνος εἰμὶ τῷ πατρί, καὶ φοβοῦμαι μὴ εἰσελθὼν ἀποθάνω καθὼς καὶ οἱ πρότεροι, ὅτι δαιμόνιον φιλεῖ αὐτὴν ὃ οὐκ ἀδικεῖ οὐδένα πλὴν τῶν προσαγόντων αὐτῇ. καὶ νῦν ἐγὼ φοβοῦμαι μὴ ἀποθάνω, καὶ κατάξω τὴν ζωὴν τοῦ πατρός μου καὶ τῆς μητρός μου μετʼ ὀδύνης ἐπʼ ἐμοὶ εἰς τὸν τάφον αὐτῶν· καὶ υἱὸς ἕτερος οὐχ ὑπάρχει αὐτοῖς ὃς θάψει αὐτούς."}, {"sp": "N", "st": "Tob 6:16", "t": "εἶπεν δὲ αὐτῷ ὁ ἄγγελος Οὐ μέμνησαι τῶν λόγων ὧν ἐνετείλατό σοι ὁ πατήρ σου ὑπέρ τοῦ λαβεῖν σε γυναῖκα ἐκ τοῦ γένους σου; καὶ νῦν ἄκουσόν μου, ἀδελφέ, | διότι σοὶ ἔσται εἰς γυναῖκα, καὶ τοῦ δαιμονίου μηδένα λόγον ἔχε, ὅτι τὴν νύκτα ταύτην δοθήσεταί σοι αὕτη εἰς γυναῖκα."}, {"sp": "N", "st": "Tob 6:17", "t": "καὶ ἐὰν εἰσέλθῃς εἰς τὸν νυμφῶνα, λήμψῃ τέφραν θυμιαμάτων καὶ ἐπιθήσεις ἀπὸ τῆς καρδίας καὶ τοῦ ἥπατος τοῦ ἰχθύος· καὶ καπνίσεις,"}, {"sp": "N", "st": "Tob 6:18", "t": "καὶ ὀσφρανθήσεται τὸ δαιμόνιον καὶ φεύξεται, καὶ οὐκ ἐπανελεύσεται τὸν αἰῶνα τοῦ αἰῶνος. ὅταν δὲ προσπορεύῃ αὐτῇ, ἐγέρθητε ἀμφότεροι καὶ βοήσατε πρὸς τὸν ἐλεήμονα θεόν, καὶ σώσει ὑμᾶς καὶ ἐλεήσει. μὴ φοβοῦ, ὅτι σοὶ αὕτη ἡτοιμασμένη ἦν ἀπὸ τοῦ αἰῶνος, καὶ σὺ αὐτὴν σώσεις, καὶ πορεύσεται μετὰ σοῦ, καὶ ὑπολαμβάνω ὅτι σοὶ ἔσται ἐξ αὐτῆς παιδία. καὶ ὡς ἤκουσεν Τωβίας ταῦτα, ἐφίλησεν αὐτήν, καὶ ἡ ψυχὴ αὐτοῦ ἐκολλήθη αὐτῇ σφόδρα."}, {"sp": "N", "st": "Tob 7:1", "t": "Καὶ ἦλθεν εἰς Ἐκβάτανα *καὶ παρεγένετο εἰς τὴν οἰκίαν Ῥαγουήλ, καὶ Σάρρα δὲ ὑπήντησεν αὐτῷ· καὶ ἐχαιρέτισεν αὐτὸν καὶ αὐτὸς αὐτούς. καὶ εἰσήγαγεν αὐτοὺς εἰς τὴν οἰκίαν."}, {"sp": "N", "st": "Tob 7:2", "t": "καὶ εἶπεν Ἔδνᾳ τῇ γυναικὶ αὐτοῦ Ὡς ὅμοιος ὁ νεανίσκος Τωβεὶτ τῷ ἀνεψιῷ μου."}, {"sp": "N", "st": "Tob 7:3", "t": "καὶ ἠρώτησεν αὐτοὺς Ῥαγουὴλ Πόθεν ἐστέ, ἀδελφοί; καὶ εἶπαν αὐτῷ Ἐκ τῶν υἱῶν Νεφθαλεὶ τῶν αἰχμαλώτων ἐκ Νινευή."}, {"sp": "N", "st": "Tob 7:4", "t": "καὶ εἶπεν αὐτοῖς Γινώσκετε Τωβεὶτ τὸν ἀδελφὸν ἡμῶν;"}, {"sp": "N", "st": "Tob 7:5", "t": "οἱ δὲ εἶπαν Καὶ ζῇ καὶ ὑγιαίνει. καὶ εἶπεν Τωβίας Πατήρ μού ἐστιν."}, {"sp": "N", "st": "Tob 7:6", "t": "καὶ ἀνεπήδησεν Ῥαγουήλ, καὶ κατεφίλησεν αὐτὸν καὶ ἔκλαυσε·"}, {"sp": "N", "st": "Tob 7:7", "t": "καὶ εὐλόγησεν αὐτὸν καὶ εἶπεν αὐτῷ Ὁ τοῦ καλοῦ καὶ ἀγαθοῦ ἀνθρώπου· καὶ ἀκούσας ὅτι Τωβεὶτ ἀπώλεσεν τοὺς ὀφθαλμοὺς ἑαυτοῦ, ἐλυπήθη καὶ ἔκλαυσεν."}, {"sp": "N", "st": "Tob 7:8", "t": "καὶ Ἔδνα ἡ γυνὴ αὐτοῦ καὶ Σάρρα ἡ θυγάτηρ αὐτοῦ ἔκλαυσαν· καὶ ὑπεδέξαντο αὐτοὺς προθύμως."}, {"sp": "N", "st": "Tob 7:9", "t": "καὶ ἔθυσαν κριὸν προβάτων, καὶ παρέθηκαν ὄψα πλείονα. (10)Εἶπεν δὲ Τωβείας τῷ Ῥαφαήλ Ἀζαρία ἀδελφέ, λάλησου ὑπὲρ ὧν ἔλεγες ἐν τῇ πορεία, καὶ τελεσθήτω τὸ πρᾶδγμα."}, {"sp": "N", "st": "Tob 7:10", "t": "καὶ μετέδωκεν τὸν λόγον τῷ Ῥαγουήλ. καὶ εἶπεν Ῥαγουὴλ πρὸς Τωβείαν Φάγε, πίε καὶ ἡδέως γίνου, σοὶ γὰρ καθήκει τὸ παιδίον μου λαβεῖν· πλὴν ὑποδείξω τὴν ἀλήθειαν."}, {"sp": "N", "st": "Tob 7:11", "t": "ἔδωκα τὸ παιδίον μου ἑπτὰ ἀνδράσιν, καὶ ὁπότε ἐὰν εἰσεπορεύοντο πρὸς αὐτήν, ἀπέθνησκον ὑπὸ νύκτα. ἀλλὰ τὸ νῦν ἔχων ἡδέως γίνου. καὶ εἶπεν Τωβίας Οὐ γεύομαι οὐδὲν ὧδε ἕως ἂν στήσητε καὶ σταθῆτε πρὸς μέ. καὶ εἶπεν Ῥαγουήλ Κομίζου αὐτὴν ἀπὸ τοῦ νῦν κατὰ τὴν κρίσιν· οὺ δὲ ἀδελφὸς εἶ αὐτῆς, καὶ αὐτή σού ἐστιν· ὁ δὲ ἐλεήμων θεὸς εὐοδώσει ὑμῖν τὰ κάλλιστα."}, {"sp": "N", "st": "Tob 7:12", "t": "καὶ ἐκάλεσεν Σάρραν τὴν θυγατέρα αὐτοῦ, καὶ λαβὼν τῆς χειρὸς αὐτῆς παρέδωκεν αὐτὴν Τωβείᾳ γυναίκα, καὶ εἶπεν Ἰδοὺ κατὰ τὸν νόμον Μωυσέως κομίζου αὐτὴν καὶ ἄπαγε πρὸς τὸν πατέρα σου· καὶ εὐλόγησεν αὐτοὺς."}, {"sp": "N", "st": "Tob 7:13", "t": "καὶ ἐκάλεσεν Ἔδναν τὴν γυναῖκα αὐτοῦ· (1⁶)καὶ λαβὼν βιβλίον ἔγραψεν συνγραφὴν καὶ ἐσφραγίσαντο."}, {"sp": "N", "st": "Tob 7:14", "t": "καὶ ἤρξαντο ἐσθίειν."}, {"sp": "N", "st": "Tob 7:15", "t": "καὶ ἐκάλεσεν Ῥαγουὴλ Ἔδναν τὴν γυναῖκα αὐτοῦ καὶ εἶπεν αὐτῇ Ἀδελφή, ἑτοίμασον τὸ ἕτερον ταμεῖον καὶ εἴσαγε αὐτήν."}, {"sp": "N", "st": "Tob 7:16", "t": "καὶ ἐποίησεν ὡς εἶπεν καὶ εἰσήγαγεν αὐτὴν ἐκεῖ, καὶ ἔκλαυσεν· καὶ ἀπέδέξατο τὰ δάκρυα τῆς θυγατρὸς αὐτῆς (20)καὶ εἶπεν αὐτῇ"}, {"sp": "N", "st": "Tob 7:17", "t": "Θάρσει, τέκνον, ὁ κύριος τοῦ οὐρανοῦ καὶ τῆς γῆς δώῃ σοι χάριν ἀντὶ τῆς λύπης σου ταύτης· θάρσει, θύγατερ."}, {"sp": "N", "st": "Tob 8:1", "t": "Ὅτε δὲ συνετέλεσαν δειπνοῦντες, εἰσήγαγον Τωβείαν πρὸς αὐτήν."}, {"sp": "N", "st": "Tob 8:2", "t": "ὁ δὲ πορευομενος ἐμνήσθη τῶν λόγων Ῥαφαήλ, καὶ ἔλαβεν τὴν τέφραν τῶν θυμιαμάτων καὶ ἐπέθηκεν τὴν καρδίαν τοῦ ἰχθύος καὶ τὸ ἦπαρ, καὶ ἐκάπνισεν."}, {"sp": "N", "st": "Tob 8:3", "t": "ὅτε δὲ ὠσφράνθη τὸ δαιμόνιον τῆς ὀσμῆς, ἔφυγεν εἰς τὰ ἀνώτατα Αἰγύπτου, καὶ ἔδησεν αὐτὸ ὁ ἄγγελος."}, {"sp": "N", "st": "Tob 8:4", "t": "ὡς δὲ συνεκλείσθησαν ἀμφότεροι, ἀνέστη Τωβείας ἀπὸ τῆς κλίνης καὶ εἶπεν Ἀνάστηθι, ἀδελφή, καὶ προσευξώμεθα ἴνα ἡμᾶς ἐλεήσῃ ὁ κύριος."}, {"sp": "N", "st": "Tob 8:5", "t": "καὶ ἤρξατο Τωβίας λέγειν Εὐλογητὸς εἶ ὁ θεὸς τῶν πατέρων ἡμῶν, καὶ εὐλογητὸν τὸ ὄνομά σου τὸ ἅγιον καὶ ἔνδοξον εἰς τοὺς αἰῶνας· εὐλογησάτωσάν σε οἱ οὐρανοὶ καὶ πᾶσαι αἱ κτίσεις σου."}, {"sp": "N", "st": "Tob 8:6", "t": "σὺ ἐποίησας Ἀδάμ, καὶ ἔδωκας αὐτῷ βοηθὸν Εὕαν στήριγμα τὴν γυναῖκα αὐτοῦ· ἐκ τούτων ἐγενήθη τὸ ἀνθρώπων, σπέρμα. σὺ εἶπας Οὐ καλὸν εἶναι τὸν ἄνθρωπον μόνον, ποιήσωμεν αὐτῷ βοηθὸν ὅμοιον αὐτῷ."}, {"sp": "N", "st": "Tob 8:7", "t": "καὶ νῦν, Κύριε, οὐ διὰ πορνείαν ἐγὼ λαμβάνω τὴν ἀδελφὴν μου ταύτην, ἀλλ᾿ ἐπ᾿ ἀληθείας· ἐπίταξον ἐλεῆσαί με καὶ αὐτῇ συνκαταγηρᾶσαι."}, {"sp": "N", "st": "Tob 8:8", "t": "καὶ εἶπεν μετʼ αὐτοῦ Ἀμήν."}, {"sp": "N", "st": "Tob 8:9", "t": "καὶ ἐκοιμήθησαν ἀμφότεροιτὴν νύκτα. (¹¹)Καὶ ἀναστὰς Ῥαγουὴλ ἐπορεύθη καὶ ὤρυξεν τάφον,"}, {"sp": "N", "st": "Tob 8:10", "t": "λέγων Μὴ καὶ οὗτος ἀποθάνῃ."}, {"sp": "N", "st": "Tob 8:11", "t": "καὶ ἦλθεν Ῥαγουὴλ εἰς τὴν οἰκίαν ἑαυτοῦ,"}, {"sp": "N", "st": "Tob 8:12", "t": "καὶ εἶπεν Ἔδνᾳ τῇ γυναικὶ αὐτοῦ (¹⁴)Ἀπόστειλον μίαν τῶν παιδισκῶν, καὶ εἰδέτωσαν εἰ ζῇ· εἰ δὲ μή, ἵνα θάψωμεν αὐτὸν καὶ μηδεὶς γνῷ."}, {"sp": "N", "st": "Tob 8:13", "t": "καὶ εἰσῆλθεν ἡ παιδίσκη ἀνοἰξασα τὴν θύραν. καὶ εὗρεν τοὺς δύο καθεύδοντας."}, {"sp": "N", "st": "Tob 8:14", "t": "καὶ ἐξελθοῦσα ἀπήγγειλεν αὐτοῖς ὅτι ζῇ."}, {"sp": "N", "st": "Tob 8:15", "t": "Καὶ εὐλόγησεν Ῥαγουὴλ τὸν θεὸν λέγων Εὐλογητὸς εἶ σὺ ὁ θεὸς ἐν πάσῃ εὐλογίᾳ· καὶ εὐλογείτωσάν σε οἱ ἅγιοί σου καὶ πᾶσαι αἱ κτίσεις σου, πάντες οἱ ἄγγελοί σου καὶ οἱ ἐκλεκτοί σου εὐλογείτωσάν σε εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "Tob 8:16", "t": "εὐλογητὸς εἶ ὅτι ηὔφρανάς με, καὶ οὐκ ἐγένετό μοι καθὼς ὑπενόουν, (18)ἀλλὰ κατὰ τὸ πολὺ ἔλεός σου ἐποίησας μεθʼ ἡμῶν."}, {"sp": "N", "st": "Tob 8:17", "t": "εὐλογητὸς εἶ ὅτι ἠλέησας δύο μονογενεῖς· ποίησον αὐτοῖς, δέσποτα, ἔλεος, συντέλεσον τὴν ζωὴν αὐτῶν ἐν ὑγείᾳ μετὰ εὐφροσύνης καὶ ἐλέους."}, {"sp": "N", "st": "Tob 8:18", "t": "ἐκελευσεν δὲ τοῖς οἰκέταις χῶσαι τὸν τάφον."}, {"sp": "N", "st": "Tob 8:19", "t": "Καὶ ἐποίησεν αὐτοῖς γάμον ἡμερῶν δέκα τεσσάρων."}, {"sp": "N", "st": "Tob 8:20", "t": "καὶ εἶπεν αὐτῷ Ῥαγουὴλ πρὶν ἢ συντελεσθῆναι τὰς ἡμέρας τοῦ γάμου ἐνόρκως, μὴ ἐξελθεῖν αὐτὸν ἐὰν μὴ πληρωθῶσιν αἱ δέκα τέσσαρες ἡμέραι τοῦ γάμου,"}, {"sp": "N", "st": "Tob 8:21", "t": "καὶ τότε λαβόντα τὸ ἥμισυ τῶν ὑπαρχόντων αὐτοῦ πορεύεσθαι μετὰ ὑγείας πρὸς τὸν πατέρα· καὶ τὰ λοιπὰ ὅταν ἀποθάνω καὶ ἡ γυνή μου."}, {"sp": "N", "st": "Tob 9:1", "t": "Καὶ ἐκάλεσεν Τωβίας τὸν Ῥαφαὴλ καὶ εἶπεν αὐτῷ"}, {"sp": "N", "st": "Tob 9:2", "t": "Ἀζαρία ἀδελφέ, (3)λάβε μετὰ σεαυτοῦ παῖδα καὶ δύο καμήλους. καὶ πορεύθητι ἐν Ῥάγοις τῆς Μηδείας παρὰ Γαβαήλ, καὶ κόμισαί μοι τὸ ἀργύριον καὶ αὐτὸν ἄγε μοι εἰς τὸν γάμον."}, {"sp": "N", "st": "Tob 9:3", "t": "διότι ὀμώμοχεν Ῥαγουὴλ μὴ ἐξελθεῖν με·"}, {"sp": "N", "st": "Tob 9:4", "t": "καὶ ὁ πατήρ μου ἀριθμεῖ τὰς ἡμέρας, καὶ ἐὰν χρονίσω μέγα, ὀδυνηθήσεται λίαν."}, {"sp": "N", "st": "Tob 9:5", "t": "καὶ ἐπορεύθη Ῥαφαήλ, καὶ ηὐλίσθη παρὰ Γαβαήλ, καὶ ἔδωκεν αὐτῷ τὸ χειρόγραφον· ὃς δὲ προήνεγκεν τὰ θυλάκια ἐν ταῖς σφραγῖσιν καὶ ἔδωκεν αὐτῷ."}, {"sp": "N", "st": "Tob 9:6", "t": "καὶ ὤρθρευσαν κοινῶς καὶ ἤλθοσαν εἰς τὸν γάμον, καὶ εὐλόγησεν Γωβείας τὴν γυναῖκα αὐτοῦ."}, {"sp": "N", "st": "Tob 10:1", "t": "Καὶ Τωβεὶτ ὁ πατὴρ αὐτοῦ ἐλογίσατο ἑκάστης ἡμέρας· καὶ ὡς ἐπληρώθησαν αἱ ἡμέραι τῆς πορείας καὶ οὐκ ἤρχετο,"}, {"sp": "N", "st": "Tob 10:2", "t": "εἶπεν Μή ποτε κατήσχυνται; (²)ἢ μή ποτε ἀπέθανεν Γαβαήλ, καὶ οὐδεὶς δίδωσιν αὐτῷ τὸ ἀργύριον ;"}, {"sp": "N", "st": "Tob 10:3", "t": "καὶ ἐλυπεῖτο λίαν."}, {"sp": "N", "st": "Tob 10:4", "t": "εἶπεν δὲ αὐτῷ ἡ γυνή Ἀπώλετο τὸ παιδίον, διότι κεχρόνικεν· καὶ ἤρξατο θρηνεῖν αὐτὸν καὶ εἶπεν"}, {"sp": "N", "st": "Tob 10:5", "t": "Οὐ μέλει μοι, τέκνον, ὅτι ἀφῆκά σε τὸ φῶς τῶν ὀφθαλμῶν μου;"}, {"sp": "N", "st": "Tob 10:6", "t": "καὶ Τωβεὶτ λέγει αὐτῇ Σίγα, μὴ λόγον ἔχε, ὑγιαίνει."}, {"sp": "N", "st": "Tob 10:7", "t": "καὶ εἶπεν αὐτῷ Σίγα, μὴ πλάνα με· ἀπώλετο τὸ παιδίον μου. καὶ ἐπορεύετο καθʼ ἡμέραν εἰς τὴν ὁδὸν ἔξω οἴας ἀπῆλθεν, ἡμέρας τε ἄρτον οὐκ ἤσθιεν, τὰς δὲ νύκτας οὐ διελίμπανεν θρηνοῦσα Γωβείαν τὸν υἱὸν αὐτῆς, ἕως οὗ συνετελέσθησαν αἱ δέκα τέσσαρες ἡμέραι τοῦ γάμου ἃς ὤμοσεν Ῥαγουὴλ ποιῆσαι αὐτὸν ἐκεῖ. Εἶπεν δὲ Γωβείας τῷ Ῥαγουήλ Ἐξαπόστειλόν με, ὅτι ὁ πατήρ μου καὶ ἡ μήτηρ μου οὐκέτι ἐλπίζουσιν ὄψεσθαί με."}, {"sp": "N", "st": "Tob 10:8", "t": "εἶπεν δὲ αὐτῷ ὁ πενθερός Μεῖνον παρʼ ἐμοί, κἀγὼ ἐξαποστελῶ πρὸς τὸν πατέρα σου καὶ δηλώσουσιν αὐτῷ τὰ κατὰ σέ."}, {"sp": "N", "st": "Tob 10:9", "t": "καὶ Γωβείας λέγει Ἐξαπόστειλόν με πρὸς τὸν πατέρα μου."}, {"sp": "N", "st": "Tob 10:10", "t": "ἀναστὰς δὲ Ῥαγουὴλ ἔδωκεν αὐτῷ Σάρραν τὴν γυναῖκα αὐτοῦ καὶ τὰ ἥμισυ τῶν ὑπαρχόντων, σώματα καὶ κτήνη, ἀργύριον·"}, {"sp": "N", "st": "Tob 10:11", "t": "καὶ εὐλογήσας αὐτοὺς ἐξαπέστειλεν λέγων Εὐοδώσει ὑμᾶς, τέκνα, ὁ θεὸς τοῦ οὐρανοῦ πρὸ τοῦ μὲ ἀποθανεῖν."}, {"sp": "N", "st": "Tob 10:12", "t": "καὶ εἶπεν τῇ θυγατρὶ αὐτοῦ Τίμα τοὺς πενθερούς σου, αὐτοὶ νῦν γονεῖς σού εἰσιν· ἀκούσαιμί σου ἀκοὴν καλήν. καὶ ἐφίλησεν αὐτήν. καὶ Ἔδνα εἶπεν πρὸς Τωβείαν Ἀδελφὲ ἀγαπητέ, ἀποκαταστήσει σε ὁ κύριος τοῦ οὐρανοῦ, καὶ δῴη μοι ἰδεῖν σου παιδία ἐκ Σάρρας τῆς θυγατρός μου, ἵνα εὐφρανθῶ ἐνώπιον τοῦ κυρίου· καὶ ἰδοὺ παρατίθεμαί σοι τὴν θυγατέρα μου ἐν παρακαταθήκῃ, μὴ λυπήσῃς αὐτήν."}, {"sp": "N", "st": "Tob 11:1", "t": "Μετὰ ταῦτα ἐπορεύετο καὶ Τωβείας εὐλογῶν τὸν θεὸν ὅτι εὐόδωσεν τὴν ὁδὸν αὐτοῦ, καὶ κατευλόγει Ῥαγουὴλ καὶ Ἔδναν τὴν γυναῖκα αὐτοῦ· (¹)καὶ ἐπορεύετο μέχρις οὗ ἐγγίσαι αὐτὸν εἰς Νινευή."}, {"sp": "N", "st": "Tob 11:2", "t": "Καὶ εἶπεν Ῥαφαὴλ πρὸς Τωβείαν Οὐ γινώσκεις, ἀδελφέ, πῶς ἀφῆκες τὸν πατέρα σου ;"}, {"sp": "N", "st": "Tob 11:3", "t": "προδράμωμεν ἔμπροσθεν τῆς γυναικός σου καὶ ἑτοιμάσωμεν τὴν οἰκίαν,"}, {"sp": "N", "st": "Tob 11:4", "t": "λάβε δὲ παρὰ χεῖρα τὴν χολὴν τοῦ ἰχθύος. καὶ ἐπορεύθησαν, καὶ συνῆλθεν ὁ κύων ὄπισθεν αὐτῶν."}, {"sp": "N", "st": "Tob 11:5", "t": "καὶ Ἅννα ἐκάθητο περιβλεπομένη εἰς τὴν ὁδὸν τὸν παῖδα αὐτῆς,"}, {"sp": "N", "st": "Tob 11:6", "t": "καὶ προσενόησεν αὐτὸν ἐρχόμενον· εἶπεν τῷ πατρὶ αὐτοῦ Ἰδοὺ ὁ υἱός μου ἔρχεται καὶ ὁ ἄνθρωπος ὁ πορευθεὶς μετʼ αὐτοῦ."}, {"sp": "N", "st": "Tob 11:7", "t": "καὶ Ῥαφαὴλ εἶπεν Ἐπίσταμαι ἐγὼ ὅτι ἀνοίξει τοὺς ὀφθαλμοὺς ὁ πατήρ σου·"}, {"sp": "N", "st": "Tob 11:8", "t": "σὺ ἔγχρισον τὴν χολὴν εἰς τοὺς ὀφθαλμοὺς αὐτοῦ, καὶ δηχθεὶς διατρίψει καὶ ἀποβαλεῖται τὰ λευκώματα καὶ ὄψεταί σε."}, {"sp": "N", "st": "Tob 11:9", "t": "Καὶ προσδραμοῦσα Ἅννα ἐπέπεσεν ἐπὶ τὸν τράχηλον τοῦ υἱοῦ αὐτῆς, καὶ εἶπεν αὐτῷ Εἶδόν σε, παιδίον, ἀπὸ τοῦ νῦν ἀποθανοῦμαι. (11)καὶ ἔκλαυσαν ἀμφότεροι."}, {"sp": "N", "st": "Tob 11:10", "t": "καὶ Γωβεὶτ ἐξήρχετο πρὸς τὴν θύραν καὶ προσέκοπτεν· ὁ δὲ υἱὸς προσέδραμεν αὐτῷ,"}, {"sp": "N", "st": "Tob 11:11", "t": "καὶ ἐπελάβετο τοῦ πατρὸς αὐτοῦ, καὶ προσέπασεν τὴν χολὴν ἐπὶ τοὺς ὀφθαλμοὺς τοῦ πατρὸς αὐτοῦ λέγων Θάρσει, πάτερ."}, {"sp": "N", "st": "Tob 11:12", "t": "ὡς δὲ συνεδήχθησαν, διέτριψε τοὺς ὀφθαλμοὺς αὐτοῦ,"}, {"sp": "N", "st": "Tob 11:13", "t": "καὶ ἐλεπίσθη ἀπὸ τῶν κανθῶν τῶν ὀφθαλμῶν αὐτοῦ τὰ λευκώματα. καὶ ἰδὼν τὸν υἱὸν αὐτοῦ ἐπέπεσεν ἐπὶ τὸν τράχηλον αὐτοῦ,"}, {"sp": "N", "st": "Tob 11:14", "t": "καὶ ἔκλαυσεν καὶ εἶπεν Εὐλογητὸς εἶ ὁ θεός, καὶ εὐλογητὸν τὸ ὄνομά σου εἰς τοὺς αἰῶνας, καὶ εὐλογημένοι πάντες οἱ ἅγιοι ἄγγελοί σου,"}, {"sp": "N", "st": "Tob 11:15", "t": "ὅτι ἐμαστίγωσας καὶ ἠλέησάς με· ἰδοὺ βλέπω Γωβείαν τὸν υἱόν μου. (18)καὶ εἰσῆλθεν ὁ υἱὸς αὐτοῦ χαίρων, (19)καὶ ἀπήγγειλεν τῷ πατρὶ αὐτοῦ τὰ μεγαλεῖα τὰ γενόμενα αὐτῷ ἐν τῇ Μηδείᾳ."}, {"sp": "N", "st": "Tob 11:16", "t": "Καὶ ἐξῆλθεν Γωβείας εἰς συνόντησιν τῇ νύμφη αὐτοῦ, χαίρων καὶ εὐλογῶν τὸν θεόν, πρὸς τῆ πύλῃ Νινευή. καὶ ἐθαύμαζον οἱ θεωροῦντες αὐτὸν πορευόμενον, ὅτι ἔβλεψεν·"}, {"sp": "N", "st": "Tob 11:17", "t": "καὶ Τωβεὶτ ἐξαωμολογεῖτο ἐνώπιον αὐτοῦ ὅτι ἡλέηκεν αὐτοὺς ὁ θεός. καὶ ὡς ἤγγσεν Τωβεὶτ Σάρρᾳ τῇ νύμφῃ αὐτοῦ, κατευλόγησεν αὐτὴν λέγων Ἔλθοις ὑγιαίνουσα, θύγατερ· εὐλογητὸς ὁ θεός, ὃς ἤγαγέν σε πρὸς ἡμᾶς, καὶ ὁ πατήρ σου καὶ ἡ μήτηρ σου. (20) καὶ ἐγένετο χαρὰ πᾶσι τοῖς ἐν Νινευὴ ἀδελφοῖς αὐτοῦ."}, {"sp": "N", "st": "Tob 11:18", "t": "καὶ παρεγένετο Ἀχιάχαρος καὶ Νασβᾶς ὁ ἐξάδελφος αὐτοῦ,"}, {"sp": "N", "st": "Tob 11:19", "t": "καὶ ἤχθη ὁ γάμος Τωβεία μετʼ εὐφροσύνης ἑπτὰ ἡμέρας."}, {"sp": "N", "st": "Tob 12:1", "t": "Καὶ ἐκάλεσεν Τωβεὶτ Τωβείαν τὸν υἱὸν αὐτοῦ καὶ εἶπεν αὐτῷ Ὅρα, τέκνον, μισθὸν τῷ ἀνθρώπῳ τῷ συνελθόντι σοι, καὶ προσθεῖναι αὐτῷ δεῖ"}, {"sp": "N", "st": "Tob 12:2", "t": "καὶ εἶπεν Πάτερ, οὐ βλάπτομαι δοὺς αὐτῷ τὸ ἥμισυ ὧν ἐνήνοχα,"}, {"sp": "N", "st": "Tob 12:3", "t": "ὅτι με ἀγίοχέν σοι ὑγιῆ, καὶ τὴν γυναῖκά μου ἐθεράπευσεν καὶ τὸ ἀργύριόν μου ἤνεγκεν, καὶ σέ ὁμοίως ἐθεράπευσεν."}, {"sp": "N", "st": "Tob 12:4", "t": "καὶ εἶπεν ὁ πρεσβύτης Δικαιοῦται αὐτῷ."}, {"sp": "N", "st": "Tob 12:5", "t": "καὶ ἐκάλεσεν τὸν ἄγγελον καὶ εἶπεν αὐτῷ Λάβε τὸ ἥμισυ πάντων ὧν ἐνηνόχατε."}, {"sp": "N", "st": "Tob 12:6", "t": "καὶ καλέσας τοὺς δύο κρυπτῶς εἶπεν αὐτοῖς Εὐλογεῖτε τὸν θεὸν καὶ αὐτῷ ἐξομολογεῖσθε, μεγαλωσύνην δίδοτε αὐτῷ, καὶ ἐξομολογεῖσθε αὐτῷ ἐνώπιον πάντων τῶν ζώντων περὶ ὧν ἐποίησεν μεθʼ ὑμῶν. ἀγαθὸν τὸ εὐλογεῖν τὸν θεὸν καὶ ὑψοῖν τὸ ὄνομα αὐτοῦ, τοὺς λόγους τῶν ἔργων τοῦ θεοῦ ἐντίμως ὑποδεικνύοντες· καὶ μὴ ὀκνεῖτε ἐξομολογεῖσθαι αὐτῷ."}, {"sp": "N", "st": "Tob 12:7", "t": "μυστήριον βασιλέως καλὸν κρύψαι, τὰ δὲ ἔργα τοῦ θεοῦ ἀνακαλύπτειν ἐνδόξως. ἀγαθὸν ποιήσατε, καὶ κακὸν οὐχ εὑρήσει ὑμᾶς."}, {"sp": "N", "st": "Tob 12:8", "t": "ἀγαθὸν προσευχὴ μετὰ νηστείας καὶ ἐλεημοσύνης καὶ δικαιοσύνης· ἀγαθὸν τὸ ὀλίγον μετὰ δικαιοσύνης ἢ πολὺ μετὰ ἀδικίας· καλὸν ποιῆσαι ἐλεημοσύνην ἢ θησαυρίσαι χρυσίον."}, {"sp": "N", "st": "Tob 12:9", "t": "ἐλεημοσύνη ἐκ θανάτου ῥύεται, καὶ αὕτη ἀποκαθαριεῖ πᾶσαν ἁμαρτίαν· οἱ ποιοῦντες ἐλεημοσύνας καὶ δικαιοσύνας πλησθήσονται ζωῆς·"}, {"sp": "N", "st": "Tob 12:10", "t": "οἱ δὲ ἁμαρτάνοντες πολέμιοί εἰσιν τῆς ἑαυτῶν ζωῆς."}, {"sp": "N", "st": "Tob 12:11", "t": "οὐ μὴ κρύψω ἀφʼ ὑμῶν πᾶν ῥῆμα· εἴρηκα δὴ μυστήριον βασιλέως κρύψαι καλόν, τὰ δὲ ἔργα τοῦ θεοῦ ἀνακαλύπτειν ἐνδόξως."}, {"sp": "N", "st": "Tob 12:12", "t": "καὶ νῦν ὅτε προσηύξω σὺ καὶ ἡ νύμφη σου Σάρρα, ἐγὼ προσήγαγον τὸ μνημόσυνον τῆς προσευχῆς ὑμῶν ἐνώπιον τοῦ ἁγίου· καὶ ὅτε ἔθαπτες τοὺς νεκρούς, ὡσαύτως συμπαρήμην σοι·"}, {"sp": "N", "st": "Tob 12:13", "t": "καὶ ὅτε οὐκ ὤκνησας ἀναστῆναι καὶ καταλιπεῖν τὸ ἄριστόν σου ὅπως ἀπελθὼν περιστείλῃς τὸν νεκρόν, οὐκ ἔλαθές με ἀγαθοποιῶν, ἀλλὰ σὺν σοὶ ἤμην."}, {"sp": "N", "st": "Tob 12:14", "t": "καὶ νῦν ἀπέστειλέν με ὁ θεὸς ἰάσασθαί σε καὶ τὴν νύμφην σου Σάρραν."}, {"sp": "N", "st": "Tob 12:15", "t": "ἐγὼ εἰμι Ῥαφαήλ, εἰς ἐκ τῶν ἑπτὰ ἁγίων ἀγγέλων οἳ προσαναφέρουσιν τὰς προσευχὰς τῶν ἁγίων καὶ εἰσπορεύονται ἐνώπιον τῆς δόξης τοῦ ἁγίου."}, {"sp": "N", "st": "Tob 12:16", "t": "Καὶ ἐταράχθησαν οἱ δύο καὶ ἔπεσον ἐπὶ πρόσωπον, ὅτι ἐφοβήθησαν."}, {"sp": "N", "st": "Tob 12:17", "t": "καὶ εἶπεν αὐτοῖς Μὴ φοβεῖσθε, εἰρήνη ὑμῖν ἔσται· τὸν δὲ θεὸν εὐλογεῖτε εἰς τὸν αἰῶνα,"}, {"sp": "N", "st": "Tob 12:18", "t": "ὅτι οὐ τῇ ἐμαυτοῦ χάριτι ἀλλὰ τῆ θελήσει τοῦ θεοῦ ὑμῶν· ὅθεν εὐλογεῖτε αὐτὸν εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Tob 12:19", "t": "πάσας τὰς ἡμέρας ὠπτανόμην ὑμῖν, καὶ οὐκ ἔφαγον οὐδὲ ἔπιον, ἀλλὰ ὅρασιν ὑμεῖς ἐθεωρεῖτε."}, {"sp": "N", "st": "Tob 12:20", "t": "καὶ νῦν ἐξομολογεῖσθε τῷ θεῷ, διότι ἀναβαίνω πρὸς τὸν ἀποστείλανταά με, καὶ γράψατε πάντα τὰ συντελεσθέντα εἰς βιβλίον."}, {"sp": "N", "st": "Tob 12:21", "t": "καὶ ἀνέστησαν, καὶ οὐκ εἶδον αὐτόν."}, {"sp": "N", "st": "Tob 12:22", "t": "καὶ ἐξομολογοῦντο τὰ ἔργα τὰ μεγάλα καὶ θαυμαστὰ αὐτοῦ, ὡς ὤφθη αὐτοῖς ἄγγελος Κυρίου."}, {"sp": "N", "st": "Tob 13:1", "t": "¹Καὶ Τωβεὶτ ἔγραψεν προσευχὴν εἰς ἀγαλλίασιν καὶ εἶπεν Εὐλογητὸς ὁ θεὸς ὁ ζῶν εἰς τοὺς αἰῶνας καὶ ἡ βασιλεία αὐτοῦ,"}, {"sp": "N", "st": "Tob 13:2", "t": "²ὅτι αὐτὸς μαστιγοῖ καὶ ἐλεῷ, κατάγει εἰς ᾃδην καὶ ἀνάγει, καὶ οὐκ ἔστιν ὃς ἐκφεύξεται τὴν χεῖρα αὐτοῦ."}, {"sp": "N", "st": "Tob 13:3", "t": "³ἐξομολογεῖσθε αὐτῷ, οἱ υἱοὶ Ἰσραήλ, ἐνώπιον τῶν ἐθνῶν, (4)ὅτι αὐτὸς διέσπειρεν ἡμᾶς ἐν αὐτοῖς."}, {"sp": "N", "st": "Tob 13:4", "t": "4ἐκεῖ ὑποδείξατε τὴν μεγαλωσύνην αὐτοῦ, ὑψοῦτε αὐτὸν ἐνώπιον παντὸς ζῶντος· καθότι αὐτὸς κύριος ἡμῶν, καὶ θεὸς αὐτὸς πατὴρ ἡμῶν εἰς πάντας τοὺς αἰῶνας."}, {"sp": "N", "st": "Tob 13:5", "t": "5καὶ μαστιγώσει ἡμᾶς ἐν ταῖς ἀδικίαις ἡμῶν, καὶ πάλιν ἐλεήσει καὶ συνάξει ἡμᾶς ἐκ πάντων τῶν ἐθνῶν, οὗ ἐὰν σκορπισθῆτε ἐν αὐτοῖς."}, {"sp": "N", "st": "Tob 13:6", "t": "6ἐὰν ἐπιστρέψητε πρὸς αὐτὸν ἐν ὅλη καρδίᾳ ὑμῶν καὶ ἐν ὅλῃ τῆ ψυχῇ ποιῆσαι ἐνώπιον αὐτοῦ ἀλήθειαν, τότε ἐπιστρέψει πρὸς ὑμᾶς καὶ οὐ μὴ κρύψῃ τὸ πρόσωπον αὐτοῦ ἀφʼ ὑμῶν. (6)καὶ θεάσασθε ὁ ποιήσει μεθʼ ὑμῶν, καὶ ἐξομολογήσασθε αὐτῷ ἐν ὅλῳ τῷ σώματι ὑμῶν· καὶ εὐλογήσατε τὸν κύριον τῆς δικαιοσύνης, καὶ ὑψώσατε τὸν βασιλέα τῶν αἰώνων. (7)ἐγὼ ἐν τῇ γῇ τῆς αἰχμαλωσίας μου ἐξομολογοῦμαι αὐτῷ, καὶ δεικνύω τὴν ἰσχὺν καὶ τὴν μεγαλωσύνην αὐτοῦ ἔθνη ἁμαρτωλῶν. (8)ἐπιστρέψατε, ἁμαρτωλοί, καὶ ποιήσατε δικαιοσύνην ἐνώπιον αὐτοῦ· τίς γινώσκει εἰ θελήσει ὑμᾶς καὶ ποιήσει ἐλεημοσύνην ὑμῖν;"}, {"sp": "N", "st": "Tob 13:7", "t": "7τὸν θεόν μου ὑψῶ, καὶ ἡ ψυχῇ μου τῷ βασιλεῖ τοῦ οὐρανοῦ, καὶ ἀγαλλιάσεται τὴν μεγαλωσύνην αὐτοῦ."}, {"sp": "N", "st": "Tob 13:8", "t": "8λεγέτωσαν πάντες καὶ ἐξομολογείσθωσαν αὐτῷ ἐν Ἰεροσολύμοις."}, {"sp": "N", "st": "Tob 13:9", "t": "9Ἰεροσόλυμα πόλις ἁγίου· μαστιγώσει ἐπὶ τὰ ἔργα τῶν υἱῶν σου, καὶ πάλιν ἐλεήσει τοὺς υἱοὺς τῶν δικαίων."}, {"sp": "N", "st": "Tob 13:10", "t": "10ἐξομολογοῦ τῷ κυρίῳ ἀγαθῶς, καὶ εὐλόγει τὸν βασιλέα τῶν αἰώνων, ἵνα πάλιν ἡ σκηνὴ αὐτοῦ οἰκοδομηθῇ σοι μετὰ χαρᾶς καὶ εὐφράναι ἐν σοὶ τοὺς αἰχμαλώτους καὶ ἀγαπήσαι ἐν σοὶ τοὺς ταλαιπώρους εἰς πάσας τὰς γενεὰς τοῦ αἰῶνος."}, {"sp": "N", "st": "Tob 13:11", "t": "¹¹ἔθνη πολλὰ μακρόθεν ἥξει πρὸς τὸ ὄνομα Κυρίου τοῦ θεοῦ, δῶρα ἐν χερσὶν ἔχοντες καὶ δῶρα τῷ βασιλεῖ τοῦ οὐρανοῦ· γενεαὶ γενεῶν δώσουσίν σοι ἀγαλλίαμα."}, {"sp": "N", "st": "Tob 13:12", "t": "¹²ἐπικατάρατοι πάντες οἱ μισοῦντές σε, εὐλογημένοι ἔσονται πάντες οἵ ἀγαπῶντές σε εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Tob 13:13", "t": "13χάρηθι καὶ ἀγαλλίασαι ἐπὶ τοῖς υἱοῖς τῶν δικαίων, ὅτι συναχθήσονται καὶ εὐλογήσουσιν τὸν κύριον τῶν δικαίων."}, {"sp": "N", "st": "Tob 13:14", "t": "¹⁴ὢ μακάριοι οἱ ἀγαπῶντές σε· χαρήσονται ἐπὶ τῇ εἰρήνῃ σου. μακάριοι ὅσοι ἐλυπήθησαν ἐπὶ ταῖς μάστιξίν σου, ὅτι ἐπὶ σοὶ χαρήσονται θεασάμενοι πᾶσαν τὴν δόξαν σου· καὶ εὐφρανθήσεται εἰς τὸν αἰῶνα ἡ ψυχὴ μου."}, {"sp": "N", "st": "Tob 13:15", "t": "15εὐλόγει τὸν θεὸν τὸν βασιλέα τὸν μέγαν,"}, {"sp": "N", "st": "Tob 13:16", "t": "16ἔτι οἰκοδομηθήσεται Ἰερουσαλὴμ σαπφείρῳ καὶ σμαράγδῳ, καὶ λίθῳ ἐντίμῳ τὰ τείχη σου, καὶ οἱ πύργοι καὶ οἱ προμαχῶνες χρυσίῳ καθαρῷ,"}, {"sp": "N", "st": "Tob 13:17", "t": "17καὶ αἱ πλατεῖαι Ἰερουσαλὴμ βηρύλλῳ καὶ ἄνθρακι καὶ λίθῳ ἐκ Σουφεὶρ ψηφολογηθήσονται."}, {"sp": "N", "st": "Tob 13:18", "t": "18καὶ ἐροῦσιν πᾶσαι αἱ ῥῦμαι αὐτῆς ἁλληλουιὰ καὶ αἴνεσιν, λέγοντες (23)Εὐλογητὸς ὁ θεὸς ὃς ὕψωσεν πάντας τοὺς αἰῶνας."}, {"sp": "N", "st": "Tob 14:1", "t": "Καὶ ἐπαύσατο ἐξομολογούμενος Γωβείτ."}, {"sp": "N", "st": "Tob 14:2", "t": "καὶ ἦν ἐτῶν πεντήκοντα ὀκτὼ ὅτε ἀπώλεσεν τὰς ὄψεις, καὶ μετὰ ἔτη ὀκτὼ ἀνέβλεψεν· καὶ ἐποίει ἐλεημοσύνας, (4)καὶ προσέθετο φοβεῖσθαι Κύριον τὸν θεὸν καὶ ἐξωμολογεῖτο αὐτῷ."}, {"sp": "N", "st": "Tob 14:3", "t": "μεγάλως δὲ ἐγήρασεν· καὶ ἐκάλεσεν τὸν υἱὸν αὐτοῦ καὶ τοὺς υἱοὺς αὐτοῦ, καὶ εἶπεν αὐτῷ Τέκνον, λάβε τοὺς υἱούς σου· ἰδοὺ γεγήρακα, καὶ πρὸς τὸ ἀποτρέχειν ἐκ τοῦ ζῆν εἰμί."}, {"sp": "N", "st": "Tob 14:4", "t": "ἄπελθε εἰς τὴν Μηδείαν, τέκνον, ὅτι πέπεισμαι ὅσα ἐλάλησεν Ἰωνᾶς ὁ προφήτης περὶ Νινευὴ ὅτι καταστραφήσεται, ἐν δὲ τῇ Μηδείᾳ ἔσται εἰρήνη μᾶλλον ἕως καιροῦ· καὶ ὅτι οἱ ἀδελφοὶ ἡμῶν ἐν τῇ γῇ σκορπισθήσονται ἀπὸ τῆς ἀγαθῆς γῆς, καὶ Ἰεροσόλυμα ἔσται ἔρημος καὶ ὁ οἶκος τοῦ θεοῦ ἐν αὐτῇ κατακαήσεται, καὶ ἔρημος ἔσται μέχρι χρόνου."}, {"sp": "N", "st": "Tob 14:5", "t": "καὶ πάλιν ἐλεήσει αὐτοὺς ὁ θεὸς καὶ ἐπιστρέψει αὐτοὺς εἰς τὴν γῆν, καὶ οἰκοδομήσουσιν τὸν οἶκον, οὐχ οἷος ὁ πρότερος, ἕως πληρωθῶσιν καιροὶ τοῦ αἰῶνος. καὶ μετὰ ταῦτα ἐπιστρέψουσιν ἐκ τῶν αἰχμαλωσιῶν καὶ οἰκοδομήσουσιν Ἰερουσαλὴμ ἐντίμως, καὶ ὁ οἶκος τοῦ θεοῦ ἐν αὐτῇ οἰκοδομηθήσεται ἐνδόξως, καθὼς ἐλάλησαν περὶ αὐτῆς οἱ προφῆται."}, {"sp": "N", "st": "Tob 14:6", "t": "καὶ πάντα τὰ ἔθνη ἐπιστρέψουσιν ἀληθινῶς φοβεῖσθαι Κύριον τὸν θεόν· κατορύξουσιν τὰ εἴδωλα αὐτῶν·"}, {"sp": "N", "st": "Tob 14:7", "t": "καὶ εὐλογήσουσιν πάντα τὰ ἔθνη Κύριον. καὶ ὁ λαὸς αὐτοῦ ἐξομολογήσεται τῷ θεῷ, καὶ ὑψώσει Κύριος τὸν λαὸν αὐτοῦ· καὶ χαρήσονται πάντες οἱ ἀγαπῶντες Κύριον τὸν θεὸν ἐν ἀληθείᾳ καὶ δικαιοσύνῃ, ποιοῦντες ἔλεος τοῖς ἀδελφοῖς ἡμῶν."}, {"sp": "N", "st": "Tob 14:8", "t": "καὶ νῦν, τέκνον, ἄπελθε ἀπὸ Νινευή, ὅτι πάντως ἔσται ἃ ἐλάλησεν ὁ προφήτης Ἰωνᾶς."}, {"sp": "N", "st": "Tob 14:9", "t": "σὺ δὲ τήρησον τὸν νόμον καὶ τὰ προστάγματα, καὶ γενοῦ φιλελεήμων καὶ δίκαιος, ἵνα σοι καλῶς ἦν."}, {"sp": "N", "st": "Tob 14:10", "t": "καὶ θάψον με καλῶς, καὶ τὴν μητέρα σου μετʼ ἐμοῦ, καὶ μηκέτι αὐλισθῆτε εἰς Νινευή. τέκνον, ἴδε τί ἐποίησεν Ἀδὰμ Ἀχιαχάρῳ τῷ θρέψαντι αὐτόν, ὡς ἐκ τοῦ φωτὸς ἤγαγεν αὐτὸν εἰς τὸ σκότος καὶ ὅσα ἀνταπέδωκεν αὐτῷ· καὶ Ἀχιάχαρον μὲν ἔσωσεν, ἐκείνῳ δὲ τὸ ἀνταπόδομα ἀπεδόθη, καὶ αὐτὸς κατέβη εἰς τὸ σκότος. Μανασσῆς ἐποίησεν ἐλεημοσύνην, καὶ ἐσώθη ἐκ παγίδος θανάτου ἧς ἔπηξεν αὐτῷ, Ἀδὰμ δὲ ἐνέπεσεν εἰς τὴν παγίδα καὶ ἀπώλετο."}, {"sp": "N", "st": "Tob 14:11", "t": "καὶ νῦν, παιδία, ἴδετε τί ἐλεημοσύνη ποιεῖ καὶ δικαιοσύνη ῥύεται. καὶ ταῦτα αὐτοῦ λέγοντος ἐξέλιπεν αὐτοῦ ἡ ψυχὴ ἐπὶ τῆς κλίνης· ἦν δὲ ἐτῶν ἑκατὸν πεντήκοντα ὀκτώ· καὶ ἔθαψεν αὐτὸν ἐνδόξως."}, {"sp": "N", "st": "Tob 14:12", "t": "Καὶ ὅτε ἀπέθανεν Ἅννα, ἔθαψεν αὐτὴν μετὰ τοῦ πατρὸς αὐτοῦ· ἀπῆλθεν δὲ Τωβίας μετὰ τῆς γυναικὸς αὐτοῦ καὶ τῶν υἱῶν αὐτοῦ εἰς Ἐκβάτανα πρὸς Ῥαγουὴλ τὸν πενθερὸν αὐτοῦ."}, {"sp": "N", "st": "Tob 14:13", "t": "καὶ ἐγήρασεν ἐντίμαως, καὶ ἔθαψεν τοὺς πενθεροὺς αὐτοῦ ἐνδόξως, καὶ ἐκληρονόμησεν τὴν οὐσίαν αὐτῶν καὶ Τωβεὶτ τοῦ πατρὸς αὐτοῦ."}, {"sp": "N", "st": "Tob 14:14", "t": "καὶ ἀπέθανεν ἐτῶν ἑκατὸν ἑπτὰ ἐν Ἐκβατάνοις τῆς Μηδείας."}, {"sp": "N", "st": "Tob 14:15", "t": "καὶ ἤκουσεν πρὶν ἢ ἀποθανεῖν αὐτὸν τὴν ἀπωλίαν Νινευὴ ἣν ᾐχμαλώτισεν Ναβουχοδονοσὸρ καὶ Ἀσύηρος· ἐχάρη πρὸ τοῦ ἀποθανεῖν ἐπὶ Νινευή. ἀμήν."}, {"sp": "HDR", "t": "ΙΟΥΔΕΙΘ"}, {"sp": "N", "st": "Jdt 1:1", "t": "ΕΤΟΥΣ δωδεκάτου τῆς βασιλείας Ναβουχοδονοσόρ, ὃς ἐβαἡμέραις σίλευσεν Ἀσσυρίων ἐν Νινευὴ τῇ πόλει τῇ μεγάλη, (1)ἐν ταῖς Ἀρφαξάδ, ὃς ἐβασίλευσεν Μήδων ἐν Ἐκβατάνοις"}, {"sp": "N", "st": "Jdt 1:2", "t": "καὶ ᾠκοδόμησεν ἐπʼ Ἐκβατάνων καὶ κύκλῳ (2a)τείχη ἐκ λίθων λελαξευμένων, εἰς πλάτος πηχῶν τριῶν καὶ εἰς μῆκος πηχῶν ἕξ, καὶ ἐποίησεν τὸ ὕψος τοῦ τείχους πηχῶν ἑβδομήκοντα καὶ τὸ πλάτος αὐτοῦ πηχῶν πεντήκοντα·"}, {"sp": "N", "st": "Jdt 1:3", "t": "καὶ τοὺς πύργους αὐτοῦ ἔστησεν ἐπὶ ταῖς πύλαις αὐτῆς πηχῶν ἑκατόν, καὶ τὸ πλάτος αὐτῆς ἐθεμελίωσεν εἰς πήχεις ἐξήκοντα·"}, {"sp": "N", "st": "Jdt 1:4", "t": "καὶ ἐποίησεν τὰς πύλας αὐτῆς πύλας διεγειρομένας εἰς ὕψος πηχῶν ἑβδομήκοντα, καὶ τὸ πλάτος αὐτῆς πήχεις τεσσεράκοντα, (4)εἰς ἐξόδους δυνάμεως δυνατῶν αὐτοῦ καὶ διατάξεις τῶν πεζῶν αὐτοῦ·"}, {"sp": "N", "st": "Jdt 1:5", "t": "καὶ ἐποίησεν πόλεμον ἐν ταῖς ἡμέραις ἐκείναις βασιλεὺς Ναβουχοδονοσὸρ πρὸς βασιλέα Ἀρφαξὰβ (⁶)ἐν τῷ πεδίῳ τῷ μεγάλῳ, τοῦτό ἐστιν τοῖς ὁρίοις Ῥαγαύ."}, {"sp": "N", "st": "Jdt 1:6", "t": "καὶ συνήντησαν πρὸς αὐτὸν πάντες οἱ κατοικοῦντες τὴν ὀρινήν, καὶ πάντες οἱ κατοικοῦντες τὸν Εὐφράτην καὶ τὸν Τίγριν καὶ τὸν Υδάσπην, καὶ πεδίῳ Ἀριὼχ ὁ βασιλεὺς Ἐλυμαίων· καὶ συνῆλθον ἔθνη πολλὰ εἰς παράταξιν υἱῶν Χελεούλ."}, {"sp": "N", "st": "Jdt 1:7", "t": "Καὶ κατοικοῦντας τὴν Περσίδα καὶ ἐπὶ πάντας τοὺς κατοικοῦντας πρὸς δυσμαῖς, τοὺς κατοικοῦντας τὴν Κιλικίαν καὶ Δαμασκόν, τὸν Λίβανον καὶ Ἀντιλίβανον, καὶ πάντας τοὺς κατοικοῦντας κατὰ πρόσωπον παραλίας,"}, {"sp": "N", "st": "Jdt 1:8", "t": "καὶ τοὺς ἐν τοῖς ἔθνεσι τοῦ Καρμήλου καὶ Γαλαὰδ καὶ τὴν ἄνω Γαλειλαίαν καὶ τὸ μέγα πεδίον Ἐσρήμ,"}, {"sp": "N", "st": "Jdt 1:9", "t": "καὶ πάντας τοὺς ἐν Σαμαρείᾳ καὶ ταῖς πόλεσιν αὐτῆς, καὶ πέραν τοῦ Ἰορδάνου ἕως Ἰερουσαλὴμ καὶ Βαιτανὴ καὶ Χελοὺς καὶ Κάδης καὶ τοῦ ποταμοῦ Αἰγύπτου, καὶ Ταφνὰς καὶ Ῥαμεσσῆ καὶ πᾶσαν γῆν Γέσεμ"}, {"sp": "N", "st": "Jdt 1:10", "t": "ἕως τοῦ ἐλθεῖν ἐπάνω Τάνεως καὶ Μέμφεως, καὶ πάντας τοὺς κατοικοῦντας τὴν Aἵγυπτον ἕως τοῦ ἐλ. θεῖν ἐπὶ τὰ ὅρια τῆς Αἰθιοπίας."}, {"sp": "N", "st": "Jdt 1:11", "t": "καὶ ἐφαύλισαν πάντες οἱ κατοικοῦντες πᾶσαν τὴν γῆν τὸ ῥῆμα Ναβουχοδονοσὸρ βασιλέως Ἀσσυρίων καὶ οὐ συνῆλθον αὐτῷ εἰς τὸν πόλεμον, ὅτι οὐκ ἐφοβήθησαν αὐτὸν ἀλλ\\᾿ ἦν ἐναντίον αὐτῶν ὡς ἀνὴρ ἴσος, καὶ ἀνέστρεψαν τοὺς ἀγγέλους αὐτοῦ κενοὺς ἐν ἀτιμίᾳ πρὸ προσώπου αὐτῶν."}, {"sp": "N", "st": "Jdt 1:12", "t": "Καὶ ἐθυμώθη Ναβουχοδονοσὸρ ἐπὶ πᾶσαν τὴν γῆν ταύτην σφόδρα, καὶ ὤμοσε κατὰ τοῦ θρόνου καὶ τῆς βασιλείας αὐτοῦ, εἰ μὴν ἐκδικήσειν πάντα τὰ ὅρια τῆς Κιλικίας καὶ Δαμασκηνῆς καὶ Συρίας, ἀνελεῖν τῇ ῥομφαίᾳ αὐτοὺς καὶ πάντας τοὺς κατοικοῦντας ἐν τῇ Μωὰβ καὶ τοὺς υἱοὺς Ἀμμὼν καὶ πᾶσαν τὴν Ἰδουμαίαν καὶ πάντας τοὺς ἐν Αἰγύπτῳ ἕως τοῦ ἐλ. θεῖν ἐπὶ τὰ δρία τῶν δύο θαλασσῶν."}, {"sp": "N", "st": "Jdt 1:13", "t": "καὶ παρετάξατο ἐν τῇ δυνάμει αὐτοῦ πρὸς Ἀρφαξὰδ βασιλέα ἐν τῷ ἔτει τῷ ἑπτακαιδεκάτῳ· καὶ ἐκραταιώθη ἐν τῷ πολέμῳ αὐτοῦ, καὶ ἀνέστρεψεν πᾶσαν τὴν δύναμιν Ἀρφαξὰδ καὶ πᾶσαν τὴν ἵππον αὐτοῦ καὶ πάντα τὰ ἅρματα αὐτοῦ,"}, {"sp": "N", "st": "Jdt 1:14", "t": "καὶ ἐκυρίευσε τῶν πόλεων αὐτοῦ· καὶ ἀφίκετο ἕως Ἐκβατάνων, καὶ ἐκράτησε τῶν πύργων καὶ ἐπρονόμευσε τὰς πλατείας αὐτῆς, καὶ τὸν κόσμον αὐτῆς ἔθηκεν εἰς ὄνειδος αὐτῆς·"}, {"sp": "N", "st": "Jdt 1:15", "t": "καὶ ἔλαβε τὸν Ἀρφαξὰδ ἐν τοῖς ὄρεσι Ῥαγαύ, καὶ κατηκόντισεν αὐτὸν ἐν ταῖς σιβύναις αὐτοῦ, καὶ ἐξωλέθρευσεν αὐτὸν ἕως τῆς ἡμέρας ἐκείνης."}, {"sp": "N", "st": "Jdt 1:16", "t": "καὶ ἀνέστρεψεν μετʼ αὐτῶν αὐτὸς καὶ ἡ δύναμις αὐτοῦ ἐφʼ ἡμέρας ἑκατὸν εἴκοσι."}, {"sp": "N", "st": "Jdt 2:1", "t": "Καὶ ἐν τῷ ἔτει τῷ ὀκτωκαιδεκάτῳ, δευτέρᾳ καὶ εἰκάδι τοῦ πρώτου μηνός, ἐγένετο λόγος ἐν οἴκῳ Ναβουχοδονοσὸρ βασιλέως Ἀσσυρίων ἐκδικῆσαι πᾶσαν τὴν γῆν καθὼς ἐλάλησεν."}, {"sp": "N", "st": "Jdt 2:2", "t": "καὶ συνεκάλεσεν πάντας τοὺς θεράποντας αὐτοῦ καὶ πάντας τοὺς μεγιστᾶνας αὐτοῦ, καὶ ἔθετο μετʼ αὐτῶν τὸ μυστήριον τῆς βουλῆς αὐτοῦ, καὶ συνετέλεσεν πᾶσαν τὴν κακίαν τῆς γῆς ἐκ τοῦ στόματος αὐτοῦ·"}, {"sp": "N", "st": "Jdt 2:3", "t": "καὶ αὐτοὶ ἔκριναν ὀλεθρεῦσαι πᾶσαν σάρκα οἳ οὐκ ἠκολούθησαν τῷ λόγῳ τοῦ στόματος αὐτοῦ."}, {"sp": "N", "st": "Jdt 2:4", "t": "καὶ ἐγένετο ὡς συνετέλεσεν τὴν βουλὴν αὐτοῦ, ἐκάλεσεν Ναβουχοδονοσὸρ βασιλεὺς Ἀσσυρίων τὸν Ὀλοφέρνην ἀρχιστράτηγον τῆς δυνάμεως αὐτοῦ, δεύτερον ὄντα μετʼ αὐτάν, (⁵a)καὶ εἶπεν πρὸς αὐτόν"}, {"sp": "N", "st": "Jdt 2:5", "t": "Τάδε λέγει ὁ βασιλεὺς ὁ μέγας, ὁ κύριος πάσης τῆς γῆς Ἰδοὺ σὺ ἐξελεύσῃ ἐκ τοῦ προσώπου μου, καὶ λήμψῃ μετὰ σεαυτοῦ ἄνδρας πεποιθότας ἐν ἰσχύι αὐτῶν, πεζῶν εἰς χιλιάδας ἑκατὸν εἴκοσι καὶ πλῆθος ἵππων σὺν ἀναβάταις μυριάδας δέκα δύο,"}, {"sp": "N", "st": "Jdt 2:6", "t": "καὶ ἐξελεύσῃ εἰς συνάντησιν πάσῃ τῇ γῇ ἐπὶ δυσμάς, ὅτι ἠπείθησαν τῷ ῥήματι τοῦ στόματός μου·"}, {"sp": "N", "st": "Jdt 2:7", "t": "καὶ ἑτοιμάζειν γῆν καὶ ὕδωρ, ὅτι ἐξελεύσομαι ἐν θυμῷ μου ἐπʼ αὐτούς, καὶ καλύψω πᾶν τὸ πρόσωπον τῆς γῆς ἐν τοῖς ποσὶν τῆς δυνάμεώς μου, καὶ δώσω αὐτοὺς εἰς διαρπαγὴν αὐτοῖς·"}, {"sp": "N", "st": "Jdt 2:8", "t": "καὶ οἱ τραυματίαι αὐτῶν πληρώσουσιν τὰς φάραγγας αὐτῶν καὶ τοὺς χειμάρρους, καὶ ποταμὸς ἐπικλύζων τοῖς νεκροῖς αὐτῶν πληρωθήσεται·"}, {"sp": "N", "st": "Jdt 2:9", "t": "καὶ ἄξω τὴν αἰχμαλαωσίαν αὐτῶν ἐπὶ τὰ ἄκρα πάσης τῆς γῆς."}, {"sp": "N", "st": "Jdt 2:10", "t": "σὺ δὲ ἐξελθὼν προκαταλήμψῃ μοι πᾶν ὅριον αὐτῶν, καὶ ἐκδώσουσίν σοι ἑαυτούς, καὶ διατηρήσεις ἐμοὶ αὐτοὺς εἰς ἡμέραν ἐλεγμοῦ αὐτῶν·"}, {"sp": "N", "st": "Jdt 2:11", "t": "ἐπὶ δὲ τοὺς ἀπειθοῦντας οὐ φείσεται ὁ ὀφθαλμός σου, δοῦναι αὐτοὺς εἰς φόνον καὶ ἁρπαγὴν ἐν πάσῃ τῇ γῇ σου."}, {"sp": "N", "st": "Jdt 2:12", "t": "ὅτι ζῶν ἐγὼ καὶ τὸ κράτος τῆς βασιλείας μου, λελάληκα καὶ ποιήσω ταῦτα ἐν χειρί μου."}, {"sp": "N", "st": "Jdt 2:13", "t": "καὶ σὺ δὲ οὐ παραβήσῃ ἕν τι τῶν ῥημάτων τοῦ κυρίου σου, ἀλλὰ ἐπιτελῶν ἐπιτελέσεις καθότι προστέταχά σοι, καὶ οὐ μακρυνεῖς τοῦ ποιῆσαι αὐτά."}, {"sp": "N", "st": "Jdt 2:14", "t": "Καὶ ἐξῆλθεν Ὀλοφέρνης ἀπὸ προσώπου τοῦ κυρίου αὐτοῦ, καὶ ἐκάλεσεν πάντας τοὺς δυνάστας καὶ τοὺς στρατηγοὺς καὶ ἐπιστάτας τῆς δυνάμεως Ἀσσούρ,"}, {"sp": "N", "st": "Jdt 2:15", "t": "καὶ ἠρίθμησεν ἐκλεκτοὺς ἄνδρας εἰς παράταξιν, καθότι ἐκέλευσεν αὐτῷ ὁ κύριος αὐτοῦ, εἰς μυριάδας δέκα δύο καὶ ἱππεῖς τοξότας μυρίους δισχιλίους,"}, {"sp": "N", "st": "Jdt 2:16", "t": "καὶ διέταξεν αὐτοὺς ὃν τρόπον πολέμου πλῆθος συντάσσεται."}, {"sp": "N", "st": "Jdt 2:17", "t": "καὶ ἔλαβεν καμήλους καὶ ὄνους καὶ ἡμιόνους εἰς τὴν ἀπαρτίαν αὐτῶν, πλῆθος πολὺ σφόδρα, καὶ πρόβατα καὶ βόας καὶ αἶγας εἰς τὴν παρασκευὴν αὐτῶν ὦν οὐκ ἦν ἀριθμός,"}, {"sp": "N", "st": "Jdt 2:18", "t": "καὶ ἐπισιτισμὸ παντὶ ἀνδρὶ εἰς πλῆθος, καὶ χρυσίον καὶ ἀργύριον ἐξ οἴκου βασιλέως σφόδρα."}, {"sp": "N", "st": "Jdt 2:19", "t": "καὶ ἐξῆλθεν αὐτὸς καὶ πᾶσα ἡ δύναμις αὐτοῦ εἰς πορείαν τοῦ προελθεῖν βασιλέως Ναβουχοδονοσὸρ καὶ καλύψαι πᾶν τὸ πρόσωπον τῆς γῆς πρὸς δυσμαῖς ἐν ἄρμασι καὶ ἱππεῦσι καὶ πεζοῖς ἐπιλέκτοις αὐτῶν."}, {"sp": "N", "st": "Jdt 2:20", "t": "καὶ πολὺς ὁ ἐπίμικτος ὡς ἀκρὶς συνεξῆλθον αὐτοῖς, καὶ ὡς ἡ ἄμμος τῆς γῆς, οὐ γὰρ ἦν ἀριθμὸς ἀπὸ πλήθους αὐτῶν."}, {"sp": "N", "st": "Jdt 2:21", "t": "καὶ ἐπῆλθον ἐκ Νινευὴ ὁδὸν τριῶν ἡμερῶν ἐπὶ πρόσωπον τοῦ πεδίου Βαικτειλαίθ, καὶ ἐπεστρατοπέδευσαν ἀπὸ Βαικτειλαὶθ πλησίον τοῦ ὄρους τοῦ ἐπʼ ἀριστερᾷ τῆς ἄνω Κιλικίας."}, {"sp": "N", "st": "Jdt 2:22", "t": "καὶ ἔλαβεν πᾶσαν τὴν δύναμιν αὐτοῦ, τοὺς πεζοὺς καὶ τοὺς ἱππεῖς καὶ τὰ ἄρματα αὐτοῦ, καὶ ἀπῆλθεν ἐκεῖθεν εἰς τὴν ὀρινήν."}, {"sp": "N", "st": "Jdt 2:23", "t": "καὶ διέκοψεν τὸ Φοὺδ καὶ Λούδ, καὶ ἐπρονόμευσαν υἱοὺς πάντας Ῥασσεὶς καὶ υἱοὺς Ἰσμαὴλ τοὺς κατὰ πρόσωπον τῆς ἐρήμου πρὸς νότον τῆς Χαλδαίων."}, {"sp": "N", "st": "Jdt 2:24", "t": "καὶ παρῆλθεν τὸν Εὐφράτην καὶ διῆλθεν τὴν Μεσοποταμίαν, καὶ διέσκαψε πάσας τὰς πόλεις τὰς ὑψηλὰς τὰς ἐπὶ τοῦ χειμάρρου Ἀβρωνά ἕως τοῦ ἐλθεῖν ἐπὶ θάλασσαν."}, {"sp": "N", "st": "Jdt 2:25", "t": "καὶ κατελάβετο τὰ ὅρια τῆς Κιλικίας, καὶ κατέκοψε πάντας τοὺς ἀντιστάντας αὐτῷ, καὶ ᾖλ. θεν ἕως ὁρίων Ἰάφεθ τὰ πρὸς νότον κατὰ πρόσωπον τῆς Ἀραβίας."}, {"sp": "N", "st": "Jdt 2:26", "t": "καὶ ἐκύκλωσεν πάντας τοὺς υἱοὺς Μαδιάμ, καὶ ἐνέπρησεν τὰ σκηνώματα αὐτῶν, καὶ ἐπρονόμευσεν τὰς μάνδρας αὐτῶν."}, {"sp": "N", "st": "Jdt 2:27", "t": "καὶ κατέβη εἰς πεδίον Δαμασκοῦ ἐν ἡμέραις θερισμοῦ πυρῶν καὶ ἐνέπρησεν πάντας τοὺς ἀγροὺς αὐτῶν, τὰ ποίμνια καὶ τὰ βουκόλια ἔδωκεν εἰς ἀφανισμόν, καὶ τὰς πόλεις αὐτῶν ἐσκύλευσεν καὶ τὰ πεδία αὐτῶν ἐξελίκμησεν, καὶ ἐπάταξεν πάντας τοὺς νεανίσκους αὐτῶν ἐν στόματι ῥομφαίας."}, {"sp": "N", "st": "Jdt 2:28", "t": "Καὶ ἐπέπεσεν φόβος καὶ τρόμος αὐτοῦ ἐπὶ τοὺς κατοικοῦντας τὴν παραλίαν, τοὺς ὄντας ἐν Σιδῶνι καὶ Τύρῳ, καὶ τοὺς κατοικοῦντας Ἀσσοὺρ καὶ Ὀκεινά, καὶ πάντας τοὺς κατοικοῦντας Ἰεμνάαν, καὶ οἱ κατοικοῦντες ἐν Ἀζώτῳ καὶ Ἀσκάλωνι ἐφοβήθησαν αὐτὸν σφόδρα."}, {"sp": "N", "st": "Jdt 3:1", "t": "Καὶ ἀπέστειλαν πρὸς αὐτὸν ἀγγέλους λόγοις εἰρηνικοῖς λέγοντες ² Ἰδοὺ ἡμεῖς οἱ παῖδες Ναβουχοδονοσὸρ βασιλέως μεγάλου παρακείμεθα ἐνώπιόν σου, χρῆσαι ἡμῖν καθὼς ἀρεστόν ἐστιν τῷ προσώπῳ σου·"}, {"sp": "N", "st": "Jdt 3:3", "t": "ἰδοὺ αἱ ἐπαύλεις ἡμῶν καὶ πᾶν πεδίον πυρῶν καὶ τὰ ποίμνια καὶ τὰ βουκόλια καὶ πᾶσαι αἱ μάνδραι τῶν σκηνῶν ἡμῶν παράκεινται πρὸ προσώπου σου, χρῆσαι καθʼ ὃ ἂν ἀρέσκῃ σοι·"}, {"sp": "N", "st": "Jdt 3:4", "t": "ἰδοὺ καὶ αἱ πόλεις ἡμῶν καὶ οἱ κατοικοῦντες ἐν αὐταῖς δοῦλοι σοί εἰσιν, ἐλθλὼν ἀπάντησον αὐταῖς ὡς ἔστιν ἀγαθὸν ἐν ὀφθαλμοῖς σου."}, {"sp": "N", "st": "Jdt 3:5", "t": "καὶ παρεγένοντο οἱ ἄνδρες πρὸς Ολοφέρνην καὶ ἀπήγγειλαν αὐτῷ κατὰ τὰ ῥήματα ταῦτα."}, {"sp": "N", "st": "Jdt 3:6", "t": "καὶ κατέβη ἐπὶ τὴν παραλίαν αὐτὸς καὶ ἡ δύναμις αὐτοῦ, καὶ ἐφρούρωσε τὰς πόλεις τὰς ὑψηλάς, καὶ ἔλαβον ἐξ αὐτῶν εἰς συμμαχίαν ἄνδρας ἐπιλέκτους·"}, {"sp": "N", "st": "Jdt 3:7", "t": "καὶ ἐδέξαντο αὐτὸν αὐτοὶ καὶ πᾶσα ἡ περίχωρος αὐτῶν μετὰ στεφάνων καὶ χορῶν καὶ τυμπάνων."}, {"sp": "N", "st": "Jdt 3:8", "t": "καὶ κατέσκαψεν πάντα τὰ ὅρια οὐτῶν, καὶ τὰ ἄλση αὐτῶν ἐξέκοψεν· καὶ ἦν δεδομένον αὐτῷ ἐξολεθρεῦσαι πάντας τοὺς θεοὺς τῆς γῆς, ὅπως αὐτῷ μόνῳ τῷ Ναβουχοδονοσὸρ λατρεύωσι πάντα τὰ ἔθνη, καὶ πᾶσαι αἱ γλῶσσαι καὶ πᾶσαι αἱ φυλαὶ αὐτῶν ἐπικαλέσωνται αὐτὸν εἰς θεόν."}, {"sp": "N", "st": "Jdt 3:9", "t": "καὶ ἦλθεν κατὰ πρόσωπον Ἐσδραηλὼν πλησίον τῆς Δωταίας, ἥ ἐστιν ἀπέναντι τοῦ πρίονος τοῦ μεγάλου τῆς Ἰουδαίας,"}, {"sp": "N", "st": "Jdt 3:10", "t": "καὶ κατεστρατοπέδευσαν ἀνὰ μέσον Γαιβαὶ καὶ Σκυθῶν πόλεως, καὶ ἦν ἐκεῖ μῆνα ἡμερῶν εἰς τὸ συλλέξαι πᾶσαν τὴν ἀπαρτίαν τῆς δυνάμεως αὐτοῦ."}, {"sp": "N", "st": "Jdt 4:1", "t": "Καὶ ἤκουσαν οἱ υἱοὶ Ἰσραὴλ οἱ κατοικοῦντες ἐν τῇ Ἰουδαίᾳ πάντα ὅσα ἐποίησεν Ὀλοφέρνης τοῖς ἔθνεσιν, ὁ ἀρχιστράτηγος Ναβουχοδονοσὸρ βασιλέως Ἀσσυρίων, καὶ ὃν τρόπον ἐσκύλευσεν πάντα τὰ ἱερὰ αὐτῶν καὶ ἔδωκεν αὐτὰ εἰς ἀφανισμόν·"}, {"sp": "N", "st": "Jdt 4:2", "t": "καὶ ἐφοβήθησαν σφόδρα σφόδρα ἀπὸ προσώπου αὐτοῦ, καὶ περὶ Ἰερουσαλὴμ καὶ τοῦ ναοῦ Κυρίου θεοῦ αὐτῶν ἐταράχθησαν."}, {"sp": "N", "st": "Jdt 4:3", "t": "ὅτι προσφάτως ἦσαν ἀναβεβηκότες ἐκ τῆς αἰχμαλωσίας, καὶ νεωστὶ πᾶς ὁ λαὸς συνελέλεκτο τῆς Ἰουδαίας, καὶ τὰ σκεύη καὶ τὸ θυσιαστήριον καὶ ὁ οἶκος ἐκ τῆς βεβηλώσεως ἡγιασμένα ἦν."}, {"sp": "N", "st": "Jdt 4:4", "t": "καὶ ἀπέστειλαν εἰς πᾶν ὅριον Σαμαρίας· καὶ Κωνὰ καὶ Βαιθωρὼν αὶ Βαιλμάιν καὶ Ἰερειχὼ καὶ εἰς Χωβὰ καὶ Αἱσωρὰ καὶ τὸν αὐλῶνα Σαλήμ,"}, {"sp": "N", "st": "Jdt 4:5", "t": "καὶ προκατελάβοντο πάσας τὰς κορυφὰς τῶν ὀρέων τῶν ὑψηλῶν, (4)καὶ ἐτειχίσαντο τὰς ἐν αὐτοῖς κώμας, καὶ παρέθεντο εἰς ἐπισιτισμὸν εἰς παρασκευὴν πολέμου, ὅτι προσφάτως ἦν τὰ πεδία αὐτῶν τεθερισμένα."}, {"sp": "N", "st": "Jdt 4:6", "t": "καὶ ἔγραψεν Ἰωακεὶμ ὁ ἱερεὺς ὁ μέγας, ὃς ἦν ἐν ταῖς ἡμέραις ἐν Ἰερουσαλήμ, τοῖς κατοικοῦσι Βαιτουλουὰ καὶ Βαιτομαισθάιμ, ἥ ἐστιν ἀπέναντι Ἐσρηλὼν κατὰ πρόσωπον τοῦ πεδίου τοῦ πλησίον Δωθάειμ,"}, {"sp": "N", "st": "Jdt 4:7", "t": "λέγων διακατασχεῖν τὰς ἀναβάσεις τῆς ὀρινῆς, ὅτι δι᾿ αὐτῶν ἦν ἡ εἴσοδος εἰς τὴν Ἰουδαίαν· καὶ ἦν εὐχερῶς διακωλῦσαι αὐτοὺς προσβαίνοντας, στενῆς τῆς προσβάσεως οὔσης, ἐπ᾿ ἄνδρας τοὺς πάντας δύο."}, {"sp": "N", "st": "Jdt 4:8", "t": "καὶ ἐποίησαν οἱ υἱοὶ Ἰσραὴλ καθὰ συνέταξεν αὐτοῖς Ἰωακεὶμ ὁ ἱερεὺς ὁ μέγας καὶ ἡ γερουσία παντὸς δήμου Ἰσραὴλ οἳ ἐκάθηντο ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "Jdt 4:9", "t": "Καὶ ἀνεβόησαν πᾶς ἀνὴρ Ἰσραὴλ πρὸς τὸν θεὸν ἐν ἐκτενείᾳ μεγάλῃ, καὶ ἐταπεινοῦσαν τὰς ψυχὰς αὐτῶν ἐν ἐκτενείᾳ μεγάλῃ,"}, {"sp": "N", "st": "Jdt 4:10", "t": "αὐτοὶ καὶ αἱ γυναῖκες αὐτῶν (9b) καὶ τὰ νήπια αὐτῶν καὶ τὰ κτήνη αὐτῶν· καὶ πᾶς πάροικος ἢ μισθωτὸ καὶ ἀργυρώνητος αὐτῶν ἐπέθεντο σάκκους ἐπὶ τὰς ὀσφύας αὐτῶν."}, {"sp": "N", "st": "Jdt 4:11", "t": "καὶ πᾶς ἀνήρ Ἰσραὴλ καὶ γυνὴ καὶ παιδία, οἱ κατοικοῦντες ἐν Ἰερουσαλήμ, ἔπεσον κατὰ πρόσωπον τοῦ ναοῦ, καὶ ἐσποδώσαντο τὰς κεφαλὰς αὐτῶν, καὶ ἐξέτειναν τοὺς σάκκους αὐτῶν κατὰ πρόσωπον Κυρίου,"}, {"sp": "N", "st": "Jdt 4:12", "t": "καὶ τὸ θυσιαστήριον σάκκῳ περιέβαλλον· (10b)καὶ ἐβόησαν πρὸς τὸν θεὸν Ἰσραὴλ ὁμοθυμαδὸν ἐκτενῶς, τοῦ μὴ δοῦναι εἰς διαρπαγὴν τὰ νήπια αὐτῶν καὶ τὰς γυναῖκας εἰς προνομὴν καὶ τὰς πόλεις τῆς κληρονομίας αὐτῶν εἰς ἀφανισμὸν καὶ τὰ ἅγια εἰς βεβήλωσιν καὶ ὀνειδισμόν, ἐπίχαρμα τοῖς ἔθνεσιν."}, {"sp": "N", "st": "Jdt 4:13", "t": "καὶ εὰτήκουσεν Κύριος τῆς φωνῆς αὐτῶν καὶ ἐσεῖδεν τὴν θλίψιν αὐτῶν· καὶ ἣν ὁ λαὸς νηστεύων ἡμέρας πλείους ἐν πάσῃ τῇ Ἰουδαίᾳ καὶ Ἰερουσαλὴμ κατὰ πρόσωπον τῶν ἁγίων Κυρίου Παντοκράτορος."}, {"sp": "N", "st": "Jdt 4:14", "t": "καὶ Ἰωακεὶμ ὁ ἱερεὺς ὁ μέγας καὶ πάντες οἵ παρεστηκότες ἐνώπιον Κυρίου, ἱερεῖς καὶ οἱ λειτουργοῦντες Κυρίῳ, σάκκους περιεζωσμένοι τὰς ὀσφύας αὐτῶν προσέφερον τὴν ὁλοκαύτωσιν τοῦ ἐνδελεχισμοῦ καὶ τὰς. εὐχὰς καὶ τὰ ἑκούσια δόματα τοῦ λαοῦ,"}, {"sp": "N", "st": "Jdt 4:15", "t": "καὶ ἦν σποδὸς ἐπὶ τὰς κιδάρεις αὐτῶν· καὶ ἐβόων πρὸς Κύριον ἐκ πάσης δυνάμεως, εἰς ἀγαθὸν ἐπισκέψασθαι πᾶν οἶκον Ἰσραήλ."}, {"sp": "N", "st": "Jdt 5:1", "t": "Καὶ ἀνηγγέλη Ὀλοφέρνῃ ἀρχιστρατήγῳ δυνάμεως Ἀσσοὺρ διότι οἱ υἱοὶ Ἰσραὴλ παρεσκευάσαντο εἰς πόλεμον, καὶ τὰς διόδους τῆς ὐρινῆς συνέκλεισαν καὶ ἐτείχισαν πᾶσαν κορυφὴν ὄρους ὑψηλοῦ, καὶ ἔθηκαν ἐν τοῖς πεδίοις σκάνδαλα."}, {"sp": "N", "st": "Jdt 5:2", "t": "καὶ ὠργίσθη θυμῷ σφόδρα, καὶ ἐκάλεσεν πάντας τοὺς ἄρχοντας Μαωὰβ καὶ τοὺς στρατηγοὺς Ἀμμὼν καὶ πάντας σατράπας τῆς παραλίας,"}, {"sp": "N", "st": "Jdt 5:3", "t": "καὶ εἶπεν αὐτοῖς Ἀναγγείλατε δή μοι, υἱοὶ Χανάαν, τίς ὁ λαὸς οὗτος ὁ καθήμενος ἐν τῇ ὀρίνῆ, καὶ τίνες ἃς κατοικοῦσιν πόλεις, καὶ τὸ πλῆθος τῆς δυνάμεως αὐτῶν, καὶ ἐν τίνι τὸ κράτος αὐτῶν καὶ ἡ ἰσχὺς αὐτῶν, καὶ τίς ἀνέστηκεν ἐπʼ αὐτῶν βασιλεὺς ἡγούμενος στρατιᾶς αὐτῶν,"}, {"sp": "N", "st": "Jdt 5:4", "t": "καὶ διὰ τί κατενωτίσαντο τοῦ μὴ ἐλθεῖν εἰς ἀπάντησίν μοι παρὰ πάντας τοὺς κατοικοῦντας ἐν δυσμαῖς."}, {"sp": "N", "st": "Jdt 5:5", "t": "Καὶ εἶπεν πρὸς αὐτὸν Αχιὼρ ὁ ἡγούμενος πάντων υἱῶν Ἀμμών Ἀκουσάτω δὴ λόγον ὁ κύριός μου ἐκ στόματος τοῦ δούλου σου, καὶ ἀναγγελῶ σοι τὴν ἀλήθειαν περὶ τοῦ λαοῦ ὃς κατοικεῖ τὴν ὀρινὴν ταύτην πλησίον σοῦ οἰκοῦντος, καὶ οὐκ ἐξελεύσεται ψεῦδος ἐκ τοῦ στόματος τοῦ δούλου σου."}, {"sp": "N", "st": "Jdt 5:6", "t": "ὁ λαὸς οὗτός εἰσιν ἀπόγονοι Χαλδαίων·"}, {"sp": "N", "st": "Jdt 5:7", "t": "καὶ παρῴκησαν τὸ πρότερον ἐν τῇ Μεσοποταμίᾳ, ὅτι οὐκ ἐβουλήθησαν ἀκολουθῆσαι τοῖς θεοῖς τῶν πατέρων αὐτῶν οἱ ἐγένοντο ἐν γῇ Χαλδαίων."}, {"sp": "N", "st": "Jdt 5:8", "t": "ἐξέβησαν ἐξ ὁδοῦ τῶν γονέων αὐτῶν (9)καὶ προσεκύνησαν τῷ θεῷ τοῦ οὐρανοῦ, θεῷ ᾧ ἐπέγνωσαν· καὶ ἐξέβαλον αὐτοὺς ἀπὸ προσώπου τῶν θεῶν αὐτῶν, καὶ ἔφυγον εἰς Μεσοποταμίαν, καὶ παρῴκησαν ἐκεῖ ἡμέρας πολλάς."}, {"sp": "N", "st": "Jdt 5:9", "t": "καὶ εἶπεν ὁ θεὸς αὐτῶν ἐξελθεῖν ἐκ τῆς παροικίας αὐτῶν καὶ πορευθῆναι εἰς γῆν Χανάαν· καὶ κατῴκησαν ἐκεῖ, καὶ ἐπληθύνθησαν χρυσίῳ καὶ ἀργυρίῳ καὶ ἐν κτήνεσιν πολλοῖς σφόδρα."}, {"sp": "N", "st": "Jdt 5:10", "t": "καὶ κατέβησαν εἰς Αἴγυπτον, ἐκάλυψεν γὰρ τὸ πρόσωπον τῆς γῆς Χανάαν λιμός, καὶ παρῴκησαν ἐκεῖ μέχρις οὗ διετράφησαν· καὶ ἐγένοντο ἐκεῖ εἰς πλῆθος πολύ, καὶ οὐκ ἣν ἀριθμὸς τοῦ γένους αὐτῶν."}, {"sp": "N", "st": "Jdt 5:11", "t": "καὶ ἐπανέστη αὐτοῖς ὁ βασιλεὺς Αἰγύπτου, καὶ κατεσοφίσαντο αὐτοὺς ἐν πόνῳ καὶ πλίνθῳ, ἐταπείνωσαν αὐτοὺς καὶ ἔθεντο αὐτοὺς εἰς δούλους."}, {"sp": "N", "st": "Jdt 5:12", "t": "καὶ ἀνεβόησαν πρὸς τὸν θεὸν αὐτῶν, καὶ ἐπάταξεν γῆν Αἰγύπτου πληγαῖς ἐν αἷς οὐκ ἦν ἴασις· (¹¹ª)καὶ ἐξέβαλον αὐτοὺς οἱ Αἰγύπτιοι ἀπὸ προσώπου αὐτῶν."}, {"sp": "N", "st": "Jdt 5:13", "t": "καὶ κατεξήρανεν ὁ θεὸς τὴν ἐρυθρὰν θάλασσαν ἔμπροσθεν αὐτῶν,"}, {"sp": "N", "st": "Jdt 5:14", "t": "καὶ ἤγαγεν αὐτοὺς εἰς ὁδὸν τοῦ Σεινὰ καὶ Καδὴς Βαρνή· καὶ ἐξέβαλον πάντας τοὺς κατοικοῦντας ἐν τῇ ἐρήμῳ,"}, {"sp": "N", "st": "Jdt 5:15", "t": "καὶ ιᾤκησαν ἐν γῇ Ἀμορραίων, καὶ πάντας τοὺς Ἑσεβωνείτας ἐξωλέθρευσαν ἐν τῇ ἰσχύι αὐτῶν· καὶ διαβάντες τὸν Ἰορδάνην ἐκληρονόμησαν πᾶσαν τὴν ὀρινήν."}, {"sp": "N", "st": "Jdt 5:16", "t": "καὶ ἐξέβαλον ἐκ προσώπου αὐτῶν τὸν Χαναναῖον καὶ τὸν Φερεζαῖον καὶ τὸν Ἰεβουσαῖον καὶ τὸν Συχέμ καὶ πάντας τοὺς Γεργεσαίους, καὶ κατῴκησαν ἐν αὐτῇ ἡμέρας πολλάς."}, {"sp": "N", "st": "Jdt 5:17", "t": "καὶ ἕως οὐχ ἥμαρτον ἐνώπιον τοῦ θεοῦ αὐτῶν, ἦν μετʼ αὐτῶν τὰ ἀγαθά, ὅτι θεὸς μισῶν ἀδικίαν μετʼ αὐτῶν ἐστίν·"}, {"sp": "N", "st": "Jdt 5:18", "t": "ὅτε δὲ ἀπέστησαν ἀπὸ τῆς ὁδοῦ ἧς διέθετο αὐτοῖς, ἐξωλεθρεύθησαν ἐν πολλοῖς πολέμοις ἐπὶ πολὺ σφόδρα, καὶ ᾐχμαλωτεύθησαν εἰς γῆν οὐκ ἰδίαν, καὶ ὁ ναὸς τοῦ θεοῦ αὐτῶν ἐγενήθη εἰς ἔδαφος, καὶ αἱ πόλεις αὐτῶν ἐκρατήθησαν ὑπὸ τῶν ὑπεναντίων."}, {"sp": "N", "st": "Jdt 5:19", "t": "καὶ νῦν ἐπιστρέψαντες ἐπὶ τὸν θεὸν αὐτῶν ἀνέβησαν ἐκ τῆς διασπορᾶς οὗ διεσπάρησαν ἐκεῖ, κατέσχον τὴν Ἰερουσαλὴμ οὗ τὸ ἁγίασμα αὐτῶν, καὶ κατῳκίσθησαν ἐν τῇ ὀρίνῇ, ὅτι ἦν ἔρημος."}, {"sp": "N", "st": "Jdt 5:20", "t": "καὶ νῦν, δέσποτα κύριε, εἰ μέν ἐστιν ἀγνόημα ἐν τῷ λαῷ τούτῳ καὶ ἁμαρτάνουσιν εἰς τὸν θεὸν αὐτῶν, καὶ ἐπισκεψόμεθα ὅτι ἐστὶν ἐν αὐτοῖς σκάνδαλον τοῦτο, καὶ ἀναβησόμεθα καὶ ἐκπολεμήσομεν αὐτούς·"}, {"sp": "N", "st": "Jdt 5:21", "t": "εἰ δ᾿ οὐκ ἔστιν ἀνομία ἐν τῷ ἔθνει αὐτῶν, παρελθέτω δὴ ὁ κύριος, μὴ ποτε ὑπερασπίσῃ ὁ κύριος αὐτῶν καὶ ὁ θεὸς αὐτῶν ὑπέρ αὐτῶν, καὶ ἐσόμεθα εἰς ὀνειδισμὸν ἐναντίον πάσης τῆς γῆς."}, {"sp": "N", "st": "Jdt 5:22", "t": "Καὶ ἐγένετο ὡς ἐπαύσατο Ἀχιὼρ λαλῶν τοὺς λόγους τούτους, καὶ ἐγόγγυσεν πᾶς ὁ λαὸς ὁ κυκλῶν τὴν σκηνὴν καὶ περιεστώς· καὶ εἶπαν οἱ μεγιστᾶνες Ὀλοφέρνου καὶ πάντες οἱ κατοικοῦντες τὴν παραλίαν καὶ τὴν Μωὰβ συγκόψαι αὐτόν"}, {"sp": "N", "st": "Jdt 5:23", "t": "Οὐ γὰρ φοβηθησόμεθα ἀπὸ υἱῶν Ἰσραήλ· ἰδοὺ γὰρ λαὸς ἐν ᾧ οὐκ ἔστιν δύναμις οὐδέ κράτος εἰς παράταξιν ἰσχυράν."}, {"sp": "N", "st": "Jdt 5:24", "t": "διὸ δὴ ἀναβησόμεθα, καὶ ἔσονται εἰς κατάβρωμα πάσης τῆς στρατείας σου, δέσποτα Ὀλὸφέρνη."}, {"sp": "N", "st": "Jdt 6:1", "t": "Καὶ ὡς κατέπαυσεν ὁ θόρυβος τῶν ἀνδρῶν τῶν κύκλῳ τῆς συνεδρίας, εἶπεν Ὀλοφέρνης ἀρχιστράτηγος δυνάμεως Ἀσσοὺρ πρὸς Ἀχιὼρ ἐνανπίον παντὸς τοῦ δήμου ἀλλοφύλων"}, {"sp": "N", "st": "Jdt 6:2", "t": "Καὶ τίς εἶ σὺ Ἀχιὼρ καὶ πρὸς πάντας υἱοὺς Μωὰβ καὶ οἱ μισθωτοὶ Ἐφράιμ, (²)ὅτι ἐπροφήτευσας ἐν ἡμῖν καθὼς σήμερον, καὶ εἶπας τὸ γένος Ἰσραὴλ μὴ πολεμῆσαι, ὅτι θεὸς αὐτῶν ὑπερασπιεῖ αὐτῶν ; καὶ τίς ὁ θεὸς εἰ μὴ Ναβουχοδονοσόρ ; οὗτος ἀποστελεῖ τὸ κράτος αὐτοῦ καὶ ἐξολεθρεύσει αὐτοὺς ἀπὸ προσώπου τῆς γῆς, καὶ οὐ ῥύσεται αὐτοὺς ὁ θεὸς αὐτῶν·"}, {"sp": "N", "st": "Jdt 6:3", "t": "ἀλλʼ ἡμεῖςοἱ δοῦλοι αὐτοῦ πατάξομεν αὐτοὺς ὡς ἄνθρωπον ἕνα, καὶ οὐχ ὑποστήσονται τὸ κράτος τῶν ἵππων ἡμῶν."}, {"sp": "N", "st": "Jdt 6:4", "t": "κατακαύσομεν γὰρ αὐτοὺς ἐν αὐτοῖς, καὶ τὰ ὅρια αὐτῶν μεθυσθήσεται ἐν τῷ αἵματι 0οὕτων, καὶ τὰ πεδία αὐτῶν πληρωθήσεται νεκρῶν αὐτῶν· καὶ οὐκ ἀντιστήσεται τὸ ἴχνος τῶν ποδῶν αὐτῶν κατὰ πρόσωπον ἡμῶν, ἀλλ᾿ ἀπωλείᾳ ἀπολοῦνται, λέγει ὁ βασιλεὺς (⁴ª)Ναβουχοδονοσόρ, ῥήματα τῶν λόγων αὐτοῦ."}, {"sp": "N", "st": "Jdt 6:5", "t": "σὺ δὲ Ἀχιώρ, μισθωτὲ τοῦ Ἀμμών. ὃς ἐλάλησας τοὺς λόγους τούτους ἐν ἡμέρᾳ ἀδικίας σου, οὐκ ὄψῃ ἔτι τὸ πρόσωπόν μου ἀπὸ τῆς ἡμέρας ταύτης ἕως οὗ ἐκδικήσω τὸ γένος τῶν ἐξ Αἰγύπτου·"}, {"sp": "N", "st": "Jdt 6:6", "t": "καὶ τότε διελεύσεται ὁ σίδηρος τῆς στρατείας μου καὶ ὁ λαὸς τῶν θεραπόντων μου τὰς πλευράς σου, καὶ πεσῇ ἐν τοῖς τραυματίαις αὐτῶν ὅταν ἐπιστρέψωσιν·"}, {"sp": "N", "st": "Jdt 6:7", "t": "καὶ ἀποκαταστήσουσίν σε οἱ δοῦλοί μου εἰς τὴν ὀρινὴν καὶ θήσουσίν σε ἐν μιᾷ τῶν πόλεων τῶν ἀναβάσεων,"}, {"sp": "N", "st": "Jdt 6:8", "t": "καὶ οὐκ ἀπολῇ ἕως οὗ ἐξολεθρευθῇς μετʼ αὐτῶν."}, {"sp": "N", "st": "Jdt 6:9", "t": "καὶ εἴπερ ἐλπίζεις τῇ καρδίᾳ σου ὅτι οὐ λημφθήσονται, μὴ συμπεσέτω σου τὸ πρόσωπον. ἐλάλησα, καὶ οὐδέν διαπεσεῖται τῶν ῥημάτων μου."}, {"sp": "N", "st": "Jdt 6:10", "t": "Καὶ προσἐταξεν Ὀλοφέρνης τοῖς δούλοις αὐτοῦ, οἱ ἦσαν παρεστηκότες ἐν τῇ σκηνῇ αὐτοῦ, συλλαβεῖυ τὸν Ἀχιὼρ καὶ ἀποκαταστῆσαι οὐτὸν εἰς Βετυλουὰ καὶ παραδοῦναι εἰς χεῖρας υἱῶν Ἰσραήλ."}, {"sp": "N", "st": "Jdt 6:11", "t": "καὶ συνέλαβον αὐτὸν οἱ δοῦλοι αὐτοῦ καὶ ἤγαγον αὐτὸν ἔξω τῆς παρεμβολῆς εἰς τὸ πεδίον, καὶ ἀπῆραν ἐκ μέσου τῆς πεδινῆς εἰς τὴν ὀρινήν, καὶ παρεγένοντο ἐπὶ τὰς πηγὰς αἱ ἦσαν ὑποκάτω Βετυλουά."}, {"sp": "N", "st": "Jdt 6:12", "t": "καὶ ὡς ἴδαν αὐτοὺς οἱ ἄνδρες τῆς πόλεως ἐπὶ τὴν κορυφὴν τοῦ ὄρους, ἀνέλαβον τὰ ὅπλα αὐτῶν καὶ ἐπῆλθον ἔξω τῆς πόλεως ἐπὶ τὴν κορυφὴν τοῦ ὄρους· καὶ πᾶς ἀνὴρ σφενδονήτης διεκράτησαν τὴν ἀνάβασιν αὐτῶν καὶ ἔβαλλον ἐν λίθοις (9) 13 ἐπʼ αὐτοὺς."}, {"sp": "N", "st": "Jdt 6:13", "t": "καὶ ὑποδύσαντες ὑποκάτω τοῦ ὄρους ἔδησαν τὸν Ἀχιὼρ καὶ ἀφῆκαν ἐρριμμένον ὑπὸ τὴν ῥίζαν τοῦ ὄρους. καὶ ἀπῴχοντο πρὸς τὸν κύριον αὐτῶν."}, {"sp": "N", "st": "Jdt 6:14", "t": "καταβάντες δὲ οἱ υἱοὶ Ἰσραὴλ ἐκ τῆς πόλεως αὐτῶν ἐπέστησαν αὐτῷ, καὶ λύσαντες αὐτὸν ἀπήγαγον εἰς τὴν Βετυλουά, καὶ κατέσπησαν αὐτὸν ἐπὶ τοὺς ἄρχοντας τῆς πόλεως αὐτῶν,"}, {"sp": "N", "st": "Jdt 6:15", "t": "οἳ ἧκαν ἐν ταῖς ἡμέραις ἐκείναις Ὀζείας ὁ τοῦ Μειχὰ ἐκ τῆς φυλῆς Συμεὼν καὶ Χαβρεὶς ὁ τοῦ Γοθονιὴλ καὶ Χαρμεὶς υἱὸς Μελχειήλ."}, {"sp": "N", "st": "Jdt 6:16", "t": "καὶ συνεκάλεσεν πάντας τοὺς πρεσβυτέρους τῆς πόλεως, καὶ συνέδραμον πᾶς νεανίσκος αὐτῶν καὶ αἱ γυυαῖκες εἰς τὴν ἐκκλησίαν, καὶ ἔστησαν τὸν Ἀχιὼρ ἐν μέσῳ παντὸς τοῦ λαοῦ αὐτῶν, καὶ ἐπηρώτησεν αὐτὸν Ὀζείας τὸ συμβεβηκός."}, {"sp": "N", "st": "Jdt 6:17", "t": "καὶ ἀποκριθεὶς ἀπήγγειλεν αὐτοῖς τὰ ἀήματα τῆς συνεδρείας Ολοφέρνου, καὶ πάντα τὰ φήματα ὅσα ἐλάλησεν ἐν μἐσῳ τῶν ἀρχόντων υἱῶν Ἀσσούρ, καὶ ὅσα ἐμεγαλορημόνησεν λοφέρνης εἰς τὸν οἶκον Ἰσραήλ."}, {"sp": "N", "st": "Jdt 6:18", "t": "καὶ πεσόντες ὁ λαὸς προσεκύνησαν τῷ θεῷ, καὶ ἐβόησαν λέγοντες"}, {"sp": "N", "st": "Jdt 6:19", "t": "Κύριε ὁ θεὸς τοῦ οὐρανοῦ, κάτιδε ἐπὶ τὰς ὑπερηφανίας αὐτῶν, καὶ ἐλέησον τὴν ταπείνωσιν τοῦ γένους ἡμῶν, καὶ ἐπίβλεψον ἐπὶ τὸ πρόσωπον τῶν ἡγιασμένων σοι ἐν τῇ ἡμέρᾳ ταύτῃ."}, {"sp": "N", "st": "Jdt 6:20", "t": "καὶ παρεκάλεσαν τὸν Ἀχιώρ, καὶ ἐπήνεσαν αὐτὸν σφόδρα."}, {"sp": "N", "st": "Jdt 6:21", "t": "καὶ παρέλαβεν αὐτὸν Ὀζείας ἐκ τῆς ἐκκλησίας εἰς οἶκον αὐτοῦ, καὶ ἐποίησεν πότον τοῖς πρεσβυτέροις· καὶ ἐπεκαλέσαντο τὸν θεὸν Ἰσραὴλ εἰς βοήθειαν ὅλην τὴν νύκτα ἐκείνην."}, {"sp": "N", "st": "Jdt 7:1", "t": "Τῇ δὲ ἐπαύριον παρήγγειλεν Ὀλοφέρνης πάσῃ τῇ στρατείᾳ αὐτοῦ καὶ παντὶ τῷ λαῷ αὐτοῦ οἳ παρεγένοντο ἐπὶ τὴν συμμαχίαν αὐτοῦ, ἀναζευγνύειν ἐπὶ Βαιτυλουὰ καὶ τὰς ἀναβάσεις τῆς ἀρινῆς προκαταλαμβάνεσθαι καὶ ποιεῖν πόλεμον πρὸς τοὺς υἱοὺς Ἰσραήλ."}, {"sp": "N", "st": "Jdt 7:2", "t": "καὶ ἀνέζευξεν ἐν τῇ ἡμέρᾳ ἐκείνῃ πᾶς ἀνὴρ δυνατὸς αὐτῶν· καὶ ἡ δύναμις αὐτῶν ἀνδρῶν πολεμιστῶν χιλιάδες ἀνδρῶν πεζῶν ἑκατὸν ἑβδομήκοντα καὶ ἱππέων χιλιάδες δέκα δύο, χωρὶς τῆς ἀποσκευῆς τῶν ἀνδρῶν οἳ ἦσαν πεζοὶ ἐν αὐτοῖς, πλῆθος πολὺ σφόδρα."}, {"sp": "N", "st": "Jdt 7:3", "t": "καἰ παρενέβαλον ἐν τῷ αὐλῶνι πλησίον Βαιτυλουὰ ἐπὶ τῆς πηγῆς, καὶ παρέτειναν εἰς εἶρος ἐπὶ Δωθάειμ ἕως Βελβάιμ, καὶ εἰς μῆκος ἕως Βαιτυλουὰ ἕως Κυαμῶνος ἥ ἐστιν ἀπέναντι τοῦ Ἐσδρηλών."}, {"sp": "N", "st": "Jdt 7:4", "t": "οἱ δὲ υἱοὶ Ἰσραήλ, ὡς ἴδον αὐτῶν τὸ πλῆθος, ἐταράχθησαν σφόδρα, καὶ εἶπαν ἕκαστος πρὸς τὸν πλησίον αὐτοῦ Νῦν ἐκλίξουσιν οὗτοι τὸ πρόσωπον τῆς γῆς πάσης, καὶ οὔτε τὰ ὄρη τὰ ὑψηλὰ οὔτε αἱ φάραγγες οὕτε οἱ βουνοὶ ὑποστήσονται τὸ βάρος αὐτῶν."}, {"sp": "N", "st": "Jdt 7:5", "t": "καὶ ἀναλαβόντες ἕκαστος τὰ σκεύη τὰ πολεμικὰ αὐτῶν καὶ ἀνακαύσαντες πυρὰς ἐπὶ τοὺς πύργους αὐτῶν ἔμενον φυλάσσοντες ὅλην τὴν νύκτα ἐκείνην."}, {"sp": "N", "st": "Jdt 7:6", "t": "τῇ δὲ ἡμέρᾳ τῇ δευτέρᾳ ἐξήγαγεν λοφέρνης πᾶσαν τὴν ἵππον αὐτοῦ κατὰ πρόσωπον τῶν υἱῶν Ἰσραὴλ οἳ ἤσαν ἐν Βετυλουά,"}, {"sp": "N", "st": "Jdt 7:7", "t": "καὶ ἐπεσκέψατο τὰς ἀναβάσεις τῆς πόλεως αὐτῶν, καὶ τὰς πηγὰς τῶν ὑδάτων ἐφώδευσεν καὶ προκατελάβετο αὐτάς, καὶ ἐπέστησεν αὐταῖς παρεμβολὰς ἀνδρῶν πολεμιστῶν, καὶ αὐτὸς ἀνέζευξεν εἰς τὸν λαὸν αὐτοῦ."}, {"sp": "N", "st": "Jdt 7:8", "t": "Καὶ προσελθόντες αὐτῷ πάντες ἄρχοντες υἱῶν Ἠσαὺ καὶ πάντες οἱ ἡγούμενοι τοῦ λαοῦ Μωὰβ καὶ οἱ στρατηγοὶ τῆς παραλίας εἶπαν"}, {"sp": "N", "st": "Jdt 7:9", "t": "Ἀκουσάτω δὴ λόγον ὁ δεσπότης ἡμῶν, ἵνα μὴ γένηται θραῦσμα ἐν τῇ δυνάμει σου."}, {"sp": "N", "st": "Jdt 7:10", "t": "ὁ γὰρ λαὸς οὗτος τῶν υἱῶν Ἰσραὴλ οὐ πέποιθαν ἐπὶ τοῖς δόρασιν αὐτῶν ἀλλʼ ἐπὶ τοῖς ὕψεσι τῶν ὀρέων αὐτῶν, ἐν οἷς αὐτοὶ ἐνοικοῦσιν ἐν αὐτοῖς· οὐ γὰρ ἔστιν εὐχερὲς προσβῆναι ταῖς κορυφαῖς τῶν ὀρέων αὐτῶν."}, {"sp": "N", "st": "Jdt 7:11", "t": "καὶ νῦν, δέσποτα, μὴ πολέμει πρὸς αὐτοὺς καθὼς γίνεται πόλεμος παρατάξεως, καὶ οὐ πεσεῖται ἐκ τοῦ λαοῦ σου ἀνὴρ εἷς."}, {"sp": "N", "st": "Jdt 7:12", "t": "ἀνάμεινον ἐπὶ τῆς παρεμβολῆς σου, διαφυλάσσων πάντα ἄνδρα ἐκ τῆς δυνάμεώς σου, καὶ ἐπικρατησάτωσαν οἱ παῖδές σου τῆς πηγῆς τοῦ ὕδατος ἣ ἐκπορεύεται ἐκ τῆς ῥίζης τοῦ ὄρους,"}, {"sp": "N", "st": "Jdt 7:13", "t": "διότι ἐκεῖθεν ὑδρεύονται πάντες οἱ κατοικοῦντες Βαιτυλουά, καὶ ἀνελεῖ αὐτοὺς ἡ δίψα, καὶ ἐκδώσουσι τὴν πόλιν αὐτῶν· καὶ ἡμεῖς καὶ ὁ λαὸς ἡμῶν ἀναβησόμεθα ἐπὶ τὰς πλησίον κορυφὰς τῶν ὀρέων, καὶ παρεμβαλοῦμεν ἐπʼ αὐταῖς εἰς προφυλακὴν τοῦ μὴ ἐξελθεῖν ἐκ τῆς πόλεως ἄνδρα ἕνα."}, {"sp": "N", "st": "Jdt 7:14", "t": "καὶ τακήσονται ἐν τῷ λιμῷ αὐτοὶ καὶ αἱ γυναῖκες αὐτῶν καὶ τὰ τέκνα αὐτῶν, καὶ πρὶν ἐλθεῖν τὴν ῥομφαίαν ἐπʼ αὐτοὺς καταστρωθήσονται ἐν ταῖς πλατείαις τῆς οἰκήσεως αὐτῶν·"}, {"sp": "N", "st": "Jdt 7:15", "t": "καὶ ἀνταποδώσεις αὐτοῖς ἀνταπόδομα πονηρὸν ἀνθʼ ὧν ἐστασίασαν καὶ οὐκ ἀπήντησαν τῷ προκώπῳ σου ἐν εἰρήνῃ."}, {"sp": "N", "st": "Jdt 7:16", "t": "Καὶ ἤρεσαν οἱ λόγοι αὐτῶν ἐνώπιον Ὀλοφέρνου καὶ ἐνώπιον πάντων τῶν θεραπόνταων αὐτοῦ, καὶ συνέταξε ποιεῖν καθὰ ἐλάλησαν."}, {"sp": "N", "st": "Jdt 7:17", "t": "καὶ ἀπῆρεν παρεμβολὴ υἱῶν Ἄμμών, καὶ μετʼ αὐτῶν χιλιάδες πέντε υἱῶν Ἀσσούρ, καὶ παρενέβαλον ἐν τῷ αὐλῶνι καὶ προκατελάβοντο τὰ ὕδατα καὶ τὰς πηγὰς τῶν ὑδάτων τῶν υἱῶν Ἰσραήλ."}, {"sp": "N", "st": "Jdt 7:18", "t": "καὶ ἀνέβησαν οἱ υἱοὶ Ησαὺ καἱ οἱ υἱοὶ Ἀμμών, καὶ παρενέβαλον ἐν τῇ ὀρινῃ ἀπέναντι Δωθάειμ, καὶ ἀπέστειλαν ἐξ αὐτῶν πρὸς νότον καὶ ἀπηλιώτην ἀπέναντι Ἐγρεβὴλ ἥ ἐστιν πλησίον Χοὺς ἥ ἐστιν ἐπὶ τοῦ χειμάρρου Μοχμούρ· καὶ ἡ λοιπὴ στρατεία τῶν Ἀσσυρίων παρενέβαλον ἐν τῷ πεδίῳ καὶ ἐκάλυψαν πᾶν τὸ πρόσωπον τῆς γῆς, καὶ αἱ σκηναὶ καὶ αἱ ἀπαρτίαι αὐτῶν κατεστρατοπέδευσαν ἐν ὄχλῳ πολλῷ καὶ ἦσαν εἰς πλῆθος πολὺ σφόδρα."}, {"sp": "N", "st": "Jdt 7:19", "t": "καὶ οἱ υἱοὶ Ἰσραὴλ ἀνεβόησαν πρὸς Κύριον θεὸν αὐτῶν, ὅτι ὠλιγοψύχησεν τὸ πνεῦμα οὐτῶν, ὅτι ἐκύκλωσαν πάντες οἱ ἐχθροὶ αὐτῶν καὶ οὐκ ἦν διαφυγεῖν ἐκ μέσου αὐτῶν."}, {"sp": "N", "st": "Jdt 7:20", "t": "καὶ ἔμεινεν κύκλῳ αὐτῶν πᾶσα παρεμβολὴ Ἀσσούρ, οἱ πεζυὶ καὶ ἄρματα καὶ οἱ ἱππεῖς αὐτῶν, ἡμέρας τριάκοντα τέσσαρες· καὶ ἐξέλειπεν πάντας τοὺς κατοικοῦντας Βαιτυλουὰ πάντα τὰ ἀγγεῖα αὐτῶν τῶν ὑδάτων,"}, {"sp": "N", "st": "Jdt 7:21", "t": "καὶ οἱ λάκκοι ἐξεκενοῦντο, καὶ οὐκ εἶχον πεῖν εἰς πλησμονὴν ὕδωρ ἡμέραν μίαν, ὅτι ἐν μέτρῳ ἐδίδοσαν αὐτοῖς πεῖν."}, {"sp": "N", "st": "Jdt 7:22", "t": "καὶ ἠθύμησεν τὰ νήπια αὐτῶν, καὶ αἱ γυναῖκες καὶ οἱ νεανίσκοι ἐξέλιπον ἀπὸ τῆς δίψης, καὶ ἔπιπτον ἐν ταῖς πλατείαις τῆς πόλεως καὶ ἐν ταῖς διόδοις τῶν πυλῶν, καὶ οὐκ ἦν κραταίωσις ἔτι ἐν αὐτοῖς."}, {"sp": "N", "st": "Jdt 7:23", "t": "Καὶ ἐπισυνήχθησαν πᾶς ὁ λαὸς ἐπὶ Ὀζείαν καὶ τοὺς ἄρχοντας τῆς πόλεαως, οἱ νεανίσκοι καὶ αἱ γυναῖκες καὶ τὰ παιδία, καὶ ἀνεβόησαν φαωνῇ μεγάλῃ καὶ εἶπαν ἐναντίον τῶν πρεσβυτέρων"}, {"sp": "N", "st": "Jdt 7:24", "t": "Κρίναι ὁ θεὸς ἀνὰ μέσον ὑμῶν καὶ ἡμών, ὅτι ἐποιήσατε ἐν ἡμῖν ἀδικίαν μεγάλην οὐ λαλήσαντες εἰρηνικὰ μετὰ υἱῶν Ἀσσούρ."}, {"sp": "N", "st": "Jdt 7:25", "t": "καὶ νῦν οὐκ ἔστιν ὁ βοηθὸς ἡμῶν, ἀλλὰ πέπρακεν ἡμᾶς ὁ θεὸς εἰς τὰς χεῖρας αὐτῶν τοῦ καταστρωθῆναι ἐυαντίον αὐτῶν ἐν δίψῃ καὶ ἀπωλίᾳ μεγάλῃ."}, {"sp": "N", "st": "Jdt 7:26", "t": "καὶ νῦν ἐπικαλέσασθε αὐτοὺς καὶ ἔκδοσθε τὴν πόλιν πᾶσαν εἰς προνομὴν τῷ λαῷ Ὀλοφέρνου καὶ πάσῃ τῇ δυνάμει αὐτοῦ."}, {"sp": "N", "st": "Jdt 7:27", "t": "κρεῖσσον γὰρ ἡμῖν γενηθῆναι αὐτοῖς εἰς διαρπαγήν· ἐσόμεθα γὰρ εἰς δούλους καὶ ζήσεται ἡ ψυχὴ ἡμῶν, καὶ οὐκ ὀψόμεθα τὸν θάνατον τῶν νηπίων ἡμῶν ἐν ὀφθαλμοῖς ἡμῶν καὶ τὰς γυναῖκας καὶ τὰ τέκνα ἡμῶν ἐκλειπούσας τὰς ψυχὰς αὐτῶν."}, {"sp": "N", "st": "Jdt 7:28", "t": "μαρτυρόμεθα ὑμῖν τὸν οὐρανὸν καὶ τὴν γῆν καὶ τὸν θεὸν ἡμῶν καὶ κύριον τῶν πατέρων ἡμῶν, ὃς ἐκδικεῖ ἡμᾶς κατὰ τὰς ἁμαρτίας ἡμῶν καὶ κατὰ τὰ ἁμαρτήματα τῶν πατέρων ἡμῶν, ἵνα μὴ ποιήσῃ κατὰ τὰ ῥήματα ταῦτα ἐν τῇ ἡμέρᾳ τῇ σήμερον."}, {"sp": "N", "st": "Jdt 7:29", "t": "καὶ ἐγένετο κλαυθμὸς μέγας ἐν μέσῳ τῆς ἐκκλησίας πάντων ὁμοθυμαδόν, καὶ ἐβόησαν πρὸς Κύριον τὸν θεὸν φωνῇ μεγάλῃ."}, {"sp": "N", "st": "Jdt 7:30", "t": "καὶ εἶπεν πρὸς αὐτοὺς Ὀζείας Θαρσεῖτε, ἀδελφοί, διακαρτερήσωμεν ἔτι πέντε ἡμέρας ἐν αἷς ἐπιστρέψει Κύριος ὁ θεὸς ἡμῶν τὸ ἔλεος αὐτοῦ ἐφʼ ἡμᾶς, οὐ γὰρ ἔγκαταλείψει ἡμᾶς εἰς τέλος·"}, {"sp": "N", "st": "Jdt 7:31", "t": "ἐὸν δὲ διέλθωσιν αὗται καὶ μὴ ἔλθῃ ἐφʼ ἡμᾶς βοήθεια, ποιήσω κατὰ τὰ ῥήματα ὑμῶν."}, {"sp": "N", "st": "Jdt 7:32", "t": "καὶ ἐσκόρπισεν τὸν λαὸν εἰς τὴν ἑαυτοῦ παρεμβολήν, καὶ ἐπὶ τὰ τείχη καὶ τοὺς πύργους τῆς πόλεως αὐτῶν ἀπῆλθον, καὶ τὰς γυναῖκας καὶ τὰ τέκνα εἰς τοὺς οἴκους αὐτῶν ἀπέστειλεν· καὶ ἦσαν ἐν ταπεινώσει πολλῇ ἐν τῇ πόλει."}, {"sp": "N", "st": "Jdt 8:1", "t": "Καὶ ἤκουσεν ἐν ἐκείναις ταῖς ἡμέραις Ἰουδεὶθ θυγάτηρ Μεραρεὶ υἱοῦ *Ωξ υἱοῦ Ἰωσὴφ υἱοῦ Ὀζειὴλ υἱοῦ Ἐλκειὰ υἱοῦ Ἠλειοὺ υἱοῦ Χελκείου υἱοῦ Ἐλιὰβ υἱοῦ Ναθαναὴλ υἱοῦ Σαλαμιὴλ υἱοῦ Σαρασαδαὶ υἱοῦ Ἰσραήλ."}, {"sp": "N", "st": "Jdt 8:2", "t": "καὶ ὁ ἀνὴρ αὐτῆς Μανασσῆς τῆς φυλῆς αὐτῆς καὶ τῆς πατριᾶς αὐτῆς· καὶ ἀπέθανεν ἐν ἡμέραις θερισμοῦ κριθῶν."}, {"sp": "N", "st": "Jdt 8:3", "t": "ἐπέστη γὰρ ἐπὶ τοῦ δεσμεύοντος τὸ δράγμα ἐν τῷ πεδίῳ, καὶ ὁ καύσων ἦλθεν ἐπὶ τὴν κεφαλὴν αὐτοῦ, καὶ ἔπεσεν ἐπὶ τὴν κλίνην καὶ ἐτελεύτησεν ἐν Βαιτυλουα τῇ πόλει αὐτοῦ, καὶ ἔθαψαν αὐτὸν μετὰ τῶν, πατέρων αὐτοῦ ἐν τῷ ἀγρῷ τῷ ἀνὰ μέσον Δωθάειμ καὶ Βαλαμών."}, {"sp": "N", "st": "Jdt 8:4", "t": "καὶ ἣν Ἰουδεὶθ ἐν τῷ οἵκῳ αὐτῆς χηρεύουσα ἔτη τρία καὶ μῆνας τέσσαρες."}, {"sp": "N", "st": "Jdt 8:5", "t": "καὶ ἐποίησεν αὐτῇ σκηνὴν ἐπὶ τοῦ δώματος τοῦ οἴκου αὐτῆς, (6) καὶ ἐπέθηκεν ἐπὶ τὴν ὀσφὺν αὐτῆς σάκκον, καὶ ἦν ἐπʼ αὐτῆς τὰ ἱμάτια τῆς χηρεύσεαως αὐτῆς."}, {"sp": "N", "st": "Jdt 8:6", "t": "καὶ ἐνήστευε πάσας τὰς ἡμέρας τῆς χηρεύσεως αὐτῆς χωρὶς προσαββάτων καὶ σαββάτων καὶ προνουμηνιῶν καὶ ἑορτῶν καὶ χαρμοσυνῶν οἴκου Ἰσραήλ."}, {"sp": "N", "st": "Jdt 8:7", "t": "καὶ ἦν καλὴ τῷ εἴδει καὶ ὡραία τῇ ὄψει σφόδρα· καὶ ὑπελείπετο αὐτῇ Μανασσῆς ὁ ἀνὴρ αὐτῆς χρυσίον καὶ ἀργύριον καὶ παῖδας καὶ παιδίσκας καὶ κτήνη καὶ ἀγρούς, καὶ ἔμενεν ἐπʼ αὐτῶν."}, {"sp": "N", "st": "Jdt 8:8", "t": "καὶ οὐκ ἦν ὃς ἐπήνεγκεν αὐτῇ ῥῆμα πονηρόν, ὅτι ἐφοβεῖτο τὸν θεὸν σφόδρα."}, {"sp": "N", "st": "Jdt 8:9", "t": "Καὶ ἤκουσεν ῥήματα τοῦ λαοῦ τὰ πονηρὰ ἐπὶ τὸν ἄρχοντα, ὅτι ὼλιγοψύχησαν ἐπὶ τῇ σπάνει τῶν ὑδάτων· καὶ ἤκουσεν πάντας τοὺς λόγους Ἰουδεὶθ σὃς ἐλάλησεν πρὸς αὐτοὺς Ὀζείας, ὃς ὥμοσεν αὐτοῖς παραδώσειν τὴν πόλιν μετὰ ἡμέρας πέντε τοῖς Ἀσσυρίοις."}, {"sp": "N", "st": "Jdt 8:10", "t": "καὶ ἀποστείλασα τὴν ἄβραν αὐτῆς τὴν ἐφεστῶσαν πᾶσιν τοῖς ὑπάρχουσιν αὐτῆς ἐκάλεσεν Χάβρειν καὶ Χάρμειν τοὺς πρεσβυτέρους τῆς πόλεως αὐτῆς."}, {"sp": "N", "st": "Jdt 8:11", "t": "καὶ ἦλθον πρὸς αὐτήν· καὶ εἶπεν πρὸς αὐτούς Ἀκούσατε δὴ μου, ἄρχοντες τῶν κατοικούντων ἐν Βαιτυλουά· ὅτι οὐκ εὐθὴς ὁ λόγος ὑμῶν ὃν ἐλαλήσατε ἐναντίον τοῦ λαοῦ ἐν τῇ ἡμέρᾳ ταύτῃ, καὶ ἐστήσατε τὸν ὅρκον ὃν ἐλαλήσατε ἀνὰ μέσον τοῦ θεοῦ καὶ ὑμῶν, καὶ εἶπατε ἐκδώσειν τὴν πόλιν τοῖς ἐχθροῖς ἡμῶν ἐὰν μὴ ἐν αὐταῖς ἐπιστρέψῃ ὁ κύριος βοήθειαν ὑμῖν."}, {"sp": "N", "st": "Jdt 8:12", "t": "καὶ νῦν τίνες ἐστὲ ὑμεῖς οἳ ἐπειράσατε τὸν θεὸν ἐν τῇ ἡμέρᾳ τῇ σήμερον, καὶ ἵστατε ὑπέρ τοῦ θεοῦ ἐν μέσῳ υἱῶν ἀνθρώπων;"}, {"sp": "N", "st": "Jdt 8:13", "t": "καὶ νῦν Κύριον Παντοκράτορα ἐξετάζετε, καὶ οὐθὲν ἐπιγνώσεσθε ἕως τοῦ αἰώνος·"}, {"sp": "N", "st": "Jdt 8:14", "t": "ὅτι βάθος καρδίας ἀνθρώπου οὐχ εὑρήσετε, καὶ λόγους τῆς διανοίας αὐτοῦ οὐ διαλήμψεσθε· καὶ πῶς τὸν θεὸν ὃς ἐποίησεν τὰ πάντα ταῦτα ἐρευνήσετε, καὶ τὸν νοῦν αὐτοῦ ἐπιγνώσεσθε, καὶ τὸν λογισμὸν αὐτοῦ κατανοήσετε; μηδαμῶς, ἀδελφοί, μὴ παροργίζετε Κύριον θεὸν ἡμῶν."}, {"sp": "N", "st": "Jdt 8:15", "t": "ὅτι ἐὰν μὴ βούληται ἐν ταῖς πέντε ἡμέραις βοηθῆσαι ἡμῖν, αὐτὸς ἔχει τὴν ἐξουσίαν ἐν αἷς θέλει σκεπάσαι ἡμέραις, ἢ καὶ ὀλεθρεῦσαι ἡμᾶς πρὸ προσώπου τῶν ἐχθρῶν ἡμῶν."}, {"sp": "N", "st": "Jdt 8:16", "t": "ὑμεῖς δὲ μὴ ἐνεχυράζετε τὰς βουλὰς Κυρίου τοῦ θεοῦ ἡμῶν, ὅτι οὐχ ὡς ἄνθρωπος ὁ θεὸς ἀπειληθῆναι οὐδʼ ὡς υἱὸς ἀνθρώπου διαιτηθῆναι."}, {"sp": "N", "st": "Jdt 8:17", "t": "διόπερ ἀναμένοντες τὴν παρʼ αὐτοῦ σωτηρίαν ἐπικαλεσώμεθα αὐτὸν εἰς βοήθειαν ἡμῶν, καὶ εἰσακούσεται τῆς φωνῆς ἡμῶν, ἐὰν ἦν αὐτῷ ἀρεστόν."}, {"sp": "N", "st": "Jdt 8:18", "t": "ὅτι οὐκ ἀνέστη ἐν ταῖς γενεαῖς ἡμῶν οὐδὲ ἔστιν ἐν τῇ ἡμέρᾳ τῇ σήμερον οὔτε φυλὴ οὔτε πατριὰ οὕτε δῆμος οὕτε πόλις ἐξ ἡμῶν οἳ προσκυνοῦσι θεοῖς χειροποιήτοις, καθάπερ ἐγένετο ἐν ταῖς πρότερον ἡμέραις·"}, {"sp": "N", "st": "Jdt 8:19", "t": "ὦν χάριν ἐδόθησαν εἰς ῥομφαίαν καὶ εἰς διαρπαγὴν οἱ πατέρες ἡμῶν, καὶ ἔπεσον πτῶμα μέγα ἐνώπιον τῶν ἐχθρῶν ἡμῶν."}, {"sp": "N", "st": "Jdt 8:20", "t": "ἡμεῖς δὲ ἕτερον θεὸν οὐκ ἐπέγνωμεν πλὴν αὐτοῦ· ὅθεν ἐλπίζομεν ὅτι οὐχ ὑπερόψεται ἡμᾶς οὐδʼ ἀπὸ τοῦ γένους ἡμῶν."}, {"sp": "N", "st": "Jdt 8:21", "t": "ὅτι ἐν τῷ λημφθῆναι ἡμᾶς οὕτως καθήσεται πᾶσα ἡ Ἰουδαία, καὶ προνομευθήσεται τὰ ἅγια ἡμῶν, καὶ ζητήσει τὴν βεβήλωσιν αὐτῶν ἐκ τοῦ αἵματος ἡμῶν,"}, {"sp": "N", "st": "Jdt 8:22", "t": "καὶ τὸν φόνον τῶν ἀδελφῶν ἡμῶν καὶ τὴν αἰχμαλωσίαν τῆς γῆς καὶ τὴν ἐρήμωσιν τῆς κληρονομίας ἡμῶν ἐπιστρέψει εἰς κεφαλὴν ἡμῶν ἐν τοῖς ἔθνεσιν οὖ ἐὰν δουλεύσωμεν ἐκεῖ, καὶ ἐσόμεθα εἰς πρόσκομμα καὶ εἰς ὄνειδος ἐναντίον τῶν κτωμένων ἡμᾶς."}, {"sp": "N", "st": "Jdt 8:23", "t": "ὅτι οὐ κατευθυνθήσεται ἡ δουλεία ἡμῶν εἰς χάριν, ἀλλʼ εἰς ἀτιμίαν θήσει αὐτὴν Κύριος ὁ θεὸς ἡμῶν."}, {"sp": "N", "st": "Jdt 8:24", "t": "καὶ νῦν, ἀδελφοί, ἐπιδειξώμεθα τοῖς ἀδελφοῖς ἡμῶν, ὅτι ἐξ ἡμῶν κρέμαται ἡ ψυχὴ αὐτῶν, καὶ τὰ ἅγια καὶ ὁ οἶκος καὶ τὸ θυσιαστήριον ἐπεστήρισται ἐφʼ ἡμῖν."}, {"sp": "N", "st": "Jdt 8:25", "t": "παρὰ ταῦτα πάντα εὐχαριστήσωμεν Κυρίῳ τῷ θεῷ ἡμῶν, ὃς πειράζει ἡμᾶς καθὰ καὶ τοὺς πατέρας ἡμῶν."}, {"sp": "N", "st": "Jdt 8:26", "t": "μνήσθητε ὅσα ἐποίησεν μετὰ Ἀβραάμ, καὶ ὅσα ἐπείρασεν τὸν Ἰσαάκ, καὶ ὅσα ἐγένετο τῷ Ἰακὼβ ἐν Μεσοποταμίᾳ τῆς Συρίας ποιμαίνοντι τὰ πρόβατα Λαβὰν τοῦ ἀδελφοῦ τῆς μητρὸς αὐτοῦ."}, {"sp": "N", "st": "Jdt 8:27", "t": "ὅτι οὐ καθὼς ἐκείνους ἐπύρωσεν εἰς ἐτασμὸν τῆς καρδίας αὐτῶν, καὶ ἡμᾶς οὐκ ἐξεδίκησεν, ἀλλ εἰς νουθέτησιν μαστιγοῖ Κύριος τοὺς ἐγγίζοντας αὐτῷ."}, {"sp": "N", "st": "Jdt 8:28", "t": "Καὶ εἶπεν πρὸς αὐτὴν Ὀζείας Πάντα ὅσα εἶπας ἀγαθῇ καρδίᾳ ἐλάλησας, καὶ οὐκ ἔστιν ὃς ἀντιστήσεται τοῖς λόγοις σου."}, {"sp": "N", "st": "Jdt 8:29", "t": "ὃτὶ οὐκ ἐν τῇ σήμερον ἡ σοφία σου πρόδηλός ἐστιν, ἀλλʼ ἀπʼ ἀρχῆς ἡμερῶν σου ἔγνω πᾶς ὁ λαὸς τὴν σύνεσίν σου, καθότι ἀγαθόν ἐστιν τὸ πλάσμα τῆς καρδίας σου."}, {"sp": "N", "st": "Jdt 8:30", "t": "ἀλλὰ ὁ λαὸς ἐδίψησεν σφόδρα, καὶ ἠνάγκασαν ποιῆσαι ἡμᾶς καθὰ ἐλαλήσαμεν αὐτοῖς, καὶ ἐπαγαγεῖν ἐφʼ ἡμᾶς ὅρκον ὃν οὐ παραβησόμεθα."}, {"sp": "N", "st": "Jdt 8:31", "t": "καὶ νῦν δεήθητι περὶ ἡμῶν, ὅτι γυνὴ εὐσεβὴς εἶ, καὶ ἀποστελεῖ Κύριος τὸν ὑετὸν εἰς πλήρωσιν τῶν λάκκων ἡμῶν, καὶ οὐκ ἐκλείψομεν ἔτι"}, {"sp": "N", "st": "Jdt 8:32", "t": "καὶ εἶπεν πρὸς αὐτοὺς Ἰουδείθ Ἀκούσατέ μου, καὶ ποιήσω πρᾶγμα ὃ ἀφίξεται εἰς γενεὰς γενεῶν υἱοῖς τοῦ γένους ἡμῶν."}, {"sp": "N", "st": "Jdt 8:33", "t": "ὑμεῖς στήσεσθε ἐπὶ τῆς πύλης τὴν νύκτα ταύτην, καὶ ἐξελεύσομαι ἐγὼ μετὰ τῆς ἀβρας μου, καὶ ἐν ταῖς ἡμέραις μεθʼ ἅς εἶπατε παραδώσειν τὴν πόλιν τοῖς ἐχθροῖς ἡμῶν ἐπισκέψεται Κύριος τὸν Ἰσραὴλ ἐν χειρί μου."}, {"sp": "N", "st": "Jdt 8:34", "t": "ὑμεῖς δὲ οὐκ ἐξερευνήσετε τὴν πρᾶξίν μου, οὐ γὰρ ἐρῶ ὑμῖν ἕως τοῦ τελεσθῆναι ἃ ἐγὼ ποιῶ."}, {"sp": "N", "st": "Jdt 8:35", "t": "καὶ εἶπεν ζείας καὶ οἱ ἄρχοντες πρὸς αὐτήν Πορεύου εἰς εἰρήνην, καὶ Κύριος ὁ θεὸς ἔμπροσθέν σου εἰς ἐκδίκησιν τῶν ἐχθρῶν ἡμῶν."}, {"sp": "N", "st": "Jdt 8:36", "t": "καὶ ἀποστρέψαντες ἐκ τῆς σκηνῆς ἐπορεύθησαν ἐπὶ τὰς διατάξεις αὐτῶν."}, {"sp": "N", "st": "Jdt 9:1", "t": "Ἰουδεὶθ δὲ ἔπεσεν ἐπὶ πρόσωπον, καὶ ἐπέθετο σποδὸν ἐπὶ τὴν κεφαλὴν αὐτῆς, καὶ ἐγύμνωσεν ὃν ἐδεδύκει σάκκον· καὶ ἦν ἄρτι προσφερόμενον ἐν Ἰερουσαλὴμ εἰς τὸν οἶκον τοῦ θεοῦ τὸ θυμίαμα τῆς ἑσπέρας ἐκείνης, καὶ ἐβόησεν φωνῇ μεγάλῃ Ἰουδεὶθ πρὸς Κύριον καὶ εἶπεν"}, {"sp": "N", "st": "Jdt 9:2", "t": "Κύριε ὁ θεὸς τοῦ πατρός μου Συμεών, ᾧ ἔδωκας ἐν χειρὶ ῥομφαίαν εἰς ἐκδίκησιν ἀλλογενῶν, οἳ ἔλυσαν μήτραν παρθένου εἰς μίασμα καὶ ἐγύμνωσαν μηρὸν εἰς αἰσχύνην καὶ ἐβεβήλωσαν μήτραν εἰς ὄνειδος· εἶπας γάρ Οὐχ οὕτως ἔσται· καὶ ἐποίησαν."}, {"sp": "N", "st": "Jdt 9:3", "t": "ἀυθʼ ὦν ἔδωκας ἄρχοντας αὐτῶν εἰς φόνον, καὶ τὴν στραωμνὴν αὐτῶν ἡ ήδέσατο τὴν ἀπάτην αὐτῶν ἀπατηθεῖσαν εἰς αἵμα, καὶ ἐπάταξας δούλους ἐπὶ δυνάσταις καὶ δυνάστας ἐπὶ θρόνους αὐτῶν·"}, {"sp": "N", "st": "Jdt 9:4", "t": "καὶ ἔδωκας γυναῖκας αὐτῶν εἰς προνομὴν καὶ θυγατέρας εἰς αἰχμαλωσίαν καὶ πάντα τὰ σκῦλα εἰς διαίρεσιν υἱῶν ἠγαπημένων ὑπὸ σοῦ, οἳ καὶ ἐζήλωσαν τὸν ζῆλόν σου καὶ ἐβδελύξαντο μίασμα αἵματος αὐτῶν καὶ ἐπεκαλέσαντό σε εἰς βοηθόν· ὁ θεὸς ὁ θεὸς ἐμός, καὶ εἰσάκουσον ἐμοῦ τῆς χήρας."}, {"sp": "N", "st": "Jdt 9:5", "t": "σὺ γὰρ ἐποίησας τὰ πρότερα ἐκείναων, καὶ ἐκεῖνα καὶ τὰ μετέπειτα καὶ τὰ νῦν καὶ τὰ ἐπερχόμενα διενοήθης, καὶ ἐγενήθησαν ἃ ἐνενοήθης,"}, {"sp": "N", "st": "Jdt 9:6", "t": "καὶ παρέστησαν ἃ ἐβουλεύσω καὶ εἶπαν Ἰδοὺ πάρεσμεν· (⁵)πᾶσαι γὰρ αἱ ὁδοί σου ἕτοιμοι, καὶ ἡ κρίσις σου ἐν προγνώσει."}, {"sp": "N", "st": "Jdt 9:7", "t": "ἰδοὺ γὰρ Ἀσσύριοι ἐπληθύνθησαν ἐν δυνάμει αὐτῶν, ὑψώθησαν ἐφʼ ἵππῳ καὶ ἀναβάτῃ, ἐγαυρίασαν ἐν βραχίονι πεζῶν, ἤλπισαν ἐν ἀσπίδι καὶ ἐν γαίσῳ καὶ τόξῳ καὶ σφενδόνῃ, καὶ οὐκ ἔγνωσαν ὅτι σὺ εἶ Κύριος συντρίβων πολέμους."}, {"sp": "N", "st": "Jdt 9:8", "t": "Κύριος ὄνομά σοι· σὺ ῥάξον αὐτῶν τὴν ἰσχὺν ἐν δυνάμει σου, καὶ κάταξον τὸ κράτος αὐτῶν ἐν τῷ θυμῷ σου· ἐβουλεύσαντο γὰρ βεβηλῶσαι τὰ ἅγιά σου, μιᾶναι τὸ σκήναωμα τῆς ααταπαύσεως τοῦ ὀνόματος τῆς δόξης σου, καταβαλεῖν σιδήρῳ κέρας θυσιαστηρίου σου."}, {"sp": "N", "st": "Jdt 9:9", "t": "βλέψου εἰς ὑπερηφανίαν αὐτῶν, ἀπόστειλον τὴν ὀργὴν σου εἰς κεφαλὰς αὐτῶν, δὸς ἐν χειρί μου τῆς χήρας ὃ διενοήθην κράτος."}, {"sp": "N", "st": "Jdt 9:10", "t": "πάτάξον δοῦλον ἐκ χειλέων ἀπάτης μσυ ἐπʼ ἄρχοντι καὶ ἄρχοντα ἐπὶ θεράποντι αἰτοῦ, θραῦσον αὐτῶν τὸ ἀνάστεμα ἐν χειρὶ θηλείας."}, {"sp": "N", "st": "Jdt 9:11", "t": "οὐ γὰρ ἐν πλήθει τὸ κράτος σου, οὐδὲ ἡ δυναστεία σου ἐν ἰσχύουσιν, ἀλλὰ ταπεινῶν εἶ θεός, ἐλαττόνων εἶ βοηθός, ἀντιλήμπταωρ ἀσθενούνταωυ, ἀπεγνωσμέναον σκεπαστής, ἀπηλπισμένων σωτήρ."}, {"sp": "N", "st": "Jdt 9:12", "t": "υαὶ ναὶ ὁ θεὸς τοῦ πατρός μου καὶ θεὸς κληρονομίας Ἰσραήλ, (¹⁷)δέσποτα τῶν οὐρανῶν καὶ τῆς γῆς, κτίστα τῶν ὑδάτων, βασιλεῦ πάσης κτίσεώς σου, σὺ εἰσάκουσου τῆς δεήσεως μου,"}, {"sp": "N", "st": "Jdt 9:13", "t": "καὶ δὸς λόγον μου καὶ ἀπάτην εἰς τραῦμα καὶ μάώλωπα αὺτῶν, οἳ κατὰ τῆς διαθήκης σου καὶ οἴκου ἡγιασμένου σου καὶ κορυφῆς Σιὼν καὶ οἴκου κατασχέσεως υἱῶν σου ἐβουλεύσαντο σκληρά."}, {"sp": "N", "st": "Jdt 9:19", "t": "καὶ ποίησον ἐπὶ πᾶν τὸ ἔθνος σου καὶ πάσης φυλῆς ἐπίγνωσιν, τοῦ εἰδῆσαι ὅτι σὺ εἶ ὁ θεὸς πάσης δυνάμεως καὶ κράτους, καὶ οὐκ ἔστιν ἄλλος ὑπερασπίζων τοῦ γένους Ἰσραὴλ εἰ μὴ σύ."}, {"sp": "N", "st": "Jdt 10:1", "t": "Καὶ ἐγένετο ὡς ἐπαύσατο βοῶσα πρὸς τὸν θεὸν Ἰσραὴλ καὶ συνετέλεσεν πάντα τὰ ῥήματα ταῦτα,"}, {"sp": "N", "st": "Jdt 10:2", "t": "καὶ ἀνέστη ἀπὸ τῆς πτώσεως (²)καὶ ἐκάλεσεν τὴν ἅβραν αὐτῆς, καὶ κατέβη εἰς τὸν οἶκον ἐν ᾧ διέτριβεν ἐν αὐτῷ ἐν ταῖς ἡμέραις τῶν σαββάτων καὶ ἐν ταῖς ἑορταῖς αὐτῆς,"}, {"sp": "N", "st": "Jdt 10:3", "t": "καὶ περιείλατο τὸν σάκκον ὃν ἐνδεδύκει, καὶ ἐξεδύσατο τὰ ἱμάτια τῆς χηρεύσεως αὐτῆς· (3)περιεκλύσατο τὸ σῶμα ὕδατι καὶ ἐχρίσατο μύρῳ παχεῖ, καὶ διέταξε τὰς τρίχας τῆς κεφαλῆς αὐτῆς καὶ ἐπέθετο μίτραν ἐπʼ αὐτῆς, καὶ ἐνεδύσατο τὰ ἱμάτια τῆς εὐφροσύνης αὐτῆς ἐν αἷς ἐστολίζετο ἐν ταῖς ἡμέραις τῆς ζωῆς τοῦ ἀνδρὸς αὐτῆς Μανασσῆ·"}, {"sp": "N", "st": "Jdt 10:4", "t": "καὶ ἔλαβεν σανδάλια εἰς τοὺς πόδας αὐτῆς, καὶ περιέθετο τοὺς χλίδωνας καὶ τὰ ψέλια καὶ τοὺς δακτυλίους καὶ τὰ ἐνώτια καὶ πάντα τὸν κόσμον αὐτῆς· (4b) καὶ ἐκαλλωπίσατο σφόδρα εἰς ἀπάντησιν ὀφθαλμῶν ἀνδρῶν ὅσοι ἂν ἴδωσιν αὐτήν."}, {"sp": "N", "st": "Jdt 10:5", "t": "καὶ ἔδωκεν τῇ ἃβρᾳ αὐτῆς ἀσκοπυτίνην οἴνου καὶ καψάκην ἐλαίου, καὶ πήραν ἐπλήρωσεν ἀλφίτων καὶ παλάθης καὶ ἄρτων καθαρῶν, καὶ περιεδίπλωσε πάντα τὰ ἄγγια αὐτῆς καὶ ἐπέθηκεν αὐτῇ."}, {"sp": "N", "st": "Jdt 10:6", "t": "καὶ ἐξήλθοσαν ἐπὶ τὴν πύλην τῆς πόλεως Βαιτυλουά, καὶ εὕροσαν ἐπεστῶτα ἐπʼ αὐτῇ Ὀζείαν καὶ τοὺς πρεσβυτέρους τῆς πόλεως Χάβρειν καὶ Χάρμειν."}, {"sp": "N", "st": "Jdt 10:7", "t": "ὡς δὲ ἴδον αὐτήν, καὶ ἦν ἠλλοιωμένον τὸ πρόσωπον αὐτῆς, καὶ τὴν στολὴν μεταβεβληκυῖαν, καὶ ἐθαύμασαν ἐπὶ τῷ κάλλει αὐτῆς ἐπὶ πολὺ σφόδρα, (8) καὶ εἶπαν αὐτῇ"}, {"sp": "N", "st": "Jdt 10:8", "t": "Ὁ θεὸς τῶν πατέρων ἡμῶν δῴη σε εἰς χάριν. καὶ τελειώσαι τὰ ἐπιτηδεύματά σου εἰς γαυρίαμα υἱῶν Ἰσραὴλ καὶ ὕψωμα Ἰερουσαλήμ. καὶ προσεκύνησεν τῷ θεῷ,"}, {"sp": "N", "st": "Jdt 10:9", "t": "καὶ εἶπεν πρὸς αὐτούς Ἐπιτάξατε ἀνοῖξαί μοι τὴν πύλην τῆς πόλεως, καὶ ἐξελεύσομαι εἰς τελείωσιν τῶν λόγων ὧν ἐλαλήσατε μετʼ ἐμοῦ· καὶ συνέταξαν τοῖς νεανίσκοις ἀνοῖξαι αὐτῇ καθότι ἐλάλησαν."}, {"sp": "N", "st": "Jdt 10:10", "t": "καὶ ἐποίησαν οὕτως· (10)καὶ ἐξῆλθεν Ἰουδείθ, αὐτὴ καὶ ἡ παιδίσκη αὐτῆς μετʼ αὐτῆς· ἀπεσκόπευον δʼ αὐτὴν οἱ ἄνδρες τῆς πόλεως ἕως οὗ κατέβη τὸ ὄρος. ἕως διῆλθεν τὸν αὐλῶνα καὶ οὐκ οὐκέτι ἐθεώρουν αὐτήν."}, {"sp": "N", "st": "Jdt 10:11", "t": "Καὶ ἐπορεύοντο ἐν τῷ αὐλῶνι εἰς εὐθεῖαν, καὶ συνήντησεν αὐτῇ προφυλακὴ τῶν Ἀσσυρίων."}, {"sp": "N", "st": "Jdt 10:12", "t": "καὶ συνέλαβον αὐτὴν καὶ ἐπηρώτησαν Τίνων εἶ, καὶ πόθεν ἔρχῃ, καὶ ποῦ πορεύῃ ; (¹²)καὶ εἶπεν Θυηάτηρ εἰμὶ τῶν Ἐβραίων, καὶ ἀποδιδράσκω ἀπὸ προσώπου αὐτῶν, ὅτι μέλλουσιν δίδοσθαι ὑμῖν εἰς κατάβρωμα."}, {"sp": "N", "st": "Jdt 10:13", "t": "κἀγὼ ἔρχομαι εἰς τὸ πρόσωπον Ὀλοφέρνου ἀρχιστρατήγου δυνάμεως ὑμῶν τοῦ ἀναγγεῖλαι ῥήματα ἀληθείας, καὶ δείξω πρὸ προσώπου αὐτοῦ ὁδὸν καθʼ ἣν πορεύσεται καὶ κυριεύσει πάσης τῆς ὀρίνῆς, καὶ οὐ διαφωνήσει τῶν ἀνδρῶν αὐτοῦ σὰρξ μία οὐδὲ πνεῦμα ζωῆς."}, {"sp": "N", "st": "Jdt 10:14", "t": "ὡς δὲ ἤκουσαν οἱ ἄνδρες τὰ ῥήματα αὐτῆς, καὶ κατενόησαν τὸ πρόσωπον αὐτῆς, καὶ ἦν ἐναντίον αὐτῶν θαυμάσιον τῷ κάλλει σφόδρα· (¹5)καὶ εἶπαν πρὸς αὐτήν"}, {"sp": "N", "st": "Jdt 10:15", "t": "Σέσωκας τὴν ψυχὴν σου σπεύσασα καταβῆναι εἰς πρόσωπον τοῦ κυρίου ἡμῶν· καὶ νῦν πρόσελθε ἐπὶ τὴν σκηνὴν αὐτοῦ, καὶ ἀφʼ ἡμῶν προπέμψουσίν σε ἕως παραδῶσίν σε εἰς χεῖρας αὐτοῦ."}, {"sp": "N", "st": "Jdt 10:16", "t": "ἐὸν δὲ στῆς ἐναντίον αὐτοῦ, μὴ φοβηθῇς τῇ καρδίᾳ σου, ἀλλὰ ἀνάγγειλον κατὰ τὰ ῥήματά σου, καὶ εἶ σε ποιήσει."}, {"sp": "N", "st": "Jdt 10:17", "t": "καὶ ἀπέλεξαν ἐξ αὐτῶν ἄνδρας ἑκατόν, καὶ παρέζευξαν αὐτῇ καὶ τῇ ἅβρᾳ αὐτῆς, καὶ ἤγαγον αὐτὰς ἐπὶ τὴν σκηνὴν Ὀλοφέρνου."}, {"sp": "N", "st": "Jdt 10:18", "t": "καὶ ἐγένετο συνδρομὴ ἐν τῇ παρεμβολῇ, διεβοήθη γὰρ εἰς τὰ σκηνώματα ἡ παρουσία αὐτῆς· καὶ ἐλθόντες ἐκύκλουν αὐτὴν ὡς ἱστήκει ἔξω τῆς σκηνῆς Ὀλοφέρνου, ἕως προσήγγειλαν αὐτῷ περὶ αὐτῆς."}, {"sp": "N", "st": "Jdt 10:19", "t": "καὶ ἐθαύμαζον ἐπὶ τῷ κάλλει αὐτῆς, καὶ ἐθαύμαζον τοὺς υἱοὺς Ἰσραὴλ ἀπʼ αὐτῆς· καὶ εἶπεν ἕκαστος πρὸς τὸν πλησίον αὐτοῦ Τίς καταφρονήσει τοῦ λαοῦ τούτου ὃς ἔχει ἐν ἑαυτῷ γυναῖκας τοιαύτας; ὅτι οὐ καλόν ἐστιν ὑπολείπεσθαι ἐξ αὐτῶν ἄνδρα ἕνα, οἱ ἀφεθέντες δυνήσονται κατασοφίσασθαι πᾶσαν τὴν γῆν."}, {"sp": "N", "st": "Jdt 10:20", "t": "καὶ ἐξῆλθον οἱ παρακαθεύδοντες Ὀλοφέρνῃ καὶ πάντες οἱ θεράποντες αὐτοῦ, καὶ εἰσήγαγον αὐτὴν εἰς τὴν σκηνήν."}, {"sp": "N", "st": "Jdt 10:21", "t": "καὶ ἦν Ὀλοφέρνης ἀναπαυόμενος ἐπὶ τῆς κλίνης αὐτοῦ ἐν τῷ κωνωπίῳ, ὁ ἦν ἐκ πορφύρας καὶ χρυσίου καὶ σμαράγδου καὶ λίθων πολυτελῶν καθυφασμένων."}, {"sp": "N", "st": "Jdt 10:22", "t": "καὶ ἀνήγγειλαν αὐτῷ περὶ αὐτῆς, καὶ ἐξῆλθεν εἰς τὸ προσκήνιον, καὶ λαμπάδες ἀργυραῖ προάγουσαι αὐτοῦ."}, {"sp": "N", "st": "Jdt 10:23", "t": "ὡς δὲ ἦλθεν κατὰ πρόσωπον αὐτοῦ Ἰουδεὶθ καὶ τῶν θεραπόντων αὐτοῦ, ἐθαύμασαν πάντες ἐπὶ τῷ κάλλει τοῦ προσώπου· καὶ πεσοῦσα ἐπὶ πρόσωπον προσεκύνησεν αὐτῷ, καὶ ἤγειραν αὐτὴν οἱ δοῦλοι αὐτοῦ."}, {"sp": "N", "st": "Jdt 11:1", "t": "Καὶ εἶπεν πρὸς αὐτὴν Ὀλοφέρνης Φάρσησον, γύναι, μὴ φοβηθῇς τῇ καρδίᾳ σου· ὅτι ἐγὼ οὐκ ἐκάκωσα τῆς γῆς."}, {"sp": "N", "st": "Jdt 11:2", "t": "καὶ νῦν ὁ λαός σου ὁ κατοικῶν τὴν ὀρινήν, εἰ μὴ ἐφαύλισάν με, οὐκ ἂν ἦρα τὸ δόρυ μου ἐπʼ αὐτούς, ἀλλὰ αὐτοὶ ἑαυτοῖς ἐποίησαν ταῦτα."}, {"sp": "N", "st": "Jdt 11:3", "t": "καὶ νῦν λέγε μοι τίνος ἕνεκεν ἀπέδρας ἀπʼ αὐτῶν καὶ ἦλθες πρὸς ἡμᾶς· ἤκεις γὰρ εἰς σωτηρίαν· θάρσει, ἐν τῇ νυκτὶ ταύτῃ ζήσῃ καὶ εἰς τὸ λοιπόν·"}, {"sp": "N", "st": "Jdt 11:4", "t": "οὐ γὰρ ἔστιν ὃς ἀδικήσει σε, ἀλλʼ εὖ σε ποιήσει καθὰ γίνεται τοῖς δούλοις τοῦ κυρίου μου βασιλέως Ναβουχοδονοσόρ."}, {"sp": "N", "st": "Jdt 11:5", "t": "καὶ εἶπεν πρὸς αὐτὸν Ἰουδείθ Δέξαι τὰ ῥήματα τῆς δούλης σου, καὶ λαλησάτω ἡ παιδίσκη σου κατὰ πρόσωπόν σου, καὶ οὐκ ἀναγγελῶ ψεῦδος τῷ κυρίῳ μου ἐν τῇ νυκτὶ ταύτῃ."}, {"sp": "N", "st": "Jdt 11:6", "t": "καὶ ἐὰν κατακολουθήσῃς τοῖς λόγοις τῆς παιδίσκης σου, τελείως πρᾶγμα ποιήσει μετὰ σοῦ ὁ θεός, καὶ οὐκ ἀποπεσεῖται ὁ κύριός μου τῶν ἐπιτηδευμάτων αὐτοῦ."}, {"sp": "N", "st": "Jdt 11:7", "t": "ζῇ γὰρ βασιλεὺς Ναβουχοδονοσὸρ πάσης τῆς γῆς καὶ ζῇ τὸ κράτος αὐτοῦ, ὃς ἀπέστειλέν σε εἰς κατόρθωσιν πάσης ψυχῆς, ὅτι οὐ μόνον ἄνθρωποι διὰ σὲ δουλεύουσιν αὐτῷ, ἀλλὰ καὶ τὰ θηρία τοῦ ἀγροῦ καὶ τὰ κτήνη καὶ τὰ πετεινὰ τοῦ οὐρανοῦ διὰ τῆς ἰσχύος σου ζήσονται Ναβουχοδονοσὸρ καὶ πάντα τὸν οἶκον αὐτοῦ."}, {"sp": "N", "st": "Jdt 11:8", "t": "ἠκούσαμεν γὰρ τὴν σοφίαν σου καὶ τὰ πανουργεύματα τῆς ψυχῆς σου, καὶ ἀνηγγέλη πάσῃ τῇ γῇ ὅτι σὺ μόνος ἀγαθὸς ἐν πάσῃ βασιλείᾳ καὶ δυνατὸς ἐν ἐπιστήμῃ καὶ θαυμαστὸς ἐν στρατεύμασιν πολέμου."}, {"sp": "N", "st": "Jdt 11:9", "t": "καὶ νῦν λόγος ὃν ἐλάλησεν Ἀχιὼρ ἐν τῇ συνεδρείᾳ σου, ἠκούσαμεν τὰ ῥήματα αὐτοῦ, ὅτι περιεποιήσαντο αὐτὸν οἱ ἄνδρες Βαιτυλουά, καὶ ἀνήγγειλεν αὐτοῖς πάντα ὅσα ἐξελάλησεν παρὰ σοί"}, {"sp": "N", "st": "Jdt 11:10", "t": "διό, δέστ ποτα κύριε. μὴ παρέλθῃς τὸν λόγον αὐτοῦ, ἀλλὰ κατάθου αὐτὸν ἐν τῇ καρδίᾳ σου, (8)ὅτι ἐστιν ἀληθής· οὐ γὰρ ἐκδικᾶται τὸ γένος ἡμῶν, οὐ κατισχύει ῥομφαία ἐπʼ αὐτοὺς ἐὰν μὴ ἁμάρτωσιν εἰς τὸν θεὸν αὐτῶν."}, {"sp": "N", "st": "Jdt 11:11", "t": "καὶ νῦν ἴνα μὴ γένηται ὁ κύριός μου ἔκηβολος καὶ ἄπρακτος, ἐπιπεσεῖται θάνατος ἐπὶ πρόσωπον αὐτῶν, καὶ κατελάβετο αὐτοὺς ἁμάρτημα ἐν ᾧ παροργιοῦσιν τὸν θεὸν αὐτῶν, ὁπηνίκα ἂν ποιήσωσιν ἀτοπίαν."}, {"sp": "N", "st": "Jdt 11:12", "t": "ἐπεὶ γὰρ ἐξέλειπεν αὐτοὺς τὰ βρώματα καὶ ἐσπανίσθη πᾶν ὕδωρ, ἐβουλεύσαντο ἐπιβαλεῖν τοῖς κτήνεσιν αὐτῶν, καὶ πάντα ὅσα διεστείλατο αὐτοῖς ὁ θεὸς τοῖς νόμοις αὐτοῦ μὴ φαγεῖν διέγνωσαν δαπανῆσαι."}, {"sp": "N", "st": "Jdt 11:13", "t": "καὶ τὰς ἀπαρχὰς τοῦ σίτου καὶ τὰς δεκάτας τοῦ οἴνου καὶ τοῦ ἐλαίου, ἃ διεφύλαξαν ἁγιάσαντες τοῖςἱερεῦσιυ τοῖς παρεστηκόσιυ ἐν Ἰερουσαλὴμ ἀπέναντι τοῦ προσώπου τοῦ θεοῦ ἡμῶν, κεκρίκασιν ἐξαναλῶσαι, ὧν οὐδὲ ταῖς χερσὶν. καθῆκεν ἅψασθαι οὐδένα τῶν ἐκ τοῦ λαοῦ."}, {"sp": "N", "st": "Jdt 11:14", "t": "καὶ ἀπεστάλκασιν εἰς Ἰερουσαλήμ, ὅτι καὶ οἱ ἐκεῖ κατοικοῦντες ἐποίησαν ταῦτα, τοὺς μετοικίσαντας αὐτοῖς τὴν ἄφεσιν παρὰ τῆς γερουσίας."}, {"sp": "N", "st": "Jdt 11:15", "t": "καὶ ἔσται ὡς ἂν ἀναγγείλῃ αὐτοῖς καὶ ποιήσωσιν, δοθήσονταί σοι εἰς ὄλεθρον ἐν τῇ ἡμέρᾳ ἐκείνῃ."}, {"sp": "N", "st": "Jdt 11:16", "t": "ὅθεν ἐγὼ ἡ δούλη σου ἐπιγνοῦσα ταῦτα πάντα ἀπέδρων ἀπὸ προσώπου αὐτῶν, καὶ ἀπέστειλέν με ὁ θεὸς ποιῆσαι μετὰ σοῦ πράγματα ἐφʼ οἷς ἐκστήσεται πᾶσα ἡ γῆ ὅσοι ἐὰν ἀκούσωσιν αὐτά."}, {"sp": "N", "st": "Jdt 11:17", "t": "ὅτι ἡ δούλη σου θεοσεβής ἐστιν, καὶ θεραπεύουσα νυκτὸς καὶ ἡμέρας τὸν θεὸν τοῦ οὐρανοῦ· καὶ νῦν μενῶ παρὰ σοί, κύριέ μου, καὶ ἐξελεύσεται ἡ δούλη σου κατὰ νύκτα εἰς τὴν φάραγγα καὶ προσεύξομαι πρὸς τὸν θεόν, (15ª) καὶ ἐρεῖ μοι πότε ἐποίησαν τὰ ἁμαρτήματα αὐτῶν."}, {"sp": "N", "st": "Jdt 11:18", "t": "καὶ ἐλθοῦσα προσανοίσω σοι, καὶ ἐξελεύσῃ σὺν πάσῃ τῇ δυνάμει σου, καὶ οὐκ ἔστιν ὃς ἀντιστήσεταί σοι ἐξ αὐτῶν."}, {"sp": "N", "st": "Jdt 11:19", "t": "καὶ ἄξω σε διὰ μέσου τῆς Ἰουδαίας ἕως τοῦ ἐλθεῖν ἀπέναντι Ἰερουσαλήμ, καὶ θήσω τὸν δίφρον σου ἐν μέσῳ αὐτῆς, καὶ ἄξεις αὐτοὺς ὡς πρόβατα οἷς οὐκ ἔστιν ποιμήν, καὶ οὐ γρύξει κύων τῇ γλώσσῃ αὐτοῦ ἀπέναντί σου· (¹⁶)ὅτὶ ταῦτα ἐλαλήθη μοι κατὰ πρόγνωσίν μου καὶ ἀπηγγέλη μοι, (¹⁷)καὶ ἀπεστάλην ἀναγγεῖλαί σοι."}, {"sp": "N", "st": "Jdt 11:20", "t": "Καὶ ἤρεσαν οἱ λόγοι αὐτῆς ἐναντίον Ὁλοφέρνου καὶ ἐναντίον πάντων τῶν θεραπόντων αὐτοῦ, καὶ ἐθαύμασαν ἐπὶ τῇ σοφίᾳ αὐτῆς καὶ εἶπαν"}, {"sp": "N", "st": "Jdt 11:21", "t": "Οὐκ ἔστιν τοιαύτη γυνὴ ἀπʼ ἄκρου ἕως ἄκρου τῆς γῆς, ἐν καλῷ προσώπῳ καὶ συνέσει λόγων."}, {"sp": "N", "st": "Jdt 11:22", "t": "καὶ εἶπεν πρὸς αὐτὴν Ὀλοφέρνης Εὖ ἐποίησευ ὁ θεὸς ἀποστείλας σε ἔμπροσθεν τοῦ λαοῦ, τοῦ γενηθῆναι ἐν χερσὶν ἡμῶν κράτος· ἐν δὲ τοῖς φαυλίσασι τὸν κύριόν μου ἀπώλεια."}, {"sp": "N", "st": "Jdt 11:23", "t": "καὶ νῦν ἀστεία εἶ σὺ ἐν τῷ εἴδει σου καὶ ἀγαθὴ ἐν τοῖς λόγοις σου· ὅτι ἐὰν ποιήσῃ καθὰ ἐλάλησας, ὁ θεός σου ἔσται μοῦ θεός, καὶ σὺ ἐν οἴκῳ Ναβουχοδονοσὸρ βασιλέως καθήσῃ, καὶ ἔσῃ ὀνομαστὴ παρὰ πᾶσαν τὴν γῆν."}, {"sp": "N", "st": "Jdt 12:1", "t": "Καὶ ἐκέλευσεν εἰσαγαγεῖν αὐτὴν οὗ ἐτίθετο τὰ ἀργυρώματα αὐτοῦ, καὶ συνέταξεν καταστρῶσαι αὐτῇ ἀπὸ τῶν ὀψοποιημάτων αὐτοῦ καὶ τοῦ οἴνου αὐτοῦ πίνειν."}, {"sp": "N", "st": "Jdt 12:2", "t": "καὶ εἶπεν Ἰουδείθ Οὐ φάγομαι ἐξ αὐτῶν, ἵνα μὴ γένηται σκάνδαλον, ἀλλʼ ἐκ τῶν ἠκολουθηκότων μοι χορηγηθήσεται."}, {"sp": "N", "st": "Jdt 12:3", "t": "καὶ εἶπεν πρὸς αὐτὴν Ὀλοφέρνης Ἐὰν δὲ ἐκλίπῃ τὰ μετὰ σοῦ ὄντα, πόθεν ἐξοίσομέν σοι δοῦναι ὅμοια αὐτοῖς; οὐ γάρ ἐστιν μεθʼ ἡμῶν ἐκ τοῦ ἔθνους σου."}, {"sp": "N", "st": "Jdt 12:4", "t": "καὶ εἶπεν Ἰουδεὶθ πρὸς αὐτόν Ζῇ ἡ ψυχή σου, κύριέ μου, ὅτι οὐ δαπανήσει ἡ δούλη σου τὰ ὄντα μετ᾿ ἐμοῦ ἕως ἂν ποιήσῃ ἐν χειρί μου ἃ ἐβουλεύσατο."}, {"sp": "N", "st": "Jdt 12:5", "t": "καὶ ἠγάγοσαν αὐτὴν οἱ θεράποντες Ὀλοφέρνου εἰς τὴν σκηνήν, καὶ ὕπνωσεν μέχρι μεσούσης τῆς νυκτός· καὶ ἀνέστη πρὸς τὴν ἑωθινὴν φυλακήν,"}, {"sp": "N", "st": "Jdt 12:6", "t": "καὶ ἀπέστειλεν πρὸς Ὀλοφέρνην λέγουσα Ἐπιταξάτω δὴ ὁ κύριός μου ἐᾶσαι τὴν δούλην σου ἐπὶ προσευχὴν ἐξελθεῖν."}, {"sp": "N", "st": "Jdt 12:7", "t": "καὶ προσέταξεν Ὀλοφέρνης τοῖς σωματοφύλαξιν μὴ διακωλύειν αὐτήν. καὶ παρέμεινεν ἐν τῇ παρεμβολῇ ἡμέρας τρεῖς· (7) καὶ ἐξεπορεύετο κατὰ νύκτα εἰς τὴν φάραγγα Βαιτυλουά, καὶ ἐβαπτίζετο ἐν τῇ παρεμβολῇ ἐπὶ τῆς πηγῆς τοῦ ὕδατος."}, {"sp": "N", "st": "Jdt 12:8", "t": "καὶ ὡς ἀνέβη, ἐδέετο τοῦ κυρίου θεοῦ Ἰσραὴλ κατευθῦναι τὴν ὁδὸν αὐτῆς εἰς ἀνάστημα τῶν υἱῶν τοῦ λαοῦ αὐτοῦ."}, {"sp": "N", "st": "Jdt 12:9", "t": "καὶ εἰσπορευομένη καθαρὰ παρέμενεν τῇ σκηνῇ, μέχρι οὗ προσηνέγκατο τὴν τροφὴν αὐτῆς πρὸς ἑσπέραν."}, {"sp": "N", "st": "Jdt 12:10", "t": "Καὶ ἐγένετο ἐν τῇ ἡμέρᾳ τῇ τετάρτῃ ἐποίησεν Ὀλοφέρνης πότον τοῖς δούλοις αὐτοῦ μόνοις, καὶ οὐκ ἐκάλεσεν εἰς τὴν χρῆσιν οὐδένα τῶν πρὸς ταῖς χρείαις."}, {"sp": "N", "st": "Jdt 12:11", "t": "καὶ εἶπεν Βαγώᾳ τῷ εὐνούχῳ, ὃς ἣν ἐφεστηκὼς ἐπὶ πάντων τῶν αὐτοῦ Πεῖσον δὴ πορευθεὶς τὴν γυναῖκα τὴν Ἐβραίαν ἥ ἐστιν παρὰ σοὶ τοῦ ἐλθεῖν πρὸς ἡμᾶς καὶ φαγεῖν καὶ πιεῖν μεθʼ ἡμῶν."}, {"sp": "N", "st": "Jdt 12:12", "t": "ἰδοὺ γὰρ αἰσχρὸν τῷ προσώπῳ ἡμῶν εἰ γυναῖκα τοιαύτην παρήσομεν οὐχ ὁμιλήσαντες αὐτῇ· ὅτι ἐὰν ταύτην μὴ ἐπισπασώμεθα, καταγελάσεται ἡμῶν."}, {"sp": "N", "st": "Jdt 12:13", "t": "καὶ ἐξῆλθεν Βαγώας ἀπὸ προσώπου Ὀλοφέρνου, καὶ εἰσῆλθεν πρὸς αὐτὴν καὶ εἶπεν Μὴ ὀκνησάτω δὴ ἡ παιδίσκη ἡ καλὴ αὕτη ἐλθοῦσα πρὸς τὸν κύριόν μου δοξασθῆναι κατὰ πρόσωπον αὐτοῦ, καὶ πίεσαι μεθʼ ἡμῶν εἰς εὐφροσύνην οἶνον, καὶ γενηθῆναι ἐν τῇ ἡμέρᾳ ταύτῃ ὡς θυγάτηρ μία τῶν υἱῶν Ἀσσοὺρ αἰ παρεστήκασιν ἐν οἴκῳ Ναβουχοδονοσόρ."}, {"sp": "N", "st": "Jdt 12:14", "t": "καὶ εἶπεν πρὸς αὐτὸν Ἰουδείθ Καὶ τίς εἰμι ἐγὼ ἀντεροῦσα τῷ κυρίῳ μου ; ὅτι πᾶν ἔσται ἐν τοῖς ὀφθαλμοῖς αὐτοῦ ἀρεστὸν σπεύσασα ποιήσω, καὶ ἔσται τοῦτό μοι ἀγαλλίαμα ἕως ἡμέρας θανάτου μου."}, {"sp": "N", "st": "Jdt 12:15", "t": "καὶ διαναστᾶσα ἐκοσμήθη τῷ ἱματισμῷ καὶ παντὶ τῷ κόσμῳ τῷ γυναικείῳ· καὶ προῆλθεν ἡ δούλη αὐτῆς καὶ ἔστρωσεν αὐτῇ κατέναντι Ὀλοφέρνου χαμαὶ τὰ κώδια, ἃ ἔλαβεν παρὰ Βαγώου εἰς τὴν καθημερινὴν δίαιταν αὐτῆς εἰς τὸ ἐσθίειν κατακλινομένην ἐπʼ αὐτῶν."}, {"sp": "N", "st": "Jdt 12:16", "t": "καὶ εἰσελθοῦσα ἀνέπεσεν Ἰουδείθ, (¹⁶)καὶ ἐξέστη ἡ καρδία Ὀλοφέρνου ἐπʼ αὐτήν, ἐσαλεύθη ἡ ψυχὴ αὐτοῦ· καὶ ἦν κατεπίθυμος σφόδρα τοῦ συγγενέσθαι μετʼ αὐτῆς, καὶ ἐτήρει καιρὸν τοῦ ἀπατῆσαι αὐτὴν ἀφʼ ἧς ἡμέρας εἶδεν αὐτήν."}, {"sp": "N", "st": "Jdt 12:17", "t": "καὶ εἶπεν πρὸς αὐτὴν Ὀλοφέρνης Πίε δὴ καὶ γενήθητι μεθʼ ἡμῶν εἰς εὐφροσύνην."}, {"sp": "N", "st": "Jdt 12:18", "t": "καὶ εἶπεν Ἰουδείθ Πίομαι δή, κύριε, ὅτι ἐμεγαλύνθη τὸ ζῇν μου ἐν ἐμοὶ σήμερον παρὰ πάσας τὰς ἡμέρας τῆς γενέσεώς μου."}, {"sp": "N", "st": "Jdt 12:19", "t": "καὶ λαβοῦσα ἔφαγεν καὶ ἔπιεν κατέναντι αὐτοῦ ἃ ἡτοίμασεν ἡ δούλη αὐτῆς."}, {"sp": "N", "st": "Jdt 12:20", "t": "καὶ ηὐφράνθη Ὀλοφέρνης ἀπʼ αὐτῆς, καὶ ἔπιεν οἶνον πολὺν σφόδρα ὅσον οὐκ ἔπιεν πώποτε ἐν ἡμέρᾳ μιᾷ ἀφʼ οὗ ἐγεννήθη."}, {"sp": "N", "st": "Jdt 13:1", "t": "Ὡς δὲ ὀψία ἐγένετο, ἐσπούδασαν οἱ δοῦλοι αὐτοῦ ἀναλύειν· καὶ Βαγώας συνέκλεισεν τὴν σκηνὴν ἔξωθεν, καὶ ἀπέκλεισεν τοὺς παρεστῶτας ἐκ προσώπου τοῦ κυρίου αὐτοῦ, καὶ ἀπῴχοντο εἰς τὰς κοίτας αὐτῶν· (²)ἤσαν γὰρ πάντες κεκοπωμένοι διὰ τὸ ἐπὶ πλεῖον γεγονέναι τὸν πότον."}, {"sp": "N", "st": "Jdt 13:2", "t": "ὑπελείφθη δὲ Ἰουδεὶθ μόνη ἐν τῇ σκηνῇ. (4)καὶ Ὀλοφέρνης προπεπτωκὼς ἐπὶ τὴν κλίνην ἑαυτοῦ· ἦν γὰρ περικεχυμένος αὐτῷ ὁ οἶνος."}, {"sp": "N", "st": "Jdt 13:3", "t": "καὶ εἶπεν Ἰουδεὶθ τῇ δούλη αὐτῆς στῆναι ἔξω τοῦ κοιτῶνος αὐτῆς καὶ ἐπιτηρεῖν τὴν ἔξοδον αὐτῆς καθάπερ καθʼ ἡμέραν, ἐξελεύσεσθαι γὰρ ἔφη ἐπὶ τὴν προσευχὴν αὐτῆς· καὶ τῷ Βαγώᾳ ἐλάλησεν κατὰ τὰ ῥήματα ταῦτα."}, {"sp": "N", "st": "Jdt 13:4", "t": "καὶ ἀπήλθοσαν πάντες ἐκ προσώπου, καὶ οὐδεὶς κατελείφθη ἐν τῷ κοιτῶνι ἀπὸ μικροῦ ἕως μεγάλου· (⁶)καὶ στᾶσα Ἰουδεὶθ παρὰ τὴν κλίνην αὐτοῦ εἶπεν ἐν τῇ καρδίᾳ ἑαυτῆς (⁷)Κύριε ὁ θεὸς πάσης δυνάμεως, ἐπίβλεψον ἐν τῇ ὥρᾳ ταύτῃ ἐπὶ τὰ ἔργα τῶν χειρῶν μου, εἰς ὕψωμα Ἰερουσαλήμ·"}, {"sp": "N", "st": "Jdt 13:5", "t": "ὅτι νῦν καιρὸς ἀντιλαβέσθαι τῆς κληρονομίας σου καὶ ποιῆσαι τὸ ἐπιτήδευμά μου εἰς θραῦμα ἐχθρῶν οἱ ἐπανέστησαν ἡμῖν."}, {"sp": "N", "st": "Jdt 13:6", "t": "καὶ προσελθοῦσα τῷ κανόνι τῆς κλίνης ὃς ἣν πρὸς κεφαλῆς Ὀλοφέρνου καθεῖλεν τὸν ἀκινάκην αὐτοῦ ἀπʼ αὐτοῦ,"}, {"sp": "N", "st": "Jdt 13:7", "t": "καὶ ἐγγίσασα τῆς κλίνης ἐδράξατο τῆς κόμης τῆς κεφαλῆς αὐτοῦ, καὶ εἶπεν Κραταίωσόν με, ὁ θεὸς Ἰσραήλ, ἐν τῇ ἡμέρᾳ ταύτῃ."}, {"sp": "N", "st": "Jdt 13:8", "t": "καὶ ἐπάταξεν εἰς τὸν τράχηλον αὐτοῦ δὶς ἐν τῇ ἰσχύι αὐτῆς, καὶ ἀφεῖλεν τὴν κεφαλὴν αὐτοῦ,"}, {"sp": "N", "st": "Jdt 13:9", "t": "καὶ ἀπεκύλισε τὸ σῶμα αὐτοῦ ἀπὸ τῆς στρωμνῆς, καὶ ἀφεῖλε τὸ κωνώπιον ἀπὸ τῶν στύλων· (¹¹)καὶ μετʼ ὀλίγον ἐξῆλθεν καὶ παρέδωκεν τῇ ἅβρᾳ αὐτῆς τὴν κεφαλὴν Ὀλοφέρνου,"}, {"sp": "N", "st": "Jdt 13:10", "t": "καὶ ἐνέβαλεν αὐτὴν εἰς τὴν πήραν τῶν βρωμάτων αὐτῆς· (¹²)καὶ ἐξῆλθον αἱ δύο ἄμα κατὰ τὸν ἐθισμὸν αὐτῶν. καὶ διελθοῦσαι τὴν παρεμβολὴν ἐκύκλωσαν τὴν φάραγγα ἐκείνην, καὶ προσανέβησαν τὸ ὄρος Βαιτυλουά, καὶ ἤλθοσαν πρὸς τὰς πύλας αὐτῆς."}, {"sp": "N", "st": "Jdt 13:11", "t": "Καὶ εἶπεν Ἰουδεὶθ μακρόθεν τοῖς φυλάσσουσιν ἐπὶ τῶν πυλῶν Ἀνοίξατε, ἀνοίξατε δὴ τὴν πύλην· μεθʼ ἡμῶν ὁ θεὸς ὁ θεὸς ἡμῶν ποιῆσαι ἔτι ἰσχὺν ἐν Ἰσραὴλ καὶ κράτος κατὰ τῶν ἐχθρῶν ἡμῶν, καθὰ καὶ σήμερον ἐποίησεν."}, {"sp": "N", "st": "Jdt 13:12", "t": "καὶ ἐγένετο ὡς ἤκουσαν οἱ ἄνδρες τῆς πόλεως αὐτῆς τὴν φωνὴν αὐτῆς, ἐσπούδασαν τοῦ καταβῆναι ἐπὶ τὴν πύλην τῆς πόλεως αὐτῶν, καὶ συνεκάλεσαν τοὺς πρεσβυτέρους τῆς πόλεως."}, {"sp": "N", "st": "Jdt 13:13", "t": "καὶ συνέδραμον πάντες ἀπὸ μικροῦ ἕως μεγάλου αὐτῶν, ὅτι παράδοξον ἣν αὐτοῖς τοῦ ἐλθεῖν αὐτήν, καὶ ἤνοιξαν τὴν πύλην καὶ ἀπεδέξαντο αὐτάς· (¹⁶)ἅψαντες πῦρ εἰς φαῦσιν περιεκύκλωσαν αὐτάς."}, {"sp": "N", "st": "Jdt 13:14", "t": "ἡ δὲ εἶπεν πρὸς αὐτοὺς φωνῇ μεγάλῃ Αἰνεῖτπ τὸν θεόν, αἰνεῖτε· αἰνεῖτε τὸν θεὸν ὃς (18)οὐκ ἀπέστησεν τὸ ἔλεος αὐτοῦ ἀπὸ τοῦ οἴκου Ἰσραήλ, ἀλλ᾿ ἔθραυσε τοὺς ἐχθροὺς ἡμῶν διὰ χειρός μου ἐν τῇ νυκτὶ ταύτῃ."}, {"sp": "N", "st": "Jdt 13:15", "t": "καὶ προελοῦσα τὴν κεφαλὴν ἐκ τῆς πήρας ἔδειξεν καὶ εἶπεν αὐτοῖς Ἰδοὺ ἡ κεφαλὴ Ὀλοφέρνου ἀρχιστρατήγου δυνάμεως Ἀσσούρ, καὶ ἰδοὺ τὸ κωνώπιον ἐυ ᾧ κατέκειτο ἐν ταῖς μέθαις αὐτοῦ· καὶ ἐπάταξεν αὐτὸν ὁ κύριος ἐν χειρὶ θηλείας."}, {"sp": "N", "st": "Jdt 13:16", "t": "καὶ ζῇ Κύριος ὃς διεφύλαξέν με ἐν τῇ ὁδῷ μου ᾖ ἐπορεύθην, ὅτι ἠπάτησεν αὐτὸν τὸ πρόσωπόν μου εἰς ἀπώλειαν αὐτοῦ, καὶ οὐκ ἐποίησεν ἁμάρτημα μετʼ ἐμοῦ εἰς μίασμα καὶ αἰσχύνην."}, {"sp": "N", "st": "Jdt 13:17", "t": "καὶ ἐξέστη πᾶς ὁ λαὸς σφόδρα, καἰ κύψαντες προσεκύνησαν τῷ θεῷ καὶ εἶπαν ὁμοθυμαδόν Εὐλογητὸς εἶ ὁ θεὸς ἡμῶν ὁ ἐξουδενώσας ἐν τῇ ἡμέρᾳ τῇ σήμερον τοὺς ἐχθροὺς τοῦ λαοῦ σου."}, {"sp": "N", "st": "Jdt 13:18", "t": "καὶ εἶπεν αὐτῇ Ὀζείας Εὐλογητὴ σύ, θυγάτηρ, τῷ θεῷ τῷ ὑψίστῳ παρὰ πάσας τὰς γυναῖκας τὰς ἐπὶ τῆς γῆς, (24)καὶ εὐλογημένος Κύριος ὁ θεὸς ὃς ἔκτισεν τοὺς οὐρανοὺς καὶ τὴν γῆν, ὃς κατεύθυνέν σε εἰς τραῦμα κεφαλῆς ἄρχοντος ἐχθρῶν ἡμῶν·"}, {"sp": "N", "st": "Jdt 13:19", "t": "ὅτι οὐκ ἀποστήσεται ἡ ἐλπίς σου ἀπὸ καρδίας ἀνθρώπων μνημονευόντων ἰσχὺν θεοῦ ἕως αἰῶνος."}, {"sp": "N", "st": "Jdt 13:20", "t": "καὶ ποιήσαι σοι αὐτὰ ὁ θεὸς εἰς ὕψος αἰώνιον, τοῦ ἐπισκέψασθαί σε ἐν ἀγαθοῖς, ἀνθʼ ὧν οὐκ ἐφείσω τῆς ψυχῆς σου διὰ τὴν ταπείνωσιν τοῦ γένους ἡμῶν, ἀλλ᾿ ἐπεξῆλθες πτώματι ἡμῶν, ἐπʼ εὐθεῖαν πορευθεῖσα ἐνώπιον τοῦ θεοῦ ἡμῶν. (26) καὶ εἶπαν πᾶς ὁ λαός Γένοιτο, γένοιτο."}, {"sp": "N", "st": "Jdt 14:1", "t": "Καὶ εἶπεν πρὸς αὐτοὺς Ἰουδείθ Ἀκούσατε δὴ μου, ἀδελφοί, καὶ λαβόντες τὴν κεφαλὴν ταύτην κρεμάσατε αὐτὴν ἐπὶ τῆς ἐπάλξεως τοῦ τείχους ὑμῶν."}, {"sp": "N", "st": "Jdt 14:2", "t": "καὶ ἔσται ἡνίκα ἐὰν διαφαύσῃ ὁ ὄρθρος καὶ ἐξέλθῃ ὁ ἥλιος ἐπὶ τὴν γῆν, ἀναλήμψεσθε ἕκαστος τὰ σκεύη τὰ πολεμικὰ ὑμῶν καὶ ἐξελεύσεσθε πᾶς ἀνὴρ ἰσχύων ἔξω τῆς πόλεως, καὶ δώσετε ἀρχηγὸν εἰς αὐτούς, ὡς καταβαίνοντες ἐπὶ τὸ πεδίον εἰς τὴν προφυλακὴν υἱῶν Ἀσσούρ· καὶ οὐ καταβήσεσθε."}, {"sp": "N", "st": "Jdt 14:3", "t": "καὶ ἀναλαβόντες οὗτοι τὰς πανοπλίας αὐτῶν πορεύσονται εἰς τὴν παρεμβολὴν αὐτῶν καὶ ἐγεροῦσι τοὺς στρατηγοὺς τῆς δυνάμεως Ἀσσούρ· (4) καὶ συνδραμοῦνται ἐπὶ τὴν σκηνὴν Ὀλοφέρνου, καὶ οὐχ εὑρήσουσιν αὐτόν· καὶ ἐπιπεσεῖται ἐπʼ αὐτοὺς φόβος, καὶ φεύξονται ἀπὸ προσώπου ὑμῶν."}, {"sp": "N", "st": "Jdt 14:4", "t": "καὶ ἐπακολουθήσαντες ὑμεῖς καὶ πάντες οἱ κατοικοῦντες πᾶν ὅριον Ἰσραὴλ καταστρώσατε αὐτοὺς ἐν ταῖς ὁδοῖς αὐτῶν."}, {"sp": "N", "st": "Jdt 14:5", "t": "πρὸ δὲ τοῦ ποιῆσαι ταῦτα καλέσατέ μοι Ἀχιὼρ τὸν Ἀμμανείτην, ἵνα ἰδὼν ἐπιγνοῖ τὸν ἐκφαυλίσαντα τὸν οἶκον τοῦ Ἰσραήλ, καὶ αὐτὸν ὡς εἰς θάνατον ἀποστείλαντα εἰς ἡμᾶς."}, {"sp": "N", "st": "Jdt 14:6", "t": "Καὶ ἐκάλεσαν τὸν Ἀχιὼρ ἐκ τοῦ οἴκου Ὀζεἰα· (29)ὡς δὲ ἦλθεν καὶ ἴδεν τὴν κεφαλὴν Ὀλοφέρνου ἐν χειρὶ ἀνδρὸς ἑνὸς ἐν τῇ ἐκκλησίᾳ τοῦ λαοῦ, ἔπεσεν ἐπὶ πρόσωπον, καὶ ἐξελύθη τὸ πνεῦμα αὐτοῦ."}, {"sp": "N", "st": "Jdt 14:7", "t": "ὡς δὲ ἀνέλαβον αὐτόν, προσέπεσεν τοῖς ποσὶν Ἰουδεὶθ καὶ προσεκύνησεν τῷ προσώπῳ αὐτῆς καὶ εἶπεν (³¹)Εὐλογημένη σὺ ἐν παντὶ σκηνώματι Ἰούδα καὶ ἐν παντὶ ἔθνει, οἵτινες ἀκούσαντες τὸ ὄνομά σου ταραχθήσονται."}, {"sp": "N", "st": "Jdt 14:8", "t": "καὶ νῦν ἀνάγγειλόν μοι ὅσα ἐποίησας ἐν ταῖς ἡμέραις ταύταις. καὶ ἀπήγγειλεν αὐτῷ Ἰουδεὶθ ἐν μέσῳ τοῦ λαοῦ πάντα ὅσα ἦν πεποιηκυῖα, ἀφʼ ἧς ἡμέρας ἐξῆλθεν ἕως ο ἐλάλει αὐτοῖς."}, {"sp": "N", "st": "Jdt 14:9", "t": "ὡς δὲ ἐπαύσατο λαλοῦσα, ἠλάλαξεν ὁ λαὸς φωνῇ μεγάλῃ καὶ ἔδωκεν φωνὴν εὐφρόσυνον ἐν τῇ πόλει αὐτῶν."}, {"sp": "N", "st": "Jdt 14:10", "t": "δῦ δὲ Ἀχιὼρ πάντα ὅσα ἐποίησεν ὁ θεὸς τοῦ Ἰσραήλ, ἐπίστευσεν τῷ θεῷ σφόδρα, καὶ περιετέμετο τὴν σάρκα τῆς ἀκροβυστίας αὐτοῦ, καὶ προσετέθη πρὸς τὸν οἶκον Ἰσραὴλ ἕως τῆς ἡμέρας ταύτης."}, {"sp": "N", "st": "Jdt 14:11", "t": "Ἡνίκα δὲ ὁ ὄρθρος ἀνέβη, καὶ ἐκρέμασαν τὴν κεφαλὴν Ὀλοφέρνου ἐκ τοῦ τείχους, καὶ ἀνέλαβεν πᾶς ἀνὴρ Ἰσραὴλ τὰ ὅπλα αὐτοῦ καὶ ἐξήλθοσαν κατὰ σπείρας ἐπὶ τὰς ἀναβάσεις."}, {"sp": "N", "st": "Jdt 14:12", "t": "οἱ δὲ υἱοὶ Ἀσσοὺρ ὡς ἴδον αὐτούς, διέπεμψαν ἐπὶ τοὺς ἡγουμένους αὐτῶν· οἵ δὲ ἦλθον ἐπὶ τοὺς στρατηγοὺς καὶ χιλιάρχους καὶ ἐπὶ πάντα ἄρχοντα αὐτῶν."}, {"sp": "N", "st": "Jdt 14:13", "t": "καὶ παρεγένοντο ἐπὶ τὴν σκηνὴν Ὀλοφέρνου, καὶ εἶπαν τῷ ὄντι ἐπὶ πάντων τῶν αὐτοῦ Ἔγειρον δὴ τὸν κύριον ἡμῶν, ὅτι ἐτόλμησαν οἱ δοῦλοι καταβαίνειν ἐφʼ ἡμᾶς εἰς πόλεμον, ἵνα ἐξολεθρευθῶσιν εἰς τέλος."}, {"sp": "N", "st": "Jdt 14:14", "t": "καὶ εἰσῆλθεν Βαγώας καὶ ἔκρουσε τὴν αὐλαίαν τῆς σκηνῆς· ὑπενοεῖτο γὰρ καθεύδειν αὐτὸν μετὰ Ἰουδείθ."}, {"sp": "N", "st": "Jdt 14:15", "t": "ὡς δʼ οὐθεὶς ἐπήκουσεν, διαστείλας εἰσῆλθεν εἰς τὸν κοιτῶνα, καὶ εὗρεν αὐτὸν ἐπὶ τῆς χελωνίδος ἐριμμένον νεκρόν, καὶ ἡ κεφαλὴ αὐτοῦ αφῄρητο ἀπʼ αὐτοῦ."}, {"sp": "N", "st": "Jdt 14:16", "t": "καὶ ἐβόησεν φωνῇ μεγάλῃ μετὰ κλαυθμοῦ καὶ στεναγμοῦ καὶ βοῆς ἰσχυρᾶς, καὶ διέρρηξεν τὰ ἱμάτια αὐτοῦ."}, {"sp": "N", "st": "Jdt 14:17", "t": "καὶ εἰσῆλθεν εἰς τὴν σκηνὴν οὗ ἦν Ἰουδεὶθ καταλύουσα, καὶ οὐχ εἶρεν αὐτὴν· καὶ ἐξεπήδησεν εἰς τὸν λαὸν (¹⁶)κράζων"}, {"sp": "N", "st": "Jdt 14:18", "t": "Ἠθέτησαν οἱ δοῦλοι, ἐποίησεν αἰσχύνην μία γυνὴ τῶν Ἐβραίων εἰς τὸν οἶκον τοῦ βασιλέως Ναβουχοδονοσόρ· ὅτι ἰδοὺ Ὀλοφέρνης χαμαί, καὶ ἡ κεφαλὴ οὐκ ἔστιν ἐπʼ αὐτῷ."}, {"sp": "N", "st": "Jdt 14:19", "t": "ὡς δὲ ἤκουσαν τὰ ῥήματα οἱ ἄρχοντες τῆς δυνάμεως Ἀσσούρ, τοὺς χιτῶνας αὐτῶν διέρρηξαν, καὶ ἐταράχθη αὐτῶν ἡ ψυχὴ σφόδρα, (¹⁸) καὶ ἐγένετο αὐτῶν κραυγὴ καὶ βοὴ μεγάλη σφόδρα ἐν μέσῳ τῆς παρεμβολῆς."}, {"sp": "N", "st": "Jdt 15:1", "t": "Καὶ ὡς ἤκουσαν οἱ ἐν τοῖς σκηνώμασιν ὄντες, ἐξέστησαν ἐπὶ τὸ γεγονός,"}, {"sp": "N", "st": "Jdt 15:2", "t": "καὶ ἐπέπεσεν ἐπʼ αὐτοὺς τρόμος καὶ φόβος, (²)καὶ οὐκ ἦν ἄνθρωπος μένων κατὰ πρόσωπον τοῦ πλησίον ἔτι, ἀλλ᾿ ἐκχυθέντες ὁμοθυμαδὸν ἔφευγον ἐπὶ πᾶσαν ὁδὸν τοῦ πεδίου καὶ τῆς ὀρινῆς."}, {"sp": "N", "st": "Jdt 15:3", "t": "καὶ οἱ παρεμβεβληκότες ἐν τῇ ὀρίνῇ κύκλῳ Βαιτυλουὰ καὶ ἐτράπησαν εἰς φυγὴν· καὶ τότε οἱ υἱοὶ Ἰσραὴλ πᾶς ἀνὴρ πολεμιστὴς ἐξ αὐτῶν ἐξεχύθησαν ἐπʼ αὐτούς."}, {"sp": "N", "st": "Jdt 15:4", "t": "καὶ ἀπέστειλεν Ὀζείας εἰς Βαιτομασθάιμ καὶ Χωβαὶ καὶ Χωλὰ καὶ εἰς πᾶν ὅριον Ἰσραὴλ τοὺς ἀπαγγέλλοντας ὑπέρ τῶν συντετελεσμένων, καὶ ἴνα πάντες ἐπεκχυθῶσιν τοῖς πολεμίοις εἰς τὴν ἀναίρεσιν αὐτῶν."}, {"sp": "N", "st": "Jdt 15:5", "t": "ὡς δέ ἤκουσαν οἱ υἱοὶ Ἰσραήλ, πἀντες ὁμοθυμαδὸν ἐπέπεσον ἐπʼ αὐτοὺς καὶ ἔκοπτον αὐτοὺς ἕως Χωβά. ὡσαύτως δέ καὶ οἱ ἐξ Ἰερουσαλὴμ παρεγενήθησαν καὶ ἐκ πάσης τῆς ὀρίνῆς, ἀνήγγειλαν γὰρ αὐτοῖς τὰ γεγονότα τῇ παρεμβολῇ τῶν ἐχθρῶν αὐτῶν· καὶ οἱ ἐν Γαλαὰδ καὶ οἱ ἐν τῇ Γαλειλαίᾳ ὑπερεκέρασαν αὐτοὺς πληγῇ μεγάλῃ, ἕως οὗ παρῆλθον Δαμασκὸν καὶ τὰ ὅρια αὐτῆς."}, {"sp": "N", "st": "Jdt 15:6", "t": "οἱ δὲ λοιποὶ οἱ κατοικοῦντες Βαιτυλουὰ ἐπέπεσαν τῇ παρεμβολῇ Ἀσσοὺρ καὶ ἐπρονόμευσαν αὐτούς, καὶ ἐπλούτησαν σφόδρα."}, {"sp": "N", "st": "Jdt 15:7", "t": "οἱ δὲ υἱοὶ Ἰσραὴλ ἀναστρέψαντες ἀπὸ τῆς κοπῆς ἐκυρίευσαν τῶν λοιπῶν, καὶ αἵ κῶμαι καὶ ἐπαύλεις ἐν τῇ ὀρινῇ καὶ πεδινῇ ἐκράτησαν πολλῶν λαφύρων, ἦν γὰρ πλῆθος πολὺ σφόδρα."}, {"sp": "N", "st": "Jdt 15:8", "t": "Καὶ Ἰωακεὶμ ὁ ἱερεὺς ὁ μέγας καὶ ἡ γερουσία τῶν υἱῶν Ἰσραὴλ οἱ κατοικοῦντες ἐν Ἰερουσαλὴμ ἦλθον τοῦ θεάσασθαι τὰ ἀγαθὰ ἃ ἐποίησεν Κύριος τῷ Ἰσραήλ, καὶ τοῦ ἰδεῖν τὴν Ἰουδεὶθ καὶ λαλῆσαι μετʼ αὐτῆς εἰρήνην."}, {"sp": "N", "st": "Jdt 15:9", "t": "ὡς δὲ εἰσῆλθον πρὸς αὐτήν, εὐλόγησαν αὐτὴν πάντες ὁμοθυμαδὸν καὶ εἶπαν πρὸς αὐτήν Σὺ ὕψωμα Ἰερουσαλήμ, σὺ γαυρίαμα μέγα τοῦ Ἰσραήλ, σὺ καύχημα μέγα τοῦ γένους ἡμῶν."}, {"sp": "N", "st": "Jdt 15:10", "t": "ἐποίησας πάντα ταῦτα ἐν χειρί σου, ἐποίησας τὰ ἀγαθὰ μετὰ Ἰσραήλ, καὶ εὐδοκήσοι ἐπʼ αὐτοῖς ὁ θεός· εὐλογημένη γίνου παρὰ τῷ παντοκράτορι κυρίῳ εἰς τὸν αἰῶνα χρόνον. (¹²)καὶ εἶπεν πᾶς ὁ λαός Γένοιτο."}, {"sp": "N", "st": "Jdt 15:11", "t": "καὶ ἐλαφύρευσεν πᾶς ὁ λαὸς τὴν παρεμβολὴν ἐφʼ ἡμέρας τριάκοντα, (¹⁴)καὶ ἔδωκαν τῇ Ἰουδεὶθ τὴν σκηνὴν Ὀλοφέρνου καὶ πάντα τὰ ἀργυρώματα καὶ τὰς κλίνας καὶ τὰ ὅλκια καὶ πάντα τὰ σκευάσματα αὐτοῦ· καὶ λαβοῦσα αὕτη ἐπέθηκεν ἐπὶ τὴν ἡμίονον αὐτῆς, καὶ ἔζευξεν τὰς ἁμάξας αὐτῆς, καὶ ἐσώρευσεν αὐτὰ ἐπʼ αὐτῶν."}, {"sp": "N", "st": "Jdt 15:12", "t": "Καὶ συνέδραμεν πᾶσα γυνὴ Ἰσραὴλ τοῦ ἰδεῖν αὐτήν, καὶ εὐλόγησαν αὐτήν, καὶ ἐποίησαν αὐτῇ χορὸν ἐξ αὐτῶν· καὶ ἔλαβεν θύρσους ἐν ταῖς χερσὶν αὐτῆς, καὶ ἔδωκεν ταῖς γυναιξὶν ταῖς μετʼ αὐτῆς,"}, {"sp": "N", "st": "Jdt 15:13", "t": "καὶ ἐσπεφανώσαντο τὴν ἐλαίαν αὕτη καὶ αἱ μετʼ αὐτῆς· καὶ προῆλθεν παντὸς τοῦ λαοῦ ἐν χορείᾳ ἡγουμένη πασῶν τῶν γυναικῶν, καὶ ἠκολούθει πᾶς ἀνὴρ Ἰσραὴλ ἐνωπλισμένοι μετὰ στεφάνων καὶ ὕμνων ἐν τῷ στόματι αὐτῶν."}, {"sp": "N", "st": "Jdt 15:14", "t": "καὶ ἐξῆρχεν Ἰουδεὶθ τὴν ἐξομολόγησιν ταύτην ἐν παντὶ Ἰσραήλ, καὶ ὑπερεφώνει πᾶς ὁ λαὸς τὴν αἴνεσιν ταύτην·"}, {"sp": "N", "st": "Jdt 16:1", "t": "καὶ εἶπεν Ἰουδείθ (²)Ἐξάρχετε τῷ θεῷ μου ἐν τυμπάνοις. ᾄσατε τῷ κυρίῳ ἐν κυμβάλοις, ἐναρμόσασθε αὐτῷ ψαλμὸν καὶ αἶνον, ὑψοῦτε καὶ ἐπικαλεῖρθε τὸ ὄνομα αὐτοῦ."}, {"sp": "N", "st": "Jdt 16:2", "t": "²ὅτι θεὸς συντρίβων πολέμους Κύριος, (4)ὕτι εἰς παρεμβολὰς αὐτοῦ ἐν μέσῳ λαοῦ ἐξείλατό με ἐκ χειρὸς καταδιωκόντων με."}, {"sp": "N", "st": "Jdt 16:3", "t": "³ἦλθεν Ἀσσοὺρ ἐξ ὀρέων ἀπὸ βορρᾶ. ἦλθεν ἐν μυριάσι δυνάμεων αὐτοῦ, ὧν τὸ πλῆθος αὐτῶν ἐνέφραξεν χειμάρρους. καὶ ἡ ἵππος αὐτῶν ἐκάλυψεν βουνούς."}, {"sp": "N", "st": "Jdt 16:4", "t": "4εἶπεν ἐμπρήσειν τὰ ὄρη μου, καὶ τοὺς νεανίσκους μου ἀνελεῖν ῥομφαίᾳ, καὶ τὰ θηλάζοντά μου θήσειν εἰς ἔδαφος, καὶ τὰ νήπιά μου δώσειυ εἰς προνομήν, καὶ τὰς παρθένους σκυλεῦσαι."}, {"sp": "N", "st": "Jdt 16:5", "t": "5Κύριος Παντοκράτωρ ἠθέτησεν αὐτοὺς ἐν χειρὶ θηλείας."}, {"sp": "N", "st": "Jdt 16:6", "t": "6οὐ γὰρ ὑπέπεσεν ὁ δυνατὸς αὐτῶν ὑπὸ νεανίσκων, οὐδὲ υἱοὶ Τιτάνων ἐπάταξαν αὐτόν, οὐδὲ ὑψηλοὶ γίγαντες ἐπέθεντο αὐτῷ· ἀλλὰ Ἰουδεὶθ θυγάτηρ Μεραρεί· ἐν κάλλει προσώπου αὐτῆς παρέλυσεν αὐτόν."}, {"sp": "N", "st": "Jdt 16:7", "t": "7ἐξεδύσατο γὰρ στολὴν χηρεύσεως αὐτῆς εἰς ὕψος τῶν πονούντων ἐν Ἰσραήλ, (10)ἠλείψατο τὸ πρόσωπον αὐτῆς ἐν μυρισμῷ,"}, {"sp": "N", "st": "Jdt 16:8", "t": "8καὶ ἐδήσατο τὰς τρίχας αὐτῆς ἐν μίτρᾳ, καὶ ἔλαβεν στολὴν λινῆν εἰς ἀπάτην αὐτοῦ."}, {"sp": "N", "st": "Jdt 16:9", "t": "9τὸ σανδάλιον αὐτῆς ἤρπασεν ὀφθαλμὸν αὐτοῦ, καὶ τὸ κάλλος αὐτῆς ἠχμαλώτισεν ψυχὴν αὐτοῦ. διῆλθεν ὁ ἀκινάκης τὸν τράχηλον αὐτοῦ."}, {"sp": "N", "st": "Jdt 16:10", "t": "¹0ἔφριξαν Πέρσαι τὴν τόλμαν αὐτῆς, καὶ Μῆδοι τὸ θράσος αὐτῆς ἐρράχθησαν."}, {"sp": "N", "st": "Jdt 16:11", "t": "¹¹τότε ἠλάλαξαν οἱ ταπεινοί μου, καὶ ἐφοβήθησαν οἱ ἀσθενοῦντές μου καὶ ἐπτοήθησαν· ὕψωσαν τὴν φωνὴν αὐτῶν καὶ ἀνετράπησαν."}, {"sp": "N", "st": "Jdt 16:12", "t": "12υἱοὶ κορασίων κατεκέντησαν αὐτούς, καὶ ὡς παῖδας αὐτομολούντων ἐτίτρωσκον· ἀπώλοντο ἐκ παρατάξεως κυρίου μου."}, {"sp": "N", "st": "Jdt 16:13", "t": "¹³ὑμνήσω τῷ θεῷ μου ὕμνον καινόν. (16)Κύριε. μέγας εἶ καὶ ἔνδοξος. θαυμαστὸς ἐν ἰσχύι, ἀνυπέρβλητος."}, {"sp": "N", "st": "Jdt 16:14", "t": "¹4σοὶ δουλευσάτω πᾶσα ἡ κτίσις σου· ὅτι εἶπας, καὶ ἐγενήθησαν· ἀπέστειλας τὸ πνεῦμά σου, καὶ ᾠκοδόμησεν· καὶ οὐκ ἔστιν ὃς ἀντιστήσεται τῇ φωνῇ σου."}, {"sp": "N", "st": "Jdt 16:15", "t": "¹5ὄρη γὰρ ἐκ θεμελίων σὺν ὕδασιν σαλευθήσεται, πέτραι δʼ ἀπὸ προσώπου σου ὡς κηρὸς τακήσονται· (19)ἔτι δὲ τοῖς φοβουμένοις σε, σὺ εὐιλατεύεις αὐτοῖς."}, {"sp": "N", "st": "Jdt 16:16", "t": "¹6ὅτι μικρὸν πᾶσα θυσία εἰ ὀσμὴν εὐωδίας, καὶ ἐλάχιστον πᾶν ?? ?? εἰς ὁλοκαύτωμά σοι ὁ δὲ φοβούμενος τὸν ?? ?? μέγας διὰ παντός."}, {"sp": "N", "st": "Jdt 16:17", "t": "¹7οὐαὶ ἔθνεσιν ?? τῷ γένει μου· Κύριος Παντοκράτωρ ἐκδικήσει αὐτοὺς ἐν ἡμέρᾳ κρίσεως, (21)δοῦναι πῦρ καὶ σκώληκας εἰς σάρκας αὐτῶν, καὶ κλαύσονται ἐν αἰσθήσει ἕως αἰῶνος."}, {"sp": "N", "st": "Jdt 16:18", "t": "Ὡς δὲ ἤλθοσαν εἰς Ἰερουσαλήμ, προσεκύνησαν τῷ θεῷ, καὶ ἡνίκα ἐκαθαρίσθη ὁ λαός, ἀνήνεγκαν τὰ ὁλοκαυτώματα αὐτῶν καὶ τὰ ἑκούσια αὐτῶν καὶ τὰ δόματα."}, {"sp": "N", "st": "Jdt 16:19", "t": "καὶ ἀνέθηκεν Ἰουδεὶθ πάντα τὰ σκεύη Ὀλοφέρνου ὅσα ἔδωκεν ὁ λαὸς αὐτῇ, καὶ τὸ κωνώπιον ὃ ἔλαβεν ἑαυτῇ ἐκ τοῦ κοιτῶνος αὐτοῦ εἰς ἀνάθημα τῷ θεῷ ἔδωκεν."}, {"sp": "N", "st": "Jdt 16:20", "t": "καὶ ἣν ὁ λαὸς εὐφραινόμενος ἐν Ἰερουσαλὴμ κατὰ πρόσωπον τῶν ἁγίων ἐπὶ μῆνας τρεῖς, καὶ Ἰουδεὶθ μετʼ αὐτῶν κατέμενεν."}, {"sp": "N", "st": "Jdt 16:21", "t": "Μετὰ δὲ τὰς ἡμέρας ταύτας ἀνέζευξεν ἕκαστος εἰς τὴν κληρονομίαν αὐτοῦ, καὶ Ἰουδεὶθ ἀπῆλθεν εἰς Βαιτυλουὰ καὶ κατέμεινεν ἐπὶ τῆς ὑπάρξεως αὐτῆς· καὶ ἐγένετο κατὰ τὸν καιρὸν αὐτῆς ἔνδοξος ἐν πάσῃ τῇ γῇ."}, {"sp": "N", "st": "Jdt 16:22", "t": "καὶ πολλοὶ ἐπεθύμησαν αὐτήν, καὶ οὐκ ἔγνω ἀνὴρ αὐτὴν πάσας τὰς ἡμέρας τῆς ζωῆς αὐτῆς, ἀφʼ ἧς ἡμέρας ἀπέθανεν Μανασσῆς ὁ ἀνὴρ αὐτῆς καὶ προσετέθη πρὸς τὸν λαὸν αὐτοῦ."}, {"sp": "N", "st": "Jdt 16:23", "t": "καὶ ἦν προβαίνουσα μεγάλη σφόδρα, (28)καὶ ἐγήρασεν ἐν τῷ οἴκῳ τοῦ ἀνδρὸς αὐτῆς ἔτη ἑκατὸν πέντε, καὶ ἀφῆκεν τὴν ἄβραν αὐτῆς ἐλευθέραν. καὶ ἀπέθανεν εἰς Βαιτυλουα, καὶ ἔθαψαν αὐτὴν ἐν τῷ σπηλαίῳ τοῦ ἀνδρὸς αὐτῆς Μανασσῆ."}, {"sp": "N", "st": "Jdt 16:24", "t": "καὶ ἐπένθησεν αὐτὴν οἶκος Ἰσραὴλ ἡμέρας ἑπτά. καὶ διεῖλεν τὰ ὑπάρχοντα αὐτῆς πρὸ τοῦ ἀποθανεῖν αὐτὴν πᾶσι τοῖς ἔγγιστα Μανασσῆ τοῦ ἀνδρὸς αὐτῆς καὶ τοῖς ἔγγιστα τοῦ γένους αὐτῆς."}, {"sp": "N", "st": "Jdt 16:25", "t": "καὶ οὐκ ἦν ἔτι ὁ ἐκφοβῶν τοὺς υἱοὺς Ἰσραὴλ ἐν ταῖς ἡμέραις Ἰουδεὶθ καὶ μετὰ τὸ ἀποθανεῖν αὐτὴν ἡμέρας πολλάς. ἀμήν."}, {"sp": "HDR", "t": "The Rest of the Chapters of the Book of Esther"}, {"sp": "N", "t": "<i>No Greek text of this book is included. In the Greek Bible these chapters are woven through the Book of Esther.</i>"}, {"sp": "HDR", "t": "ΣΟΦΙΑ ΣΑΛΩΜΩΝΟΣ"}, {"sp": "N", "st": "Wis 1:1", "t": "ΑΓΑΠΗΣΑΤΕ δικαιοσύνην, οἱ κρίνοντες τὴν γῆν· φρονήσατε περὶ τοῦ κυρίου ἐν ἀγαθότητι, καὶ ἐν ἁπλότητι καρδίας ζητήσατε αὐτόν."}, {"sp": "N", "st": "Wis 1:2", "t": "ὅτι εὑρίσκεται τοῖς μὴ πειράζουσιν αὐτόν, ἐμφανίζεται δὲ τοῖς μὴ ἀπιστοῦσιν αὐτῷ·"}, {"sp": "N", "st": "Wis 1:3", "t": "σκολοὶ γὰρ λογισμοὶ χωρίζουσιν ἀπὸ θεοῦ, δοκιμαζομένη τε ἡ δύναμις ἐλέγχει τοὺς ἄφρονας."}, {"sp": "N", "st": "Wis 1:4", "t": "ὅτι εἰς κακότεχνον ψυχὴν οὐκ εἰσελεύσεται σοφία, οὐδὲ κατοικήσει ἐν σώματι καταχρἐῳ ἁμαρτίας."}, {"sp": "N", "st": "Wis 1:5", "t": "ἅγιον γὰρ πνεῦμα παιδεἰας φεύξεται δόλον, καὶ ἀπαναστήσεται ἀπὸ λογισμῶν ἀσυνέτων, καὶ ἐλεγχθήσεται ἐπελθούσης ἀδικίας."}, {"sp": "N", "st": "Wis 1:6", "t": "φιλάνθρωπον γὰρ πνεῦμα σοφία, καὶ οὐκ ἀθῳώσει βλάσφημον ἀπὸ χελέων αὐτοῦὅτι τῶν νεφρῶν αὐτοῦ μάρτυς ὁ θεός, καὶ τῆς καρδίας αὐτοῦ ἐπίσκοπος ἀληθὴς καὶ τῆς γλώσσης ἀκουστής·"}, {"sp": "N", "st": "Wis 1:7", "t": "ὅτι πνεῦμα Κυρίου πεπλήρωκεν τὴν οἰκουμένην, καὶ τὸ συνέχον τὰ πάντα γνῶσιν ἔχει φωνῆς."}, {"sp": "N", "st": "Wis 1:8", "t": "δμὰ τοῦτο φθεγγόμενος ἄδικα οὐδεὶς μὴ λάθῃ, οὐδὲ μὴν παροδεύσῃ αὐτὸν ἐλέγχουσα ἡ δἰκη."}, {"sp": "N", "st": "Wis 1:9", "t": "ἐν γὰρ διαβουλίοις ἀσεβοῦς ἐξέτασις ἔσται, όγων δὲ αὐτοῦ ἀκοὴ πρὸς Κύριον ἤξει εἰς λεγχον ἀνομημάτων αὐτοῦ·"}, {"sp": "N", "st": "Wis 1:10", "t": "ὅτι ὖς ζηλώσεως ἀκροᾶται τὰ πάντα, καὶ θροῦς γογγυσμῶν οὐκ ἀποκρύπτεται."}, {"sp": "N", "st": "Wis 1:11", "t": "φυλάξασθε τοίνυν γογγυσμὸν ἀνωφελῆ, καὶ ἀπὸ καταλαλιᾶς φείσασθε γλώσσης· ὅτι φθέγμα λαθραῖον κενὸν οὐ πορεύσεται, στόμα δὲ καταψευδόμενον ἀναιρεῖ ψυχήν."}, {"sp": "N", "st": "Wis 1:12", "t": "μὴ ζηλοῦτε θάνατον ἐν πλάνῃ ζωῆς ὑμῶν, μηδὲ ἐπισπᾶσθε ὄλεθρον ἔργοις χειρῶν ὑμῶν·"}, {"sp": "N", "st": "Wis 1:13", "t": "ὅτι ὁ θεὸς θάνατον οὐκ ἐποίγῳεν, οὐδὲ τέρπεται ἐπʼ ἀπωλείᾳ ζώντων·"}, {"sp": "N", "st": "Wis 1:14", "t": "ἔκτισεν γὰρ εἰς τὸ εἶναι τὰ πάντα, καὶ σωτήριοι αἱ γενέσεις τοῦ κόσμου, καὶ οὐκ ἔστιν ἐν αὐταῖς φάρμακον ὀλέθρου, οδτε Μδοὺ βασίλειον ἐπὶ γῆς·"}, {"sp": "N", "st": "Wis 1:15", "t": "δικαιοσύνη γὰρ ἀθάνατός ἐστιν· ἀσεβεῖς δὲ ταῖς χερσὶν καὶ τοῖς λόγοις προσεκαλέσαντο α φίλον ἡγησάμενοι αὐτὸν ἐτάκησάν, καὶ συνθήκην ἔθεντο πρὸς αὐτόν, ὅτι ἰξιοί εἰσιν τῆς ἐκείνου μερίδος εἶναι"}, {"sp": "N", "st": "Wis 2:1", "t": "Εἶπον γὰρ ἐν ἑαυτοῖς λογισάμενοι οὐκ ὁρθῶς Ολίγος ἐστὶν καὶ λυπηρὸς ὁ βίος ἡμῶν, καὶ οὐκ ἔστιν ἴασις ἐν τελευτῇ ἀνθρώπου, καὶ οὐκ ἐγνώσθη ὁ ἀναλύσας ἐξ ᾅδου"}, {"sp": "N", "st": "Wis 2:2", "t": "ὅτι αὐτοσχεδίως ἐγενήθημεν, καὶ μετὰ τοῦτο ἐσόμεθα ὡς οὐχ ὑπάρξαντες· ὅτι καπνὸς ἡ πνοὴ ἐν ῥισὶν ἡμῶν, καὶ ὁ λόγος σπινθὴρ ἐν κινήσει καρδίας ἡμῶν,"}, {"sp": "N", "st": "Wis 2:3", "t": "οἶ πβεσθέντος τέφρα ἀποβήσεται τὸ σῶμα, καὶ τὸ πνεῦμα δαχυθήσεται ὡς χαῦνος ἀὴρ."}, {"sp": "N", "st": "Wis 2:4", "t": "καὶ τὸ ὄνομα ἡμῶν ἐπιλησθήσεται ἐν χρόνᾳῃ, καὶ οὐθεὶς μνημονεύσει τῶν ἔργων ἡμῶν· καὶ παρελεύσεται ὁ βίος ἡμῶν ὡς ἴχνη νεφέλης, καὶ ὡς ὁμίχλη διασκεδασθήσεται διωχθεῖσα ὑπὸ ἀκτίνων ἡλίου καὶ ὑπὸ θερμότητος αὐτοῦ βαρυνθεῖσα."}, {"sp": "N", "st": "Wis 2:5", "t": "σκιᾶς γὰρ πάροδος ὁ βίος ἡμῶν. καὶ οὐκ ἔστιν ἀναποδισμὸς τῆς τελευτῆς ἡμῶν, ὅτι κατεσφραγίσθη, καὶ οὐδεὶς ἀναστρέφει."}, {"sp": "N", "st": "Wis 2:6", "t": "δεῦτε οὖν καὶ ἀπολαύσωμεν τῶν ὄντων ἀγαθῶν, καὶ χρησώμεθα τῇ κτίσει ὡς νεότητι σπουδαίως·"}, {"sp": "N", "st": "Wis 2:7", "t": "οἴνου πολυτελοῦς καὶ μύρσων πλησθῶμεν, καὶ μὴ παροδευσάτω ἡμᾶς ἄνθος ἀέρος·"}, {"sp": "N", "st": "Wis 2:8", "t": "στεψώμεθα ῥόδων κάλυξιν πρὶν ἢ μαρανθῆναι"}, {"sp": "N", "st": "Wis 2:9", "t": "μηδεὶς ἡμῶν ἄμοιρος ἔστω τῆς ἡμετέρας ἀγερωχίας, πανταχῇ καταλίπωμεν σύμβολα τῆς εὐφροσύνης, ὅτι αὕτη ἡ μερὶς ἡμῶν καὶ ὁ κλῆρος οὗτος."}, {"sp": "N", "st": "Wis 2:10", "t": "καταδυναστεύσωμεν πένητα δίκαιον, μὴ φεισώμεθα χήρας. μηδέ πρεσβύτου ἐντραπῶμεν πολιὰς πολυχρονίους·"}, {"sp": "N", "st": "Wis 2:11", "t": "ἔτῶ δὲ ἡμῶυ ἡ ἰσχὺς νόμος τῆς δικαιοσύνης, τὸ γὰρ ἀσθενές ἄχρηστον ἐλέγχεται."}, {"sp": "N", "st": "Wis 2:12", "t": "ἐνεδρεύσαομεν δὲ τὸν δίκαιον, ὅτι δύσχρηστος ἡμῖν ἐστιν, καὶ ἐναντιοῦται τοῖς ἔργοις ἡμῶν, καὶ ὀνειδίζει ἡμῖν ἁμαρτῆματα νόμου, καὶ ἐπιφημίζει ἡμῖν ἁμαρτήματα παιδείας ἡμῶν·"}, {"sp": "N", "st": "Wis 2:13", "t": "ἐπαγγέλλεται γνῶσιν ἔχειν θεοῦ, καὶ παῖδα Κυρίου ἑαυτὸν ὀνομάζει·"}, {"sp": "N", "st": "Wis 2:14", "t": "ἐγένετο ἡμῖν εἰς ἔλεγχον ἐννοιῶν ἡμῶν· βαρύς ἐστιν ἡμῖν καὶ βλεπόμενος."}, {"sp": "N", "st": "Wis 2:15", "t": "ὅτι ἀνόμοιος τοῖς ἄλλοις ὁ βίος αὐτοῦ, καὶ ἐξηλλαγμέναι αἱ τρίβοι αὐτοῦ·"}, {"sp": "N", "st": "Wis 2:16", "t": "εἰς κίβδηλον ἐλογίσθημεν αὐτῷ, καὶ ἀπέχεται τῶν ὁδῶν ἡμῶν ὡς ἀπὸ ἀκαθαρσιῶν· μακαρίζει ἔσχατα δικαίων, καὶ ἀλαζονεύεται πατέρα θεόν."}, {"sp": "N", "st": "Wis 2:17", "t": "ἴδωμεν εἰ οἱ λόγοι αὐτοῦ ἀληθεῖς, καὶ πειράσαωμεν τὰ ἐν ἐκβάσει αὐτοῦ."}, {"sp": "N", "st": "Wis 2:18", "t": "εἰ γάρ ἐστίν ὁ δίκαιος υἱὸς θεοῦ, ἀντιλήμψεται αὐτοῦ, καὶ ῥύσεται αὐτὸν ἐκ χειρὸς ἀνθεστηκότων."}, {"sp": "N", "st": "Wis 2:19", "t": "ὕβρει καὶ βασάνῳ ἐτάσαωμεν αὐτόν, ἴνα γνῶμεν τὴν ἐπιεικίαν αὐτοῦ καὶ δικάσωμεν τὴν ἀνεξικακίαν αὐτοῦ·"}, {"sp": "N", "st": "Wis 2:20", "t": "ανάτῳ ἀσχήμονι καταδικάσαωμεν αὐτόν, ἔσται γὰρ αὐτοῦ ἐπισκοπὴ ἐκ λόγων αὐτοῦ."}, {"sp": "N", "st": "Wis 2:21", "t": "ταῦτα ἐλογίσαντο, καὶ ἐπλανήθησαν· ἀπετύφλωσεν γὰρ αὐτοὺς ἡ κακία αὐτῶν,"}, {"sp": "N", "st": "Wis 2:22", "t": "καὶ οὐκ ἔγνωσαν μυστήρια αὐτοῦ, οὐδὲ μισθὸν ἤλπισαν ὁσιότητος, οὐδὲ ἔκριναν γέρας ψυχῶν ἀμώμων."}, {"sp": "N", "st": "Wis 2:23", "t": "ὅτι ὁ θεὸς ἔκτισεν τὸν ἄνθρωπον ἐπʼ ἀφθαρσίᾳ, καὶ εἰκόνα τῆς ἰδίας ἰδιότητος ἐποίησεν αὐτόν"}, {"sp": "N", "st": "Wis 2:24", "t": "φθόνῳ δὲ διαβόλου θάνατος εἰσῆλθεν εἰς τὸν κόσμον, πειράζουσιν δὲ αὐτὸν οἱ τῆς ἐκεἰνου μερίδος ὄντες."}, {"sp": "N", "st": "Wis 3:1", "t": "Δικαίων δὲ ψυχαὶ ἐν χειρὶ θεοῦ, καὶ οὐ μὴ ἅψηται αὐτῶν βάσανος."}, {"sp": "N", "st": "Wis 3:2", "t": "ἔδοξαν ἐν ὀφθαλμοῖς ἀφρόνων τεθνάναι. καὶ ἐλογίσθη κάκωσις ἡ ἔξοδος αὐτῶν,"}, {"sp": "N", "st": "Wis 3:3", "t": "καὶ ἡ ἀφʼ ἡμῶν πορεία σύντριμμα· οἱ δέ εὰσιν ἐν εἰρήνῃ"}, {"sp": "N", "st": "Wis 3:4", "t": "καὶ γὰρ ἐν ὄψει ἀνθρώπων ἐὰν κολασθῶσιν, καὶ ἄτιμον ἐπʼ ἐσχάτων τὸ γῆρας αὐτῶν·"}, {"sp": "N", "st": "Wis 3:18", "t": "ἐάν τε ὀξέως τελευτήσωσιν, οὐκ ἔχουσιν ἐλπίδα οὐδὲ ἐν ἡμέρᾳ διαγνώσεως παραμύθιον·"}, {"sp": "N", "st": "Wis 3:19", "t": "γενεᾶς γὰρ ἀδίκου χαλεπὰ τὰ τέλη."}, {"sp": "N", "st": "Wis 4:1", "t": "κρείσσων ἀτεκνία μετὰ ἀρετῆς· ἀθανασία γάρ ἐστιν ἐν μνήμῃ αὐτῆς, ὅτι καὶ παρὰ θεῷ γινώσκεται καὶ παρὰ ἀνθρώποις."}, {"sp": "N", "st": "Wis 4:2", "t": "παροῦσάν τε μιμοῦνται αὐτήν, καὶ ποθοῦσιν ἀπελθοῦσαν· καὶ ἐν τῷ αἰῶνι στεφανηφοροῦσα πομπεύει, τὸν τῶν ἀμιάντων ἄθλων ἀγῶνα νικήσασα."}, {"sp": "N", "st": "Wis 4:3", "t": "πολύγονον δὲ ἀσεβῶν πλῆθος οὐ χρησιμεύσει, καὶ ἐκ νόθων μοσχευμάτων οὐ δώσει ῥίζαν εἰς βάθος, οὐδὲ ἀσφαλῆ βάσιν ἑδράσει·"}, {"sp": "N", "st": "Wis 4:4", "t": "κἂν γὰρ ἐν κλάδοις πρὸς καιρὸν ἀναθάλῃ, ἐπισφαλῶς βεβηκότα ὑπὸ ἀνέμου σαλευθήσεται, καὶ ὑπὸ βίας ἀνέμων ἐκριζωθήσεται·"}, {"sp": "N", "st": "Wis 4:5", "t": "περικλασθήσονται κλῶνες ἀτέλεστοι, καὶ ὁ καρπὸς αὐτῶν ἄχρηστος, ἄωρος εἰς βρῶσιν καὶ εἰς οὐθὲν ἐπιτήδειος·"}, {"sp": "N", "st": "Wis 4:6", "t": "ἐκ γὰρ ἀνόμων ὕπνων τέκνα γεννώμενα μάρτυρές εἰσιν πονηρίας κατὰ γονέων ἐν ἐξετασμῷ αὐτῶν."}, {"sp": "N", "st": "Wis 4:7", "t": "δἰκαιος δὲ ἐὰν φθάσῃ τελευτῆσαι. ἐν ἀναπαύσει ἔται"}, {"sp": "N", "st": "Wis 4:8", "t": "γῆρας γὰρ τίμιον οὐ τὸ πολυχρόνιον, οὐδὲ ἀριθμῷ ἐτῶν μεμέτρηται"}, {"sp": "N", "st": "Wis 4:9", "t": "πολιὰ δέ ἐστιν φρόνησις ἀνθρώποις, καὶ ἡλικία γήρως βίος ἀκηλίδωτος."}, {"sp": "N", "st": "Wis 4:10", "t": "εὐάρεστος τῷ θεῷ γενόμενος ἠγαπήθη, καὶ ζῶν μεταξὺ ἁμαρτωλῶν μετετέθη·"}, {"sp": "N", "st": "Wis 4:11", "t": "ἡρπάγη, μὴ κακία ἀλλάξ σύνεσιν αὐτοῦ, ἢ δόλος ἀπατήσῃ ψυχὴν αὐτοῦ·"}, {"sp": "N", "st": "Wis 4:12", "t": "βασκανία γὰρ φαυλἁητος ἀμαμροῖ τὰ καλά, ⁷ καὶ ῥεμβασμὸς ἐπιθυμίας μεταλλεύει νοῦν ἄκακον."}, {"sp": "N", "st": "Wis 4:13", "t": "τελεωθεὶς ἐν ὀλίγῳ ἐπλήρπνσεν χρόνοαος ωαρούς·"}, {"sp": "N", "st": "Wis 4:14", "t": "ἀρεστὴ γὰρ ἧν Κωρίῳ ἡ ψυχὴ αὐτοῦ, διὰ τοῦτο ἔαπευσεν ἐκ μέσου πονηρόας. αι δὲ λαοὶ δόντες καὶ μὴ νοήσαντες, μηδὲ θέντες ἐπὶ δμανοίᾳ τὸ τομοῦτο,"}, {"sp": "N", "st": "Wis 4:15", "t": "ὅτι χάρις καὶ ἔλεος ἐν ταῖς ἐκλεκτοῖς αὐταῶ καὶ ἐπισκοπὴ ἐν τοῖς ὁσίοις αὐποῦ."}, {"sp": "N", "st": "Wis 4:16", "t": "κατακρινεῖ δὲ δίκαιος καμὼν τοὺς ζῶντας ἀπεβεῖς, καὶ νεότης τελεσθεῖσα ταχέως πολυετὴς γῆρας ἀδίκου."}, {"sp": "N", "st": "Wis 4:17", "t": "ὄψονται γὰρ τελευτὴν σοφὸν, καὶ οὐ νοήσουπα τί ἐβουλεύαατο περὶ αὐτοῦ, καὶ εἰς τί ἠσφαλίσατο αὐτόν ὁ κύρος·"}, {"sp": "N", "st": "Wis 4:18", "t": "ὄψονται καὶ ἐξουβενήσοωαισ, αὐτοὺς δὲ ὁ κύριος ἐκγελάσεται·"}, {"sp": "N", "st": "Wis 4:19", "t": "καὶ ἔσονται μετὰ τοῦτο εἰς πτῶμα ἄτιμον καὶ εἰς ὅβριν ἐν νεκροῖς δι᾿ αἰῶνος. ὅτι ῥήξει αὐτοὺς ἀφώνους πρηνεῖς, καὶ σαλεύσει αὐτοὺς ἐκ θεμελίων· καὶ ἕως ἐσχάτου χερσποθήσονται, καὶ ἔσονται ἐν ὀδύνῃ, καὶ ἡ μνήμη αὐτῶν ἀπαλεῖται."}, {"sp": "N", "st": "Wis 4:20", "t": "ἐλεύσονται ἐν συλλογισμῷ ἁμαρτημάπνν αὐτῶν δειλοί, καὶ ἐλέγξει αὐτὸς ἐξ ἐναντίας τὰ ἀνομήματα αὐτῶν."}, {"sp": "N", "st": "Wis 4:21", "t": "Τότε στήσεται ἐν παρρησίὰ πολλῇ ὁ δίκαιος καπὰ πρόσωπον τῶν θλιψάντων αὐτὸ"}, {"sp": "N", "st": "Wis 5:1", "t": "καὶ τῶν ἀθετούυτων τοὺς πόνους αὐτοῦ."}, {"sp": "N", "st": "Wis 5:2", "t": "ἰδόντες ταραχθήσονται φόβῳ δπινῷ, καὶ ἐκστήσονται ἐπὶ τῷ παραδόξῳ τῆς σωτηρίας·"}, {"sp": "N", "st": "Wis 5:3", "t": "ἐροῦσιν ἐν ἑαυτοῖς μετανοοῦντες, καὶ διὰ στενοχωρίαν πνεύματος στενάξονται Ὀὓτος ἦν ὃν ἔσχομέν ποτε εἰς γέλωτα"}, {"sp": "N", "st": "Wis 5:4", "t": "καὶ εἰς παραβολὴν ὀνειδισμοῦ, ⁴οἱ ἄφρονες· τὸν βίον αὐτοῦ ἐλογισάμεθα μανίαν καὶ τὴν τελευτὴν αὐτοῦ ἄτιμον·"}, {"sp": "N", "st": "Wis 5:5", "t": "πῶς κατελογίσθη ἐν υἱοῖς θεοῦ, καὶ ἐν ἁγίοις ὁ κλῆρος αὐτοῦ ἐστιν;"}, {"sp": "N", "st": "Wis 5:6", "t": "ἄρα ἐπλανήθημεν ἀπὸ ὁδοῦ ἀληθείας, καὶ τὸ τῆς δικαρσύνης φῶς οὐκ ἔλαμψεν ἡμῖν. καὶ ὁ ἥλιος οὐκ ἀνέτεθλεν ἡμῖν·"}, {"sp": "N", "st": "Wis 5:7", "t": "ἀνομίας ἐνεπλήσθημεν τρίβοις καὶ ἀπωλείας, καὶ διωδεύσαμεν ἐρήμους ἀβάτους, τὴν δὲ ὁδὸν Κυρίου οὐκ ἔγνωμεν."}, {"sp": "N", "st": "Wis 5:8", "t": "τί ὠφέλησεν ἡμᾶς ἡ ὑπερηφανία; καὶ τί πλοῦτος μετὰ ἀλαζονίας συμβέβληται ἡμῖν;"}, {"sp": "N", "st": "Wis 5:9", "t": "παρῆλθεν ἐκεῖνα πάντα ὡς σκιὰ καὶ ὡς ἀγγελία παρατρέχουσα·"}, {"sp": "N", "st": "Wis 5:10", "t": "ὼς ναῦς διερχομένη κυμαινόμενον ὕδωρ, ἧς διαβάσης οὐκ ἔστιν ἴχνος εὑρεῖν, οὐδὲ ἀτραπὸν τρόπιος αὐτῆς ἐν κύμασιν·"}, {"sp": "N", "st": "Wis 5:11", "t": "ἡ ὡς ὀρνέου διιπτάντος ἀέρα οὐθὲν εὑρίσκεται τεκμήριον πορείας, πληγῇ δέ μαστιζόμενον ταρσῶν πνεῦμα κοῦφον καὶ σχιζόμενον βἰᾳ ῥοἰζου. κινουμένων πτερύγων διωδεύθη, καὶ μετὰ τοῦτο οὐχ εὑρέθη σημεῖον ἐπιβάσεως ἐν αὐτῷ·"}, {"sp": "N", "st": "Wis 5:12", "t": "ἢ ὡς βέλους βληθέντος ἐπὶ σκοπὸν τμηθεὶς ὁ ἀὴρ εὐθέως εἰς ἑαυτὸν ἀνελύθη, ὡς ἀγνοῆσαι τὴν δίδον αὐτοῦ·"}, {"sp": "N", "st": "Wis 5:13", "t": "οὕτως καὶ ἡμεῖς γενηθέντες ἐξελίπομεν, καὶ ἀρετῆς μὲν σημεῖον οὐδὲν ἔσχομεν δεῖξαι, ἐν δέ τῇ κακίᾳ ἡμῶν κατεδαπανήθημεν."}, {"sp": "N", "st": "Wis 5:14", "t": "ὅτι ἐλπὶς ἀσεβοῦς ὡς φερόμενος χνοῦς ὑπὸ ἀνέμου, καὶ ὡς πάχνη ὑπὸ λαίλαπος διωχθεῖσα λεπτή, καὶ ὡς καπνὸς ὑπὸ ἀνέμου διεχύθη, καὶ ὡς μνεία καταλύτου μονοημέρου παρώδευσεν."}, {"sp": "N", "st": "Wis 5:15", "t": "δίκαιοι δὲ εἰς τὸν αἰῶνα ζῶσιν, καὶ ἐν Κυρίῳ ὁ μισθὸς αὐτῶν, καὶ ἡ φροντὶς αὐτῶν παρὰ Ὑψίστῳ."}, {"sp": "N", "st": "Wis 5:16", "t": "διὰ τοῦτο λήμψονται τὸ βασίλειον τῆς εὐπρεπείας καὶ τὸ διάδημα τοῦ κάλλους ἐκ χειρὸς Κυρίου, ὅτι τῇ δεξιἄ σκεπάσει αὐτούς, καὶ τῷ βραχίονι ὑπερασπιεῖ αὐτῶν."}, {"sp": "N", "st": "Wis 5:17", "t": "λήμψεται πανοπλίαν τὸν ζῆλον αὐτοῦ, καὶ ὁπλοποιήσει τὴν κτίσιν εἰς ἄμυναν ἐχθρῶν· |"}, {"sp": "N", "st": "Wis 5:18", "t": "ἐνδύσεται θώρακα δικαιοσύνην, καὶ περιθήσεται κόρυθα κρίσιν ἀνυπόκριτον·"}, {"sp": "N", "st": "Wis 5:19", "t": "λήμψεται ἀσπίδα ἀκαταμάχητον ὁσιότητα,"}, {"sp": "N", "st": "Wis 5:20", "t": "ὀξυνεῖ δὲ ἀπότομον ὀργὴν εἰς ῥομφαίαν, συνεκπολεμήσει δέ αὐτῷ ὁ κόσμος ἐπὶ τοὺς παράφρονας."}, {"sp": "N", "st": "Wis 5:21", "t": "πορεύσονται εὔστοχοι βολίδες ἀστραπῶν, καὶ ὡς ἀπὸ εὐκύκλου τόξου τῶν νεφῶν ἐπὶ σκοπὸν ἁλοῦνται,"}, {"sp": "N", "st": "Wis 5:22", "t": "καὶ ἐκ πετροβόλου θυμοῦ πλήρεις ῥιφήσονται χάλαζαι ἀγανακτήσει κατʼ αὐτῶν ὕδωρ θαλάσσης, ποταμοὶ δὲ συνκλύσουσιν ἀποτόμαας·"}, {"sp": "N", "st": "Wis 5:23", "t": "ἀντιστήσεται αὐτοῖς πνεῦμα δυνάμεος, καὶ ὡς λαῖλαψ ἐκλικμήσει αὐτούς· καὶ ἐρημώσει πᾶσα τὴν γῆν ἀνομία, καὶ ἡ κακοπραγία περιτρέψει θρόνους δυναστῶν."}, {"sp": "N", "st": "Wis 6:1", "t": "Ἀκούσατε οὗν, βασιλεῖς, καὶ σύνετε· μάθετε, δικασταὶ περάτων γῆς·"}, {"sp": "N", "st": "Wis 6:2", "t": "ἐνωτίσασθε, οἱ κρατοῦντες πλήθους καὶ γεγαυρωμένοι ἐπὶ ὄχλοις ἐθνῶν."}, {"sp": "N", "st": "Wis 6:3", "t": "ὅτι ἐδόθη παρὰ τοῦ κυρίου ἡ κράτησις ὑμῖν. καὶ ἡ δυναστεία παρὰ Ὑψίστου, ὃς ἐξετάσει ὑμῶν τὰ ἔργα καὶ τὰς βουλὰς διεραυνήσει·"}, {"sp": "N", "st": "Wis 6:4", "t": "ὅτι ὑπηρέται ὄντες τῆς αὐτοῦ βασιλείας οὐκ ἐκρίνατε ὀρθῶς, οὐδὲ ἐφυλάξατε νόμον, οὐδὲ κατὰ τὴν βουλὴν τοῦ θεοῦ ἐπορεύθητε"}, {"sp": "N", "st": "Wis 6:5", "t": "φρικτῶς καὶ ταχέως ἐπιστήσεται ὑμῖν, ὅτι κρίσις ἀπότομος ἐν τοῖς ὑπερέχουσιν γίνεται."}, {"sp": "N", "st": "Wis 6:6", "t": "ὁ γὰρ ἐλάχιστος συγγνωστός ἐστιν ἐλέους, δυνατοὶ δὲ δυνατῶς ἐτασθήσονται·"}, {"sp": "N", "st": "Wis 6:7", "t": "οὐ γὰρ ὑποστελεῖται πρόσωπον ὁ πάντων δεσπότης, οὐδὲ ἐντραπήσεται μέγεθος· ὅτι μικρὸν καὶ μέγαν αὐτὸς ἐποίησεν, ὁμοίως τε προνοεῖ περὶ πάντων·"}, {"sp": "N", "st": "Wis 6:8", "t": "τοῖς δὲ κραταιοῖς ἰσχυρὰ ἐφίσταται ἔραυνᾷ."}, {"sp": "N", "st": "Wis 6:9", "t": "πρὸς ὑμᾶς οὖν, ὦ τύραννοι, οἱ λόγοι μου, ἴνα μάθητε σοφίαν καὶ μὴ παραπέσητε."}, {"sp": "N", "st": "Wis 6:10", "t": "οἱ γὰρ φυλάξαντες ὁσίως τὰ ὅσια ὁσιωθήσονται, καὶ οἱ διδαχθέντες αὐτὰ εὑρήσουσιν ἀπολογίαν."}, {"sp": "N", "st": "Wis 6:11", "t": "ἐπιθυμήσατε οὗν τῶν λόγων μου, ποθήσατε καὶ παιδευθήσεσθε."}, {"sp": "N", "st": "Wis 6:12", "t": "Λαμπρὰ καὶ ἀμάραντός ἐστιν ἡ σοφία, καὶ εὐχερῶς θεωρεῖται ὑπὸ τῶν ἀγαπώντων αὐτήν·"}, {"sp": "N", "st": "Wis 6:13", "t": "φθάνει τοὺς ἐπιθυμοῦντας προγνωσθῆναι."}, {"sp": "N", "st": "Wis 6:14", "t": "ὁ ὀρθρίσας ἐπʼ αὐτὴν οὐ κοπιάσει, πάρεδρον γὰρ εὑρήσει τῶν πυλῶν αὐτοῦ."}, {"sp": "N", "st": "Wis 6:15", "t": "τὸ γὰρ ἐνθυμηθῆναι περὶ αὐτῆς φρονήσεως τελειότης, καὶ ὁ ἀγρυπνήσας δι᾿ αὐτὴν ταχέως ἀμέριμνος ἔσται·"}, {"sp": "N", "st": "Wis 6:16", "t": "ὅτι τοὺς ἀξίους αὐτῆς αὕτη περιέρχεται ζητοῦσα, καὶ ἐν ταῖς τρίβοις φαντάζεται αὐτοῖς εὐμενῶς, καὶ ἐν πάσῃ ἐπινοίᾳ ὑπαντῶ αὐτοῖς."}, {"sp": "N", "st": "Wis 6:17", "t": "ἀρχὴ γὰρ αὐτῆς ἡ ἀληθεστάτη παιδείας ἐπιθυμία,"}, {"sp": "N", "st": "Wis 6:18", "t": "φροντὶς δὲ παιδείας ἀγάπη, ἀγάπη δὲ τήρησις νόμων αὐτῆς, προσοχὴ δέ νόμων βεβαίωσις ἀφθαρσίας,"}, {"sp": "N", "st": "Wis 6:19", "t": "ἀφθαρσία δὲ ἐγγὺς εἶναι ποιεῖ θεοῦἐπιθυμία"}, {"sp": "N", "st": "Wis 6:20", "t": "ἄρα σοφίας ἀνάγει ἐπὶ βασιλείαν."}, {"sp": "N", "st": "Wis 6:21", "t": "εἰ οὖν ἥδεσθε ἐπὶ θρόνοις καὶ σκήπτροις, τύραννοι λαῶν, τιμήσατε σοφίαν, ἵνα εἰς τὸν αἰῶνα βασιλεύσητε."}, {"sp": "N", "st": "Wis 6:22", "t": "τί δέ ἐστιν σοφία καὶ πῶς ἐγένετο ἀπαγγελῶ, καὶ οὐκ ἀποκρύψω ὑμῖν μυστήρια, ἀλλὰ ἀπʼ ἀρχῆς γενέσεως ἐξιχνιάσω καὶ θήσω εἰς τὸ ἐμφανές τὴν γνῶσιν αὐτῆς, καὶ οὐ μὴ παροδεύσω τὴν ἀλήθειαν·"}, {"sp": "N", "st": "Wis 6:23", "t": "οὔτε μὴν φθόνῳ τετηκότι συνοδεύσαα, ὅτι οὗτος οὐ κοινανήσει σοφίᾳ."}, {"sp": "N", "st": "Wis 6:24", "t": "πλῆθος δὲ σοφῶν σαντηρία κόσμου, καὶ βασιλεὺς φρόνιμος εὐσταθίᾳ δήμου."}, {"sp": "N", "st": "Wis 6:25", "t": "ὥστε παιδεύεσθε τοῖς ῥήμασίν μου, καὶ ὠφεληθήσεσθε."}, {"sp": "N", "st": "Wis 7:1", "t": "Εἰμὶ μέν κἀγὼ θνητὸς ἴσος ἄπασιν, καὶ γηγενοῦς ἀπόγονος πρωτοπλάστου· καὶ ἐν κοιλίᾳ μητρὸς ἐγλύφην σὰρξ"}, {"sp": "N", "st": "Wis 7:2", "t": "δεκαμηνιαίῃ χρόνῳ, παγεὶς ἐν αἵματι ἐκ σπέρματος ἀνδρὸς καὶ ἡδονῆς ὕπνῳ συνελθούσης·"}, {"sp": "N", "st": "Wis 7:3", "t": "καὶ ἐγὼ δέ γενόμενος ἔσπασα τὸν κοινὸν ἀέρα, καὶ ἐπὶ τὴν ὁμοιοπαθῆ κατέπεσον γῆν, πρώτην φωνὴν τὴν ὁμοίαν πᾶσιν ἴσα κλαίων·"}, {"sp": "N", "st": "Wis 7:4", "t": "ἐν σπαργάνοις ἀνετράφην καὶ ἐν φροντίσιν."}, {"sp": "N", "st": "Wis 7:5", "t": "οὐδεὶς γὰρ βασιλεὺς ἑτέραν ἔσχεν γενέσεως ἀρχήν·"}, {"sp": "N", "st": "Wis 7:6", "t": "μια δὲ πάντων εἴσοδος εἰς τὸν βίον ἔξοδός τε ἴση."}, {"sp": "N", "st": "Wis 7:7", "t": "διὰ τοῦτο εὐξάμην, καὶ φρόνησις ἐδόθη μοι· ἐπεκαλεσάμην, καὶ ἦλθέν μοι πνεῦμα σοφίας."}, {"sp": "N", "st": "Wis 7:8", "t": "προέκρινα αὐτὴν σκήπτρων καὶ θρόνων, καὶ πλοῦτον οὐδὲν ἡγησάμην ἐν συγκρίσει αὐτῆς·"}, {"sp": "N", "st": "Wis 7:9", "t": "οὐδὲ ὡμοίωσα αὐτῇ λίθον ἀτίμητον, ὅτι ὁ πᾶς χρυσὸς ἐν ὄψει αὐτῆς ψάμμος ὀλίγη, καὶ ὡς πηλὸς λογισθήσεται ἄργυρος ἐναντίον αὐτῆς·"}, {"sp": "N", "st": "Wis 7:10", "t": "ὑπέρ ὑγείαν καὶ εὐμορφίαν ἠγάπησα αὐτήν, καὶ προειλόμην αὐτὴν ἀντὶ φωτὸς ἔχειν, ὅτι ἀκοίμητον τὸ ἐκ ταύτης φέγγος."}, {"sp": "N", "st": "Wis 7:11", "t": "ἦλθεν δέ μοι τὰ ἀγαθὰ ὁμοῦ πάντα μετ᾿ αὐτῆς. καὶ ἀναρίθμητος πλοῦτος ἐν ταῖς χερσὶν αὐτῆς·."}, {"sp": "N", "st": "Wis 7:12", "t": "εὐφράνθην δὲ ἐπὶ πάντων, ὅτι αὐτῶν ἡγεῖται σοφία, ἠγνόουν δὲ αὐτὴν γένεσιν εἶναι τούτων."}, {"sp": "N", "st": "Wis 7:13", "t": "ἀδόλως τε ἔμαθον, ἀφθόνως τε μεταδίδωμι. τὸν πλοῦτον αὐτῆς οὐκ ἀποκρύπτομαι·"}, {"sp": "N", "st": "Wis 7:14", "t": "ἀνεκλιπὴς γὰρ θησαυρός ἐστιν ἀνθρώποις, ὃν οἱ χρησάμενοι πρὸς θεὸν ἐστείλαντο φιλίαν, διὰ τὰς ἐκ παιδείας δωρεὰς συσταθέντες."}, {"sp": "N", "st": "Wis 7:15", "t": "ἐμοὶ δὲ δῴη ὁ θεὸς εἰπεῖν κατὰ γνώμην καὶ ἐνθυμηθῆναι άξίως τῶν δεδομένων. ὅτι αὐνὸς καὶ τῆς σοφίας ὁδηγός ἐστιν καὶ τῶν σοφῶν διορθωτής."}, {"sp": "N", "st": "Wis 7:16", "t": "ἐν γὰρ χειρὶ αὐτοῦ καὶ ἡμεῖς καὶ οἱ λόγοι ἡμῶν. πᾶσά τε φρόνησις καὶ ἐργατειῶν ἐπιστήμη."}, {"sp": "N", "st": "Wis 7:17", "t": "αὐτὸς γάρ μοι ἔδωκεν τῶν ὄντων γνῶσιν ἀψευδῆ, εἰδέναι σύστασιν κόσμου καὶ ἐνέργειαν.στοιχείων,"}, {"sp": "N", "st": "Wis 7:18", "t": "ἀρχὴν καὶ τέλος καὶ μεσότητα χρόνων, τροπῶν ἀλλαγὰς καὶ μεταβολὰς καιρῶν."}, {"sp": "N", "st": "Wis 7:19", "t": "ἐνιαυτῶν κύκλους καὶ ἀστέρων θέσεις."}, {"sp": "N", "st": "Wis 7:20", "t": "φύσεις ζώων καὶ θυμοὺς θηρίων, πνευμάτῳν βίας καὶ διαλογισμοὺς ἀνθρώπων, διαφορὰς φυτῶν καὶ δυνάμεις ῥιζῶν."}, {"sp": "N", "st": "Wis 7:21", "t": "ὅσα τέ ἐστιν κρυπτὰ καὶ ἐμφανῆ ἔγνων·"}, {"sp": "N", "st": "Wis 7:22", "t": "ἡ γὰρ πάντων τεχνῖτις ἐδίδαξέν με σοφία. Ἔοτιν γὰρ ἐν αὐτῇ πνεῦμα νοερόν, ἅγιον, μονογενές, πολυμερές, λεπτόν, εὐκίνητον, τρανόν, ἀμόλυντον, σαφές, ἀπήμαντον, φιλάγαθον, ὀξύ, ἀκώλυτον, εὐεργετικόν,"}, {"sp": "N", "st": "Wis 7:23", "t": "φιλάνθραοπον, βέβαιον, ἀσφαλές, ἀμέριμνον. παντοδύυαμον, πανεπίσκοπον, καὶ διὰ πάντων χωροῦν πνευμάτων νοερῶν καθαρῶν λεπτοτάτων."}, {"sp": "N", "st": "Wis 7:24", "t": "πάσης γὰρ κινήσεως κινητικώτερον σοφία, διήκει δὲ καὶ χωρεῖ διὰ πάντων διὰ τὴν καθαρότητα."}, {"sp": "N", "st": "Wis 7:25", "t": "ἀτμὶς γάρ ἐστιν τῆς τοῦ θεοῦ δυνάμεως, καὶ ἀπόρροια τῆς τοῦ παντοκράτορος δόξης εἰλικρινής· δμὼ τοῦτο οὐδέν μεμιαμμένον εἰς αὐτὴν παρεμπίπτει."}, {"sp": "N", "st": "Wis 7:26", "t": "ἀπαύγασμα γάρ ἐστιν φωτὸς ἀιδίου, καὶ ἔσοπτρον ἀκηλίδωτον τῆς τοῦ θεοῦ ἐνεργείας, καί εἰκὼν τῆς ἀγαθότητος αὐτοῦ."}, {"sp": "N", "st": "Wis 7:27", "t": "μια δὲ οὖσα πάντα δύναται, καὶ μένουσα ἐν αὑτῇ τὰ πάντα καινίζει, καὶ κατὰ γενεὰς εἰς ψυχὰς ὁσίας μεταβαίνουσα φίλους θεοῦ καὶ προφήτας κατασκευάζει·"}, {"sp": "N", "st": "Wis 7:28", "t": "σύθὲν γὰρ ἀγαπῷ ὁ θεὸς εἰ μὴ τὸν σοφίᾳ συνοικοῦντα."}, {"sp": "N", "st": "Wis 7:29", "t": "ἔστιν γὰρ αὕτη εὐπρεπεστέρα ἡλίου, καὶ ὑπέρ πᾶσαν ἄστρων θέσιν. φωτὶ συνκρινομένη εὺρίσκεται προτέρα·"}, {"sp": "N", "st": "Wis 7:30", "t": "τοῦτο μέν γὰρ διαδέχεται νύξ, σοφίας δὲ οὐκ ἀντισχύει κακία."}, {"sp": "N", "st": "Wis 8:1", "t": "διατείνει δὲ ἀπὸ πέρατος εἰς πέρας εὐρώστως, καὶ διοικεῖ τὰ πάντα χρηστῶς."}, {"sp": "N", "st": "Wis 8:2", "t": "Ταύτην ἐφίλησα καὶ ἐξεζήτησα ἐκ νεότητός μου, καὶ ἐζήτησα νύμφην ἀγαγέσθαι ἐμαυτῷ, καὶ ἐραστὴς ἐγενόμην τοῦ κάλλους αὐτῆς."}, {"sp": "N", "st": "Wis 8:3", "t": "εὐγένειαν δοξάζει συμβίωσιν θεοῦ ἔχουσα, καὶ ὁ πάντων δεσπότης ἠγάπησεν αὐτήν·"}, {"sp": "N", "st": "Wis 8:4", "t": "μύστις γάρ ἐστιν τῆς τοῦ θεοῦ ἐπιστήμης. καὶ αἱρετὶς τῶν ἔργων αὐτοῦ."}, {"sp": "N", "st": "Wis 8:5", "t": "εἰ δὲ πλοῦτός ἐστιν ἐπιθυμητὸν κτῆμα ἐν βίῳ, τί σοφίας πλουσιώτερον τῆς τὰ πάντα ⁸ἐργαζομένης;"}, {"sp": "N", "st": "Wis 8:6", "t": "εἰ δὲ φρόνησις ἐργάζεται, τίς αὐτῆς τῶν ὄντων μᾶλλόν ἐστιν τεχνῖτις;"}, {"sp": "N", "st": "Wis 8:7", "t": "καὶ εἰ δικαιοσύνην ἀγαπῷ τις, οἱ πόνοι ταύτης εἰσὶν ἀρεταί σωφροσύνην γὰρ καὶ φρόνησιν ἐκδιδάσκει, δικαιοσύνην καὶ ἀνδρείαν, ὧν χρησιμώτερον οὐδέν ἐστιν ἐν βίῳ ἀνθρώποις."}, {"sp": "N", "st": "Wis 8:8", "t": "εἰ δὲ καὶ πολυπειρίαν ποθεῖ τις, οἶδεν τὰ ἀρχαῖα καὶ τὰ μέλλοντα εἰκάζειν, ἐπίσταται στροφὰς λόγων καὶ λύσεις αἰνιγμάτων, σημεῖα καὶ τέρατα προγινώσκει καὶ ἐκβάσεις καιρῶν καὶ χρόνον."}, {"sp": "N", "st": "Wis 8:9", "t": "ἕκρινα τοίνυν ταύτηυ ἀγαγέσθαι πρὸς συμβίαοσιν, εἰδὼς ὅτι ἔσται μοι σύμβουλος ἀγαθῶν, καὶ παραίνεσις φροντίδαωων καὶ λύπης."}, {"sp": "N", "st": "Wis 8:10", "t": "ἔξω δι᾿ αὐτὴν δόξαν ἐν ὄχλοις. καὶ τιμὴν παρὰ πρεσβυτέροις ὁ νέος·"}, {"sp": "N", "st": "Wis 8:11", "t": "ὀξὺς εὑρεθήσομαι ἐν κρίσει, καὶ ἐν ὄψει δυναστῶν θαυμασθήσομαι"}, {"sp": "N", "st": "Wis 8:12", "t": "σιγῶντά με περιμενοῦσιν, καὶ φθεγγομένῳ προσέξουσιν, καὶ λαλοῦντος ἐπὶ πλεῖον χεῖρα ἐπιθήσουσιν ἐπὶ στόμα αὐτῶν."}, {"sp": "N", "st": "Wis 8:13", "t": "ἔξω δι᾿ αὐτὴν ἀθανασίαν, καὶ μνήμην αἰώνιον τοῖς μετʼ ἐμέ ἀπολείψω."}, {"sp": "N", "st": "Wis 8:14", "t": "διοικήσω λαούς, καὶ ἔθνη ὑποταγήσεταί μοι·"}, {"sp": "N", "st": "Wis 8:15", "t": "φοβηθήσονταί με ἀκούσαντες τύραννοι φρικτοί ἐν πλήθει φανοῦμαι ἀγαθὸς καὶ ἐν πολέμῳ ἀνδρεῖος."}, {"sp": "N", "st": "Wis 8:16", "t": "κἰσελθὼν εἰς τὸν οἶκόν μου προσαναπαύσομαι αὐτῇ· οὐ γὰρ ἔχει πικρίαν ἡ συναναστροφὴ αὐτῆς, οὐδὲ ὀδύνην ἡ συμβίωσις αὐτῆς, ἀλλὰ εὐφροσύνην καὶ χαράν."}, {"sp": "N", "st": "Wis 8:17", "t": "ταῦτα λογισάμενος ἐν ἐμαυτῷ καὶ φροντίσας ἐν καρδίᾳ μου ὅτι ἔστιν ἀθανασία ἐν συγγενείᾳ σοφίας,"}, {"sp": "N", "st": "Wis 8:18", "t": "καὶ ἐν φιλίᾳ αὐτῆς τέρψις ἀγαθή, καὶ ἐν πόνοις χειρῶν αὐτῆς πλοῦτος ἀνεκλιπής, καὶ ἐν συνγυμνασίᾳ ὁμιλίας αὐτῆς φρόνησις, καὶ εὔκλεια ἐν κοινωνίῷ λόγων αὐτῆς, περιῄειν ζητῶν ὅπως λάβω αὐτὴν εἰς ἐμαυτόν."}, {"sp": "N", "st": "Wis 8:19", "t": "παῖς δὲ ἤμην εὐφυής, ψυχῆς τε ἔλαχον ἀγαθῆς,"}, {"sp": "N", "st": "Wis 8:20", "t": "μᾶλλον δὲ ἀγαθὸς ὢν ἦλθον εἰς σῶμα ἀμίαντον."}, {"sp": "N", "st": "Wis 8:21", "t": "γνοὺς δὲ ὅτι οὐκ ἄλλως ἔσομαι ἐγκρατὴς ἐὰν μὴ ὁ θεὸς δῷ. καὶ τοῦτο δʼ ἦν φρονήσεως τὸ εἰδέναι τίνος ἡ χάρις. ἐνέτυχον τῷ κυρίῳ καὶ ἐδεήθην αὐτοῦ, καὶ εἶπον ἐξ ὅλης τῆς καρδίας μου"}, {"sp": "N", "st": "Wis 9:1", "t": "θεὲ πατέρων καὶ Κύριε τοῦ ἐλέους σου, ὁ ποιήσας τὰ πάντα ἐυ λόγῳ σου,"}, {"sp": "N", "st": "Wis 9:2", "t": "καὶ τῇ σοφίᾳ σου κατεσκεύασας ἄνθρωπον ἴνα δεσπόζῃ τῶν ὑπὸ σοῦ γενομένων κτισμάτων,"}, {"sp": "N", "st": "Wis 9:3", "t": "καὶ διέπῃ τὸν κόσμον ἐν ὁσιότητι καὶ δικαιοσύνῃ, καὶ ἐν εὐθύτητι ψυχῆς κρίσιν κρίνῃ·"}, {"sp": "N", "st": "Wis 9:4", "t": "δός μοι τὴν τῶν σῶυ θρόνων πάρεδρον σοφίαν, καὶ μὴ με ἀποδοκιμάσῃς ἐκ παίδων σου."}, {"sp": "N", "st": "Wis 9:5", "t": "ὅτι ἐγὼ δοῦλος σὸς καὶ υἱὸς τῆς παιδίσκης σου, ἄνθρωπος ἀσθενὴς καὶ ὀλιγοχρόνιος καὶ ἐλάσσαων ἐν συνέσει κρίσεαως καὶ νόμων·"}, {"sp": "N", "st": "Wis 9:6", "t": "κἂν γάρ τις ᾖ τέλειος ἐν υἱοῖς ἀνθρώπων, τῆς ἀπὸ σοῦ σοφίας ἀπδὐισης εἰς οὐδὲν λογισθήσεται"}, {"sp": "N", "st": "Wis 9:7", "t": "σύ με προείλω βασιλέα λαοῦ σου καὶ δικαστὴν υἱῶν σου καὶ θυγατέρων·"}, {"sp": "N", "st": "Wis 9:8", "t": "εἶπας οἰκοδομῆσαι ναὸν ἐν ὄρει ἁγίῳ σου, καὶ ἐν πόλει κατασκηνώσεώς σου θυσιαστήριον, μίμημα σκηνῆς ἁγίας ἣν προητοίμασας ἀπʼ ἀρχῆς."}, {"sp": "N", "st": "Wis 9:9", "t": "καὶ μετὰ σοῦ ἡ σοφία ἡ εἰδυῖα τὰ ἔργα σου, καὶ παροῦσα ὅτε ἐποίεις τὸν κόσμον, καὶ ἐπισταμένη τί ἀρεστὸν ἐν ὀφθαλμοῖς σου καὶ τί εὐθὲς ἐν ἐντολαῖς σου."}, {"sp": "N", "st": "Wis 9:10", "t": "ἐξαπόστειλον αὐτὴν ἐξ ἁγίων οὐρανῶν, καὶ ἀπὸ θρόνου δόξης σου πέμψον αὐτήν· ἴνα συνπαροῦσά μοι κοπιάσῃ, καὶ γνῶ τί εὐάρεστόν ἐστιν παρὰ σοί."}, {"sp": "N", "st": "Wis 9:11", "t": "οἶδε γὰρ ἐκείνη πάντα καὶ συνίει, καὶ ὁδηγήσει με ἐν ταῖς πράξεσί μου σωφρόνως. καὶ φυλάξει με ἐν τῆ δόξῃ αὐτῆς·"}, {"sp": "N", "st": "Wis 9:12", "t": "καὶ ἔσται προσδεκτὰ τὰ ἔργα μου, καὶ διακρινῶ τὸν λαόν σου δικαίως, καὶ ἔσομαι ἄξιος θρόνων πατρός μου."}, {"sp": "N", "st": "Wis 9:13", "t": "τίς γὰρ ἄνθρωπος γνώσεται βουλὴν θεοῦ; ἢ τίς ἐνθυμηθήσεται τί θέλει ὁ κύριος"}, {"sp": "N", "st": "Wis 9:14", "t": "λογισμοὶ γὰρ θνητῶν δειλοί, καὶ ἐπισφαλεῖς αἱ ἐπίνοιαι ἡμῶν·"}, {"sp": "N", "st": "Wis 9:15", "t": "φθαρτὸν γὰρ σῶμα βαρύνει ψυχήν. καὶ βρίθει τὸ γεῶδες σκῆνος νοῦν πολυφρόντιδα."}, {"sp": "N", "st": "Wis 9:16", "t": "καὶ μόλις εἰκάζομεν τὰ ἐπὶ γῆς. καὶ τὰ ἐν χερσὶν εὑρίσκομεν μετὰ πόνου· τὰ δὲ ἐν οὐρανοῖς τίς ἐξιχνίασεν;"}, {"sp": "N", "st": "Wis 9:17", "t": "βουλὴν δέ σου τίς ἔγνω, εἰ μὴ σὺ ἔδωκας σοφίαν καὶ ἔπεμψας τὸ ἅγιόν σου πνεῦμα ἀπὸ ὐψίσταων"}, {"sp": "N", "st": "Wis 9:18", "t": "καὶ οὕτως διωρθώθησαν αἱ τρὰβοι τῶν ἐπὶ γῆς. καὶ τὰ ἀρεστά σου ἐδιδάχθησαν ἄνθρωποι,"}, {"sp": "N", "st": "Wis 9:19", "t": "καὶ τῇ σοφίᾳ ἐσώθησαν."}, {"sp": "N", "st": "Wis 10:1", "t": "Αὕτη πρωτόπλαστον πατέρα κόσμου μόνον κτισθέντα διεφύλαξεν, καὶ ἐξείλατο αὐτὸν ἐκ παραπτώματος ἰδίου,"}, {"sp": "N", "st": "Wis 10:2", "t": "ἔδωκέν τε αὐτῷ ἰσχὺν κρατῆσαι ἁπάντων."}, {"sp": "N", "st": "Wis 10:3", "t": "ἀποστὰς δὲ ἀπʼ αὐτῆς ἄδικος ἐν ὀργῇ αὐτοῦ ἀδελφοκτόνοις συναπώλετο θυμοῖς·"}, {"sp": "N", "st": "Wis 10:4", "t": "δι ὃν κατακλυζομένην γῆν πάλιν διέσωσεν σοφία, δι εὐτελοῦς ξύλου τὸν δίκαιον κυβερνήσασα."}, {"sp": "N", "st": "Wis 10:5", "t": "αὕτη καὶ ἐν ὁμονοίᾳ πονηρίας ἐθνῶν συγχυθέντων εὗρεν τὸν δίκαιον, καὶ ἐτήρησεν αὐτὸν ἄμεμπτον θεῷ, καὶ ἐπὶ τέκνου σπλάγχνοις ἰσχυρὸν ἐφύλαξεν."}, {"sp": "N", "st": "Wis 10:6", "t": "αὕτη δίκαιον ἐξαπολλυμένων ἀσεβῶν ἐρρύσατο φυγόντα πῦρ καταβάσιον Πενταπόλεως·"}, {"sp": "N", "st": "Wis 10:7", "t": "ἧς ἔτι μαρτύριον τῆς πονηρίας καπνιζομένη καθέστηκε χέρσος, καὶ ἀτελέσιν ὥραις καρποφοροῦντα φυτά, ἀπιστούσης ψυχῆς μνημεῖον ἑστηκυῖα στήλη ἁλός."}, {"sp": "N", "st": "Wis 10:8", "t": "σοφίαν γὰρ παροδεύσαντες οὐ μόνον ἐβλάβησαν τοῦ μὴ γνῶναι τὰ καλά, ἀλλὰ καὶ τῆς ἀφροσύνης ἀπέλιηον τῷ βίῳ μνημόσυνον, ἵνα ἐν οἷς ἐσφάλησαν μηδὲ λαθεῖν δυνηθῶσιν."}, {"sp": "N", "st": "Wis 10:9", "t": "σοφία δὲ τοὺς θεραπεύσαντας αὐτὴν ἐκ πόνων ἐρρύσατο."}, {"sp": "N", "st": "Wis 10:10", "t": "αὕτη φυγάδα ὀργῆς ἀδελφοῦ δίκαιον ὡδήγησεν ἐν τρίβοις εὐθείαις· ἔδειξεν αὐτῷ βασιλείαν θεοῦ, καὶ ἔδωκεν αὐτῷ γνῶσιν ἁγίων· εὐπόρησεν αὐτὸν ἐν μόχθοις, καὶ ἐπλήθυνεν τοὺς πόνους αὐτοῦ·"}, {"sp": "N", "st": "Wis 10:11", "t": "ἐν πλεονεξίᾳ κατισχυόντων αὐτὸν παρέστη, καὶ ἐπλούτισεν αὐτόν·"}, {"sp": "N", "st": "Wis 10:12", "t": "δεφύλαξεν αὐτὸν ἀπὸ ἐχθρῶν, καὶ ἀπὸ ἐνεδρευόντων ἠσφαλίσατο, καὶ ἀγῶνα ἰσχυρὸν ἐβράβευσεν αὐτῷ, ἵνα γνῷ ὅτι παντὸς δυνατωτέρα ἐστὶν εὐσέβεια."}, {"sp": "N", "st": "Wis 10:13", "t": "αὕτη πραθέντα δίκαιον οὐκ ἐγκατέλιπεν, ἀλλὰ ἐξ ἁμαρτίας ἐρρύσατο αὐτόν·"}, {"sp": "N", "st": "Wis 10:14", "t": "συνκατέβη αὐτῷ εἰς λάκκον. καὶ ἐν δεσμοῖς οὐκ ἀφῆκεν αὐτόν, ἕως ἤνεγκεν αὐτῷ σκῆπτρα βασιλείας καὶ ἐξουσίαν τυραννούντων αὐτοῦ· ψευδεῖς τε ἔδεξεν τοὺς μωμησαμένους αὐτόν, καὶ ἔδωκεν αὐτῷ δόξαν αἰώνιον."}, {"sp": "N", "st": "Wis 10:15", "t": "αὕτη λαὸν ὅσιον καὶ σπέρμα ἄμεμπτον ἐρρύσατο ἐξ ἔθνους θλβόντων."}, {"sp": "N", "st": "Wis 10:16", "t": "εἰσῆλθεν εἰς ψυχὴν θεράποντος Κυρίου, καὶ ἀντέστη βασιλεῦσιν φοβεροῖς ὀν τέρασι καὶ σημείοις."}, {"sp": "N", "st": "Wis 10:17", "t": "ἀπέδωκεν ὁσίοις μισθὸν κόπων αὐτῶν, ὡδήγησεν αὐτοὺς ἐν ὁδῷ θαυμαστῇ, καὶ ἐγένετο αὐτοῖς εἰς σκέπην ἡμέρας καὶ εἰς φλόγα ἄστρων τὴν νύκτα."}, {"sp": "N", "st": "Wis 10:18", "t": "διεβίβασεν αὐτοὺς θάλασσαν ἐρυθράν, καὶ διήγαγεν αὐτοὺς δι᾿ ὕδατος πολλοῦ·"}, {"sp": "N", "st": "Wis 10:19", "t": "τοὺς δὲ ἐχθροὺς αὐτῶν κατέκλυσεν, καὶ ἐκ βάθους ἀβύσσου ἀνέβρασεν αὐτούς."}, {"sp": "N", "st": "Wis 10:20", "t": "διὰ τοῦτο δίκαιοι ἐσκύλευσαν ἀσεβεῖς, καὶ ὕμνησαν, Κύριε, τὸ ὄνομα τὸ ἅγιόν σου, τήν τε ὑπέρμαχόν σου χεῖρα ᾔνεσαν ὁμοθυμαδόν·"}, {"sp": "N", "st": "Wis 10:21", "t": "ὅτι ἡ σοφία ἤνοιξεν στόμα κωφῶν, καὶ γλώσσας νηπίων ἔθηκεν τρανάς."}, {"sp": "N", "st": "Wis 11:1", "t": "Εὐόδωσεν τὰ ἔργα αὐτῶν ἐν χειρὶ προφήτου ἁγίου."}, {"sp": "N", "st": "Wis 11:2", "t": "διώδευσαν ἔρημον ἀοίκητον, καὶ ἐν ἀβάτοις ἔπηξαν σκηνάς·"}, {"sp": "N", "st": "Wis 11:3", "t": "ἀντέστησαν πολεμίοις, καὶ ἠμύναντο ἐχθρούς."}, {"sp": "N", "st": "Wis 11:4", "t": "ἐδίψησαν καὶ ἐπεκαλέσαντό σε, καὶ ἐδόθη αὐτοῖς ἐκ πέτρας ἀκροτόμου ὕδωρ, καὶ ἴαμα δίψης ἐκ λίθου σκληροῦ."}, {"sp": "N", "st": "Wis 11:5", "t": "δι᾿ ὧν γὰρ ἐκολάσθησαν οἱ ἐχθροὶ αὐτῶν, (⁶)διὰ τούτων αὐτοὶ ἀποροῦντες εὐεργετήθησαν."}, {"sp": "N", "st": "Wis 11:6", "t": "ἀντὶ μὲν πηγῆς ἀενάου ποταμοῦ αἵματι λυθρώδει ταραχθέντες"}, {"sp": "N", "st": "Wis 11:7", "t": "εἰς ἔλεγχον νηπιοκτόνου διατάγματος,"}, {"sp": "N", "st": "Wis 11:8", "t": "ἔδωκας αὐτοῖς δαψιλὲς ὕδωρ ἀνελπίστως, 8 δείξας διὰ τοῦ τότε δίψους πῶς τοὺς ὑπεναντίους ἐκόλασας."}, {"sp": "N", "st": "Wis 11:9", "t": "ὅτε γὰρ ἐπειράσθησαν, καίπερ ἐν ἐλέει παιδευόμενοι, ἔγνωσαν πῶς ἐν ὀργῇ κρινόμενοι ἀσεβεῖς ἐβασανίζοντο·"}, {"sp": "N", "st": "Wis 11:10", "t": "τούτους μὲν γὰρ ὡς πατὴρ νουθετῶν ἐδοκίμασας, ἐκείνους δὲ ὡς ἀπότομος βασιλεὺς καταδικάζων ἐξήτασας."}, {"sp": "N", "st": "Wis 11:11", "t": "καὶ ἀπόντες δὲ καὶ παρόντες ὁμοίως ἐτρύχοντο·"}, {"sp": "N", "st": "Wis 11:12", "t": "διπλῆ γὰρ αὐτοὺς ἔλαβεν λύπη καὶ στεναγμὸς μνημῶν τῶν παρελθουσῶν."}, {"sp": "N", "st": "Wis 11:13", "t": "ὅτε γὰρ ἤκουσαν διὰ τῶν ἰδίων κολάσεων εὐεργετουμένους αὐτούς, ᾔσθοντο τοῦ κυρίου."}, {"sp": "N", "st": "Wis 11:14", "t": "τὸν γὰρ ἐν ἐκθέσει πάλαι ῥιφέντα ἀπεῖπον χλευάζοντες· ἐπὶ τέλει τῶν ἐκβάσεων ἐθαύμασαν, οὐχ ὅμοια δικαίοις διψήσαντες."}, {"sp": "N", "st": "Wis 11:15", "t": "ἀντὶ δὲ λογισμῶν ἀσυνέτων ἀδικίας αὐτῶν, ἐν οἷς πλανηθέντες ἐθρήσκευον ἄλογα ἑρπετὰ καὶ κνώδαλα εὐτελῆ, ἐπαπέστειλας αὐτοῖς πλῆθος ἀλόγων ζῴων εἰς ἐκδίκησιν,"}, {"sp": "N", "st": "Wis 11:16", "t": "ἵνα γνῶσιν ὅτι δι᾿ ὧν τις ἁμαρτάνει, διὰ τούτων κολάζεται."}, {"sp": "N", "st": "Wis 11:17", "t": "οὐ γὰρ ἠπόρει ἡ παντοδύναμός σου χεὶρ καὶ κτίσασα τὸν κόσμον ἐξ ἀμόρφου ὕλης ἐπιπέμψαι αὐτοῖς πλῆθος ἄρκων ἢ θρασεῖς λέοντας."}, {"sp": "N", "st": "Wis 11:18", "t": "ἢ νεοκτίστους θυμοῦ πλήρεις θῆρας ἀγνώστους, ἤτοι πυρπνόον φυσῶντας ἆσθμα, ἢ βρόμους λικμωμένους καπνοῦ, ἢ δεινοὺς ἀπʼ ὀμμάτων σπινθῆρας ἀστράπτοντας,"}, {"sp": "N", "st": "Wis 11:19", "t": "ὧν οὐ μόνον ἡ βλάβη ἠδύνατο συνεκτρῖψαι αὐτούς, ἀλλὰ καὶ ἡ ὄψις ἐκφοβήσασα διολέσαι."}, {"sp": "N", "st": "Wis 11:20", "t": "καὶ χωρὶς δὲ τούτων ἑνὶ πνεύματι πεσεῖν ἐδύναντο ὑπὸ τῆς δίκης διωχθέντες, καὶ λικμηθέντες ὑπὸ πνεύματος δυνάμεώς σου· ἀλλὰ πάντα μέτρῳ καὶ ἀριθμῷ καὶ σταθμῷ διέταξας."}, {"sp": "N", "st": "Wis 11:21", "t": "τὸ γὰρ μεγάλως ἰσχύειν πάρεστίν σοι πάντοτε, καὶ κράτει βραχίονός σου τίς ἀντιστήσεται;"}, {"sp": "N", "st": "Wis 11:22", "t": "ὅτι ὡς ῥοπὴ ἐκ πλαστίγγων ὅλος ὁ κόσμος ἐναντίον σου, καὶ ὡς ῥανὶς δρόσου ὀρθρινὴ κατελθοῦσα ἐπὶ γῆν."}, {"sp": "N", "st": "Wis 11:23", "t": "ἐλεεῖς δὲ πάντας, ὅτι πάντα δύνασαι, καὶ παρορᾷς ἁμαρτήματα ἀνθρώπων εἰς μετάνοιαν."}, {"sp": "N", "st": "Wis 11:24", "t": "ἀγαπᾷς γὰρ τὰ ὄντα πάντα, καὶ οὐδὲν βδελύσσῃ ὧν ἐποησας, οὐδέ γὰρ ἂν μισῶν τι κατεσκεύασας."}, {"sp": "N", "st": "Wis 11:25", "t": "πῶς δὲ ἔμεινεν ἄν τι εἰ μὴ σὺ ἠθέλησας, ἢ τὸ μὴ κληθὲν ὑπὸ σοῦ διετηρήθη;"}, {"sp": "N", "st": "Wis 11:26", "t": "φείδῃ δὲ πάντων, ὅτι σά ἐστιν, Δέσποτα φιλόψυχε."}, {"sp": "N", "st": "Wis 12:1", "t": "τὸ γὰρ ἄφθαρτόν σου πνεῦμά ἐστιν ἐν πᾶσιν."}, {"sp": "N", "st": "Wis 12:2", "t": "διὸ τοὺς παραπίπτοντας κατʼ ὀλίγον ἐλέγχεις, καὶ ἐν οἷς ἁμαρτάνουσιν ὑπομιμνήσκων νουθετεῖς, ἵνα ἀπαλλαγέντες τῆς κακίας πιστεύσωσιν ἐπὶ σέ, Κύριε."}, {"sp": "N", "st": "Wis 12:3", "t": "Καὶ γὰρ τοὺς παλαιοὺς οἰκήτορας τῆς ἁγίας σου γῆς"}, {"sp": "N", "st": "Wis 12:4", "t": "μισήσας ἐπὶ τῷ ἔχθιστα πράσσειν ἔργα φαρμακειῶν καὶ τελετὰς ἀνοσίους,"}, {"sp": "N", "st": "Wis 12:5", "t": "τέκνων τε φονέας ἀνελεήμονας, καὶ σπλαγχνοφάγον ἀνθρωπίνων σαρκῶν θοίναν καὶ αἵματος, ἐκ μέσου μύστας θιάσου,"}, {"sp": "N", "st": "Wis 12:6", "t": "καὶ αὐθέντας γονεῖς ψυχῶν ἀβοηθήτων, ἐβουλήθης ἀπολέσαι διὰ χειρῶν πατέρων ἡμῶν,"}, {"sp": "N", "st": "Wis 12:7", "t": "ἵνα ἀξίαν ἀποικίαν δέξηται θεοῦ παίδων ἡ παρὰ σοὶ πασῶν τιμιωτάτη γῆ."}, {"sp": "N", "st": "Wis 12:8", "t": "ἀλλὰ καὶ τούτων ὡς ἀνθρώπων ἐφείσω, ἀπέστειλάς τε προδρόμους τοῦ στρατοπέδου σου σφῆκας, ἵνα αὐτοὺς κατὰ βραχὺ ἐξολεθρεύσωσιν·"}, {"sp": "N", "st": "Wis 12:9", "t": "οὐκ ἀδυνατῶν ἐν παρατάξει ἀσεβεῖς δικαίοις ὑποχειρίους δοῦναι, ἢ θηρίοις δεινοῖς, ἢ λόγῳ ἀποτόμῳ ὑφʼ ἓν ἐκτρῖψαι"}, {"sp": "N", "st": "Wis 12:10", "t": "κρίνων δὲ κατὰ βραχὺ ἐδίδους τόπον μετανοίας, C οὐκ ἀγνοῶν ὅτι πονηρὰ ἡ γένεσις αὐτῶν καὶ ἔμφυτος ἡ κακία αὐτῶν, καὶ ὅτι οὐ μὴ ἀλλαγῇ ὁ λογισμὸς αὐτῶν εἰς τὸν αἰῶνα,"}, {"sp": "N", "st": "Wis 12:11", "t": "σπέρμα γὰρ ἦν κατηραμένον ἀπʼ ἀρχῆς· οὐδὲ εὐλαβούμενός τινα ἐφʼ οἷς ἡμάρτανον ἄδειαν ἐδίδους."}, {"sp": "N", "st": "Wis 12:12", "t": "τίς γὰρ ἐρεῖ Τί ἐποίησας; ἢ τίς ἀντιστήσεται τῷ κρίματί σου; τίς δὲ ἐκαλέσει σοι κατὰ ἐθνῶν ἀπολωλότων, ἃ σὺ ἐποίησας; ἢ τίς εἰς κατάστασίν σοι ἐλεύσεται ἔκδικος κατὰ ἀδίκων ἀνθρώπων;"}, {"sp": "N", "st": "Wis 12:13", "t": "οὔτε γὰρ θεός ἐστιν πλὴν σοῦ, ᾧ μέλει περὶ πάντων, ἵνα δείξῃς ὅτι οὐκ ἀδίκως ἔκρινας·"}, {"sp": "N", "st": "Wis 12:14", "t": "οὔτε βασιλεὺς ἢ τύραννος ἀντοφθαλμῆσαι δυνήσεταί σοι περὶ ὧν ἐκόλασας."}, {"sp": "N", "st": "Wis 12:15", "t": "δίκαιος δὲ ὢν δικαίως τὰ πάντα διέπεις, αὐτὸν τὸν μὴ ὀφείλοντα κολασθῆναι καταδικάσαι ἀλλότριον ἡυούμενος τῆς σῆς δυνάμεως."}, {"sp": "N", "st": "Wis 12:16", "t": "ἡ γὰρ ἰσχύς σου δικαιοσύνης ἀρχή, καὶ τὸ πάντων σε δεσπόζειν πάντων φείδεσθαι ποιεῖ"}, {"sp": "N", "st": "Wis 12:17", "t": "ἰσχὺν γὰρ ἐνδείκνυσαι ἀπιστούμενος ἐπὶ δυνάμεως τελειότητι, καὶ ἐν τοῖς εἰδόσι τὸ θράσος ἐξελέγχεις·"}, {"sp": "N", "st": "Wis 12:18", "t": "σὺ δὲ δεσπόζων ἰσχύος ἐν ἐπιεικείᾳ κρίνεις. καὶ μετὰ πολλῆς φειδοῦς διοικεῖς ἡμᾶς· πάρεστιν γάρ σοι ὅταν θέλῃς τὸ δύνασθαι."}, {"sp": "N", "st": "Wis 12:19", "t": "ἐδίδαξας δέ σου τὸν λαὸν διὰ τῶν τοιούτων ἔργων, ὅτι δεῖ τὸν δίκαιον εἶναι φιλάνθραωπον· καὶ εὐέλπιδας ἐποίησας τοὺς υἱούς σου, ὅτι διδοῖς ἐπὶ ἁμαρτήμασιν μετάνοιαν."}, {"sp": "N", "st": "Wis 12:20", "t": "εἰ γὰρ ἐχθροὺς παίδων σου καὶ ὀφειλομένους θανάτῳ μετὰ τοσαύτης ἐτιμώρησας προσοχῆς καὶ δεήσεως, δοὺς χρόνους καὶ τόπον δι᾿ ὧν ἀπαλλαγῶσι τῆς κακίας,"}, {"sp": "N", "st": "Wis 12:21", "t": "μετὰ πόσης ἀκριβείας ἔκρινας τοὺς υἱούς σου, ὧν τοῖς πατράσιν ὅρκους καὶ συνθήκας ἔδωκας ἀγαθῶν ὑποσχέσεων;"}, {"sp": "N", "st": "Wis 12:22", "t": "ἡμᾶς οὖν παιδεύων τοὺς ἐχθροὺς ἡμῶν ἐν μυριότητι μάστγοῖς, ἵνα σου τὴν ἀγαθότητα μεριμνῶμεν κρίνοντες, κρινόμενοι δὲ προσδοκπῶμεν ἔλεος."}, {"sp": "N", "st": "Wis 12:23", "t": "ὅθεν καὶ τοὺς ἐν ἀφροσύνῃ ζωῆς βιώσαντας ἀδίκους διὰ τῶν ἰδίων ἐβασάνισας βδελυγμάτων."}, {"sp": "N", "st": "Wis 12:24", "t": "καὶ γὰρ τῶν πλάνης ὁδῶν μακρότερον ἐπλανήθησαν, θεοὺς ὑπολαμβάνοντες τὰ καὶ ἐν ζῴοις τῶν ἐχθρῶν ἄτιμα, νηπίων δίκην ἀφρόνων ψευσθέντες."}, {"sp": "N", "st": "Wis 12:25", "t": "διὰ τοῦτο ὡς παισὶν ἀλογίστοις τὴν κρίσιν εἰς ἐμπαιγμὸν ἔπεμψας·"}, {"sp": "N", "st": "Wis 12:26", "t": "οἱ δὲ παιγνίοις ἐπιτιμήσεως μὴ νουθετηθέντες ἀξίαν θεοῦ κρίσιν πειράσουσιν."}, {"sp": "N", "st": "Wis 12:27", "t": "ἐφ᾿ οἷς γὰρ αὐτοὶ πάσχοντες ἠγανάκτουν, ἐπὶ τούτοις οὓς ἐδόκουν θεούς, ἐν αὐτοῖς κολαζόμενοι, ἰδόντες ὃν πάλαι ἠρνοῦντο εἰδέναι θεὸν ἐπέγνωσα ἀληθῆ· διὸ καὶ τὸ τέρμα τῆς καταδίκης ἐπʼ αὐτοὺς ἐπῆλθεν."}, {"sp": "N", "st": "Wis 13:1", "t": "Μάταιοι μέν γὰρ πάντες ἄνθρωποι φύσει, οἷς παρῆν θεοῦ ἀγνωσία, καὶ ἐκ τῶν ὁραωμένων ἀγαθῶν οὐκ ἴσχυσαν εἰδέναι τὸν ὄντα, οὔτε τοῖς ἔργοις προσχόντες ἐπέγνωσαν τὸν τεχνίτην·"}, {"sp": "N", "st": "Wis 13:2", "t": "ἀλλ ἢ πῦρ ἢ πνεῦμα ἢ ταχινὸν ἀέρα ἢ κύκλον ἄστρων ἢ βίαιον ὕδωρ ἢ φωστῆρας οὐρανοῦ πρυτάνεις κόσμου θεοὺς ἐνόμισαν."}, {"sp": "N", "st": "Wis 13:3", "t": "ὧν εἰ μὲν τῇ καλλονῇ τερπόμενοι θεοὺς ὑπελάμβανον, γνώτωσαν πόσῳ τούτων ὁ δεσπότης ἐστὶ βελτίων· ὁ γὰρ τοῦ κάλλους γενεσιάρχης ἔκτισεν αὐτά."}, {"sp": "N", "st": "Wis 13:4", "t": "εἰ δὲ δυνάμει καὶ ἐνεργείᾳ ἐκπλαγέντες, νοησάτωσαν ἀπʼ αὐτῶν πόσῳ ὁ κατασκευάσας αὐτὰ δυνατώτερός ἐστιν·"}, {"sp": "N", "st": "Wis 13:5", "t": "ἐκ γὰρ μεγέθους καλλονῆς καὶ κτισμάτων ἀναλόγως ὁ γενεσιουργὸς αὐτῶν θεωρεῖται."}, {"sp": "N", "st": "Wis 13:6", "t": "ἀλλʼ ὅμως ἐπὶ τούτοις ἐστὶν μέμψις ὀλίγη, καὶ γὰρ αὐτοὶ τάχα πλανῶνται θεὸν ζητοῦντες καὶ θέλοντες εὑρεῖν·"}, {"sp": "N", "st": "Wis 13:7", "t": "ἐν γὰρ τοῖς ἔργοις αὐτοῦ ἀναστρεφόμενοι διεραυνῶσιν, καὶ πείθονται τῇ ὄψει ὅτι καλὰ τὰ βλεπόμενα."}, {"sp": "N", "st": "Wis 13:8", "t": "πάλιν δʼ οὐδʼ αὐτοὶ συνγνωστοί·"}, {"sp": "N", "st": "Wis 13:9", "t": "εἰ γὰρ τοσοῦτον ἴσχυσαν εἰδέναι ἴνα δύνωνται στοχάσασθαι τὸν αἰῶνα, τὸν τούτων δεσπότην πῶς τάχιον οὐχ εὗρον;"}, {"sp": "N", "st": "Wis 13:10", "t": "Ταλαίπωροι δὲ καὶ ἐν νεκροῖς αἱ ἐλπίδες αὐτῶν, οἵτινες ἐκάλεσαν θεοὺς ἔργα χειρῶν ἀνθρώπωον, χρυσὸν καὶ ἄργυρον, τέχνης ἐμμελέτημα, καὶ ἀπεικάσματα ζῴων, ἢ λίθον ἄχρηστον. χειρὸς ἔργον ἀρχαίας."}, {"sp": "N", "st": "Wis 13:11", "t": "εἰ δὲ καί τις ὑλοτόμος τέκτων εὐκίνητον φυτὸν ἐκπρίσας περιέξυσεν εὐμαθῶς πάντα τὸν φλοιὸν αὐτοῦ, καὶ τεχνησάμενος εὐπρεπῶς κατεσκεύασεν χρήσιμον σκεῦος εἰς ὑπηρεσίαν ζωῆς,"}, {"sp": "N", "st": "Wis 13:12", "t": "τὰ δὲ ἀποβλήματα τῆς ἐργασίας εἰς ἑτοιμασίαν τροφῆς ἀναλώσας ἐνεπλήσθη·"}, {"sp": "N", "st": "Wis 13:13", "t": "τὸ δὲ ἐξ αὐτῶν ἀπόβλημα εἰς οὐθὲν εὔχρηστον, ξύλον σκολιὸν καὶ ὄζοις συμπεφυκός, λαβὼν ἔγλυψεν ἐν ἐπιμελείᾳ ἀργίας αὐτοῦ, καὶ ἐμπειρίᾳ ἀνέσεως ἐτύπωσεν αὐτό, ἀπείκασεν αὐτὸ εἰκόνι ἀνθρώπου,"}, {"sp": "N", "st": "Wis 13:14", "t": "ἢ ζῴῳ τινὶ εὐτελεῖ ὡμοίωσεν αὐτό, καταχρίσας μίλτῳ καὶ φύκει ἐρυθήνας χρόαν αὐτοῦ, καὶ πᾶσαν κηλῖδα τὴν ἐν αὐτῷ καταχρίσας,"}, {"sp": "N", "st": "Wis 13:15", "t": "καὶ ποιήσας αὐτῷ αὐτοῦ ἄξιον οἴκημα, ἐν τοίχῳ ἔθηκεν αὐτὸ ἀσφαλισάμενος σιδήρῳ."}, {"sp": "N", "st": "Wis 13:16", "t": "ἵνα μέν οὗν μὴ καταπέσῃ προενόησεν αὐτοῦ, εἰδὼς ὅτι ἀδυνατεῖ ἑαυτῷ βοηθῆσαι, καὶ γάρ ἐστιν εἰκὼν καὶ χρείαν ἔχει βοηθείας."}, {"sp": "N", "st": "Wis 13:17", "t": "περὶ δὲ κτημάτων καὶ γάμων αὐτοῦ καὶ τέκνων προσευχόμενος οὐκ αἰσχύνεται τῷ ἀψύχῳ προσλαλῶν· καὶ περὶ μὲν ὑγείας τὸ ἀσθενὲς ἐπικαλεῖται,"}, {"sp": "N", "st": "Wis 13:18", "t": "περὶ δὲ ζωῆς τὸ νεκρὸν ἀξιοῖ, περὶ δὲ ἐπικουρίας τὸ ἀπειρότατον ἱκετεύει, περὶ δὲ ὁδοιπορίας τὸ μηδὲ βάσει χρῆσθαι δυνάμενον,"}, {"sp": "N", "st": "Wis 13:19", "t": "περὶ δὲ πορισμοῦ καὶ ἐργασίας καὶ χειρῶν ἐπιτυχίας τὸ ἀδρανέστατον ταῖς χερσὶν εὐδράνειαν αἰτεῖται."}, {"sp": "N", "st": "Wis 14:1", "t": "Πλοῦν τις πάλιν στελλόμενος καὶ ἄγρια μέλλων διοδεύειν κύματα τοῦ φέροντος αὐτὸν πλοίου σαθρότερον ξύλον ἐπιβοᾶται."}, {"sp": "N", "st": "Wis 14:2", "t": "ἐκεῖνο μὲν γὰρ ὄρεξις πορισμῶν ἐπενόησεν, τεχνῖτις δὲ σοφία κατεσκεύασεν·"}, {"sp": "N", "st": "Wis 14:3", "t": "ἡ δὲ σή, πάτερ, διακυβερνᾷ πρόνοια, ὅτι ἔδωκας καὶ ἐν θαλάσσῃ ὁδὸν καὶ ἐν κύμασι τρίβον ἀσφαλῆ,"}, {"sp": "N", "st": "Wis 14:4", "t": "δεικνὺς ὅτι δύνασαι ἐκ παντὸς σώζειν, ἴνα κἂν ἄνευ τέχνης τις ἐπιβῇ."}, {"sp": "N", "st": "Wis 14:5", "t": "θέλεις δὲ μὴ ἀργὰ εἶναι τὰ τῆς σοφίας σου ἔργα· διὰ τοῦτο καὶ ἐλαχίστῳ ξύλῳ πιστεύουσιν ἄνθρωποι ψυχάς. καὶ διελθόντες κλύδωνα σχεδίᾳ διεσώθησαν."}, {"sp": "N", "st": "Wis 14:6", "t": "καὶ ἀρχῆς γὰρ ἀπολλυμένων ὑπερηφάνων γιγάντων, ἡ ἐλπὶς τοῦ κόσμου ἐπὶ σχεδίας καταφυγοῦσα ἀπέλιπεν τῷ αἰῶνι σπέρμα γενέσεως, τῇ σῇ κυβερνηθεῖσα"}, {"sp": "N", "st": "Wis 14:7", "t": "εὐλόγηται γὰρ ξύλον δι᾿ οὗ γίνεται δικαιοσύνη·"}, {"sp": "N", "st": "Wis 14:8", "t": "τὸ χειροποίητον δέ, ἐπικατάρατον αὐτὸ καὶ ὁ ποιήσας αὐτό, ὅτι ὁ μὲν ἠργάζετο, τὸ δὲ φθαρτὸν θεὸς ὠνομάσθη."}, {"sp": "N", "st": "Wis 14:9", "t": "ἐν ἴσῳ γὰρ μισητὰ θεῷ καὶ ὁ ἀσεβῶν καὶ ἡ ἀσέβεια αὐτοῦ·"}, {"sp": "N", "st": "Wis 14:10", "t": "καὶ γὰρ τὸ πραχθὲν σὺν τῷ δράσαντι κολασθήσεται."}, {"sp": "N", "st": "Wis 14:11", "t": "διὰ τοῦτο καὶ ἐν εἰδώλοις ἐθνῶν ἐπισκοπὴ ἔσται, ὅτι ἐν κτίσματι θεοῦ εἰς βδέλυγμα ἐγενήθησαν καὶ εἰς σκάνδαλα ψυχαῖς ἀνθρώπων καὶ εἰς παγίδα ποσὶν ἀφρόνων."}, {"sp": "N", "st": "Wis 14:12", "t": "Ἀρχὴ γὰρ πορνείας ἐπίνοια εἰδώλων, εὑρέσεις δὲ αὐτῶν φθορὰ ξωῆς."}, {"sp": "N", "st": "Wis 14:13", "t": "οὔτε γὰρ ἦν ἀπʼ ἀρχῆς, οὔτε εἰς τὸν αἰῶνα ἔσται·"}, {"sp": "N", "st": "Wis 14:14", "t": "κενοδοξίᾳ γὰρ ἀνθρώπων εἰσῆλθεν εἰς κόσμον. καὶ διὰ τοῦτο σύντομον αὐτῶν τέλος ἐπενοήθη."}, {"sp": "N", "st": "Wis 14:15", "t": "ἀώρῳ γὰρ πένθει τρυχόμενος πατὴρ τοῦ ταχέως ἀφαιρεθέντος τέκνου εἰκόνα ποιήσας τὸν τότε νεκρὸν ἄνθρωπον νῦν ὡς θεὸν ἐτίμησεν, καὶ παρέδωκεν τοῖς ὑποχειρίοις μυστήρια καὶ τελετάς·"}, {"sp": "N", "st": "Wis 14:16", "t": "εἶτα ἐν χρόνῳ κρατυνθὲν τὸ ἀσεβὲς ἔθος ὡς νόμος ἐφυλάχθη, καὶ τυράννων ἐπιταγαῖς ἐθρησκεύετο τὰ γλυπτά·"}, {"sp": "N", "st": "Wis 14:17", "t": "οὓς ἐν ὄψει μὴ δυνάμενοι τιμᾷν ἄνθρωποι διὰ τὸ μακρὰν οἰκεῖν, τὴν πόρρωθεν ὄψιν ἀνατυπωσάμενοι, ἐμφανῆ εἰκόνα τοῦ τιμωμένου βασιλέως ἐποίησαν, ἵνα τὸν ἀπόντα ὡς παρόντα κολακεύωσιν διὰ τῆς σπουδῆς."}, {"sp": "N", "st": "Wis 14:18", "t": "εἰς ἐπίτασιν δὲ θρησκείας καὶ τοὺς ἀγνοοῦντας ἡ τοῦ τεχνίτου προετρέψατο φιλοτιμία."}, {"sp": "N", "st": "Wis 14:19", "t": "C 19ὁ μὲν γὰρ τάχα κρατοῦντι βουλόμενος ἀρέσαι ἐξεβιάσατο τῇ τέχνῃ τὴν ὁμοιότητα ἐπὶ τὸ κάλλιον·"}, {"sp": "N", "st": "Wis 14:20", "t": "τὸ δὲ πλῆθος ἐφελκόμενον διὰ τὸ εὔχαρι τῆς ἐργασίας τὸν πρὸ ὀλίγου τιμηθέντα ἄνθρωπον νῦν σέβασμα ἐλογισαντο."}, {"sp": "N", "st": "Wis 14:21", "t": "καὶ τοῦτο ἐγένετο τῷ βίῳ εἰς ἔνεδρον, ὅτι ἢ συμφορᾷ ἢ τυραννίδι δουλεύσαντες ἄνθρωποι τὸ ἀκοινώνητον ὄνομα λίθοις καὶ ξύλοις περιέθεσαν."}, {"sp": "N", "st": "Wis 14:22", "t": "Εἶτ᾿ οὐκ ἤρκεσεν τὸ πλανᾶσθαι περὶ τὴν τοῦ θεοῦ γνῶσιν, ἀλλὰ καὶ μεγάλῳ ζῶντες ἀγνοίας πολέμῳ τὰ τοσαῦτα κακὰ εἰρήνην προσαγορεύουσιν."}, {"sp": "N", "st": "Wis 14:23", "t": "ἢ γὰρ τεκνοφόνους τελετὰς ἢ κρύφια μυστήρια ἢ ἐμμανεῖς ἐξάλλων θεσμῶν κώμους ἄγοντες,"}, {"sp": "N", "st": "Wis 14:24", "t": "οὔτε βίους οὔτε γάμους καθαροὺς ἔτι φυλάσσουσιν, ἕτερος δʼ ἕτερον ἢ λοχῶν ἀναιρεῖ, ἢ νοθεύαων ὀδυνᾶ."}, {"sp": "N", "st": "Wis 14:25", "t": "πάντα δʼ ἐπιμὶξ ἔχει αἷμα καὶ φόνος, κλοπὴ καὶ δόλος, φθορά, ἀπιστία, τάραχος. ἐπιορκία, θ6ορυβος ἀγαθῶν,"}, {"sp": "N", "st": "Wis 14:26", "t": "χάριτος ἀμνησία, ψυχῶν μιασμός, γενέσεως ἐναλλαγή, γάμων ἀταξία, μοιχεία καὶ ἀσέλγεια."}, {"sp": "N", "st": "Wis 14:27", "t": "ἡ γὰρ τῶν ἀνωνύμων εἰδώλων θρησκεία παντὸς ἀρχὴ κακοῦ καὶ αἰτία καὶ πέρας ἐστίν·"}, {"sp": "N", "st": "Wis 14:28", "t": "ἢ γὰρ εὐφραινόμενοι μεμήνασιν, ἢ προφητεύουσιν ψευδῆ. ἢ ζῶσιν ἀδίκως, ἢ ἐπιορκοῦσιν ταχέως·"}, {"sp": "N", "st": "Wis 14:29", "t": "ἀψύχοις γὰρ πεποιθότες εἰδώλοις — κακῶς ὀμόσαντες ἀδικηθῆναι οὐ προσδέχονται."}, {"sp": "N", "st": "Wis 14:30", "t": "ἀμφότερα δὲ αὐτοὺς μετελεύσεται τὰ δίκαια, ὅτι κακῶς ἐφρόνησαν περὶ θεοῦ προσχόντες εἰδώλοις, καὶ ἀδίκως ὤμοσαν ἐν δόλῳ καταφρονήσαντες ὁσιότητος."}, {"sp": "N", "st": "Wis 14:31", "t": "οὐ γὰρ ἡ τῶν ὀμνυμένων δύναμις, ἀλλ᾿ ἡ τῶν ἁμαρτανόντων δίκη ἐπεξέρχεται ἀεὶ τὴν τῶν ἀδίκων παράβασιν"}, {"sp": "N", "st": "Wis 16:1", "t": "Σὺ δὲ ὁ θεὸς ἡμῶν χρηστὸς καὶ ἀληθής, μακρόθυμος καὶ ἐλέει διοικῶν τὰ πάντα."}, {"sp": "N", "st": "Wis 16:2", "t": "καὶ γὰρ ἐὰν ἁμάρτωμεν, σοί ἐσμεν, εἰδότες σου τὸ κράτος· οὐχ ἁμαρτησόμεθα, εἰδότες ὅτι σοὶ λελογίσμεθα."}, {"sp": "N", "st": "Wis 16:3", "t": "τὸ γὰρ ἐπίστασθαί σε ὁλόκληρος δικαιοσύνη, καὶ εἰδέναι σου τὸ κράτος ῥίζα ἀθανασίας."}, {"sp": "N", "st": "Wis 16:4", "t": "οὔτε γὰρ ἐπλάνησεν ἡμᾶς ἀνθρώπων κακότεχνος ἐπίνοια, οὐδὲ σκιαγράφων πόνος ἄκαρπος, εἶδος σπιλωθὲν χρώμασιν διηλλαγμένοις·"}, {"sp": "N", "st": "Wis 16:5", "t": "ὧν ὄψις ἄφροσιν εἰς ὄνειδος ἔρχεται, ποθεῖ τε νεκρᾶς εἰκόνος εἶδος ἄπνουν."}, {"sp": "N", "st": "Wis 16:6", "t": "κακῶν ἐρασταὶ ἄξιοί τε τοιούτων ἐλπίδων καὶ οἱ δρῶντες καὶ οἱ ποθοῦυτες καὶ οἱ σεβόμενοι."}, {"sp": "N", "st": "Wis 16:7", "t": "Καὶ γὰρ κεραμεὺς ἁπαλὴν γῆν θλίων ἐπίμοχθον πλάσσει πρὸς ὑπηρεσίαν ἡμῶν ἕκαστου· ἀλλʼ ἐκ τοῦ αὐτοῦ πηλοῦ ἀνεπλάσατο τά τε τῶν καθαρῶν ἔργων δοῦλα σκεύη τά τε ἐναντία, πάνθʼ ὁμοίως· τούτων δέ ἑτέρου τίς ἑκάστου ἐστὶν ἡ χρῆσις, κριτὴς ὁ πηλουργός·"}, {"sp": "N", "st": "Wis 16:8", "t": "καὶ κακόμοχθος θεὸν μάταιον ἐκ τοῦ αὐτοῦ πλάσσει πηλοῦ, ὃς πρὸ μικροῦ ἐκ γῆς γενηθεὶς μετʼ ὀλίγον πορεύεται ἐξ ἧς ἐλήμφθη. τὸ τῆς ψυχῆς ἀπαιτηθεὶς χρέος."}, {"sp": "N", "st": "Wis 16:9", "t": "ἀλλ᾿ ἔστιν αὐτῷ φροντὶς οὐχ ὅτι μέλλει κάμνειν, οὐδʼ ὅτι βραχυτελῆ βίον ἔχει. ἀλλʼ ἀντερείδεται μὲν χρυσουργοῖς καὶ ἀργυροχόοις. χαλκοπλάστας τε μιμεῖται, καὶ δόξαν ἡγεῖται ὅτι κίβδηλα πλάσσει."}, {"sp": "N", "st": "Wis 16:10", "t": "σ ποδὸς ἡ καρδία αὐτοῦ, καὶ γῆς εὐτελεστέρα ἡ ἐλπὶς αὐτοῦ, πηλοῦ τε ἀτιμότερος ὁ βίος αὐτοῦ,"}, {"sp": "N", "st": "Wis 16:11", "t": "ὅτι ἠγνόησεν τὸν πλάσαντα αὐτὸν καὶ τὸν ἐμπνεύσαντα αὐτῷ ψυχὴν ἐνεργοῖσαν καὶ ἐμφυσήσαντα πνεῦμα ζωτικόν·"}, {"sp": "N", "st": "Wis 16:12", "t": "ἀλλ᾿ ἐλογίσατο παίγνιον εἶναι τὴν ζωὴν ἡμῶν καὶ τὸν βίον πανηγυρισμὸν ἐπικερδῆ, δεῖν γάρ φησιν ὅθεν δὴ κἂν ἐκ κακοῦ πορίζειν."}, {"sp": "N", "st": "Wis 16:13", "t": "οὗτος γὰρ παρὰ πάντας οἶδεν ὅτι ἁμαρτάνει, ὕλης γεώδους εὔθραυστα σκεύη καὶ γλυπτὰ δημιουργῶν."}, {"sp": "N", "st": "Wis 16:14", "t": "πάντες δὲ ἀφρονέστατοι καὶ τάλανες ὑπέρ ψυχὴν νηπίου, οἱ ἐχθροὶ τοῦ λαοῦ σου οἱ καταδυναστεύσαντες αὐτόν."}, {"sp": "N", "st": "Wis 16:15", "t": "ὅτι καὶ πάντα τὰ εἴδωλα τῶν ἐθνῶν ἐλογίσαντο θεούς, οἶς οὔτε ὀμμάτων χρῆσις εἰς ὄρασιν, οὔτε ῥῖνες εἰς συνολκὴν ἀέρος, οδτε ὤτα ἀκούειν, οὔτε δάκτυλοι χειρῶν εἰς ψηλάφησιν, καὶ οἱ πόδες αὐτῶν ἀργοὶ πρὸς ἐπίβασιν."}, {"sp": "N", "st": "Wis 16:16", "t": "ἄνθρωπος γὰρ ἐποίησεν αὐτούς, καὶ τὸ πνεῦμα δεδανισμένος ἔπλασεν αὐτούς· οὐδεὶς γὰρ αὐτῷ ὅμοιον ἄνθρωπος ἰσχύει πλάσαι θεόν·"}, {"sp": "N", "st": "Wis 16:17", "t": "θνητὸς δὲ ὢν νεκρὸν ἐργάζεται χερσὶν ἀνόμοις· κρείττων γάρ ἐστιν τῶν σεβασμάτων αὐτοῦ, ὧν αὐτὸς μέν ἔζησεν, ἐκεῖνα δὲ οὐδέποτε."}, {"sp": "N", "st": "Wis 16:18", "t": "Καὶ τὰ ζῷα δὲ τὰ ἔχθιστα σέβονται· ἀνοίᾳ γὰρ συγκρινόμενα τῶν ἄλλων ἐστὶ χείρονα."}, {"sp": "N", "st": "Wis 16:19", "t": "οὐδ᾿ ὅσον ἐπιποθῆσαι ὡς ἐν ζῴων ὄψει καλὰ τυγχάνει, ἐκπέφευγεν δέ καὶ τὸν τοῦ θεοῦ ἔπαινον κοίτὴν εὐλογίαν οὐ"}, {"sp": "N", "st": "Wis 17:1", "t": "διὰ τοῦτο δι᾿ ὁμοίων ἐκολάσθησαν ἀξίως, καὶ διὰ πλήθους κνωδάλων ἐβασανίσθησαν."}, {"sp": "N", "st": "Wis 17:2", "t": "ἀνθʼ ἧς κολάσεως εὐεργετήσας τὸν λαόν σου, εἰς ἐπιθυμίαν ὀρέξεως ξένην γεῦσιν, τροφὴν ἡτοίμασας ὀρτυγομήτραν."}, {"sp": "N", "st": "Wis 17:3", "t": "ἵνα ἐκεῖνοι μὲν ἐπιθυμοῦντες τροφὴν διὰ τὴν δειχθεῖσαν τῶν ἐπαπεσταλμένων καὶ τὴν ἀναγκαίαν ὄρεξιν ἀποστρέφωνται, αὐτοὶ δὲ ἐπʼ ὀλίγον ἐνδεεῖς γενόμενοι καὶ ξένης μετάσχωσι γεύσεως."}, {"sp": "N", "st": "Wis 17:4", "t": "ἔδει γὰρ ἐκείνοις ἀπαραίτητον ἔνδειαν ἐπελθεῖν τυραννοῦσ τούτοις δὲ μόνον δειχθῆναι πῶς οἱ ἐχθροὶ αὐτῶν ἐβασανίζο"}, {"sp": "N", "st": "Wis 17:5", "t": "καὶ γὰρ ὅτε αὐτοῖς δεινὸς ἐπῆλθεν θηρίων θυμός, δήγμασίν τε σκολιῶν διεφθείροντο ὄφεων, οὐ μέχρι τέλους ἔμεινεν ἡ ὀργή σου·"}, {"sp": "N", "st": "Wis 17:6", "t": "εἰς νουθεσίαν δὲ πρὸς ὀλίγον ἐταράχθησαν, σου. σύμβολον ἔχοντες σωτηρίας, εἰς ἀνάμνησιν ἐντολῆς νόμου"}, {"sp": "N", "st": "Wis 17:7", "t": "ὁ γὰρ ἐπιστραφεὶς οὐ διὰ τὸ θεωρούμενον ἐσώζετο, ἀλλὰ διὰ σέ, τὸν πάντων σωτῆρα."}, {"sp": "N", "st": "Wis 17:8", "t": "καὶ ἐν τούτῳ δὲ ἔπεισας τοὺς ἐχθροὺς ἡμῶν, ὅτι σὺ εἶ ὁ ῥυόμενος ἐκ παντὸς κακοῦ·"}, {"sp": "N", "st": "Wis 17:9", "t": "οὓς μέν γὰρ ἀκρίδων καὶ μυιῶν ἀπέκτεινεν δήγματα, καὶ οὐχ εὑρέθη ἴαμα τῇ ψυχῇ αὐτῶν, ὅτι ἄξιοι ἦσαν ὑπὸ τοιούτων κολασθῆναι·"}, {"sp": "N", "st": "Wis 17:10", "t": "τοὺς δὲ υἱοὺς σου οὐδὲ ἰοβόλων δρακόντων ἐνίκησαν ὀδόντες, τὸ ἔλεος γάρ σου ἀντιπαρῆλθεν καὶ ἰάσατο αὐτούς."}, {"sp": "N", "st": "Wis 17:11", "t": "εἰς γὰρ ὑπόμνησιν τῶν λογίων σου ἐνεκεντρίζοντο, καὶ ὀξέως διεσώζοντο, ἴνα μὴ εἰς βαθεῖαν ἐμπεσόντες λήθην ἀπερίσπαστοι γέναωνται τῆς σῆς εὐεργεσίας."}, {"sp": "N", "st": "Wis 17:12", "t": "καὶ γὰρ οὕτε βοτάνη οὕτε μάλαγμα ἐθεράπευσεν αὐτούς, ἀλλὰ ὁ σός, Κύριε, λόγος ὁ πάντα ἰώμενος."}, {"sp": "N", "st": "Wis 17:13", "t": "σὺ γὰρ ζωῆς καὶ θανάτου ἐξουσίαν ἔχεις, καὶ κατάγεις εἰς πύλας ᾄδου καὶ ἀνάγεις."}, {"sp": "N", "st": "Wis 17:14", "t": "ἄνθρωπος δὲ ἀποκτέννει μὲν τῇ κακίᾳ αὐτοῦ, ἐξελθὸν δὲ πνεῦμα οὐκ ἀναστρέφει, οὐδὲ ἀναλύει ψυχὴν παραλημφθεῖσαν."}, {"sp": "N", "st": "Wis 17:15", "t": "Τὴν δὲ σὴν χεῖρα φυγεῖν ἀδύνατόν ἐστιν."}, {"sp": "N", "st": "Wis 17:16", "t": "ἀρνούμενοι γάρ σε εἰδέναι ἀσεβεῖς ἐν ἰσχύι βραχίονός σου ἐμαστιγώθησαν, ξένοις ὑετοῖς καὶ χαλάζαις καὶ ὄμβροις διωκόμενοι ἀπαραιτήτοις καὶ πυρὶ καταναλισκόμενοι."}, {"sp": "N", "st": "Wis 17:17", "t": "τὸ γὰρ παραδοξότατον, ἐν τῷ πάντα σβεννύντι ὕδατι πλεῖον ἐνήργει τὸ πῦρ, ὑπέρμαχος γὰρ ὁ κόσμος ἐστὶν δικαίων."}, {"sp": "N", "st": "Wis 17:18", "t": "ποτὲ μέν γὰρ ἡμεροῦτο φλόξ, ἴνα μὴ καταφλέξῃ τὰ ἐπʼ ἀσεβεῖς ἀπεσταλμένα ζῷα, ἀλλʼ αὐτοὶ βλέποντες εἰδῶσιν ὅτι θεοῦ κρίσει ἐλαύνονται·"}, {"sp": "N", "st": "Wis 17:19", "t": "ποτὲ δὲ καὶ μεταξὺ ὕδατος ὑπέρ τὴν πυρὸς δύναμιν φλέγει. ἴνα ἀδίκου γῆς γενήματα διαφθείρῃ."}, {"sp": "N", "st": "Wis 17:20", "t": "ἀνθʼ ὧν ἀγγέλων τροφὴν ἐψώμισας τὸν λαόν σου, καὶ ἕτοιμον ἄρτον αὐτοῖς ἀπʼ οὐρανοῦ ἔπεμψας ἀκοπιάτως, πᾶσαν ἡδονὴν ἰσχύοντα καὶ πρὸς πᾶσαν ἁρμόνιον γεῦσιν."}, {"sp": "N", "st": "Wis 17:21", "t": "ἡ μέν γὰρ ὑπόστασίς σου τὴν σὴν γλυκύτητα πρὸς τέκνα ἐνεφάνισεν, τῇ δὲ τοῦ προσφερομένου ἐπιθυμίᾳ ὑπηρετῶν πρὸς ὅ τις ἐβούλετο μετεκιρνᾶτο."}, {"sp": "N", "st": "Wis 17:22", "t": "χιὼν δὲ καὶ κρύσταλλος ὑπέμεινε πῦρ καὶ οὐκ ἐτήκετο, ἵνα γνῶσιν ὅτι τοὺς τῶν ἐχθρῶν καρποὺς κατέφθειρε πῦρ φλεγόμενον ἐν τῇ χαλάζρῃ καὶ ἐν τοῖς ὑετοῖς διαστράπτον·"}, {"sp": "N", "st": "Wis 17:23", "t": "τοῦτο πάλιν δʼ, ἴνα τραφῶσιν δίκαιοι, καὶ τῆς ἰδίας ἐπιλέλησται δυνάμεαως."}, {"sp": "N", "st": "Wis 17:24", "t": "ἡ γὰρ κτίσις σοι τῷ ποιήσαντι ὑπηρετοῦσα ἐπιτείνεται εἰς κόλασιν κατὰ τῶν ἀδίκων, καὶ ἀνίεται εἰς εὐεργεσίαν ὑπέρ τῶν εἰς σἐ πεποιθότων."}, {"sp": "N", "st": "Wis 17:25", "t": "διὰ τοῦτο καὶ τότε τἰς πάντα μεταλλευομένη τῇ παντοτρόφῳ σου δαωρεᾷ ὑπηρετεῖ, πρὸς τὴν τῶν δεομένων θέλησιαυ·"}, {"sp": "N", "st": "Wis 17:26", "t": "ἴνα μάθωσιν οἱ υἱοί σου, οὓς ἠγάπησας, Κύριε, ὅτι οὐχ αἱ γενέσεις τῶν καρπῶν τρέφουσιν ἄνθρωπον, ἀλλὰ τὸ ῥῆμά σου τοὺς σοὶ πιστεύοντας διατηρεῖ."}, {"sp": "N", "st": "Wis 17:27", "t": "τὸ γὰρ ὑπὸ πυρὸς μὴ φθειρόμενον ἁπλῶς ὑπὸ βραχείας ἀκτῖνος ἡλίου θερμαινόμενον ἐτήκετο,"}, {"sp": "N", "st": "Wis 17:28", "t": "Μπως γνωστὸν ἧν ὅτι δεῖ φθάνειν τὸν ἥλιον ἐπʼ εὐχαριστίαν καὶ πρὸς ἀνατολὴν φωτὸς ἐντυγχάνειν σοι."}, {"sp": "N", "st": "Wis 17:29", "t": "ἀχαρίστου γὰρ ἐλπὶς ὡς χειμέριος πάχνη τακήσεται, καὶ ῥυήσεται ὡς ὕδαωρ ἄχρηστον."}, {"sp": "N", "st": "Wis 18:1", "t": "Μεγάλαι γάρ σου αἱ κρίσεις καὶ δυσδιήγητοι· διὰ τοῦτο ἀπαίδευτοι ψυχαὶ ἐπλανήθησαν."}, {"sp": "N", "st": "Wis 18:2", "t": "ὑπειληφότες γὰρ καταδυναστεύεια ἔθνος ἅγιον ἄνομοι. δέσμιοι σκότους καὶ μακρᾶς πεδῆται νυκτὸς κατακλεισθέντες ὀρόφοις, φυγάδες τῆς αἰωνίου προνοίας ἕκειντο."}, {"sp": "N", "st": "Wis 18:3", "t": "λανθάνειν γὰρ νομίζοντες ἐπὶ κρυφαίοις ἁμαρτήμασιν, ἀφεγγεῖ λήθης παρακαλύμματι ἐσκορπίσθησαν, θαμβούμενοι δεινῶς καὶ ἰνδάλμασιν ἐκταρασσόμενοι·"}, {"sp": "N", "st": "Wis 18:4", "t": "οὐδὲ γὰρ ὁ κατέχων αὐτοὺς μυχὸς ἀφόβως διεφύλασσεν, ἦχοι δʼ ἐκταράσσοντες αὐτοὺς περιεκόμπουν, καὶ φάσματα ἀμειδήτοις κατηφῆ προσώποις ἐνεφανίζετο."}, {"sp": "N", "st": "Wis 18:5", "t": "καὶ πυρὸς μέν οὐδεμία βία κατίσχυεν φωτίζειν, οὔτε ἄστρων ἔκλαμπροι φλόγες καταυγάζειν ὑπέμενον τὴν στυγνὴν ἐκείνην νύκτα."}, {"sp": "N", "st": "Wis 18:6", "t": "διεφαίνετο δʼ αὐτοῖς μόνον αὐτομάτη πυρὰ φόβου πλήρης. ἐκδειματούμενοι δὲ τῆς μὴ θεωρουμένης ἐκείνης ὄψεως ἡγοῦυτο χείραω τὰ βλεπόμενα."}, {"sp": "N", "st": "Wis 18:7", "t": "μαγικῆς δέ ἐμπαίγματα κατέκειτο τέχνης, καὶ τῆς ἐπὶ φρονήσει ἀλαζονίας ἔλεγχος ἐφύβριστος·"}, {"sp": "N", "st": "Wis 18:8", "t": "οἱ γὰρ ὑπισχνούμενοι δείματα καὶ ταραχὰς ἀπελαύνειν ψυχῆς νοσούσης, οὗτοι καταγέλαστον εὐλάβειαν ἐνόσουν."}, {"sp": "N", "st": "Wis 18:9", "t": "καὶ γὰρ εἰ μηδέν αὐτοὺς ταραχῶδες ἐφόβει, κνωδάλων παρόδοις καὶ ἑρπετῶν συριγμοῖς ἐκσεσοβημένοι,"}, {"sp": "N", "st": "Wis 18:10", "t": "διώλλυντο ἔντρομοι καὶ τὸν μηδαμόθεν φευκτὸν ἀέρα προσιδεῖν ἀρνούμενοι."}, {"sp": "N", "st": "Wis 18:11", "t": "δειλὸν γὰρ ἰδίως πονηρία μαρτυρεῖ καταδικ ἀεὶ δὲ προσείληφεν τὰ χαλεπὰ συνεχομένη τῇ συνειδήσει."}, {"sp": "N", "st": "Wis 18:12", "t": "οὐθὲν γάρ ἐστιν φόβος εἰ μὴ προδοσία τῶν ἀπὸ λογισμοῦ βοηθημάτων·"}, {"sp": "N", "st": "Wis 18:13", "t": "ἔνδοθεν δὲ οὖσα ἥττων ἡ προσδοκία πλείονα λογίζεται τὴν ἄγνοιαν τῆς παρεχούσης τὴν βάσανον αἰτίας."}, {"sp": "N", "st": "Wis 18:14", "t": "οἱ δὲ τὴν ἀδύνατον ὄντως νύκτα καὶ ἐξ ἀδυνάτου ἄδου μυχῶν ἐπελθοῦσαν"}, {"sp": "N", "st": "Wis 18:15", "t": "τὸν αὐτὸν ὕπνον κοιμώμενοι, τὰ μὲν τέρασιν ἠλαύνοντο φαντασμάτων, τὰ δὲ τῆς ψυχῆς παρελύοντο προδοσίᾳ· αἰφνίδιος γὰρ αὐτοῖς καὶ ἀπροσδόκητος φόβος ἐπῆλθεν."}, {"sp": "N", "st": "Wis 18:16", "t": "εἶθ᾿ οὕτως, ὃς δή ποτʼ οὖν ἦν ἐκεῖ καταπίπτων, ἐφρουρεῖτο εἰς τὴν ἀσίδηρον εἱρκτὴν κατακλεισθείς·"}, {"sp": "N", "st": "Wis 18:17", "t": "εἴ τε γὰρ γεαοργὸς ἦν τις ἡ ποιμὴν ἢ τῶν κατʼ ἐρημίαν ἐργάτης μόχθων, προλημφθεὶς τὴν δυσάλυκτον ἔμενεν ἀνάγκην."}, {"sp": "N", "st": "Wis 18:18", "t": "μιᾷ γὰρ ἁλύσει σκότους πάντες ἐδέθησαν. εἴ τε πνεῦμα συρίζον, ἡ περὶ ἀμφιλαφεῖς κλάδους ὀρνέων ἦχος εὐμελής, ἢ ῥυθμὸς ὕδατος πορευομένου βία,"}, {"sp": "N", "st": "Wis 18:19", "t": "*ἢ κτύπος ἀπηνὴς καταριπτομένων πετρῶυ, ἡ σκιρτώνταον ζῴων δρόμος ἀθεώρητος, ἡ ὠρυομένων ἀπηνεστάτων θηρίων φωνή, ἢ ἀντανακλωμένη ἐκ κοιλότητος ὀρέων ἠχώ, παρέλυσεν αὐτοὺς ἐκφοβοῦντα."}, {"sp": "N", "st": "Wis 18:20", "t": "ὅλος γὰρ ὁ κόσμος λαμπρῷ κατελάμπετο φωτί, καὶ ἀνεμποδίστοις συνείχετο ἔργοις·"}, {"sp": "N", "st": "Wis 18:21", "t": "μόνοις δὲ ἐκείνοις ἐπέτατο βαρεῖα νύξ, εἰκὼν τοῦ μέλλοντος αὐτοὺς διαδέχεσθαι σκότους, ἑαυτοῖς δὲ ἦσαν βαρύτεροι σκότους."}, {"sp": "N", "st": "Wis 19:1", "t": "τοῖς δὲ ὁσίοις σου μέγιστον ἦν φῶς. ὧν φωνὴν ἀκούοντες μορφὴν δὲ οὐχ ὁρῶντες, ὅτι μὲν οὖν κἀκεῖνοι ἐπεπόνθεισαν, ἐμακάριζον·"}, {"sp": "N", "st": "Wis 19:2", "t": "ὅτι δʼ οὐ βλάπτουσιν προηδικημένοι, εὐχαριστοῦσιν, καὶ τοῦ διενεχθῆναι χάριν ἐδέοντο."}, {"sp": "N", "st": "Wis 19:3", "t": "ἀνθʼ ὧν πυριφλεγῆ στύλον, ὁδηγὸν μὲν ἀγνώστου ὁδοιπορίας, ἥλιον δὲ ἀβλαβῆ φιλοτίμου ξενιτείας παρέσχες"}, {"sp": "N", "st": "Wis 19:4", "t": "ἄξιοι μὲν γὰρ ἐκεῖνοι στερηθῆναι φωτὸς καὶ φυλακισθῆναι σκότει, οἱ κατακλείστους φυλάξαντες τοὺς υἱούς σου, δι᾿ ὧν ἤμελλεν τὸ ἄφθαρτον νόμου φῶς τῷ αἰῶνι δίδοσθαι."}, {"sp": "N", "st": "Wis 19:5", "t": "βουλευσαμένους αὐτοὺς τὰ τῶν ὁσίων ἀποκτεῖναι νήπια, καὶ ἑυὸς ἐκτεθέντος τέκνου καὶ σωθέντος, εἰς ἔλεγχον τὸ αὐτῶν ἀφείλω πλῆθος τέκνων, καὶ ὁμοθυμαδὸν ἀπώλεσας ἐν ὕδατι σφοδρῷ."}, {"sp": "N", "st": "Wis 19:6", "t": "ἐκείνη ἡ νὺξ προεγνώσθη πατράσιν ἡμῶν, ἵνα ἀσφαλῶς εἰδότες οἶς ἐπίστευσαν ὅρκοις ἐπευθυμήσωσιν."}, {"sp": "N", "st": "Wis 19:7", "t": "προσεδέχθη ὑπὸ λαοῦ σου σωτηρία μὲν δικαίων, ἐχθρῶν δὲ ἀπωλία·"}, {"sp": "N", "st": "Wis 19:8", "t": "ὧς γὰρ ἐτιμωρήσαω τοὺς ὑπεναντίους, τούτῳ ἡμᾶς προσκαλεσάμενος ἐδόξασας."}, {"sp": "N", "st": "Wis 19:9", "t": "κρυφῇ γὰρ ἐθυσίαζον ὅσιοι παῖδες ἀγαθῶν, καὶ τὸν τῆς θειότητος νόμον ἐν ὁμονοίᾳ διέθεντο, τῶν αὐτῶν ὁμοίως καὶ ἀγαθῶν καὶ κινδύνων μεταλήμψεσθαι τοὺς ἁγίους, πατέρων ἤδη προαναμελπόντων αἴνους."}, {"sp": "N", "st": "Wis 19:10", "t": "ἀντήχει δʼ ἀσύμφωνος ἐχθρῶν ἡ βοή, καὶ οἰκτρὰ διεφέρετο θρηνουμένων παίδων."}, {"sp": "N", "st": "Wis 19:11", "t": "ὁμοίᾳ δὲ δίκῃ δοῦλος ἅμα δεσπότῃ κολασθείς, καὶ δημότης βασιλεῖ τὰ αὐτὰ πάσχων·"}, {"sp": "N", "st": "Wis 19:12", "t": "ὁμοθυμαδὸν δὲ πάντες ἐν ἐνὶ ὀνόματι θανάτου νεκροὺς εἶχον ἀναριθμήτους· οὐδὲ γὰρ πρὸς τὸ θάψαι οἱ ζῶντες ἦσαν ἱκανοί, ἐπεὶ πρὸς μίαν ῥοπὴν ἡ ἐντιμοτέρα γένεσις αὐτῶν διεφθάρη."}, {"sp": "N", "st": "Wis 19:13", "t": "πάντα γὰρ ἀπιστοῦντες διὰ τὰς φαρμακείας, ἐπὶ τῷ τῶν πρωτοτόκων ὀλέθρῳ ὡμολόγησαν θεοῦ υἱὸν λαὸν εἶναι."}, {"sp": "N", "st": "Wis 19:14", "t": "ἡσύχου γὰρ σιγῆς περιεχούσης τὰ πάντα καὶ νυκτὸς ἐν ἰδίῳ τάχει μεσαζούσης τὰ πάντα,"}, {"sp": "N", "st": "Wis 19:15", "t": "ὁ παντοδύναμός σου λόγος ἀπʼ οὐρανῶν ἐκ θρόνων βασιλείων ἀπότομος πολεμιστὴς εἰς μέσον τῆς ὀλεθρίας ἥλατο γῆς·"}, {"sp": "N", "st": "Wis 19:16", "t": "ξίφος ὀξὺ τὴν ἀνυπόκριτον ἐπιταγὴν σου φέρων, καὶ στὰς ἐπλήραοσεν τὰ πάντα θανάτου· καὶ οὐρανοῦ μέν ἥπτετο, βεβήκει δʼ ἐπὶ γῆς."}, {"sp": "N", "st": "Wis 19:17", "t": "τότε παραχρῆμα φαντασίαι μὲν ὀνείρων δεινῶς ἐξετάραξαν αὐτούς, φόβοι δὲ ἐπέστησαν ἀδόκητοι,"}, {"sp": "N", "st": "Wis 19:18", "t": "καὶ ἄλλος ἀλλαχῇ ῥιμφεὶς ἡμίθνητος δι᾿ ἣν ἔθνησκεν αἰτίαν ἐνεφάνιζεν·"}, {"sp": "N", "st": "Wis 19:19", "t": "οἱ γὰρ ὄνειροι θορυβήσαντες αὐτοὺς τοῦτο προεμήνυσαν, ἵνα μὴ ἀγνοοῦντες δι᾿ ὃ κακῶς πάσχουσιν ἀπόλωνται."}, {"sp": "N", "st": "Wis 19:20", "t": "Ἥψατο δὲ καὶ δικαίων πεῖρα θανάτου, καὶ θραῦσις ἐν ἐρήμῳ ἐγένετο πλήθους· ἀλλ᾿ οὐκ ἐπὶ πολὺ ἔμεινεν ἡ ὀργή."}, {"sp": "N", "st": "Wis 19:21", "t": "σπεύσας γὰρ ἀνὴρ ἄμεμπτος προεμάχησεν, τὸ τῆς ἰδίας λειτουργίας ὅπλον προσευχὴν καὶ θυμιάματος ἐξιλασμὸν κομίσας· ἀντέστη τῷ θυμῷ καὶ πέρας ἐπέθηκε τῇ συμφορᾷ, δεικνὺς ὅτι σός ἐστιν θεράπων."}, {"sp": "N", "st": "Wis 19:22", "t": "ἐνίκησεν τὸν ὄχλον οὐκ ἰσχύι τοῦ σώματος, οὐχ ὅπλων ἐνερἀλλὰ λόγῳ τὸν κολάζοντα ὑπέταξεν, ὅρκους πατέρων καὶ διαθήκας ὑπομνήσας."}, {"sp": "N", "st": "Wis 19:23", "t": "σωρηδὸν γὰρ ἤδη πεπτωκότων ἐπʼ ἀλλήλων νεκρῶν. μεταξὺ στὰς ἀνέκοψε τὴν ὀργὴν καὶ διέσχισεν τὴν πρὸς τοὺς ζῶντας ὁδόν."}, {"sp": "N", "st": "Wis 19:24", "t": "24 ἐπὶ γὰρ ποδήρους ἐνδύματος ἦν ὅλος ὁ κόσμος. καὶ πατέρων δόξαι ἐπὶ τετραστίχου λίθου γλυφῆς, καὶ μεγαλωσύνη σου ἐπὶ διαδήματος κεφαλῆς αὐτοῦ."}, {"sp": "N", "st": "Wis 19:25", "t": "τούτοις εἶξεν ὁ ὀλοθρεύων, ταῦτα δέ ἐφοβήθησαν· ἦν γὰρ μόνη ἡ πεῖρα τῆς ὀργῆς ἱκανή."}, {"sp": "N", "st": "Wis 20:1", "t": "Τοῖς δὲ ἀσεβέσιν μέχρι τέλους ἀνελεήμων θυμὸς ἐπέστη· προῄδει γὰρ αὐτῶν καὶ τὰ μέλλοντα,"}, {"sp": "N", "st": "Wis 20:2", "t": "ὅτι αὐτοὶ ἐπιστρέψαντες τοῦ ἀπεῖναι καὶ μετὰ σπουδῆς προπέμψαντες αὐτούς, διώξουσιν μεταμεληθέντες."}, {"sp": "N", "st": "Wis 20:3", "t": "ἔτι γὰρ ἐν χερσὶν ἔχοντες τὰ πένθη καὶ προσοδυρόμενοι τάφοις νεκρῶν, ἕτερον ἐπεσπάσαντο λογισμὸν ἀνοίας, καὶ οὓς ἱκετεύοντες ἐξέβαλον, τούτους ὡς φυγάδας ἐδίωκον."}, {"sp": "N", "st": "Wis 20:4", "t": "εἷλκεν γὰρ αὐτοὺς ἡ ἀξία ἐπὶ τοῦτο πέρας ἀνάγκη, καὶ τῶν συμβεβηκότων ἀμνηστίαν ἐνέβαλεν, ἵνα τὴν λείπουσαυ ταῖς βασάνοις προσαναπληρῶσαωσιν κόλασιν,"}, {"sp": "N", "st": "Wis 20:5", "t": "καὶ ὁ μὲν λαός σου παράδοξον ὁδοιπορίαν πειράσῃ, ἐκεῖνοι δὲ ξένον εὕρωσι θάνατον."}, {"sp": "N", "st": "Wis 20:6", "t": "ὅλη γὰρ ἡ κτίσις ἐν ἰδίῳ γένει πάλιν ἄνωθεν διετυποῦτο, ὑπηρετοῦσα ταῖς ἰδίαις ἐπιταγαῖς, ἵνα οἱ σοὶ παῖδες φυλαχθῶσιν ἀβλαβεῖς."}, {"sp": "N", "st": "Wis 20:7", "t": "ἡ τὴν παρεμβολὴν σκιάζουσα νεφέλη, ἐκ δὲ προυφεστῶτος ὕδατος ξηρᾶς ἀνάδυσις γῆς ἐθεωρήθη, ἐξ ἐρυθρᾶς θαλάσσης ὁδὸς ἀνεμπόδιστος, καὶ χλοηφόρον πεδίον ἐκ κλύδωνος βιαίου·"}, {"sp": "N", "st": "Wis 20:8", "t": "δι᾿ οὖ πανεθνεὶ διῆλθον οἱ τῇ σῇ σκεπαζόμενοι χειρί, θεωρήσαντες θαυμαστὰ τέρατα."}, {"sp": "N", "st": "Wis 20:9", "t": "ὡς γὰρ ἵπποι ἐνεμήθησαν καὶ ὡς ἀμνοὶ διεσκίρτησαν, αἰνοῦντές σε, Κύριε, τὸν ῥυόμενον αὐτούς·"}, {"sp": "N", "st": "Wis 20:10", "t": "ἐμέμνηντο γὰρ ἔτι τῶν ἐν τῇ παροικίᾳ αὐτῶν, πῶς ἀντὶ μὲν γενέσεως ζῴων ἐξήγαγεν ἡ γῆ σκνῖπα, ἀντὶ δὲ ἐνύδρων ἐξηρεύξατο ὁ ποταμὸς πλῆθος βατράχων."}, {"sp": "N", "st": "Wis 20:11", "t": "ἐφʼ ὑστέρῳ δὲ εἶδον καὶ νέαν γένεσιν ὀρνέων, ὅτε ἐπιθυμίᾳ προαχθέντες ἠτήσαντο ἐδέσματα τρυφῆς·"}, {"sp": "N", "st": "Wis 20:12", "t": "εἰς γὰρ παραμυθίαν ἀνέβη αὐτοῖς ἀπὸ θαλάσσης ὀρτυγομήτρα."}, {"sp": "N", "st": "Wis 20:13", "t": "καὶ αἱ τιμωρίαι τοῖς ἁμαρτωλοῖς ἐπῆλθον, οὐκ ἄνευ τῶν γεγονότων τεκμηρίων τῇ βίᾳ τῶν κεραυνῶν· δικαίως γὰρ ἔπασχον ταῖς ἰδίαις αὐτῶν πονηρίαις, (¹³)καὶ γὰρ χαλεπωτέραν μισοξενίαν ἐπετήδευσαν."}, {"sp": "N", "st": "Wis 20:14", "t": "οἱ μὲν γὰρ τοὺς ἀγνοοῦντας οὐκ ἐδέχοντο παρόντας, οὗτοι δὲ εὐεργέτας ξενους ἐδουλοῦντο."}, {"sp": "N", "st": "Wis 20:15", "t": "καὶ οὐ μόνον, ἀλλ᾿ ἦ τις ἐπισκοπὴ ἔσται αὐτῶν, ἐπεὶ ἀπεχθῶς προσεδέχοντο τοὺς ἀλλοτρίους·"}, {"sp": "N", "st": "Wis 20:16", "t": "οἱ δὲ μετὰ ἑορτασμάτων εἰσδεξάμενοι τοὺς ἤδη τῶν αὐτῶν μετεσχηκότας δικαίων δεινοῖς ἐκάκωσαν πόνοις."}, {"sp": "N", "st": "Wis 20:17", "t": "ἐπλήγησαν δὲ καὶ ἀορασίᾳ, ὥσπερ ἐκεῖνοι ἐπὶ ταῖς τοῦ δικαίου θύραις, ὅτε ἀχανεῖ περιβληθέντες σκότει ἕκαστος τῶν αὐτοῦ θυρῶν τὴν δίοδον ἐζήτει."}, {"sp": "N", "st": "Wis 20:18", "t": "δι᾿ ἑαυτῶν γὰρ τὰ στοιχεῖα μεθαρμοζόμενα, ὥσπερ ἐν ψαλτηρίῳ φθόγγοι τοῦ ῥυθμοῦ τὸ ὄνομα διαλλάσσουσιν, πάντοτε μένοντα ἤχῳ, ὅπερ ἐστὶν εἰκάσαι ἐκ τῆς τῶν γεγονότων ὄψεως ἀκριβῶς."}, {"sp": "N", "st": "Wis 20:19", "t": "χερσαῖα γὰρ εἰς ἔνυδρα μετεβάλλετο, καὶ νηκτὰ μετέβαινεν ἐπὶ γῆς·"}, {"sp": "N", "st": "Wis 20:20", "t": "πῦρ ἴσχυσεν ἐν ὕδατι τῆς ἰδίας δυνάμεως, καὶ ὕδωρ τῆς σβεστικῆς δυνάμεως ἐπελανθάνετο."}, {"sp": "N", "st": "Wis 20:21", "t": "φλόγες ἀνάπαλιν εὐφθάρτων ζῴων οὐκ ἐμάραναν σάρκας ἐμπεριπατούντων, οὐδὲ τηκτὸν εὔτηκτον κρυσταλλοειδὲς γένος ἀμβροσίας τροφῆς."}, {"sp": "N", "st": "Wis 20:22", "t": "Κατὰ πάντα γάρ, Κύριε, ἐμεγάλυνας τὸν λαόν σου καὶ ἐδόξασας. καὶ οὐχ ὑπερεῖδες ἐν παντὶ καιρῷ καὶ τόπῳ παριστάμενος."}, {"sp": "HDR", "t": "ΣΟΦΙΑ ΣΕΙΡΑΧ"}, {"sp": "N", "t": "προλοΓοϲ ΠΟΛΛΩΝ καὶ μεγάλων ἡμῖν διὰ τοῦ νόμου καὶ τῶν προφητῶν καὶ τῶν ἄλλων τῶν κατʼ αὐτούς ἠκολουθηκότων δεδομένων, ὑπὲρ ὧν δέον ἐστὶν ἐπαινεῖν τὸν Ἰσραὴλ παιδείας καὶ σοφίας· καὶ ὡς οὐ μόνον αὐτοὺς τοὺς ἀναγινώσκοντας δέον ἐστὶν ἐπιστήμονας γίνεσθαι, ἀλλὰ καὶ τοῖς ἐκτὸς δύνασθαι τοὺς φιλομαθοῦντας χρησίμους εἴψαι καὶ λέγοντας καὶ γράφοντας· ὁ πάππος μου Ἰησοῦς ἐπὶ πλεῖὸν ἑαυτὸν δοὺς εἴς τε τὴν τοῦ νόμου καὶ τῶν προφητῶν καὶ τῶν ἄλλων πατρίων βιβλίων ἀνάγνωσιν, καὶ ἐν τούτοις ἱκανὴν ἔξιν περιποιησάμενος, προήχθη καὶ αὐτὸς συγγράψαι τι τῶν εἰς παιδείαν καὶ σοφίαν ἀνηκόντων, ὅπως οἱ φιλομαθεῖς καὶ τούτων ἔνοχοι γενόμενοι πολλῷ μᾶλλον ἐπιπροσθῶσιν διὰ τῆς ἐννόμου βιώσεως. παρακέκλησθε οὖν μετʼ εὐνοίας καΣ προσοχῆς τὴν ἀνάγνωσιν ποιεῖσθαι, καὶ συγγνώμην ἔχειν ἐφʼ οἰς ἂν δοκῶμεν τῶν κατὰ τὴν ἐρμηνείαν πεφιλοπονημένων τισὶν τῶν λέξεων ἀδυ. ναμεῖν· οὐ γὰρ ἰσοδυναμεῖ αὐτὰ ἐν ἑαυτοῖς Ἐβραιστὶ λεγόμενα καὶ ὅταν μεταχθῇ εἰς ἑτέραν γλῶσσαν· οὐ μόνον δὲ ταῦτα, ἀλλὰ καὶ αὐτὸς ὁ νόμος καὶ αἱ προφητεῖαι καὶ τὰ λοιπὰ τῶν βιβλίων οὐ μικρὰν ἔχει τὴν διαφορὰν ἐν ἑαυτοῖς λεγόμενα. ἐν γὰρ τῷ ὁγδόῳ καὶ τριακοστῷ ἔτει ἐπὶ τοῦ Εὐεργέτου βασιλέως παραγενηθεὶς εἰς Αἴγυπτον καὶ συνχρονίσας, εὑρον οὐ μικρᾶς παιδείας ἀφόμοιον. ἀναγκαιότατον ἐθέμην αὐτὸς προσενέγκασθαί τινα σπουδὴν καὶ φιλοπονίαν τοῦ μεθερμηνεῦσαι τήνδε τὴν βίβλον· πολλὴν γὰρ ἀγρυπνίαν καὶ ἐπιστήμην προσενεγκάμενος ἐν τῷ διαστῆματι τοῦ χρόνου πρὸς τὸ ἐπὶ πέρας ἄγοντα τὸ βιβλίον ἐκδοσθαι καὶ τοῖς ἐν τῇ παροικίᾳ βουλομένοις φιλομαθεῖν, προκατασκευαζομένους τὰ ἤθη ἐν νόμῳ βιωτεύειν."}, {"sp": "N", "st": "Sir 1:1", "t": "ΠΑΣA σοφία παρὰ Κυρίου, καὶ μετʼ αὐτοῦ ἐστιν εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Sir 1:2", "t": "ἄμμον θαλασσῶν καὶ σταγόνας ὑετοῦ καὶ ἡμέρας αἰῶνος τίς ἐξαριθμήσει ;"}, {"sp": "N", "st": "Sir 1:3", "t": "ὕψος οὐρανοῦ καὶ πλάτος γῆς καὶ ἄβυσσον καὶ σοφίαυ τίς ἐξιχνιάσει ;"}, {"sp": "N", "st": "Sir 1:4", "t": "προτέρα πάντων ἔκτισται σοφία, καὶ σύνεσις φρονήσεως ἐξ αἰῶνυς."}, {"sp": "N", "st": "Sir 1:6", "t": "ῥίζα σοφίας τίνι ἀπεκαλύφθη; καὶ τὰ πανουργεύματα αὐτῆς τίς ἔγνω;"}, {"sp": "N", "st": "Sir 1:7", "t": "εἷς ἐστὶν σοφός, φοβερὸς σφόδρα, καθήμενος ἐπὶ τοῦ θρόνου αὐτοῦ."}, {"sp": "N", "st": "Sir 1:9", "t": "Κύριος ⁹αὐτὸς ἔκτισεν αὐτήν, καὶ ἴδεν καὶ ἐξηρίθμησεν αὐτήν, (10)καὶ ἐξέχεεν αὐτὴν ἐπὶ πάντα τὰ ἔργα αὐτοῦ,"}, {"sp": "N", "st": "Sir 1:10", "t": "μετὰ πάσης σαρκὸς κατὰ τὴν δόσιν αὐτοῦ, καὶ ἐχορήγησεν αὐτὴν τοῖς ἀγαπῶσιν αὐτόν."}, {"sp": "N", "st": "Sir 1:11", "t": "φόβος Κυρίου δόξα καὶ καύχημα καὶ εὐφροσύνη καὶ στέφανος ἀγαλλιάματος."}, {"sp": "N", "st": "Sir 1:12", "t": "φόβος Κυρίου τέρψει καρδίαν, καὶ δώσει εὐφροσύνην καὶ χαρὰν καὶ μακροημέρευσιν. τῷ φοβουμένῳ τὸν κύριον εὖ ἔσται ἐπʼ ἐσχάτων, καὶ ἐν ἡμέρᾳ τελευτῆς αὐτοῦ εὑρήσει χάριν."}, {"sp": "N", "st": "Sir 1:14", "t": "ἀρχὴ σοφίας φοβεῖσθαι τὸν θεόν, καὶ μετὰ πιστῶν ἐν μήτρᾳ συνεκτίσθη αὐτοῖς·"}, {"sp": "N", "st": "Sir 1:15", "t": "καὶ μετὰ ἀνθρώπων θεμέλιον αἰῶνος ἐνόσσευσεν, καὶ μετὰ τοῦ σπέρματος αὐτῶν ἐμπιστευθήσεται."}, {"sp": "N", "st": "Sir 1:16", "t": "πλησμονὴ σοφίας φοβεῖσθαι τὸν κύριον. καὶ μεθύσκει αὐτοὺς ἀπὸ τῶν καρπῶν αὐτῆς·"}, {"sp": "N", "st": "Sir 1:17", "t": "πάντα τὸν οἶκον αὐτῆς ἐμπλήσει ἐπιθυμημάτων, καὶ τὰ ἀποδοχεῖα ἀπὸ τῶν γενημάτων αὐτῆς."}, {"sp": "N", "st": "Sir 1:18", "t": "στέφανος σοφίας φόβος Κυρίου, ἀναθάλλων εἰρήνην καὶ ὑγείαν ἰάσεως."}, {"sp": "N", "st": "Sir 1:19", "t": "καὶ εἶδεν καὶ ἐξηρίθμησεν αὐτήν, (24)ἐπιστήμην καὶ γνῶσιν συνέσεως ἐξώμβρησεν, καὶ δόξαν κρατούντων αὐτῆς ἀνύψωσεν."}, {"sp": "N", "st": "Sir 1:20", "t": "ῥίζα σοφίας φοβεῖσθαι τὸν κύριον. καὶ οἱ κλάδοι αὐτῆς μακροημέρευσις."}, {"sp": "N", "st": "Sir 1:22", "t": "Οὐ δυνήσεται θυμὸς ἄδικος δικαιωθῆναι· ἡ γὰρ ῥοπὴ τοῦ θυμοῦ αὐτοῦ πτῶσις αὐτῷ."}, {"sp": "N", "st": "Sir 1:23", "t": "ἕως καιροῦ ἀνθέξεται μακρόθυμος, καὶ ὕστερον αὐτῷ ἀναδώσει εὐφροσύνη·"}, {"sp": "N", "st": "Sir 1:24", "t": "ἕως καιροῦ κρύψει τοὺς λόγους αὐτοῦ, καὶ χείλη πιστῶν ἐκδιηγήσεται σύνεσιν αὐτοῦ."}, {"sp": "N", "st": "Sir 1:25", "t": "ἐν θησαυροῖς σοφίας παραβολὴ· ἐπιστήμης, βδέλυγμα δὲ ἁμαρτωλῷ θεοσέβεια."}, {"sp": "N", "st": "Sir 1:26", "t": "ἐπιθυμήσας σοφίαν διατήρησον ἐντολάς, καὶ Κύριος χορηγήσει σοι αὐτήν."}, {"sp": "N", "st": "Sir 1:27", "t": "σοφία γὰρ καὶ παιδεία φόβος Κυρίρυ, καὶ ἡ εὐδοκία αὐτοῦ (35)πίστις καὶ πρᾳότης."}, {"sp": "N", "st": "Sir 1:28", "t": "μὴ ἀπειθήσῃς φόβῳ Κυρίου, καὶ μὴ προσέλθῃς αὐτῷ ἐν καρδίᾳ δισσῇ."}, {"sp": "N", "st": "Sir 1:29", "t": "μὴ ὑποκριθῇς ἐν στόμασιν ἀνθρώπαν, καὶ ἐν τοῖς χείλεσίν σου πρόσεχε."}, {"sp": "N", "st": "Sir 1:30", "t": "μὴ ἐξύψου σεαυτόν, ἵνα μὴ πέσῃς καὶ ἐπαγάγῃς· τῇ ψυχῇ σου ἀτιμίαν, (39)καὶ ἀποκαλύψει Κύριος τὰ κρυπτά σου. καὶ ἐν μέσῳ συναγωγῆς καταβαλεῖ σε, (40)ὅτι οὐ προσῆλθες φόβῳ Κυρίου, καὶ ἡ καρδία σου πλήρης δόλου."}, {"sp": "N", "st": "Sir 2:1", "t": "Τέκνον, εἰ προσέρχῃ δουλεύειν Κυρίῳ θεῷ, ἑτοίμασον τὴν ψυχήν σου εἰς πειρασμόν·"}, {"sp": "N", "st": "Sir 2:2", "t": "εὔθυνον τὴν καρδίαν σου καὶ καρτέρησον, καὶ μὴ σπεύσῃς ἐν καιρῷ ἐπαγωγῆς·"}, {"sp": "N", "st": "Sir 2:3", "t": "κολλήθητι αὐτῷ καὶ μὴ ἀποστῇς, ἵνα αὐξηθῇς ἐπʼ ἐσχάτων σου."}, {"sp": "N", "st": "Sir 2:4", "t": "πᾶν ὃ ἐὰν ἐπαχθῇ σοι δέξαι, καὶ ἐν ἀλλάγμασιν ταπεινώσεως σου μακροθύμησον·"}, {"sp": "N", "st": "Sir 2:5", "t": "ὅτι ἐν πυρὶ δοκιμάζεται χρυσός, καὶ ἄνθρωποι δεκτοὶ ἐν καμίνῳ ταπεινώσεαως."}, {"sp": "N", "st": "Sir 2:6", "t": "πίστευσον αὐτῷ καὶ ἀντιλήμψεταί σου· εὔθυνον τὰς ὁδούς σου καὶ ἔλπισον ἐπʼ αὐτόν."}, {"sp": "N", "st": "Sir 2:7", "t": "οἱ φοβούμενοι τὸν κύριον, ἀναμείνατε τὸ ἔλεος αὐτοῦ, καὶ μὴ ἐκκλινητε, ἵνα μὴ πέσητε."}, {"sp": "N", "st": "Sir 2:8", "t": "οἱ φοβούμενοι Κύριον, πιστεύσατε αὐτῷ, καὶ οὐ μὴ πταίσῃ ὁ μισθὸς ὑμῶν."}, {"sp": "N", "st": "Sir 2:9", "t": "οἱ φοβούμενοι Κύριον, ἐλπίσατε εἰς ἀγαθὰ καὶ εἰς εὐφροσύυην αἰῶνος καὶ ἐλέους."}, {"sp": "N", "st": "Sir 2:10", "t": "ἐμβλέψατε εἰς ἀρχαίας γενεὰς καὶ ἴδετε· τίς ἐνεπίστευσεν Κυρίῳ καὶ κατῃσχύνθη; (12)ἢ τίς ἐνέμεινεν τῷ φόβῳ αὐτοῦ καὶ ἐγκατελείφθης ἢ τίς ἐπεκαλέσατο αὐτόν, καὶ ὑπερεῖδεν αὐτόν;"}, {"sp": "N", "st": "Sir 2:11", "t": "διότι οἰκτείρμων καὶ ἐλεήμων ὁ κύριρς, καὶ ἀφίησιν ἁμαρτίας καὶ σώζει ἐν καιρῷ θλίψεως."}, {"sp": "N", "st": "Sir 2:12", "t": "οὐαὶ καρδίαις δειλαῖς καὶ χερσὶν παρειμέναις, καὶ ἁμαρτωλῷ ἐπιβαίνοντι ἐπὶ δύο τρίβους."}, {"sp": "N", "st": "Sir 2:13", "t": "οὐαὶ καρδίᾳ παρειμένῃ, ὅτι οὐ πιστεύει· διὰ τοῦτο οὐ σκεπασθήσεται."}, {"sp": "N", "st": "Sir 2:14", "t": "οὐαὶ ὑμῖν τοῖς ἀπολωλεκόσιν τὴν ὑπομονήν· καὶ τί ποιήσετε ὅταν ἐπισκέπτηται ὁ κύριος ;"}, {"sp": "N", "st": "Sir 2:15", "t": "οἱ φοβούμενοι Κύριον οὐκ ἀπειθήσουσνι ῥημάτων αὐτοῦ, καὶ οἱ ἀγαπῶντες αὐτὸν συντηρήσουσιν τὰς ὁδοὺς αὐτοῦ."}, {"sp": "N", "st": "Sir 2:16", "t": "οἱ φοβούμενοι Κύριον ζητήσουσιν εὐδοκίαν αὐτοῦ, καὶ οἱ ἀγαπῶντες αὐτὸν ἐμπλησθήσονται τοῦ νόμου."}, {"sp": "N", "st": "Sir 2:17", "t": "οἱ φοβούμενοι Κύριον ἑτοιμάσουσιν καρδίας αὐτῶν, καὶ ἐνώπιον αὐτοῦ ταπεινώσουσιν τὰς ψυχὰς αὐτῶν."}, {"sp": "N", "st": "Sir 2:18", "t": "ἐμπεσούμεθα εἰς χεῖρας Κυρίου καὶ οὐκ εἰς χεῖρας ἀνθρώπων· (23)ὡς γὰρ ἡ μεγαλωσύνη αὐτοῦ, οὕτως καὶ τὸ ἔλεος αὐτοῦ."}, {"sp": "N", "st": "Sir 3:1", "t": "Ἐμοῦ τοῦ πατρὸς ἀκούσατε, τέκνα, καὶ οὕτως ποιήσατε, ἴνα σαωθῆτε."}, {"sp": "N", "st": "Sir 3:2", "t": "ὁ γὰρ Κύριος ἐδόξασεν πατέρα ἐπὶ τέκνοις, καὶ κρίσιν μητρὸς ἐστερέωσεν ἐφʼ υἱοῖς."}, {"sp": "N", "st": "Sir 3:3", "t": "ὁ τιμῶν πατέρα ἐξιλάσεται ἁμαρτίας·"}, {"sp": "N", "st": "Sir 3:4", "t": "καὶ ὡς ὁ ἀποθησαυρίζων ὁ δοξάζων μητέρα αὐτοῦ."}, {"sp": "N", "st": "Sir 3:5", "t": "ὁ τιμῶν πατέρα εὐφρανθήσεται ὑπὸ τέκνων, καὶ ὡς ὁ ἀποθησαυρίζων ὁ δοξάζων μητέρα αὐτοῦ· καὶ ἐν ἡμέρᾳ προσευχῆς αὐτοῦ εἰσακουσθήσεται."}, {"sp": "N", "st": "Sir 3:6", "t": "ὁ δοξάζων πατέρα μακροημερεύσει, καὶ ὁ εἰσακούων Κυρίου ἀναπαύσει μητέρα αὐτοῦ,"}, {"sp": "N", "st": "Sir 3:7", "t": "καὶ ὡς δεσπόταις δουλεύσει ἐν τοῖς γεννήσασιν αὐτόν."}, {"sp": "N", "st": "Sir 3:8", "t": "ἐν ἔργῳ καὶ λόγῳ τίμα τὸν πατέρα σου, (10)ἵνα ἐπέλθῃ σοι εὐλογία παρʼ αὐτοῦ·"}, {"sp": "N", "st": "Sir 3:9", "t": "εὐλογία γὰρ πατρὸς στηρίζει οἴκους τέκνων, κατάρα δέ μητρὸς ἐκριζοῖ θεμέλια."}, {"sp": "N", "st": "Sir 3:10", "t": "μὴ δοξάζου ἐν ἀτιμίᾳ πατρός σου, οὐ γάρ ἐστίν σοι δόξα πρὸς ἀτιμίαν·"}, {"sp": "N", "st": "Sir 3:11", "t": "ἡ γὰρ δόξα ἀνθρώπου ἐκ τιμῆς πατρὸς αὐτοῦ, καὶ ὄνειδος τέκνοις μήτηρ ἐν ἀδοξίᾳ."}, {"sp": "N", "st": "Sir 3:12", "t": "τέκνον, ἀντιλαβοῦ ἐν γήρᾳ πατρός σου, καὶ μὴ λυπήσῃς αὐτὸν ἐν τῇ ζωῇ αὐτοῦ·"}, {"sp": "N", "st": "Sir 3:13", "t": "κἂν ἀπολείπῃ σύνεσιν, συγγνώμην ἔχε, καὶ μὴ ἀτιμάσῃς αὐτὸν ἐν πάσῃ ἰσχύι σου."}, {"sp": "N", "st": "Sir 3:14", "t": "ἐλεημοσύνη γὰρ πατρὸς οὐκ ἐπιλησθήσεται, (16) καὶ ἀντὶ ἁμαρτιῶν (17)προσανοικοδομηθήσεταί σοι·"}, {"sp": "N", "st": "Sir 3:15", "t": "ἐν ἡμέρᾳ θλίψεως σου ἀναμνησθήσεταί σου· ὡς εὐδία ἐπὶ παγετῷ, οὕτως ἀναλυθήσονταί σου αἱ ἁμαρτίαι."}, {"sp": "N", "st": "Sir 3:16", "t": "ὡς βλάσφημος ὁ ἐγκαταλιπὼν πατέρα, καὶ κεκατηραμένος ὑπὸ Κυρίου ὁ παροργίζων μητέρα αὐτοῦ."}, {"sp": "N", "st": "Sir 3:17", "t": "Τέκνον, ἐν πρᾳύτητι τὰ ἔργα σου διέξαγε, καὶ ὑπὸ ἀνθρώπου δεκτοῦ ἀγαπηθήσῃ."}, {"sp": "N", "st": "Sir 3:18", "t": "ὅσῳ μέγας εἰ, τοσούτῳ ταπεινοῦ σεαυτόν, καὶ ἔναντι Κυρίου εὑρήσεις χάριν·"}, {"sp": "N", "st": "Sir 3:20", "t": "ὅτι μεγάλη ἡ δυναστεία τοῦ κυρίου καὶ ὑπὸ τῶν ταπεινῶν δοξάζεται."}, {"sp": "N", "st": "Sir 3:21", "t": "χαλεπώτερά σου μὴ ζήτει. καὶ ἰσχυρότερά σου μὴ ἐξέταζε."}, {"sp": "N", "st": "Sir 3:22", "t": "ἃ προσετάγη σοι, ταῦτα διανοοῦ· (23)οὐ γάρ ἐστίν σοι χρεία τῶν κρυπτῶν."}, {"sp": "N", "st": "Sir 3:23", "t": "ἐν τοῖς περισσοῖς τῶν ἔργων σου μὴ περιεργάζου· (25) πλείονα γὰρ συνέσεως ἀνθρώπων ὑπεδείχθη σοι."}, {"sp": "N", "st": "Sir 3:25", "t": "πολλοὺς γὰρ ἐπλάνησεν ἡ ὑπόλημψις αὐτῶν, καὶ ὑπόνοια πονηρὰ ὠλίσθησεν διανοίας αὐτῶν."}, {"sp": "N", "st": "Sir 3:26", "t": "καὶ ὁ ἀγαπῶν κίνδυνον ἐν αὐτῷ ἐμπεσεῖται· καρδία σκληρὰ κακωθήσεται ἐπʼ ἐσχάτων, καρδία σκληρὰ βαρυνθήσεται ἐπʼ ἐσχάτων."}, {"sp": "N", "st": "Sir 3:27", "t": "καρδία σκληρὰ βαρυνθήσεται πόνοις, καὶ ὁ ἁμαρταυλὸς προσθήσει ἁμαρτίαν ἐφʼ ἁμαρτίαις."}, {"sp": "N", "st": "Sir 3:28", "t": "ἐπαγωγῇ ὑπερηφάνου οὐκ ἔστιν ἴασις, φυτὸν γὰρ πονηρίας ἐρρίζωκεν ἐν αὐτῷ."}, {"sp": "N", "st": "Sir 3:29", "t": "καρδία συνετοῦ διανοηθήσεται παραβολήν, καὶ οὖς ἀκροατοῦ ἐπιθυμία σοφοῦ."}, {"sp": "N", "st": "Sir 3:30", "t": "πῦρ φλογιζόμενον ἀποσβέσει ὕδωρ, καὶ ἐλεημοσύνη ἐξιλάσεται ἁμαρτίας."}, {"sp": "N", "st": "Sir 3:31", "t": "ὁ ἀνταποδιδοὺς χάριτας μέμνηται εἰς τὰ μετὰ ταῦτα, καὶ ἐν καιρῷ πτώσεαως εὑρήσει στήριγμα."}, {"sp": "N", "st": "Sir 4:1", "t": "Τέκνον, τὴν ζωὴν τοῦ πτωχοῦ μὴ ἀποστερήσῃς, καὶ μὴ παρελκύσῃς ὀφθαλμοὺς ἐπιδεεῖς."}, {"sp": "N", "st": "Sir 4:2", "t": "ψυχὴν πεινῶσαν μὴ λυπήσῃς, καὶ μὴ παροργίσῃς ἄνδρα ἐν ἀπορίᾳ αὐτοῦ."}, {"sp": "N", "st": "Sir 4:3", "t": "καρδίαν παροργισμένην μὴ προσταράξῃς, καὶ μὴ παρελκύσῃς δόσιν προσδεομένου."}, {"sp": "N", "st": "Sir 4:4", "t": "ἱκέτην θλιβόμενον μὴ ἀπαναίνου, καὶ μὴ ἀποστρέψῃς τὸ πρόσαωπόν σου ἀπὸ πτωχοῦ."}, {"sp": "N", "st": "Sir 4:5", "t": "ἀπὸ δεομένου μὴ ἀποστρέψῃς ὀφθαλμόν, καὶ μὴ δῷς τόπον ἀνθρώπῳ καταράσασθαί σε·"}, {"sp": "N", "st": "Sir 4:6", "t": "καταραωμένου γάρ σε ἐν πικρίᾳ ψυχῆς αὐτοῦ, τῆς δεήσεως αὐτοῦ ἐπακούσεται ὁ ποιήσας αὐτόν."}, {"sp": "N", "st": "Sir 4:7", "t": "προσφιλῆ συναγωγῇ σεαυτὸν ποίει, καὶ μεγιστᾶνι ταπείνου τὴν κεφαλήν σου."}, {"sp": "N", "st": "Sir 4:8", "t": "κλῖνον πτωχῷ τὸ οὖς σου, καὶ ἀποκρίθητι αὐτῷ εἰρηνικὰ ἐν πρᾳύτητι."}, {"sp": "N", "st": "Sir 4:9", "t": "ἐξελοῦ ἀδικούμενον ἐκ χειρὸς ἀδικοῦντος, καὶ μὴ ὀλιγοψυχήσῃς ἐν τῷ κρίνειν σε."}, {"sp": "N", "st": "Sir 4:10", "t": "γίνου ὀρφανοῖς ὡς πατήρ, καὶ ἀντὶ ἀνδρὸς τῇ μητρὶ αὐτῶν· (11)καὶ ἔσῃ ὡς υἱὸς Ὑψίστου, καὶ ἀγαπήσει σε μᾶλλον ἢ μήτηρ σου."}, {"sp": "N", "st": "Sir 4:11", "t": "Ἡ σοφία υἱοὺς ἑαυτῇ ἀνύψωσεν, καὶ ἐπιλαμβάνεται τῶν ζητούντων αὐτήν."}, {"sp": "N", "st": "Sir 4:12", "t": "ὁ ἀγαπῶν αὐτὴν ἀγαπᾷ ζωήν, καὶ οἱ ὀρθρίζοντες πρὸς αὐτὴν ἐμπλησθήσονται εὐφροσύνης·"}, {"sp": "N", "st": "Sir 4:13", "t": "ὁ κρατῶν αὐτῆς κληρονομήσει δόξαν, καὶ οὗ εἰσπορεύεται, εὐλογήσει Κύριος·"}, {"sp": "N", "st": "Sir 4:14", "t": "οἱ λατρεύοντες αὐτῇ λειτουργήσουσιν ἁγίῳ, καὶ τοὺς ἀγαπῶντας αὐτὴν ἀγαπᾷ ὁ κύριος·"}, {"sp": "N", "st": "Sir 4:15", "t": "ὁ ὑπακούων αὐτῆς κρινεῖ ἔθνη, καὶ ὁ προσελθὼν αὐτῇ κατασκηνώσει πεποιθώς."}, {"sp": "N", "st": "Sir 4:16", "t": "ἐὰν ἐμπιστεύσῃς, κατακληρονομήσεις αὐτήν, καὶ ἐν κατασχέσει ἔσονται αἱ γενεαὶ αὐτοῦ·"}, {"sp": "N", "st": "Sir 4:17", "t": "ὅτι διεστραμμένως πορεύεται μετʼ αὐτοῦ ἐν πρώτοις, (19)φόβον δὲ καὶ δειλίαν ἐπάξει ἐπʼ αὐτόν, καὶ βασανίσει αὐτὸν ἐν παιδίᾳ αὐτῆς, ἕως οὗ ἐνπιστεύσῃ τῇ ψυχῇ αὐτοῦ· καὶ πειράσει αὐτὸν ἐν τοῖς δικαιώμασιν αὐτῆς·"}, {"sp": "N", "st": "Sir 4:18", "t": "καὶ πάλιν ἐπανήξει κατʼ εὐθεῖαν πρὸς αὐτὸν καὶ εὐφρανεῖ αὐτόν, (21)καὶ ἀποκαλύψει αὐτῷ τὰ κρυπτὰ αὐτῆς."}, {"sp": "N", "st": "Sir 4:19", "t": "ἐὰν ἀποπλανηθῇ, ἐγκαταλείψει αὐτόν, καὶ παραδώσει αὐτὸν εἰς χεῖρας πτώσεως αὐτοῦ."}, {"sp": "N", "st": "Sir 4:20", "t": "Συντήρησον καιρὸν καὶ φύλαξαι ἀπὸ πονηροῦ, (²⁴)καὶ περὶ τῆς ψυχῆς σου μὴ αἰσχυνθῇς·"}, {"sp": "N", "st": "Sir 4:21", "t": "ἔστιν γὰρ αἰσχύνη ἐπάγουσα ἁμαρτίαν, καὶ ἔστιν αἰσχύνη δόξα καὶ χάρις."}, {"sp": "N", "st": "Sir 4:22", "t": "μὴ λάβῃς πρόσωπον κατὰ τῆς ψυχῆς σου, (27)καὶ μὴ ἐντραπῇς εἰς πτῶσίν σου."}, {"sp": "N", "st": "Sir 4:23", "t": "μὴ κωλύσῃς λόγον ἐν καιρῷ σωτηρίας·"}, {"sp": "N", "st": "Sir 4:24", "t": "ἐν γὰρ λόγῳ γνωσθήσεται σοφία, καὶ παιδεία ἐν ῥήματι γλώσσης."}, {"sp": "N", "st": "Sir 4:25", "t": "μὴ ἀντίλεγε τῆ ἀληθεία, καὶ περὶ τῆς ἀπαιδευσίας σου ἐντράπητι·"}, {"sp": "N", "st": "Sir 4:26", "t": "μὴ αἰσχυνθῇς ὁμολογῆσαι ἐφʼ ἁμαρτίαις σου, (32)καὶ μὴ βιάζου ῥοῦν ποταμοῦ."}, {"sp": "N", "st": "Sir 4:27", "t": "καὶ μὴ ὑποστρώσῃς σεαυτὸν ἀνθρώπῳ μωρῷ, καὶ μὴ λάβῃς πρόσωπον δυνάστου."}, {"sp": "N", "st": "Sir 4:28", "t": "ἕως τοῦ θανάτου ἀγώνισαι περὶ τῆς ἀληθείας, καὶ Κύριος ὁ θεὸς πολεμήσει ὑπέρ σοῦ."}, {"sp": "N", "st": "Sir 4:29", "t": "μὴ γίνου τραχὺς ἐν γλώσσῃ σου, καὶ νωθρὸς καὶ παρειμένος ἐν τοῖς ἔργοις σου."}, {"sp": "N", "st": "Sir 4:30", "t": "μὴ ἴσθι ὡς λέων ἐν τῷ οἴκῳ σου, καὶ φαντασιοκοπῶυ ἐν τοῖς οἰκέταις σου."}, {"sp": "N", "st": "Sir 4:31", "t": "μὴ ἔστω ἡ χείρ σου ἐκτεταμένη εἰς τὸ λαβεῖν, καὶ ἐν τῷ ἀποδιδόναι συνεσταλμένη."}, {"sp": "N", "st": "Sir 5:1", "t": "μὴ ἔπεχε ἐπὶ τοῖς χρήμασίν σου, καὶ μὴ εἴπῃς Αὐτάρκη μοί ἐστιν."}, {"sp": "N", "st": "Sir 5:2", "t": "μὴ ἐξακολούθει τῇ ψυχῇ σου καὶ τῇ ἰσχύι σου, πορεύεσθαι ἐν ἐπιθυμίαις καρδίας σου·"}, {"sp": "N", "st": "Sir 5:3", "t": "καὶ μὴ εἴπῃς Τίς με δυναστεύσει; ὁ γὰρ κύριος ἐκδικῶν ἐκδικήσει σε."}, {"sp": "N", "st": "Sir 5:4", "t": "μὴ εἴπῃς Ἥμαρτον, καὶ τί μοι ἐγένετο ; ὁ γὰρ κύριός ἐστιν μακρόθυμος."}, {"sp": "N", "st": "Sir 5:5", "t": "περὶ ἐξιλασμοῦ μὴ ἄφοβος γίνου. προσθεῖναι ἁμαρτίαν ἐφʼ ἁμαρτίαις·"}, {"sp": "N", "st": "Sir 5:6", "t": "καὶ μὴ εἴπῃς Ο οἰκτειρμὸς αὐτοῦ πολύς, τὸ πλῆθος τῶν ἁμαρτιῶν μου ἐξιλάσεται· (7)ἔλεος γὰρ καὶ ὀργὴ παρʼ αὐτοῦ, καὶ ἐπὶ ἁμαρτωλοὺς καταπαύσει ὁ θυμὸς αὐτοῦ·"}, {"sp": "N", "st": "Sir 5:7", "t": "μὴ ἀνάμενε ἐπιστρέψαι πρὸς Κύριον, καὶ μὴ ὑπερβάλλου ἡμέραν ἐξ ἡμέρας· (9)ἐξάπινα γὰρ ἐξελεύσεται ὀργὴ Κυρίου. καὶ ἐν καιρῷ ἐκδικήσεως ἐξολῇ."}, {"sp": "N", "st": "Sir 5:8", "t": "μὴ ἔπεχε ἐπὶ χρήμασιν ἀδίκοις· οὐδὲν γὰρ ὠφελήσεις ἐν ἡμέρᾳ ἐπαγωγῆς"}, {"sp": "N", "st": "Sir 5:9", "t": "μὴ λίκμα ἐν παντὶ ἀνέμῳ, καὶ μὴ πορεύου ἐν πάσῃ ἀτραπῷ· οὕτως ὁ ἁμαρτωλὸς ὁ δίγλωσσος."}, {"sp": "N", "st": "Sir 5:10", "t": "ἵσθι ἐστηριγμένος ἐν συνέσει σου, καὶ εἷς ἔστω σου ὁ λόγος."}, {"sp": "N", "st": "Sir 5:11", "t": "γίνου ταχὺς ἐν ἀκροάσει σου, καὶ ἐν μακροθυμίᾳ φθέγγου ἀπόκρισιν."}, {"sp": "N", "st": "Sir 5:12", "t": "εἰ ἔστιν σοι σύνεσις, ἀποκρίθητι τῷ πλησίον· εἰ δὲ μή, ἡ χείρ σου ἔστω ἐπὶ στόματί σου."}, {"sp": "N", "st": "Sir 5:13", "t": "δόξα καὶ ἀτιμία ἐν λαλιᾷ, καὶ γλῶσσα ἀνθρώπου πτῶσις αὐτῷ."}, {"sp": "N", "st": "Sir 5:14", "t": "μὴ κληθῇς ψίθυρος, καὶ τῇ γλώσσῃ σου μὴ ἐνεδρευθῇς· (17)ἐπὶ γὰρ τῷ κλέπτῃ ἐστὶν αἰσχύνη, καὶ κατάγνωσις πονηρὰ ἐπὶ διγλώσσου."}, {"sp": "N", "st": "Sir 5:15", "t": "ἐν μεγάλῳ καὶ ἐν μικρῷ μὴ ἀγνόει,"}, {"sp": "N", "st": "Sir 6:1", "t": "καὶ ἀντὶ φίλου μὴ γίνου ἐχθρός· ὄνομα γὰρ πονηρὸν αἰσχύνη, καὶ ὄνειδος κληρονομήσει· οὕτως ὁ ἁμαρτωλὸς ὁ δίγλωσσος."}, {"sp": "N", "st": "Sir 6:2", "t": "μὴ ἐπάρῃς σεαυτὸν ἐν βουλῇ ψυχῆς σου, ἵνα μὴ διαρπαγῇ ὡς ταῦρος ἡ ψυχή σου·"}, {"sp": "N", "st": "Sir 6:3", "t": "τὰ φύλλα σου καταφάγεσαι καὶ τοὺς καρποὺς σου ἀπολέσεις, καὶ ἀφήσεις σεαυτὸν ὡς ξύλον ξηρόν."}, {"sp": "N", "st": "Sir 6:4", "t": "Ψυχὴ πονηρὰ ἀπολεῖ τὸν κτησάμενον αὐτήν, καὶ ἐπίχαρμα ἐχθρῶν ποιήσει αὐτόν."}, {"sp": "N", "st": "Sir 6:5", "t": "λάρυγξ γλυκὺς πληθυνεῖ φίλους αὐτοῦ, καὶ γλῶσσα εὔλαλος πληθυνεῖ εὐπροσήγορα."}, {"sp": "N", "st": "Sir 6:6", "t": "οἱ εἰρηνεύοντές σοι ἔστωσαν πολλοί, οἱ δὲ σύμβουλοί σου εἰς ἀπὸ χιλίων."}, {"sp": "N", "st": "Sir 6:7", "t": "εἰ κτᾶσαι φίλον, ἐν πειρασμῷ κτῆσαι αὐτόν, καὶ μὴ ταχὺ ἐμπιστεύσῃς αὐτῷ."}, {"sp": "N", "st": "Sir 6:8", "t": "ἔστιν γὰρ φίλος ἐν καιρῷ αὐτοῦ, καὶ οὐ μὴ παραμείνῃ ἐν ἡμέρᾳ θλίψεως σου·"}, {"sp": "N", "st": "Sir 6:9", "t": "καὶ ἔστιν φίλος μετατιθέμενος εἰς ἔχθραν, καὶ μάχην ὀνειδισμοῦ σου ἀποκαλύψει·"}, {"sp": "N", "st": "Sir 6:10", "t": "καὶ ἔστιν φίλος κοινωνὸς τραπεζῶν, καὶ οὐ μὴ παραμείνῃ ἐν ἡμέρᾳ θλίψεώς σου·"}, {"sp": "N", "st": "Sir 6:11", "t": "καὶ ἐν τοῖς ἀγαθοῖς σου ἔσται ὡς σύ, καὶ ἐπὶ τοὺς οἰκέτας σου παρρησιάσεται·"}, {"sp": "N", "st": "Sir 6:12", "t": "ἐὰν ταπεινωθῇς, ἔσται κατὰ σοῦ, καὶ ἀπὸ τοῦ προσώπου σου κρυβήσεται."}, {"sp": "N", "st": "Sir 6:13", "t": "ἀπὸ τῶν ἐχθρῶν σου διαχωρίσθητι, καὶ ἀπὸ τῶν φίλων σου πρόσεχε."}, {"sp": "N", "st": "Sir 6:14", "t": "φίλος πιστὸς σκέπη κραταιά· ὁ δὲ εὑρὼν αὐτόν, εὗρεν θησαυρόν."}, {"sp": "N", "st": "Sir 6:15", "t": "φίλου πιστοῦ οὐκ ἔστιν ἀντάλλαγμα, καὶ οὐκ ἔστιν σταθμὸς τῆς καλλονῆς αὐτοῦ."}, {"sp": "N", "st": "Sir 6:16", "t": "φίλος πιστὸς φάρμακον ζωῆς, καὶ οἱ φοβούμενοι Κύριον εὑρήσουσιν αὐτόν."}, {"sp": "N", "st": "Sir 6:17", "t": "ὁ φοβούμενος Κύριον εὐθυνεῖ φιλίαν αὐτοῦ, ὅτι κατʼ αὐτὸν οὕτως καὶ ὁ πλησίον αὐτοῦ."}, {"sp": "N", "st": "Sir 6:18", "t": "Τέκνον, ἐκ νεότητός σου ἐπίλεξαι παιδίαν, καὶ ἕως πο λιῶν εὑρ ήσεις σος φίαν·"}, {"sp": "N", "st": "Sir 6:19", "t": "ὡς ὁ ἀροτριῶν καὶ ὁ σπείρφφν πρόσελθε αὐτῇ, καὶ ἀνάμενε τοὺς ἀγαθοὺς καρποὺς αὐτῆς· (20)ἐν γὰρ τῇ ἐργασίᾳ αὐτῆς ὀλίγον κοπιάσεις, καὶ ταχὺ φάγεσαι τῶν γενημάτων αὐτῆς."}, {"sp": "N", "st": "Sir 6:20", "t": "ὡς ταχεῖά ἐστιν σφόδρα τοῖς ἀπαιδεύτοις, καὶ οὐκ ἐμμενεῖ ἐν αὐτῇ ἀκάρδιος·"}, {"sp": "N", "st": "Sir 6:21", "t": "ὡς λίθος δοκιμασίας ἰσχυρὸς ἔσται ἐπʼ αὐτῷ, καὶ οὐ χρονιεῖ ἀπορῖψαι αὐτήν."}, {"sp": "N", "st": "Sir 6:22", "t": "σοφία γὰρ κατὰ τὸ ὄνομα αὐτῆς ἐστιν, καὶ οὐ πολλοῖς ἐστιν φανερά."}, {"sp": "N", "st": "Sir 6:23", "t": "ἄκουσον, τέκνον, καὶ δέξαι γνώμην μου, καὶ μὴ ἀπαναίνου τὴν συμβουλίαν μου·"}, {"sp": "N", "st": "Sir 6:24", "t": "καὶ εἰσένεγκον τοὺς πόδας σου εἰς τὰς πέδας αὐτῆς, καὶ εἰς τὸν κλοιὸν αὐτῆς τὸν τράχηλόν σου·"}, {"sp": "N", "st": "Sir 6:25", "t": "ὑπόθες τὸν ὖμόν σου καὶ βάσταξον αὐτήν, καὶ μὴ προσοχθίσῃς τοῖς δεσμοῖς αὐτῆς·"}, {"sp": "N", "st": "Sir 6:26", "t": "ἐν πάσῃ ψυχῇ σου πρόσελθε αὐτῇ, καὶ ἐν ὅλῃ δυνάμει σου συντήρησον τὰς ὁδοὺς αὐτῆς."}, {"sp": "N", "st": "Sir 6:27", "t": "ἐξίχνευσον καὶ ζήτησον, καὶ γνωσθήσεταί σοι, καὶ ἐγκρατὴς γενόμενος μὴ ἀρῇς αὐτήν·"}, {"sp": "N", "st": "Sir 6:28", "t": "ἐπ᾿ ἐσχάτων γὰρ εὑρήκεις τὴν ἀνάπαυσιν αὐτῆς, καὶ στραφήσεταί σοι εἰς εὐφροσύνην·"}, {"sp": "N", "st": "Sir 6:29", "t": "καὶ ἔσονταί σοι αἱ πέδαι εἰς σκέπην ἰσχύος, καὶ οἱ κλάδοι αὐτῆς εἰς στολὴν δόξης."}, {"sp": "N", "st": "Sir 6:30", "t": "κόσμος γὰρ χρύσεός ἐστιν ἐπʼ αὐτῆς, καὶ οἱ δεσμοὶ αὐτῆς κλῶσμα ὑακίνθινον·"}, {"sp": "N", "st": "Sir 6:31", "t": "στολὴν δόξης ἐνδύσῃ αὐτήν, καὶ στέφανον ἀγαλλιάματος περιθήσεις σεαυτῷ."}, {"sp": "N", "st": "Sir 6:32", "t": "ἐὸν θέλῃς, τέκνον, παιδευθήσῃ, καὶ ἐὰν δῷς τὴν ψυχὴν σου, πανοῦργος ἔσῃ·"}, {"sp": "N", "st": "Sir 6:33", "t": "ἐὰν ἀγαπήσῃς ἀκούειν, ἐκδέξῃ, καὶ ἐὰν κλίνῃς τὸ οὖς σου, σοφὸς ἔσῃ."}, {"sp": "N", "st": "Sir 6:34", "t": "ἐν πλήθει πρεσβυτέρων στῆθι καὶ τίς σοφός; αὐτῷ προσκολλήθητι."}, {"sp": "N", "st": "Sir 6:35", "t": "πᾶσαν διήγησιν θείαν θέλε ἀκούειν, καὶ παροιμίαι συνέσεως μὴ ἐκφευγέτωσάν σε."}, {"sp": "N", "st": "Sir 6:36", "t": "ἐὰν ἴδῃς συνετόν, ὄρθριζε πρὸς αὐτόν, καὶ βαθμοὺς θυρῶν αὐτοῦ ἐκτριβέτω ὁ πούς σου."}, {"sp": "N", "st": "Sir 6:37", "t": "διανοοῦ ἐν τοῖς προστάγμασιν Κυρίου, καὶ ἐν ταῖς ἐντολαῖς αὐτοῦ μελέτα διὰ παντός· αὐτὸς στηριεῖ τὴν καρδίαν σου, καὶ ἡ ἐπιθυμία τῆς σοφίας σου δοθήσεταί σοι."}, {"sp": "N", "st": "Sir 7:1", "t": "Μὴ ποίει κακά, καὶ οὐ μή σε καταλάβῃ κακόν·"}, {"sp": "N", "st": "Sir 7:2", "t": "ἀπόστηθι ἀπὸ ἀδίκου, καὶ ἐκκλινεῖ ἀπὸ σοῦ."}, {"sp": "N", "st": "Sir 7:3", "t": "υἱέ, μὴ σπεῖρε ἐπʼ αὔλακας ἀδικίας, καὶ οὐ μὴ θερίσῃς αὐτὰς ἑπταπλασίως."}, {"sp": "N", "st": "Sir 7:4", "t": "μὴ ζήτει παρὰ Κυρίου ἡγεμονίαν, μηδὲ παρὰ βασιλέως καθέδραν δόξης."}, {"sp": "N", "st": "Sir 7:5", "t": "μὴ δικαιοῦ ἔναντι Κυρίου, καὶ παρὰ βασιλεῖ μὴ σοφίζου."}, {"sp": "N", "st": "Sir 7:6", "t": "μὴ ζήτει γενέσθαι κριτής. μὴ οὐκ ἐξισχύσεις ἐξᾶραι ἀδικίας· μή ποτε εὐλαβηθῇς ἀπὸ προσώπου δυνάστου, καὶ θήσεις σκάνδαλον ἐν εὐθύτητί σου."}, {"sp": "N", "st": "Sir 7:7", "t": "μὴ ἁμάρτανε εἰς πλῆθος πόλεως, καὶ μὴ καταβάλῃς σεαυτὸν ἐν ὄχλῳ."}, {"sp": "N", "st": "Sir 7:8", "t": "μὴ καταδεσμεύσῃς δὶς ἁμαρτίαν, ἐν γὰρ τῇ μιᾷ οὐκ ἀθῷος ἔσῃ."}, {"sp": "N", "st": "Sir 7:9", "t": "μὴ εἴπῃς Τῷ πλήθει τῶν δώρων μου ἐπόψεται, καὶ ἐν τῷ προσενέγκαι με θεῷ ὑψίστῳ προσδέξεται."}, {"sp": "N", "st": "Sir 7:10", "t": "μὴ ὀλιγοψυχήσῃς ἐν τῇ προσευχῇ σου, καὶ ἐλεημοσύνην ποιῆσαι μὴ παρίδῃς."}, {"sp": "N", "st": "Sir 7:11", "t": "μὴ καταγέλα ἄνθρωπον ὄντα ἐν πικρίᾳ ψυχῆς αὐτοῦ· ἔστιν γὰρ ὁ ταπεινῶν καὶ ἀνυψῶν."}, {"sp": "N", "st": "Sir 7:12", "t": "μὴ ἀροτρία ψεῦδος ἐπ᾿ ἀδελφῷ σου. μηδέ φίλῳ τὸ ὅμοιον ποίει."}, {"sp": "N", "st": "Sir 7:13", "t": "μὴ θέλε ψεύδεσθαι πᾶν ψεῦδος· ὁ γὰρ ἐνδελεχισμὸς αὐτοῦ οὐκ εἰς ἀγαθόν."}, {"sp": "N", "st": "Sir 7:14", "t": "μὴ ἀδολέσχει ἐν πλήθει πρεσβυτέρων, καὶ μὴ δευτερώσῃς λόγον ἐν προσευχῇ σου."}, {"sp": "N", "st": "Sir 7:15", "t": "μὴ μισήσῃς ἐπίπονον ἐργασίαν καὶ γεωργίαν ὑπὸ Ὑψίστου ἐκτισμένην."}, {"sp": "N", "st": "Sir 7:16a", "t": "μὴ προσλογίζου σεαυτὸν ἐν πλήθει ἁμαρτωλῶν·"}, {"sp": "N", "st": "Sir 7:17a", "t": "ταπείνωσον σφόδρα τὴν ψυχήν σου."}, {"sp": "N", "st": "Sir 7:16b", "t": "μνήσθητι ὅτι ὀργὴ οὐ χρονιεῖ,"}, {"sp": "N", "st": "Sir 7:17b", "t": "ὅτι ἐκδίκησις ἀσεβοῦς πῦρ καὶ σκώληξ,"}, {"sp": "N", "st": "Sir 7:18", "t": "μὴ ἀλλάξῃς φίλον ἕνεκεν ἀδιαφόρου, μηδὲ ἀδελφὸν γνήσιον ἐν χρυσίῳ Σουφείρ."}, {"sp": "N", "st": "Sir 7:19", "t": "μὴ ἀστόχει γυναικὸς σοφῆς καὶ ἀγαθῆς, καὶ γὰρ χάρις αὐτῆς ὑπὲρ τὸ χρυσίον."}, {"sp": "N", "st": "Sir 7:20", "t": "μὴ κακώσῃς οἰκέτην ἐργαζόμενον ἐν ἀληθεία, μηδὲ μίσθιον διδόντα ψυχὴν αὐτοῦ·"}, {"sp": "N", "st": "Sir 7:21", "t": "οἰκέτην ἀγαθὸν ἀγαπάτω σου ἡ ψυχή· μὴ στερήσῃς αὐτὸν ἐλευθερίας."}, {"sp": "N", "st": "Sir 7:22", "t": "Κτήνη σοί ἐστιν ; ἐπισκέπτου αὐτά, καὶ εἰ ἔστιν σοι χρήσιμα, ἐμμενέταω σοι."}, {"sp": "N", "st": "Sir 7:23", "t": "τέκνα σοί ἐστιν; παίδευσον αὐτά, καὶ κάμψον ἐκ νεότητος τὸν τράχηλον αὐτῶν."}, {"sp": "N", "st": "Sir 7:24", "t": "θυγατέρες σοί εἰσιν; πρόσεχε τῷ σώματι αὐτῶν, καὶ μὴ ἱλαρώσῃς πρὸς αὐτὰς τὸ πρόσαωπόν σου."}, {"sp": "N", "st": "Sir 7:25", "t": "εκδου θυγατέρα, καὶ ἔσῃ τετελεκὼς ἔργον μέγα, καὶ ἀνδρὶ συνετῷ δώρησαι αὐτήν."}, {"sp": "N", "st": "Sir 7:26", "t": "γυνή σοί ἐστιν κατὰ ψυχήν μὴ ἐκβάλῃς αὐτήν."}, {"sp": "N", "st": "Sir 7:27", "t": "ἐν ὅλῃ καρδἰᾳ (29)δόξασον τὸν πατέρα σου, καὶ μητρὸς ὠδῖνας μὴ ἐπιλάθῃ·"}, {"sp": "N", "st": "Sir 7:28", "t": "μνήσθητι ὅτι δι᾿ αὐτῶν ἐγενήθης, καὶ τί ἀνταποδώσεις αὐτοῖς καθὼς αὐτοὶ σοί;"}, {"sp": "N", "st": "Sir 7:29", "t": "ἐν ὅλῃ ψυχῇ σου εὐλαβοῦ τὸν κύριον. καὶ τοὺς ἱερεῖς αὐτοῦ θαύμαζε·"}, {"sp": "N", "st": "Sir 7:30", "t": "ἐν ὅλῃ δυνάμει ἀγάπησον τὸν ποιήσαντά σε, καὶ τοὺς λειτουργοὺς αὐτοῦ μὴ ἐγκαταλίπῃς."}, {"sp": "N", "st": "Sir 7:31", "t": "φοβοῦ τὸν κύριον καὶ δόξασον ἱερέα, (34)καὶ δὸς τὴν μερίδα αὐτῷ καθὼς ἐντέταλταί σοι ἀπʼ ἀρχῆς. (35)καὶ περὶ πλημμελίας καὶ δόσιν βραχιόνων καὶ θυσίαν ἁγιασμοῦ καὶ ἀπαρχήν."}, {"sp": "N", "st": "Sir 7:32", "t": "καὶ πτωχῷ ἔκτεινον τὴν χεῖρά σου, ἵνα τελειωθῇ ἡ εὐλογία σου."}, {"sp": "N", "st": "Sir 7:33", "t": "χάρις δόματος ἔναντι παντὸς ζῶντος, καὶ ἐπὶ νεκρῷ μὴ ἀποκωλύσῃς χάριν."}, {"sp": "N", "st": "Sir 7:34", "t": "μὴ ὑστέρει ἀπὸ κλαιόντων, καὶ μετὰ πευθούντων πένθησον."}, {"sp": "N", "st": "Sir 7:35", "t": "μὴ ὄκνει ἐπισκέπτεσθαι ἄρρωστον· ἐκ γὰρ τῶν τοιούταων ἀγαπηθήσῃ."}, {"sp": "N", "st": "Sir 7:36", "t": "ἐν πᾶσι τοῖς λόγοις σου μιμνήσκου τὰ ἔσχατά σου, καὶ εἰς τὸν αἰῶνα οὐχ ἁμαρτήσεις."}, {"sp": "N", "st": "Sir 8:1", "t": "Μὴ διαμάχου μετὰ ἀνθρώπου δυνάστου, μὴ ποτε ἐμπέσῃς εἰς τὰς χεῖρας αὐτοῦ."}, {"sp": "N", "st": "Sir 8:2", "t": "μὴ ἔριζε μετὰ ἀνθρώπου πλουσίου, μὴ ποτε ἀντιστήσῃ σου τὴν ὁλκήν· (3)πολλοὺς γὰρ ἀπώλεσεν τὸ χρυσίον, καὶ καρδίας βασιλέων ἐξέκλινεν."}, {"sp": "N", "st": "Sir 8:3", "t": "μὴ διαμάχου μετὰ ἀνθρώπου γλωσσώδους, καὶ μὴ ἐπιστοιβάσῃς ἐπὶ τὸ πῦρ αὐτοῦ ξύλα."}, {"sp": "N", "st": "Sir 8:4", "t": "μὴ πρόσπαιζε ἀπαιδεύτῳ, ἵνα μὴ ἀτιμάζωνται οἱ πρόγονοί σου."}, {"sp": "N", "st": "Sir 8:5", "t": "μὴ ὀνείδιζε ἄνθρωπον ἀποστρέφοντα ἀπὸ ἁμαρτίας· μνήσθητι ὅτι πάντες ἐσμὲν ἐν ἐπιτίμοις."}, {"sp": "N", "st": "Sir 8:6", "t": "μὴ ἀτιμάσῃς ἄνθρωπον ἐν γήρει αὐτοῦ, καὶ γὰρ ἐξ ἡμῶν γηράσκουσιν."}, {"sp": "N", "st": "Sir 8:7", "t": "μὴ ἐπίχαιρε ἐπὶ νεκρῷ· μνήσθητι ὅτι πάντες τελευτῶμεν."}, {"sp": "N", "st": "Sir 8:8", "t": "μὴ παρίδῃς διήγημα σοφῶν, καὶ ἐν ταῖς παροιμίαις αὐτῶν ἀναστρέφου· (10)ὅτι παρʼ αὐτῶν μαθήσῃ παιδείαν καὶ λειτουργῆσαι μεγιστᾶσιν."}, {"sp": "N", "st": "Sir 8:9", "t": "μὴ ἀστόχει διηγήματος γερόντων, καὶ γὰρ αὐτοὶ ἔμαθον παρὰ τῶν πατέρων αὐτῶν· ὅτι παρʼ αὐτῶν μαθήσῃ σύνεσιν καὶ ἐν καιρῷ χρείας δοῦναι ἀπόκρισιν."}, {"sp": "N", "st": "Sir 8:10", "t": "μὴ ἔκκαιε ἄνθρακας ἁμαρτωλοῦ, μὴ ἐμπυρισθῇς ἐν πυρὶ φλογὸς αὐτοῦ."}, {"sp": "N", "st": "Sir 8:11", "t": "μὴ ἐξαναστῇς ἀπὸ προσώπου ὑβριστοῦ, ἵνα μὴ ἐνκαθίσῃ ὡς ἔνεδρον τῷ στόματί σου."}, {"sp": "N", "st": "Sir 8:12", "t": "μὴ δανίσῃς ἀνθρὠπῳ ἰσχυροτέρῳ σου, καὶ ἐὰν δανίσῃς, ὡς ἀπολωλεκὼς γίνου."}, {"sp": "N", "st": "Sir 8:13", "t": "μὴ ἐγγυήσῃ ὑπέρ δύναμίν σου, καὶ ἐὰν ἐγγυήσῃ, ὡς ἀποτίσων φρόντιζε."}, {"sp": "N", "st": "Sir 8:14", "t": "μὴ δικάζου μετὰ κριτοῦ· κατὰ γὰρ τὴν δόξαν αὐτοῦ κρινοῦσιν αὐτῷ."}, {"sp": "N", "st": "Sir 8:15", "t": "μετὰ τολμηροῦ μὴ πορεύου ἐν ὁδῷ, ἵνα μὴ καταβαρύνηται κατὰ σοῦ· αὐτὸς γὰρ κατὰ τὸ θέλημα αὐτοῦ ποιήσει, καὶ τῇ ἀφροσύνῃ αὐτοῦ συναπολῇ."}, {"sp": "N", "st": "Sir 8:16", "t": "μετὰ θυμώδους μὴ ποιήσῃς μάχην, καὶ μὴ διαπορεύου μετʼ αὐτοῦ τὴν ἔρημον· ὅτι ὡς οὐδὲν ἐν ὀφθαλμοῖς αὐτοῦ αἷμα, καὶ ὅπου οὐκ ἔστιν βοήθεια καταβαλεῖ σε."}, {"sp": "N", "st": "Sir 8:17", "t": "μετὰ μωροῦ μὴ συμβουλεύου, οὐ γὰρ δυνήσεται λόγον στέξαι."}, {"sp": "N", "st": "Sir 8:18", "t": "ἐνώπιον ἀλλοτρίου μὴ ποιήσῃς κρυπτόν, οὐ γὰρ γινώσκεις τί τέξεται."}, {"sp": "N", "st": "Sir 8:19", "t": "παντὶ ἀνθρώπῳ μὴ ἔκφαινε σὴν καρδίαν, καὶ μὴ ἀναφερέτω σοι χάριν."}, {"sp": "N", "st": "Sir 9:1", "t": "Μὴ ζήλου γυναῖκα τοῦ κόλπου σου, μηδὲ διδάξῃς ἐπὶ σεαυτὸν παιδείαν πονηράν"}, {"sp": "N", "st": "Sir 9:2", "t": "μὴ δῷς γυναικὶ τὴν ψυχήν σου, ἐπιβῆναι αὐτὴν ἐπὶ τὴν ἰσχύν σου."}, {"sp": "N", "st": "Sir 9:3", "t": "μὴ ὑπάντα γυναικὶ ἑταιριζομένῃ, μή ποτε ἐμπέσῃς εἰς τὰς παγίδας αὐτῆς."}, {"sp": "N", "st": "Sir 9:4", "t": "μετὰ ψαλλούσης μὴ ἐνδελέχιζε. μή ποτε ἁλῷς ἐν τοῖς ἐπιχειρήμασιν αὐτῆς."}, {"sp": "N", "st": "Sir 9:5", "t": "παρθένον μὴ καταμάνθανε, μή ποτε σκανδαλισθῇς ἐν τοῖς ἐπιτιμίοις αὐτῆς."}, {"sp": "N", "st": "Sir 9:6", "t": "μὴ δῷς πόρναις τὴν ψυχήν σου, ἵνα μὴ ἀπολέσῃς τὴν κληρονομίαν σου."}, {"sp": "N", "st": "Sir 9:7", "t": "μὴ περιβλέπου ἐν ῥύμαις πόλεως, καὶ ἐν ταῖς ἐρήμοις αὐτῆς μὴ πλανῶ."}, {"sp": "N", "st": "Sir 9:8", "t": "ἀπόστρεψον ὀφθαλμὸν ἀπὸ γυναικὸς εὐμόρφου. καὶ μὴ καταμάνθανε κάλλος ἀλλότριον· (9)ἐν κάλλει γυναικὸς πολλοὶ ἐπλανήθησαν, καὶ ἐκ τούτου φιλία ὡς πῦρ ἀνακαίεται."}, {"sp": "N", "st": "Sir 9:9", "t": "μετὰ ὑπάνδρου γυναικὸς μὴ κάθου τὸ σύνολον, (13)καὶ μὴ συμβολοκοπήσῃς μετʼ αὐτῆς ἐν οἴνῳ· μή ποτε ἐκκλίνῃ ἡ ψυχὴ σου ἐπʼ αὐτήν, καὶ τῷ πνεύματί σου ὀλισθήσῃς εἰς ἀπώλειαν."}, {"sp": "N", "st": "Sir 9:10", "t": "Μὴ ἐγκαταλίπῃς φίλον ἀρχαῖον, ὁ γὰρ πρόσφατος οὐκ ἔστιν ἔφισος αὐτῷ· (15)οἶνος νέος φίλος νέος· ἐὰν παλαιωθῇ, μετʼ εὐφροσύνης πίεσαι αὐτόν."}, {"sp": "N", "st": "Sir 9:11", "t": "μὴ ζηλώσῃς δόξαν ἁμαρτωλοῦ· οὐ γὰρ οἶδας τί ἔσται ἡ καταστροφὴ αὐτοῦ."}, {"sp": "N", "st": "Sir 9:12", "t": "μὴ εὐδοκήσῃς ἐν εὐδοκίᾳ ἀσεβῶν, μνήσθητι ὅτι ἕως ᾅδου οὐ μὴ δικαιωθῶσιν."}, {"sp": "N", "st": "Sir 9:13", "t": "μακρὰν ἄπεχε ἀπὸ ἀνθρώπου ὃς ἔχει ἐξουσίαν τοῦ φονεῦσαι, καὶ οὐ μὴ ὑποπτεύσῃς φόβον θανάτου· (19)κἂν προσέλθῃς, μὴ πλημμελήσῃς. ἵνα μὴ ἀφέληται τὴν ζωήν σου· (20)ἐπίγνωθι ὅτι ἐν μέσῳ παγίδων διαβαίνεις, καὶ ἐπὶ ἐπάλξεων πόλεων περιπατεῖς."}, {"sp": "N", "st": "Sir 9:14", "t": "κατὰ τὴν ἰσχύν σου στόχασαι τοὺς πλησίον, καὶ μετὰ σοφῶν συμβουλεύου·"}, {"sp": "N", "st": "Sir 9:15", "t": "καὶ μετὰ συνετῶν ἔστω ὁ διαλογισμός σου, καὶ πᾶσα διήγησίς σου ἐν νόμῳ Ὑψίστου."}, {"sp": "N", "st": "Sir 9:16", "t": "ἄυδρες δίκαιοι ἔσταοσαν σύνδειπνοί σου, καὶ ἐν φόβῳ Κυρίου ἔστω τὸ καύχημά σου."}, {"sp": "N", "st": "Sir 9:17", "t": "ἐν χειρὶ τεχνικῶν ἔργον ἐπαινεσθήσεται, καὶ ὁ ἡγούμενος λαοῦ σοφὸς ἐν λόγῳ αὐτοῦ."}, {"sp": "N", "st": "Sir 9:18", "t": "φοβερὸς ἐν πόλει αὐτοῦ ἀνὴρ γλωσσώδης, καὶ ὁ προπετὴς ἐν λόγῳ αὐτοῦ μισηθήσεται."}, {"sp": "N", "st": "Sir 10:1", "t": "Κριτὴς σοφὸς παιδεύσει τὸν λαὸν αὐτοῦ, καὶ ἡγεμονία συνετοῦ τεταγμένη ἔσται."}, {"sp": "N", "st": "Sir 10:2", "t": "κατὰ τὸν κριτὴν τοῦ λαοῦ αὐτοῦ οὕτως καὶ οἱ λειτουργοὶ αὐτοῦ, καὶ κατὰ τὸν ἡγούμενον τῆς πόλεως πάντες οἱ κατοικοῦντες αὐτὴν."}, {"sp": "N", "st": "Sir 10:3", "t": "βασιλεὺς ἀπαίδευτος ἀπολεῖ τὸν λαὸν αὐτοῦ, καὶ πόλις οἰκισθήσεται ἐν συνέσει δυναστῶν."}, {"sp": "N", "st": "Sir 10:4", "t": "ἐν χειρὶ Κυρίου ἐξουσία τῆς γῆς. καὶ τὸν χρήσιμον ἐγερεῖ εἰς καιρὸν ἐπʼ αὐτῆς."}, {"sp": "N", "st": "Sir 10:5", "t": "ἐν χειρὶ Κυρίου εὐοδία ἀνδρός, καὶ προσώπῳ γραμματέως ἐπιθήσει δόξαν αὐτοῦ."}, {"sp": "N", "st": "Sir 10:6", "t": "Ἐπὶ παντὶ ἀδικήματι μὴ μηνιάσῃς τῷ πλησίον, καὶ μὴ πρᾶσσε μηδὲν ἐν ἔργοις ὕβρεως."}, {"sp": "N", "st": "Sir 10:7", "t": "μισητὴ ἔναντι Κυρίου καὶ ἀνθρώπων ὑπερηφανία, καὶ ἐξ ἀμφοτέρων πλημμελήσει ἄδικα."}, {"sp": "N", "st": "Sir 10:8", "t": "βασιλεία ἀπὸ ἔθνους εἰς ἔθνος μετάγεται διὰ ἀδικίας καὶ ὕβρεις καὶ χρήματα."}, {"sp": "N", "st": "Sir 10:9", "t": "τί ὑπερηφανεύεται γῆ καὶ σποδός; ὅτι ἐν ζωῇ ἔρριψα τὰ ἐνδόσθια αὐτοῦ."}, {"sp": "N", "st": "Sir 10:10", "t": "μακρὸν ἀρρώστημα, σκώπτει ἰατρός· καὶ βασιλεὺς σήμερον, καὶ αὔριον τελευτήσει."}, {"sp": "N", "st": "Sir 10:11", "t": "ἐν γὰρ τῷ ἀποθανεῖν ἄνθρωπον κληρονομήσει ἑρπετὰ καὶ θηρία, σκώληκας."}, {"sp": "N", "st": "Sir 10:12", "t": "ἀρχὴ ὑπερηφανίας ἀνθρώπου ἀφισταμένου ἀπὸ Κυρίου, (15)καὶ ἀπὸ τοῦ ποιήσαντος αὐτὸν ἀπέστη ἡ καρδία αὐτοῦ."}, {"sp": "N", "st": "Sir 10:13", "t": "ὅτι ἀρχὴ ὑπερηφανίας ἁμαρτία, καὶ ὁ κρατῶν αὐτῆς ἐξομβρήσει βδέλυγμα. (16)διὰ τοῦτο παρεδόξασεν Κύριος τὰς ἐπαγωγάς. καὶ κατέστρεψεν εἰς τέλος αὐτοὺς·"}, {"sp": "N", "st": "Sir 10:14", "t": "θρόνους ἀρχόντων καθεῖλεν ὁ κύριος. καὶ ἐκάθισεν πρᾳεῖς ἀντʼ αὐτῶν·"}, {"sp": "N", "st": "Sir 10:15", "t": "ῥίζας ἐθνῶν ἐξέτιλεν ὁ κύριος. καὶ ἐφύτευσεν ταπεινοὺς ἀντʼ αὐτῶν·"}, {"sp": "N", "st": "Sir 10:16", "t": "χώρας ἐθνῶν κατέστρεψεν ὁ κύριος. καὶ ἀπώλεσεν αὐτὰς ἕως θεμελίων γῆς·"}, {"sp": "N", "st": "Sir 10:17", "t": "ἐξήρανεν ἐξ αὐτῶν καὶ ἀπώλεσεν αὐτούς, καὶ κατέπαυσεν ἀπὸ γῆς τὸ μνημόσυνον αὐτῶν."}, {"sp": "N", "st": "Sir 10:18", "t": "οὐκ ἔκτισται ἀνθρώποις ὑπερηφανία, οὐδὲ ὀργὴ θυμοῦ γεννήμασιν γυναικῶν."}, {"sp": "N", "st": "Sir 10:19", "t": "σπέρμα ἔντιμον ποῖον; σπέρμα ἀνθρώπου· σπέρμα ἔντιμον ποῖον; οἱ φοβούμενοι τὸν κύριον. σπέρμα ἄτιμον ποῖον; σπέρμα ἀνθρώπου· σπέρμα ἄτιμον ποῖον; οἱ παραβαίνοντες ἐντολάς."}, {"sp": "N", "st": "Sir 10:20", "t": "ἐν μέσῳ ἀδελφῶν ὁ ἡγούμενος αὐτῶν ἔντιμος. καὶ οἱ φοβούμενοι Κύριον ἐν ὀφθαλμοῖς αὐτοῦ."}, {"sp": "N", "st": "Sir 10:22", "t": "γτλούσιος καὶ ἔνδοξος καὶ πτωχός, τὸ καύχημα αὐτῶν φόβος Κυρίου."}, {"sp": "N", "st": "Sir 10:23", "t": "οὐ δίκαιον ἀτιμάσαι πτωχὸν συνετόν, καὶ οὐ καθῆκεν δοξάσαι ἄνδρα ἁμαρτωλόν."}, {"sp": "N", "st": "Sir 10:24", "t": "μεγιστὰν καὶ κριτὴς καὶ δυνάστης δοξασθήσεται, καὶ οὐκ ἔστιν αὐτῶν τις μείζων τοῦ φοβουμένου τὸν κύριον."}, {"sp": "N", "st": "Sir 10:25", "t": "οἰκέτῃ σοφῷ ἐλεύθεροι λειτουργήσουσιν, καὶ ἀνὴρ ἐπιστήμων οὐ γογγύσει."}, {"sp": "N", "st": "Sir 10:26", "t": "Μὴ σοφίζου ποιῆσαι τὸ ἔργον σου, καὶ μὴ δοξάζου ἐν καιρῷ στενοχωρίας σου."}, {"sp": "N", "st": "Sir 10:27", "t": "κρείσσων ἐργαζόμενος ἐν πᾶσιν ἢ περιπατῶν, ἢ δοξαζόμενος καὶ ἀπορῶν ἄρτων."}, {"sp": "N", "st": "Sir 10:28", "t": "τέκνον, ἐν πρᾳύτητι δόξασον τὴν ψυχήν σου, καὶ δὸς αὐτῇ τιμὴν κατὰ τὴν ἀξίαν αὐτῆς."}, {"sp": "N", "st": "Sir 10:29", "t": "τὸν ἁμαρτάνοντα εἰς τὴν ψυχὴν αὐτοῦ τίς δικαιώσει; καὶ τίς δοξάσει τὸν ἀτιμάζοντα τὴν ζωὴν αὐτοῦ;"}, {"sp": "N", "st": "Sir 10:30", "t": "πτωχὸς δοξάζεται δι᾿ ἐπιστήμην αὐτοῦ, καὶ πλούσιος δοξάζεται διὰ τὸν πλοῦτον αὐτοῦ."}, {"sp": "N", "st": "Sir 10:31", "t": "ὁ δὲ δοξαζόμενος ἐν πτωχείᾳ, καὶ ἐν πλούτῳ ποσαχῶς; καὶ ὁ ἄδοξος ἐν πλούτῳ, ἐν πτωχείᾳ ποσαχῶς"}, {"sp": "N", "st": "Sir 11:1", "t": "σοφία ταπεινοῦ ἀνύψωσεν κεφαλήν, καὶ ἐν μέσῳ μεγιστάνων καθίσει αὐτόν."}, {"sp": "N", "st": "Sir 11:2", "t": "μὴ αἰνέσῃς ἄνδρα ἐν κάλλει αὐτοῦ, καὶ μὴ βδέλυξῃ ἄνθρωπον ἐν ὁράσει αὐτοῦ."}, {"sp": "N", "st": "Sir 11:3", "t": "μικρὰ ἐν πετεινοῖς μέλισσα, καὶ ἀρχὴ γλυκασμάτων ὁ καρπὸς αὐτῆς."}, {"sp": "N", "st": "Sir 11:4", "t": "ἐν περιβολῇ ἱματίων μὴ καυχήσῃ, καὶ ἐν ἡμέρᾳ δόξης μὴ ἐπαίρου· ὅτι θαυμαστὰ τὰ ἔργα Κυρίου, καὶ κρυπτὰ τὰ ἔργα αὐτοῦ ἐν ἀνθρώποις."}, {"sp": "N", "st": "Sir 11:5", "t": "πολλοὶ τύραννοι ἐκάθισαν ἐπὶ ἐδάφους, ὁ δὲ ἀνυπονόητος ἐφόρεσεν διάδημα·"}, {"sp": "N", "st": "Sir 11:6", "t": "πολλοὶ δυνάσται ἠτιμάσθησαν σφόδρα, καὶ ἔνδοξοι παρεδόθησαν εἰς χεῖρας ἑταίρων."}, {"sp": "N", "st": "Sir 11:7", "t": "πρὶν ἐξετάσῃς μὴ μέμψῃ, υόησον πρῶτον καὶ τότε ἐπιτίμα."}, {"sp": "N", "st": "Sir 11:8", "t": "πρὶν ἢ ἀκοῦσαι μὴ ἀποκρίνου, καὶ ἐν μέσῳ λόγων μὴ παρεμβάλλου."}, {"sp": "N", "st": "Sir 11:9", "t": "περὶ πράγματος οὗ οὐκ ἔστιν σοι χρεία μὴ ἔριζε. καὶ ἐν κρίσει ἁμαρτωλῶν μὴ συνέδρευε."}, {"sp": "N", "st": "Sir 11:10", "t": "τέκνον, μὴ περὶ πολλὰ ἔστωσαν αἱ πράξεις σου· ἐὰν πληθύνῃς, οὐκ ἀθῳωθήσῃ· καὶ ἐὰν διώκῃς, οὐ μὴ καταλάβῃς, καὶ οὐ μὴ ἐκφύγῃς διαδράς."}, {"sp": "N", "st": "Sir 11:11", "t": "ἔητιν κοπιῶν καὶ πονῶν καὶ σπεύδων, καὶ τόσῳ μᾶλλον ὑστερεῖται."}, {"sp": "N", "st": "Sir 11:12", "t": "ἔστιν νωθρὸς καὶ προσδεόμενος ἀντιλήμψεως, ὑστερῶν ἰσχύι καὶ πτωχείᾳ περισσεύει· (13)καὶ οἱ ὀφθαλμοὶ Κυρίου ἐπέβλεψαν αὐτῷ εἰς ἀγαθά. καὶ ἀνώρθωσεν αὐτὸν ἐκ ταπεινώσεως αὐτοῦ."}, {"sp": "N", "st": "Sir 11:13", "t": "καὶ ἀνύψωσεν κεφαλὴν αὐτοῦ, καὶ ἀπεθαύμασαν ἐπʼ αὐτῷ πολλοί"}, {"sp": "N", "st": "Sir 11:14", "t": "ἀγαθὰ καὶ κακά, ζωὴ καὶ θάνατος, πταχεία καὶ πλοῦτος παρὰ Κυρίου ἐστίν."}, {"sp": "N", "st": "Sir 11:17", "t": "Δόσις Κυρίου παραμένει εὐσεβέσιν, καὶ ἡ εὐδοκία αὐτοῦ εἰς τὸν αἰῶνα εὐοδααοθήσεται."}, {"sp": "N", "st": "Sir 11:18", "t": "ἔστιν πλουτῶν ἀπὸ προσοχῆς καὶ σφιγγίας αὐτοῦ, καὶ αὕτη ἡ μερὶς τοῦ μισθοῦ αὐτοῦ·"}, {"sp": "N", "st": "Sir 11:19", "t": "ἐν τῷ εἰπεῖν αὐτόν Εὗρον ἀνάπαυσιν, καὶ νῦν φάγομαι ἐκ τῶν ἀγαθῶν μου, (20)καὶ οὐκ οἶδεν τίς καιρὸς παρελεύσεται, καὶ καταλείψει αὐτὰ ἑτέροις καὶ ἀποθανεῖται."}, {"sp": "N", "st": "Sir 11:20", "t": "στῆθι ἐν διαθήκῃ σου καὶ ὁμίλει ἐν αὐτῇ, καὶ ἐν τῷ ἔργῳ σου παλαιώθητι."}, {"sp": "N", "st": "Sir 11:21", "t": "μὴ θαύμαζε ἐν ἔργοις ἁμαρτωλοῦ· πίστευε τῷ κυρίῳ καὶ ἔμμενε τῷ πόνῳ σου· (23)ὅτι κοῦφον ἐν ὀφθαλμοῖς Κυρίου διὰ τάχους ἐξάπινα πλου· τίσαι πένητα."}, {"sp": "N", "st": "Sir 11:22", "t": "εὐλογία Κυρίου ἐν μισθῷ εὐσεβοῦς, καὶ ἐν ὥρᾳ ταχινῇ ἀναθάλλει εὐλογίαν αὐτοῦ."}, {"sp": "N", "st": "Sir 11:23", "t": "μὴ εἴπῃς Τίς ἐστίν μου χρεία, καὶ τίνα ἀπὸ τοῦ νῦν ἔσται μου τὰ ἀγαθά;"}, {"sp": "N", "st": "Sir 11:24", "t": "μὴ εἴπῃς Αὐτάρκη μοί ἐστιν, καὶ τί ἀπὸ τοῦ νῦν κακωθήσομαι ;"}, {"sp": "N", "st": "Sir 11:25", "t": "ἐν ἡμέρᾳ ἀγαθῶν ἀμνησία κακῶν, καὶ ἐν ἡμέρᾳ κακῶν οὐ μνησθήσεται ἀγαθῶν·"}, {"sp": "N", "st": "Sir 11:26", "t": "ὅτι κοῦφον ἔναντι Κυρίου ἐν ἡμέρᾳ τελευτῆς ἀποδοῦναι ἀνθρώπῳ κατὰ τὰς ὁδοὺς αὐτοῦ."}, {"sp": "N", "st": "Sir 11:27", "t": "κάκωσις ὥρας ἐπιλησμονὴν ποιεῖ τρυφῆς, καὶ ἐν συντελείᾳ ἀνθρώπου ἀποκάλυψις ἔργων αὐτοῦ."}, {"sp": "N", "st": "Sir 11:28", "t": "πρὸ τελευτῆς μὴ μακάριζε μηδένα, καὶ ἐν τέκνοις αὐτοῦ γνωσθήσεται ἀνήρ."}, {"sp": "N", "st": "Sir 11:29", "t": "Μὴ πάντα ἄνθρωπον εἴσαγε εἰς τὸν οἶκόν σου· πολλὰ γὰρ τὰ ἔνεδρα τοῦ δολίου."}, {"sp": "N", "st": "Sir 11:30", "t": "πέρδιξ θηρευτὴς ἐν καρτάλλῳ· οὕτως καρδία ὑπερηφάνου, καὶ ὡς ὁ κατάσκοπος ἐπιβλέπει πτῶσιν."}, {"sp": "N", "st": "Sir 11:31", "t": "τὰ γὰρ ἀγαθὰ εἰς κακὰ μεταστρέφων ἐνεδρεύει, καὶ ἐν τοῖς αἱρετοῖς ἐπιθήσει μῶμον."}, {"sp": "N", "st": "Sir 11:32", "t": "ἀπὸ σπινθῆρος πυρὸς πληθυνθήσεται ἀνθρακιά, καὶ ἄνθρωπος ἁμαρτωλὸς εἰς αἷμα ἐνεδρεύει."}, {"sp": "N", "st": "Sir 11:33", "t": "πρόσεχε ἀπὸ κακούργου, πονηρὰ γὰρ τεκταίνει, μὴ ποτε μῶμον εἰς τὸν αἰῶνα δῷ σοι."}, {"sp": "N", "st": "Sir 11:34", "t": "ἐνοίκισον ἀλλότριον, καὶ διαστρέψει σε ἐν ταραχαῖς καὶ ἀπαλλοτριώσει σε τῶν ἰδίων σου."}, {"sp": "N", "st": "Sir 12:1", "t": "ἐὸν εὖ ποιῆς, γνῶθι τίνι ποιεῖς, καὶ ἔσται χάρις τοῖς ἀγαθοῖς σου."}, {"sp": "N", "st": "Sir 12:2", "t": "εὖ ποίησον εὐσεβεῖ, καὶ εὑρήσεις ἀνταπόδομα, καὶ εἰ μὴ παρὰ αὐτοῦ, ἀλλὰ παρὰ Ὑψίστου."}, {"sp": "N", "st": "Sir 12:3", "t": "οὐκ ἔστιν ἀγαθὰ τῷ ἐνδελεχίζοντι εἰς κακὰ καὶ τῷ ἐλεημοσύνην μὴ χαριζομένῳ."}, {"sp": "N", "st": "Sir 12:4", "t": "δὸς τῷ εὐσεβεῖ, καὶ μὴ ἀντιλάβῃ τοῦ ἁμαρτωλοῦ."}, {"sp": "N", "st": "Sir 12:5", "t": "εὖ ποίησον τῷ ταπεινῷ καὶ μὴ δῷς ἀσεβεῖ ἐμπόδισον τοὺς ἄρτους αὐτοῦ καὶ μὴ δῷς αὐτῷ, ἵνα μὴ ἐν αὐτοῖς σε δυναστεύσῃ· (7)διπλάσια γὰρ κακὰ εὑρήσεις ἐν πᾶσιν ἀγαθοῖς οἷς ἂν ποιήσῃς αὐτῷ."}, {"sp": "N", "st": "Sir 12:6", "t": "ὅτι καὶ ὁ ὕψιστος ἐμίσησεν ἁμαρτωλούς, καὶ τοῖς ἀσεβέσιν ἀποδώσει ἐκδίκησιν."}, {"sp": "N", "st": "Sir 12:7", "t": "δὸς τῷ ἀγαθῷ, καὶ μὴ ἀντιλάβῃ τοῦ ἁμαρτωλοῦ."}, {"sp": "N", "st": "Sir 12:8", "t": "Οὐκ ἐκδικηθήσεται ἐν ἀγαθοῖς ὁ φίλος, καὶ οὐ κρυβήσεται ἐν κακοῖς ὁ ἐχθρός."}, {"sp": "N", "st": "Sir 12:9", "t": "ἐν ἀγαθοῖς ἀνδρὸς οἱ ἐχθροὶ αὐτοῦ ἐν λύπῃ, καὶ ἐν τοῖς κακοῖς αὐτοῦ καὶ ὁ φίλος διαχωρισθήσεται."}, {"sp": "N", "st": "Sir 12:10", "t": "μὴ πιστεύσῃς τῷ ἐχθρῷ σου εἰς τὸν αἰῶνα· ὡς γὰρ ὁ χαλκὸς ἰοῦται, οὕτως ἡ πονηρία αὐτοῦ·"}, {"sp": "N", "st": "Sir 12:11", "t": "καὶ ἐὰν ταπεινωθῇ καὶ πορεύηται συνκεκυφώς, ἐπίστησον τὴν ψυχήν σου καὶ φύλαξαι ἀπʼ αὐτοῦ, καὶ ἔσῃ αὐτῷ ὡς ἐκμεμαχὼς ἔσοπτρον, καὶ γνώσῃ ὅτι οὐκ εἰς τέλος κατίωσεν."}, {"sp": "N", "st": "Sir 12:12", "t": "μὴ στήσῃς αὐτὸν παρὰ σεαυτόν, μὴ ἀνατρέψας σε στῇ ἐπὶ τὸν τόπον σου· μὴ καθίσῃς αὐτὸν ἐκ δεξιῶν σου, μή ποτε ζητήσῃ τὴν καθέδραν σου, καὶ ἐπʼ ἐσχάτῳ ἐπιγνώσῃ τοὺς λόγους μου, καὶ ἐπὶ τῶν ῥημάτων μου κατανυγήσῃ."}, {"sp": "N", "st": "Sir 12:13", "t": "τίς ἐλεήσει ἐπαοιδὸν ὀφιόδηκτον καὶ πάντας τοὺς προσάγοντας θηρίοις ;"}, {"sp": "N", "st": "Sir 12:14", "t": "οὕτως τὸν προσπορευόμενον ἀνδρὶ ἁμαρτωλῷ καὶ συνφυρόμενον ἐν ταῖς ἁμαρτίαις αὐτοῦ."}, {"sp": "N", "st": "Sir 12:15", "t": "ὤραν μετὰ σοῦ διαμενεῖ, καὶ ἐὰν ἐκκλίνῃς, οὐ μὴ καρτερήσῃ."}, {"sp": "N", "st": "Sir 12:16", "t": "καὶ ἐν τοῖς χείλεσιν αὐτοῦ γλυκανεῖ ὁ ἐχθρός, καὶ ἐν τῇ καρδίᾳ αὐτοῦ βουλεύσεται ἀνατρέψαι σε εἰς βόθρον· (16)ἐν ὀφθαλμοῖς αὐτοῦ δακρύσει ὁ ἐχθρός, καὶ ἐὰν εὕρῃ καιρόν, οὐκ ἐμπλησθήσεται ἀφʼ αἵματος·"}, {"sp": "N", "st": "Sir 12:17", "t": "κακὰ ἂν ὑπαντήσῃ σοι, εὑρήκεις αὐτὸν πρότερον ἐκεῖ σου, (18)κοὶ ὡς βοηθῶν ὑποσχάσει πτέρναν σου·"}, {"sp": "N", "st": "Sir 12:18", "t": "κινήσει τὴν κεφαλὴν αὐτοῦ καὶ ἐπικροτήσει ταῖς χερσὶν αὐτοῦ, καὶ πολλὰ διαψιθυρίσει καὶ ἀλλοιώσει τὸ πρόσωπον αὐτοῦ."}, {"sp": "N", "st": "Sir 13:1", "t": "Ὁ ἁπτόμενος πίσσης μολυνθήσεται, καὶ ὁ κοινωνῶν ὑπερηφάνῳ ὁμοιωθήσεται αὐτῷ."}, {"sp": "N", "st": "Sir 13:2", "t": "βάρος ὑπέρ σέ μὴ ἄρης. καὶ ἰσχυροτέρῳ σου καὶ πλουσιαωτέρῳ μὴ κοινώνει. (³)τί κοινωνήσει χύτρα πρὸς λέβητα; αὕτη προσκρούσει, καὶ αὕτη συντριβήσεται."}, {"sp": "N", "st": "Sir 13:3", "t": "πλούσιος ἠδίκησεν, καὶ αὐτὸς προσενεβριμήσατο· πτωχὸς ἠδίκηται, καὶ αὐτὸς προσδεηθήσεται."}, {"sp": "N", "st": "Sir 13:4", "t": "ἐὰν χρησιμεύσῃς. ἐργᾶται ἐν σοί καὶ ἐὰν ὑστερήσῃς, καταλείψει σε·"}, {"sp": "N", "st": "Sir 13:5", "t": "ἐὸν ἔχῃς. συμβιώσεταί σοι καὶ ἀποκενώσει σε, καὶ αὐτὸς οὐ πονέσει·"}, {"sp": "N", "st": "Sir 13:6", "t": "χρείαν ἔσχηκέν σου, καὶ ἀποπλανήσει σε, καὶ προσγελάσεταί σοι καὶ δώσει σοι ἐλπίδαλαλήσει σοι καλὰ καὶ ἐρεῖ Τίς ἡ χρεία σου;"}, {"sp": "N", "st": "Sir 13:7", "t": "καὶ αἰσχυνεῖ σε ἐν τοῖς βρώμασιν αὐτοῦ, ἕως οὗ ἀποκενώσῃ σε δὶς ἢ τρίς, καὶ ἐπʼ ἐσχάτῳ καταμωκήσεταί σου· μετὰ ταῦτα ὄψεταί σε καὶ καταλείψει σε, καὶ τὴν κεφαλὴν αὐτοῦ κινήσει ἐπὶ σοί."}, {"sp": "N", "st": "Sir 13:8", "t": "πρόσεχε μὴ ἀποπλανηθῇς, καὶ μὴ ταπεινωθῇς ἐν εὐφροσύνῃ σου."}, {"sp": "N", "st": "Sir 13:9", "t": "προσκαλεσαμένου σε δυνάστου ὑποχωρῶν γίνου, καὶ τόσῳ μᾶλλον προσκαλέσεταί σε·"}, {"sp": "N", "st": "Sir 13:10", "t": "μὴ ἔμπιπτε, ἵνα μὴ ἀπωσθῇς, καὶ μὴ μακρὰν ἀφιστῶ, ἵνα μὴ ἐπιλησθῇς."}, {"sp": "N", "st": "Sir 13:11", "t": "μὴ ἔπεχε ἰσηγορεῖσθαι μετʼ αὐτοῦ, καὶ μὴ πίστευε τοῖς πλείοσιν λόγοις αὐτοῦ· ἐκ πολλῆς γὰρ λαλιᾶς πειράσει σε, καὶ ὡς προσγελῶν ἐξετάσει σε·"}, {"sp": "N", "st": "Sir 13:12", "t": "ἀνελεήμων ὁ μὴ συντηρῶν λόγους, καὶ οὐ μὴ φείσηται περὶ κακώσεως καὶ δεσμῶν."}, {"sp": "N", "st": "Sir 13:13", "t": "συντήρησον καὶ πρόσεχε σφοδρῶς, ὅτι μετὰ τῆς πτώσεως σου περιπατεῖς."}, {"sp": "N", "st": "Sir 13:15", "t": "πᾶν ζῷον ἀγαπᾷ τὸ ὅμοιον αὐτῷ, καὶ πᾶς ἄνθρωπος τὸν πλησίον αὐτοῦ·"}, {"sp": "N", "st": "Sir 13:16", "t": "πᾶσα σὰρξ κατὰ γένος συνάγεται, καὶ τῷ ὁμοίῳ αὐτοῦ προσκολληθήσεται ἀνήρ."}, {"sp": "N", "st": "Sir 13:17", "t": "τί κοινωνήσει λύκος ἀμνῷ ; οὕτως ἁμαρτωλὸς πρὸς εὐσεβῆ."}, {"sp": "N", "st": "Sir 13:18", "t": "τίς εἰρήνη ὑαίνῃ πρὸς κύνα; καὶ τίς εἰρήνη πλουσίῳ πρὸς πένητα;"}, {"sp": "N", "st": "Sir 13:19", "t": "κυνήγια λεόντων ὄναγροι ἐν ἐρήμῳ· οὕτως νομαὶ πλουσίων πτωχοί."}, {"sp": "N", "st": "Sir 13:20", "t": "βδέλυγμα ὑπερηφάνῳ ταπεινότης, οὕτως βδέλυγμα πλουσίῳ πτωχός."}, {"sp": "N", "st": "Sir 13:21", "t": "πλούσιος σαλευόμενος στηρίζεται ὑπὸ φίλων, ταπεινὸς δὲ πεσὼν προσαπωθεῖται ὑπὸ φίλαων."}, {"sp": "N", "st": "Sir 13:22", "t": "πλουσίου σφαλέντος πολλοὶ ἀντιλήμπτορες, ἐλάλησεν ἀπόρρητα καὶ ἐδικαίωσαν αὐτόν· (27)ταπεινὸς ἔσφαλεν καὶ προσεπετίμησαν αὐτῷ, ἐφθέγξατο σύνεσιν καὶ οὐκ ἐδόθη αὐτῷ τόπος."}, {"sp": "N", "st": "Sir 13:23", "t": "ετλούσιος ἐλάλησεν καὶ πάντες ἐσίγησαν, καὶ τὸν λόγον αὐτοῦ ἀνύψωσαν ἕως τῶυ νεφελῶν· (29) πτωχὸς ἐλάλησεν καὶ εἶπαν Τίς οὗτος; κἂν προσκόψῃ, προσανατρέψουσιν αὐτόν."}, {"sp": "N", "st": "Sir 13:24", "t": "ἀγαθὸς ὁ πλοῦτος ᾧ μή ἐστιν ἁμαρτία, καὶ πονηρὰ ἡ πτωχεία ἐν στόμασιν εὐσεβοῦς."}, {"sp": "N", "st": "Sir 13:25", "t": "καρδία ἀνθρώπου ἀλλοιοῖ τὸ πρόσωπον αὐτοῦ, ἐὰν εἰς ἀγαθὰ ἐάν τε εἰς κακά."}, {"sp": "N", "st": "Sir 13:26", "t": "ἴχνος καρδίας ἐν ἀγαθοῖς πρόσωπον ἱλαρόν, καὶ εὕρεσις παραβολῶν διαλογισμοὶ μετὰ κόπου."}, {"sp": "N", "st": "Sir 14:1", "t": "Μακάριος ἀνὴρ ὃς οὐκ ὠλίσθησεν ἐν στόματι αὐτοῦ, καὶ οὐ κατενύγη ἐν λύπῃ ἁμαρτίας·"}, {"sp": "N", "st": "Sir 14:2", "t": "μακάριος οὗ οὐ κατέγνω ἡ ψυχὴ αὐτοῦ, καὶ ὃς οὐκ ἔπεσεν ἀπὸ τῆς ἐλπίδος αὐτοῦ."}, {"sp": "N", "st": "Sir 14:3", "t": "ἀνδρὶ μικρολόγῳ οὐ καλὸς ὁ πλοῦτος, καὶ ἀνθρώπῳ βασκάνῳ ἵνα τί χρήματα ;"}, {"sp": "N", "st": "Sir 14:4", "t": "ὁ συνάγων ἀπὸ τῆς ψυχῆς αὐτοῦ συνάγει ἄλλοις, καὶ ἐν τοῖς ἀγαθοῖς αὐτοῦ τρυφήσουσιν ἕτεροι."}, {"sp": "N", "st": "Sir 14:5", "t": "ὁ πονηρὸς ἑαυτῷ τίνι ἀγαθὸς ἔσται; καὶ οὐ μὴ εὐφρανθήσεται ἐν τοῖς χρήμασιν αὐτοῦ."}, {"sp": "N", "st": "Sir 14:6", "t": "τοῦ βασκαίνοντος ἑαυτὸν οὐκ ἔστιν πονηρότερος, καὶ τοῦτο ἀνταπόδομα τῆς κακίας αὐτοῦκἂν"}, {"sp": "N", "st": "Sir 14:7", "t": "εὖ ποιῇ, ἐν λήθῃ ποιεῖ, καὶ ἐπʼ ἐσχάτων ἐκφαίνει τὴν κακίαν αὐτοῦ."}, {"sp": "N", "st": "Sir 14:8", "t": "πονηρὸς ὁ βασκαίνων ὀφθαλμῷ, ἀποστρέφων πρόσαωπον καὶ ὑπερορῶν ψυχάς."}, {"sp": "N", "st": "Sir 14:9", "t": "πλεονέκτου ὀφθαλμὸς οὐκ ἐμπίπλαται μερίδι, καὶ ἀδικία πονηρὰ ἀναξηρανεῖ ψυχήν."}, {"sp": "N", "st": "Sir 14:10", "t": "ὀφθαλμὸς πονηρὸς φθονερὸς ἐπʼ ἄρτῳ, καὶ ἐνλιπὴς ἐπὶ τῆς τραπέζης αὐτοῦ."}, {"sp": "N", "st": "Sir 14:11", "t": "Τέκνον, καθὼς ἐὰν ἔχῃς εὖ ποίει σεαυτόν, καὶ προσφορὰς Κυρίῳ ἀξίως πρόσαγε·"}, {"sp": "N", "st": "Sir 14:12", "t": "μνήσθητι ὅτι θάνατος οὐ χρονιεῖ, καὶ διαθήκη ἅδου οὐχ ὑπεδείχθη σοι·"}, {"sp": "N", "st": "Sir 14:13", "t": "πρίν σε τελευτῆσαι εὖ ποίει φίλῳ, καὶ κατὰ τὴν ἰσχύν σου ἔκτεινον καὶ δὸς αὐτῷ."}, {"sp": "N", "st": "Sir 14:14", "t": "μὴ ἀφυστερήσῃς ἀπὸ ἀγαθῆς ἡμέρας. καὶ μερὶς ἐπιθυμίας ἀγαθῆς μή σε παρελθάτω."}, {"sp": "N", "st": "Sir 14:15", "t": "οὐχὶ ἑτέρῳ καταλείψεις τοὺς πόνους σου, καὶ τοὺς κόπους σου εἰς διαίρεσιν κλήρου;"}, {"sp": "N", "st": "Sir 14:16", "t": "δὸς καὶ λάβε, καὶ ἀπάτησον τὴν ψυχὴν σου, (17)ὅτι οὐκ ἔστιν ἐν ᾅδου ζητῆσαι τρυφήν."}, {"sp": "N", "st": "Sir 14:17", "t": "πᾶσα σὰρξ ὡς ἱμάτιον παλαιοῦται· (12)ἡ γὰρ διαθήκη ἀπʼ αἰῶνος Θανάτῳ ἀποθανῇ."}, {"sp": "N", "st": "Sir 14:18", "t": "ὡς φύλλον θάλλον ἐπὶ δένδρου δασέος, (19)τὰ μὲν καταβάλλει, ἄλλα δὲ φύει· οὕτως γενεὰ σαρκὸς καὶ αἵματος, ἡ μὲν τελευτᾷ, ἑτέρα δέ γεννᾶται."}, {"sp": "N", "st": "Sir 14:19", "t": "τᾶν ἔργον σηπόμενον ἐκλείπει, καὶ ὁ ἐργαζόμενος αὐτὸ μετʼ αὐτοῦ ἀπελεύσεται."}, {"sp": "N", "st": "Sir 14:20", "t": "Μακάριος ἀνὴρ ὃς ἐν σοφίᾳ τελευτήσει, καὶ ὃς ἐν συνέσει αὐτοῦ διαλεχθήσεται·"}, {"sp": "N", "st": "Sir 14:21", "t": "ὁ διανοούμενος τὰς ὁδοὺς αὐτῆς ἐν καρδίᾳ αὐτοῦ. καὶ ἐν τοῖς ἀποκρύφοις αὐτῆς νοηθήσεται."}, {"sp": "N", "st": "Sir 14:22", "t": "ἔξελθε ὀπίσω αὐτῆς ὡς ἰχνευτής, καὶ ἐν ταῖς εἰσόδοις αὐτῆς ἐνέδρευε."}, {"sp": "N", "st": "Sir 14:23", "t": "ὁ παρακύπτων διὰ τῶν θυρίδων αὐτῆς, καὶ ἐπὶ τῶν θυρωμάτων αὐτῆς ἀκροάσεται·"}, {"sp": "N", "st": "Sir 14:24", "t": "ὁ καταλύων σύνεγγυς τοῦ οἴκου αὐτῆς, καὶ πήξει πάσσαλον ἐν τοῖς τοίχοις αὐτῆς·"}, {"sp": "N", "st": "Sir 14:25", "t": "στήσει τὴν σκηνὴν αὐτοῦ κατὰ χεῖρας αὐτῆς, καὶ καταλύσει ἐν καταλύματι ἀγαθῶν·"}, {"sp": "N", "st": "Sir 14:26", "t": "θήσει τὰ τέκνα αὐτοῦ ἐν τῇ σκέπῃ αὐτῆς, καὶ ὑπὸ τοὺς κλάδους αὐτῆς αὐλισθήσεται·"}, {"sp": "N", "st": "Sir 14:27", "t": "σκεπασθήσεται ὑπʼ αὐτῆς ἀπὸ καύματος, καὶ ἐν τῇ δόξῃ αὐτῆς καταλύσει."}, {"sp": "N", "st": "Sir 15:1", "t": "ὁ φοβούμενος Κύριον ποιήσει αὐτό, καὶ ὁ ἐγκρατὴς τοῦ νόμου καταλήμψεται αὐτήν·"}, {"sp": "N", "st": "Sir 15:2", "t": "καὶ ὑπαντήσεται αὐτῷ ὡς μήτηρ, καὶ ὡς γυνὴ παρθενείας προσδέξεται αὐτόν·"}, {"sp": "N", "st": "Sir 15:3", "t": "ψωμιεῖ αὐτὸν ἄρτον συνέσεως, καὶ ὕδωρ σοφίας ποτίσει αὐτόν·"}, {"sp": "N", "st": "Sir 15:4", "t": "στηριχθήσεται ἐπʼ αὐτὴν καὶ οὐ μὴ κλιθῇ, (4)καὶ ἐπʼ αὐτῆς ἐφέξει καὶ οὐ μὴ καταισχυνθῇ·"}, {"sp": "N", "st": "Sir 15:5", "t": "καὶ ὑψώσει αὐτὸν παρὰ τοὺς πλησίον αὐτοῦ, (5)καὶ ἐν μέσῳ ἐκκλησίας ἀνοίξει στόμα αὐτοῦ·"}, {"sp": "N", "st": "Sir 15:6", "t": "εὐφροσύνην καὶ στέφανον ἀγαλλιάματος καὶ ὄνομα αἰώνιον κατακληρονομήσει."}, {"sp": "N", "st": "Sir 15:7", "t": "οὐ μὴ καταλήμψονται αὐτὴν ἄνθρωποι ἀσύνετοι, καὶ ἄνδρες ἁμαρτωλοὶ οὐ μὴ ἴδωσιν αὐτήν·"}, {"sp": "N", "st": "Sir 15:8", "t": "μακράν ἐστιν ὑπερηφανίας, (8)καὶ ἄνδρες ψεῦσται οὐ μὴ μνησθήσονται αὐτῆς."}, {"sp": "N", "st": "Sir 15:9", "t": "Οὐχ ὡραῖος αἶνος ἐν στόματι ἁμαρτωλοῦ, (10)ὅτι οὐ παρὰ Κυρίου ἀπεστάλη·"}, {"sp": "N", "st": "Sir 15:10", "t": "ἐν γὰρ σοφίᾳ ῥηθήσεται αἶνος, καὶ ὁ κύριος εὐοδώσει αὐτόν."}, {"sp": "N", "st": "Sir 15:11", "t": "μὴ εἴπῃς ὅτι Διὰ Κύριον ἀπέστην· ἃ γὰρ ἐμίσησεν, οὐ ποιήσεις."}, {"sp": "N", "st": "Sir 15:12", "t": "μὴ εἴπῃς ὅτι Αὐτός με ἐπλάνησεν· οὐ γὰρ χρείαν ἔχει ἀνδρὸς ἁμαρτωλοῦ."}, {"sp": "N", "st": "Sir 15:13", "t": "πᾶν βδέλυγμα ἐμίσησεν Κύριος. καὶ οὐκ ἔστιν ἀγαπητὸν τοῖς φοβουμένοις αὐτόν."}, {"sp": "N", "st": "Sir 15:14", "t": "αὐτὸς ἐξ ἀρχῆς ἐποίησεν ἄνθρωπον, καὶ ἀφῆκεν αὐτὸν ἐν χειρὶ διαβουλίου αὐτοῦ."}, {"sp": "N", "st": "Sir 15:15", "t": "ἐὰν θέλῃς, συντηρήσεις ἐντολάς, καὶ πίστιν ποίησαι εὐδοκίας."}, {"sp": "N", "st": "Sir 15:16", "t": "παρέθηκέν σοι πῦρ καὶ ὕδαωρ, οὗ ἐὰν θέλῃς ἐκτενεῖς τὴν χεῖρά σου·"}, {"sp": "N", "st": "Sir 15:17", "t": "ἔναντι ἀνθρώπων ἡ ζωὴ καὶ ὁ θάνατος, καὶ ὁ ἐὰν εὐδοκήσῃ δοθήσεται αὐτῷ."}, {"sp": "N", "st": "Sir 15:18", "t": "ὅτι πολλὴ σοφία τοῦ κυρίου· ἰσχυρὸς ἐν δυναστείᾳ καὶ βλέπων τὰ πάντα·"}, {"sp": "N", "st": "Sir 15:19", "t": "καὶ οἱ ὀφθαλμοὶ αὐτοῦ ἐπὶ τοὺς φοβουμένους αὐτόν, καὶ αὐτὸς ἐπιγνώσεται πᾶν ἔργον ἀνθρώπου·"}, {"sp": "N", "st": "Sir 15:20", "t": "καὶ οὐκ ἐνετείλατο οὐδενὶ ἀσεβεῖν, καὶ οὐκ ἔδωκεν ἄνεσιν οὐδενὶ ἁμαρτάνειν."}, {"sp": "N", "st": "Sir 16:1", "t": "Μὴ ἐπιθύμει τέκνων πλῆθος ἀχρήστων, (1)μηδὲ εὐφραίνου ἐπὶ υἱοῖς ἀσεβέσιν·"}, {"sp": "N", "st": "Sir 16:2", "t": "ἐὰν πληθύνωσιν, μὴ εὐφραίνου ἐπʼ αὐτοῖς· εἰ μή ἐστιν φόβος Κυρίου μετʼ αὐτῶν,"}, {"sp": "N", "st": "Sir 16:3", "t": "μὴ ἐνπιστεύσῃς τῇ ζωῇ αὐτῶν, καὶ μὴ ἔπεχε ἐπὶ τὸν τόπον αὐτῶν· (3)κρείσσων γὰρ εἰς ἡ χίλιοι, (4)καὶ ἀποθανεῖν ἄτεκνον ἡ ἔχειν τέκνα ἀσεβθῆ·"}, {"sp": "N", "st": "Sir 16:4", "t": "ἀπὸ γὰρ ἑνὸς συνετοῦ συνοικισθήσεται πόλις, φυλὴ δὲ ἀνόμων ἐρημωθήσεται."}, {"sp": "N", "st": "Sir 16:5", "t": "πολλὰ τοιαῦτα ἑόρακα ἐν ὀφθαλμοῖς μου, καὶ ἵσχυρότερα τούτων ἀκήκοεν τὸ οὗς μου."}, {"sp": "N", "st": "Sir 16:6", "t": "ἐν συναγωγῇ ἁμαρτωλῶν ἐκκαυθήσεται πῦρ, καὶ ἐν ἔθνει ἀπειθεῖ ἐξεκαύθη ὀργή."}, {"sp": "N", "st": "Sir 16:7", "t": "οὐκ ἐξιλάσατο περὶ τῶν ἀρχαίων γιγάντων, οἱ ἀπέστησαν τῇ ἰσχύι αὐτῶν·"}, {"sp": "N", "st": "Sir 16:8", "t": "οὐκ ἐφείσατο περὶ τῆς παροικίας Λώτ, σὓς ἐβδελύξατο διὰ τὴν ὑπερηφανίαν αὐτῶν·"}, {"sp": "N", "st": "Sir 16:9", "t": "οὐκ ἠλέησεν ἔθνος ἀπωλείας, τοὺς ἐξηρμένους ἐν ἁμαρτίαις αὐτῶν·"}, {"sp": "N", "st": "Sir 16:10", "t": "καὶ οὕτως ἑξακοσίας χιλιάδας πεζῶν τοὺς ἐπισυναχθέντας ἐν σκληροκαρδίᾳ αὐτῶν."}, {"sp": "N", "st": "Sir 16:11", "t": "κδν ἦ εἰς σκληροτράχηλος, θαυμαστὸν τοῦτο εἰ ἀθῳωθῇἔλεος (12)γὰρ καὶ ὀργὴ παρʼ αὐτοῦ, δυνάστης ἐξιλασμῶν καὶ ἐκχέων ἀργήν."}, {"sp": "N", "st": "Sir 16:12", "t": "κατὰ τὸ πολὺ ἔλεος αὐτοῦ, οὕτως καὶ πολὺς ὁ ἔλεγχος αὐτοῦ ἄνδρα κατὰ τὰ ἔργα αὐτοῦ κρινεῖ"}, {"sp": "N", "st": "Sir 16:13", "t": "οὐκ ἐκφεύξεται ἐν ἁρπάγμασιν ἁμαρτωλός, καὶ οὐ μὴ καθυστερήσει ὑπομονὴν εὐσεβοῦς."}, {"sp": "N", "st": "Sir 16:14", "t": "πάσῃ ἐλεημοσύνῃ ποιήσει τόπον, ἕκαστος κατὰ τὰ ἔργα αὐτοῦ εὑρήσει."}, {"sp": "N", "st": "Sir 16:17", "t": "μὴ εἶπῃς ὅτι Ἀπὸ Κυρίου κρυβήσομαιμὴ ἐξ ὕψους τις μου μνησθήσεται; (17)ἐν λαῷ πλείονι οὐ μὴ μνησθῶ, τίς γὰρ ἡ μου ἐν ἀμετρήτῳ κτίσει;"}, {"sp": "N", "st": "Sir 16:18", "t": "δοῦ ὁ οὐρανὸς καὶ ὁ οὐρανὸς τοῦ οὐρανοῦ τοῦ θεοῦ, ἄβυσσος καὶ γῆ σαλευθήσονται ἐν τῇ ἐπισκοπῇ αὐτοῦ·"}, {"sp": "N", "st": "Sir 16:19", "t": "ἄμα τὰ ὄρη καὶ τὰ θεμέλια τῆς γῆς ἐν τῷ ἐπιβλέψαι εἰς αὐτὰ τρόμῳ συνσείονται,"}, {"sp": "N", "st": "Sir 16:20", "t": "καὶ 2ἐπʼ αὐτοῖς οὐ διανοηθήσεται καρδία· (²¹)καὶ τὰς ὁδοὺς αὐτοῦ τίς ἐνθυμηθήσεται"}, {"sp": "N", "st": "Sir 16:21", "t": "καὶ καταιγίς, ἣν οὐκ ὄψεται ἄνθρωπος, (22)τὰ δὲ πλείονα τῶν ἔργων αὐτοῦ ἐν ἀποκρύφοις."}, {"sp": "N", "st": "Sir 16:22", "t": "ἔργα δικαιοσύνης τίς ἀναγγελεῖ; ἢ τίς ὑπομενεῖς μακρὰν γὰρ ἡ διαθήκη."}, {"sp": "N", "st": "Sir 16:23", "t": "ἐλαττούμενος καρδίᾳ διανοεῖται ταῦτα, καὶ ἀνὴρ ἄφρων καὶ πλανώμενος διανοεῖται μαωρά."}, {"sp": "N", "st": "Sir 16:24", "t": "ʼAκουσόν μου, τέκνον, καὶ μάθε ἐπιστήμην, καὶ ἐπὶ τῶν λόγων μου πρόσεχε τῇ καρδίᾳ σου·"}, {"sp": "N", "st": "Sir 16:25", "t": "ἐκφαίνω ἐν σταθμῷ παιδείαν, καὶ ἐν ἀκριβείᾳ ἀπαγγέλλω ἐπιστήμην."}, {"sp": "N", "st": "Sir 16:26", "t": "ἐν κρίσει Κυρίου τὰ ἔργα αὐτοῦ ἀπʼ ἀρχῆς, καὶ ἀπὸ ποιήσεως αὐτῶν διέστελλεν μερίδας αὐτῶν·"}, {"sp": "N", "st": "Sir 16:27", "t": "ἐκόσμησεν εἰς αἰῶνα τὰ ἔργα αὐτοῦ, καὶ τὰς ἀρχὰς αὐτῶν εἰς γενεὰς αὐτῶν· τοὕτη ἐπείυασαν οὔτη ἐκοπίασαν, καὶ οὐκ ἐξέλιπον ἀπὸ τῶν ἔργων αὐτῶν·"}, {"sp": "N", "st": "Sir 16:28", "t": "ἕκαστος τὸν πλησίον αὐτοῦ οὐκ ἔθλιψεν, καὶ ἕως αἰῶνος (29)οὐκ ἀπειθήσουσιν τοῦ ῥήματος αὐτοῦ."}, {"sp": "N", "st": "Sir 16:29", "t": "καὶ μετὰ ταῦτα Κύριος εἰς τὴν γῆν ἐπέβλεψεν καὶ ἐνέπλησεν αὐτὴν τῶν ἀγαθῶν αὐτοῦψυχὴν"}, {"sp": "N", "st": "Sir 16:30", "t": "παντὸς ζῴου ἐκάλυψεν τὸ πρόσωπον αὐτῆς, καὶ εἰς αὐτὴν ἡ ἀποστροφὴ αὐτῶν."}, {"sp": "N", "st": "Sir 17:1", "t": "Κύριος ἔκτισεν ἐκ γῆς ἄνθρωπον, aκαὶ πάλιν ἀπέστρεψεν αὐτὸν εἰς αὐτήν·"}, {"sp": "N", "st": "Sir 17:2", "t": "ἡμέρας ἀριθμοῦ καὶ καιρὸν ἔδωκεν αὐτοῖς, καὶ ἔδωκεν αὐτοῖς ἐξουσίαν τῶν ἐπʼ αὐτῆς."}, {"sp": "N", "st": "Sir 17:3", "t": "καθʼ ἑαυτοὺς ἐνέδυσεν αὐτοὺς ἰσχύν, (1b) καὶ κατʼ εἰκόνα αὐτοῦ ἐποίησεν αὐτοὺς·"}, {"sp": "N", "st": "Sir 17:4", "t": "καὶ ἔθηκεν τὸν φόβον αὐτοῦ ἐπὶ πάσης σαρκός. καὶ κατακυριεύειν θηρίων καὶ πετεινῶν."}, {"sp": "N", "st": "Sir 17:6", "t": "διαβούλιον καὶ γλῶσσαν καὶ ὀφθαλμούς, ὦτα καὶ καρδίαν ἔδωκεν διανοεῖσθαι αὐτοῖς·"}, {"sp": "N", "st": "Sir 17:7", "t": "ἐπιστήμην συνέσεως ἐνέπλησεν αὐτούς, καὶ ἀγαθὰ καὶ κακὰ ὑπέδειξεν αὐτοῖς·"}, {"sp": "N", "st": "Sir 17:8", "t": "θηκεν τὸν ὀφθαλμὸν αὐτοῦ ἐπὶ τὰς καρδίας αὐτῶν, δεῖξαι αὐτοῖς τὸ μεγαλεῖον τῶν ἔργων αὐτοῦ·"}, {"sp": "N", "st": "Sir 17:10", "t": "καὶ ὄνομα ἁγιασμοῦ αἰνέσουσιν,"}, {"sp": "N", "st": "Sir 17:9", "t": "ἵνα διηγῶνται τὰ μεγαλεῖα τῶν ἔργων αὐτοῦ."}, {"sp": "N", "st": "Sir 17:11", "t": "προσέθηκεν αὐτοῖς ἐπιστήμην, καὶ νόμον ζωῆς ἐκληροδότησεν αὐτοῖς·"}, {"sp": "N", "st": "Sir 17:12", "t": "¹²διαθήκην αἰῶνος ἔστησεν μετʼ αὐτῶν, καὶ τὰ κρίματα αὐτοῦ ὑπέδειξεν αὐτοῖς·"}, {"sp": "N", "st": "Sir 17:13", "t": "μεγαλεῖν δόξης εἶδον οἱ ὀφθαλμοὶ αὐτῶν, καὶ δόξαν φωνῆς αὐτῶν ἤκουσεν τὸ οὗς αὐτῶν·"}, {"sp": "N", "st": "Sir 17:14", "t": "καὶ εἶπεν αὐτοῖς Προσέχετε ἀπὸ παντὸς ἀδίκου, (¹²)καὶ ἐνετείλατο αὐτοῖς ἑκάστῳ περὶ τοῦ πλησίον."}, {"sp": "N", "st": "Sir 17:15", "t": "αἱ ὁδοὶ αὐτῶν ἐναντίον αὐτοῦ διὰ παντός, οὐ κρυβήσονται ἀπὸ τῶν ὀφθαλμῶν αὐτοῦ."}, {"sp": "N", "st": "Sir 17:17", "t": "ἑκάστῳ ἔθνει κατέστησεν ἡγούμενον, (15)καὶ μερὶς Κυρίου Ἰσραήλ ἐστιν."}, {"sp": "N", "st": "Sir 17:19", "t": "ἅπαντα τὰ ἔργα αὐτῶν ὡς ὁ ἥλιος ἐναντίον αὐτοῦ, καὶ οἱ ὀφθαλμοὶ αὐτοῦ ἐνδελεχεῖς ἐπὶ τὰς ὁδοὺς αὐτῶν·"}, {"sp": "N", "st": "Sir 17:20", "t": "οὐκ ἐκρύβησαν αἱ ἀδικίαι αὐτῶν ἀπʼ αὐτοῦ, καὶ πᾶσαι αἱ ἁμαρτίαι αὐτῶν ἔναντι Κυρίου."}, {"sp": "N", "st": "Sir 17:22", "t": "ἐλεημοσύνη ἀνδρὸς ὡς σφραγὶς μετʼ αὐτοῦ, καὶ χάριν ἀνθρώπου ὡς κόρην συντηρήσει."}, {"sp": "N", "st": "Sir 17:23", "t": "μετὰ ταῦτα ἐξαναστήσεται καὶ ἀνταποδώσει αὐτοῖς, καὶ τὸ ἀνταπόδομα αὐτῶν εἰς κεφαλὴν αὐτῶν ἀποδώσει·"}, {"sp": "N", "st": "Sir 17:24", "t": "πλὴν μετανοοῦσιν ἔδωκεν ἐπάνοδον, καί παρεκάλεσεν ἐκλείποντας ὑπομονήν."}, {"sp": "N", "st": "Sir 17:25", "t": "Ἐπίστρεφε ἐπὶ Κύριον καὶ ἀπόλειπε ἁμαρτίας, (22) δκήθητι κατὰ πρόσαωπον καὶ σμίκρυνον πρόσκομμα·"}, {"sp": "N", "st": "Sir 17:26", "t": "ἐπάναγε ἐπὶ Ὕψιστον καὶ ἀπόστρεφε ἀπὸ ἀδικίας, καὶ σφόδρα μίσησον βδέλυγμα."}, {"sp": "N", "st": "Sir 17:27", "t": "Ὑψίστῳ τίς αἰνέσει ἐν ἅδου (25) ἀντὶ ζώντων καὶ διδόντων ἀνθομολόγησι"}, {"sp": "N", "st": "Sir 17:28", "t": "ἀπὸ νεκροῦ ὡς μηδὲ ὄντος ἀπόλλυται ἐξομολόγησις· (27)ζῶν καὶ ὑγιὴς αἰνέσει τὸν κύριον."}, {"sp": "N", "st": "Sir 17:29", "t": "ὡς μεγάλη ἡ ἐλεημοσύνη τοῦ κυρίου, καὶ ἐξιλασμὸς τοῖς ἐπιστρέφουσιν ἐπʼ αὐτόν."}, {"sp": "N", "st": "Sir 17:30", "t": "οὐ γὰρ δύναται πάντα εἶναι ἐν ἀνθρώποις, ὅτι οὐκ ἀθάνατος υἱὸς ἀνθρώπου."}, {"sp": "N", "st": "Sir 17:31", "t": "τί φωτεινότερον ἡλίου; καὶ τοῦτο ἐκλείπει, καὶ πονηρὸς ἐνθυμήσεται σάρκα καὶ αἵμα."}, {"sp": "N", "st": "Sir 17:32", "t": "δύναμιν ὕψους οὐρανοῦ αὐτὸς ἐπισκέπτεται, καὶ οἱ ἄνθρωποι πάντες γῆ καὶ σποδός."}, {"sp": "N", "st": "Sir 18:1", "t": "Ὁ ζῶν εἰς τὸν αἰῶνα ἔκτισεν τὰ πάντα κοινῇ·"}, {"sp": "N", "st": "Sir 18:2", "t": "Κύριος μόνος δικαιωθήσεται."}, {"sp": "N", "st": "Sir 18:4", "t": "οὐθενὶ ἐξεποίησεν ἐξαγγεῖλαι τὰ ἔργα αὐτοῦκαὶ (³)τίς ἐξιχνιάσει τὰ μεγαλεῖα αὐτοῦ;"}, {"sp": "N", "st": "Sir 18:5", "t": "κράτος μεγαλωσύνης αὐτοῦ τίς ἐξαριθμήσεται; καὶ τίς προσθήσει ἐκδιηγήσασθαι τὰ ἐλέη αὐτοῦ"}, {"sp": "N", "st": "Sir 18:6", "t": "οὐκ ἔστιν ἐλαττῶσαι οὐδὲ προσθεῖναι, καὶ οὐκ ἔστιν ἐξιχνιάσαι τὰ θαυμάσια τοῦ κυρίου·"}, {"sp": "N", "st": "Sir 18:7", "t": "ὅταν συντελέσῃ ἄνθρωπος τότε ἄρχεται, καὶ ὅταν παύσηται τότε ἀπορηθήσεται."}, {"sp": "N", "st": "Sir 18:8", "t": "τί ἄνθρωπος καὶ τί ἡ χρῆσις αὐτοῦ; τί τὸ ἀγαθὸν αὐτοῦ, καὶ τί τὸ κακὸν αὐτοῦ;"}, {"sp": "N", "st": "Sir 18:9", "t": "ἀριθμὸς ἡμερῶν ἀνθρώπου πολλὰ ἔτη ἑκατόν·"}, {"sp": "N", "st": "Sir 18:10", "t": "ὡς σταγὼν ὕδατος ἀπὸ θαλάσσης καὶ ψῆφος ἄμμου. οὕτως ὀλίγα ἔτη ἐν ἡμέρᾳ αἰῶνος."}, {"sp": "N", "st": "Sir 18:11", "t": "διὰ τοῦτο ἐμακροθύμησεν Κύριος ἐπʼ αὐτοῖς. καὶ ἐξέχεεν ἐπʼ αὐτοὺς τὸ ἔλεος αὐτοῦ·"}, {"sp": "N", "st": "Sir 18:12", "t": "ἴδεν καὶ ἐπέγνω τὴν καταστροφὴν αὐτῶν ὅτι πονηρά, (¹¹)διὰ τοῦτο ἐπλήθυνεν τὸν ἐξιλασμὸν αὐτοῦ."}, {"sp": "N", "st": "Sir 18:13", "t": "ἔλεος ἀνθρώπου ἐπὶ τὸν πλησίον αὐτοῦ, ἔλεος δέ Κυρίου ἐπὶ πᾶσαν σάρκα· (¹³) ἐλέγχων καὶ παιδεύων καὶ διδάσκων καὶ ἐπιστρέφων ὡς ποιμὴν τὸ ποίμνιον αὐτοῦ."}, {"sp": "N", "st": "Sir 18:14", "t": "τοὺς ἐκδεχομένους παιδείαν ἐλεῷ, καὶ τοὺς κατασπεύδοντας ἐπὶ τὰ κρίματα αὐτοῦ."}, {"sp": "N", "st": "Sir 18:15", "t": "Τέκνον, ἐν ἀγαθοῖς μὴ δῷς μῶμον. καὶ ἐν πάσῃ δόσει λύπην λόγων."}, {"sp": "N", "st": "Sir 18:16", "t": "οὐχὶ καύσαωνα ἀναπαύσει δρόσος; οὕτως κρείσσων λόγος ἣ δόσις,"}, {"sp": "N", "st": "Sir 18:17", "t": "οὐκ ἰδοὺ λόγος ὑπέρ δόμα ἀγαθόν; καὶ ἀμφότερα παρὰ ἀνδρὶ κεχαριτωμένῳ."}, {"sp": "N", "st": "Sir 18:18", "t": "μωρὸς ἀχαρίστως ὀνειδιεῖ, καὶ δόσις βασκάνου ἐκτήκει ὀφθαλμούς."}, {"sp": "N", "st": "Sir 18:19", "t": "πρὶν ἢ λαλῆσαι μάνθανε, καὶ πρὸ ἀρρωστείας θεραπεύου·"}, {"sp": "N", "st": "Sir 18:20", "t": "πρὸ κρίσεως ἐξέταζε σεαυτόν, καὶ ἐν ὥρᾳ ἐπισκοπῆς εὑρήσεις ἐξιλασμόν·"}, {"sp": "N", "st": "Sir 18:21", "t": "πρὶν ἀρρωστῆσαί σε ταπεινώθητι, καὶ ἐν καιρῷ ἁμαρτημάτων δεῖξον ἐπιστροφήν."}, {"sp": "N", "st": "Sir 18:22", "t": "μὴ ἐμποδισθῇς τοῦ ἀποδοῦναι εὐχὴν εὐκαίρως, καὶ μὴ μείνῃς ἕως θανάτου δικαιωθῆναι·"}, {"sp": "N", "st": "Sir 18:23", "t": "πρὶν εὔξασθαι ἑτοίμασον σεαυτόν, καὶ μὴ γίνου ὡς ἄνθρωπος πειράζων τὸν κύριον."}, {"sp": "N", "st": "Sir 18:24", "t": "μνήσθητι θυμοῦ ἐν ἡμέραις τελευτῆς, καὶ καιρὸν ἐκδικήσεως ἐν ἀποστροφῇ προσώπου."}, {"sp": "N", "st": "Sir 18:25", "t": "μνήσθητι καιρὸν λιμοῦ ἐν καιρῷ πλησμονῆς, πτωχείαν καὶ ἔνδειαν ἐν ἡμέραις πλούτου."}, {"sp": "N", "st": "Sir 18:26", "t": "ἀπὸ πρωίθεν ἕως ἑσπέρας μεταβάλλει καιρός. καὶ πάντα ἐστὶν ταχινὰ ἔναντι Κυρίου."}, {"sp": "N", "st": "Sir 18:27", "t": "ἄνθρωπος σοφὸς ἐν παντὶ εὐλαβηθήσεται, καὶ ἐν ἡμέραις ἁμαρτιῶν προσέξει ἀπὸ πλημμελίας."}, {"sp": "N", "st": "Sir 18:28", "t": "πᾶς συνετὸς ἔγνω σοφίαν, καὶ τῷ εὑρόντι αὐτὴν δώσει ἐξομολόγησιν."}, {"sp": "N", "st": "Sir 18:29", "t": "συνετοὶ ἐν λόγοις καὶ αὐτοὶ ἐσοφίσαντο, καὶ ἀνώμβρησαν παροιμίας ἀκριβεῖς. Ἐγκράτεια ψυχῆς."}, {"sp": "N", "st": "Sir 18:30", "t": "Ὀπίσω τῶν ἐπιθυμιῶν σου μὴ πορεύου, καὶ ἀπὸ τῶν ὀρέξεων σου κωλύου·"}, {"sp": "N", "st": "Sir 18:31", "t": "ἐὰν χορηγήσεις τῇ ψυχῇ σου εὐδοκίαν ἐπιθυμίας, ποιήσει σε ἐπίχαρμα τῶν ἐχθρῶν σου."}, {"sp": "N", "st": "Sir 18:32", "t": "μὴ εὐφραίνου ἐπὶ πολλῇ τρυφῇ. μὴ προσδεθῇς συμβολῇ αὐτῆς·"}, {"sp": "N", "st": "Sir 18:33", "t": "μὴ γίνου πτωχὸς συμβολοκοπῶν ἐκ δανισμοῦ, καὶ οὐδέν σοί ἐστιν ἐν μαρσιππίῳ."}, {"sp": "N", "st": "Sir 19:1", "t": "ἐργάτης μέθυσος οὐ πλουτισθήσεται· ὁ ἐξουθενῶν τὰ ὀλίγα κατὰ μικρὸν πεσεῖται."}, {"sp": "N", "st": "Sir 19:2", "t": "οἶνος καὶ γυναῖκες ἀποστήσουσιν συνετούς, καὶ ὁ κολλώμενος πόρναις τολμηρότερος ἔσται·"}, {"sp": "N", "st": "Sir 19:3", "t": "σήπη καὶ σκώληκες κληρονομήσουσιν αὐτόν, καὶ ψυχὴ τολμηρὰ ἐξαρθήσεται."}, {"sp": "N", "st": "Sir 19:4", "t": "ὁ ταχὺ ἐνπιστεύων κοῦφος καρδίᾳ, καὶ ὁ ἁμαρτάνων εἰς ψυχὴν αὐτοῦ πλημμελήσει."}, {"sp": "N", "st": "Sir 19:5", "t": "ὁ εὐφραινόμενος καρδίᾳ καταγναωσθήσεται,"}, {"sp": "N", "st": "Sir 19:6", "t": "καὶ ὁ μισῶν λαλιὰν ἐλαττονοῦται κακίᾳ."}, {"sp": "N", "st": "Sir 19:7", "t": "μηδέποτε δευτερώσῃς λόγον, καὶ οὐθέν σοι οὐ μὴ ἐλαττονωθῇ."}, {"sp": "N", "st": "Sir 19:8", "t": "ἐν φἰλῳ καὶ ἐν ἐχθρῷ μὴ διηγοῦ, καὶ εἰ μή ἐστίν σοι ἁμαρτία, μὴ ἀποκάλυπτε·"}, {"sp": "N", "st": "Sir 19:9", "t": "ἀκήκοεν γάρ σου καὶ ἐφυλάξατό σε, καὶ ἐν καιρῷ μισήσει σε."}, {"sp": "N", "st": "Sir 19:10", "t": "ἀκήκοας λόγον ; συναποθανέτω σοι· θάρσει, οὐ μή σε ῥήξει."}, {"sp": "N", "st": "Sir 19:11", "t": "ἀπὸ προσώπου λόγου ὠδινήσει μαωρός, ὡς ἀπὸ προσώπου βρέφους ἡ τίκτουσα."}, {"sp": "N", "st": "Sir 19:12", "t": "βέλος πεπηγὸς ἐν μηρῷ σαρκός, οὕτως λόγος ἐν κοιλίᾳ μωροῦ."}, {"sp": "N", "st": "Sir 19:13", "t": "Ἔλεγξον φίλον, μή ποτε οὐκ ἐποίησεν, καὶ εἴ τι ἐποίησεν, μή ποτε προσθῇ."}, {"sp": "N", "st": "Sir 19:14", "t": "ἔλεγξον τὸν φίλον, μὴ ποτε οὐκ εἶπεν· καὶ εἰ εἴρηκεν, ἵνα μὴ δευτερώσῃ."}, {"sp": "N", "st": "Sir 19:15", "t": "ἔλεγξον φίλον, πολλάκις γὰρ γίνεται διαβολή, (¹⁶)καὶ μὴ παντὶ λόγῳ πίστευε."}, {"sp": "N", "st": "Sir 19:16", "t": "ἔστιν ὀλισθάνων καὶ οὐκ ἀπὸ ψυχῆς, (17)καὶ τίς οὐχ ἥμαρτεν ἐν τῇ γλώσσῃ αὐτοῦ;"}, {"sp": "N", "st": "Sir 19:17", "t": "ἔλεγξον τὸν πλησίον σου πρὶν ἢ ἀπειλῆσαι, (18)καὶ δὸς τόπον νόμῳ Ὑψίστου."}, {"sp": "N", "st": "Sir 19:20", "t": "Πᾶσα σοφία φόβος Κυρίου, καὶ ἐν πάσῃ σοφίᾳ ποίησις νόμου."}, {"sp": "N", "st": "Sir 19:22", "t": "καὶ οὐκ ἔστιν σοφία πονηρίας ἐπιστήμη, καὶ οὐκ ἔστιν ὅπου βουλὴ ἁμαρτωλῶν φρόνησις."}, {"sp": "N", "st": "Sir 19:23", "t": "ἔστιν πονηρία καὶ αὕτη βδέλυγμα, καὶ ἔστιν ἄφρων ἐλαττούμενος σοφίᾳ."}, {"sp": "N", "st": "Sir 19:24", "t": "κρείττων ἡττώμενος ἐν συνέσει ἔμφοβος ἢ περισσεύων ἐν φρονήσει καὶ παραβαίνων νόμον."}, {"sp": "N", "st": "Sir 19:25", "t": "ἔστιν πανουργία ἀκριβὴς καὶ αὕτη ἄδικος, καὶ ἔστιν διαστρέφων χάριν τοῦ ἐκφᾶναι κρίμα."}, {"sp": "N", "st": "Sir 19:26", "t": "ἔστιν πονηρευόμενος συνκεκυφὼς μελανίᾳ, καὶ τὰ ἐντὸς αὐτοῦ πλήρης δόλου·"}, {"sp": "N", "st": "Sir 19:27", "t": "συνκύφων πρόσωπον καὶ ἑτεροκαωφῶν, ὅπου οὐκ ἐπεγνώσθη προφθάσει σε·"}, {"sp": "N", "st": "Sir 19:28", "t": "καὶ ἐὰν ὑπὸ ἐλαττώματος ἰσχύος κωλυθῇ ἁμαρτεῖν, ἐὰν εὕρῃ καιρὸν κακοποιήσει."}, {"sp": "N", "st": "Sir 19:29", "t": "ἀπὸ ὁράσεως ἐπιγνωσθήσεται ἀνήρ, καὶ ἀπὸ ἀπαντήσεως προσώπου ἐπιγνωσθήσεται νοήμων·"}, {"sp": "N", "st": "Sir 19:30", "t": "στολισμὸς ἀνδρὸς καὶ γέλως ὀδόντων καὶ βήματα ἀνθρώπου ἀναγγέλλει τὰ περὶ αὐτοῦ."}, {"sp": "N", "st": "Sir 20:1", "t": "ἔστιν ἔλεγχος ὁς οὐκ ἔστιν ὡραῖος, καὶ ἔστιν σιωπῶν καὶ αὐτὸς φρόνιμος."}, {"sp": "N", "st": "Sir 20:2", "t": "Ὡς καλὸν ἐλέγξαι ἢ θυμοῦσθαι, καὶ ὁ ἀνθομολογούμενος ἀπὸ ἐλαττώσεως κωλυθήσεται."}, {"sp": "N", "st": "Sir 20:4", "t": "ἐπιθυμία εὐνούχου ἀποπαρθενῶσαι νεάνιδα, οὕτως ὁ ποιῶν ἐν βίᾳ κρίματα."}, {"sp": "N", "st": "Sir 20:5", "t": "ἔστιν σιωπῶν εὑρισκομενος σοφός, καὶ ἔστιν μισητὸς ἀπὸ πολλῆς λαλιᾶς."}, {"sp": "N", "st": "Sir 20:6", "t": "ἔστιν σιωπῶν, οὐ γὰρ ἔχει ἀπόκρισιν, καὶ ἔστιν σιωπῶν, εἰδὼς καιρόν."}, {"sp": "N", "st": "Sir 20:7", "t": "ἄνθρωπος σοφὸς σιγήσει ἕως καιροῖ, ὁ δὲ λαπιστὴς καὶ ἄφρων ὑπερβήσεται καιρόν."}, {"sp": "N", "st": "Sir 20:8", "t": "ὁ πλεονάζων λόγῳ βδελυχθήσεται, καὶ ὁ ἐνεξουσιαζόμενος μισηθήσεται."}, {"sp": "N", "st": "Sir 20:9", "t": "Ἔστιν εὐοδία ἐν κακοῖς ἀνδρί, καὶ ἔστιν εὕρεμα εἰς ἐλάττωσιν."}, {"sp": "N", "st": "Sir 20:10", "t": "ἔστιν δόσις ἣ οὐ λυσιτελήσει σοι, καὶ ἔστιν δόσις ἧς τὸ ἀνταπόδομα διπλοῦν."}, {"sp": "N", "st": "Sir 20:11", "t": "ἔστιν ἐλάττωσις ἕνεκεν δόξης, καὶ ἔστιυ ὃς ἀπὸ ταπεινώσεως ἦρεν κεφαλήν."}, {"sp": "N", "st": "Sir 20:12", "t": "ἔστιν ἀγοράζων πολλὰ ὀλίγου καὶ ἀποτιννύων αὐτὰ ἑπταπλάσιον."}, {"sp": "N", "st": "Sir 20:13", "t": "ὁ σοφὸς ἐν λόγῳ ἑαυτὸν προσφιλῆ ποιήσει. χάριτες δὲ μωρῶν ἐκχυθήσονται."}, {"sp": "N", "st": "Sir 20:14", "t": "δόσις ἄφρονος οὐ λυσιτελήσει σοι, οἱ γὰρ ὀφθαλμοὶ αὐτοῦ ἀνθʼ ἑνὸς πολλοί"}, {"sp": "N", "st": "Sir 20:15", "t": "ὀλίγα δώσει καὶ πολλὰ ὀνειδίσει, καὶ ἀνοίξει τὸ στόμα αὐτοῦ ὡς κήρυξ· (16)σήμερον δανιεῖ καὶ αὔριον ἀπαιτήσει, μισητὸς ἄνθρωπος ὁ τοιοῦτος."}, {"sp": "N", "st": "Sir 20:16", "t": "μωρὸς ἐρεῖ Οὐχ ὑπάρχει μοι φίλος, καὶ οὐκ ἔστιν χάρις τοῖς ἀγαθοῖς μου· (18)οἱ ἔσθοντες τὸν ἄρτον μου φαῦλοι γλώσσῃ."}, {"sp": "N", "st": "Sir 20:17", "t": "ποσάκις καὶ ὅσοι καταγελάσονται αὐτοῦ ;"}, {"sp": "N", "st": "Sir 20:18", "t": "Ὀλίσθημα ἀπὸ ἐδάφους μᾶλλον ἢ ἀπὸ γλώσσης. οὕτως πτῶσις κακῶν κατὰ σπουδὴν ἥξει."}, {"sp": "N", "st": "Sir 20:19", "t": "ἄνθρωπος ἄχαρις, μῦθος ἄκαιρος· ἐν στόματι ἀπαιδεύτων ἐνδελεχισθήσεται."}, {"sp": "N", "st": "Sir 20:20", "t": "ἀπὸ στόματος μωροῦ ἀποδοκιμασθήσεται παραβολή, οὐ γὰρ μὴ εἴπῃ αὐτὴν ἐν καιρῷ αὐτῆς."}, {"sp": "N", "st": "Sir 20:21", "t": "ἔστιν κωλυόμενος ἁμαρτάνειν ἀπὸ ἐνδείας, καὶ ἐν τῇ ἀναπαύσει αὐτοῦ οὐ κατανυγήσεται."}, {"sp": "N", "st": "Sir 20:22", "t": "ἔστιν ἀπολλύων τὴν ψυχὴν αὐτοῦ δι᾿ αἰσχύνην, καὶ ἀπὸ ἄφρονος προσώπου ἀπολεῖ αὐτὴν."}, {"sp": "N", "st": "Sir 20:23", "t": "ἔστιν χάριν αἰσχύνης ἐπαγγελλόμενος φίλῳ, καὶ ἐκτήσατο αὐτὸν ἐχθρὸν δωρεάν."}, {"sp": "N", "st": "Sir 20:24", "t": "μῶμος πονηρὸς ἐν ἀνθρώπῳ ψεῦδος, ἐν στόματι ἀπαιδεύτων ἐνδελεχισθήσεται."}, {"sp": "N", "st": "Sir 20:25", "t": "αἱρετὸν κλέπτης ἢ ἐνδελεχίζων ψεύδει, ἀμφότεροι δὲ ἀπωλίαν κληρονομήσουσιν."}, {"sp": "N", "st": "Sir 20:26", "t": "ἦθος ἀνθρώπου ψευδοῦς ἀτιμία, καὶ ἡ αἰσχύνη αὐτοῦ μετʼ αὐτοῦ ἐνδελεχῶς Λόγοι παραβολῶν."}, {"sp": "N", "st": "Sir 20:27", "t": "Ὁ σοφὸς ἐν λόγοις προάξει ἑαυτόν, καὶ ἄνθρωπος φρόνιμος ἀρέσει μεγιστᾶσιν·"}, {"sp": "N", "st": "Sir 20:28", "t": "ὁ ἐργαζόμενος γῆν ἀνυψώσει θιμωνιὰν αὐτοῦ, καὶ ὁ ἀρέσκων μεγιστᾶσιν ἐξιλάσεται ἀδίκαν."}, {"sp": "N", "st": "Sir 20:29", "t": "ξένια καὶ δῶρα ἀποτυφλοῖ ὀφθαλμοὺς σοφῶν, καὶ ὡς φιμὸς ἐν στόματι ἀποτρέπει ἐλεγμούς."}, {"sp": "N", "st": "Sir 20:30", "t": "σοφία κεκρυμμένη καὶ θησαυρὸς ἀφανής, τίς ὠφέλεια ἐν ἀμφοτέροις;"}, {"sp": "N", "st": "Sir 20:31", "t": "κρείσσων ἄνθρωπος ἀποκρύπτων τὴν μαωρίαν αὐτοῦ ἢ ἄνθρωπος ἀποκρύπτων τὴν σοφίαν αὐτοῦ."}, {"sp": "N", "st": "Sir 21:1", "t": "Τέκνον, ἥμαρτες μὴ προσθῇς μηκέτι, καὶ περὶ τῶν προτέρων σου δεήθητι."}, {"sp": "N", "st": "Sir 21:2", "t": "ὡς ἀπὸ προσώπου ὄφεως φεῦγε ἀπὸ ἁμαρτίας· ἐὰν γὰρ προσέλθῃς, δήξεταί σε· (3)ὀδόντες λέοντος οἱ ὀδόντες αὐτῆς, ἀναιροῦντες ψυχὰς ἀνθρώπων."}, {"sp": "N", "st": "Sir 21:3", "t": "ὡς ῥομφαία δίστομος πᾶσα ἀνομία, τῇ πληγῇ αὐτῆς οὐκ ἔστιν ἴασις."}, {"sp": "N", "st": "Sir 21:4", "t": "καταπληγμὸς καὶ ὕβρις ἐρημώσουσιν πλοῦτον, οὕτως οἶκος ὑπερηφάνου ἐρημωθήσεται."}, {"sp": "N", "st": "Sir 21:5", "t": "δέησις πτωχοῦ ἐκ στόματος ἕως ὠτίων αὐτοῦ, καὶ τὸ κρίμα αὐτοῦ κατὰ σπουδὴν ἔρχεται."}, {"sp": "N", "st": "Sir 21:6", "t": "μισῶν ἐλεγμὸν ἐν ἴχνει ἁμαρτωλοῦ, καὶ ὁ φοβούμενος Κύριον ἐπιστρέψει ἐν καρδίᾳ."}, {"sp": "N", "st": "Sir 21:7", "t": "γνωστὸς μακρόθεν ὁ δυνατὸς ἐν γλώσσῃ, ὁ δὲ νοήμων οἶδεν ἐν τῷ ὀλισθάνειν αὐτόν."}, {"sp": "N", "st": "Sir 21:8", "t": "ὁ οἰκοδομῶν τὴν οἰκίαν αὐτοῦ ἐν χρήμασιν ἀλλοτρίοις ὡς συνάγων αὐτοῦ τοὺς λίθους εἰς χειμῶνα."}, {"sp": "N", "st": "Sir 21:9", "t": "στιππύον συνηγμένον συναγααωγὴ ἀνόμων, καὶ ἡ συντέλεια αὐτῶν φλὸξ πυρός."}, {"sp": "N", "st": "Sir 21:10", "t": "ὁδὸς ἁμαρτωλῶν ὡμαλισμένη ἐκ λίθων, καὶ ἐπʼ ἐσχάτῳ αὐτῆς βόθρος ᾅδου."}, {"sp": "N", "st": "Sir 21:11", "t": "ὁ φυλάσσων νόμον κατακρατεῖ τοῦ ἐννοήματος αὐτοῦ, (13)καὶ συντέλεια τοῦ φόβου Κυρίου σοφία."}, {"sp": "N", "st": "Sir 21:12", "t": "12οὐ παιδευθήσεται ὃς οὐκ ἔστιν πανοῦργος· (15)ἔστιν πανουργία πληθύνουσα πικρίαν."}, {"sp": "N", "st": "Sir 21:13", "t": "γνῶσις σοφοῦ ὡς κατακλυσμὸς πληθυνθήσεται, καὶ ἡ βουλὴ αὐτοῦ ὡς πηγὴ ζωῆς."}, {"sp": "N", "st": "Sir 21:14", "t": "ἔγκατα μωροῦ ὡς ἅγγιον συντετριμμένον, καὶ πᾶσαν γνῶσιν οὐ κρατήσει."}, {"sp": "N", "st": "Sir 21:15", "t": "λόγον σοφὸν ἐὰν ἀκούσῃ ἐπιστήμων, αἰνέσει αὐτὸν καὶ ἐπʼ αὐτὸν προσθήσει· ἤκουσεν ὁ σπαταλῶν καὶ ἀπήρεσεν αὐτῷ, καὶ ἀπέστρεψεν αὐτὸν ὀπίσω τοῦ νώτου αὐτοῦ."}, {"sp": "N", "st": "Sir 21:16", "t": "ἐξήγησις μωροῦ ὡς ἐν ὁδῷ φορτίον, ἐπὶ δὲ χείλους συνετοῦ εὑρεθήσεται χάρις."}, {"sp": "N", "st": "Sir 21:17", "t": "στόμα φρονίμου ζητηθήσεται ἐν ἐκκλησίᾳ. καὶ τοὺς λόγους αὐτοῦ διανοηθήσεται ἐν καρδίᾳ."}, {"sp": "N", "st": "Sir 21:18", "t": "ὡς οἶκος ἠφανισμένος οὕτως μωρῷ σοφία, καὶ γνῶσις ἀσυνέτου ἀδιεξέταστοι λόγοι."}, {"sp": "N", "st": "Sir 21:19", "t": "πέδαι ἐν ποσὶν ἀνοήτοις παιδεία, καὶ ὡς χειροπέδαι ἐπὶ χειρὸς δεξιᾶς."}, {"sp": "N", "st": "Sir 21:20", "t": "μωρὸς ἐν γέλωτι ἀνυψοῖ φωνὴν αὐτοῦ, ἀνὴρ δὲ πανοῦργος μόλις ἡσυχῇ μειδιάσει."}, {"sp": "N", "st": "Sir 21:21", "t": "ὡς κόσμος χρυσοῦς φρονίμῳ παιδεία, καὶ ὡς χλιδὼν ἐπὶ βραχίονι δεξιῷ."}, {"sp": "N", "st": "Sir 21:22", "t": "ποὺς μωροῦ ταχὺς εἰς οἰκίαν, ἄνθρωπος δὲ πολύπειρος αἰσχυνθήσεται ἀπὸ προσώἄφρων"}, {"sp": "N", "st": "Sir 21:23", "t": "ἀπὸ θύρας παρακύπτει εἰς οἰκίαν, ἀνήρ δὲ πεπαιδευμένος ἔξω στήσεται."}, {"sp": "N", "st": "Sir 21:24", "t": "ἀπαιδευσία ἀνθρώπου ἀκροᾶσθαι παρὰ θύραν, ὁ δὲ φρόνιμος βαρυνθήσεται ἀτιμίᾳ."}, {"sp": "N", "st": "Sir 21:25", "t": "χείλη ἀλλοτρίων ἐν τούτοις βαρυνθήσεται, λόγοι δὲ φρονίμων ἐν ζυγῷ σταθήσονται."}, {"sp": "N", "st": "Sir 21:26", "t": "ἐν στόματι μωρῶν ἡ καρδία αὐτῶν, καρδία δὲ σοφῶν στόμα αὐτῶν."}, {"sp": "N", "st": "Sir 21:27", "t": "ἐν τῷ καταρᾶσθαι ἀσεβῆ τὸν σατανᾶν αὐτὸς καταρᾶται τὴν ἑαυτοῦ ψυχήν."}, {"sp": "N", "st": "Sir 21:28", "t": "μολύνει τὴν ἑαυτοῦ ψυχὴν ὁ ψιθυρίζων. καὶ ἐν παροικήσει μισηθήσεται."}, {"sp": "N", "st": "Sir 22:1", "t": "Λίθῳ ἠρδαλωμένῳ συνεβλήθη ὀκνηρός. καὶ πᾶς ἐκσυριεῖ ἐπὶ τῇ ἀτιμίᾳ αὐτοῦ."}, {"sp": "N", "st": "Sir 22:2", "t": "βολβίτῳ κοπρίων συνεβλήθη ὀκνηρός. πᾶς ὁ ἀναιρούμενος αὐτὸν ἐκτινάξει χεῖρα."}, {"sp": "N", "st": "Sir 22:3", "t": "αἰσχύνη πατρὸς ἐν γεννήσει ἀπαιδεύτου, θυγάτηρ δὲ ἐπʼ ἐλαττώσει γίνεται."}, {"sp": "N", "st": "Sir 22:4", "t": "θυγάτηρ φρονίμη κληρονομήσει ἄνδρα αὐτῆς, καὶ ἡ καταισχύνουσα εἰς λύπην γεννήσαντος·"}, {"sp": "N", "st": "Sir 22:5", "t": "πατέρα καὶ ἄνδρα καταισχύνει ἡ θρασεῖα, καὶ ὑπὸ ἀμφοτέρων ἀτιμασθήσεται."}, {"sp": "N", "st": "Sir 22:6", "t": "μουσικὰ ἐν πένθει ἄκαιρος διήγησις. μάστιγες καὶ παιδεία ἐν παντὶ καιρῷ σοφίας."}, {"sp": "N", "st": "Sir 22:7", "t": "συνκολλῶν ὄστρακον ὁ διδάσκων μαορόν, (8)ἐξεγείρων καθεύδοντα ἐκ βαθέος ὕπνου·"}, {"sp": "N", "st": "Sir 22:8", "t": "διηγούμενος νυστάζοντι ὁ διηγούμενος μωράῷ. καὶ ἐπὶ συντελείᾳ ἐρεῖ Τί ἐστιν"}, {"sp": "N", "st": "Sir 22:11", "t": "ἐπὶ νεκρῷ κλαῦσον, ἐξέλιπεν γὰρ φῶς· καὶ ἐπὶ μωρῷ κλαῦσον, ἐξέλιπεν γὰρ σύνεσιν· (11)ἥδιον κλαῦσον ἐπὶ νεκρῷ, ὅτι ἀνεπαύσατο, (12)τοῦ δέ μωροῦ ὑπέρ θάνατον ἡ ζωὴ πονηρά."}, {"sp": "N", "st": "Sir 22:12", "t": "¹²πένθος νεκροῦ ἑπτὰ ἡμέραι, μωροῦ δὲ καὶ ἀσεβοῦς πᾶσαι αἱ ἡμέραι τῆς ζωῆς αὐτοῦ."}, {"sp": "N", "st": "Sir 22:13", "t": "μετὰ ἄφρονος μὴ πληθύνῃς λόγον, καὶ πρὸς ἀσύνετον μὴ πορεύου· (15)φλύλαξαι ἀπʼ αὐτοῦ, ἴνα μὴ κόπον ἔχης καὶ οὐ μὴ μολυνθῇς ἐν τῷ ἐντιναγμῷ αὐτοῦ· (16)ἔκκλινον ἀπʼ αὐτοῦ καὶ εὑρήσεις ἀνάπαυσιν, καὶ οὐ μὴ ἀκηδιάσῃς ἐν τῇ ἀπονοίᾳ αὐτοῦ."}, {"sp": "N", "st": "Sir 22:14", "t": "ὑπέρ μόλβον τί βαρυνθήσεται; καὶ τί αὐτῷ ὄνομα ἀλλ᾿ ἦ μωρός"}, {"sp": "N", "st": "Sir 22:15", "t": "ἄμμον καὶ ἄλα καὶ βῶλον σιδήρου εὔκόπου ὑπενεγκεῖν ἡ ἄνθραωπον ἀσύνετον."}, {"sp": "N", "st": "Sir 22:16", "t": "ἱμάντωσις ξυλίνη ἐνδεδεμένη εἰς οἰκοδομὴν ἐν συσσεισμῷ οὐ διαλυθήσεται, οὕτως καρδία ἐστηριγμένη ἐπὶ διανοήματος βουλῆς (20)ἐν καιρῷ οὐ δειλιάσει."}, {"sp": "N", "st": "Sir 22:17", "t": "καρδία ἡδρασμένη ἐπὶ διανοίας συνέσεως ὡς κόσμος ψαμμωτὸς τοίχου ξυστοῦ."}, {"sp": "N", "st": "Sir 22:18", "t": "χάρακες ἐπὶ μετεάρου κείμενοι κατέναντι ἀνέμου οὐ μὴ ὑπομείναωσιν· ,23) οὕτως καρδία δειλὴ ἐπὶ διανοήματος μωροί κατέναντι παντὸς φόβου οὐ μὴ ὑπομείνῃ."}, {"sp": "N", "st": "Sir 22:19", "t": "ὁ νύσσων ὀφθαλμὸν κατάξει δάκρυα, καὶ νύσσων καρδίαν ἐκφαίνει αἴσθησιν."}, {"sp": "N", "st": "Sir 22:20", "t": "ξΝάλλων λίθον ἐπὶ πετεινὰ ἀποσοβεῖ αὐτά, καὶ ὁ ὀνειδίζων φίλον διαλύσει φιλίαν."}, {"sp": "N", "st": "Sir 22:21", "t": "ἐπὶ φίλον ἐὰν σπάσῃς όομφαίαν, μὴ ἀφελπίσῃς, ἔστιν γὰρ ἐπάνοδοςΣπὶ"}, {"sp": "N", "st": "Sir 22:22", "t": "φίλον (27)ἐὸν ἀνοίξῃς στόμα, μὴ εὐλαβηθῇς, ἔστιν γὰρ διαλλαγή· πλὴν ὀνειδισμοῦ καὶ ὑπερηφανίας καὶ μυστηρίου ἀποκαλύψεως καὶ πληγῆς δολίας· ἐν τούτοις ἀποφεύξεται πᾶς φίλος."}, {"sp": "N", "st": "Sir 22:23", "t": "ςίστιν κτῆσαι ἐν πταωχείᾳ μετὰ τοῦ πλησίον, ἵνα ἐν τοῖς ἀγαθοῖς αὐτοῦ ὁμοῦ πλησθῇς· (29)ἐν καιρῷ θλίψεανς διάμενε αὐτῷ, ἵνα ἐν τῇ κληρονομίᾳ αὐτοῦ συνκληρονομήσῃς."}, {"sp": "N", "st": "Sir 22:24", "t": "πρὸ πυρὸς ἀτμὶς καμίνου καὶ καπνός, οὕτως πρὸ αἱμάτων λοιδορίαι."}, {"sp": "N", "st": "Sir 22:25", "t": "φίλον σκεπάσαι οὐκ αἰσχυνθήσομαι, καὶ ἀπὸ προσώπου αὐτοῦ οὐ μὴ κρυβῶ,"}, {"sp": "N", "st": "Sir 22:26", "t": "καὶ εἰ κακά μοι συμβήσεται δι᾿ αὐτόν, (32)πᾶς ὁ ἀκούων φυλάξεται ἀπʼ αὐτοῦ."}, {"sp": "N", "st": "Sir 22:27", "t": "Τἰς δώσει μοι ἐπὶ στόμα μου φυλακὴν καὶ ἐπὶ τῶν χειλέων μου σφραγῖδα πανοῦργον. ἵνα μὴ πέσω ἀπʼ αὐτῆς, καὶ ἡ γλῶσσά μου ἀπολέσῃ με;"}, {"sp": "N", "st": "Sir 23:1", "t": "Κύριε, πάτερ καὶ δέσποτα ζωῆς μου. μὴ ἐγκαταλίπῃς με ἐν βουλῇ αὐτῶν, μὴ ἀιφῆς με πεσεῖν ἐν αὐτοῖς."}, {"sp": "N", "st": "Sir 23:2", "t": "τίς ἐπιστήσει ἐπὶ τοῦ διανοήματός μου μάστιγας. καὶ ἐπὶ τῆς καρδίας μου παιδείαν σοφίας, ἵνα ἐπὶ τοῖς ἀγνοήμασίν μου μὴ φείσωνται, καὶ οὐ μὴ παρῇ τὰ ἁμαρτήματα αὐτῶν·"}, {"sp": "N", "st": "Sir 23:3", "t": "ὅπως μὴ πληθύνωσιν αἱ ἄγνοιαί μου, καὶ αἱ ἁμαρτίαι μου πλεονάσαωσιν, καὶ πεσοῦμαι ἔναντι τῶυ ὑπεναντίων, καὶ ἐπιχαρεῖταί μοι ὁ ἐχθρός μου"}, {"sp": "N", "st": "Sir 23:4", "t": "Κύριε, πάτερ καὶ θεὲ ζωῆς μου, (5)μετεωρισμὸν ὀφθαλμῶν μὴ δῷς μοι."}, {"sp": "N", "st": "Sir 23:5", "t": "καὶ ἐπιθυμίαν ἀπόστρεψον ἀπʼ ἐμοῦ·"}, {"sp": "N", "st": "Sir 23:6", "t": "κοιλίας ὄρεξις καὶ συνουσιασμὸς μὴ καταλαβέτωσάν με. καὶ ψυχῇ ἀναιδεῖ μὴ παραδῷς με. Παιδεία στόματος."}, {"sp": "N", "st": "Sir 23:7", "t": "Παιδείαν στόματος ἀκούσατε, τέκνα, καὶ ὁ φυλάσσων οὐ μὴ ἁλῷ·"}, {"sp": "N", "st": "Sir 23:8", "t": "ἐν τοῖς χείλεσιν αὐτοῦ ⁸καταλεμμφθήσεται ἁμαρτωλὸς καὶ λοίδορος καὶ ὑπερήφανος· σκανδαλισθήσονται ἐν αὐτοῖς."}, {"sp": "N", "st": "Sir 23:9", "t": "ὅρκῳ μὴ ἐθίσῃς τὸ στόμα σου, (10)καὶ ὀνομασίᾳ τοῦ ἁγίου μὴ συνεθισθῇς."}, {"sp": "N", "st": "Sir 23:10", "t": "ὥσπερ γὰρ οἰκέτης ἐξεταζόμενος ἐνδελεχῶς ἀπὸ μώλωπος οὐκ ἐλατπαοθήσεται, οὕτως καὶ ὁ ὀμνύων καὶ ὀνομάζων διὰ παντὸς ἀπὸ ἁμαρτίας οὐ μὴ καθαρισθῇ."}, {"sp": "N", "st": "Sir 23:11", "t": "ἀνὴρ πολύορκος πλησθήσεται ἀνομίας, καὶ οὐκ ἀποστήσεται ἀπὸ τοῦ οἴκου αὐτοῦ μάστιξ· (13)ἐὰν πλημμελήσῃ, ἁμαρτία αὐτοῦ ἐπʼ αὐτῷ, κἂν ὑπερίδῃ, ἥμαρτεν δισσῶς· (14)καὶ εἰ διὰ κενῆς μοσεν, οὐ δικαιωθήσεται, πλησθήσεται γὰρ ἐπαγωγῶν ὁ οἶκος αὐτοῦ."}, {"sp": "N", "st": "Sir 23:12", "t": "ἔστιν λέξις ἀντιπεριβεβλημένη θανάτῳ, μὴ εὑρεθήτω ἐν κληρονομίᾳ Ἰακώβ· (16)ἀπὸ γὰρ εὐσεβῶν ταῦτα πάντα ἀποστήσεται, καὶ ἐν ἁμαρτίαις οὐκ ἐνκυλισθήσονται."}, {"sp": "N", "st": "Sir 23:13", "t": "ἀπαιδευσίαν ἀσυρῆ μὴ συνεθίσῃς τὸ στόμα σου· ἔστιν γὰρ ἐν αὐτῇ λόγος ἁμαρτίας."}, {"sp": "N", "st": "Sir 23:14", "t": "μνήσθητι πατρὸς καὶ μητρός σου, ἀνὰ μέσον γὰρ μεγιστάνων συνεδρεύει· (19)μή ποτε ἐπιλάθῃ ἐνώπιον αὐτῶν, καὶ τῷ ἐθισμῷ σου μωρανθῇς, καὶ θελήσεις εἰ μὴ ἐγεννήθης, καὶ τὴν ἡμέραν τοῦ τοκετοῦ σου μὴ καταράσῃ."}, {"sp": "N", "st": "Sir 23:15", "t": "ἄθρωπος συνεθιζόμενος λόγοις ὀνειδισμοῦ ἐν πάσαις ταῖς ἡμέραις αὐτοῦ οὐ μὴ παιδευθῇ."}, {"sp": "N", "st": "Sir 23:16", "t": "Δύο εἴδη πληθύνουσιν ἁμαρτίας. καὶ τὸ τρίτον ἐπάξει ὀργήν· (22)ψυχὴ θερμὴ ὡς πῦρ καιόμενον, οὐ μὴ σβεσθῇ ἕως ἂν καταποθῇ· (23)ἄνθρωπος πόρνος ἐν σώματι σαρκὸς αὐτοῦ, οὐ μὴ παύσηται ἕως ἂν ἐκκαύσῃ πῦρ·"}, {"sp": "N", "st": "Sir 23:17", "t": "ἀνθρώπῳ πόρνῳ πᾶς ἄρτος ἡδύς, οὐ μὴ κοπάσῃ ἕως ἂν τελευτήσῃ·"}, {"sp": "N", "st": "Sir 23:18", "t": "ἄνθρωπος παραβαίνων ἀπὸ τῆς κλίνης αὐτοῦ, λέγων ἐν τῇ ψυχῇ αὐτοῦ Τίς με ὁρᾷ; (26)σκότος κύκλῳ μου, καὶ οἱ τοῖχοί με καλύπτουσιν, καὶ οὐθείς με ὁρᾷ, τί εὐλαβοῦμαις; τῶν ἁμαρτιῶν μου οὐ μὴ μνησθήσεται ὁ ὕψιστος."}, {"sp": "N", "st": "Sir 23:19", "t": "καὶ ὀφθαλμοὶ ἀνθρώπων ὁ φόβος αὐτοῦ, (28)καὶ οὐκ ἔγνω ὅτι ὀφθαλμοὶ Κυρίου μυριοπλασίως ἡλίου φωτεινότεροι, ἐπιβλέποντες πάσας ὁδοὺς ἀνθρώπων καὶ κατανοοῦντες εἰς ἀπόκρυφα μέρη."}, {"sp": "N", "st": "Sir 23:20", "t": "πρὶν ἢ κτισθῆναι τὰ πάντα ἔγνωσται αὐτῷ, οὕτως καὶ μετὰ τὸ συντελεσθῆναι."}, {"sp": "N", "st": "Sir 23:21", "t": "οὗτος ἐν πλατείαις πόλεως ἐκδικηθήσεται, καὶ οὗ οὐχ ὑπενόησεν πιασθήσεται."}, {"sp": "N", "st": "Sir 23:22", "t": "οὕτως καὶ γυνὴ καταλιποῦσα τὸν ἄνδρα καὶ παριστῶσα κληρονόμον ἐξ ἀλλοτρίου·"}, {"sp": "N", "st": "Sir 23:23", "t": "πρῶτον μὲν γὰρ ἐν νόμῳ Ὑψίστου ἠπείθησεν, καὶ δεύτερον εἰς ἄνδρα ἑαυτῆς ἐπλημμέλησεν· καὶ τὸ τρίτον ἐν πορνείᾳ ἐμοιχεύθη, ἐξ ἀλλοτρίου ἀνδρὸς τέκνα παρέστησεν."}, {"sp": "N", "st": "Sir 23:24", "t": "αὕτη εἰς ἐκκλησίαν ἐξαχθήσεται, καὶ ἐπὶ τὰ τέκνα αὐτῆς ἐπισκοπὴ ἔσται·"}, {"sp": "N", "st": "Sir 23:25", "t": "διαδώσουσιν τὰ τέκνα αὐτῆς εἰς ῥίζαν, καὶ οἱ κλάδοι αὐτῆς οὐ δώσουσιν καρπόν·"}, {"sp": "N", "st": "Sir 23:26", "t": "καταλείψει εἰς κατάραν τὸ μνημόσυνον αὐτῆς, καὶ τὸ ὄνειδος αὐτῆς οὐκ ἐξαλειφθήσεται·"}, {"sp": "N", "st": "Sir 23:27", "t": "καὶ ἐπιγνώσονται οἵ καταλειφθέντες ὅτι οὐθὲν κρεῖττον φόβου Κυρίου, καὶ οὐθὲν γλυκύτερον τοῦ προσέχειν ἐντολαῖς Κυρίου. Αἵνεσις σοφίας."}, {"sp": "N", "st": "Sir 24:1", "t": "Ἡ σοφία αἰνέσει ψυχὴν αὐτῆς, καὶ ἐν μέσῳ λαοῦ αὐτῆς καυχήσεται."}, {"sp": "N", "st": "Sir 24:2", "t": "ἐν ἐκκλησίὰ Ὑψἰστου στόμα αὐτῆς ἀνοίξει. καὶ ἔναντι δυνάμεως αὐτοῦ καυχήσεται"}, {"sp": "N", "st": "Sir 24:3", "t": "Ἐγὼ ἀπὸ στόματος Ὑψίστου ἐξῆλθον, (6)καὶ ὡς ὁμίχλη κατεκάλυψα γῆν·"}, {"sp": "N", "st": "Sir 24:4", "t": "ἐγὼ ἐν ὑψηλοῖς κατεσκήνωσα, καὶ ὁ θρόνος μου ἐν στύλῳ νεφέλης·"}, {"sp": "N", "st": "Sir 24:5", "t": "γῦρον οὐρανοῦ ἐκύκλωσα μόνη, καὶ ἐν βάθει ἀβύσσων περιεπάτησα·"}, {"sp": "N", "st": "Sir 24:6", "t": "ἐν κύμασιν θαλάσσης (9)καὶ ἐν πάσῃ τῇ γῇ, (10)καὶ ἐν παντὶ λαῷ καὶ ἔθνει ἐκτησάμην·"}, {"sp": "N", "st": "Sir 24:7", "t": "μετὰ τούτων πάντων ἀνάπαυσιν ἐζήτησα, καὶ ἐν κληρονομίᾳ τίνος αὐλισθήσομαις"}, {"sp": "N", "st": "Sir 24:8", "t": "τότε ἐνετείλατό μοι ὁ κτίστης ἁπάντων, καὶ ὁ κτίσας με κατέπαυσεσ τὴν σκηνὴν μου (13)καὶ εἶπ εν Ἐν Ἰακὼβ κατασκήνωσον, καὶ ἐν Ἰσραὴλ κατακληρονομήθητι."}, {"sp": "N", "st": "Sir 24:9", "t": "πρὸ τοῦ αἰῶνος ἀπʼ ἀρχῆς ἔκτισέν με. καὶ ἕως αἰῶνος οὐ μὴ ἐκλίπαω."}, {"sp": "N", "st": "Sir 24:10", "t": "ἐν σκηνῇ ἁγίᾳ ἐνώπιον αὐτοῦ ἐλειτούργησα, (15)καὶ οὕτως ἐν Σειῶν ἐστηρίχθην·"}, {"sp": "N", "st": "Sir 24:11", "t": "ἐν πόλει ἠγαπημένῃ ὀμοίαως με κατέπαυσεν, καὶ ἐν Ἰερουσαλὴμ ἡ ἐξουσία μου·"}, {"sp": "N", "st": "Sir 24:12", "t": "καὶ ἐρρίζωσα ἐν λαῷ δεδοξασμένῳ. ἐν μερίδι Κυρίου κληρονομίας αὐτοῦ."}, {"sp": "N", "st": "Sir 24:13", "t": "ὡς κέδρος ἀνυψώθην ἐν τῷ ΑΛιβάνῳ, καὶ ὡς κυπάρισσος ἐν ὄρεσιν Ἀερμών·"}, {"sp": "N", "st": "Sir 24:14", "t": "ὁς φοίνιξ ἀνυψώθην ἐν αἰγιαλοῖς, καὶ ὡς φυτὰ ὸόδου ἐν Ἰερειχώ· (19)ὡς ἐλαία εὐπρεπὴς ἐν πεδίῳ, καὶ ἀνυψώθην ὡς πλάτανος."}, {"sp": "N", "st": "Sir 24:15", "t": "ὁὡς κιννάμωμον καὶ ἀσπάλαθος ἀρωμάτων δέδωκα ὀσμήν, καὶ ὡς σμύρνα ἐκλεκτὴ διέδωκα εὐωδίαν, ὡς χαλβάνη καὶ ὄνυξ καὶ στακτή, καὶ ὡς λιβάνου ἀτμὶς ἐν σκηνῇ·"}, {"sp": "N", "st": "Sir 24:16", "t": "ἐγὼ ὡς τερέμινθος ἐξέτεινα κλάδους μου, καὶ οἱ κλάδοι μου κλάδοι δόξης καὶ χάριτος."}, {"sp": "N", "st": "Sir 24:17", "t": "ἐγὼ ὡς ἄμπελος βλαστήσασα χάριν. καὶ τὰ ἄνθη μου καρπὸς δόξης καὶ πλούτου."}, {"sp": "N", "st": "Sir 24:19", "t": "προσέλθετε πρὸς μέ, οἱ ἐπιθυμοῦντές μου, καὶ ἀπὸ τῶν γενημάτων μου ἐμπλήσθητε·"}, {"sp": "N", "st": "Sir 24:20", "t": "τὸ γὰρ μνημόσυνόν μου ὑπέρ μέλι γλυκύ, καὶ ἡ κληρονομία μου ὑπέρ μέλιτος κηροῦ."}, {"sp": "N", "st": "Sir 24:21", "t": "οἱ ἐσθίοντές με ἔτι πεινάσουσιν, καὶ οἱ πίνοντές με ἔτι διψήσουσιν·"}, {"sp": "N", "st": "Sir 24:22", "t": "ὁ ὑπακούων μου οὐκ αἰσχυνθήσεται, καὶ οἱ ἐργαζόμενοι ἐν ἐμοὶ οὐχ ἁμαρτήσουσιν."}, {"sp": "N", "st": "Sir 24:23", "t": "ταῦτα πάντα ββίδλος διαθήκης θεοῦ Ὑψίστου, νόμον ὃν ἐνετείλατο Μωυσῆς κληρονομίαν συναγωγαῖς Ἰακώβ·"}, {"sp": "N", "st": "Sir 24:25", "t": "ὁ πιμπλῶν ὡς Φισὼν σοφίαν, καὶ ὡς Τίγρις ἐν ἡμέραις νέων·"}, {"sp": "N", "st": "Sir 24:26", "t": "ὁ ἀναπληρῶν ὡς Εὐφράτης σύνεσιν, καὶ ὡς Ἰορδάνης ἐν ἡμέραις θερισμοῦ·"}, {"sp": "N", "st": "Sir 24:27", "t": "ὁ ἐκφαίνων ὡς φῶς παιδείαν, ὡς Γηὼν ἐν ἡμέραις τρυγητοῦ."}, {"sp": "N", "st": "Sir 24:28", "t": "οὐ συνετέλεσεν ὁ πρῶτος γνῶναι αὐτήν, καὶ οὕτως ὁ ἔσχατος οὐκ ἐξιχνίασεν αὐτήν·"}, {"sp": "N", "st": "Sir 24:29", "t": "ἀπὸ γὰρ θαλάσσης ἐπληθύνθη διανόημα αὐτῆς, καὶ ἡ βουλὴ αὐτῆς ἀπὸ ἀβύσσου μεγάλης."}, {"sp": "N", "st": "Sir 24:30", "t": "κἀγὼ ὡς διῶρυξ ἀπὸ ποταμοῦ, καὶ ὡς ὑδραγωγὸς ἐξῆλθον εἰς παράδεισον·"}, {"sp": "N", "st": "Sir 24:31", "t": "κἶπα Ποτιῶ μου τὸν κῆπον, καὶ μεθύσω μου τὴν πρασιάν· (43) καὶ ἰδοὺ ἐγένετό μοι ἡ διῶρυξ εἰς ποταμόν, καὶ ὁ ποταμός μου ἐγένετο εἰς θάλασσαν."}, {"sp": "N", "st": "Sir 24:32", "t": "ἔτι παιδείαν ὡς ὄρθρον φωτιῶ, καὶ ἐκφανῶ αὐτὰ ἕως εἰς μακράν·"}, {"sp": "N", "st": "Sir 24:33", "t": "ἔτι διδασκαλίαν ὡς προφητείαν ἐκχεῶ, καὶ καταλείψω αὐτὴν εἰς γενεὰς αἰώνων."}, {"sp": "N", "st": "Sir 24:34", "t": "ἴδετε ὅτι οὐκ ἐμοὶ μόνῳ ἐκοπίασα, ἀλλʼ ἅποσιν τοῖς ἐκζητοῦσιν αὐτήν."}, {"sp": "N", "st": "Sir 25:1", "t": "Ἐν τρισὶν ὡραίσθην καὶ ἀνέστην ὡραία ἔναντι Κυρίου καὶ ἀνθρώπων· (2)ὁμόνοια ἀδελφῶν, καὶ φιλία τῶν πλησίον, καὶ γυνὴ καὶ ἀνὴρ ἑαυτοῖς συνπεριφερόμενοι"}, {"sp": "N", "st": "Sir 25:2", "t": "τρία δὲ εἴδη ἐμίσησεν ἡ ψυχὴ μου καὶ προσώχθισα σφόδρα τῇ ζωῇ αὐτῶνεττωχὸν (4)ὑπερήφανον, καὶ πλούσιον ψεύστην, γέροντα μοιχὸν ἐλαττούμενον συνέσει."}, {"sp": "N", "st": "Sir 25:3", "t": "ἐν νεότητι οὐ συναγίοχας, καὶ πῶς ἂν εὕροις ἐν τῷ γήρᾳ σου;"}, {"sp": "N", "st": "Sir 25:4", "t": "ὡς ὡραῖον πολιαῖς κρίσις, καὶ πρεσβυτέροις ἐπιγνῶναι βουλήν·"}, {"sp": "N", "st": "Sir 25:5", "t": "ὡς ὡραία γερόντων σοφία, καὶ δεδοξασμένοις διανόημα καὶ βουλή."}, {"sp": "N", "st": "Sir 25:6", "t": "στέφανος γερόντων πολυπειρία, καὶ τὸ καύχημα αὐτῶν φόβος Κυρίου."}, {"sp": "N", "st": "Sir 25:7", "t": "Ἐννέα ὑπονοήματα ἐμακάρισα ἐν καρδίᾳ, καὶ τὸ δέκατον ἐρῶ ἐπὶ γλώσσης· (10)Μνθρωπος εὐφραινόμενος ἐπὶ τέκνοις, ζῶυ καὶ βλέπων ἐπὶ πτώσει ἐχθρῶν·"}, {"sp": "N", "st": "Sir 25:8", "t": "μακάριος ὁ συνοικῶν γυναικὶ συνετῇ, καὶ ὸς ἐν γλωσσῃ οὐκ λίσθησεν, καὶ ὅς οὐκ ἐδούλευσεν ἀναξίῳ αὐτοῦ·"}, {"sp": "N", "st": "Sir 25:9", "t": "μακάριος ὁς εὗρεν φρόνησιν, καὶ ὁ διηγούμενος εἰς ὥτα ἀκουόντων·"}, {"sp": "N", "st": "Sir 25:10", "t": "ὁὡι μέγας ὁ εὑρών σοφίαν, ἀλλʼ οὐκ ἔστιν ὑπέρ τὸν φοβούμενον τὸν κύριον·"}, {"sp": "N", "st": "Sir 25:11", "t": "φόβος Κυρίου ὑπέρ πᾶν ὑπερέβαλεν, ὁ κρατῶυ αὐτοῦ τίνι ὁμοιωθήσεται;"}, {"sp": "N", "st": "Sir 25:13", "t": "Ιᾶσαν πληγήν, καὶ μὴ πληγὴν καρδίας· καὶ πᾶσαν πονηρίαν, καὶ μὴ πονηρίαν γυναικῆς·"}, {"sp": "N", "st": "Sir 25:14", "t": "ετᾶσαν ἐπαγωγήν, καὶ μὴ ἐπαγωγὴν μισούντων· (21)καὶ πᾶσαν ἐκδίκησιν, καὶ μὴ ἐκδίκησιν ἐχθρῶν."}, {"sp": "N", "st": "Sir 25:15", "t": "οὐκ ἔστιν κεφαλὴ ὑπὲρ κεφαλὴν ὄφεως, καὶ οὐκ ἔστιν θυμὸς ὑπέρ θυμὸν ἐχθροῦ."}, {"sp": "N", "st": "Sir 25:16", "t": "συνοικῆσαι λέοντι καὶ δράκοντι εὐδοκήσω ἤ ἐνοικῆσαι μετὰ γυναικὸς πονηρᾶς."}, {"sp": "N", "st": "Sir 25:17", "t": "πονηρία γυναικὸς ἀλλοιοῖ τὴν ὄρασιν αὐτῆς, καὶ σκοτοῖ τὸ πρόσωπον αὐτῆς ὡς σάκκον·"}, {"sp": "N", "st": "Sir 25:18", "t": "ἀνὰ μέσον τοῦ πλησίον αὐτοῦ (25)ἀναπεσεῖται ὁ ἀνὴρ αὐτῆς, καὶ ἀκούσας ἀνεστέναξεν πικρά."}, {"sp": "N", "st": "Sir 25:19", "t": "μικρὰ πᾶσα κακία πρὸς κακίαν γυναικός, κλῆρος ἁμαρτωλοῦ ἐπιπέσοι αὐτῇ."}, {"sp": "N", "st": "Sir 25:20", "t": "ἀνάβασις ἀμμώδης ἐν ποσὶν πρεσβυτέρου, οὕτως γυνὴ γλωσσώδης ἀνδρὶ ἡσύχᾳῃλ"}, {"sp": "N", "st": "Sir 25:21", "t": "μὴ προσπέσῃς ἐπὶ κάλλος γυναικός, καὶ γυναῖκα μὴ ἐπιποθήσῃς."}, {"sp": "N", "st": "Sir 25:22", "t": "ὀργὴ καὶ ἀναίδεια καὶ αἰσχύνη μεγάλη πγυνὴ ἐὰν ἐπιχορηγῇ τῷ ἀνδρὶ αὐτῆς."}, {"sp": "N", "st": "Sir 25:23", "t": "καρδία ταπεινὴ καὶ πρόσωπον σκυθρωπὸν καὶ πληγὴ καρδίας γυνὴ πονηρά· (32)χεῖρες παρειμέναι καὶ γόνατα παραλελυμένα, ἥτις οὐ μακαριεῖ τὸν ἄνδρα αὐτῆς."}, {"sp": "N", "st": "Sir 25:24", "t": "ἀπὸ γυναικὸς ἀρχὴ ἁμαρτίας. καὶ δι αὐτὴν ἀποθνήσκομεν πάντες."}, {"sp": "N", "st": "Sir 25:25", "t": "μὴ δῷς υδατι διέξοδον, μηδέ γυναικὶ πονηρῷ ἐξουσίαν·"}, {"sp": "N", "st": "Sir 25:26", "t": "εἰ μὴ πορεύεται κατὰ χεῖρά σου, (36)ἀπὸ τῶν σαρκῶν σου ἀπότεμε αὐτήν."}, {"sp": "N", "st": "Sir 26:1", "t": "Γυναικὸς ἀγαθῆς μακάριος ὁ ἀνήρ, καὶ ἀριθμὸς τῶν ἡμερῶν αὐτοῦ διπλάσιος."}, {"sp": "N", "st": "Sir 26:2", "t": "γυνὴ ἀνδρεία εὐφραίνει τὸν ἄνδρα αὐτῆς, καὶ τὰ ἔτη αὐτοῦ πληρώσει ἐν εἰρήνῃ."}, {"sp": "N", "st": "Sir 26:3", "t": "γυνὴ ἀγαθὴ μερὶς ἀγαθή, ἐν μερίδι φοβουμένων Κύρον δοθήσεται."}, {"sp": "N", "st": "Sir 26:4", "t": "τλουσίου δὲ καὶ πτωχοῦ καρδία ἀγαθή, ἐν παντὶ καιρῷ πρόσωπον ἱλαρόν."}, {"sp": "N", "st": "Sir 26:5", "t": "ἀπὸ τριῶν εὐλαβήθη ἡ καρδία μου, καὶ ἐπὶ τῷ τετάρτῳ προσώπῳ ἐδεήθηνδιαβολὴν (⁹)πόλεως, καὶ ἐκκλησίαν ὄχλου, (7)καὶ καταψευσμόν, ὑπέρ θάνατον πάντα μοχθηρά."}, {"sp": "N", "st": "Sir 26:6", "t": "6ἄλγος καρδίας καὶ πένθος γυνὴ ἀντίζηλος ἐπὶ γυναικί, καὶ μάστιξ γλώσσης πᾶσιν ἐπικοινωνοῦσα."}, {"sp": "N", "st": "Sir 26:7", "t": "βοοζύγιον σαλευόμενον γυνὴ πονηρά, ὁ κρατῶν αὐτῆς ὡς ὁ δρασσόμενος σκορπίου."}, {"sp": "N", "st": "Sir 26:8", "t": "ὀργὴ μεγάλη γυνὴ μέθυσος, καὶ ἀσχημοσύνην αὐτῆς οὐ συνκαλύψει."}, {"sp": "N", "st": "Sir 26:9", "t": "πορνεία γυναικὸς ἐν μετεωρισμοῖς ὀφθαλμῶν, καὶ ἐν τοῖς βλεφάροις αὐτῆς γνωσθήσεται."}, {"sp": "N", "st": "Sir 26:10", "t": "ἐπ ὶ θυγατρὶ ἀδιατρέπτως στερέωσον φυλακήν, ἵνα μὴ εὑροῦσα ἄνεσιν ἑαυτῇ χρήσηται·"}, {"sp": "N", "st": "Sir 26:11", "t": "ὀπίσω ἀναιδοῦς ὀφθαλμοῦ φύλαξαι, καὶ μὴ θαυμάσῃς ἐὰν εἰς σὲ πλημμελήσῃ·"}, {"sp": "N", "st": "Sir 26:12", "t": "ς διψῶν ὁδοιπόρος τὸ στόμα ἀνοίγει, καὶ ἀπὸ παντὸς ὕδατος τοῦ σύνεγγυς πίεται, κατέναντι παντὸς πασσάλου καθήσεται, καὶ ἔναντι βέλους ἀνοίξει φαρέτραν."}, {"sp": "N", "st": "Sir 26:13", "t": "χάρις γυναικὸς τέρψει τὸν ἄνδρα αὐτῆς, καὶ τὰ ὀστᾶ αὐτοῦ πιανεῖ ἡ ἐπιστήμη αὐτῆς."}, {"sp": "N", "st": "Sir 26:14", "t": "δόσις Κυρίου γυνὴ σιγηρά, (8)καὶ οὐκ ἔστιν ἀντάλλαγμα πεπαιδευμένης ψυχῆς·"}, {"sp": "N", "st": "Sir 26:15", "t": "χάρις ἐπὶ χάριτι γυνὴ αἰσχυντηρά, καὶ οὐκ ἔστιν σταθμὸς πᾶς ἄξιος ἐγκρατοῦς ψυχῆς."}, {"sp": "N", "st": "Sir 26:16", "t": "ἥλιος ἀνατέλλων ἐν ὑψίστοις Κυρίου, καὶ κάλλος ἀγαθῆς γυναικὸς ἐν κόσμῳ οἰκίας αὐτοῦ·"}, {"sp": "N", "st": "Sir 26:17", "t": "λύχνος ἐκλάμπων ἐπὶ λυχνίας ἁγίας, καὶ κάλλος προσώπου ἐπὶ ἡλικίᾳ στασίμῃ·"}, {"sp": "N", "st": "Sir 26:18", "t": "στύλοι χρύσεοι ἐπὶ βάσεως ἀργυρῆς. καὶ πόδες ὡραῖοι ἐπὶ στέρνοις εὐσταθοῦς."}, {"sp": "N", "st": "Sir 26:28", "t": "Επὶ 1 δυσὶ λελύπηται ἡ καρδία μου, καὶ ἐπὶ τῷ τρίτῳ θυμός μοι ἐπῆλθεν· (26)ἀνὴρ πολεμιστὴς ὑστερῶν δι᾿ νδειαν, καὶ ἄνδρες συνετοὶ ἐὰν σκυβαλισθῶσιν, (27)ἐπανάγων ἀπὸ δικαιοσύνης ἐπὶ ἁμαρτίαν· ὁ κύριος ἑτοιμάσει εἰς ῥομφαίkαν αὐτόν."}, {"sp": "N", "st": "Sir 26:29", "t": "Μόλις ἐξελεῖται ἔμπορος ἀπὸ πλημμελείας. καὶ οὐ δικαιωθήσεται κάπηλος ἀσὸ ἁμαρτίας."}, {"sp": "N", "st": "Sir 27:1", "t": "χάριν ἀδιαφόρου πολλοὶ ἥμαρτον, καὶ ὁ ζητῶν πληθῦναι ἀποστρέψει ὀφθαλμόν."}, {"sp": "N", "st": "Sir 27:2", "t": "ἀνὰ μέσον ἁρμῶν λίθων παγήσεται πάσσαλος, καὶ ἀνὰ μέσον πράσεως καὶ ἀγορασμοῦ συντριβήσεται ἁμαρτία."}, {"sp": "N", "st": "Sir 27:3", "t": "ἐὰν μὴ ἐν φόβῳ Κυρίου κρατήσῃ κατὰ σπουδήν, ἐν τάχει καταστραφήσεται αὐτοῦ ὁ οἶκος."}, {"sp": "N", "st": "Sir 27:4", "t": "ἐν σείσματι κοσκίνου διαμένει κοπρία, οὕτως σκύβαλα ἀνθρώπου ἐν λογισμῷ αὐτοῦ."}, {"sp": "N", "st": "Sir 27:5", "t": "σκεύη κεραμέως δοκιμάζει κάμινος, καὶ πειρασμὸς ἀνθρώπου ἐυ διαλογισμῷ αὐτοῦ."}, {"sp": "N", "st": "Sir 27:6", "t": "γεώργιον ξύλου ἐκφαίνει ὁ καρπὸς αὐτοῦ, οὕτως λόγος ἐνθυμήματος καρδίας ἀνθρώπου."}, {"sp": "N", "st": "Sir 27:7", "t": "πρὸ λογισμοῦ μὴ ἐπαινέσῃς ἄνδρα, οὗτος γὰρ πειρασμὸς ἀνθρώπων."}, {"sp": "N", "st": "Sir 27:8", "t": "ἐὰν διώκῃς τὸ δίκαιον, καταλήμψῃ, καὶ ἐνδύσῃ αὐτὸ ὡς ποδήρη δόξης."}, {"sp": "N", "st": "Sir 27:9", "t": "πετεινὰ πρὸς τὰ ὅμοια αὐτοῖς καταλύσει, καὶ ἀλήθεια πρὸς τοὺς ἐργαζομένους αὐτὴν ἐπανήξει."}, {"sp": "N", "st": "Sir 27:10", "t": "λέων θῆραν ἐνεδρεύει, οὕτως ἁμαρτίαι ἐργαζομένους ἄδικα."}, {"sp": "N", "st": "Sir 27:11", "t": "διήγησις εὐσεβοῦς διὰ παντὸς σοφία, ὁ δὲ ἄφρων ὡς σελήνη ἀλλοιοῦται."}, {"sp": "N", "st": "Sir 27:12", "t": "εἰς μέσον ἀσυνέτων συντήρησον καιρόν, εἰς μέσον δὲ διανοουμένου ἐνδελέχιζε."}, {"sp": "N", "st": "Sir 27:13", "t": "διήγησις μαορῶν προσόχθισμα, καὶ ὁ γέλως αὐτῶν ἐν σπατάλῃ ἁμαρτίας."}, {"sp": "N", "st": "Sir 27:14", "t": "λάλα πολυόρκου ὀρθώσει τρίχας. καὶ ἡ μάχη αὐτῶν ἐνφραγμὸς ὠτίων."}, {"sp": "N", "st": "Sir 27:15", "t": "ἕκχυσις αἵματος μάχη ὑπερηφάνων, καὶ ἡ διαλοιδόρησις αὐτῶν ἀκοὴ μοχθηρά."}, {"sp": "N", "st": "Sir 27:16", "t": "Ὁ ἀποκαλύπτων μυστήρια ἀπώλεσεν πίστιν, καὶ οὐ μὴ εὕρῃ φίλον πρὸς τὴν ψυχὴν αὐτοῦ."}, {"sp": "N", "st": "Sir 27:17", "t": "στέρξον φίλον καὶ πιστώθητι μετʼ αὐτοῦ· (19)ἐὸν δὲ ἀποκαλύψῃς τὰ μυστήρια αὐτοῦ, οὐ μὴ καταδιώξῃς ὀπίσω αὐτοῦ."}, {"sp": "N", "st": "Sir 27:18", "t": "καθὼς γὰρ ἀπώλεσεν ἄνθρωπος τὸν ἐχθρὸν αὐτοῦ, οὕτως ἀπώλεσας τὴν φιλίαν τοῦ πλησίον·"}, {"sp": "N", "st": "Sir 27:19", "t": "19καὶ ὡς πετεινὸν ἐκ χειρός σου ἀπέλυσας, οὕτως ἀφῆκας τὸν πλησίον, καὶ οὐ θηρεύσεις αὐτόν."}, {"sp": "N", "st": "Sir 27:20", "t": "μὴ αὐτὸν διώξῃς, ὅτι μακρὰν ἀπέστη, καὶ ἐξέφυγεν ὡς δορκὰς ἐκ παγίδος."}, {"sp": "N", "st": "Sir 27:21", "t": "ὅτι τραῦμα ἔστιν (23)καταδῆσαι, καὶ λοιδορίας ἐστὶν διαλλαγή· (24)ὁ δὲ ἀποκαλύψας μυστήρια ἀφήλπισεν."}, {"sp": "N", "st": "Sir 27:22", "t": "διανεύων ὀφθαλμῷ τεκταίνει κακά, καὶ οὐδεὶς αὐτὸν ἀποστήσει ἀπʼ αὐτοῦ·"}, {"sp": "N", "st": "Sir 27:23", "t": "ἀπέναντι τῶν ὀφθαλμῶν σου γλυκανεῖ στόμα σου καὶ ἐπὶ τῶν λόγων σου ἐκθαυμάσει, ὕστερον δὲ διαστρέψει τὸ στόμα αὐτοῦ καὶ ἐν τοῖς λόγοις σου δώσει σκάνδαλον."}, {"sp": "N", "st": "Sir 27:24", "t": "πολλὰ ἐμίσησα καὶ οὐχ ὀμοίωσα αὐτῷ, καὶ ὁ κύριος μισήσει αὐτόν."}, {"sp": "N", "st": "Sir 27:25", "t": "ὁ ββάλλων λίθον εἰς ὕψος ἐπὶ κεφαλὴν αὐτοῦ βάλλει, καὶ πληγὴ δολία διελεῖ τραύματα."}, {"sp": "N", "st": "Sir 27:26", "t": "ὁ ὀρύσσων βόθρον εἰς αὐτὸν ἐμπεσεῖται, καὶ ὁ ἱστῶν παγίδα ἐν αὐτῇ ἁλώσεται·"}, {"sp": "N", "st": "Sir 27:27", "t": "ὁ ποιῶν πονηρὰ εἰς αὐτὸν κυλισθήσεται, καὶ οὐ μὴ ἐπιγνῷ πόθεν ἤκει αὐτῷ."}, {"sp": "N", "st": "Sir 27:28", "t": "ἐμπαιγμὸς καὶ ὀνειδισμὸς ὑπερηφάνων, καὶ ἡ ἐκδίκησις ὡς λέων ἐνεδρεύσει αὐτόν."}, {"sp": "N", "st": "Sir 27:29", "t": "παγίδι ἁλώσονται οἱ εὐφραινόμενοι πτώσει εὐσεβῶν, καὶ ὀδύνη καταναλώσει αὐτοὺς πρὸ τοῦ θανάτου αὐτῶν."}, {"sp": "N", "st": "Sir 27:30", "t": "Μῆνις καὶ ὀργή, καὶ ταῦτά ἐστιν βδελύγματα, καὶ ἀνὴρ ἁμαρτωλὸς ἐγκρατὴς ἔσται αὐτῶν."}, {"sp": "N", "st": "Sir 28:1", "t": "ὁ ἐκδικῶν παρὰ Κυρίου εὑρήσει ἐκδίκησιν, καὶ τὰς ἁμαρτίας αὐτοῦ διαστηριῶν διαστηρίσει."}, {"sp": "N", "st": "Sir 28:2", "t": "ἄφες ἀδίκημα τῷ πλησίον σου, καὶ τότε δεηθέντος σου αἱ ἁμαρτίαι σου λυθήσονται."}, {"sp": "N", "st": "Sir 28:3", "t": "ἄνθρωπος ἀνθρώπῳ συντηρεῖ ὀργὴν, καὶ παρὰ Κυρίου ζητεῖ ἵασιν"}, {"sp": "N", "st": "Sir 28:4", "t": "ἐπ ἄνθρωπον ὅμοιον αὐτῷ οὐκ ἔχει ἔλεος, καὶ περὶ τῶν ἁμαρτιῶν αὐτοῦ δεῖται;"}, {"sp": "N", "st": "Sir 28:5", "t": "αὐτὸς σὰρξ ὧν διατηρεῖ μῆνιν, τίς ἐξιλάσεται τὰς ἁμαρτίας αὐτοῦ;"}, {"sp": "N", "st": "Sir 28:6", "t": "μνήσθητι τὰ ἔσχατα καὶ παῦσαι ἐχθραίνων, (7)καταφθορὰν καὶ θάνατον, καὶ ἔμμενε ἐντολαῖς."}, {"sp": "N", "st": "Sir 28:7", "t": "μνήσθητι ἐντολῶν καὶ μὴ μηνίσῃς τῷ πλησίον, (9)καὶ διαθήκην Ὑψίστου, καὶ πάριδε ἄγνοιαν."}, {"sp": "N", "st": "Sir 28:8", "t": "Ἀπόσχου ἀπὸ μάχης. καὶ ἐλαττώσεις ἁμαρτίας· Μνθρωπος γὰρ θυμώδης ἐκκαύσει μάχην."}, {"sp": "N", "st": "Sir 28:9", "t": "καὶ ἀνὴρ ἁμαρτωλὸς ταράξει φίλους, καὶ ἀνὰ μέσον εἰρηνευόντων ἐκβάλλει διαβολήν."}, {"sp": "N", "st": "Sir 28:10", "t": "κατὰ τὴν ὕλην πυρὸς οὕτως ἐκκαυθήσεται, κατὰ τὴν ἰσχὺν τοῦ ἀνθρώπου ὁ θυμὸς αὐτοῦ ἔσται· καὶ κατὰ τὸν πλούτου ἀνυψώσει ὀργὴν αὐτοῦ, καὶ κατὰ τὴν στερέωσιν τῆς μάχης ἐκκαυθήrτεται."}, {"sp": "N", "st": "Sir 28:11", "t": "ἔρις κατασπευδομένη ἐκκαίει πῦρ, καὶ μάχη κατασπεύδουσα ἐκχέει αἶμα."}, {"sp": "N", "st": "Sir 28:12", "t": "ἐὰν φυσήσῃς σπινθῆρα ἐκκαήσεται, καὶ ἐὰν πτύσῃς ἐπʼ αὐτὸν σβεσθήσεται· καὶ ἀμφότερα ἐκ τοῦ στόματός σου ἐκπορεύεται."}, {"sp": "N", "st": "Sir 28:13", "t": "ψίθυρον καὶ δίγλωσσον καταρᾶσθε, πολλοὺς γὰρ εἰρηνεύοντας ἀπώλεσαν."}, {"sp": "N", "st": "Sir 28:14", "t": "γλῶσσα τρίτη πολλοὺς ἐσάλευσεν καὶ διέστησεν αὐτοὺς ἀπὸ ἔθνους εἰς ἔθνος, (17)καὶ πόλεις ὀχυρὰς καθεῖλεν, καὶ οἰκίας μεγιστάνων κατέστρεψεν·"}, {"sp": "N", "st": "Sir 28:15", "t": "γλῶσσα τρίτη γυναῖκας ἀνδρείας ἐξέβαλεν, καὶ ἐστέρεσεν αὐτὰς τῶν πόνων αὐτῶν·"}, {"sp": "N", "st": "Sir 28:16", "t": "ὁ προσέχων αὐτῇ οὐ μὴ εὕρῃ ἀνάπαυσιν, οὐδὲ κατασκηνάσει μεθʼ ἡσυχίας."}, {"sp": "N", "st": "Sir 28:17", "t": "πληγὴ μάστιγος ποιεῖ μώλωπας, πληγὴ δέ γλώσσης συνκλάσει ὀστᾶ."}, {"sp": "N", "st": "Sir 28:18", "t": "ὅλοι ἔπεσαν ἐν στόματι μαχαίρας. καὶ οὐχ ὡς οἱ πεπτωκότες διὰ γλῶσσαν."}, {"sp": "N", "st": "Sir 28:19", "t": "μακάριος ὁ σκεπασθεὶς ἀπʼ αὐτῆς, ὁς οὐ διῆλθεν ἐν τῷ θυμῷ αὐτῆς, ὁς οὐχ εἵλκυσεν τὸν ζυγὸν αὐτῆς, καὶ ἐν τοῖς δεσμοῖς αὐτῆς οὐκ ἐδέθη·"}, {"sp": "N", "st": "Sir 28:20", "t": "ὁ γὰρ ζυγὸς αὐτῆς ζυγὸς σιδηροῦς. καὶ οἱ δεσμοὶ αὐτῆς δεσμοὶ χαλκεῖοι·"}, {"sp": "N", "st": "Sir 28:21", "t": "θάνατος πονηρὸς ὁ θάνατος αὐτῆς, καὶ λυσιτελὴς μᾶλλον ὁ ἄδης αὐτῆς."}, {"sp": "N", "st": "Sir 28:22", "t": "οὐ μὴ κρατήσῃ εὐσεβῶν, καὶ ἐν τῇ φλογὶ αὐτῆς οὐ καήσονται·"}, {"sp": "N", "st": "Sir 28:23", "t": "οἱ καταλείποντες Κύριον ἐμπεσοῦνται εἰς αὐτήν, καὶ ἐν αὐτοῖς ἐκκαήσεται καὶ οὐ μὴ σβεσθῇ· ἐξαποσταλήσεται ἐπʼ αὐτοῖς ὡς λέων, καὶ ὡς πάρδαλις λυμανεῖται αὐτούς."}, {"sp": "N", "st": "Sir 28:24", "t": "δὲ, περίφραξον τὸ κτῆμά σου ἀκάνθαις, (29)τὸ ἀργύριόν σου καὶ τὸ χρυσίον κατάδησον·"}, {"sp": "N", "st": "Sir 28:25", "t": "καὶ τοῖς λόγοις σου ποίησον ζυγὸν καὶ σταθμόν, καὶ τῷ στόματί σου ποίησον θύραν καὶ μοχλόν."}, {"sp": "N", "st": "Sir 28:26", "t": "πρόσεχε μὴ πως ὀλισθήσῃς ἐν αὐτῇ, μὴ πέσῃς κατέναντι ἐνεδρεύοντος."}, {"sp": "N", "st": "Sir 29:1", "t": "Ὁ ποιῶν ἔλεος δανιεῖ τῷ πλησίον, καὶ ὁ ἐπισχύων τῇ χειρὶ αὐτοῦ τηρεῖ ἐντολάς."}, {"sp": "N", "st": "Sir 29:2", "t": "δάνισον τῷ πλησίον ἐν καιρῷ χρείας αὐτοῦ, καὶ πάλιν ἀπόδος τῷ πλησίον εἰς τὸν καιρόν·"}, {"sp": "N", "st": "Sir 29:3", "t": "στερέωσον λόγον καὶ πιστώθητι μετʼ αὐτοῦ, καὶ ἐν παντὶ καιρῷ εὑρήκεις τὴν χρείαν σου."}, {"sp": "N", "st": "Sir 29:4", "t": "εςολλοὶ ὡς εὕρεμα ἐνόμισαν δάνος, καὶ παρέσχον πόνον τοῖς βοηθήσασιν αὐτοῖς."}, {"sp": "N", "st": "Sir 29:5", "t": "ἕως οὗ λάβῃ, καταφιλήσει χεῖρα αὐτοῦ, καὶ ἐπὶ τῶν χρημάτων τοῦ πλησίον ταπεινώσει φωνὴν· (6)κρὶ ἐν καιρῷ ἀποδόσεως παρελκύσει χρόνον, καὶ ἀποδώσει λόγους ἀκηδίας καὶ τὸν καιροῦ αἰτιάσεται."}, {"sp": "N", "st": "Sir 29:6", "t": "ἐὰν ἰσχύσῃ, μόλις κομίσεται τὸ ἥμισυ καὶ λογιεῖται αὐτὸ ὡς εἰρεμα· (8)εἰ δὲ μή, ἀπεστέρησεν αὐτὸν τῶν χρημάτων αὐτοῦ, καὶ ἐκτήσατο αὐτὸν ἐχθρὸν οὐ δωρεάν· κατάρας καὶ λοιδορίας ἀποδώσει αὐτῷ, καὶ ἀντὶ δόξης ἀποδώσει αὐτῷ ἀτιμίαν."}, {"sp": "N", "st": "Sir 29:7", "t": "πολλοὶ χάριν πονηρίας ἀπέστρεψαν, ἀποστερηθῆναι δωρεὰν εὐλαβήθησαν."}, {"sp": "N", "st": "Sir 29:8", "t": "χ λῆν ἐπὶ ταπεινῷ μακροθύμησον, καὶ ἐπʼ ἐλεημοσύνην παρελκύσεις αὐτόνχάριν"}, {"sp": "N", "st": "Sir 29:9", "t": "ἐντολῆς ἀντιλαβοῦ πένητος, καὶ κατὰ τὴν ἔνδειαν αὐτοῦ μὴ ἀποστρέψῃς αὐτὸν κενόν."}, {"sp": "N", "st": "Sir 29:10", "t": "ἀπόλεσον ἀργύριον δι᾿ ἀδελφὸν καὶ φίλον, καὶ μὴ ἰωθήτω ὑπὸ τὸν λίθον εἰς ἀπωλίαν·"}, {"sp": "N", "st": "Sir 29:11", "t": "θὲς τὸν θησαυρόν σου κατʼ ἐντολὰς ὑψίστου, καὶ λυσιτελήσει σοι μᾶλλον ἤ τὸ χρυσίον."}, {"sp": "N", "st": "Sir 29:12", "t": "σύνκλεισον ἐλεημοσύνην ἐν τοῖς ταμείοις σου, καὶ αὕτη ἐξελεῖταί σε ἐκ πάσης κακώσεαος·"}, {"sp": "N", "st": "Sir 29:13", "t": "ὑπέρ ἀσπίδα κράτους καὶ ὑπὲρ δόρυ ἀλκῆς κατέναντι ἐχθροῦ πολεμήσει ὑπέρ σοῦ."}, {"sp": "N", "st": "Sir 29:14", "t": "ἀνήρ ἀγαθὸς ἐγγυήσεται τὸν πλησίον, καὶ ὁ ἀπολωλεκὼς αἰσχύνην καταλείψει αὐτόν."}, {"sp": "N", "st": "Sir 29:15", "t": "χάριτας ἐγγύου μὴ ἐπιλάθῃ, ἔδωκεν γὰρ τὴν ψυχὴν αὐτοῦ ὑπέρ σοῦ."}, {"sp": "N", "st": "Sir 29:16", "t": "ἀγαθὰ ἐγγύου ἀνατρέψει ἁμαρτωλός, καὶ ἀχάριστος ἐν διανοίᾳ ἐγκαταλείψει ῥυσάμενον."}, {"sp": "N", "st": "Sir 29:18", "t": "ἐγγύη πολλοὺς ἀπώλεσεν κατευθύνοντας, καὶ ἐσάλευσεν αὐτοὺς ὡς κῦμα θαλάσσης· (25)ἄνδρας δυνατοὺς ἀπᾠκισεν, καὶ ἐπλανήθησαν ἐν ἔθνεσιν ἀλλοτρίοις."}, {"sp": "N", "st": "Sir 29:19", "t": "ἁμαρτωλὸς ἐμπεσὼν εἰς ἐγγύην καὶ διώκαων ἐργολαβείας ἐμπεσεῖται εἰς κρίσεις."}, {"sp": "N", "st": "Sir 29:20", "t": "ἀντιλαβοῦ τοῦ πλησίον κατὰ δύναμίν σου, καὶ πρόσεχε σεαυτῷ μὴ ἐμπέσῃς."}, {"sp": "N", "st": "Sir 29:21", "t": "Ἀρχὴ ζωῆς ὕδωρ καὶ ἄρτος καὶ ἱμάτιον, καὶ οἶκος καλύπτων ἀσχημοσύνην."}, {"sp": "N", "st": "Sir 29:22", "t": "κρείσσων βίος πτωχοῦ ὑπὸ σκέπην δοκῶν ἡ ἐδέσματα λαμπρὰ ἐν ἀλλοτρίοις."}, {"sp": "N", "st": "Sir 29:23", "t": "ἐπὶ μικρῷ καὶ μεγάλῳ εὐδοκίαν ἔχεζωὴ"}, {"sp": "N", "st": "Sir 29:24", "t": "πονηρὰ ἐξ οἰκίας εἰς οἰκίαν, καὶ οὗ παροικήσει οὐκ ἀνοίξει στόμα·"}, {"sp": "N", "st": "Sir 29:25", "t": "ξενιεῖς καὶ ποτιεῖς εἰς ἀχάριστα, καὶ πρὸς ἐπὶ τούτοις πικρὰ ἀκούσῃ"}, {"sp": "N", "st": "Sir 29:26", "t": "Τάρελθε, πάροικε, κόσμησον τράπεζαν, καὶ εἵ τι ἐν τῇ χειρί σου ψώμισόν με·"}, {"sp": "N", "st": "Sir 29:27", "t": "ἔξελθε, πάροικε, ἀπὸ προσώπου δόξης, ἐπεξένωταί μοι ὁ ἀδελφός, χρεία τῆς ξενίας."}, {"sp": "N", "st": "Sir 29:28", "t": "βαρέα ταῦτα ἀνθρώπῳ ἔχοντι φρόνησιν, ἐπιτίμησις οἰκίας καὶ ὀνειδισμὸς δανιστοῦ. Περὶ τέκνων."}, {"sp": "N", "st": "Sir 30:1", "t": "Ὁ ἀγαπῶν τὸν υἱὸν αὐτοῦ ἐνδελεχήσει μάστιγας αὐτῷ, ἵνα εὐφρανθῇ ἐπʼ ἐσχάτων αὐτοῦ·"}, {"sp": "N", "st": "Sir 30:2", "t": "ὁ παιδεύων τὸν υἱὸν αὐτοῦ ὀνήσεται ἐπʼ αὐτῷ, καὶ ἀνὰ μέσον γνωρίμων ἐπʼ αὐτῷ καυχήσεται·"}, {"sp": "N", "st": "Sir 30:3", "t": "ὁ διδάσκων τὸν υἱὸν αὐτοῦ παραζηλώσει τὸν ἐχθρόν, καὶ ἔναντι φίλων ἐπʼ αὐτῷ ἀγαλλιάσεται."}, {"sp": "N", "st": "Sir 30:4", "t": "ἐτελεύτησεν αὐτοῦ ὁ πατήρ, καὶ ὥς οὐκ ἀπέθανεν, ὅμοιον γὰρ αὐτῷ κατέλιπεν μετʼ αὐτόν."}, {"sp": "N", "st": "Sir 30:5", "t": "ἐν τῆ ζωῇ αὐτοῦ εἶδεν καὶ εὐφράνθη, καὶ ἐν τῇ τελευτῇ αὐτοῦ οὐκ ἐλυπήθη·"}, {"sp": "N", "st": "Sir 30:6", "t": "ἐναντίον ἐχθρῶν κατέλιπεν ἔκδικον, καὶ τοῖς φίλοις ἀνταποδιδόντα χάριν."}, {"sp": "N", "st": "Sir 30:7", "t": "περὶ ψυχῶν υἱῶν καταδεσμεύσει τραύματα αὐτοῦ, καὶ ἐπὶ πάσῃ βοῇ ταραχθήσεται σπλάγχνα αὐτοῦ."}, {"sp": "N", "st": "Sir 30:8", "t": "8ἵπτ πος ἀδάμαστος ἀποβαίνει σκληρός, καὶ υἱὸς ἀνειμένος ἐκβαίνει προαλής."}, {"sp": "N", "st": "Sir 30:9", "t": "τιθήνησον τέκνον καὶ ἐκθαμβήσει σε, σύνπαιξον αὐτῷ καὶ λυπήσει σε."}, {"sp": "N", "st": "Sir 30:10", "t": "μὴ συνγελάσῃς αὐτῷ, ἵνα μὴ συνοδυνηθῇς, καὶ ἐπʼ ἐσχάτῳ γομφιάσεις τοὺς ὀδόντας σου."}, {"sp": "N", "st": "Sir 30:11", "t": "μὴ δῷς αὐτῷ ἐξουσίαν ἐν νεότητι·"}, {"sp": "N", "st": "Sir 30:12", "t": "ἡλάσον τὰς πλευρὰς αὐτοῦ ὡς ἔστιν νήπιος, μὴ ποτε σκληρυνθεὶς ἀπειθήσῃ σοι."}, {"sp": "N", "st": "Sir 30:13", "t": "παίδευσον τὸν υἱόν σου καὶ ἔργασαι ἐν αὐτῷ, ἵνα μὴ ἐν τῇ ἀσχημοσύνῃ σου προσκόψῃ."}, {"sp": "N", "st": "Sir 30:14", "t": "κρείσσων πτωχὸς ὑγιὴς καὶ ἰσχύων τῇ ἔξει ἤ πλούσιος μεμαστιγωμένος εἰς σῶμα αὐτοῦ."}, {"sp": "N", "st": "Sir 30:15", "t": "ὑγεία καὶ εὐεξία βελτίων παντὸς χρυσίου, καὶ σῶμα εἰρωστον ἤ ὄλβος ἀμέτρητος. Πεπἰ βρωμάτων."}, {"sp": "N", "st": "Sir 30:16", "t": "Οὐκ ἔστιν πλοῦτος βελτίων ὑγείας σώματος, καὶ οὐκ ἔστιν εὐφροσύνη ὑπέρ χαρὰν καρδίας."}, {"sp": "N", "st": "Sir 30:17", "t": "κρείσσων θάνατος ὑπέρ ζωὴν πικρὰν ἤ ἀρρώστημα ἔμμονον. ἀγαθὰ ἐκκεχυμένα ἐπὶ στόματι κεκλεισμένα, θέμα βρωμάτων παρακείμενα ἐπὶ τάφῳ."}, {"sp": "N", "st": "Sir 30:19", "t": "τί συμφέρει κάρπωσις εἰδώλῳς οὔτε γὰρ ἔδεται οδτε μὴ ὀσφρανθῆ· (20)οὕτως ὁ ἐκδιωκόμενος ὑπὸ Κυρίου."}, {"sp": "N", "st": "Sir 30:20", "t": "βλέπων ἐν ὀφθαλμοῖς καὶ στενάζων ὥσπερ εὐνοῦχος περιλαμβάνων παρθένον καὶ στενάζων."}, {"sp": "N", "st": "Sir 30:21", "t": "μὴ δῷς εἰς λύπην τὴν ψυχὴν σου, καὶ μὴ θλίψῃς σεαυτὸν ἐν βουλῇ σου."}, {"sp": "N", "st": "Sir 30:22", "t": "εὐφροσύνη καρδίας ζωὴ ἀνθρώπου, καὶ ἀγαλλίαμα ἀνδρὸς μακροημέρευσις."}, {"sp": "N", "st": "Sir 30:23", "t": "ἀγάπα τὴν ψυχὴν σου καὶ παρακάλει τὴν καρδίαν σου, καὶ λύπην μακρὰν ἀπόστησον ἀπὸ σοῦ· (25)_Φολλοὺς γὰρ ἀπέκτεινεν ἡ λύπη, καὶ οὐκ ἔστιν ὠφελία ἐν αὐτῇ."}, {"sp": "N", "st": "Sir 30:24", "t": "ζῆλος καὶ θυμὸς ἐλαττοῦσιν ἡμέρας. καὶ πρὸ καιροῦ γῆρας ἄγει μέριμνα."}, {"sp": "N", "st": "Sir 30:13b", "t": "bλαμπρὰ καρδία καὶ ἀγαθὴ ἐπὶ ἐδέσμασιν τῶν βρωμάτων αὐτῆς ἐπιμελήσεται."}, {"sp": "N", "st": "Sir 31:1", "t": "ἀγρυπνία πλούτου ἐκτήκει σάρκας, καὶ ἡ μέριμνα αὐτοῦ ἀφιστῷ ὕπνον·"}, {"sp": "N", "st": "Sir 31:2", "t": "μἐριμνα ἀγρυπνίας ἀπαιτήσει νυσταγμόν, καὶ ἀρρώστημα βαρὺ ἐκνήψει ὕπνον."}, {"sp": "N", "st": "Sir 31:3", "t": "ἐκοπίασεν πλούσιος ἐν συναγωγῇ χρημάτων, καὶ ἐυ τῇ ἀναπαύσει ἐμπίμπλαται τῶν τρυφημάτων αὐτοῦ·"}, {"sp": "N", "st": "Sir 31:4", "t": "ἐκοπίασεν πτωχὸς ἐν ἐλαττώσει βίου, καὶ ἐν τῇ ἀναπαύσει ἐπιδεὴς γίνεται."}, {"sp": "N", "st": "Sir 31:5", "t": "ὁ ἀγαπῶν χρυσίον οὐ δικαιωθήσεται, καὶ ὁ διώκων διαφθορὰν αὐτὸς πλησθήσεται."}, {"sp": "N", "st": "Sir 31:6", "t": "πολλοὶ ἐδόθησαν εἰς πτῶμα χάριν χρυσίου, καὶ ἐγενήθη ἀπώλεια αὐτῶν κατὰ πρόσωπον αὐτῶν."}, {"sp": "N", "st": "Sir 31:7", "t": "ξύλον προσκόμματός ἐστιν τοῖς ἐνθυσιάζουσιν αὐτῷ, καὶ πᾶς ἄφρων ἁλώσεται ἐν αὐτῷ."}, {"sp": "N", "st": "Sir 31:8", "t": "μακάριος πλούσιος ὅς εὑρέθη ἄμωμος, καὶ ὃς ὀπίσω χρυσίου οὐκ ἐπορεύθη·"}, {"sp": "N", "st": "Sir 31:9", "t": "τίς ἐστιν, καὶ μακαριοῦμεν αὐτόν; ἐποίησεν γὰρ θαυμάσια ἐν λαῷ αὐτοῦ."}, {"sp": "N", "st": "Sir 31:10", "t": "τἰς ἐδοκιμάσθη ἐν αὐτῷ καὶ ἐτελειώθη; καὶ ἔστω εἰς καύχησιν. τίς ἐδύνατο παραβῆναι καὶ οὐ παρέβη, καὶ ποιῆσαι κακὰ καὶ οὐκ ἐποίησεν;"}, {"sp": "N", "st": "Sir 31:11", "t": "στερεωθήσεται τὰ ἀγαθὰ αὐτοῦ, καὶ τὰς ἐλεημοσύνας αὐτοῦ ἐκδιηγήσεται ἐκκλησία."}, {"sp": "N", "st": "Sir 31:12", "t": "Ἐπὶ τραπέζης μεγάλης ἐκάθισας· μὴ ἀνοίξῃς ἐπʼ αὐτῆς τὸν φάρυγγά σου. (13)καὶ μὴ εἴπῃς Πολλά γε τὰ ἐπʼ αὐτῆς."}, {"sp": "N", "st": "Sir 31:13", "t": "μνήσθητι ὅτι κακὸν ὀφθαλμὸς πονηρός· (15)πονηρότερον ὀφθαλμοῦ τί ἔκτισται διὰ τοῦτο ἀπὸ παντὸς προσώπου δακρύει."}, {"sp": "N", "st": "Sir 31:14", "t": "οὑ ἐὰν ἐπιβλέψῃ, μὴ ἐκτείνῃς χεῖρα. (17)καὶ μὴ συνθλίβου αὐτῷ ἐν τρυβλίῳ."}, {"sp": "N", "st": "Sir 31:15", "t": "¹⁵υὁει τὰ τοῦ πλησίον ἐκ σεαυτοῦ, καὶ ἐπὶ παντὶ πράγματι διανοοῦ."}, {"sp": "N", "st": "Sir 31:16", "t": "φάγε ὡς ἄνθρωπος τὰ παρακείμενά σοι. καὶ μὴ διαμασῶ, μὴ μισηθῇς·"}, {"sp": "N", "st": "Sir 31:17", "t": "παῦσαι πρῶτος χάριν παιδείας, καὶ μὴ ἀπληστεύου, μὴ ποτε προσκόψῃς·"}, {"sp": "N", "st": "Sir 31:18", "t": "καὶ εἰ ἀνὰ μέσον πλειόνων ἐκάθισας, πρότερος αὐτῶν μὴ ἐκτείνῃς τὴν χεῖρά σου."}, {"sp": "N", "st": "Sir 31:19", "t": "ὡς ἱκανὸν ἀνθρώπῳ πεπαιδευμένῳ τὸ ὀλίγον, καὶ ἐπὶ τῆς κοίτης αὐτοῦ οὐκ ἀσθμαίνει."}, {"sp": "N", "st": "Sir 31:20", "t": "ὕπνος ὑγείας ἐπὶ ἐντέρῳ μετρίαφ ἀνέστη πρωί, καὶ ἡ ψυχὴ αὐτοῦ μετʼ αὐεοῦ· (23)πόνος ἀγρυπνίας καὶ χολέρας καὶ στρόφος μετὰ ἀνδρὸς ἀπλήστου."}, {"sp": "N", "st": "Sir 31:21", "t": "καὶ εἰ ἐβιάσθης ἐν ἐδέσμασιν, ἀνάστα μεσοπορῶν, καὶ ἀναπαύσῃ."}, {"sp": "N", "st": "Sir 31:22", "t": "ἄκουσόν μου, τέκνον, καὶ μὴ ἐξουδενήσῃς με, καὶ ἐπʼ ἐσχάτῳ εὑρήκεις τοὺς λόγους μου. (27)ἐν πᾶσι τοῖς ἔργοις σου γίνου ἐντρεχής. καὶ πᾶν ἀρρώστημα οὐ μή σοι ἀπαντήσῃ."}, {"sp": "N", "st": "Sir 31:23", "t": "λαμπρὸν ἐπʼ ἄρτοις εὐλογήσει χείλη, καὶ μαρτυρία τῆς καλλονῆς αὐτοῦ πιστή·"}, {"sp": "N", "st": "Sir 31:24", "t": "πονηρῷ ἐπʼ ἄρτῳ διαγογγύσει πόλις, καὶ ἡ μαρτυρία τῆς πονηρίας αὐτοῦ ἀκριβής."}, {"sp": "N", "st": "Sir 31:25", "t": "Ἐν οἴνῳ μὴ ἀνδρίζου. πολλοὺς γὰρ ἀπὼλεσεν ὁ οἶνος·"}, {"sp": "N", "st": "Sir 31:26", "t": "κάμινος δοκιμάζει στόμωμα ἐν βαφῇ, οὕτως οἶνος καρδίας ἐν μάχῃ ὑπερηφάνων."}, {"sp": "N", "st": "Sir 31:27", "t": "ἔφισον ζωῆς οἶνος ἀνθρώπᾳῳ, ἐὰν πίνῃς αὐτὸν μέτρῳ αὐτοῦ· ᵃ³τἰς ζωὴ ἐλασσουμένῳ οἴνῳ (35)καὶ αὐτὸς ἔκτισται εἰς εὐφροσύνην ἀνθρώποις."}, {"sp": "N", "st": "Sir 31:28", "t": "ἀγαλλίαμα καρδίας καὶ εὐφροσύνη ψυχῆς οἶνος πινόμενος ἐυ καιρῷ αὐτάρκης·"}, {"sp": "N", "st": "Sir 31:29", "t": "πικρία ψυχῆς οἶνος πινόμενος πολὺς ἐν ἐρεθισμῷ καὶ ἀντιπτώματι."}, {"sp": "N", "st": "Sir 31:30", "t": "πληθύνει μέθη θυμὸν ἄφρονος εἰς πρόσκομμα. ἐλαττῶν ἰσχὺν καὶ προσποιῶν τραύματα."}, {"sp": "N", "st": "Sir 31:31", "t": "ἐν συμποσίῳ οἴνου μὴ ἐλέγξῃς τὸν πλησίον, καὶ μὴ ἐξουθενήσῃς αὐτὸν ἐν εὐφροσύνῃ αὐτοῦ· (42)λόγον ὀνειδισμοῦ μὴ εἶπῃς αὐτῷ, καὶ μὴ αὐτὸν θλίψῃς ἐν ἀπαιτήσει."}, {"sp": "N", "st": "Sir 32:1", "t": "Ἡγούμενόν σε κατέστησαν ; μὴ ἐπαίρου· γίνου ἐν αὐτοῖς ὡς εἰς ἐξ αὐτῶν, (2)φρόντισον αὐτῶν καὶ οὕτω κάθισον·"}, {"sp": "N", "st": "Sir 32:2", "t": "καὶ πᾶσαυ τὴν χρείαν σου ποιήσας ἀνάπεσε, (3)ἵα εὐφρανθῇς δι᾿ αὐτούς, καὶ εὐκοσμίας χάριν λάβῃς στέφανον."}, {"sp": "N", "st": "Sir 32:3", "t": "Λάλησον, πρεσβύτερε, πρέπει γάρ σοι, (5)ἐν ἀκριβεῖ ἐπιστήμῃ, καὶ μὴ ἐμποδίσῃς μουσικά."}, {"sp": "N", "st": "Sir 32:4", "t": "ὅπου ἀκρόαμα, μὴ ἐκχέῃς λαλιάν, καὶ ἀκαίρως μὴ σοφίζου."}, {"sp": "N", "st": "Sir 32:5", "t": "σφραγὶς ἄνθρακος ἐπὶ κόσμῳ χρυσῷ, σύγκριμα μουσικῶν ἐυ συμποσίῳ οἴυου·"}, {"sp": "N", "st": "Sir 32:6", "t": "ἐν κατασκευάσματι χρυσῷ σφραγὶς σμαράγδου, μέλος μουσικῶν ἐφʼ ἡδεῖ οἴνῳ."}, {"sp": "N", "st": "Sir 32:7", "t": "λάλησον, νεανίσκε, εί χρεία σου, (¹¹)μόλις δὶς ἐὰν ἐπερωτηθῇς·"}, {"sp": "N", "st": "Sir 32:8", "t": "κεφαλαίωσον λόγον, ἐν ὀλίγοις πολλά· γίνου ὡς γινόσκων καὶ ἅμα σιωπῶν."}, {"sp": "N", "st": "Sir 32:9", "t": "ἐν μέσᾳῳ μεγιστάνων μὴ ἐξισάζου, καὶ ἑτέρου λέγοντος μὴ πολλὰ ἀδολέσχει."}, {"sp": "N", "st": "Sir 32:10", "t": "πρὸ βροντῆς κατασπεύδει ἀστραπή, καὶ πρὸ αἰσχυντηροῦ προελεύσεται χάρις."}, {"sp": "N", "st": "Sir 32:11", "t": "ἐν ὥρᾳ ἐξεγείρου καὶ μὴ οὐράγει. ἀπότρεχε εἰς οἶκον καὶ μὴ ὸᾳθύμει·"}, {"sp": "N", "st": "Sir 32:12", "t": "ἐκεῖ παῖζε καὶ ποίει τὰ ἐνθυμήματά σου, καὶ μὴ ἁμάρτῃς λόγῳ ὑπερηφάνῳ."}, {"sp": "N", "st": "Sir 32:13", "t": "καὶ ἐπὶ τούτοις εὐλόγησον τὸν ποιήσαντά σε καὶ μεθύσκοντά σε ἀπὸ τῶν ἀγαθῶν αὐτοῦ."}, {"sp": "N", "st": "Sir 32:14", "t": "Ὁ φοβούμενος Κύριον ἐκδέξεται παιδίαν, καὶ οἱ ὀρθρίζοντες εὑρήσουσιν εὐδοκίαν·"}, {"sp": "N", "st": "Sir 32:15", "t": "ὁ ζητῶν νόμον ἐμπλησθήσεται αὐτοῦ, καὶ ὁ ὑποκρινόμενος σκανδαλισθήσεται ἐν αὐτῷ·"}, {"sp": "N", "st": "Sir 32:16", "t": "οἱ φοβούμενοι Κύριον είρήσουσιν κρίμα. καὶ δικαιώματα ὡς φῶς ἐξάψουσιν."}, {"sp": "N", "st": "Sir 32:17", "t": "ἄνθρωπος ἁμαρτωλὸς ἐκκλινεῖ ἐλεγμόν, καὶ κατὰ τὸ θέλημα αὐτοῦ εὑρήσει σύγκριμα."}, {"sp": "N", "st": "Sir 32:18", "t": "ἀνὴρ βουλῆς οὐ μὴ παρίδῃ διανόημα. ἀλλότριος καὶ ὑπερήφανος οὐ καταπτήξει φόβον, (23)καὶ μετὰ τὸ ποιῆσαι μετʼ αὐτοῦ ἄνευ βουλῆς."}, {"sp": "N", "st": "Sir 32:19", "t": "ἄνευ βουλῆς μηθὲν ποιήσῃς. καὶ ἐν τῷ ποιῆσαί σε μὴ μεταμελοῦ."}, {"sp": "N", "st": "Sir 32:20", "t": "ἐν ὁδῷ ἀντιπτώματος μὴ πορεύου, καὶ μὴ προσκόψῃς ἐν λιθώδεσιν·"}, {"sp": "N", "st": "Sir 32:21", "t": "μὴ πιστεύσῃς ἐν ὁδῷ ἀπροσκόπῳ,"}, {"sp": "N", "st": "Sir 32:22", "t": "καὶ ἀπὸ τῶν τέκνων σου φύλαξαι."}, {"sp": "N", "st": "Sir 32:23", "t": "ἐν παντὶ ἔργῳ πίστευε τῇ ψυχῇ σου, καὶ γὰρ τοῦτό ἐστιν τήρησις ἐντολῶν."}, {"sp": "N", "st": "Sir 32:24", "t": "ὁ πιστεύων νόμῳ προσέχει ἐντολαῖς, καὶ ὁ πεποιθὰς Κυρίῳ οὐκ ἐλαττωθήσεται."}, {"sp": "N", "st": "Sir 33:1", "t": "τῷ φοβουμένῳ Κύριον οὐκ ἀπαντήσει κακόν, ἀλλʼ ἐν πειρασμῷ καὶ πάλιν ἐξελεῖται."}, {"sp": "N", "st": "Sir 33:2", "t": "ἀνὴρ σοφὸς οὐ μισήσει νόμον, ὁ δὲ ὑποκρινόμενος ἐν αὐτῷ ὡς ἐν καταιγίδι πλοῖον."}, {"sp": "N", "st": "Sir 33:3", "t": "ἄυθρωπος συνετὸς ἐνπιστεύσει νόμῷ, καὶ ὁ νόμος αὐτῷ πιστὸς (4)ὡς ἐρώτημα δικαίων."}, {"sp": "N", "st": "Sir 33:4", "t": "ἑτοίμασον λόγον καὶ οὕτως ἀκουσθήσῃ, σύνδησον παιδείαν καὶ ἀποκρίθητι."}, {"sp": "N", "st": "Sir 33:5", "t": "τροχὸς ἁμάξης σπλάγχνα μωροῦ, καὶ ὡς ἄξων στρεφόμενος ὁ διαλογισμὸς αὐτοῦ."}, {"sp": "N", "st": "Sir 33:6", "t": "ζππος εἰς ὀχείαν ὡς φίλος μῶκος, ὑποκάτω παντὸς ἐπικαθημένου χρεμετίζει."}, {"sp": "N", "st": "Sir 33:7", "t": "διὰ τί ἡμέρα ἡμέρας ὑπερέχει, καὶ πᾶν φῶς ἡμέρας ἐνιαυτοῦ ἀφʼ ἡλἰου;"}, {"sp": "N", "st": "Sir 33:8", "t": "ἐν γνώσει Κυρίου διεχωρίσθησαν, καὶ ἠλλοίωσεν καιροὺς καὶ ἑορτάς·"}, {"sp": "N", "st": "Sir 33:9", "t": "ἀπʼ αὐτῶν ἀνύψωσεν καὶ ἡγίασεν, καὶ ἐξ αὐτῶν ἔθηκεν εἰς ἀριθμὸν ἡμερῶν."}, {"sp": "N", "st": "Sir 33:10", "t": "καὶ ἄνθρωποι πάντες ἀπὸ ἐδάφους, καὶ ἐκ γῆς ἐκτἰσθη Ἀδάμ·"}, {"sp": "N", "st": "Sir 33:11", "t": "ἐν πλήθει ἐπιστήμης Κύριος διεχώρισεν αὐτούς, καὶ ἠλλοίωσεν τὰς ὁδοὺς αὐτῶν·"}, {"sp": "N", "st": "Sir 33:12", "t": "ἐξ αὐτῶν εὺλόγησεν καὶ ἀνύψωσεν, καὶ ἐξ αὐτῶν ἡγίασεν καὶ πρὸς αὐτὸν ἤγισεν· ἀπʼ αὐτῶν κατηράσατο καὶ ἐταπείνωσεν, καὶ ἀνέστρεψεν αὐτοὺς ἀπὸ στάσεως αὐτῶν."}, {"sp": "N", "st": "Sir 33:13", "t": "ὡς πηλὸς κεραμέως ἐν χειρὶ αὐτοῦ, (14)πᾶσαι αἱ ὁδοὶ αὐτοῦ κατὰ τὴν εὐδοκίαν αὐτοῦ· οὕτως ἄνθρωποι ἐν χειρὶ τοῦ ποιήσαντος αὐτούς, ἀποδοῦναι αὐτοῖς κατὰ τὴν κρίσιν αὐτοῦ."}, {"sp": "N", "st": "Sir 33:14", "t": "ἀπέναντι τοῦ κακοῦ τὸ ἀγαθόν, καὶ ἀπέναντι τοῦ θανάτου ἡ ζωή· οὕτως ἀπέναντι εὐσεβοῦς ἁμαρτωλός."}, {"sp": "N", "st": "Sir 33:15", "t": "καὶ οὕτως ἔμβλεψον εἰς πάντα τὰ ἔργα τοῦ ὑψίστου, δύο δύο, ἕν κατέναντι τοῦ ἑνός."}, {"sp": "N", "st": "Sir 33:16a", "t": "a Κἀγὼ ἔσχατος ἠγρύπνησα,"}, {"sp": "N", "st": "Sir 33:25", "t": "²⁵ὡς καλαμώμενος ὀπίσω τρυγητῶν· (17)ἐν εὐλογίᾳ Κυρίου ἔφθασα, καὶ ὡς τρυγῶν ἐπλήρωσα ληνόν."}, {"sp": "N", "st": "Sir 33:26", "t": "κατανοήσατε ὅτι οὐκ ἐμοὶ μόνῳ ἐκοπίασα, ἀλλὰ πᾶσιν τοῖς ζητοῦσιν παιδείαν."}, {"sp": "N", "st": "Sir 33:27", "t": "ἀκούσατέ μου, μεγιστᾶνες λαοῦ, καὶ οἱ ἡγούμενοι ἐκκλησίας, ἐναοτίσασθε."}, {"sp": "N", "st": "Sir 33:28", "t": "υἱῷ καὶ γυναικί, ἀδελφῷ καὶ φίλῳ μὴ δῷς ἐξουσίαν ἐπὶ σὲ ἐν ζωῇ σου· καὶ μὴ δῷς ἑτέρῳ τὰ χρῆματά σου, ἵνα μὴ μεταμεληθεὶς δέῃ περὶ αὐτῶν."}, {"sp": "N", "st": "Sir 33:29", "t": "ἕως ἔτι ζῆς καὶ πνοὴ ἐν σοί, μὴ ἀλλάξῃς σεαυτὸν πάσῃ σαρκί."}, {"sp": "N", "st": "Sir 33:30", "t": "κρεῖσσον γάρ ἐστιν τὰ τέκνα δεηθῆναί σου ἡ σὲ ἐμβλέπειν εἰς χεῖρας υἱῶν σου."}, {"sp": "N", "st": "Sir 33:31", "t": "ἐν πᾶσι τοῖς ἔργοις σου γίνου ὑπεράγαν, μὴ δῷς μῶμον ἐν τῇ δόξῃ σου."}, {"sp": "N", "st": "Sir 33:32", "t": "ἐν ἡμέρᾳ συντελείας ἡμερῶν ζωῆς σου καὶ ἐν καιρῷ τελευτῆς διάδος κληρονομίαν."}, {"sp": "N", "st": "Sir 33:33", "t": "χορτάσματα καὶ ῥάβδος καὶ φορτία ὄνῳ, ἄρτος καὶ παιδεία καὶ ἔργον οἰκέτῃ."}, {"sp": "N", "st": "Sir 33:34", "t": "ἔργασαι ἐν παιδί, καὶ εὑρήσεις ἀνάπαυσιν· ἄνες χεῖρας αὐτῷ, καὶ ζητήσει ἐλευθερίαν."}, {"sp": "N", "st": "Sir 33:35", "t": "ζυγὸς καὶ ἱμὰς κάμψουσιν τράχηλον, καὶ οἰκέτῃ κακούργῳ στρέβλαι καὶ βάσανοι·"}, {"sp": "N", "st": "Sir 33:36", "t": "μβαλε αὐτὸν εἰς ἐργασίαν, ἴνα μὴ ἀργῇ."}, {"sp": "N", "st": "Sir 33:37", "t": "πολλὴν γαρ κακίαν ἐδίδαξεν ἡ ἀργία·"}, {"sp": "N", "st": "Sir 33:38", "t": "εἰς ἔργα κατάστησον καθὼς πρέπει αὐτῷ, κἂν μὴ πειθαρχῇ, βάρυνον τὰς πέδας αὐτοῦ. καὶ μὴ περισσεύσῃς ἐν πάσῃ σαρκί, καὶ ἄνευ κρίσεως μὴ ποιήσῃς μηδέν."}, {"sp": "N", "st": "Sir 33:39", "t": "τἰ ἔστιν σοι οἰκέτης, ἔστω ὡς σύ, ὅτι ἐν αἵματι ἐκτήσω αὐτόν· εἰ ἔστιν σοι οἰκέτης, ἄγε αὐτὸν ὡς σεαυτόν, ὅτι ὡς ἡ ψυχή σου ἐπιδέησις αὐτῷ·"}, {"sp": "N", "st": "Sir 33:40", "t": "ἐὰν κακώσῃς αὐτὸν καὶ ἀπάρας ἀποδρῶ, (33)ἐν ποἰᾳ ὁδῷ ζητήσεις αὐτόν;"}, {"sp": "N", "st": "Sir 34:1", "t": "Κεναὶ ἐλπίδες καὶ ψευδεῖς ἀσυνέτῳ ἀνδρί, καὶ ἐνύπνια ἀναπτεροῦσιν ἄφρονας."}, {"sp": "N", "st": "Sir 34:2", "t": "ὁὡς δρασσόμενος σκιᾶς καὶ διώκων ἄνεμον, οὕτως ὁ ἐπέχων ἐνυπνίοις·"}, {"sp": "N", "st": "Sir 34:3", "t": "τοῦτο κατὰ τούτου ὅρασις ἐνυπνίων, κατέναντι προσώπου ἁμοίαομα προσώπου."}, {"sp": "N", "st": "Sir 34:4", "t": "ἀπὸ ἀκαθάρτου τί καθαρισθήσεται; καὶ ἀπὸ ψευδοῦς τί ἀληθεύσεις"}, {"sp": "N", "st": "Sir 34:5", "t": "μαντεῖαι καὶ οἰωνισμοὶ καὶ ἐνύπνια μάταιά ἐστιν, (6)καὶ ὡς ὠδινούσης φαντάζεται καρδία"}, {"sp": "N", "st": "Sir 34:6", "t": "ἐὰν μὴ παρὰ Ὑψίστου ἀποσταλῇ ἐν ἐπισκοπῇ, μὴ δῷς εἰς αὐτὰ τὴν καρδίαν σου·"}, {"sp": "N", "st": "Sir 34:7", "t": "πολλοὺς ἐπλάνησεν τὰ ἐνύπνια, καὶ ἐξέπεσον ἐλπίζοντες ἐπʼ αὐτοῖς."}, {"sp": "N", "st": "Sir 34:8", "t": "ἄνευ ψεύδους συντελεσθήσεται νόμος, καὶ σοφία στόματι πιστῷ τελείωσις."}, {"sp": "N", "st": "Sir 34:9", "t": "Ἀνήρ πεπαιδευμένος ἔγνω πολλά, καὶ ὁ πολύπειρος ἐκδιηγήσεται σύνεσιν·"}, {"sp": "N", "st": "Sir 34:10", "t": "ὅς οὐκ ἐπειράθη ὀλίγα οἶδεν,"}, {"sp": "N", "st": "Sir 34:11", "t": "δὲ πεπλανημένος πληθυνεῖ πανουργίαν."}, {"sp": "N", "st": "Sir 34:12", "t": "πολλὰ ἑώρακα ἐν τῇ ἀποπλανήσει μου, καὶ πλείονα τῶν λόγων μου σύνεσίς μου·"}, {"sp": "N", "st": "Sir 34:13", "t": "πλεονάκις ἕως θανάτου ἐκινδύνευσα, καὶ διεσώθην τούτων χάριν."}, {"sp": "N", "st": "Sir 34:14", "t": "πνεῖμα φοβουμένων Κύριον ζήσεται,"}, {"sp": "N", "st": "Sir 34:15", "t": "ἡ γὰρ ἐλπὶς αὐτῶν ἐπὶ τὸν σώζοντα αὐτούς·"}, {"sp": "N", "st": "Sir 34:16", "t": "ό φοβούμενος Κύριον οὐ μὴ εὐλαβηθήσεται, καὶ οὐ μὴ δειλιάσει, ὅτι αὐτὸς ἐλπὶς αὐτοῦ."}, {"sp": "N", "st": "Sir 34:17", "t": "φοβουμένου τὸν κύριον μακαρία ἡ ψυχή·"}, {"sp": "N", "st": "Sir 34:18", "t": "τίνι ἐπέχεις καὶ τίς ἀντιστήριγμα αὐτοῦ"}, {"sp": "N", "st": "Sir 34:19", "t": "οἱ ὀφθαλμοὶ Κυρίου ἐπὶ τοὺς ἀγαπῶντας αὐτόν, ὑπερασπισμὸς δυναστείας καὶ στήριγμα ἰσχύος, σκέπη ἀπὸ καύσαωνος καὶ σκέπη ἀπὸ μεσημβρίας, (20)φυλακὴ ἀπὸ προσκόμματος καὶ βοήθεια ἀπὸ πτώματος·"}, {"sp": "N", "st": "Sir 34:20", "t": "ἀνυψῶν ψυχὴν καὶ φωτίζων ὀφθαλμούς, ἴασιν διδοὺς ζωὴν καὶ εὐλογίαν."}, {"sp": "N", "st": "Sir 34:21", "t": "ᵇυσιάζων ἐξ ἀδίκου, προσφορὰ μεμαοκημένη."}, {"sp": "N", "st": "Sir 34:22", "t": "καὶ οὐκ εἰς εὐδοκίαν μωκήματα ἀνόμων·"}, {"sp": "N", "st": "Sir 34:23", "t": "οὐκ εὐδοκεῖ ὁ ὕψιστος ἐν προσφοραῖς ἀσεβῶν, οὐδὲ ἐν πλήθει θυσιῶν ἐξιλάσκεται ἁμαρτίας"}, {"sp": "N", "st": "Sir 34:24", "t": "ἡύωυ υἱὸν ἔναντι τοῦ πατρὸς αὐτοῦ ὁ προσάγων θυσίαν ἐκ χρημάτων πενήτων."}, {"sp": "N", "st": "Sir 34:25", "t": "ἄρτος ἐπιδεομένων ζωὴ πτωχῶν. ὁ ἀποστερῶν αὐτὴν ἄνθρωπος αἱμάτων·"}, {"sp": "N", "st": "Sir 34:26", "t": "φονεύων τὸν πλησίον ὁ ἀφαιρούμενος συμβίωσιν,"}, {"sp": "N", "st": "Sir 34:27", "t": "καὶ ἐκχέων αἶμα ὁ ἀποστερῶν μισθὸν μισθίου."}, {"sp": "N", "st": "Sir 34:28", "t": "εἴς οἰκοδομῶν καὶ εἶς καθαιρῶν, τί ὥφέλησαν πλεῖον ἦ κόπου;"}, {"sp": "N", "st": "Sir 34:29", "t": "εἶς εὐχόμενος καὶ εἴς καταρώμενος, τίνος φωνῆς εἰσακούσεται ὁ δεσπότης;"}, {"sp": "N", "st": "Sir 34:30", "t": "βαπτιζόμενος ἀπὸ νεκροῦ καὶ πάλιν ἁπτόμενος αὐτοῦ, τί ὠφέλησεν τῷ λουτρῷ αὐτοῦ;"}, {"sp": "N", "st": "Sir 34:31", "t": "οὕτως ἄνθρωπος νηστεύων ἐπὶ τῶν ἁμαρτιῶν αὐτοῦ καὶ πάλιν πορευόμενος καὶ τὰ αὐτὰ ποιῶν· τῆς προσευχῆς αὐτοῦ τίς εἰσακούσεται καὶ τί φέλησεν ἐν τῷ ταπεινωθῆναι αὐτόν"}, {"sp": "N", "st": "Sir 35:1", "t": "Ὁ συντηρῶν νόμον πλεονάζει συμφοράς,"}, {"sp": "N", "st": "Sir 35:2", "t": "θυσιάζων σαοτηρίου ὁ προσέχων ἐντολαῖς·"}, {"sp": "N", "st": "Sir 35:3", "t": "ἀνταποδιδοὺς χάριν προσφέρων σεμίδαλιν,"}, {"sp": "N", "st": "Sir 35:4", "t": "καὶ ὁ ποιῶν ἐλεημοσύνην θυσιάζων αἰνέσεως."}, {"sp": "N", "st": "Sir 35:5", "t": "εὐδοκία Κυρίου ἀποστῆναι ἀπὸ πονηρίας, καὶ ἐξιλασμὸς ἀποστῆναι ἀπὸ ἀδικίας."}, {"sp": "N", "st": "Sir 35:6", "t": "μὴ ὀφθῇς ἐν προσώπῳ Κυρίου κενός,"}, {"sp": "N", "st": "Sir 35:7", "t": "πάντα γὰρ ταῦτα χάριν ἐντολῆς."}, {"sp": "N", "st": "Sir 35:8", "t": "προσφορὰ δικαίου λιπαίνει θυσιαστήριον, καὶ ἡ εὐωδία αὐτῆς ἔναντι Γψἰστου"}, {"sp": "N", "st": "Sir 35:9", "t": "θυσία ἀνδρὸς δικαίου δεκτή, καὶ τὸ μνημόσυνον αὐτῆς οὐκ ἐπιλησθήσεται."}, {"sp": "N", "st": "Sir 35:10", "t": "ἐν ἀγαθῷ ὀφθαλμῷ δόξασον τὸν κύριον, καὶ μὴ μικρύνῃς ἀπαρχὴν χειρῶν σου·"}, {"sp": "N", "st": "Sir 35:11", "t": "ἐν πάσῃ δόσει ἱλάρωσον τὸ πρόσωπόν σου, καὶ ἐν εὐφροσύνῃ ἁγίασον δεκάτην."}, {"sp": "N", "st": "Sir 35:12", "t": "δὸς Γψίστῳ κατὰ τὴν δόσιν αὐτοῦ, καὶ ἐν ἀγαθῷ ὀφθαλμῷ καθʼ εὕρεμα χειρός·"}, {"sp": "N", "st": "Sir 35:13", "t": "ὅτι Κύριος ἀνταποδιδοὺς ἐστιν, καὶ ἑπταπλᾶ ἀνταποδώσει σοι."}, {"sp": "N", "st": "Sir 35:14", "t": "μὴ δωροκόπει, οὐ γὰρ προσδέξεται"}, {"sp": "N", "st": "Sir 35:15", "t": "καὶ μὴ ἔπεχε θυσίᾳ ἀδίκῳ, ὅτι Κύριος κριτής ἐστιν, καὶ οὐκ ἔστιν παρʼ αὐτῷ δόξα προσώπου."}, {"sp": "N", "st": "Sir 35:16", "t": "οὐ λήμψεται πρόσωπον ἐπὶ πτωχοί, καὶ δέησιν ἠδικημένου εἰσακούσεται·"}, {"sp": "N", "st": "Sir 35:17", "t": "οὐ μὴ ὑπερίδῃ ἱκετἰαν ὀρφανοῦ, καὶ χήραν ἐὰν ἐκχέῃ λαλιάν."}, {"sp": "N", "st": "Sir 35:18", "t": "οὐχὶ δάκρυα χήρας ἐπὶ σιαγόνα καταβαίνει,"}, {"sp": "N", "st": "Sir 35:19", "t": "καὶ ἡ καταβόησις ἐπὶ τῷ καταγαγόντι αὐτά"}, {"sp": "N", "st": "Sir 35:20", "t": "θεραπεύων ἐν εὐδοκίᾳ δεχθήσεται, καὶ ἡ δέησις αὐτοῦ ἕως νεφελῶν συνάψει·"}, {"sp": "N", "st": "Sir 35:21", "t": "προσευχὴ ταπεινοῦ νεφέλας διῆλθεν, καὶ ἕως συνεγγίσῃ, οὐ μὴ παρακληθῇ· καὶ οὐ μὴ ἀποστῇ ἕως ἐπισκέψηται ὁ ὕψιστος,"}, {"sp": "N", "st": "Sir 35:22", "t": "καὶ κρινεῖ δικαίως καὶ ποιήσει κρίσιν. καὶ ὁ κύριος οὐ μὴ βραδύνῃ οὐδὲ μὴ μακροθυμήσει ἐπʼ αὐτοῖς, ἕως ἂν συντρίψῃ ὀσφὺν ἀνελεημόνων,"}, {"sp": "N", "st": "Sir 35:23", "t": "καὶ τοῖς ἔθνεσιν ἀνταποδώσει ἐκδίκησιν· ἕως ἐξάρῃ πλῆθος ὑβριστῶν καὶ σκῆπτρα ἀδίκαων συντρίψει·"}, {"sp": "N", "st": "Sir 35:24", "t": "ἕως ἀνταποδῷ ἀνθρώπῳ κατὰ τὰς πράξεις αὐτοῦ, καὶ τὰ ἔργα τῶν ἀνθρώπων κατὰ τὰ ἐνθυμήματα αὐτῶν·"}, {"sp": "N", "st": "Sir 35:25", "t": "ἕως κρίνῃ τὴν κρίσιν τοῦ λαοῦ αὐτοῦ καὶ εὐφρανεῖ αὐτοὺς ἐν τῷ ἐλέει αὐτοῦ."}, {"sp": "N", "st": "Sir 35:26", "t": "ώραῖον ἔλεος ἐν καιρῷ θλίψεως αὐτοῦ, ὡς νεφέλαι ὑετοῦ ἐν καιρῷ ἀβροχίας"}, {"sp": "N", "st": "Sir 36:1", "t": "Ἐλέησον ἡμᾶς, δέσποτα ὁ θεὸς πάντων,"}, {"sp": "N", "st": "Sir 36:2", "t": "καὶ ἐπίβλεψον, (2)καὶ ἐπίβαλε τὸν φόβον σου ἐπὶ πάντα τὰ ἔθνη·"}, {"sp": "N", "st": "Sir 36:3", "t": "ἔπαρον τὴν χεῖρά σου ἐπὶ ἔθνη ἀλλότρια, καὶ ἰδέτωσαν τὴν δυναστείαν σου."}, {"sp": "N", "st": "Sir 36:4", "t": "ὥσπερ ἐνώπιον αὐτῶν ἡγιάσθης ἐν ἡμίν, οὕτως ἐνώπιον ἡμῶν μεγαλυνθείης ἐν αὐτοῖς·"}, {"sp": "N", "st": "Sir 36:5", "t": "καὶ ἐπιγνώτωσάν σε καθάπερ καὶ ἡμεῖς ἐπέγνωμεν, ὅτι οὐκ ἔστιν θεὸς πλὴν σοῦ, Κύριε."}, {"sp": "N", "st": "Sir 36:6", "t": "ἐγκαίνισον σημεῖα καὶ ἀλλοίωσον θαυμάσια,"}, {"sp": "N", "st": "Sir 36:7", "t": "δόξασον χεῖρα καὶ βραχίονα δεξιόν·"}, {"sp": "N", "st": "Sir 36:8", "t": "ἔγειρον θυμὸν καὶ ἔκχεον ἀργήν,"}, {"sp": "N", "st": "Sir 36:9", "t": "ἔξαρον ἀντίδικον καὶ ἔκτριψον ἐχθρόν."}, {"sp": "N", "st": "Sir 36:10", "t": "σπεῦσον καιρὸν καὶ μνήσθητι ὁρκισμοῦ, καὶ ἐκδιηγησάσθωσαν τὰ μεγαλεῖά σου."}, {"sp": "N", "st": "Sir 36:11", "t": "ἐν ἀργῇ πυρὸς καταβρωθήτω ὁ σωζόμενος, καὶ οἱ ἀδικοῦντες τὸν λαόν σου εῦροισαν ἀπώλειαν."}, {"sp": "N", "st": "Sir 36:12", "t": "σύντριψον κεφαλὰς ἀρχόντων ἐχθρῶν, λεγόντων Οὐκ ἔστιν πλὴν ἡμῶν."}, {"sp": "N", "st": "Sir 36:13a", "t": "σύναγε πάσας φυλὰς Ἰακώβ,"}, {"sp": "N", "st": "Sir 36:16b", "t": "bκαὶ κατακληρονομήσεις αὐτοὺς καθὼς ἀπʼ ἀρχῆς."}, {"sp": "N", "st": "Sir 36:17", "t": "ἐλέησον λαόν, Κύριε, κεκλημένον ἐπʼ ὀνόματί σου, καὶ Ἰσραὴλ ὃν πρωτογόνῳ ὡμοίωσας."}, {"sp": "N", "st": "Sir 36:18", "t": "οἰκτείρησον πόλιν ἁγιάσματός σου, Ἰερουσαλήμ, πόλιν καταπαύματός σου·"}, {"sp": "N", "st": "Sir 36:19", "t": "πλῆσον Σιὼν ἀρεταλογίας σου, καὶ ἀπὸ τῆς δόξης σου τὸν λαόν σου."}, {"sp": "N", "st": "Sir 36:20", "t": "δὸς μαρτύριον τοῖς ἐν ἀρχῇ κτίσμασίν σου, καὶ ἔγειρον προφητείας τὰς ἐπʼ ὀνόματί σου·"}, {"sp": "N", "st": "Sir 36:21", "t": "δὸς μισθὸν τοῖς ὑπομένουσίν σε, καὶ οἱ προφῆταί σου ἐμπιστευθήταωσαν."}, {"sp": "N", "st": "Sir 36:22", "t": "κἰσάκουσον, Κύριε, δεήσεως τῶν ἱκετῶν σου (19)κατὰ τὴν εὐλογίαν Ἀαρὼν περὶ τοῦ λαοῦ σου, καὶ γνώσονται πάντες οἱ ἐπὶ τῆς γῆς ὅτι Κύριος εἶ, ὁ θεὸς τῶν αἰώνων."}, {"sp": "N", "st": "Sir 36:23", "t": "Τᾶν βρῶμα φάγεται κοιλία, ἔστιν δὲ βρῶμα βρώματος κάλλιον."}, {"sp": "N", "st": "Sir 36:24", "t": "φάρυγξ γεύεται βρώματα θήρας. οὕτως καρδία συνετὴ λόγους ψευδεῖς."}, {"sp": "N", "st": "Sir 36:25", "t": "καρδία στρεβλὴ δώσει λύπην, καὶ ἄνθρωπος πολύπειρος ἀνταποδώσει αὐτῷ."}, {"sp": "N", "st": "Sir 36:26", "t": "πάντα ἄρρενα ἐπιδέξεται γυνή, ἔστιν δὲ θυγάτηρ θυγατρὸς κρεῖσσον."}, {"sp": "N", "st": "Sir 36:27", "t": "κάλλος γυναικὸς ἱλαρύνει πρόσωπον, καὶ ὑπέρ πᾶσαν ἐπιθυμίαν ἀνθρώπου ὑπεράγει·"}, {"sp": "N", "st": "Sir 36:28", "t": "τἰ ἔστιν ἐπὶ γλώσσης αὐτῆς ἔλεος καὶ πρᾳύτης. οὐκ ἔστιν ὁ ἀνὴρ αὐτῆς καθʼ υἱοὺς ἀνθρώπων."}, {"sp": "N", "st": "Sir 36:29", "t": "ὁ κτώμενος γυναῖκα ἐνάρχεται κτήσεως, βοηθὸν κατʼ αὐτὸν καὶ στύλον ἀναπαύσεως."}, {"sp": "N", "st": "Sir 36:30", "t": "οὖ οὐκ ἔστιν φραγμός, διαρπαγήσεται κτῆμα· καὶ nὗ οὐκ ἔστιν γυνή, στενάξει πλανώμενος."}, {"sp": "N", "st": "Sir 36:31", "t": "τίς γὰρ πιστεύσει εὐζώνῳ λῃστῇ σφαλλομένῳ ἐκ πόλεως εἰς πόλιν; οὕτως ἀνθρώπῳ μὴ ἔχοντι νοσσιὰν καὶ καταλύοντι οὄ ἐὰν ὀψίσῃ."}, {"sp": "N", "st": "Sir 37:1", "t": "Τᾶς φίλος ἐρεῖ Ἐφιλίασα αὐτῷ κἀγώ ἀλλʼ ἔστιν φίλος ὀνόματι μόνον φίλος."}, {"sp": "N", "st": "Sir 37:2", "t": "οὐχὶ λύπη ἔνι ἕως θανάτου (2)ἔταῖρος καὶ φίλος τρεπόμενος εἰς ἔχθραν;"}, {"sp": "N", "st": "Sir 37:3", "t": "πονηρὸν ἐνθύμημα, πόθεν ἐνεκυλίσθης καλύψαι τὴν ξηρὰν ἐν δολιότητι"}, {"sp": "N", "st": "Sir 37:4", "t": "ἑταῖρος φίλου ἐν εὐφροσύνῃ ἥδεται, καὶ ἐν καιρῷ θλίψεως ἔσται ἀπέναντι·"}, {"sp": "N", "st": "Sir 37:5", "t": "ἑταῖρος φίλῳ συνπονεῖ χάριν γαστρός, ἔναντι πολέμου λήμψεται ἀσπίδα."}, {"sp": "N", "st": "Sir 37:6", "t": "μὴ ἐπιλάθῃ φίλου ἐν τῆ ψυχῇ σου. καὶ μὴ ἀμνημονήσῃς αὐτοῦ ἐν χρήμασίν σου."}, {"sp": "N", "st": "Sir 37:7", "t": "πᾶς σύμβουλος ἐξαίρει βουλήν, ἀλλʼ ἔστιν συμβουλεύων εἰς αὐτόν."}, {"sp": "N", "st": "Sir 37:8", "t": "ἀπὸ συμβούλου φύλαξον τὴν ψυχήν σου, καὶ γνῶθι πρότερον τίς αὐτοῦ χρεία· καὶ γὰρ αὐτὸς ἑαυτῷ βουλεύσεται, (10)μή ποτε βάλῃ ἐπὶ σοὶ κλῆρον,"}, {"sp": "N", "st": "Sir 37:9", "t": "καὶ εἴπῃ σοι (11)Καλὴ ἡ ὁδός σου, καὶ στήσεται ἐξ ἐναντίας ἰδεῖν τὸ συμβησόμενόν σοι."}, {"sp": "N", "st": "Sir 37:10", "t": "μὴ βουλεύου μετὰ τοῦ ὑποβλεπομένου σε καὶ ἀπὸ τῶν ζηλούντων σε κρύψον βουλήν"}, {"sp": "N", "st": "Sir 37:11", "t": "¹¹μετὰ γυναικὸς τῆς ἀντιζήλου αὐτῆς καὶ μετὰ δειλοῦ περὶ πολέμου καὶ μετὰ ἐμπόρου περὶ μεταβολίας καὶ μετὰ ἀγοράζοντος περὶ πράσεως, μετὰ βασκάνου περὶ εὐχαριστίας καὶ μετὰ ἀνελεήμονος περὶ χρηστοηθείας, μετὰ ὀκνηροῦ περὶ παντὸς ἔργου καὶ μετὰ μισθίου ἀφεστίου περὶ συντελείας, οἰκέτῃ ἀργῷ περὶ πολλῆς ἐργασίας. μὴ ἔπεχε ἐπὶ τούτοις περὶ πάσης συμβουλίας"}, {"sp": "N", "st": "Sir 37:12", "t": "ἀλλ ἡ μετὰ ἀνδρὸς εὐσεβοῦς ἐνδελέχιζε, ὃν ἂν ἐπιγνῷς συντηροῦντα ἐντολάς, (16)ὅς ἐν τῇ ψυχῇ αὐτοῦ κατὰ τὴν ψυχήν σου. καὶ ἐὰν πταίσῃς συναλγήσει σοι."}, {"sp": "N", "st": "Sir 37:13", "t": "καὶ βουλὴν καρδίας στῆσον, οὐ γάρ ἐστίν σοι πιστότερος αὐτῆς·"}, {"sp": "N", "st": "Sir 37:14", "t": "ψυχὴ γὰρ ἀνδρὸς ἀπαγγέλλειν ἐνίοτε εἴωθεν ἤ ἑπτὰ σκοποὶ ἐπὶ μετεώρου καθήμενοι ἐπὶ σκοπῆς."}, {"sp": "N", "st": "Sir 37:15", "t": "καὶ ἐπὶ πᾶσι τούτοις δεήθητι Ὑψίστου ἴνα εὐθύνῃ ἐν ἀληθείᾳ τὴν ὁδόν σου"}, {"sp": "N", "st": "Sir 37:16", "t": "ἀρχὴ παντὸς ἔργου λόγος. καὶ πρὸ πάσης πράξεως βουλή."}, {"sp": "N", "st": "Sir 37:17", "t": "ἴχνος ἀλλοιώσεως καρδίᾳ·"}, {"sp": "N", "st": "Sir 37:18", "t": "τέσσερα μέρη ἀνατέλλει, ἀγαθὸν καὶ κακόν, ζωὴ καὶ θάνατος. καὶ κυριεύουσα ἐνδελεχῶς αὐτῶν γλῶσσά ἐστιν."}, {"sp": "N", "st": "Sir 37:19", "t": "ἔστιν ἀνὴρ πανοῖργος καὶ πολλῶν παιδευτής, καὶ τῆ ἰδίᾳ ψυχῇ ἐστιν ἄχρηστος"}, {"sp": "N", "st": "Sir 37:20", "t": "ἔστιν σοφιζόμενος ἐν λόγοις μισητός. οὗτος πάσης τροφῆς καθυστερήσει·"}, {"sp": "N", "st": "Sir 37:21", "t": "οὐ γὰρ ἐδόθη αὐτῷ παρὰ Κυρίου χάρς, ὅτι πάσης σοφίας ἐστερήθη."}, {"sp": "N", "st": "Sir 37:22", "t": "ατιν σοφὸς τῇ ἰδίᾳ ψυχῇ. καὶ οἵ καρποὶ τῆς συνέσεως αὐτοῦ ἐπὶ στόματος πιστοί."}, {"sp": "N", "st": "Sir 37:23", "t": "ἀνὴρ σοφὸς τὸν ἑαυτοῦ λαὸν παιδεύσει, καὶ οἵ καρποὶ τῆς συνέσεως αὐτοῦ πιστοί."}, {"sp": "N", "st": "Sir 37:24", "t": "ἀνὴρ σοφὸς πλησθήσεται εὐλογίας, καὶ μακαριοῦσιν αὐτὸν πάντες οἱ ὁρῶντες."}, {"sp": "N", "st": "Sir 37:25", "t": "ζωὴ ἀνδρὸς ἐν ἀριθμῷ ἡμερῶν. καὶ αἱ ἡμέραι τοῦ Ἰσραὴλ ἀναρίθμητοι."}, {"sp": "N", "st": "Sir 37:26", "t": "ὁ σοφὸς ἐν τῷ λαῷ αὐτοῦ κληρονομήσει πίστιν, καὶ τὸ ὄνομα αὐτοῦ ζήσεται εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Sir 37:27", "t": "τέκνον, ἐν τῇ ζωῇ σου πείρασον τὴν ψυχὴν σου, καὶ δὲ τί πονηρὸν αὐτῇ, καὶ μὴ δῷς αὐτῇ·"}, {"sp": "N", "st": "Sir 37:28", "t": "σὺ γὰρ πάντα πᾶσιν συμφέρει, καὶ οὐ πᾶσα ψυχὴ ἐν παντὶ εὐδοκεῖ"}, {"sp": "N", "st": "Sir 37:29", "t": "μὴ ἀπληστεύου ἐν πάσῃ τρυφῇ, καὶ μὴ ἐκχυθῇς ἐπὶ ἐδεσμάτων·"}, {"sp": "N", "st": "Sir 37:30", "t": "ἐν πολλοῖς γὰρ βρώμασιν ἔσται πόνος, καὶ ἡ ἀπληστία ἐγγιεῖ ἕως χολέρας·"}, {"sp": "N", "st": "Sir 37:31", "t": "δἰ ἀπληστίαν πολλοὶ ἐτελεύτησαν, ὁ δὲ προσέχων προσθήσει ζωήν."}, {"sp": "N", "st": "Sir 38:1", "t": "ίμα 1Τἰατρὸν πρὸς τὰς χρείας τιμαίς αὐτοῦ, καὶ γὰρ αὐτὸν ἔκτισεν Κύριος·"}, {"sp": "N", "st": "Sir 38:2", "t": "παρὰ γὰρ Γψἰστου ἐστὶν ἴασις, καὶ παρὰ βασιλέως λήμψεται δόμα."}, {"sp": "N", "st": "Sir 38:3", "t": "ἐπιστήμη ἰατροῦ ἀνυψώσει κεφαλὴν αὐτοῦ, καὶ ἔναντι μεγιστάνων θαυμασθήσεται."}, {"sp": "N", "st": "Sir 38:4", "t": "Κύριος ἔκτισεν ἐκ γῆς φάρμακα. καὶ ἀνὴρ φρόνιμος οὐ προσοχθιεῖ αὐτοῖς."}, {"sp": "N", "st": "Sir 38:5", "t": "οὐκ ἀπὸ ξύλου ἐγλυκάνθη ὕδωρ (6)εἰς τὸ γνωσθῆναι τὴν ἰσχὺν αὐτοῦ;"}, {"sp": "N", "st": "Sir 38:6", "t": "καὶ αὐτὸς ἔδωκεν ἀνθρώποις ἐπιστήμην ἐνδοξάζεσθαι ἐν τοῖς θαυμασίοις αὐτοῦ·"}, {"sp": "N", "st": "Sir 38:7", "t": "ἐν αὐτοῖς ἐθεράπευσεν καὶ ἤρεν τὸν πόνον αὐτοῦ,"}, {"sp": "N", "st": "Sir 38:8", "t": "μυρεψὸς ἐν τούτοις ποιήσει μίγμα· καὶ οὐ μὴ συντελέσῃ ἔργα αὐτοῦ, (8)καὶ εἰρήνη παρʼ αὐτοῦ ἐστιν ἐπὶ προσώπου τῆς γῆς."}, {"sp": "N", "st": "Sir 38:9", "t": "τέκνον, ἐν ἀρρωστήματί σου μὴ παράβλεπε, ἀλλ εδξαι Κυρίῳ, καὶ αὐτὸς ἰάσεταί σε"}, {"sp": "N", "st": "Sir 38:10", "t": "ἀπόστησον πλημμελίαν καὶ εδθυνον χεῖρας, καὶ ἀπὸ πάσης ἁμαρτίας καθάρισον καρδίαν·"}, {"sp": "N", "st": "Sir 38:11", "t": "δὸς εὐωδίαν καὶ μνημόσυνον σεμιδάλεως, καὶ λίπανον προσφοράν, ὡς μὴ ὑπάρχαον."}, {"sp": "N", "st": "Sir 38:12", "t": "καὶ ἰατρῷ δὸς τόπον, (12)καὶ γὰρ αὐτὸν ἔκτισεν Κύριος. καὶ μὴ ἀποστήτω σου, καὶ γὰρ αὐτοῦ χρεία."}, {"sp": "N", "st": "Sir 38:13", "t": "ἔστιν καιρὸς ὅτε καὶ ἐν χερσὶν αὐτῶν εὐοδία"}, {"sp": "N", "st": "Sir 38:14", "t": "καὶ γὰρ αὐτοὶ Κυρίὰυ δεηθήσονται, ἵνα εὐοδώσῃ αὐτοῖς ἀνάπαυσιν καὶ ἴασιν χάριν ἐμβιώσεαος."}, {"sp": "N", "st": "Sir 38:15", "t": "ὁ ἁμαρτάνων ἔναντι τοῦ ποιῆσαντος αὐτὸν ἐμπέσοι εἰς χεῖρας ἰατροῦ"}, {"sp": "N", "st": "Sir 38:16", "t": "τέκνον, ἐπὶ νεκρῷ κατάγαγε δάκρυα, καὶ ὡς δεινὰ πάσχων ἔναρξαι θρῆνου, κατὰ δὲ τὴν κρίσιν αὐτοῦ περίστειλου τὸ σῶμα αὐτοῦ, καὶ μὴ ὑπερίδῃς τὴν ταφὴν αὐτοῦ."}, {"sp": "N", "st": "Sir 38:17", "t": "πίκρανον κλαυθμὸν καὶ θέρμανον κοπετόν, (18)καὶ ποίησον τὸ πένθος κατὰ τὴν ἀξίου αὐτοῦ ἡμέραν μίαν καὶ δύο χάριν διαβολῆς, καὶ παρακλήθητι λύπης ἕνεκα·"}, {"sp": "N", "st": "Sir 38:18", "t": "ὰπὸ λύπης γὰρ ἐκβαίνει θάνατος. καὶ λύπη καρδίας κάμψει ἰσχύν·"}, {"sp": "N", "st": "Sir 38:19", "t": "ἐν ἀπαγωγῇ παραβαίνει καὶ λύπη, καὶ βίος πτωχοῦ κατὰ καρδίας."}, {"sp": "N", "st": "Sir 38:20", "t": "μὴ δῷς εἰς λύπην τὴν καρδίαν σου, ἀπόστησον αὐτὴν μνησθεὶς τὰ ἔσχατα·"}, {"sp": "N", "st": "Sir 38:21", "t": "μὴ ἐπιλάθῃ, οὐ γάρ ἐστιν ἐπάνοδος, καὶ τοῦτον οὐκ ἁφελήσεις καὶ σεαυτὸν κακώσεις."}, {"sp": "N", "st": "Sir 38:22", "t": "μνήσθητι ὅτι τὸ κρίμα αὐτοῦ οὕτω ὡς καὶ τὸ σόν· ἐμοὶ ἐχθὲς καὶ σοὶ σήμερον."}, {"sp": "N", "st": "Sir 38:23", "t": "ἐμ ἀναπαύσει νεκροῦ κατάπαυσον τὸ μνημόσυνον αὐτοῦ, καὶ παρακλήθητι ἐν αὐτῷ ἐν ἐξόδῳ πνεύματος αὐτοῦ."}, {"sp": "N", "st": "Sir 38:24", "t": "Σοφία γραμματέως ἐν εὐκαιρίᾳ σχολῆς, καὶ ὁ ἐλασσούμενος πράξει αὐτοῦ σοφισθήσεται."}, {"sp": "N", "st": "Sir 38:25", "t": "τί σοφισθήσεται (26)ὁ κρατῶν ἀρότρου, καὶ καυχώμενος ἐν δόρατι κέντρου, βόας ἐλαύνων καὶ ἀναστρεφόμενος ἐν ἔργοις αὐτῶν, καὶ ἡ διήγησις αὐτῶν ἐν υἱοῖς ταύρων ;"}, {"sp": "N", "st": "Sir 38:26", "t": "καρδίαν αὐτοῦ δώσει ἐκδοῦναι αδλακας, καὶ ἡ ἀγρυπνία αὐτοῦ εἰς χορτάσματα δαμάλεων."}, {"sp": "N", "st": "Sir 38:27", "t": "οὕτως πᾶς τέκτων καὶ ἀρχιτέκτων, ὅστις νύκτωρ ὡς ἡμέρᾳ διάγει· οἱ γλύφοντες γλύμματα σφραγίδων, καὶ ἡ ὑπομονὴ αὐτοῦ ἀλλοιῶσαι ποικιλίαν· καρδίαν αὐτοῦ δώσει εἰς ὁμοιῶσαι ζωγραφίαν, καὶ ἡ ἀγρυπνία αὐτοῦ τελέσαι ἔργον."}, {"sp": "N", "st": "Sir 38:28", "t": "οὕτως χαλκεὺς καθήμενος ἐγγὺς ἄκμονος καὶ καταμανθάνων ἀργῷ σιδήρῳ· ἀτμὶς πυρὸς πήξει σάρκας αὐτοῦ, καὶ ἐν θέρμῃ καμίνου διαμαχήσεται· (30) φωνή σφύρης καινιεῖ τὸ οὗς αὐτοῦ, καὶ κατέναντι ὁμοιώματος σκεύους οἱ ὀφθαλμοὶ αὐτοῦ· (31) καρδίαν αὐτοῦ δώσει εἰς συντέλειαν ἔργων, καὶ ἡ ἀγρυπνία αὐτοῦ κοσμῆσαι ἐπὶ συντελείας."}, {"sp": "N", "st": "Sir 38:29", "t": "οὕτως κεραμεὺς καθήμενος ἐν ἔργῳ αὐτοῦ καὶ συστρέφων ἐν ποσὶν αὐτοῦ τροχόν, ὅς ἐν μερίμνῃ κεῖται διὰ παντὸς ἐπὶ τὸ ἔργον αὐτοῦ, καὶ ἐναρίθμιος πᾶσα ἡ ἐργασία αὐτοῦ·"}, {"sp": "N", "st": "Sir 38:30", "t": "Τἐν βραχίονι αὐτοῦ τυπώσει πηλόν, καὶ πρὸ ποδῶν κάμψει ἰσχύν αὐτοῦ· (34)καρδίαν ἐπιδώσει συντελέσαι τὸ χάρισμα, καὶ ἡ ἀγρυπνία αὐτοῦ καθαρίσαι κάμινον."}, {"sp": "N", "st": "Sir 38:31", "t": "πάντες οὗτοι εἰς χεῖρας αὐτῶν ἐνεπίστευσαν, καὶ ἕκαστος ἐν τῷ ἔργῳ αὐτοῦ σοφίζεται"}, {"sp": "N", "st": "Sir 38:32", "t": "ἄυευ αὐτῶν οὐκ οἰκισθήσεται πόλις, (37)καὶ οὐ παροικήσουσιν οὐδὲ περιπατήσουσιν·"}, {"sp": "N", "st": "Sir 38:33", "t": "καὶ ἐν ἐκκλησίᾳ οὐχ ὑπεραλοῦνται, καὶ διαθήκην κρίματος οὐ διανοηθήσονται· (38)ἐs ὶ δίφρον δικαστοῦ οὐ καθιοῦνται, οὐδὲ μὴ ἐκφάναοσιν δικαιοσύνην καὶ κρίμα, καὶ ἐν παραβολαῖς οὐχ εὑρεθήσονται·"}, {"sp": "N", "st": "Sir 38:34", "t": "ἀλλὰ κτίσμα αἰῶνος τηρήσουσιν, καὶ ἡ δέησις αὐτῶν ἐν ἐργασίᾳ τέχνης. Πλὴν τοῦ ἐπιδόντος τὴν ψυχὴν αὐτοῦ καὶ διανοουμένου ἐν νόμῳ Ὑψίστου,"}, {"sp": "N", "st": "Sir 39:1", "t": "σοφίαν πάντων ἀρχαίων ἐκζητήσει, καὶ ἐν προφητείαις ἀσχοληθήσεται·"}, {"sp": "N", "st": "Sir 39:2", "t": "διηγήσεις ἀνδρῶν ὀνομαστῶν συντηρήσει, καὶ ἐυ στροφαῖς παραβολῶν συνεισελεύσεται·"}, {"sp": "N", "st": "Sir 39:3", "t": "ἀπόκρυφα παροιμιῶν ἐκζητήσει, καὶ ἐν αἰνίγμασι παραβολῶν ἀναστραφήσεται."}, {"sp": "N", "st": "Sir 39:4", "t": "ἀνὰ μέσον μεγιστάνων ὑπηρετήσει, καὶ ἔναντι ἡγουμένου ὀφθήσεται· (5)ἐν γῇ ἀλλοτρίων ἐθνῶν δωλεύσεται, ἀγαθὰ γὰρ καὶ κακὰ ἐν ἀνθρώποις ἐπείρασεν."}, {"sp": "N", "st": "Sir 39:5", "t": "τὴν καρδίαν αὐτοῦ ἐπιδώσει ὀρθρίσαι πρὸς Κύριον τὸν ποιήσαντα αὐτόν, καὶ ἔναντι Ὑψίστου δεηθήσεται· (7) καὶ ἀνοίξει στόμα αὐτοῦ ἐν σροσευχῆ, καὶ περὶ τῶν ἁμαρτιῶν αὐτοῦ δεηθήσεται."}, {"sp": "N", "st": "Sir 39:6", "t": "ἐὰν Κύριος ὁ μέγας θελήσῃ, πνεύματι συνέσεως ἐμπλησθήσεται· (9) ἀνομβρήσει ῥήματα σοφίας αὐτός, καὶ ἐν σροσευχῇ ἐξομολογήσεται Κυρίῳ·"}, {"sp": "N", "st": "Sir 39:7", "t": "⁷ρὐτὸς κατευθυνεῖ βουλὴυ αὐτοῦ καὶ ἐπιστήμην, καὶ ἐυ τοῖς ἀποκρύφοις αὐτοῦ διαοοηθήσεται·"}, {"sp": "N", "st": "Sir 39:8", "t": "αὐτὸς ἐκφαίνει παιδείαο διδασααλίας αὐτοῦ, καὶ ἐυ νόμῳ διαθήκης Κυρίου καυχήσεται."}, {"sp": "N", "st": "Sir 39:9", "t": "αἰνέσουσιν τὴυ σύνεσιν αὐτοῦ πολλοί, ἕως τοῦ αἰῶνος οὐκ ἐξαλειφθήσεται· (13)οὐκ ἀποστήσεται τὸ μνημοσύνου αὐτοῦ, καὶ ὄυομα αὐτοῦ ζήσεται εἰς γενεὰς γενεῶν·"}, {"sp": "N", "st": "Sir 39:10", "t": "τὴν σοφίαυ αὐτοῦ διηγήσονται ἔθνη, καὶ τὸυ ἔπαινου αὐτοῦ ἐξαγγελεῖ ἐκκλησία·"}, {"sp": "N", "st": "Sir 39:11", "t": "ἐὰν ἐμμείνῃ, ὄνομα καταλείψει ἡ χίλιοι, καὶ ἐὰν ἀναπαύσηται, ἐμποιεῖ αὐτῷ."}, {"sp": "N", "st": "Sir 39:12", "t": "Ἔτι διανοηθεὶς ἐκδιηγήσομαι, καὶ ὡς διχομηνία ἐπληρώθην."}, {"sp": "N", "st": "Sir 39:13", "t": "εἰσακούσατέ μου, υἱὰρὶ ὅσιοι, καὶ βλαστήσατε ὡς ῥόδον φυόμενον ἐπὶ όεύματος ἀγροῦ,"}, {"sp": "N", "st": "Sir 39:14", "t": "καὶ ὡς λίβανος εὐωδιάσατε ὀσμήν, (19)καὶ ἀνθήσατε ἄνθος ὡς κρίνον, διάδοτε ὀσμὴν καὶ αἰνέσατε ἄσμα. εὐλογήσατε Κύριρν ἐπὶ πᾶσιν τοῖς ἔργοις,"}, {"sp": "N", "st": "Sir 39:15", "t": "δότε τῷ ὀνόματι αὐτοῦ μεγαλωσύνην, καὶ ἐξομολογήσασθε ἐν αἰνέσει αὐτοῦ, ἐν ᾠδαῖς χειλέων καὶ ἐν κινύραις. καὶ οὕτως ἐρεῖτε ἐν ἐξομολογήσει"}, {"sp": "N", "st": "Sir 39:16", "t": "Τὰ ἔργα Κυρίου πάντα ὅτι καλὰ σφόδρα, καὶ πᾶν πρόσταγμα ἐν καιρῷ αὐτοῦ ἔσται·"}, {"sp": "N", "st": "Sir 39:17", "t": "οὐκ ἔστιν εἰπεῖν Τί τοῦτο; εἰς τί τοῦτο; πάντα γὰρ ἐν καιρῷ αὐτοῦ ζητηθήσεται. (22)ἐν λόγῳ αὐτοῦ ἔστη ὡς θιμωνιὰ ὕδωρ, καὶ ἐν ῥήματι στόματος αὐτοῦ ἀποδοχεῖα ὑδάτων."}, {"sp": "N", "st": "Sir 39:18", "t": "ἐν προστάγματι αὐτοῦ πᾶσα ἡ εὐδοκία, καὶ οὐκ ἔστιν ὃς ἐλαττώσει τὸ σωτήριον αὐτοῦ."}, {"sp": "N", "st": "Sir 39:19", "t": "ἔργα πάσης σαρκὸς ἐνώπιον αὐτοῦ, καὶ οὐκ ἔστιν κρυβῆοαι ἀπὸ τῶν ὀφθαλμῶν αὐτοῦ·"}, {"sp": "N", "st": "Sir 39:20", "t": "ἀπὸ τοῦ αἰῶνος εἰς τὸν αἰῶνα ἐπέβλεψεν, καὶ οὐθέν ἐστιν θαυμάσιον ἐναντίον αὐτοῦ."}, {"sp": "N", "st": "Sir 39:21", "t": "οὐκ ἔστιν εἰπεῖν Τί τοῦτος εἰς τί τοῦτο; πάντα γὰρ εἰς χρείας αὐτῶν ἔκτισται."}, {"sp": "N", "st": "Sir 39:22", "t": "ἡ εὐλογία αὐτοῦ ὡς ποταμὸς ἐπεκάλυψεν, (28)καὶ ὡς κατακλυσμὸς ξηρὰν ἐμέθυσεν·"}, {"sp": "N", "st": "Sir 39:23", "t": "οὕτως ὀργὴν αὐτοῦ ἔθνη κληρονομήσει, (29)ὡς μετέστρεψεν ὕδατα εἰς ἅλμην."}, {"sp": "N", "st": "Sir 39:24", "t": "ρἱ ὀδοὶ αὐτοῦ τοῖς ὁσίοις εὐθεῖαι, οὕτως τοῖς ἀνόμοις προσκόμματα·"}, {"sp": "N", "st": "Sir 39:25", "t": "ἀγαθὰ τοῖς ἀγαθοῖς ἔκτισται ἀπʼ ἀρχῆς. οὕτως τοῖς ἁμαρτωλοῖς κακά."}, {"sp": "N", "st": "Sir 39:26", "t": "ἁρχὴ πάσης χρείας εἰς ζωὴν ἀνθρώπου. ὕδωρ, πῦρ καὶ σίδηρος καὶ ἄλα καὶ σεμίδαλις, πυρὸς καὶ μέλι καὶ γάλα, αἵμα σταφυλῆς καὶ ἔλαιον καὶ ἱμάτιον·"}, {"sp": "N", "st": "Sir 39:27", "t": "ταῦτα πάντα τοῖς εὐσεβέσιν εἰς ἀγαθά, οὕτως τοῖς ἁμαρτωλοῖς τραπήσεται εἰς κακά."}, {"sp": "N", "st": "Sir 39:28", "t": "ἔοτιν πνεύματα ἄ εἰς ἐκδίκησιν ἔκτισται, καὶ ἐν θυμῷ αὐτῶν ἐστερέωσαν μάστιγας αὐτῶν· (34)καὶ ἐν καιρῷ συντελείας ἰσχὺν ἐκχεοῦσιν, καὶ τὸν θυμὸν τοῦ ποιήσαντος αὐτοὺς κοπάσουσιν."}, {"sp": "N", "st": "Sir 39:29", "t": "πῦρ καὶ χάλαζα καὶ λιμὸς καὶ θάνατος, πάντα ταῦτα εἰς ἐκδίκησιν ἔκτισται·"}, {"sp": "N", "st": "Sir 39:30", "t": "θηρίων ὀδόντες καὶ σκορπίοι καὶ ἔχεις καὶ ῥομφαία ἐκδικοῦσα εἰο ὄλεθρον ἀσεβεῖς,"}, {"sp": "N", "st": "Sir 39:31", "t": "ἐν τῇ ἐντολῇ αὐτοῦ εὐφρανθήσονται, καὶ ἐπὶ τῆς γῆς εἰς χρείας ἑτοιμασθήσονται, καὶ ἐν τοῖς καιροῖς αὐτῶν οὐ παραβήσονται λόγον."}, {"sp": "N", "st": "Sir 39:32", "t": "διὰ τοῦτο ἐξ ἀρχῆς ἐστηρίχθην καὶ διενοήθην καὶ ἐν γραφῇ ἀφῆκα."}, {"sp": "N", "st": "Sir 39:33", "t": "τὰ ἔργα Κυρίου πάντα ἀγαθά, καὶ πᾶσαν χρείαν ἐν ὥρᾳ αὐτῆς χορηγήσει·"}, {"sp": "N", "st": "Sir 39:34", "t": "καὶ οὐκ ἔστιν εἰπεῖν Τοῦτο τούτου πονηρότερον, πάντα γὰρ ἐν καιρῷ εὐδοκιμηθήσεται."}, {"sp": "N", "st": "Sir 39:35", "t": "καὶ νῦν ἐν πάσῃ καρδίᾳ καὶ στόματι ὑμνήσαμεν. καὶ εὐλογήσατε τὸ ὄνομα Κυρίου."}, {"sp": "N", "st": "Sir 40:1", "t": "Ἀσχολία μεγάλη ἔκτισται παντὶ ἀνθρώπαῳ, καὶ ζυγὸς βαρὺς ἐπὶ υἱοὺς Ἀδάμ, ἀφʼ ἡμέρας ἐξόδου ἐκ γαστρὸς μητρὸς αὐτῶν ἕως ἡμέρας ἐπὶ ταφῇ εἰς. μητέρα πάντων·"}, {"sp": "N", "st": "Sir 40:2", "t": "τοὺς διαλογισμοὺς αὐτῶν καὶ φόβον καρδίας, ἐπίνοια προσδοκίας, ἡμέρα τελευτῆς·"}, {"sp": "N", "st": "Sir 40:3", "t": "ἀπὸ καθημένου ἐπὶ θρόνου ἐν δόξῃ καὶ ἕως τεταπειναωμένου ἐν γῆ καὶ σποδῷ,"}, {"sp": "N", "st": "Sir 40:4", "t": "ἀπὸ φοροῦντος ὑακίνθου καὶ στέφανοο καὶ ἕως περιβαλλομένου ὠμόλινον·"}, {"sp": "N", "st": "Sir 40:5", "t": "θυμὸς καὶ ζῆλος καὶ ταραχὴ καὶ σάλος καὶ φόβος θανάτου καὶ μηνίαμα καὶ ἔρις. (5)καὶ ἐν καιρῷ ἀναπαύσεως ἐπὶ κοίτης ὕπνος νυκτὸς ἀλλοιοῖ γνῶσιν αὐτοῦ·"}, {"sp": "N", "st": "Sir 40:6", "t": "ὀλίγον ὡς οὐδὲν ἐν ἀναπαύσει, καὶ ἀπʼ ἐκείνου ἐν ὕπνοις ἁπ ἐν ἡμέρᾳ σκοπιᾶς· (7)τεθορυβημένος ἐν ὁράσει καρδίας αὐτοῦ, ὡς ἐκπεφευγῶς ἀπὸ προσώπου πολέsμοο·"}, {"sp": "N", "st": "Sir 40:7", "t": "ἐν καιρῷ σωτηρίας αὐτοῦ ἐξηγέρθη, καὶ ἀποθαυμάζων εἰς οὐδένα φόβον."}, {"sp": "N", "st": "Sir 40:8", "t": "μετὰ πάσης σαρκὸς ἀπὸ ἀνθρώπου ἕως κτήνους, καὶ ἐπὶ ἁμαρτωλῶν ἑπταπλάσια πρὸς ταῦτα·"}, {"sp": "N", "st": "Sir 40:9", "t": "θάνατος καὶ αἷμα καὶ ἔρις καὶ όομφαία,"}, {"sp": "N", "st": "Sir 40:10", "t": "ἐπὶ τοὺς ἀνόμους ἐκτίσθη ταῦτα πάντα, καὶ δι᾿ αὐτοὺς ἐγένετο ὁ κατακλυσμός."}, {"sp": "N", "st": "Sir 40:11", "t": "πάντα ὅσα ἀπὸ γῆς εἰς γῆν ἀναστρέφει, καὶ ἀπὸ ὑδάτων εἰς θάλασσαν ἀνακάμπτει."}, {"sp": "N", "st": "Sir 40:12", "t": "πᾶν δῶρον καὶ ἀδικία ἐξαλειφθήσεται, καὶ πίστις εἰς τὸν αἰῶνα στήσεται."}, {"sp": "N", "st": "Sir 40:13", "t": "χρήματα ἀδίκων ὡς ποταμὸς ξηρανθήσεται, καὶ ὡς βροντὴ μεγάλη ἐν ὑετῷ ἐξηχήσει"}, {"sp": "N", "st": "Sir 40:14", "t": "ἐν τῷ ἀνοῖξαι αὐτὸν χεῖρας εὐφρανθήσεται, οὕτως οἱ παραβαίνοντες εἰς συντέλειαν ἐκλείψουσιν."}, {"sp": "N", "st": "Sir 40:15", "t": "ἔκγονα ἀσεβῶν οὐ πληθυνεῖ κλάδος, καὶ ὸίζαι ἀκάθαρτοι ἐπʼ ἀκροτόμου πέτρας·"}, {"sp": "N", "st": "Sir 40:16", "t": "ἄχει ἐπὶ παντὸς ὕδατος καὶ χείλους ποταμοῦ πρὸ παντὸς χόρτου ἐκτιλήσεται."}, {"sp": "N", "st": "Sir 40:17", "t": "χάρις ὡς παράδεισος ἐν εὐλογίαις, καὶ ἐλεημοσύνη εἰς τὸν αἰῶνα διαμενεῖ."}, {"sp": "N", "st": "Sir 40:18", "t": "ζωὴ αὐτάρκους ἐργάτου γλυκανθήσεται, καὶ ὑπέρ ἀμφότερα ὁ εὑρίσκων θησαυρόν."}, {"sp": "N", "st": "Sir 40:19", "t": "τέκνα καὶ οἰκοδομὴ πόλεως στηρίζουσιν ὄνομα. καὶ ὑπέρ ἀμφότερα γυνὴ ἄμωμος λογίζεται."}, {"sp": "N", "st": "Sir 40:20", "t": "οἶνος καὶ μουσικὰ εὐφραίνουσιν καρδίαν, καὶ ὑπέρ ἀμφότερα ἀγάπησις σοφίας."}, {"sp": "N", "st": "Sir 40:21", "t": "αὐλὸς καὶ ψαλτήριον ἡδύνουσιν μέλη, καὶ ὑπέρ ἀμφότερα γλῶσσα ἡδεῖα."}, {"sp": "N", "st": "Sir 40:22", "t": "χάριν καὶ κάλλος ἐπιθυμήσει ὁ ὀφθαλμός σου, καὶ ὑπέρ ἀμφότερα χλόην σπόρου."}, {"sp": "N", "st": "Sir 40:23", "t": "φίλος καὶ ἑταῖρος εἰς καιρὸν ἀπαντῶντες, καὶ ὑπέρ ἀμφότερα γυνὴ μετὰ ἀνδρός."}, {"sp": "N", "st": "Sir 40:24", "t": "ἀδελφοὶ καὶ βοήθεια εἰς καιρὸν θλίψεως. καὶ ὑπέρ ἀμφότερα ἐλεημοσύνη δύσεται."}, {"sp": "N", "st": "Sir 40:25", "t": "χρυσίον καὶ ἀργύριον ἐπιστήσουσιν πόδα, καὶ ὑπέρ ἀμφότερα γυνὴ εὐδοκιμεῖται."}, {"sp": "N", "st": "Sir 40:26", "t": "χρήματα καὶ ἰσχὺς ἀνυψώσουσιν καρδίαν, καὶ ὑπέρ ἀμφότερα φόβος Κυρίου· (27)οὐκ ἔστιν φόβῳ Κυρίου ἐλάττωσις, καὶ οὐκ ἔστιν ἐπιζητῆσαι ἐν αὐτῷ βοήθειαν·"}, {"sp": "N", "st": "Sir 40:27", "t": "φόβος Κυρίου ὡς παράδεισος εὐλογίας, καὶ ὑπέρ πᾶσαν δόξαν ἐκάλυψαν αὐτόν."}, {"sp": "N", "st": "Sir 40:28", "t": "τέκνον, ζωὴν ἐπαιτήσεως μὴ βιώσῃς· κρεῖσσον ἀποθανεῖν ἡ ἐπαιτεῖν."}, {"sp": "N", "st": "Sir 40:29", "t": "ἀὴρ βλέπων εἰς τράπεζαν ἀλλοτρίαν, οὐκ ἔστιν αὐτοῦ ὁ βἰος ἐν λογισμῷ ζωῆς, ἀλισγήσει τὴν ψυχὴν αὐτοῦ ἐν ἐδέσμασιν ἀλλοτρίοις· (31)ἀνήρ δὲ ἐπιστήμων καὶ πεπαιδευμένος φυλάξεται."}, {"sp": "N", "st": "Sir 40:31", "t": "ἐν στόματι ἀναιδοῦς γλυκανθήσεται ἐπαίτησις, καὶ ἐν κοιλίᾳ αὐτοῦ πῦρ καήσεται."}, {"sp": "N", "st": "Sir 41:1", "t": "θάνατε, ὡς πικρόν σου τὸ μνημόσυνόν ἐστιν ἀνθρώπῳ εἰρηνεύοντι ἐν τοῖς ὑπάρχουσιν αὐτοῦ, (2)Ἰᵇάνδρὶ ἀπερισπάστῳ καὶ εὐοδουμένῳ ἐν πᾶσιν καὶ ἔτι ἰσχύοντι ἐπιδέξασθαι τροφήν."}, {"sp": "N", "st": "Sir 41:2", "t": "ὦ θανατε, καλ0ν σου τὸ κρίμα ἐστὶν ἀνθρώπῳ ἐπιδεομένῳ καὶ ἐλασσουμένῳ ἰσχύι, (4)ἐσχατογήρῳ καὶ περισπωμένῳ περὶ πάντων, καὶ ἀπειθοῦντι καὶ ἀπολωλεκότι ὑπομονὴν."}, {"sp": "N", "st": "Sir 41:3", "t": "μὴ εὐλαβοῦ κρίμα θανάτου, μνήσθητι προτέρων σου καὶ ἐσχάτων·"}, {"sp": "N", "st": "Sir 41:4", "t": "τοῦτο τὸ κρίμα παρὰ Κυρίου πάσῃ σαρκί, (6)καὶ τί ἀπαναίνῃ ἐν εὐδοκίὰ Ὑψίστου; εὗτε δέκα εἴτε ἑκατὸν εἶτε χίλια ἔτη, (7)οὐκ ἔστιν ἐν 4δοῦ ἐλεγμὸς ζωῆς."}, {"sp": "N", "st": "Sir 41:5", "t": "τέκνα βδελυκτὰ γίνεται τέκνα ἁμαρτωλῶν, καὶ συναναστρεφόμενα παροικίαις ἀσεβῶν·"}, {"sp": "N", "st": "Sir 41:6", "t": "τέκνων ἁμαρτωλῶν ἀπολεῖται κληρονομία, καὶ μετὰ τοῦ σπέρματος αὐτῶν ἐνδελεχιεῖ ὄνειδος."}, {"sp": "N", "st": "Sir 41:7", "t": "πατρὶ ἀσεβεῖ μέμψεται τέκνα, ὅτι δι αὐτὸν ὀνειδισθήσονται."}, {"sp": "N", "st": "Sir 41:8", "t": "οὐαὶ ὑμῖν ἄνδρες ἀσεβεῖς, οἵτινες ἐγκατελείπετε νόμον θεοῦ Ὑψίστου·"}, {"sp": "N", "st": "Sir 41:9", "t": "καὶ ἐὰν γεννηθῆτε, εἰς κατάραν γεννηθήσεσθε, καὶ ἐὰν ἀποθάνητε, εἰς κατάραν μερισθήσεσθε."}, {"sp": "N", "st": "Sir 41:10", "t": "πάντα ὅσα ἐκ γῆς εἰς γῆν ἀπελεύσεται, οὕτως ἀσεβεῖς ἀπὸ κατάρας εἰς ἀπωλίαν."}, {"sp": "N", "st": "Sir 41:11", "t": "πένθος ἀνθρώπων ἐν σώμασιν αὐτῶν, ὄνομα δὲ ἁμαρτωλῶν οὐκ ἀγαθὸν ἐξαλειφθήσεται."}, {"sp": "N", "st": "Sir 41:12", "t": "φρόντισον περὶ ὀνόματος, αὐτὸ γάρ σοι διαμενεῖ ἢ χίλιοι μεγάλοι θησαυροὶ χρυσίου·"}, {"sp": "N", "st": "Sir 41:13", "t": "ἀγαθῆς ζωῆς ἀριθμὸς ἡμερῶν, καὶ ἀγαθὸν ὄνομα εἰς αἰῶνα διαμενεῖ."}, {"sp": "N", "st": "Sir 41:14", "t": "παιδείαν ἐν εἰρήνῃ συντηρήσατε, τέκνα· σοφία δὲ κεκρυμμένη καὶ θησαυρὸς ἀφανής, τίς ὠφελία ἐν ἀμφοτέροις;"}, {"sp": "N", "st": "Sir 41:15", "t": "κρείσσων ἄνθρωπος ἀποκρύπτων τὴν μωρίαν αὐτοῦ ἢ ἄνθρωπος ἀποκρύπτων τὴν σοφίαν αὐτοῦ."}, {"sp": "N", "st": "Sir 41:16", "t": "τοιγαροῦν ἐντράπητε ἐπὶ τῷ ῥήματί μου· (20)οὐ γάρ ἐστιν πᾶσαν αἰσχύνην διαφυλάξαι καλόν, καὶ οὐ πάντα πᾶσιν ἐν πίστει εὐδοκιμεῖται."}, {"sp": "N", "st": "Sir 41:17", "t": "αἰσχύνεσθε ἀπὸ πατρὸς καὶ μητρὸς περὶ πορνείας, καὶ ἀπὸ ἡγουμένου καὶ δυνάστου περὶ ψεύδους,"}, {"sp": "N", "st": "Sir 41:18", "t": "ἀπὸ κριτοῦ καὶ ἄρχοντος περὶ πλημμελίας, ἀπὸ συναγωγῆς καὶ λαοῦ περὶ ἀνομίας, (23)ἀπὸ κοινωνοῦ καὶ φίλου περὶ ἀδικίας,"}, {"sp": "N", "st": "Sir 41:19", "t": "καὶ ἀπὸ τόπου οὗ παροικεῖς (24)περὶ κλοπῆς, καὶ ἀπὸ ἀληθείας θεοῦ καὶ διαθήκης, καὶ ἀπὸ πήξεως ἀγκῶνος ἐπʼ ἄρτους, ἀπὸ σκορακισμοῦ λήμψεως καὶ δόσεως,"}, {"sp": "N", "st": "Sir 41:20", "t": "καὶ ἀπὸ ἀσπαζομένων περὶ σιωπῆς, ἀπὸ ὁράσεως γυναικὸς ἑταίρας,"}, {"sp": "N", "st": "Sir 41:21", "t": "καὶ ἀπὸ ἀποστροφῆς προσώπου συγγενοῦς, ἀπὸ ἀφαιρέσεως μερίδος καὶ δόσεως, (²⁷)καὶ ἀπὸ κατανοήσεως γυναικὸς ὑπάνδρου,"}, {"sp": "N", "st": "Sir 41:22", "t": "ἀπὸ περιεργείας παιδίσκης αὐτοῦ, καὶ μὴ ἐπιστῆς ἐπὶ τὴν κοίτην αὐτῆς· (28)ἀπὸ φίλων περὶ λόγων ὀνειδισμοῦ, καὶ μετὰ τὸ δοῦναι μὴ ὀνείδιζε·"}, {"sp": "N", "st": "Sir 42:1", "t": "ἀπὸ δευτερώσεως καὶ λόγου ἀκοῆς, καὶ ἀπὸ ἀποκαλύψεων λόγων κρυφίων· καὶ ἔσῃ αἰσχυντηρὸς ἀληθινῶς, καὶ εὑρίσκαων χάριν ἔναντι παντὸς ἀνθρώπου. Μὴ περὶ τούτων αἰσχυνθῇς, καὶ μὴ λάβῃς πρόσωπον τοῦ ἁμαρτάνειν·"}, {"sp": "N", "st": "Sir 42:2", "t": "περὶ νόμου Ὑψίστου καὶ διαθήκης, καὶ περὶ κρίματος δικαιῶσαι τὸν ἀσεβῆ,"}, {"sp": "N", "st": "Sir 42:3", "t": "περὶ λόγου κοινωνοῦ καὶ ὁδοιπόρων, περὶ δόσεως κληρονομίας ἑταίρων,"}, {"sp": "N", "st": "Sir 42:4", "t": "περὶ ἀκριβείας ζυγοῦ καὶ σταθμίων, περὶ κτήσεως πολλῶν καὶ ὀλίγων,"}, {"sp": "N", "st": "Sir 42:5", "t": "περὶ ἀδιαφόρου πράσεως καὶ ἐμπόρων, καὶ περὶ παιδείας τέκνων πολλῆς, καὶ οἰκέτῃ πονηρῷ πλευρὰν αἱμάξαι·"}, {"sp": "N", "st": "Sir 42:6", "t": "ἐπὶ γυναικὶ πονηρᾷ καλὸν σφραγίς, (7)καὶ ὅπου χεῖρες πολλαὶ κλεῖσον·"}, {"sp": "N", "st": "Sir 42:7", "t": "ὃ ἐὰν παραδιδῷς, ἐν ἀριθμῷ καὶ σταθμῷ, καὶ δόσις καὶ λῆμψις παντὶ ἐν γραφῇ·"}, {"sp": "N", "st": "Sir 42:8", "t": "περὶ παιδείας ἀνοήτου καὶ μωροῦ καὶ ἐσχατογήρως κρινομένου πρὸς νέους, καὶ ἔσῃ πεπαιδευμένος ἀληθινῶς καὶ δεδοκιμασμένος ἔναντι παντὸς ζῶντος."}, {"sp": "N", "st": "Sir 42:9", "t": "θυγάτηρ πατρὶ ἀπόκρυφος ἀγρυπνία, καὶ ἡ μέριμνα αὐτῆς ἀφιστᾷ ὕπνον· ἐν νεότητι αὐτῆς μή ποτε παρακμάσῃ, καὶ συνῳκηκυῖα μὴ ποτε μισηθῇ·"}, {"sp": "N", "st": "Sir 42:10", "t": "ἐν παρθενείᾳ μὴ ποτε βεβηλωθῇ καὶ ἐν τοῖς πατρικοῖς αὐτῆς ἔγκυος γένηται· μετὰ ἀνδρὸς οὖσα μή ποτε παραβῇ, καὶ συνῳκηκυῖα μὴ ποτε στειρώσῃ."}, {"sp": "N", "st": "Sir 42:11", "t": "ἐπὶ θυγατρὶ ἀδιατρέπτῳ στερέωσον φυλακήν, μή ποτε ποιήσῃ σε ἐπίχαρμα ἐχθροῖς, λαλιὰν ἐν πόλει καὶ ἔκκλητον λαοῦ, καὶ καταισχυνεῖ σε ἐν πλήθει πολλῶν."}, {"sp": "N", "st": "Sir 42:12", "t": "παντὶ ἀνθρώπῳ μὴ ἔμβλεπε ἐν κάλλει, καὶ ἐν μέσῳ γυναικῶν μὴ συνέδρευε·"}, {"sp": "N", "st": "Sir 42:13", "t": "ἀπὸ γὰρ ἱματίων ἐκπορεύεται σής, καὶ ἀπὸ γυναικὸς πονηρία γυναικός."}, {"sp": "N", "st": "Sir 42:14", "t": "κρείσσων πονηρία ἀνδρὸς ἢ ἀγαθοποιὸς γυνή, καὶ γυνὴ καταισχύνουσα εἰς ὀνειδισμόν."}, {"sp": "N", "st": "Sir 42:15", "t": "Μνησθήσομαι δὲ τὰ ἔργα Κυρίου, καὶ ἃ ἑόρακα ἐκδιηγήσομαι· ἐν λόγοις Κυρίου τὰ ἔργα αὐτοῦ."}, {"sp": "N", "st": "Sir 42:16", "t": "ἥλιος φωτίζων κατὰ πᾶν ἐπέβλεψεν, καὶ τῆς δόξης αὐτοῦ πλῆρες τὸ ἔργον αὐτοῦ."}, {"sp": "N", "st": "Sir 42:17", "t": "οὐκ ἐνεποίησεν τοῖς ἁγίοις Κύριος ἐκδιηγήσασθαι πάντα τὰ θαυμάσια αὐτοῦ, ἃ ἐστερέωσεν Κύριος ὁ παντοκράτωρ, στηριχθῆναι ἐν δόξῃ αὐτοῦ τὸ πᾶν."}, {"sp": "N", "st": "Sir 42:18", "t": "ἄβυσσον καὶ καρδίαν ἐξίχνευσεν, καὶ ἐν πανουργεύμασιν αὐτῶν διενοήθην· (19)ἔγνω γὰρ ὁ κύριος πᾶσαν εἴδησιν καὶ ἐνέβλεψεν εἰς σημεῖον αἰῶνος,"}, {"sp": "N", "st": "Sir 42:19", "t": "ἀπαγγέλλων τὰ παρεληλυθότα καὶ ἐπεσόμενα, καὶ ἀποκαλύπτων ἴχνη ἀποκρύφων·"}, {"sp": "N", "st": "Sir 42:20", "t": "οὐ παρῆλθεν αὐτὸν πᾶν διανόημα, οὐκ ἐκρύβη ἀπʼ αὐτοῦ οὐδὲ εἷς λόγος."}, {"sp": "N", "st": "Sir 42:21", "t": "τὰ μεγαλεῖα τῆς σοφίας αὐτοῦ ἐκόσμησεν· καὶ ἕως ἔστιν πρὸ τοῦ αἰῶνος καὶ εἰς τὸν αἰῶνα, (22)οὔτε προσετέθη οὔτε ἠλαττώθη, καὶ οὐ προσεδεήθη οὐδενὸς συμβούλου."}, {"sp": "N", "st": "Sir 42:22", "t": "ὡς πάντα τὰ ἔργα αὐτοῦ ἐπιθυμητά, καὶ ὡς σπινθῆρός ἐστιν θεωρῆσαι."}, {"sp": "N", "st": "Sir 42:23", "t": "πάντα ταῦτα ζῇ καὶ μένει εἰς τὸν αἰῶνα ἐν πάσαις χρείαις, καὶ πάντα ὑπακούει·"}, {"sp": "N", "st": "Sir 42:24", "t": "πάντα δισσὰ ἕν κατέναντι τοῦ ἑνός, καὶ οὐκ ἐποίησεν οὐδέν ἐκλιπόν·"}, {"sp": "N", "st": "Sir 42:25", "t": "ἓν τοῦ ἑνὸς ἐστερέωσεν τὰ ἀγαθά, καὶ τίς πλησθήσεται ὁρῶν δόξαν αὐτοῦ;"}, {"sp": "N", "st": "Sir 43:1", "t": "γαυρίαμα ὕψους στερέωμα καθαριότητος, εἶδος οὐρανοῦ ἐν ὁράματι δόξης."}, {"sp": "N", "st": "Sir 43:2", "t": "ἥλιος ἐν ὀπτασίᾳ διαγγέλλων ἐν ἐξόδῳ, σκεῦος θαυμαστόν, ἔργον Ὑψίστου·"}, {"sp": "N", "st": "Sir 43:3", "t": "ἐν μεσημβρίᾳ αὐτοῦ ἀναξηραίνει χώραν. καὶ ἐναντίον καύματος αὐτοῦ τίς ὑποστήσεται;"}, {"sp": "N", "st": "Sir 43:4", "t": "κάμινον φυλάσσων ἐν ἔργοις καύματος, (4)τριπλασίως ἥλιος ἐκκαίων ὄρη· ἀτμίδας πυρώδεις ἐμφυσῶν, καὶ ἐκλάμπων ἀκτῖνας ἀμαυροῖ ὀφθαλμούς."}, {"sp": "N", "st": "Sir 43:5", "t": "μέγας Κύριος ὁ ποιήσας αὐτόν, καὶ ἐν λόγοις αὐτοῦ κατέσπευσεν πορείαν·"}, {"sp": "N", "st": "Sir 43:6", "t": "καὶ ἡ σελήνη ἐν πᾶσιν εἰς καιρὸν αὐτῆς, ἀνάδειξιν χρόνων καὶ σημεῖον αἰῶνος·"}, {"sp": "N", "st": "Sir 43:7", "t": "ἀπὸ σελήνης σημεῖον ἑορτῆς, φωστὴρ μειούμενος ἐπὶ συντελείας·"}, {"sp": "N", "st": "Sir 43:8", "t": "μὴν κατὰ τὸ ὄνομα αὐτῆς ἐστιν, αὐξανομένη θαυμαστῶς ἐν ἀλλοιώσει. (9)σκεῦος παραβολῶν ἐν ὕψει, ἐν στερεώματι οὐρανοῦ ἐκλάμπων·"}, {"sp": "N", "st": "Sir 43:9", "t": "κάλλος οὐρανοῦ, δόξα ἄστρων, κόσμος φωτίζων, ἐν ὑψίστοις Κύριος·"}, {"sp": "N", "st": "Sir 43:10", "t": "ἐν λόγοις ἁγίοις στήσονται κατὰ κρίμα, καὶ οὐ μὴ ἐκλυθῶσιν ἐν φυλακαῖς αὐτῶν."}, {"sp": "N", "st": "Sir 43:11", "t": "ἴδε τόξον, καὶ εὐλόγησον τὸν ποιήσαντα αὐτό, σφόδρα ὡραῖον ἐν τῷ αὐγάσματι αὐτοῦ·"}, {"sp": "N", "st": "Sir 43:12", "t": "ἐγύρωσεν οὐρανὸν ἐν κυκλώσει δόξης, χεῖρες Ὑψίστου ἐτάνυσαν αὐτό."}, {"sp": "N", "st": "Sir 43:13", "t": "προστάγματι αὐτοῦ κατέπαυσεν χιόνα, καὶ ταχύνει ἀστραπὰς κρίματος αὐτοῦ·"}, {"sp": "N", "st": "Sir 43:14", "t": "διὰ τοῦτο ἠνεῴχθησαν θησαυροί, καὶ ἐξέπτησαν νεφέλαι ὡς πετεινά·"}, {"sp": "N", "st": "Sir 43:15", "t": "ἐν μεγαλείῳ αὐτοῦ ἴσχυσεν νεφέλας, καὶ διεθρύβησαν λίθοι χαλάζης."}, {"sp": "N", "st": "Sir 43:16", "t": "καὶ ἐν ὀπτασίαις αὐτοῦ σαλευθήσεται ὄρη, ἐν θελήματι πνεύσεται νότος."}, {"sp": "N", "st": "Sir 43:17", "t": "φωνὴ βροντῆς αὐτοῦ ὠνείδισεν γῆν, καὶ καταιγὶς βορέου καὶ συστροφὴ πνεύματος. (19)ὡς πετεινὰ καθιπτάμενα πάσσει χιόνα, καὶ ὡς ἀκρὶς καταλύουσα ἡ κατάβασις αὐτῆς·"}, {"sp": "N", "st": "Sir 43:18", "t": "κάλλος λευκότητος αὐτῆς ἐκθαυμάσει ὀφθαλμός, καὶ ἐπὶ τοῦ ὑετοῦ αὐτῆς ἐκστήσεται καρδία."}, {"sp": "N", "st": "Sir 43:19", "t": "καὶ πάχνην ὡς ἅλα ἐπὶ γῆς χέει, καὶ παγεῑσα γίνεται σκολόπων ἄκρα."}, {"sp": "N", "st": "Sir 43:20", "t": "ψυχρὸς ἄνεμος βορέης πνεύσει, καὶ παγήσεται κρύσταλλος ἀφʼ ὕδατος· ἐπὶ πᾶσαν συναγωγὴν ὕδατος καταλύσει, καὶ ὡς θώρακα ἐνδύσεται τὸ ὕδωρ."}, {"sp": "N", "st": "Sir 43:21", "t": "καταφάγεται ὄρη καὶ ἔρημον ἐκκαύσει, καὶ ἀποσβέσει χλόην ὡς πῦρ."}, {"sp": "N", "st": "Sir 43:22", "t": "ἴασις πάντων κατὰ σπουδὴν ὁμίχλη, δρόσος ἀπαντῶσα ἀπὸ καύσωνος ἱλαρώσει."}, {"sp": "N", "st": "Sir 43:23", "t": "λογισμῷ αὐτοῦ ἐκόπασεν ἄβυσσον, καὶ ἐφύτευσεν αὐτὴν Ἰησοῦς."}, {"sp": "N", "st": "Sir 43:24", "t": "οἱ πλέοντες τὴν θάλασσαν διηγοῦνται τὸν κίνδυνον αὐτῆς, καὶ ἀκοαῖς ὠτίων ἡμῶν θαυμάζομεν·"}, {"sp": "N", "st": "Sir 43:25", "t": "καὶ ἐκεῖ τὰ παράδοξα καὶ θαυμάσια ἔργα, ποικιλία παντὸς ζῴου, κτίσις κητῶν."}, {"sp": "N", "st": "Sir 43:26", "t": "δι᾿ αὐτὸν εὐωδία τέλος αὐτοῦ, καὶ ἐν λόγῳ αὐτοῦ σύνκειται πάντα."}, {"sp": "N", "st": "Sir 43:27", "t": "πολλὰ ἐροῦμεν καὶ οὐ μὴ ἀφικώμεθα, καὶ συντέλεια λόγων Τὸ πᾶν ἐστιν αὐτός."}, {"sp": "N", "st": "Sir 43:28", "t": "δοξάζοντες ποῦ ἰσχύσωμεν αὐτὸς γὰρ ὁ μέγας παρὰ πάντα τὰ ἔργα αὐτοῦ."}, {"sp": "N", "st": "Sir 43:29", "t": "φοβερὸς Κύριος καὶ σφόδρα μέγας. καὶ θαυμαστὴ ἡ δυναστεία αὐτοῦ."}, {"sp": "N", "st": "Sir 43:30", "t": "δοξάζοντες Κύριον ὑψώσατε καθʼ ὅσον ἂν δύνησθε, ὑπερέξει γὰρ καὶ ἔτι· (3⁴)καὶ ὑψοῦντες αὐτὸν πληθύνατε ἐν ἰσχύι· μὴ κοπιᾶτε, οὐ γὰρ μὴ ἀφίκησθε."}, {"sp": "N", "st": "Sir 43:31", "t": "τίς ἑόρακεν αὐτὸν καὶ ἐκδιυηγήσεται; καὶ τίς μεγαλυνεῖ αὐτὸν καθώς ἐστιν;"}, {"sp": "N", "st": "Sir 43:32", "t": "πολλὰ ἀπόκρυφά ἐστιν μείζονα τούτων, ὀλίγα γὰρ ἑωράκαμεν τῶν ἔργων αὐτοῦ."}, {"sp": "N", "st": "Sir 43:33", "t": "πάντα γὰρ ἐποίησεν ὁ κύριος, καὶ τοῖς εὐσεβέσιν ἔδωκεν σοφίαν. Πατέρων ὕμνος."}, {"sp": "N", "st": "Sir 44:1", "t": "Αἰνέσωμεν δὴ ἄνδρας ἐνδόξους καὶ τοὺς πατέρας ἡμῶν τῇ γενέσει."}, {"sp": "N", "st": "Sir 44:2", "t": "πολλὴν δόξαν ἔκτισεν ὁ κύριος, τὴν μεγαλωσύνην αὐποῦ ἀπʼ αἰῶνος."}, {"sp": "N", "st": "Sir 44:3", "t": "κυριεύοντες ἐν ταῖς βασιλείαις αὐτῶν, καὶ ἄνδρες ὀνομαστοὶ ἐν δυνάμει· βουλεύσονται ἐν συνέσει αὐτῶυ, ἀπηγγελκότες ἐν προφητείαις·"}, {"sp": "N", "st": "Sir 44:4", "t": "ἡγούμενοι λαοῦ ἐν διαβουλίοις καὶ συνέσει γραμματείας λαοῦ, σοφοὶ λόγοι ἐν παιδείᾳ αὐτῶν·"}, {"sp": "N", "st": "Sir 44:5", "t": "ἐκζητοῦντες μέλη μουσικῶν, διηγούμενοι ἔπη ἐν γραφῇ·"}, {"sp": "N", "st": "Sir 44:6", "t": "ἄνδρες πλούσιοι κεχορηγημένοι ἰσχύι, εἰρηνεύοντες ἐν παροικίαις αὐτῶν·"}, {"sp": "N", "st": "Sir 44:7", "t": "πάντες οὗτοι ἐν γενεαῖς ἐδοξάσθησαν, καὶ ἐν ταῖς ἡμέραις αὐτῶν καύχημα."}, {"sp": "N", "st": "Sir 44:8", "t": "εἰσὶν αὐτῶν οἱ κατέλιπον ὄνομα τοῦ ἐκδιηγήσασθαι ἐπαίνους,"}, {"sp": "N", "st": "Sir 44:9", "t": "καὶ εἰσὶν ὧν οὐκ ἔστιν μνημόσυνον καὶ ἀπώλοντο ὡς οὐχ ὑπάρξαντες, καὶ ἐγένοντο ὡς οὐ γεγονότες, καὶ τὰ τέκνα αὐτῶν μετʼ αὐτούς."}, {"sp": "N", "st": "Sir 44:10", "t": "ἀλλ᾿ ἢ οὗτοι ἄνδρες ἐλέους, ὧν αἱ δικαιοσύναι οὐκ ἐπελήσθησαν·"}, {"sp": "N", "st": "Sir 44:11", "t": "μετὰ τοῦ σπέρματος αὐτῶν διαμενεῖ (¹² )ἀγαθὴ κληρονομία ἔκγονα αὐτῶν·"}, {"sp": "N", "st": "Sir 44:12", "t": "ἐν ταῖς διαθήκαις ¹²ἔστη σπέρμα αὐτῶν, ⁽¹³)καὶ τὰ τέκνα αὐτῶν δι᾿ αὐτούς,"}, {"sp": "N", "st": "Sir 44:13", "t": "ἕως αἰῶνος μενεῖ σπέρμα αὐτῶν, καὶ ἡ δόξα αὐτῶν οὐκ ἐξαλειφθήσεται·"}, {"sp": "N", "st": "Sir 44:14", "t": "τὸ σῶμα αὐτῶν ἐν εἰρήνῃ ἐτάφη, καὶ τὸ ὄνομα αὐτῶν ζῇ εἰς γενεάς·"}, {"sp": "N", "st": "Sir 44:15", "t": "σοφίαν αὐτῶν διηγήσονται λαοί, καὶ τὸν ἔπαινον ἐξαγγέλλει ἐκκλησία."}, {"sp": "N", "st": "Sir 44:16", "t": "Ἑνὼχ εὐηρέστησεν Κυρίῳ καὶ μετετέθη, ὑπόδειγμα μετανοίας ταῖς γενεαῖς."}, {"sp": "N", "st": "Sir 44:17", "t": "Νῶε εὑρέθη τέλειος δίκαιος, ἐν καιρῷ ὀργῆς ἐγένετο ἀντάλλαγμα· (18)διὰ τοῦτο ἐγενήθη κατάλιμμα τῇ γῇ, διὰ τοῦτο ἐγένετο κατακλυσμός·"}, {"sp": "N", "st": "Sir 44:18", "t": "διαθῆκαι αἰῶνος ἐτέθησαν πρὸς αὐτόν, ἵνα μὴ ἐξαλειφθῇ κατακλυσμῷ πᾶσα σάρξ."}, {"sp": "N", "st": "Sir 44:19", "t": "Ἀβραὰμ μέγας πατὴρ πλήθους ἐθνῶν, καὶ οὐχ ἐρέθῃ ὅμοιος ἐν τῇ δόξῃ,"}, {"sp": "N", "st": "Sir 44:20", "t": "ὃς συνετήρησεν νόμον Ὑψίστου, καὶ ἐγένετο ἐν διαθήκῃ μετʼ αὐτοῦ, (21)καὶ ἐν σαρκὶ αὐτοῦ ἔστησεν διαθήκην, καὶ ἐν πειρασμῷ εὑρέθη πιστός·"}, {"sp": "N", "st": "Sir 44:21", "t": "διὰ τοῦτο ἐν ὅρκῳ ἔστησεν αὐτῷ ἐνευλογηθῆναι ἔθνη ἐν τῷ σπέρματι αὐτοῦ, πληθῦναι αὐτὸν ὡς χοῦν τῆς γῆς, ⁽2³)καὶ ὡς ἄστρα ἀνυψῶσαι τὸ σπέρμα αὐτοῦ, καὶ κατακληρονομῆσαι αὐτοὺς ἀπὸ θαλάσσης ἕως θαλάσσης καὶ ἀπὸ ποταμοῦ ἕως ἄκροσ γῆς."}, {"sp": "N", "st": "Sir 44:22", "t": "καὶ ἐν τῷ Ἰσαὰκ ἔστησεν οὕτως δι᾿ Ἀβραὰμ τὸν πατέρα αὐτοῦ ⁽²5)εὺλογίαν πάντων ἀνθρώπων καὶ διαθήκην,"}, {"sp": "N", "st": "Sir 44:23", "t": "καὶ κατέπαυσεν ἐπὶ κεφαλὴν Ἰακώβ· ⁽26)ἐπέγνω αὐτὸν ἐν εὐλογίαις αὐτοῦ, καὶ ἔδωκεν αὐτῷ ἐν κληρονομίᾳ· καὶ διέστειλεν μερίδας αὐτοῦ, ἐν φυλαῖς ἐμέρισεν δέκα δύο· (⁽27)καὶ ἐξήγαγεν ἐξ αὐτοῦ ἄνδρα ἐλέους, εὑρίσκοντα χάριν ἐν ὀφθαλμοῖς πάσης σαρκός,"}, {"sp": "N", "st": "Sir 45:1", "t": "ἠγαπημένον ὑπὸ θεοῦ καὶ ἀνθρώπων Μωυσῆν, οὗ τὸ μνημόσυνον ἐν εὐλογίαις·"}, {"sp": "N", "st": "Sir 45:2", "t": "ὡμοίωσεν αὐτὸν δόξῃ ἁγίων, καὶ ἐμεγάλυνεν αὐτὸν ἐν φόβοις ἐχθρῶν·"}, {"sp": "N", "st": "Sir 45:3", "t": "ἐν λόγοις αὐτοῦ σημεῖα κατέπαυσεν, (³)ἐδόξασεν αὐτὸν κατὰ πρόσωπον βασιλέων· ἐνετείλατο αὐτῷ πρὸς λαὸν αὐτοῦ, καὶ ἔδειξεν αὐτῷ τῆς δόξης αὐτοῦ·"}, {"sp": "N", "st": "Sir 45:4", "t": "ἐν πίστει καὶ πρᾳύτητι αὐτοῦ ἡγίασεν, ἐξελέξατο αὐτὸν ἐκ πάσης σαρκός·"}, {"sp": "N", "st": "Sir 45:5", "t": "ἠκούτισεν αὐτὸν τῆς φωνῆς αὐτοῦ, καὶ εἰσήγαγεν αὐτὸν εἰς τὸν γνόφον, (⁶)καὶ ἔδωκεν αὐτῷ κατὰ πρόσωπον ἐντολάς, νόμον ζωῆς καὶ ἐπιστήμης, διδάξαι τὸν Ἰακὼβ διαθήκην καὶ κρίματα αὐτοῦ τὸν Ἰσραήλ."}, {"sp": "N", "st": "Sir 45:6", "t": "Ἀαρὼν ὕψωσεν ἅγιον ὅμοιον αὐτῷ ἀδελφὸν αὐτοῦ ἐκ φυλῆς Λευεί"}, {"sp": "N", "st": "Sir 45:7", "t": "ἔστησεν αὐτὸν διαθήκην αἰῶνος, καὶ ἔδωκεν αὐτῷ ἱερατίαν λαοῦ· ἐμακάρισεν αὐτὸν ἐν εὐκοσμίᾳ, (9)καὶ περιέζωσεν αὐτὸν περιστολὴν δόξης·"}, {"sp": "N", "st": "Sir 45:8", "t": "ἐνέδυσεν αὐτὸν συντέλειαν καυχήματος, καὶ ἐστερέαωσεν αὐτὸν σκεύεσιν ἰσχύος, (¹⁰)περισκελῆ καὶ ποδήρη καὶ ἐπωμίδα·"}, {"sp": "N", "st": "Sir 45:9", "t": "καὶ ἐκύκλωσεν αὐτὸν ῥοίσκοις, χρυσοῖς κώδωσιν πλείστοις κυκλόθεν, (¹¹)ἠχῆσαι φωνὴν ἐν βήμασιν αὐτοῦ, ἀκουστὸν ποιῆσαι ἦχον ἐν ναῷ, εἰς μνημόσυνον υἱοῖς λαοῦ αὐτοῦ·"}, {"sp": "N", "st": "Sir 45:10", "t": "στολῇ ἁγίᾳ. χρυσῷ καὶ ὑακίνθῳ καὶ πορφύρᾳ, ἔργων ποικιλτοῦ, λογίῳ κρίσεως, δήλοις ἀληθείας,"}, {"sp": "N", "st": "Sir 45:11", "t": "κεκλωσμένῃ κόκκῳ, ἔργῳ τεχνίτου, λίθοις πολυτελέσιν γλύμματος σφραγῖδος, ἐν δέσει χρυσίου, ἔργων λιθουργοῦ, εἰς μνημόσυνον ἐν γραφῇ κεκολαμμένῃ κατʼ ἀριθμὸν φυλῶν Ἰσραήλ·"}, {"sp": "N", "st": "Sir 45:12", "t": "στέφανον χρυσοῦν ἐπάνω κιδάρεως, ἐκτύπωμα σφραγῖδος ἁγιάσματος, καύχημα τιμῆς, ἔργον ἰσχύος, ἐπιθυμήματα ὀφθαλμῶν κοσμούμενα."}, {"sp": "N", "st": "Sir 45:13", "t": "ὡραῖα ¹³πρὸ αὐτοῦ οὐ γέγονεν τοιαῦτα, ἕως αἰῶνος (16)οὐκ ἐνεδύσατο ἀλλογενὴς πλὴν τῶν υἱῶν αὐτοῦ μόνον, καὶ τὰ ἔκγονα αὐτοῦ διὰ παντός."}, {"sp": "N", "st": "Sir 45:14", "t": "θυσίαν αὐτοῦ ὁλοκαρπωθήσονται καθʼ ἡμέραν ἐνδελεχῶς δίς."}, {"sp": "N", "st": "Sir 45:15", "t": "ἐπλήρωσεν Μωυσῆς τὰς χεῖρας καὶ ἔχρισεν αὐτὸν ἐν ἐλαίῳ ἁγίῳ· (¹9)ἐγενήθη αὐτῷ εἰς διαθήκην αἰώνιον, καὶ ἐν τῷ σπέρματι αὐτοῦ ἐν ἡμέραις οὐρανοῦ, λειτουργεῖν αὐτῷ ἅμα καὶ ἱερατεύειν, καὶ εὐλογεῖν τὸν λαὸν αὐτοῦ ἐν τῷ ὀνόματι."}, {"sp": "N", "st": "Sir 45:16", "t": "ἐξελέξατο αὐτὸν ἀπὸ παντὸς ζῶντος, προσαγαγεῖν κάρπωσιν Κυρίῳ, θυμίαμα καὶ εὐωδίαν εἰς μνημόσυνον, ἐξιλάσκεσθαι περὶ τοῦ λαοῦ σου."}, {"sp": "N", "st": "Sir 45:17", "t": "ἔδωκεν αὐτὸν ἐν ἐντολαῖς αὐτοῦ, ἐξουσίαν ἐν διαθήκαις κριμάτων, διδάξαι τὸν Ἰακὼβ τὰ μαρτύρια, καὶ ἐν νόμῳ αὐτοῦ φονῆσαι Ἰσραήλ."}, {"sp": "N", "st": "Sir 45:18", "t": "ἐπισυνέστησαν αὐτῷ ἀλλότριοι καὶ ἐζήλωσαν αὐτὸν ἐν τῆ ἐρήμῳ, ἄνδρες οἱ περὶ Δαθὰν καὶ Ἀβειρὼν καὶ ἡ συναγωγὴ Κόρε ἐν θυμῷ καὶ ὀργῇ·"}, {"sp": "N", "st": "Sir 45:19", "t": "εἶδεν Κύριος καὶ οὐκ εὐδόκησεν, καὶ συνετελέσθησαυ ἐν θυμῷ ὀργῆς· (24)ἐποίησεν αὐτοῖς τέρατα, καταναλῶσαι ἐν πυρὶ φλογὸς αὐτοῦ,"}, {"sp": "N", "st": "Sir 45:20", "t": "καὶ προσέθηκεν Ἀαρὼν δόξαν, καὶ ἔδωκεν αὐτῷ κληρονομίαν· ἀπαρχὰς πρωτογενημάτων ἐμέρισεν αὐτοῖς, (²⁶)ἄρτον πρώτοις ἡτοίμασεν πλησμονήν·"}, {"sp": "N", "st": "Sir 45:21", "t": "καὶ γὰρ θυσίας Κυρίου φάγονται, ἃς ἔδωκεν αὐτῷ τε καὶ τῷ σπέρματι αὐτοῦ."}, {"sp": "N", "st": "Sir 45:22", "t": "πλὴν ἐν γῇ λαοῦ οὐ κληρονομήσει, καὶ μερὶς οὐκ ἔστιν αὐτῷ ἐν λαῷ, αὐτὸς γὰρ μερίς σου, κληρονομία."}, {"sp": "N", "st": "Sir 45:23", "t": "καὶ Φινεὲς υἱὸς Ἐλεαζὰρ τρίτος εἰς δόξαν, ἐν τῷ ζηλῶσαι αὐτὸν ἐν φόβῳ Κυρίου (⁽29)καὶ στῆσαι αὑτὸν ἐν τροπῇ λαοῦ ἐν ἀγαθότητι προθυμίας ψυχῆς αὐτοῦ· καὶ ἐξιλάσατο περὶ τοῦ Ἰσραήλ."}, {"sp": "N", "st": "Sir 45:24", "t": "διὰ τοῦτο ἐστάθη αὐτῷ διαθήκη εἰρήνης, προστάτην ἀγίων καὶ λαῷ αὐτοῦ, ἵνα αὐτῷ ᾖ καὶ τῷ σπέρματι αὐτοῦ ἱερωσύνης μεγαλεῖον εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "Sir 45:25", "t": "καὶ διαθήκην τῷ Δαυεὶδ υἱῷ ἐκ φυλῆς Ἰούδα, κληρονομία βασιλέως υἱοῦ ἐξ υἱοῦ μόνου, κληρονομία Ἀαρὼν καὶ τῷ σπέρματι αὐτοῦ."}, {"sp": "N", "st": "Sir 45:26", "t": "δῴη ὑμῖν σοφίαν ἐν καρδίᾳ ὑμῶν, κρίνειν τὸν λαὸν αὐτοῦ ἐν δικαιοσύνῃ, ἵνα μὴ ἀφανισθῇ τὰ ἀγαθὰ αὐτῶν, καὶ τὴν δόξαν αὐτῶν εἰς γενεὰς αὐτῶν."}, {"sp": "N", "st": "Sir 46:1", "t": "κραταιὸς ἐν πολέμοις Ἰησοῦς Ναυῆ, καὶ διάδοχος Μωσῇ ἐν προφητείαις, ὃς ἐγένετο κατὰ τὸ ὄνομα αὐτοῦ (2)μέγας ἐπὶ σωτηρίᾳ ἐκλεκτῶν αὐτοῦ, ἐκδικῆσαι ἐπεγειρομένους ἐχθρούς, ὅπως κληρονομήσῃ τὸν Ἰσραήλ."}, {"sp": "N", "st": "Sir 46:2", "t": "ὡς ἐδοξάσθη ἐν τῷ ἐπᾶραι χεῖρας αὐτοῦ καὶ τῷ ἐκκλῖναι ῥομφαίαν ἐπὶ πόλεις."}, {"sp": "N", "st": "Sir 46:3", "t": "τίς πρότερον αὐτοῦ οὕτως ἔστη; τοὺς γὰρ πολεμίους Κύριος αὐτὸς ἐπήγαγεν."}, {"sp": "N", "st": "Sir 46:4", "t": "οὐχὶ ἐν χειρὶ αὐτοῦ ἀνεπόδισεν ὁ ἥλιος, καὶ μία ἡμέρα ἐγενήθη πρὸς δύο;"}, {"sp": "N", "st": "Sir 46:5", "t": "ἐπεκαλέσατο τὸν ὕψιστον δυνάστην ἐν τῷ θλίψαι αὐτὸν ἐχθροὺς κυκλόθεν καὶ ἐπήκουσεν αὐτῶν μέγας Κύριος ἐν λίθοις χαλάζης δυνάμεως κραταιᾶς·"}, {"sp": "N", "st": "Sir 46:6", "t": "κατέρραξεν ἐπ᾿ ἔθνος πόλεμον, καὶ ἐν καταβάσει ἀπώλεσεν ἀνθεστηκότας, (8)ἵνα γνῶσιν ἔθνη πανοπλίαν αὐτῶν, ὅτι ἐναντίον Κυρίου ὁ πόλεμος αὐτοῦ· καὶ γὰρ ἐπηκολούθησεν ὀπίσω Δυνάστου."}, {"sp": "N", "st": "Sir 46:7", "t": "καὶ ἐν ἡμέραις Μωυσέως ἐποίησεν ἔλεος, αὐτὸς καὶ Χαλὲβ υἱὸς Ἰεφοννή, ἀντιστῆναι ἔναντι ἐχθροῦ, κωλῦσαι λαὸν ἀπὸ ἁμαρτίας καὶ κοπάσαι γογγυσμὸν πονηρίας."}, {"sp": "N", "st": "Sir 46:8", "t": "καὶ αὐτοὶ δύο ὄντες διεσώθησαν ἀπὸ ἑξακοσίων χιλιάδων πεζῶν, εἰσαγαγεῖν αὐτοὺς εἰς κληρονομίαν, εἰς γῆν ῥέουσαν γάλα καὶ μέλι."}, {"sp": "N", "st": "Sir 46:9", "t": "καὶ ἔδωκεν ὁ κύριος τῷ Χαλὲβ ἰσχύν. καὶ ἕως γήρους διέμεινεν αὐτῷ, ἐπιβῆναι αὐτὸν ἐπὶ ὕψος τῆς γῆς. καὶ τὸ σπέρμα αὐτοῦ κατέσχεν κληρονομίαν·"}, {"sp": "N", "st": "Sir 46:10", "t": "ὅπως ἴδωσιν πάντες οἱ υἱοὶ Ἰσραὴλ ὅτι καλὸν τὸ πορεύεσθαι ὀπίσω Κυρίου."}, {"sp": "N", "st": "Sir 46:11", "t": "καὶ οἱ κριταί, ἕκαστος τῷ αὐτοῦ ὀνόματι, ⁽¹4)ὅσων οὐκ ἐξεπόρνευσεν ἡ καρδία καὶ ὅσοι οὐκ ἀπεστράφησαν ἀπὸ Κυρίου, εἴη τὸ μνημόσυνον αὐτῶν ἐν εὐλογίαις·"}, {"sp": "N", "st": "Sir 46:12", "t": "τὰ ὀστᾶ αὐτῶν ἀναθάλοι ἐκ τοῦ τόπου, αὐτῶν, ⁽¹⁵)καὶ τὸ ὄνομα αὐτῶν ἀντικαταλλασσόμενον ἐφʼ υἱοῖς δεδοξασμένων αὐτῶν."}, {"sp": "N", "st": "Sir 46:13", "t": "ἠγαπημένος ὑπὸ κυρίου αὐτοῦ προφήτης Κυρίου κατέστησεν βασιλέα, καὶ ἔχρισεν ἄρχοντας ἐπὶ τὸν λαὸν αὐτοῦ·"}, {"sp": "N", "st": "Sir 46:14", "t": "ἐν νόμῳ Κυρίου ἔκρινεν συναγωγήν, καὶ ἐπεσκέψατο Κύριος τὸν Ἰακώβ."}, {"sp": "N", "st": "Sir 46:15", "t": "ἐν πίστει αὐτοῦ ἠκριβάσθη προφήτης, (18)καὶ ἐγνώσθη ἐν πίστει αὐτοῦ πιστὸς ὁράσεως."}, {"sp": "N", "st": "Sir 46:16", "t": "καὶ ἐπεκαλέσατο τὸν κύριον δυνάστην, ἐν τῷ θλίψαι ἐχθροὺς αὐτοῦ κυκλόθεν, ἐν προσφορᾷ ἀρνὸς γαλαθηνοῦ·"}, {"sp": "N", "st": "Sir 46:17", "t": "καὶ ἐβρόντησεν ἀπʼ οὐρανοῦ Κύριος, καὶ ἐν ἤχῳ μεγάλῳ ἀκουστὴν ἐποίησεν τὴν φωνὴν αὐτοῦ,"}, {"sp": "N", "st": "Sir 46:18", "t": "καὶ ἐξέτριψεν ἡγουμένους Τυρίων καὶ πάντας ἄρχοντας Φυλιστιείμ."}, {"sp": "N", "st": "Sir 46:19", "t": "καὶ πρὸ καιροῦ κοιμήσεως αἰῶνος ἐπεμαρτύρατο ἔναντι Κυρίου καὶ χριστοῦ Χρήματα καὶ ἕως ὑποδημάτων ἀπὸ πάσης σαρκὸς οὐκ εἴληφα·Β καὶ οὐκ ἐνεκάλεσεν αὐτῷ ἄνθρωπος."}, {"sp": "N", "st": "Sir 46:20", "t": "καὶ μετὰ τὸ ὑπνῶσαι αὐτὸν προεφήτευσεν καὶ ὑπέδειξεν βασιλεῖ τὴν τελευτὴν αὐτοῦ, καὶ ἀνύψωσεν ἐκ γῆς τὴν φωνὴν αὐτοῦ ἐν προφητεία, ἐξαλεῖψαι ἀνομίαν λαοῦ."}, {"sp": "N", "st": "Sir 47:1", "t": "καὶ μετὰ τοῦτον ἀνέστη Ναθὰν προφητεύειν ἐν ἡμέραις Δαυείδ."}, {"sp": "N", "st": "Sir 47:2", "t": "ὥσπερ στέαρ ἀφωρισμένον ἀπὸ σωτηρίου, οὕτως Δαυεὶδ ἀπὸ τῶν υἱῶν Ἰσραήλ."}, {"sp": "N", "st": "Sir 47:3", "t": "ἐν λέουσιν ἔπαιζεν ὡς ἐν ἐρίφοις, καὶ ἐν ἄρκοις ὡς ἐν ἄρνασι προβάτων."}, {"sp": "N", "st": "Sir 47:4", "t": "ἐν νεότητι αὐτοῦ (⁴)οὐχὶ ἀπέκτεινεν γίγαντα, καὶ ἐξῆρεν ὀνειδισμὸν ἐκ λαοῦ (5)ἐν τῷ ἐπᾶραι χεῖρα ἐν λίθῳ σφενδόνης καὶ καταβαλεῖν γαυρίαμα τοῦ Γολιάθ ;"}, {"sp": "N", "st": "Sir 47:5", "t": "ἐπεκαλέσατο γὰρ Κύριον τὸν ὕψιστον, καὶ ἔδωκεν ἐν τῇ δεξιᾷ αὐτοῦ κράτος, ἐξᾶραι ἄνθρωπον ἐν πολέμῳ· ἀνυψώσει κέρας λαοῦ αὐτοῦ."}, {"sp": "N", "st": "Sir 47:6", "t": "οὕτως ἐν μυριάσιν ἐδόξασεν αὐτόν, καὶ ᾔνεσεν αὐτὸν ἐν εὐλογίαις Κυρίου ἐν τῷ φέρεσθαι αὐτῷ διάδημα δόξης."}, {"sp": "N", "st": "Sir 47:7", "t": "ἐξέτριψεν γὰρ ἐχθροὺς κυκλόθεν, καὶ ἐξουδένωσεν Φυλιστιεὶμ τοὺς ὑπεναντίους ἕως σήμερον συνέτριψεν αὐτῶν κέρας."}, {"sp": "N", "st": "Sir 47:8", "t": "ἐν παντὶ ἔργῳ αὐτοῦ ἔδωκεν ἐξομολόγησιν ἁγίῳ Ὑψίστῳ, ῥήματι δόξης· (10)ἐν πάσῃ καρδίᾳ αὐτοῦ ὕμνησεν καὶ ἠγάπησεν τὸν ποιήσαντα αὐτόν."}, {"sp": "N", "st": "Sir 47:9", "t": "καὶ ἔστησεν ψαλτῳδοὺς κατέναντι τοῦ θυσιαστηρίου, καὶ ἐξ ἠχοῦς αὐτῶν γλυκαίνειν μέλη·"}, {"sp": "N", "st": "Sir 47:10", "t": "εἔδωκεν ἐν ἑορταῖς εὐπρέπειαν, καὶ ἐκόσμησεν καιροὺς μέχρι συντελείας, ἐν τῷ αἰνεῖν αὐτοὺς τὸ ἅγιον ὄνομα αὐτοῦ καὶ ἀπὸ πρωὶ ἠχεῖν τὸ ἁγίασμα."}, {"sp": "N", "st": "Sir 47:11", "t": "Κύριος ἀφεῖλεν τὰς ἁμαρτίας αὐτοῦ, καὶ ἀνύψωσεν εἰς αἰῶνα τὸ κέρας αὐτοῦ, καὶ ἔδωκεν αὐτῷ διαθήκην βασιλέων καὶ θρόνον δόξης ἐν τῷ Ἰσραήλ."}, {"sp": "N", "st": "Sir 47:12", "t": "μετὰ τοῦτον ἀνέστη υἱὸς ἐπιστήμων, καὶ διʼ αὐτὸν κατέλυσεν ἐν πλατυσμῷ·"}, {"sp": "N", "st": "Sir 47:13", "t": "Σαλωμὼν ἐβασίλευσεν ἐν ἡμέραις εἰρήνης, ᾧ ὁ θεὸς κατέπαυσεν κυκλόθεν, ἵνα στήσῃ οἶκον ἐπʼ ὀνόματι αὐτοῦ καὶ ἑτοιμάσῃ ἁγίασμα εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Sir 47:14", "t": "ὡς ἐσοφίσθης ἐν νεότητί σου, (¹6)καὶ ἐνεπλήσθης ὡς ποταμὸς συνέσεως."}, {"sp": "N", "st": "Sir 47:15", "t": "γῆν ἐπεκάλυψεν ἡ ψυχὴ σου, (17)καὶ ἐνέπλησας ἐν παραβολαῖς αἰνιγμάτων·"}, {"sp": "N", "st": "Sir 47:16", "t": "εἰς νήσους πόρρω ἀφίκετο τὸ ὄνομά σου, καὶ ἠγαπήθης ἐν τῇ εἰρήνῃ σου·"}, {"sp": "N", "st": "Sir 47:17", "t": "ἐν ᾠδαῖς καὶ παροιμίαις καὶ παραβολαῖς καὶ ἐν ἐρμηνίᾳ ἀπεθαύμασάν σε χῶραι·"}, {"sp": "N", "st": "Sir 47:18", "t": "ἐν ὀνόματι Κυρίου τοῦ θεοῦ, τοῦ ἐπικεκλημένου θεοῦ Ἰσραήλ, (20) δσυνήγαγες ὡς κασσίτερον τὸ χρυσίον, καὶ ὡς μόλιβον ἐπλήθυνας ἀργύριον."}, {"sp": "N", "st": "Sir 47:19", "t": "παρανέκλινας τὰς λαγόνας σου γυναιξίν, καὶ ἐνεξουσιάσθης ἐν τῷ σώματί σου·"}, {"sp": "N", "st": "Sir 47:20", "t": "ἔδωκας μῶμον ἐν τῆ δόξῃ σου, καὶ ἐβεβήλωσας τὸ σπέρμα σου, ἐπαγαγεῖν ἀργὴν ἐπὶ τὰ τέκνα σου, καὶ κατενύγην ἐπὶ τῇ ἀφροσύνῃ σου,"}, {"sp": "N", "st": "Sir 47:21", "t": "γενέσθαι δίχα τυραννίδα καὶ ἐξ Ἐφράιμ ἄρξαι βασιλείαν ἀπειθῆ."}, {"sp": "N", "st": "Sir 47:22", "t": "ὁ δὲ Κύριος οὐ μὴ καταλίπῃ τὸ ἔλεος αὐτοῦ, καὶ οὐ μὴ διαφθαρῇ ἀπὸ τῶν ἔργων αὐτοῦ, οὐδὲ μὴ ἐξαλείψῃ ἐκλεκτοῦ αὐτοῦ ἔκγονα, καὶ σπέρμα τοῦ ἀγαπήσαντος αὐτὸν οὐ μὴ ἐξάρῃ· (25)καὶ τῷ Ἰακὼβ ἔδωκεν κατάλιμμα. καὶ τῷ Δαυείδ ἐξ αὐτοῦ ῥίζαν."}, {"sp": "N", "st": "Sir 47:23", "t": "καὶ ἀνεπαύσατο Σαλωμὼν μετὰ τῶν πατέραων, (27)καὶ κατέλιπεν μετʼ αὐτὸν ἐκ τοῦ σπέρματος αὐτοῦ λαοῦ ἀφροσύνην (28) καὶ ἐλασσούμενον συνέσει Ῥοβοάμ, ὅς ἀπέστησεν λαὸν ἐκ βουλῆς αὐτοῦ, (29)καὶ Ἰεροβοὰμ υἱὸν Ναβάτ, ὃς ἐξήμαρτεν τὸν Ἰσραὴλ καὶ ἔδωκεν τῷ Ἐφράιμ ὁδὸν ἁμαρτίας."}, {"sp": "N", "st": "Sir 47:24", "t": "καὶ ἐπληθύνθησαν αἱ ἁμαρτίαι αὐτῶν σφόδρα, ⁽³⁰)ἀποστῆσαι αὐτοὺς ἀπὸ τῆς γῆς αὐτῶν·"}, {"sp": "N", "st": "Sir 47:25", "t": "καὶ πᾶσαν πονηρίαν ἐξεζήτησαν, ἕως ἐκδίκησις ἔλθῃ ἐπʼ αὐτούς."}, {"sp": "N", "st": "Sir 48:1", "t": "καὶ ἀνέστη Ἠλίας προφήτης ὡς πῦρ, καὶ ὁ λόγος αὐτοῦ ὡς λαμπὰς ἐκαίετο·"}, {"sp": "N", "st": "Sir 48:2", "t": "ὃς ἐπήγαγεν ἐπʼ αὐτοὺς λιμόν, καὶ τῷ ζήλῳ αὐτοῦ ὠλιγοποίησεν αὐτούς·"}, {"sp": "N", "st": "Sir 48:3", "t": "ἐν λόγῳ Κυρίου ἀνέσχεν οὐρανόν, κατήγαγεν οὕτως τρὶς πῦρ."}, {"sp": "N", "st": "Sir 48:4", "t": "ὡς ἐδοξάσθης, Ἠλεία, ἐν τοῖς θαυμασίοις σου· καὶ τίς ὅμοιός σοι καυχᾶσθαι;"}, {"sp": "N", "st": "Sir 48:5", "t": "ὁ ἐγείρας νεκρὸν ἐκ θανάτου καὶ ἐξ ᾅδου ἐν λόγῳ Ὑψίστου·"}, {"sp": "N", "st": "Sir 48:6", "t": "ὁ καταγαγὼν βασιλεῖς εἰς ἀπωλίαν καὶ δεδοξασμένους ἀπὸ κλίνης αὐτῶν·"}, {"sp": "N", "st": "Sir 48:7", "t": "ἀκούων ἐν Σεινὰ ἐλεγμὸν καὶ ἐν Χωρὴβ κρίματα ἐκδικήσεως·"}, {"sp": "N", "st": "Sir 48:8", "t": "ὁ χρίων βασιλεῖς εἰς ἀνταπόδομα, καὶ προφήτας διαδόχους μετʼ αὐτόν·"}, {"sp": "N", "st": "Sir 48:9", "t": "ὁ ἀναλημφθεὶς ἐν λαίλαπι πυρὸς ἐν ἄρματι ἵππαων πυρίνων·"}, {"sp": "N", "st": "Sir 48:10", "t": "ὁ καταγραφεὶς ἐν ἐλεγμοῖς εἰς καιρούς, κοπάσαι ὀργὴν πρὸ θυμοῦ καὶ ἐπιστρέψαι καρδίαν πατρὸς πρὸς υἱὸν καὶ καταστῆσαι φυλὰς Ἰακώβ."}, {"sp": "N", "st": "Sir 48:11", "t": "¹¹μακάριοι οἱ ἰδόντες σε καὶ οἱ ἐν ἀγαπήσει κεκοσμημένοι, (12)καὶ γὰρ ἡμεῖς ζωῇ ζησόμεθα."}, {"sp": "N", "st": "Sir 48:12", "t": "Ἠλείας ὃς ἐν λαίλαπι ἐσκεπάσθη· καὶ Ἐλεισαῖε ἐνεπλήσθη πνεύματος αὐτοῦ, καὶ ἐν ἡμέραις αὐτοῦ οὐκ ἐσαλεύθη ὑπὸ ἄρχοντος, καὶ οὐ κατεδυνάστευσεν αὐτὸν οὐδείς."}, {"sp": "N", "st": "Sir 48:13", "t": "πᾶς λόγος οὐχ ὑπερῆρεν αὐτόν, καὶ ἐν κοιμήσει ἐπροφήτευσεν τὸ σῶμα αὐτοῦ·"}, {"sp": "N", "st": "Sir 48:14", "t": "καὶ ἐν ζωῇ αὐτοῦ ἐποίησεν τέρατα, καὶ ἐν τελευτῇ θαυμάσια τὰ ἔργα αὐτοῦ."}, {"sp": "N", "st": "Sir 48:15", "t": "ἐν πᾶσιν τούτοις οὐ μετενόησεν ὁ λαός, καὶ οὐκ ἀπέστησαν ἀπὸ τῶν ἁμαρτιῶν, ἕως ἐπρονομεύθησαν ἀπὸ τῆς γῆς αὐτῶν καὶ ἐσκορπίσθησαν ἐν πάσῃ τῇ γῇ, (17) καὶ κατελείφθη ὁ λαὸς ὀλιγοστός, καὶ ἄρχων τῷ οἴκῳ Δαυείδ."}, {"sp": "N", "st": "Sir 48:16", "t": "τινὲς μὲν αὐτῶν ἐποίησαν τὸ ἀρεστόν, τινὲς δὲ ἐπλήθυναν ἁμαρτίας."}, {"sp": "N", "st": "Sir 48:17", "t": "Ἑζεκίας ὠχύρωσεν τὴν πόλιν αὐτοῦ, καὶ εἰσήγαγεν εἰς μέσον αὐτῶν τὸν Γώγ· ὤρυξεν σιδήρῳ ἀκρότομον, καὶ ᾠκοδόμησεν κρήνας εἰς ὕδατα."}, {"sp": "N", "st": "Sir 48:18", "t": "ἐν ἡμέραις αὐτοῦ ἀνέβη Σενναχηρεὶμ καὶ ἀπέστειλεν Ῥαψάκην, καὶ ἀπῆρεν· καὶ ἐπῆρεν ἡ χεὶρ αὐτοῦ ἐπὶ Σειών, καὶ ἐμεγαλαύχησεν ὑπερηφανίᾳ αὐτοῦ."}, {"sp": "N", "st": "Sir 48:19", "t": "τότε ἐσαλεύθησαν καρδίαι καὶ χεῖρες αὐτῶν, καὶ ὠδίνησαν ὡς αἱ τίκτουσαι·"}, {"sp": "N", "st": "Sir 48:20", "t": "καὶ ἐπεκαλέσαντο τὸν κύριον τὸν ἐλεήμονα, ἐκπετάσαντες τὰς χεῖρας αὐτῶν πρὸς αὐτόν. καὶ ὁ ἅγιος ἐξ οὐρανοῦ ταχὺ ἐπήκουσεν αὐτῶν, (23)καὶ ἐλυτρώσατο αὐτοὺς ἐν χειρὶ Ἠσαίου·"}, {"sp": "N", "st": "Sir 48:21", "t": "ἐπάταξεν τὴν παρεμβολὴν τῶν Ἀσσυρίων, καὶ ἐξέτριψεν αὐτοὺς ὁ ἄγγελος αὐτοῦ."}, {"sp": "N", "st": "Sir 48:22", "t": "ἐποίησεν γὰρ Ἑζεκίας τὸ ἀρεστὸν Κυρίῳ, καὶ ἐνίσχυσεν ἐν ὁδοῖς Δαυεὶδ τοῦ πατρὸς αὐτοῦ, ἃς ἐνετείλατο Ἠσαίας ὁ προφήτης ὁ μέγας καὶ πιστὸς ἐν ὁράσει αὐτοῦ."}, {"sp": "N", "st": "Sir 48:23", "t": "ἐν ταῖς ἡμέραις αὐτοῦ ἀνεπόδισεν ὁ ἥλιος, καὶ προσέθηκεν ζωὴν βασιλεῖ·"}, {"sp": "N", "st": "Sir 48:24", "t": "πνεύματι μεγάλῳ ἴδεν τὰ ἔσχατα, καὶ παρεκάλεσεν τοὺς πενθοῦντας ἐν Σειών·"}, {"sp": "N", "st": "Sir 48:25", "t": "ἕως τοῦ αἰῶνος ὑπέδειξεν τὰ ἐσόμενα καὶ τὰ ἀπόκρυφα πρὶν ἢ παραγενέσθαι αὐτά."}, {"sp": "N", "st": "Sir 49:1", "t": "μνημόσυνον Ἰωσείου εἰς σύνθεσιν θυμιάματος, ἐσκευασμένον ἔργῳ μυρεψοῦ· (2) ἐν παντὶ στόματι ὡς μέλι γλυκανθήσεται, καὶ ὡς μουσικὰ ἐν συμποσίῳ οἴνου."}, {"sp": "N", "st": "Sir 49:2", "t": "αὐτὸς κατευθύνθη ἐν ἐπιστροφῇ λαοῦ, καὶ ἐξῆρεν βδελύγματα ἀνομίας·"}, {"sp": "N", "st": "Sir 49:3", "t": "κατεύθυνεν πρὸς Κύριον τὴν καρδίαν αὐτοῦ, ἐν ἡμέραις ἀνόμων κατίσχυσεν τὴν εὐσέβειαν."}, {"sp": "N", "st": "Sir 49:4", "t": "παρέξ Δαυεὶδ καὶ Ἐζεκίου καὶ Ἰωσείου πάντες πλημμελίαν ἐπλημμέλησαν· (6) κατέλιπον γὰρ τὸν νόμον τοῦ ὑψίστου, οἱ βασιλεῖς Ἰούδα ἐξέλιπον."}, {"sp": "N", "st": "Sir 49:5", "t": "ἔδωκαν γὰρ τὸ κέρας αὐτῶν ἑτέροις καὶ τὴν δόξαν αὐτῶν ἔθνει ἀλλοτρίῳ·"}, {"sp": "N", "st": "Sir 49:6", "t": "ἐνεπύρισεν ἐκλεκτὴν πόλιν ἁγιάσματος, καὶ ἠρήμωσαν τὰς ὁδοὺς αὐτῆς"}, {"sp": "N", "st": "Sir 49:7", "t": "ἐν χειρὶ Ἰερεμίου· ἐκάκωσαν γὰρ αὐτόν, καὶ αὐτὸς ἐν μήτρᾳ ἡγιάσθη προφήτης, ἐκριζοῦν καὶ κακοῦν καὶ ἀπολλύειν, ὡσαύτως οἰκοδομεῖν καὶ καταφυτεύειν."}, {"sp": "N", "st": "Sir 49:8", "t": "Ἰεζεκιήλ, ὃς εἶδεν ὅρασιν δόξης ἣν ὑπέδειξεν αὐτῷ ἐπὶ ἄρματος χερουβείμ·"}, {"sp": "N", "st": "Sir 49:9", "t": "καὶ γὰρ ἐμνήσθη τῶν ἐχθρῶν ἐν ὄμβρῳ, καὶ ἀγαθῶσαι τοὺς εὐθύνοντας ὁδούς."}, {"sp": "N", "st": "Sir 49:10", "t": "καὶ τῶν ιβʼ προφητῶν τὰ ὀστᾶ ἀναθάλοι ἐκ τοῦ τόπου αὐτῶν. παρεκάλεσεν δὲ τὸν Ἰακώβ, καὶ ἐλυτρώσατο αὐτοὺς ἐν πίστει ἐλπίδος."}, {"sp": "N", "st": "Sir 49:11", "t": "πῶς μεγαλύνωμεν τὸν Ζοροβαβέλ ; καὶ αὐτὸς ὡς σφραγὶς ἐπὶ δεξιᾶς χειρός."}, {"sp": "N", "st": "Sir 49:12", "t": "οὕτως Ἰησοῦς υἱὸς Ἰωσεδὲκ· οἳ ἐν ἡμέραις αὐτῶν οἰκοδόμησαν οἶκον καὶ ἀνύψωσαν λαὸν ἅγιον Κυρίῳ ἡτοιμασμένον εἰς δόξαν αἰῶνος."}, {"sp": "N", "st": "Sir 49:13", "t": "καὶ νέμουσιν ἐπὶ πολὺ τὸ μνημόσυνον τοῦ ἐγείραντος ἡμῖν τείχη πεπτωκότα, καὶ στήσαντος πύλας καὶ μοχλούς, καὶ ἀνεγείραντος τὰ οἰκόπεδα ἡμῶν."}, {"sp": "N", "st": "Sir 49:14", "t": "οὐδὲ εἶς ἐκτίσθη οἷος Ἑνὼχ τοιοῦτος ἐπὶ τῆς γῆς. καὶ γὰρ αὐτὸς ἀνελήμφθη ἀπὸ τῆς γῆς·"}, {"sp": "N", "st": "Sir 49:15", "t": "ὁ δὲ Ἰωσὴφ ἐγενήθη ἀνήρ. ἡγούμενος ἀδελφῶν, στήριγμα λαοῦ, (18)καὶ τὰ ὀστᾶ αὐτοῦ ἐπεσκέπησαν."}, {"sp": "N", "st": "Sir 49:16", "t": "Σὴμ καὶ Σὴθ ἐν ἀνθρώποις ἐδοξάσθησαν, καὶ ὑπέρ πᾶν ζῷον ἐν τῇ κτίσει Ἀδάμ."}, {"sp": "N", "st": "Sir 50:1", "t": "Σίμων Ὀνίου υἱὸς ἱερεὺς ὁ μέγας, ὃς ἐν ζωῇ αὐτοῦ ὑπέραψεν οἶκον, καὶ ἐυ ἡμέραις αὐτοῦ ἐστερέωσεν τὸν ναόν·"}, {"sp": "N", "st": "Sir 50:2", "t": "καὶ ὑπʼ αὐτοῦ ἐθεμελιώθη ὕψος διπλῆς, ἀνάλημμα ὑψηλὸν περιβόλου ἱεροῦ·"}, {"sp": "N", "st": "Sir 50:3", "t": "ἐν ἡμέραις αὐτοῦ ἠλαττώθη ἀποδοχεῖον ὑδάτων, χαλκὸς ὡσεὶ θαλάσσης τὸ περίμετρον·"}, {"sp": "N", "st": "Sir 50:4", "t": "ὁ φροντίζων τοῦ λαοῦ αὐτοῦ ἀπὸ πτώσεως, καὶ ἐνισχύσας πόλιν ἐνπολιορκῆσαι."}, {"sp": "N", "st": "Sir 50:5", "t": "ὡς ἐδοξάσθη ἐν περιστροφῇ λαοῦ, ἐν ἐξόδῳ οἴκου καταπετάσματος·"}, {"sp": "N", "st": "Sir 50:6", "t": "ὡς ἀστὴρ ἑωθινὸς ἐν μέσῳ νεφέλης, ὡς σελήνη πλήρης ἐν ἡμέραις·"}, {"sp": "N", "st": "Sir 50:7", "t": "ὡς ἥλιος ἐκλάμπων ἐπὶ ναὸν Ὑψίστου, καὶ ὡς τόξον φωτίζον ἐν νεφέλαις δόξης·"}, {"sp": "N", "st": "Sir 50:8", "t": "ὡς ἄνθος ῥόδων ἐν ἡμέραις νέων, ὡς κρίνα ἐπʼ ἐξόδων ὕδατος, ὡς βλαστὸς λιβάνου ἐν ἡμέραις θέρους·"}, {"sp": "N", "st": "Sir 50:9", "t": "ὡς πῦρ καὶ λίβανος ἐπὶ πυρίου· (10)ὡς σκεῦος χρυσίου ὁλοσφύρητον κεκοσμημένον παντὶ λίθῳ πολυτελεῖ·"}, {"sp": "N", "st": "Sir 50:10", "t": "ὡς ἐλαία ἀναθάλλουσα καρπούς, καὶ ὡς κυπάρισσος ὑψουμένη ἐν νεφέλαις."}, {"sp": "N", "st": "Sir 50:11", "t": "ἐν τῷ ἀναλαμβάνειν αὐτὸν στολὴν καὶ ἐνδιδύσκεσθαι αὐτὸν συντέλειαν καυχήματος, ⁽¹²)ἐν ἀναβάσει θυσιαστηρίου ἁγίου ἐδόξασεν περιβολὴν ἁγιάσματος·"}, {"sp": "N", "st": "Sir 50:12", "t": "ἐν δὲ τῷ δέχεσθαι μέλη ἐκ χειρῶν ἱερέων, καὶ αὐτὸς ἑστὼς παρʼ ἐσχάρᾳ βωμοῦ, κυκλόθεν αὐτὸς στέφανος ἀδελφῶν ὡς βλάστημα κέδρου ἐν τῷ Λιβάνῳ, ⁽¹⁴)καὶ ἐκύκλωσαν αὐτὸν ὡς στελέχη φοινίκων·"}, {"sp": "N", "st": "Sir 50:13", "t": "καὶ πάντες οἱ υἱοὶ Ἀαρὼν ἐν δόξῃ αὐτῶν, ⁽¹⁵)καὶ προσφορὰ Κυρίου ἐν χερσὶν αὐτῶν ἔναντι πάσης ἐκκλησίας Ἰσραήλ"}, {"sp": "N", "st": "Sir 50:14", "t": "καὶ συντέλειαν λειτουργῶν ἐπὶ βωμῶν, κοσμῆσαι προσφορὰν Ὑψίστου Παντοκράτορος,"}, {"sp": "N", "st": "Sir 50:15", "t": "ἐξέτεινεν ἐπὶ σπονδείου χεῖρα αὐτοῦ, καὶ ἔσπεισεν ἐξ αἵματος σταφυλῆς, (17) ἐξέχεεν εἰς θεμέλια θυσιαστηρίου ὀσμὴν εὐωδίας Ὑψίστῳ Πανβασιλεῖ."}, {"sp": "N", "st": "Sir 50:16", "t": "τότε ἀνέκραγον υἱοὶ Ἀαρών, ἐν σάλπιγξιν ἐλαταῖς ἤχησαν, ἀκουστὴν ἐποίησαν φωνὴν μεγάλην εἰς μνημόσυνον ἔναντι Ὑψίστου·"}, {"sp": "N", "st": "Sir 50:17", "t": "τότε πᾶς ὁ λαὸς κοινῇ κατέσπευσεν, καὶ ἔπεσαν ἐπὶ πρόσωπον ἐπὶ τὴν γῆν προσκυνῆσαι τῷ κυρίῳ αὐτῶν Παντοκράτορι θεῷ τῷ ὑψίστῳ·"}, {"sp": "N", "st": "Sir 50:18", "t": "καὶ ᾔνεσαν οἱ ψαλμῳδοὶ ἐν φωναῖς αὐτῶν, ἐν πλείστῳ οἴκῳ ἐγλυκάνθη μέλος·"}, {"sp": "N", "st": "Sir 50:19", "t": "καὶ ἐδεήθη ὁ λαὸς Κυρίου Ὑψίστου ἐν προσευχῇ κατέναντι Ἐλεήμονος, ἕως συντελεσθῇ κόσμος Κυρίου καὶ τὴν λειτουργίαν αὐτοῦ ἐτελείωσαν."}, {"sp": "N", "st": "Sir 50:20", "t": "τότε καταβὰς ἐπῆρεν χεῖρας αὐτοῦ ἐπὶ πᾶσαν ἐκκλησίαν υἱῶν Ἰσραήλ, δοῦναι εὐλογίαν Κυρίῳ ἐκ χειλέων αὐτοῦ καὶ ἐν ὀνόματι αὐτοῦ καυχᾶσθαι·"}, {"sp": "N", "st": "Sir 50:21", "t": "καὶ ἐδευτέρωσεν ἐν προσκυνήσει ἐπιδείξασθαι τὴν εὐλογίαν παρὰ Ὑψίστου."}, {"sp": "N", "st": "Sir 50:22", "t": "καὶ νῦν εὐλογήσατε τῷ θεῷ πάντες τῷ μεγαλοποιοῦντι πάντη, τὸν ὑψοῦντα ἡμέρας ἡμῶν ἐκ μήτρας. καὶ ποιοῦντα μεθʼ ἡμῶν κατὰ τὸ ἔλεος αὐτοῦ·"}, {"sp": "N", "st": "Sir 50:23", "t": "δῴη ὑμῖν εὐφροσύνην καρδίας, καὶ γενέσθαι εἰρήνην ἐν ἡμέραις ἡμῶν ἐν Ἰσραὴλ κατὰ τὰς ἡμέρας τοῦ αἰῶνος,"}, {"sp": "N", "st": "Sir 50:24", "t": "ἐνπιστεῦσαι μεθʼ ἡμῶν τὸ ἔλεος αὐτοῦ, καὶ ἐν ταῖς ἡμέραις αὐτοῦ λυτρωσάσθω ἡμᾶς."}, {"sp": "N", "st": "Sir 50:25", "t": "ἐν δυσὶν ἔθνεσιν προσώχθισεν ἡ ψυχή μου, καὶ τὸ τρίτον οὐκ ἔστιν ἔθνος·"}, {"sp": "N", "st": "Sir 50:26", "t": "οἱ καθήμενοι ἐν ὄρει Σαμαρείας, Φυλιστιείμ, καὶ ὁ λαὸς μωρὸς ὁ κατοικῶν ἐν Σικίμοις."}, {"sp": "N", "st": "Sir 50:27", "t": "Παιδείαν συνέσεως καὶ ἐπιστήμης ἐχάραξα ἐν τῷ βιβλίῳ τούτῳ, Ἰησοῦς υἱὸς Σειρὰχ Ἐλεαζὰρ ὁ Ἰεροσολυμείτης. ὃς ἀνώμβρησεν σοφίαν ἀπὸ καρδίας αὐτοῦ."}, {"sp": "N", "st": "Sir 50:28", "t": "μακάριος ὃς ἐν τούτοις ἀναστραφήσεται, καὶ θεὶς αὐτὰ ἐπὶ καρδίαν αὐτοῦ σοφισθήσεται·"}, {"sp": "N", "st": "Sir 50:29", "t": "ἐὰν γὰρ αὐτὰ ποιήσῃ, πρὸς πάντα ἰσχύσει· ὅτι φῶς Κυρίου τὸ ἴχνος αὐτοῦ. (¹)Προσευχὴ Ἰησοῦ υἱοῦ Σειράχ·"}, {"sp": "N", "st": "Sir 51:1", "t": "Ἐξομολογήσομαί σοι, Κύριε βασιλεῦ, καὶ αἰνέσω σε θεὸν τὸν σωτῆρά μου, (²)ἐξομολογοῦμαι τῷ ὀνόματί σου·"}, {"sp": "N", "st": "Sir 51:2", "t": "ὅτι σκεπαστὴς καὶ βοηθὸς ἐγένου μοι, (³)καὶ ἐλυτρώσω τὸ σῶμά μου ἐξ ἀπωλίας καὶ ἐκ παγίδος διαβολῆς γλώσσης, ἀπὸ χειλέων ἐργαζομένων ψεῦδος, καὶ ἔναντι τῶν παρεστηκότων"}, {"sp": "N", "st": "Sir 51:3", "t": "ἐγένου βοηθός, ³καὶ ἐλυτρώσω με κατὰ τὸ πλῆθος ἐλέου καὶ ὀνόματός σου ἐκ βρυγμῶν ἕτοιμος εἰς βρῶμα, (⁵)ἐκ χειρὸς ζητούντων τὴν ψυχήν μου. ἐκ πλειόνων θλίψεων ὧν ἔσχον,"}, {"sp": "N", "st": "Sir 51:4", "t": "ἀπὸ πνιγμοῦ πυρᾶς κυκλόθεν καὶ ἐκ μέσου πυρὸς οὗ οὐκ ἐξέκαυσα,"}, {"sp": "N", "st": "Sir 51:5", "t": "ἐκ βάθους κοιλίας ἅδου, καὶ ἀπὸ γλώσσης ἀκαθάρτου καὶ λόγου ψευδοῦς."}, {"sp": "N", "st": "Sir 51:6", "t": "βασιλεῖ διαβολὴ γλώσσης ἀδίκου· (⁸)ᾔνεσεν ἕως θανάτου ἡ ψυχὴ μου. (9)καὶ ἡ ζωή μου ἦν σύνεγγυς ᾄδου κάτω·"}, {"sp": "N", "st": "Sir 51:7", "t": "περιέσχον με πάντοθεν καὶ οὐκ ἦν ὁ βοηθῶν, ἐμβλέπων εἰς ἀντίλημψιν ἀνθρώπων καὶ οὐκ ἦν."}, {"sp": "N", "st": "Sir 51:8", "t": "καὶ ἐμνήσθην τοῦ ἐλέους σου, Κύριε, καὶ τῆς ἐργασίας σου τῆς ἀπʼ αἰῶνος, ⁽¹²)ὅτι ἐξελῇ τοὺς ὑπομένοντάς σε καὶ σώζεις αὐτοὺς ἐκ χειρὸς ἐθνῶν."}, {"sp": "N", "st": "Sir 51:9", "t": "καὶ ἀνύψωσα ἐπὶ γῆν ἱκετίαν μου, καὶ ὑπέρ θανάτου ῥύσεως ἐδεήθην"}, {"sp": "N", "st": "Sir 51:10", "t": "ἐπεκαλεσάμην Κύριον πατέρα κυρίου μου, μὴ με ἐγκαταλιπεῖν ἐν ἡμέραις θλίψεως, ἐν καιρῷ ὑπερηφανιῶν ἀβοηθησίας."}, {"sp": "N", "st": "Sir 51:11", "t": "αἰνέσω τὸ ὄνομά σου ἐνδελεχῶς, καὶ ὑμνήσω ἐν ἐξομολογήσει καὶ εἰσηκούσθη ἡ δέησίς μου."}, {"sp": "N", "st": "Sir 51:12", "t": "ἔσωσας γάρ με ἐξ ἀπωλείας, καὶ ἐξείλου με ἐκ καιροῦ πονηροῦ· (17)διὰ τοῦτο ἐξομολογήσομαι καὶ αἰνέσω σοι, καὶ εὐλογήσω τῷ ὀνόματι Κυρίου."}, {"sp": "N", "st": "Sir 51:13", "t": "Ἔτι ὢν νεώτερος πρὶν ἢ πλατηθῆναί με, ἐζήτησα σοφίαν προφανῶς ἐν προσευχῇ μου·"}, {"sp": "N", "st": "Sir 51:14", "t": "ἔναντι ναοῦ ἠξίουν περὶ αὐτῆς, καὶ ἕως ἐσχάτων ἐκζητήσω αὐτήν."}, {"sp": "N", "st": "Sir 51:15", "t": "ἐξ ἄνθους ὡς περκαζούσης σταφυλῆς (20)εὐφράνθη ἡ καρδία μου ἐν αὐτῇ· ἐπέβη ὁ πούς μου ἐν εὐθύτητι, ἐκ νεότητός μου ἴχνευον αὐτήν."}, {"sp": "N", "st": "Sir 51:16", "t": "ἔκλινα ὀλίγον τὸ οὖς μου καὶ ἐδεξάμην. καὶ πολλὴν εὗρον ἐμαυτῷ παιδείαο·"}, {"sp": "N", "st": "Sir 51:17", "t": "προκοπὴ ἐγένετό μοι ἐν αὐτῇ· (23)τῷ διδόντι μοι σοφίαν δώσω δόξαν."}, {"sp": "N", "st": "Sir 51:18", "t": "διενοήθην γὰρ τοῦ ποιῆσαι αὐτήν, καὶ ἐζήλωσα τὸ ἀγαθόν, καὶ οὐ μὴ αἰσχυνθῶ."}, {"sp": "N", "st": "Sir 51:19", "t": "διαμεμάχισται ἡ ψυχή μου ἐν αὐτῇ, καὶ ἐν ποιήσει λιμοῦ διηκριβασάμην· (2⁶)τὰς χεῖράς μου ἐξεπέτασα πρὸς ὕψος, καὶ τὰ ἀγνοήματα αὐτῆς ἐπένθησα·"}, {"sp": "N", "st": "Sir 51:20", "t": "τὴν ψυχήν μου κατεύθυνα εἰς αὐτήν, καρδίαν ἐκτησάμην μετʼ αὐτῶν ἀπʼ ἀρχῆς, καὶ ἐν καθαρισμῷ εὗρον αὐτήν· διὰ τοῦτο οὐ μὴ ἐγκαταλειφθῶ."}, {"sp": "N", "st": "Sir 51:21", "t": "καὶ ἡ κοιλία μου ἐταράχθη ἐκζητῆσαι αὐτὴν· διὰ τοῦτο ἐκτησάμην ἀγαθὸν κτῆμα."}, {"sp": "N", "st": "Sir 51:22", "t": "ἔδωκεν Κύριος γλῶσσάν μοι μισθόν μου. καὶ ἐν αὐτῇ αἰνέσω αὐτόν."}, {"sp": "N", "st": "Sir 51:23", "t": "Ἐγγίσατε πρὸς μέ, ἀπαίδευτοι, καὶ αὐλἰσθητε ἐν οἴκῳ παιδείας."}, {"sp": "N", "st": "Sir 51:24", "t": "καὶ ὅτι ὑστερεῖσθαι λέγετε ἐν τούτοις, καὶ αἱ ψυχαὶ ὑμῶν διψῶσι σφόδρα."}, {"sp": "N", "st": "Sir 51:25", "t": "ἤνοιξα τὸ στόμα μου καὶ ἐλάλησα Κτήσασθε αὐτοῖς ἄνευ ἀργυρίου·"}, {"sp": "N", "st": "Sir 51:26", "t": "τὸν τράχηλον ὑμῶν ὑπόθετε ὑπὸ ζυγόν, καὶ ἐπιδεξάσθω ἡ ψυχὴ ὑμῶν παιδείαν· ἐγγύς ἐστιν εὑρεῖν αὐτήν."}, {"sp": "N", "st": "Sir 51:27", "t": "ἴδετε ἐν ὀφθαλμοῖς ὑμῶν ὅτι ὀλίγον ἐκοπίασα, καὶ εὗρον ἐμαυτῷ πολλὴν ἀνάπαυσιν."}, {"sp": "N", "st": "Sir 51:28", "t": "μετάσχετε παιδείαν ἐν πολλῷ ἀριθμῷ ἀργυρίομ. καὶ πολὺν χρυσὸν κτήσασθε ἐν αὐτῇ·"}, {"sp": "N", "st": "Sir 51:29", "t": "εὐφρανθείη ἡ ψυχὴ ὑμῶν ἐν τῷ ἐλέει αὐτοῦ. καὶ μὴ αἰσχυνθείητε ἐν αἰνέσει αὐτοῦ·"}, {"sp": "N", "st": "Sir 51:30", "t": "ἐργάζεσθε τὸ ἔργον ὑμῶν πρὸ καιροί, καὶ δώσει τὸν μισθὸν ὑμῶν ἐν καιρῷ αὐτοῦ."}, {"sp": "HDR", "t": "ΒΑΡΟΥΧ"}, {"sp": "N", "st": "Bar 1:1", "t": "ΚAI οὗτοι οἱ λόγοι τοῦ βιβλίου οὓς ἔγραψεν B αροὺχ υἱὸς Νηρίου υἱοῦ Μαασαίου υἱοῦ Σεδεκίου υἱοῦ Ἀσαδίου υἱοῦ Χελκίου ἐν Βαβυλῶνι,"}, {"sp": "N", "st": "Bar 1:2", "t": "ἐν τῷ ἔτει τῷ πέμπτῳ ἐν ἑβδόμῃ τοῦ μηνός, ἐν τῷ καιρῷ ᾧ ἔλαβον οἱ Χαλδαῖοι τὴν Ἰερουσαλὴμ καὶ ἐνέπρησαν αὐτὴν ἐν πυρί."}, {"sp": "N", "st": "Bar 1:3", "t": "καὶ ἀνέγνω Βαροὺχ τοὺς λόγους τοῦ βιβλίου τούτου ἐν ὼσὶν Ἰεχονίου υἱοῦ Ἰωακεὶμ βασιλέως Ἰούδα, καὶ ἐν ὠσὶ παντὸς τοῦ λαοῦ τῶν ἐρχομένων πρὸς τὴν βίδλον,"}, {"sp": "N", "st": "Bar 1:4", "t": "καὶ ἐν όσὶν τῶν δυνατῶν καὶ υἱῶε τῶν βασιλέων, και ἐν ἐὼσὶ τῶν πρεσβυτέρων, καὶ ἐν Κσὶ παντὸς τοῦ λαοῦ ἀπὸ μικροῦ ἕως μεγάλου, πάντων τῶν κατοικούντων ἐν Βαβυλῶνι ἐπὶ ποταμοί Σούδ."}, {"sp": "N", "st": "Bar 1:5", "t": "καὶ ἔκλαιον καὶ ἐνήστευον καὶ ηὔχοντο ἐναντίον Κυρίου,"}, {"sp": "N", "st": "Bar 1:6", "t": "καὶ συνήγαγον ἀργύριον καθὰ ἑκάστου ἡδύνατο ἡ χείρ."}, {"sp": "N", "st": "Bar 1:7", "t": "καὶ ἀπέστειλαν εἰς Ἰερουσαλὴμ πρὸς Ἰωακεὶμ υἱὸν Χελκίου υἱοῦ Σαλὼμ τὸν ἱερέα, καὶ πρὸς τοὺς ἱερεῖς καὶ πρὸς πάντα τὸν λαὸν τοὺς εὺρεθέντας μετʼ αὐτοῦ ἐν Ἰερουσαλήμ,"}, {"sp": "N", "st": "Bar 1:8", "t": "ἐν τῷ λαβεῖν αὐτὸν τὰ σκεύη οἵκου Κυρίου τὰ ἐξενεχθέντα ἐκ τοῦ ναοῦ ἀποστρέψαι εἰς γῆν Ἰούδα, τῇ δεκάτη τοῦ Σειουάν, σκεύη ἀργυρᾶ ἃ ἐποίησεν Σεδεκίας υἱὸς Ἰωσεία βασιλεὺς Ἰούδα,"}, {"sp": "N", "st": "Bar 1:9", "t": "μετὰ τὸ ἀποικίσαι Ναβουχοδονοσὸρ βασιλέα Βαβυλῶνος τὸν Ἰεχονίαν καὶ τοὺς ἄρχοντας καὶ τοὺς δεσμώτας καὶ τοὺς δυνατοὺς καὶ τὸν λαὸν τῆς γῆς ἀπὸ Ἰερουσαλήμ, καὶ ἤγαγεν αὐτὸν εἰς Βαβυλῶνα."}, {"sp": "N", "st": "Bar 1:10", "t": "Καὶ εἶπαν Ἰδοὺ ἀπεστείλαμεν πρὸς ὑμᾶς ἀργύριον, καὶ ἀγοράσατε τοῦ ἀργυρίου ὁλοκαυτώματα καὶ περὶ ἁμαρτίας καὶ λίβανον, καὶ ποιήσατε μάννα καὶ ἀνοίσατε ἐπὶ τὸ θυσιαστήριον Κυρίου θεοῦ ἡμῶν,"}, {"sp": "N", "st": "Bar 1:11", "t": "καὶ προσεύξασθε περὶ τῆς ζωῆς Ναβουχοδονοσὸρ βασιλέως Βαβυλῶνος καὶ εἰς ζωὴν Βαλτασάρ υἱοῦ αὐτοῦ, ἵνα ὥσιν αἱ ἡμέραι αὐτῶν ὡς αἱ ἡμέραι τοῦ οὐρανοῦ ἐπὶ τῆς γῆς."}, {"sp": "N", "st": "Bar 1:12", "t": "καὶ δώσει Κύριος ἰσχὺν ἡμῖν καὶ φωτίσει τοὺς ὀφθαλμοὺς ἡμῶν, καὶ ζησόμεθα ὑπὸ τὴν σκιὰν Ναβουχοδονοσὸρ βασιλέως Βαβυλῶνος καὶ ὑπὸ τὴν σκιὰν Βαλτασάρ υἱοῦ αὐτοῦ, καὶ δουλεύσομεν αὐτοῖς ἡμέρας πολλὰς καὶ εὑρήσομεν χάριν ἐναντίον αὐτῶν."}, {"sp": "N", "st": "Bar 1:13", "t": "καὶ προσεύξασθε περὶ ἡμῶν πρὸς Κύριον τὸν θεὸν ἡμῶν, ὅτι ἡμάρτομεν τῷ κυρίῳ θεῷ ἡμῶν, καὶ οὐκ ἀπέστρεψεν ὁ θυμὸς Κυρίου καὶ ἡ ὀργὴ αὐτοῦ ἀφʼ ἡμῶν ἕως τῆς ἡμέρας ταύτης."}, {"sp": "N", "st": "Bar 1:14", "t": "Καὶ ἀναγνώσεσθε τὸ βιβλίον τοῦτο ὃ ἀπεστείλαμεν πρὸς ὑμᾶς ἐξαγορεῦσαι ἐν οἴκῳ Κυρίου ἐν ἡμέρᾳ ἑορτῆς καὶ ἐν ἡμέραις καιροῦ,"}, {"sp": "N", "st": "Bar 1:15", "t": "καὶ ἐρεῖτε ῷ κυρίῳ θεῷ ἡμῶν ἡ δικαιοσύνη, ἡμῖν δὲ αἰσχύνη τῶν προσώπων ὡς ἡ ἡμέρα αὕτη, ἀνθρώπῳ Ἰούδα καὶ τοῖς κατοικοῦσιν Ἰερουσαλήμ,"}, {"sp": "N", "st": "Bar 1:16", "t": "καὶ τοῖς βασιλεῦσιν ἡμῶν καὶ τοῖς ἄρχουσιν ἡμῶν καὶ τοῖς ἱερεῦσιν ἡμῶν καὶ τοῖς προφήταις ἡμῶν καὶ τοῖς πατράσιν ἡμῶν,"}, {"sp": "N", "st": "Bar 1:17", "t": "ὧν ἡμάρτομεν ἔναντι Κυρίου"}, {"sp": "N", "st": "Bar 1:18", "t": "καὶ ἠπειθήσαμεν αὐτῷ, καὶ οὐκ ἠκούσαμεν τῆς φωνῆς Κυρίου θεοῦ ἡμῶν πορεύεσθαι τοῖς προστάγμασιν Κυρίου οἷς ἔδωκεν κατὰ πρόσωπον ἡμῶν,"}, {"sp": "N", "st": "Bar 1:19", "t": "ἀπὸ τῆς ἡμέρας ἧς ἐξήγαγεν Κύριος τοὺς πατέρας ἡμῶν ἐκ γῆς Αἰγύπτου καὶ ἕως τῆς ἡμέρας ταύτης ἥμεθα ἀπειθοῦντες πρὸς Κύριον θεὸν ἡμῶν, καὶ ἐσχεδιάζομεν πρὸς τὸ μὴ ἀκούειν τῆς φωνῆς αὐτοῦ."}, {"sp": "N", "st": "Bar 1:20", "t": "καὶ ἐκολλήθη εἰς ἡμᾶς τὰ κακὰ καὶ ἡ ἀρὰ ὴν συνέταξεν Κύριος τῷ Μωυσῆ παιδὶ αὐτοῦ ἐν ἡμέρᾳ ἡ ἐξήγαγεν τοὺς πατέρας ἡμῶν δοῦναι ἡμῖν γῆν όέουσαν γαλα καὶ μέλι, ὡς ἡ ἡμέρα αὕτη."}, {"sp": "N", "st": "Bar 1:21", "t": "καὶ οὐκ ἠκούσαμεν τῆς φωνῆς Κυρίου τοῦ θεοῦ ἡμῶν κατὰ πάντας τοὺς λόγους τῶν προφητῶν ὧν ἀπέστειλεν πρὸς ἡμᾶς,"}, {"sp": "N", "st": "Bar 1:22", "t": "καὶ ᾠχόμεθα ἕκαστος ἐν διανοίᾳ καρδίας αὐτοῦ τῆς πονηρᾶς ἐργάζεσθαι θεοῖς ἑτέροις, ποιῆσαι τὰ κακὰ κατʼ ὀφθαλμοὺς Κυρίου θεοῦ ἡμῶν."}, {"sp": "N", "st": "Bar 2:1", "t": "καὶ ἔστησεν Κύριος τὸν κόγον αὐτοῦ ὃν ἐλάλησεν ἐφʼ ἡμᾶς καὶ ἐπὶ τοὺς δικαστὰς ἡμῶν τοὺς δικάσαντας τὺν Ἰσραὴλ κιὶ ἐπὶ τοὺς βασιλεῖς ἡμῶν κιὶ ἐπὶ τοὺς ἄρχοντας ἡμῶν καὶ ἐπὶ ἄνθρωπον Ἰσραὴλ καὶ Ἰούδα."}, {"sp": "N", "st": "Bar 2:2", "t": "οὐκ ἐποιήθη ὑποκάτω παντὸς τοῦ οὐρανοῦ καθὰ ἐποίησεν ἐν Ἰερουσαλήμ, κατὰ τὰ γεγραμμένα ἐν τῷ νόμῳ Μωυσῆ,"}, {"sp": "N", "st": "Bar 2:3", "t": "τοῦ φαγεῖν ἡμᾶς ἄνθρωπον σάρκας υἱοῦ αὐτοῦ καὶ ἄνθρωπον σάρκας θυγατρὸς αὐτοῦ,"}, {"sp": "N", "st": "Bar 2:4", "t": "καὶ ἔδωκεν αὐτοὺς ὑποχειρίους πάσαις ταῖς βασιλείαις ταῖς κύκλῳ ἡμῶν, εἰς ὀνειδισμὸν Κύριος ἐκεῖ."}, {"sp": "N", "st": "Bar 2:5", "t": "καὶ ἐγενήθησαν ὑποκάτω καὶ οὐκ ἐπάνω, ὅτι ἡμάρτομεν Κυρίῳ θεῷ ἡμῶν, πρὸς τὸ μὴ ἀκούειν τῆς φωνῆς αὐτοῦ."}, {"sp": "N", "st": "Bar 2:6", "t": "Τῷ κυρίῳ θεῷ ἡμῶν ἡ δικαιοσύνη, ἡμῖν δὲ καὶ τοῖς πατράσιν ἡμῶν ἡ αἰσχύνη τῶν προσώπων ὡς ἡ ἡμέρα αὕτη."}, {"sp": "N", "st": "Bar 2:7", "t": "ἅ ἐλάλησεν Κύριος ἐφʼ ἡμᾶς, πάντα τὰ κακὰ ταῦτα ἃ ἥλθεν ἐφʼ ἡμᾶς."}, {"sp": "N", "st": "Bar 2:8", "t": "καὶ οὐκ ἐδεἡθημεν τοῦ προσώπου Κυρίου τοῦ ἀποστρέψαι ἕκαστον ἀπὸ τῶν νοημάτων τῆς καρδίας αὐτῶν τῆς πονηρᾶς."}, {"sp": "N", "st": "Bar 2:9", "t": "καὶ ἐγρηγόρησεν Κύριος ἐπὶ τοῖς κακοῖς, καὶ ἐπήγαγε Κύριος ἐφʼ ἡμᾶς, ὅτι δίκαιος ὁ κύριος ἐπὶ πάντα τὰ ἔργα αὐτοῦ ἄ ἐνετείλατο ἡμῖν."}, {"sp": "N", "st": "Bar 2:10", "t": "καὶ οὐκ ἠκούσαμεν τῆς φωνῆς αὐτοῦ, πορεύεσθαι τοῖς προστάγμασιν Κυρίου οἰς ἔδωκεν κατὰ πρόσαωπον ἡμῶν."}, {"sp": "N", "st": "Bar 2:11", "t": "Καὶ νῦν, Κύριε ὁ θεὸς Ἰσραήλ, ὸς ἐξήγαγες τὸν λαόν σου ἐκ γῆς Αἰγύπτου ἐν χειρὶ κραταιῷ, ἐν σημείοις καὶ ἐν τέρασιν καὶ ἐν δυνάμει μεγάλῃ καὶ ἐν βραχίονι ὑψηλῷ, καὶ ἐποίησας σεαυτῷ ὄνομα ὡς ἡ ἡμέρα αὕτη,"}, {"sp": "N", "st": "Bar 2:12", "t": "ἡμάρτομεν, ἡσεββήσαμεν, ἠδικήσαμεν, Κύριε ὁ θεὸς ἡμῶν, ἐπὶ πᾶσιν τοῖς δικαιώμασίν σου."}, {"sp": "N", "st": "Bar 2:13", "t": "ἀποστραφήτω ὁ θυμός σου ἀφʼ ἡμῶν, ὅτι κατελείφθημεν ὀλίγοι ἐν τοῖς ἔθνεσιν οὄ διέσπειρας ἡμᾶς ἐκεῖ"}, {"sp": "N", "st": "Bar 2:14", "t": "εἰσάκουσον, Κύριε, τῆς προσευχῆς ἡμῶν καὶ τῆς δεήσεως ἡμῶν, καὶ ἐξελοῦ ἡμᾶς ἕνεκεν σοῦ καὶ δὸς ἡμῖν χάριν κατὰ πρόσωπον τῶν ἀποικισάντων ἡμᾶς,"}, {"sp": "N", "st": "Bar 2:15", "t": "ἴνα γνῷ πᾶσα ἡ γῆ ὅτι σὺ Κύριος ὁ θεὸς ἡμῶν, ὅτι τὸ ὄνομά σου ἐπεκλήθη ἐπὶ Ἰσραὴλ καὶ ἐπὶ τὸ γένος αὐτοῦ."}, {"sp": "N", "st": "Bar 2:16", "t": "Κύριε, κάτιδε ἐκ τοῦ οἴκου τοῦ ἁγίου σου καὶ ἐννόησον εἰς ἡμᾶς· κλῖνον, Κύριε, τὸ οὗς σου καὶ ἄκουσον."}, {"sp": "N", "st": "Bar 2:17", "t": "ἄνοιξον ὀφθαλμούς σου καὶ ἴδε ὅτι οὐχ οἱ τεθνηκότες ἐν τῷ ᾅδῃ, ὧν ἐλήμφθη τὸ πνεῦμα αὐτῶν ἀπὸ τῶν σπλάγχνοων αὐτῶν, δώσουσιν δόξαν καὶ δικαίωμα τῷ κυρίῳ·"}, {"sp": "N", "st": "Bar 2:18", "t": "ἀλλὰ ἡ ψυχὴ αὐτοῦ ἡ λυπουμένη ἐπὶ τὸ μέγεθος, ὃ βαδίζει κύπτον καὶ ἀσθενοῦν, καὶ οἱ ὀφθαλμοὶ οἱ ἐκλείποντες καὶ ἡ ψυχὴ ἡ πεινῶσα δώσουσίν σοι δόξαν καὶ δικαιοσύνην, Κύριε."}, {"sp": "N", "st": "Bar 2:19", "t": "ὅτι οὐκ ἐπὶ τὰ δικαιώματα τῶν πατέρων ἡμῶν καὶ τῶν βασιλέων ἡμῶν ἡμεῖς καταβάλλομεν τὸν ἔλεον κατὰ πρόσωπόν σου, Κύριε ὁ θεὸς ἡμῶν,"}, {"sp": "N", "st": "Bar 2:20", "t": "ὅτι ἐνῆκας τὸν θυμόν σου καὶ τὴν ὀργήν σου εἰς ἡμᾶς, καθάπερ ἐλάλησας ἐν χειρὶ τῶν παίδων σου τῶν προφητῶν"}, {"sp": "N", "st": "Bar 2:21", "t": "Οὕτως εἶπεν Κύριος Κλίνατε τὸν ὥμον ὑμῶν καὶ ἐργάσασθε τῷ βασιλεῖ Βαβυλῶνος, καὶ καθίσατε ἐπὶ τὴν γῆν ἣν δέδωκα τοῖς πατράσιν ὑμῶν·"}, {"sp": "N", "st": "Bar 2:22", "t": "καὶ ἐὰν μὴ ἀκούσητε τῆς φωνῆς Κυρίου ἐργάσασθαι τῷ βασιλεῖ Βαβυλῶνος,"}, {"sp": "N", "st": "Bar 2:23", "t": "ἐκλείψειν ποιήσω ἐκ πόλεων Ἰούδα καὶ ἔξωθεν Ἰερουσαλὴμ φωνὴν εὐφροσύνης καὶ φωνὴν χαρμοσύνης, φωνὴν νυμφίου καὶ φωνὴν νύμφης, καὶ ἔσται πᾶσα ἡ γῆ εἰς ἄβατον ἀπὸ ἐνοικούντων."}, {"sp": "N", "st": "Bar 2:24", "t": "καὶ οὐκ ὴκούσαμεν τῆς φωνῆς σου ἐργάσασθαι τῷ βασιλεῖ Βαβυλῶνος, καὶ ἔστησας τοὺς λόγους σου οὓ ς ἐλάλησας ἐν χερσὶν τῶν παίδων σου τῶν προφητῶν τοῦ ἐξενεχθῆναι τὰ ὀστᾶ βασιλέων ἡμῶν καὶ τὰ ὀστᾶ τῶν πατέρων ἡμῶν ἐκ τοῦ τόπου αὐτῶν."}, {"sp": "N", "st": "Bar 2:25", "t": "καὶ ἰδού, ἔστιν ἐξεριμμένα τῷ καύματι τῆς ἡμέρας καὶ τῷ παγετῷ τῆς νυκτός· καὶ ἀπεθάνοσαν ἐν πόνοις πονηροῖς, ἐν λιμῷ καὶ ἐν όομφαίᾳ καὶ ἐν ἀποστολῇ."}, {"sp": "N", "st": "Bar 2:26", "t": "καὶ ἔθηκας τὸν οἶκον οὗ ἐπεκλήθη τὸ ὄνομά σου ἐπʼ αὐτῷ ὡς ἡ ἡμέρα αὕτη, διὰ πονηρίαν οἴκου Ἰσραὴλ καὶ οἴκου Ἰούδα."}, {"sp": "N", "st": "Bar 2:27", "t": "Καὶ ἐποίησας εἰς ἡμᾶς, Κύριε ὁ θεὸς ἡμῶν, κατὰ πᾶσαν ἐπιεικίαν σου καὶ κατὰ πάντα οἰκτειρμόν σου τὸν μέγαν,"}, {"sp": "N", "st": "Bar 2:28", "t": "καθὰ ἐλάλησας ἐν χειρὶ παιδός σου Μωυσῆ, ἐν ἡμέρᾳ ἐντειλαμένου σου αὐτῷ γράψαι τὸν νόμον σου ἐναντίον υἱῶν Ἰσραὴλ λέγων"}, {"sp": "N", "st": "Bar 2:29", "t": "Ἐὰν μὴ ἀκούσητε τῆς φωνῆς μου. εί μὴν ἡ βόμβησις ἡ μεγάλη ἡ πολλὴ αὕτη ἀποστρέψει εἰς μικρὰν ἐν τοῖς ἔθνεσιν οὗ διασπερῶ αὐτοὺς ἐκεῖ."}, {"sp": "N", "st": "Bar 2:30", "t": "ὅτι ἔγνων ὅτι οὐ μὴ ἀκούσωσίν μου, ὅτι λαὸς σκληροτράχηλός ἐστιν· καὶ ἐπιστρέψουσιν ἐπὶ καρδίαν αὐτῶν ἐν γῇ ἀποικισμοῦ αὐτῶν,"}, {"sp": "N", "st": "Bar 2:31", "t": "καὶ γνώσονται ὅτι ἐγὼ Κύριος ὁ θεὸς αὐτῶν. καὶ δώσω αὐτοῖς καρδίαν καὶ ὥτα ἀκούοντα,"}, {"sp": "N", "st": "Bar 2:32", "t": "καὶ αἰνέσουσίν με ἐν γῇ ἀποικισμοῦ αὐτῶν, καὶ μνησθήσονται τοῦ ἀνόματός μου·"}, {"sp": "N", "st": "Bar 2:33", "t": "καὶ ἀποστρέψουσιν ἀπὸ τοῦ νώτου αὐτῶν τοῦ σκληροῦ καὶ ἀπὸ πονηρῶν πραγμάτων αὐτῶν, ὅτι μνησθήσονται τῆς ὁδοῦ πατέρων αὐτῶν τῶν ἁμαρτόντων ἔναντι Κυρίου."}, {"sp": "N", "st": "Bar 2:34", "t": "καὶ ἀποστρέψαω αὐτοὺς εἰς τὴν γῆν ἣν μοσα τοῖς πατράσιν αὐτῶν, τῷ Ἀβραὰμ καὶ τῷ Ἰσαὰκ καὶ τῷ Ἰακώβ, καὶ κυριεύσουσιν αὐτῆς· καὶ πλῆθύνω αὐτούς, καὶ οὐ μὴ σμικρυνθῶσιν·"}, {"sp": "N", "st": "Bar 2:35", "t": "καὶ στήσω αὐτοῖς διαθήκην αἰώνιον τοῦ εἶναί με αὐτοῖς εἰς θεόν, καὶ αὐτοὶ ἔσονταί μοι εἰς λαόν· καὶ οὐ κινήσω ἔτι τὸν λαόν μου Ἰσραήλ ἀπὸ τῆς γῆς ἧς ἔδωκα αὐτοῖς."}, {"sp": "N", "st": "Bar 3:1", "t": "Κύριε ΙΙαντοκράτωρ, ὁ θεὸς Ἰσραήλ, ψυχὴ ἐν στενοῖς καὶ πνεῦμα ἀκηδιῶν κέκραγεν πρὸς σέ."}, {"sp": "N", "st": "Bar 3:2", "t": "ἄκουσον, Κύριε, καὶ ἐλέησον, ὅτι ἡμάρτομεν ἐναντίον σου·"}, {"sp": "N", "st": "Bar 3:3", "t": "ὅτι σὺ καθήμενος τὸν αἰῶνα, καὶ ἡμεῖς ἀπολ. λύμενοι τὸν αἰῶνα."}, {"sp": "N", "st": "Bar 3:4", "t": "Κύριε ΠΓαντοκράτωρ, ὁ θεὸς Ἰσραήλ, ἄκουσον δὴ τῆς προσευχῆς τῶν τεθνηκότων Ἰσραὴλ καὶ υἱῶν τῶν ἁμαρτανόντων ἐναντίον σου, οἵ οὐκ ἤκουσαν τῆς φωνῆς σου θεοῦ αὐτῶν, καὶ ἐκολλήθη ἡμῖν τὰ κακά."}, {"sp": "N", "st": "Bar 3:5", "t": "μὴ μνησθῇς ἀδικιῶν πατέρων ἡμῶν, ἀλλὰ μνήσθητι χειρός σου καὶ ὀνόματός σου ἐν τῷ καιρῷ τούτῳ·"}, {"sp": "N", "st": "Bar 3:6", "t": "ὅτι σὺ Κύριος ὁ θεὸς ἡμῶν, καὶ αἰνέσομέν σε, Κύριε."}, {"sp": "N", "st": "Bar 3:7", "t": "ὅτι διὰ τοῦτο ἔδωκας τὸν φόβον σου ἐπὶ καρδίαν ἡμῶν καὶ ἐπικαλεῖσθαι τὸ ὄνομά σου· καὶ αἰνέσομέν σε ἐν τῇ ἀποικίᾳ ἡμῶν, ὅτι ἀπεστρέψαμεν ἀπὸ καρδίας ἡμῶν πᾶσαν ἀδικίαν πατέρων ἡμῶν τῶν ἡμαρτηκότων ἐναντίον σου."}, {"sp": "N", "st": "Bar 3:8", "t": "δοὺ ἡμεῖς σήμερον ἐν τῇ ἀποικίᾳ ἡμῶν, οὗ διέσπειρας ἡμᾶς ἐκεῖ εἰς ὀνειδισμὸν καὶ εἰς ἀρὰν καὶ εἰς ὄφλησιν κατὰ πάσας τὰς ἀδικίας πατέρων ἡμῶν, οἵ ἀπέστησαν ἀπὸ Κυρίου θεοῦ ἡμῶν."}, {"sp": "N", "st": "Bar 3:9", "t": "Ἄκουε, Ἰσραήλ, ἐντολὰς ζωῆς, ἐνωτίσασθε γνῶναι φρόνησιν."}, {"sp": "N", "st": "Bar 3:10", "t": "τί ἐστιν Ἰσραήλ; τί ὅτι ἐν γῆ τῶν ἐχθρῶν εἶ; ἐπαλαιώθης ἐν γῇ ἀλλοτρίᾳ, συνεμιάνθης τοῖς νεκροῖς,"}, {"sp": "N", "st": "Bar 3:11", "t": "προσελογίσθης μετὰ τῶν εἰς ἅδου,"}, {"sp": "N", "st": "Bar 3:12", "t": "ἐνκατέλιπες τὴν πηγὴν τῆς σοφίας."}, {"sp": "N", "st": "Bar 3:13", "t": "τῆ ὁδῷ τοῦ θεοῦ εἰ ἐπορεύθης, κατήκεις ἂν ἐν εἰρήνῃ τὸν αἰῶνα."}, {"sp": "N", "st": "Bar 3:14", "t": "μάθε ποῦ ἐστιν φρόνησις, ποῦ ἐστιν ἰσχύς, ποῦ ἐστιν σύνεσις, τοῦ γνῶναι ἄμα ποῦ ἐστιν μακροβίωσις καὶ ζωή, ποῦ ἐστιν φῶς ὀφθαλμῶν καὶ εἰρήνη."}, {"sp": "N", "st": "Bar 3:15", "t": "τίς εὗρεν τὸν τόπον αὐτῆς, καὶ τίς εἰσῆλθεν εἰς τοὺς θησαυροὺς αὐτῆς;"}, {"sp": "N", "st": "Bar 3:16", "t": "χοῦ εἰσιν οἱ ἄρχοντες τῶν ἐθνῶν καὶ οἱ κυριεύοντες τῶν θηρίων τῶν ἐπὶ τῆς γῆς;"}, {"sp": "N", "st": "Bar 3:17", "t": "οἱ ἐν τοῖς ὀρνέοις τοῦ οὐρανοῦ ἐμπαίζοντες, καὶ τὸ ἀργύριον θησαυρίζοντες καὶ τὸ χρυσίον ᾧ ἐπεποίθεισαν ἄνθρωποι, καὶ οὐκ ἔστιν τέλος τῆς κτήσεως αὐτῶν."}, {"sp": "N", "st": "Bar 3:18", "t": "ὅτι οἱ τὸ ἀργύριον τεκταίνοντες καὶ μεριμνῶντες, καὶ οὐκ ἔστιν ἐξεύρεσις τῶν ἔργων αὐτῶν."}, {"sp": "N", "st": "Bar 3:19", "t": "ἠφανίσθησαν καὶ εἰς ἄδου κατέβησαν, καὶ ἄλλοι ἀντανέστησαν ἀντʼ αὐτῶν."}, {"sp": "N", "st": "Bar 3:20", "t": "υεώτεροι ἴδον φῶς καὶ κατήκησαν ἐπὶ τῆς γῆς, ὁδὸν δὲ ἐπιστήμης οὐκ ἔγνωσαν"}, {"sp": "N", "st": "Bar 3:21", "t": "οὐδὲ συνῆκαν τρίβους αὐτῆς οὐδὲ ἀντελάβοντο αὐτῆς· οἱ υἱοὶ αὐτῶν ἀπὸ τῆς ὁδοῦ αὐτῶν τπόρρω ἐγενήθησαν,"}, {"sp": "N", "st": "Bar 3:22", "t": "οὐδὲ ἠκούσθη ἐν Χαναὰν οὐδὲ ὄφθη ἐν οἰμᾶν."}, {"sp": "N", "st": "Bar 3:23", "t": "οἵ τε υἱοὶ Ἅγαρ οἱ ἐκζητοῦντες τὴν σύνεσιν οἱ ἐπὶ γῆς, οἱ ἔμποροι τῆς Μερρὰν καὶ Θαιμάν, καὶ οἱ μυθολόγοι καὶ οἱ ἐκζητηταὶ τῆς συνέσεως, ὁδὸν δὲ σοφίας οὐκ ἔγνωσαν οὐδὲ ἐμνήσθησαν τὰς τρίβους αὐτῆς."}, {"sp": "N", "st": "Bar 3:24", "t": "Ὠ Ἰσραήλ, ὡς μέγας ὁ οἶκος τοῦ θεοῦ, καὶ ἐπιμήκης ὁ τόπος τῆς κτήσεως αὐτοῦ·"}, {"sp": "N", "st": "Bar 3:25", "t": "μέγας καὶ οὐκ ἔχει τελευτήν, ὑψηλὸς καὶ ἀμέτρητος."}, {"sp": "N", "st": "Bar 3:26", "t": "ἐκεῖ ἐγεννήθησαν οἱ γίγαντες οἱ ὀνομαστοὶ ἀπʼ ἀρχῆς γενόμενοι, εὐμεγέθεις, ἐπιστάμενοι πόλεμον."}, {"sp": "N", "st": "Bar 3:27", "t": "οὐ τούτους ἐξελέξατο ὁ θεός, οὐδὲ 6δὸν ἐπιστήμης ἔδωκεν αὐτοῖς·"}, {"sp": "N", "st": "Bar 3:28", "t": "καὶ ἀπώλοντο παρὰ τὸ μὴ ἔχειν φρόνησιν, ἀπώλοντο διὰ τὴν ἀβουλίαν αὐτῶν."}, {"sp": "N", "st": "Bar 3:29", "t": "τίς ἀνέβη εἰς τὸν οὐρανὸν καὶ ἔλαβεν αὐτήν, καὶ κατεβίβασεν αὐτὴν ἐκ τῶν νεφελῶν;"}, {"sp": "N", "st": "Bar 3:30", "t": "τίς διέβη πέραν τῆς θαλάσσης καὶ εὗρεν αὐτήν, καὶ οἴσει αὐτὴν χρυσίου ἐκλεκτοῦ;"}, {"sp": "N", "st": "Bar 3:31", "t": "οὐκ ἔστιν ὁ γινώσκων τὴν ὁδὸν αὐτῆς, οὐδὲ ὁ ἐνθυμούμενος τὴν τρίβον αὐτῆς."}, {"sp": "N", "st": "Bar 3:32", "t": "ἄλλο ὁ εἰδὸς τὰ πάντα γινώσκει αὐτήν, ἐξεῦρεν αὐτὴν τῇ συνέσει αὐτοῦ· ὁ κατασκευάσας τὴν γῆν εἰς τὸν αἰῶνα χρόνον ἐνέπλησεν αὐτὴν κτηνῶν τετραπόδων·"}, {"sp": "N", "st": "Bar 3:33", "t": "ὁ ἀποστέλλων τὸ φῶς καὶ πορεύεται, ἐκάλεσεν αὐτό, καὶ ὑπήκουσεν αὐτῷ τρόμῳ·"}, {"sp": "N", "st": "Bar 3:34", "t": "οἱ δὲ ἀστέρες ἔλαμψαν ἐν ταῖς φυλακαῖς αὐτῶν καὶ εὐφράνθησαν·"}, {"sp": "N", "st": "Bar 3:35", "t": "ἐκάλεσεν αὐτούς, καὶ εἶπον Πάρεσμεν· ἔλαμψαν μετʼ εὐφροσύνης τῷ ποιήσαντι αὐτούς."}, {"sp": "N", "st": "Bar 3:36", "t": "οὗτος ὁ θεὸς ἡμῶν, οὐ λογισθήσεται ἕτερος πρὸς αὐτόν."}, {"sp": "N", "st": "Bar 3:37", "t": "ἐξεῦρεν πᾶσαν ὁδὸν ἐπιστήμης. καὶ ἔδωκεν αὐτὴν Ἰακὼβ τῷ παιδὶ αὐτοῦ καὶ Ἰσραὴλ τῷ ἠγαπημένα ὑπʼ αὐτοῦ."}, {"sp": "N", "st": "Bar 3:38", "t": "μετὰ τοῦτο ἐπὶ τῆς γῆς ὤφθη, καὶ ἐν τοῖς ἀνθρώποις συνανεστράφη."}, {"sp": "N", "st": "Bar 4:1", "t": "Αὕτη ἡ βίβλος τῶν προσταγμάτων τοῦ θεοῦ, καὶ ὁ νόμος ὁ ὑπάρχααον εἰς τὸν αἰώνα· πάντες οἵ κρατοῦντες αὐτὴν, εἰς ζωήν· οἱ δὲ καταλείποντες αὐτὴν ἀποθανοῦνται."}, {"sp": "N", "st": "Bar 4:2", "t": "ἐπιστρέφου, Ἰακώβ, καὶ ἐπιλαβοῦ αὐτῆς, διόδευσον πρὸς τὴν λάμψιν κατέναντι τοῦ φωτὸς αὐτῆς."}, {"sp": "N", "st": "Bar 4:3", "t": "μὴ δῷς ἑτέρῳ τὴν δόξαν σου, καὶ τὰ συμφέροντά σοι ἔθνει ἀλλοτρίῳ."}, {"sp": "N", "st": "Bar 4:4", "t": "μακάριοί ἐσμεν, Ἰσραήλ, ὅτι τὰ ἀρεστὰ τοῦ θεοῦ ἡμῖν γνωστά ἐστιν."}, {"sp": "N", "st": "Bar 4:5", "t": "Ραρσεῖτε, λαός μου, μνημόσυνον Ἰσραήλ."}, {"sp": "N", "st": "Bar 4:6", "t": "ἐπράθητε τοῖς ἔθνεσιν οὐκ εἰς ἀπώλειαν, διὰ δὲ τὸ παροργίσαι ὑμᾶς τὸν θεόν, παρεδόθητε τοῖς ὑπεναντίοις."}, {"sp": "N", "st": "Bar 4:7", "t": "παροξύνατε γὰρ τὸν ποιήσαντα ὑμᾶς θύσαντες δαιμονίοις καὶ οὐ θεῷ·"}, {"sp": "N", "st": "Bar 4:8", "t": "ἐπελάθεοθκ ¹τὸν τροφεύσαντα ὑμᾶς θεὸν αἰώνιον, ἐλυπήσατε δὴ καὶ τὴν ἐκθρέψασαν ὑμᾶς Ἰερουσαλήμ."}, {"sp": "N", "st": "Bar 4:9", "t": "ἴδεν γὰρ τὴν ἐπελθοῦσαν ὑμῖν ὀργὴν παρὰ τοῦ θεοῦ, καὶ εἶπεν Ἀκούσατε, αἱ πάροικοι Σειών, ἐπήγαγέν μοι ὁ θεὸς πένθος μέγα."}, {"sp": "N", "st": "Bar 4:10", "t": "ἴδον γὰρ τὴν αἰχμαλωσίαν τῶν υἱῶν μου καὶ τῶν θυγατέρων, ἦν ἐπήγαγεν αὐτοῖς ὁ αἰώνιος."}, {"sp": "N", "st": "Bar 4:11", "t": "ἔθρεψα γὰρ αὐτοὺς μετ᾿ εὐφροσύνης, ἐξαπέστειλα δἐ μετὰ κλαυθμοῦ καὶ πένθους."}, {"sp": "N", "st": "Bar 4:12", "t": "μηδεὶς ἐπιχαιρέτω μοι τῇ χήρε καὶ καταλειφθείσῃ ὑπὸ πολλῶν· ἠρημώθην διὰ τὰς ἁμαρτίας τῶν τέκνων μου, διότι ἐξέκλιναν ἐκ νόμου θεοῦ"}, {"sp": "N", "st": "Bar 4:13", "t": "καὶ δικαιώματα αὐτοῦ οὐκ ἔγνωσαν, οὐδὲ ἐπορεύθησαν ὁδοῖς ἐντολῶν θεοῦ, οὐδὲ τρίβους παιδίας ἐν δικαιοσύνῃ αὐτοῦ ἐπέβησαν."}, {"sp": "N", "st": "Bar 4:14", "t": "ἐλθάτωσαν αἱ πάροικοι Σειών, καὶ μνήσθητε τὴν αἰχμαλωσίαν τῶν υἱῶν μου καὶ θυγατέραον, ἣν ἐπήγαγεν αὐτοῖς ὁ αἰώνιος."}, {"sp": "N", "st": "Bar 4:15", "t": "ἐπήγαγεν γὰρ ἐπʼ αὐτοὺς ἔθνος μακρόθεν, ἔθνος ἀναιδές καὶ ἀλλόγλωσσον· ὅτι οὐκ ἠσχύνθησαν πρεσβύτην οὐδὲ παιδίον ἠλέησαν,"}, {"sp": "N", "st": "Bar 4:16", "t": "καὶ ἀπήγαγον τοὺς ἀγαπητοὺς τῆς χήρας, καὶ ἀπὸ τῶν θυγατέρων τὴν μόνην ἠρήμωσαν."}, {"sp": "N", "st": "Bar 4:17", "t": "ἐγὼ δὲ τί δυνατὴ βοηθῆσαι ὑμῖν;"}, {"sp": "N", "st": "Bar 4:18", "t": "ὁ γὰρ ἐπαγαγὼν τὰ κακὰ ἐξελεῖται ὑμᾶς ἐκ χειρὸς ἐχθρῶν ὑμῶν."}, {"sp": "N", "st": "Bar 4:19", "t": "βαδίζετε, τέκνα, βαδίζετε, ἐγὼ γὰρ κατελείφθην ἔρημος."}, {"sp": "N", "st": "Bar 4:20", "t": "ἐξεδυσάμην τὴν στολὴν τῆς εἰρήνης, ἐνεδυσάμην δὲ σάκκον τῆς δεήσεως μου· κεκράξομαι πρὸς τὸν αἰώνιον ἐν ταῖς ἡμέραις μου."}, {"sp": "N", "st": "Bar 4:21", "t": "Ραρρεῖτε, τέκνα, βοήσατε πρὸς τὸν θεόν, καὶ ἐξελεῖται ὑμᾶς ἐκ δυναστείας, ἐκ χειρὸς ἐχθρῶν."}, {"sp": "N", "st": "Bar 4:22", "t": "ἐγὼ γὰρ ἥλπισα ἐπὶ τῷ αἰωνίῳ τὴν σωτηρίαν ὑμῶν, καὶ ἔλθέν μοι χαρὰ παρὰ τοῦ ἁγίου ἐπὶ τῇ ἐλεημοσύνῃ, ἡ ἤξει ὑμῖν ἐν τάχει παρὰ τοῦ αἰωνίου σωτῆρος ὑμῶν."}, {"sp": "N", "st": "Bar 4:23", "t": "ἐξέπεμψα γὰρ ὑμᾶς μετὰ πένθους καὶ κλαυθμοῦ, ἀποδώσει δέ μοι ὁ θεὸς ὑμᾶς μετά χαρμοσύνης καὶ εὐφροσύνης εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Bar 4:24", "t": "ἅσπερ γὰρ νῦν ἑωράκασιν αἱ πάροικοι Σειὼν τὴν ὑμετέραν αἰχμαλωσίαν, οὕτως ὄψονται ἐν τάχει τὴν παρὰ τοῦ θεοῦ ὑμῶν σωτηρίαν, ἡ ἐπελεύσεται ὑμῖν μετὰ δόξης μεγάλης καὶ λαμπρότητος τοῦ αἰωνίου."}, {"sp": "N", "st": "Bar 4:25", "t": "τέκνα, μακροθυμήσατε τὴν παρὰ τοῦ θεοῦ ἐπελθοῦσαν ὑμῖν ὀργήν· κατεδίωξέν σε ὁ ἐχθρός, καὶ ὄψει αὐτοῦ τὴν ἀπώλειαν ἐν τάχει, καὶ ἐπὶ τραχήλους αὐτῶν ἐπιβήσῃ."}, {"sp": "N", "st": "Bar 4:26", "t": "οἱ τρυφεροί μου ἐπορεύθησαν ὁδοὺς τραχείας, ρθησαν ὡς ποίμνιον ἡρπασμένον ὑπὸ ἐχθρῶν."}, {"sp": "N", "st": "Bar 4:27", "t": "Θαρρήσατε, τέκνα, καὶ βοήσατε πρὸς τὸν θεόν, ἔσται γὰρ ὑμῶν ὑπὸ τοῦ ἐπάγοντος μνεία."}, {"sp": "N", "st": "Bar 4:28", "t": "ώσπερ γὰρ ἐγένετο ἡ διάνοια ὑμῶν εἰς τὸ πλανηθῆναι ἀπὸ τοῦ θεοῦ, δεκαπλασιάσατε ἐπιστραφέντες ζητῆσαι αὐτόν."}, {"sp": "N", "st": "Bar 4:29", "t": "ὁ γὰρ ἐπαγαγὼν ὑμῖν τὰ κακὰ ἐπάξει ὑμῖν τὴν αἰώνιον εὐφροσύνην μετὰ τῆς σωτηρίας ὑμῶν."}, {"sp": "N", "st": "Bar 4:30", "t": "Θάρσει, Ἰερουσαλήμ, παρακαλέσει σε ὁ ὀνομάσας σε."}, {"sp": "N", "st": "Bar 4:31", "t": "δείλαιοι οἱ σέ κακώσαντες καὶ ἐπιχαρέντες τῇ σῇ πτώσει,"}, {"sp": "N", "st": "Bar 4:32", "t": "δείλαιαι αἱ πόλεις αἷς ἐδούλευσαν τὰ τέκνα σου, δειλαία ἡ δεξαμένη τοὺς υἱούς σου."}, {"sp": "N", "st": "Bar 4:33", "t": "ὥσπερ γὰρ ἐχάρη ἐπὶ τῇ σῇ πτώσει καὶ εὐφράνθη ἐπὶ τῷ πτώματί σου, οὕτως λυπηθήσεται ἐπὶ τῇ ἑαυτῆς ἐρημίᾳ."}, {"sp": "N", "st": "Bar 4:34", "t": "καὶ περιελῶ αὐτῆς τὸ ἀγαλλίαμα τῆς πολυοχλίας, καὶ τὸ ἀγαυρίαμα αὐτῆς εἰς πένθος."}, {"sp": "N", "st": "Bar 4:35", "t": "πῦρ γάρ ἐπελεύσεται αὐτῇ παρά τοῦ αἰωνίου εἰς ἡμέρας μακράς. καὶ κατοικηθήσεται ὑπὸ δαιμονίων τὸν πλείονα χρόνον."}, {"sp": "N", "st": "Bar 4:36", "t": "περίβλεψαι πρὸς ἀνατολάς, Ἰερουσαλήμ, καὶ ἴδε τὴν εὐφροσύνην τὴν παρά τοῦ θεοῦ σοι ἐρχομίνην."}, {"sp": "N", "st": "Bar 4:37", "t": "ἰδοὺ ἔρχονται οἱ υἱοί σου οὓς ἐξαπέστειλας, ἔρχονται συνηγμένοι ἀπʼ ἀνατολῶν ἕως δυσμῶν τῷ όήματι τοῦ ἁγίου. χαίροντες τῇ τοῦ θεοῦ δόξῃ."}, {"sp": "N", "st": "Bar 5:1", "t": "Ἔκδυσαι, Ἰερουσαλήμ, τὴν στολὴν τοῦ πένθους καὶ τῆς κακώσεως σου, καὶ ἔνδυσαι τὴν εὐπρέπειαν τῆς παρά τοῦ θεοῦ δόξης εἰς τὸν αἰῶνα."}, {"sp": "N", "st": "Bar 5:2", "t": "περιβαλοῦ τὴν διπλοίδα τῆς παρά τοῦ θεοῦ δικαιοσύνης, ἐπίθου τὴν μίτραν ἐπὶ τὴν κεφαλὴν σου τῆς δόξης τοῦ αἰωνίου."}, {"sp": "N", "st": "Bar 5:3", "t": "ὁ γὰρ θεὸς δείξει τῇ ὑπʼ οὐρανὸν πάσῃ τὴν σὴν λαμπρότητα."}, {"sp": "N", "st": "Bar 5:4", "t": "κληθήσεται γάρ σου τὸ ὄνομα παρὰ τοῦ θεοῦ εἰς τὸν αἰῶνα, εἰρήνη δικαιοσύνης καὶ δόξα θεοσεβίας."}, {"sp": "N", "st": "Bar 5:5", "t": "ἀνάστηθι, Ἰερουσαλήμ, καὶ στῆθι ἐπὶ τοῦ ὑψηλοῦ, καὶ περίβλεψαι πρὸς ἀνατολὰς καὶ ἴδε σου συνηγμένα τὰ τέκνα ἀπὸ ἡλίου δυσμῶν ἕως ἀνατολῶν τῷ όήματι τοῦ ἁγίου, χαίροντας τῇ τοῦ θεοῦ μνείᾳ."}, {"sp": "N", "st": "Bar 5:6", "t": "ἐξῆλθον γὰρ παρὰ σοῦ πεζοὶ ἀγόμενοι ὑπὸ ἐχθρῶν, εἰσάγει δὲ αὐτοὺς ὁ θεὸς πρὸς σέ αἰρομένους μετὰ δόξης ὡς θρόνον βασιλείας."}, {"sp": "N", "st": "Bar 5:7", "t": "συνέταξεν γὰρ ὁ θεὸς ταπεινοῦσθαι πᾶν ὄρος ὑψηλόν, καὶ θῖνας ἀενάους καὶ φάραγγας πληροῦσθαι εἰς ὁμαλισμὸν τῆς γῆς· ἴνα βαδίσῃ Ἰσραὴλ ἀσφαλῶς τῆ τοῦ θεοῦ δόξῃ."}, {"sp": "N", "st": "Bar 5:8", "t": "ἐσκίασαν δέ καὶ οἱ δρυμοὶ καὶ πᾶν ξύλον εὐωδίας τῷ Ἰσραὴλ προστάγματι τοῦ θεοῦ."}, {"sp": "N", "st": "Bar 5:9", "t": "ἡγήσεται γὰρ ὁ θεὸς Ἰσραὴλ μετʼ εὐφροσύνης τῷ φωτὶ τῆς δόξης αὐτοῦ σὺν ἐλεημοσύνῃ καὶ δικαιοσύνῃ τῇ παρʼ αὐτοῦ."}, {"sp": "HDR", "t": "ΕΠΙΣΤΟΛΗ ΙΕΡΕΜΙΟΥ"}, {"sp": "N", "st": "Ep Jer 6:1", "t": "ANΤΙΓΡΑΦΟΝ ἐπιστολῆς ἧς ἀπέστειλεν Ἱερεμίας πρὸς τοὺς ἁχόησομένους αἰχμαλώτους εἰς Βαβυλῶνα ὑπὸ τοῦ βασιλέως τῶν Βαβυλωνίων, ἀναγγεῖλαι αὐτοῖς καθότι ἐπετάγη αὐτῷ ὑπὸ τοῦ θεοῦ."}, {"sp": "N", "st": "Ep Jer 6:2", "t": "Διὰ τὰς ἁμαρτίας ὑμῶν ἄς ἡμαρτήκατε ἐναντίον τοῦ θεοῦ ἀχθήσεσθε εἰς Βαβυλῶνα αἰχμάλωτοι ὑπὸ Ναβουχοδονοσὸρ βασιλέως τῶν Βαβυλωνίων."}, {"sp": "N", "st": "Ep Jer 6:3", "t": "εἰσελθόντες οὗν εἰς Βαβυλῶνα ἔσεσθε ἐκεῖ ἔτη πλείονα καὶ χρόνον μακρὸν ἕως γενεῶν ἑπτά· μετὰ τοῦτο δὲ ἐξάξω ὑμᾶς ἐκεῖθεν μετʼ εἰρήνης."}, {"sp": "N", "st": "Ep Jer 6:4", "t": "νυνὶ δὲ ὄψεσθε ἐν Βαβυλῶνι θεοὺς ἀργυροῦς καὶ χρυσοῦς καὶ ξυλίνους ἐπʼ ὠμοις αἰρομένους, δεικνύντας φόβον τοῖς ἔθνεσιν."}, {"sp": "N", "st": "Ep Jer 6:5", "t": "εὐλαβήθητε οὗν μὴ καὶ ὑμεῖς ἀφομοιωθέντες τοῖς ἀλλοφύλοις ἀφομοιωθῆτε, καὶ φόβος ὑμᾶς λάβῃ ἐπʼ αὐτοῖς,"}, {"sp": "N", "st": "Ep Jer 6:6", "t": "ἰδόντας ὄχλον ἔμπροσθεν καὶ ὄπισθεν αὐτῶν προσκυνοῦντας αὐτά· εἶπατε δὲ τῇ διανοίᾳ Σοὶ δεῖ προσκυνεῖν, Δἐσποτα."}, {"sp": "N", "st": "Ep Jer 6:7", "t": "ό γὰρ ἄγγελός μου μεθʼ ὑμῶν ἐστίν, αὐτός τε ἐκζητῶν τὰς ψυχὰς ὑμῶν."}, {"sp": "N", "st": "Ep Jer 6:8", "t": "Γλῶσσα γὰρ αὐτῶν ἐστὶν κατεξυσμένη ὑπὸ τέκτονος, αὐτά τε περίχρυσα καὶ περιάργυρα, ψευδῆ δʼ ἐστὶν καὶ οὐ δύνανται λαλεῖν."}, {"sp": "N", "st": "Ep Jer 6:9", "t": "καὶ ὥσπερ παρθένῳ φιλοκόσμῳ λαμβάνοντες χρυσίον"}, {"sp": "N", "st": "Ep Jer 6:10", "t": "κατασκευἀζουσιν στεφάνους ἐπὶ τὰς κεφαλὰς τῶν θεῶν αὐτῶν· ἔστι δέ καὶ ὅτε ὑφαιρούμενοι οἱ ἱερεῖς ἀπὸ τῶν θεῶν αὐτῶν χρυσίον καὶ ἀργύριον εἰς ἑαυτοὺς καταναλοῦσιν,"}, {"sp": "N", "st": "Ep Jer 6:11", "t": "δώσουσιν δὲ ἀπ αὐτῶν καὶ ταῖς ἐπὶ τοῦ στέγους πόρναις. κοσμοῦσί τε αὐτοὺς ὡς ἀνθρώπους τοῖς ἐνδύμασιν, θεοὺς ἀργυροῦς καὶ θεοὺς χρυσοῦς καὶ ξυλίνους."}, {"sp": "N", "st": "Ep Jer 6:12", "t": "οὗτοι δὲ οὐ διασώζονται ἀπὸ ἰοῦ καὶ βρωμάτων, περιβεβλημένων αὐτῶν ἱματισμὸν πορφυροῦν."}, {"sp": "N", "st": "Ep Jer 6:13", "t": "ἐκμάσσονται τὸ πρόσωπον αὐτῶν διὰ τὸν ἐκ τῆς οἰκίας κονιορτόν, ὅς ἐστιν πλείω ἐπʼ αὐτοῖς."}, {"sp": "N", "st": "Ep Jer 6:14", "t": "καὶ σκῆπτρον ἔχει ὁὡς ἄνθρωπος κριτὴς χώρας, ὸς τὸν εἰς αὐτὸν ἁμαρτάνοντα οὐκ ἀνελεῖ."}, {"sp": "N", "st": "Ep Jer 6:15", "t": "ἔχει δὲ ἐνχειρίδιον δεξιῷ καὶ πέλεκυν, ἑαυτὸν δὲ ἐκ πολέμου καὶ λῃστῶν οὐκ ἐξελεῖται. ὅθεν γνώριμοί εἰσιν οὐκ ὄντες θεοί μὴ οὗν φοβηθῆτε αὐτούς."}, {"sp": "N", "st": "Ep Jer 6:16", "t": "Ὥσπερ γὰρ σκεῦος ἀνθρώπου συντριβὲν ἀχρεῖον γίνεται,"}, {"sp": "N", "st": "Ep Jer 6:17", "t": "τοιοῦτοι ὑπάρχουσιν οἱ θεοὶ αὐτῶν, καθιδρυμένων αὐτῶν ἐν τοῖς οἴκοις. οἱ ὀφθαλμοὶ αὐτῶν πλήρεις εἰσὶν κονιορτοῦ ἀπὸ τῶν ποδῶν τῶν εἰσπορευομένων."}, {"sp": "N", "st": "Ep Jer 6:18", "t": "καὶ ὥσπερ τινὶ ἠδικηκότι βασιλέα περιπεφραγμέναι εἰσὶν αἱ αὐλαί, ὡς ἐπὶ θανάτῳ ἀπηγμένῳ, τοὺς οἴκους αὐτῶν ὐχυροῦσιν οἱ ἱερεῖς θυρώμασίν τε καὶ κλείθροις καὶ μοχλοῖς, ὅπως ὑπὸ τῶν λῃστῶν μὴ συληθῶσι"}, {"sp": "N", "st": "Ep Jer 6:19", "t": "λύχνους καίουσιν καὶ πλείους ἑαυτοῖς, ὧν οὐδένα δύνανται ἰδεῖν."}, {"sp": "N", "st": "Ep Jer 6:20", "t": "ἔστιν μέν ὥσπερ δοκὸς τῶν ἐκ τῆς οἰκίας, τὰς δέ καρδίας αὐτῶν φασὶν ἐκλείχεσθαιʼ τῶν ἀπὸ τῆς γῆς ἑρπετῶν κατεσθόντων αὐτοὺς τε καὶ τὸν ἱματισμὸν αὐτῶν οὐκ αἰσθάνονται."}, {"sp": "N", "st": "Ep Jer 6:21", "t": "μεμελανωμένοι τὸ πρόσωπον αὐτῶν ἀπὸ τοῦ καπνοῦ τοῦ ἐκ τῆς οἰκίας."}, {"sp": "N", "st": "Ep Jer 6:22", "t": "ἐπ ὶ τὸ σώμα αὐτῶν καὶ ἐπὶ τὴν κεφαλὴν ἐφίπτανται νυκτερίδες, χελιδόνες καὶ τὰ ὄρνεα, ὡσαύτως δὲ καὶ οἱ αἵλουροι."}, {"sp": "N", "st": "Ep Jer 6:23", "t": "ἰθεν γνώσεσθε ὅτι οὐκ εἰσὶν θεοί μὴ οὗν φοβεῖσθε αὐτά."}, {"sp": "N", "st": "Ep Jer 6:24", "t": "Τὸ γὰρ χρυσίον ὁ περίκεινται εἰς κάλλος, ἐὰν μή τις ἐκμάξῃ τὸν ἰόν, οὐ μὴ στίλψωσιν· οὐδὲ γὰρ ὅτε ἐχωνεύοντο ἠσθάνοντο."}, {"sp": "N", "st": "Ep Jer 6:25", "t": "ἐκ πάσης τιμῆς ἠγορασμένα ἐστίν, ἐν οἷς οὐκ ἔστιν πνεῦμα."}, {"sp": "N", "st": "Ep Jer 6:26", "t": "ἄνευ ποδῶν ἐπʼ ὀμοις φέρονται ἐνδεικνύμενοι τὴν ἑαυτῶν ἀτιμίαν τοῖς ἀνθρώποις, αἰσχύνονταί τε καὶ οἱ θεραπεύοντες αὐτά,"}, {"sp": "N", "st": "Ep Jer 6:27", "t": "διὰ τό, μὴ ποτε ἐπὶ τὴν γῆν πέσῃ, δι᾿ αὐτῶν ἀνίστασθαι· μήτε ἐάν τις αὐτὸ ὀρθὸν στήσῃ, δι᾿ ἑαυτοῦ κινηθήσεται, μήτε ἐὰν κλιθῇ, οὐ μὴ ὀρθωθῇ, ἀλλʼ ἶσπερ νεκροῖς τὰ δώρα αὐτοῖς παρατίθεται."}, {"sp": "N", "st": "Ep Jer 6:28", "t": "τὰς δὲ θυσίας αὐτῶν ἀποδόμενοι οἱ ἱερεῖς αὐτῶν καταχρῶνται· ὡσαύτως δὲ καὶ αἱ γυναῖκες ἀπʼ αὐτῶν ταριχεύουσαι οὕτε πτωχῷ οὕτε ἀδυνάτῳ μὴ μεταδώσιν·"}, {"sp": "N", "st": "Ep Jer 6:29", "t": "τῶυ θυσιῶν αὐτῶν ἀποκαθημένη καὶ λεχὼς ἄπτονται. γνόντες οὗν ἀπὸ τούτων ὅτι οὐκ εἰσὶν θεοί, μὴ φοβηθῆτε αὐτοὺς."}, {"sp": "N", "st": "Ep Jer 6:30", "t": "Πόθεν γὰρ κληθείησαν θεοί; ὅτι γυναῖκες παρατιθέασιν θεοῖς ἀργυροῖς καὶ χρυσοῖς καὶ ξυλίνοις·"}, {"sp": "N", "st": "Ep Jer 6:31", "t": "καὶ ἐν τοῖς οἴκοις αὐτῶν οἱ ἱερεῖς διφρεύουσιν, ἔχοντες τοὺς χιτῶνας διερραωγότας καὶ τὰς κεφαλὰς καὶ τοὺς πώγωνας ἐξυρημένους, ὧν αἱ κεφαλαὶ ἀκάλυπτοί εἰσιν,"}, {"sp": "N", "st": "Ep Jer 6:32", "t": "ὠρύονται δέ βοώντες ἐναντίον τῶν θεῶν αὐτῶν ώσπερ τινές ἐν περιδείπνῳ νεκροῦ."}, {"sp": "N", "st": "Ep Jer 6:33", "t": "ἀπὸ τοῦ ἱματισμοῦ αὐτῶν ἀφελόμενοι οἱ ἱερεῖς ἐνδύσουσιν τὰς γυναίκας αὐτῶν καὶ τὰ παιδία·"}, {"sp": "N", "st": "Ep Jer 6:34", "t": "οδτε ἐὰν κακὸν πάθωσιν ὑπό τινος οὕτε ἐὰν ἀγαθόν, δυνήσονται ἀνταποδοῦναι· οὕτε καταστῆσαι βασιλέα δύνανται οὕτε ἀφελέσθαι."}, {"sp": "N", "st": "Ep Jer 6:35", "t": "ὁὡσαύτως οὕτε πλοῦτον οὐτε χαλκὸν οὐ μὴ δύνωνται διδόναι· ἐάν τις αὐτοῖς εὐχὴν εὐξάμενος μὴ ἀποδῷ, οὐ μὴ ἐπιζητήσωσιν·"}, {"sp": "N", "st": "Ep Jer 6:36", "t": "ἐκ θανάτου ἄνθρωπον οὐ μὴ όύσωνται, οὐτε ἥττονα ἀπὸ ἰσχυροῦ μὴ ἐξέλωνται·"}, {"sp": "N", "st": "Ep Jer 6:37", "t": "Μνθρωπον τυφλὸυ εἰς ὄρασιν οὐ μὴ περιστήσωσιν, ἐν ἀνάγκῃ ἄνθρωπον ὄντα οὐ μὴ ἐξέλωνται·"}, {"sp": "N", "st": "Ep Jer 6:38", "t": "χήραν οὐ μὴ ἐλεήσωσιν, οὕτε ὀρφανὸν εὗ ποιήσουσιν."}, {"sp": "N", "st": "Ep Jer 6:39", "t": "τοῖς ἀπὸ τοῦ ὄρους λίθοις ὡμοιωμένοι εἰσὶν τὰ ξύλινα καὶ τὰ περίχρυσα καὶ τὰ περιάργυρα, οἱ δῆ θεραπεύοντες αὐτὰ καταισχυνθήσονται."}, {"sp": "N", "st": "Ep Jer 6:40", "t": "πώς οὗν νομιστέον ἤ κλητέον αὐτοὺς ὑπάρχειν θεούς;"}, {"sp": "N", "st": "Ep Jer 6:41", "t": "Ἐτι δὲ καὶ αὐτῶν τῶν Χαλδαίων ἀτιμαζόντων αὐτά, oζ ὅταν ἴδωσιν ἐνεὸν οὐ δυνάμενον λαλῆσαι, προσενεγκάμενοι τὸν Βῆλον ἀξιοῦσιν φωνῆσαι, ὡς δυνατοῦ ὄντος αὐτοῦ αἰσθέσθαι,"}, {"sp": "N", "st": "Ep Jer 6:42", "t": "καὶ οὐ δύνανται αὐτοὶ νοήσαντες καταλιπεῖν αὐτά, αἵσθησιν γὰρ οὐκ ἔχουσιν."}, {"sp": "N", "st": "Ep Jer 6:43", "t": "αἱ δὲ γυναῖκες περιθέμεναι σχοινία ἐν ταῖς οδοῖς ενκαθηνται, θυμιῶσαι τὰ πίτυρα·"}, {"sp": "N", "st": "Ep Jer 6:44", "t": "ὅταν δέ τις αὐτῶν ἐφελκυσθεῖσα ὑπό τινος τῶν παραπορευομένων κοιμηθῇ, τὴν πλησίον ὀνειδίζει, ὅτι οὐκ ἠξίωται ὥσπερ καὶ αὐτὴ οὕτε τὸ σχοινίον αὐτῆς διερράγη."}, {"sp": "N", "st": "Ep Jer 6:45", "t": "πάντα τὰ γενόμενα αὐτοῖς ἐστὶν ψευδῆ. πῶς οὗν νομιστέον ἡ κλητέον ὡς θεοὺς αὐτοὺς ὑπάρχειν"}, {"sp": "N", "st": "Ep Jer 6:46", "t": "Ὑπὸ τεκτόνων καὶ χρυσοχόων κατασκευασμένα εἰσίν· οὐθὲν ἄλλο μὴ γένηται ἤ ὃ βούλονται οἱ τεχνῖται αὐτὰ γενέσθαι."}, {"sp": "N", "st": "Ep Jer 6:47", "t": "φὐτοί τε οἱ κατασκευάζοντες αὐτὰ οὐ μὴ γένωνται πολυχρόνιοι·"}, {"sp": "N", "st": "Ep Jer 6:48", "t": "πῶς τε δὴ μέλλει τὰ ὑπʼ αὐτῶν κατασκευασθέντα; κατέλιπον γὰρ ψεύδη καὶ ὄνειδος τοῖς ἐπιγινομένοις."}, {"sp": "N", "st": "Ep Jer 6:49", "t": "ὅταν γὰρ ἐπέλθῃ ἐπʼ αὐτὰ πόλεμος καὶ κακά, βουλεύονται πρὸς ἑαυτοὺς οἱ ἱερεῖς ποῦ συναποκρυβῶσι μετʼ αὐτῶν."}, {"sp": "N", "st": "Ep Jer 6:50", "t": "πῶς οὗν οὐκ ἔστιν αἰσθέσθαι ὅτι οὐκ εἰσὶν θεοί, οἱ οδτε σώζουσιν ἑαυτοὺς ἐκ πολέμου οὕτε ἐκ κακῶν;"}, {"sp": "N", "st": "Ep Jer 6:51", "t": "ὑπάρχοντα γὰρ ξύλινα καὶ περίχρυσα καὶ περιάργυρα γνωσθήσεται μετὰ ταῦτα ὅτι ἐστὶν ψευδῆ· τοῖς ἔθνεσι πᾶσι τοῖς τε βασιλεῦσι φανερὸν ἔσται ὅτι οὐκ εἰσὶ θεοὶ ἀλλὰ ἔργα χειρῶν ἀνθρώπων, καὶ οὐδὲν θεοῦ ἔργον ἐν αὐτοῖς ἐστίν."}, {"sp": "N", "st": "Ep Jer 6:52", "t": "Τίνι οὗν γνωστέον ἐστὶν ὅτι οὐκ εἰσὶν θεοί;"}, {"sp": "N", "st": "Ep Jer 6:53", "t": "βασιλέα γὰρ χώρας οὐ μὴ ἀναστήσωσιν, οὕτε ὑετὸν ἀνθρώποις οὐ μὴ δώσιν,"}, {"sp": "N", "st": "Ep Jer 6:54", "t": "κρίσιν τε οὐ μὴ διακρίνωσιν ἑαυτῶν, οὐδὲ μὴ όύσωνται ἀδίκημα, ἀδύνατοι ὄντες·"}, {"sp": "N", "st": "Ep Jer 6:55", "t": "ὥσπερ γὰρ κορῶναι ἀνὰ μέσον τοῦ οὐρανοῦ καὶ τῆς γῆς. καὶ γὰρ ὅταν ἐμπέσῃ εἰς οἰκίαν θεῶν ξυλίνων ἡ περιχρύσων ἡ περιαργύρων πῦρ, οἱ μέν ἱερεῖς αὐτῶν φεύξονται καὶ διασωθήσονται, αὐτοὶ δὲ ὥσπερ δοκοὶ μέσοι κατακαυθήσονται."}, {"sp": "N", "st": "Ep Jer 6:56", "t": "βασιλεῖ δέ καὶ πολεμίοις οὐ μὴ ἀντιστώσιν."}, {"sp": "N", "st": "Ep Jer 6:57", "t": "πῶς οὗν ἐκδεκτέον ἤ νομιστέον ὅτι εἰσὶν θεοί; Οδτε ἀπὸ κλεπτῶν οὕτε ἀπὸ λῃστῶν οὐ μὴ διαθώσιν, θεοὶ ξύλινοι καὶ περιάργυροι καὶ περίχρυσοι·"}, {"sp": "N", "st": "Ep Jer 6:58", "t": "ὦν οἱ ἰσχύοντες περιελοῦνται τὸ χρυσίον καὶ τὸ ἀργύριον, καὶ τὸν ἱματισμὸν τὸν περικείμενον αὐτοῖς ἀπελεύσονται ἔχοντες, οὕτε ἑαυτοῖς οὐ μὴ βοηθήσωσιν."}, {"sp": "N", "st": "Ep Jer 6:59", "t": "ζώστε κρεῖσσον εἶναι βασιλέα ἐπιδεικνύμενον τὴν ἑαυτοῦ ἀνδρείαν ἡ σκεῦος ἐν οἰκίᾳ χρήσιμον, ἐφ ᾧ κεχρήσεται ὁ κεκτημένος, ἤ οἱ ψευδεῖς θεοί ἡ καὶ θύρα ἐν οἰκίᾳ διασώζουσα τὰ ἐν αὐτῇ ὄντα ἤ οἱ ψευδεῖς θεοί, καὶ ξύλινος στύλος ἐν βασιλείοις ἤ οἱ ψευδεῖς θεοί"}, {"sp": "N", "st": "Ep Jer 6:60", "t": "ἥλιος μὲν γὰρ καὶ σελήνη καὶ ἄστρα ὄντα λαμπρὰ καὶ ἀποστελλόμενα ἐπὶ χρείας εὐήκοα εἰσιν."}, {"sp": "N", "st": "Ep Jer 6:61", "t": "ῶὡσαύτως καὶ ἀστραπὴ ὅταν ἐπιφανῇ εὐοπτός ἐστιν· τὸ δʼ αὐτὸ καὶ πνεῦμα ἐν πάσῃ χώρᾳ πνεῖ"}, {"sp": "N", "st": "Ep Jer 6:62", "t": "καὶ νεφέλαις ὅταν ἐπιταγῇ ὑπὸ τοῦ θεοῦ ἐπιπορεύεσθαι ἐφʼ ὅλην τὴν οἰκουμένην, συντελοῦσι τὸ ταχθέν."}, {"sp": "N", "st": "Ep Jer 6:63", "t": "χ ό τε πῦρ ἐξαποσταλὲν ἄνωθεν ἐξαναλῶσαι ὄρη καὶ δρυμοὺς ποιεῖ τὸ συνταχθέν. ταῦτα δὲ oδτε ταῖς εἰδέαις οὕτε ταῖς δυνάμεσιν αὐτῶν ἀφωμοιωμένα ἐστίν."}, {"sp": "N", "st": "Ep Jer 6:64", "t": "ὅδεν οὕτε νομιστέον οὕτε κλητέον ὑπάρχειν αὐτοὺς θεούς, οὐ δυνατῶν ὄντων αὐτῶν οὕτε κρίσιν κρῖναι οὕτε εὗ ποιεῖν ἀυθρώποις."}, {"sp": "N", "st": "Ep Jer 6:65", "t": "γνόντες οὗν ὅτι οὐκ εἰσὶν θεοί, μὴ φοβηθῆτε αὐτούς."}, {"sp": "N", "st": "Ep Jer 6:66", "t": "Οὔτε γὰρ βασιλεῦσιν οὐ μὴ καταράσωνται οὕτε μὴ εὐλογήσωσι."}, {"sp": "N", "st": "Ep Jer 6:67", "t": "σημεῖά τε ἐυ ἔθνεσιν ἐν οὐρανῷ οὐ μὴ δείξωσιν, οὐδὲ ὡς ὁ ἥλιος λάμψουσιν, οὐδὲ φωτίσουσιν ὡς σελήνη."}, {"sp": "N", "st": "Ep Jer 6:68", "t": "τὰ θηρία ἐστὶν κρείττω αὐτῶν, ἄ δύνανται ἐκφυγόντα εἰς σκέπην αὐτὰ φελῆσαι."}, {"sp": "N", "st": "Ep Jer 6:69", "t": "κατʼ οὐδένα οὗν τρόπον ἐστὶν ἡμῖν φανερὸν ὅτι εἰσὶν θεοί διὸ μὴ φοβηθῆτε αὐτούς."}, {"sp": "N", "st": "Ep Jer 6:70", "t": "Ὥσπερ γὰρ ἐν σικυηράτῳ προβασκάνιον οὐδὲν φυλάσσον, οὕτως οἱ θεοὶ αὐτῶν εἰσὶν ξύλινοι καὶ περίχρυσοι καὶ περιάργυροι."}, {"sp": "N", "st": "Ep Jer 6:71", "t": "τὸν αὐτὸν τρόπον καὶ τῇ ἐν κήπῳ όάμνῳ, ἐφʼ ἧς πᾶν ὄρνεον ἐπικάθηται, ὡσαύτως δὲ καὶ νεκρῷ ἐρριμμένῳ ἐν σκότει ἀφωμοίωνται οἱ θεοὶ αὐτῶν ξύλινοι καὶ περίχρυσοι καὶ περιάργυροι."}, {"sp": "N", "st": "Ep Jer 6:72", "t": "ἀπό τε τῆς πορφύρας καὶ τῆς μαρμάρου τῆς ἐπʼ αὐτοὺς σηπομένης γνωσθήσεται ὅτι οὐκ εἰσὶν θεοί αὐτά τε ἐξ ὑστέρου βρωθήσονται, καὶ ἔσται ὄνειδος ἐν τῇ χώρᾳ."}, {"sp": "N", "st": "Ep Jer 6:73", "t": "κρείσσων οὖν ἄνθρωπος δίκαιος οὐκ ἔχων εἶδωλα, ἔσται γὰρ μακράν ἀπὸ ὀνειδισμοῦ."}, {"sp": "HDR", "t": "ΠΡΟΣΕΥΧΗ ΑΖΑΡΙΟΥ ΚΑΙ ΥΜΝΟΣ ΤΩΝ ΤΡΙΩΝ"}, {"sp": "N", "st": "S3Y 1", "t": "Καὶ περιεπάτουν ἐν μέσῳ τῆς φλογὸς ὑμνοῦντες τὸν θεὸν καὶ εὐλογοῦντες τὸν κύριον."}, {"sp": "N", "st": "S3Y 2", "t": "καὶ συνστὰς Ἀζαρίας προσηύξατο οὕτως καὶ ἀνοίξας τὸ στόμα ἑαυτοῦ ἐν μέσῳ τοῦ πυρὸς εἶπευ"}, {"sp": "N", "st": "S3Y 3", "t": "Εὐλογητὸς εἶ, Κύριε ὁ θεὸς τῶν πατέρων ἡμῶν, καὶ αἰνετός, καὶ δεδοξασμένον τὸ ὄνομά σου εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 4", "t": "ὅτι δίκαιος εἶ ἐπὶ πᾶσιν οἷς ἐποίησας, καὶ πάντα τὰ ἔργα σου ἀληθινά, καὶ εὐθεῖαι αἱ ὁδοί σου, καὶ πᾶσαι αἱ κρίσεις σου ἀλήθεια."}, {"sp": "N", "st": "S3Y 5", "t": "καὶ κρίματα ἀληθείας ἐποίησας κατὰ πάντα ἃ ἐπήγαγες ἡμῖν καὶ ἐπὶ τὴν πόλιν τὴν ἁγίαν τὴν τῶν πατέρων ἡμῶν Ἰερουσαλήμ· ὅτι ἐν ἀληθείᾳ καὶ κρίσει ἐπήγαγες πάντα ταῦτα διὰ τὰς ἁμαρτίας ἡμῶν."}, {"sp": "N", "st": "S3Y 6", "t": "ὅτι ἡμάρτομεν καὶ ἠνομήσαμεν ἀποστῆναι ἀπὸ σοῦ, καὶ ἐξημάρτομεν ἐν πᾶσιν·"}, {"sp": "N", "st": "S3Y 7", "t": "καὶ τῶν ἐντολῶν σου οὐκ ἠκούσαμεν οὐδὲ συνετηρήσαμεν, οὐδὲ ἐποιήσαμεν καθὼς ἐνετείλω ἡμῖν ἵνα εὗ ἡμῖν γένηται."}, {"sp": "N", "st": "S3Y 8", "t": "καὶ πάντα ὅσα ἡμῖν ἐπήγαγες καὶ πάντα ὅσα ἐποίησας ἡμῖν, ἐν ἀληθινῇ κρίσει ἐποίησας."}, {"sp": "N", "st": "S3Y 9", "t": "καὶ παρέδωκας ἡμᾶς εἰς χεῖρας ἐχθρῶν ἀνόμων καὶ ἐχθίστων ἀποστατῶν, καὶ βασιλεῖ ἀδίκῳ καὶ πονηροτάτῳ παρὰ πᾶσαν τὴν γῆν."}, {"sp": "N", "st": "S3Y 10", "t": "καὶ νῦν οὐκ ἔστιν ἡμῖν ἀνοῖξαι τὸ στόμα ἡμῶν· αἰσχύνη καὶ ὄνειδος ἐγενήθη τοῖς δούλοις σου καὶ τοῖς σεβομένοις σε."}, {"sp": "N", "st": "S3Y 11", "t": "μὴ δὴ παραδοῖς ἡμᾶς εἰς τέλος διὰ τὸ ὄνομά σου, καὶ μὴ διασκεδάσῃς τὴν διαθήκην σου,"}, {"sp": "N", "st": "S3Y 12", "t": "καὶ μὴ ἀποστήσῃς τὸ ἔλεός σου ἀφʼ ἡμῶν, ὄι Ἀβραὰμ τὸν ἠγαπημένον ὑπὸ σοῦ καὶ διὰ Ἰσαὰκ τὸν δοῦλόν σου καὶ Ἰσραὴλ τὸν ἅγιόν σου,"}, {"sp": "N", "st": "S3Y 13", "t": "οἶς ἐλάλησας πληθῦναι τὸ σπέρμα αὐτῶν ὡς τὰ ἄστρα τοῦ οὐρανοῦ καὶ ὡς τὴν ἄμμον τὴν παρὰ τὸ χεῖλος τῆς θαλάσσης."}, {"sp": "N", "st": "S3Y 14", "t": "ὅτι, δέσποτα, ἐσμικρύνθημεν παρὰ πάντα τὰ ἔθνη, καί ἐσμεν ταπεινοὶ ἐν πάσῃ τῇ γῇ σήμερον διὰ τὰς ἁμαρτίας ἡμῶν."}, {"sp": "N", "st": "S3Y 15", "t": "καὶ οὐκ ἔστιν ἐν τῷ καιρῷ τούτῳ ἄρχων καὶ προφήτης καὶ ἡγούμενος, οὐδὲ ὁλοκαύτωσις οὐδὲ θυσία οὐδὲ προσφορὰ οὐδὲ θυμίαμα, οὐ τόπος τοῦ καρπῶσαι ἐναντίον σου καὶ εὑρεῖν ἔλεος."}, {"sp": "N", "st": "S3Y 16", "t": "ἀλλʼ ἐυ ψυχῇ συντετριμμένῃ καὶ πνεύματι ταπεινώσεως προσδεχθείημεν·"}, {"sp": "N", "st": "S3Y 17", "t": "ὡς ἐυ ὁλοκαυτώσει κριῶν καὶ ταύρων καὶ ἐν μυριάσιν ἀρνῶν πιόνων, οὕτως γενέσθω θυσία ἡμῶν ἐνώπιόν σου σήμερον καὶ ἐκτελέσαι ὄπισθέν σου, ὅτι οὐκ ἔσται αἰσχύνη τοῖς πεποιθόσιν ἐπὶ σοί."}, {"sp": "N", "st": "S3Y 18", "t": "καὶ νῦν ἐξακολουθοῦμεν ἐν ὅλῃ καρδίᾳ, καὶ φοβούμεθά σε καὶ ζητοῦμεν τὸ πρόσωπόν σου."}, {"sp": "N", "st": "S3Y 19", "t": "μὴ καταισ χύνῃς ἡμᾶς, ἀλλὰ ποί ησον μεθʼ ἡμῶν κατὰ τὴν ἐπιείκειάν σου καὶ κατὰ τὸ πλῖθος τοῦ ἐλέους σου."}, {"sp": "N", "st": "S3Y 20", "t": "καὶ ἐξελοῦ ἡμᾶς κατὰ τὰ θαυμάσιαά σου, καὶ δὸς δόξαν τῷ ὀνόματι σου, Κύριε."}, {"sp": "N", "st": "S3Y 21", "t": "καὶ ἐντραπείησαν πάντες οἱ ἐνδεικνύμενοι τοῖς δούλοις σου κακά, καὶ καταισχυνθείησαν ἀπὸ πάσης τῆς δυναστείας, καὶ ἡ ἰσχὺς αὐτῶν συντριβείη,"}, {"sp": "N", "st": "S3Y 22", "t": "γνώτωσαν ὅτι σὺ κἶ Κύριος θεὸς μόνος καὶ ἔνδοξος ἐφʼ ὅλην τὴν οἰκουμένην."}, {"sp": "N", "st": "S3Y 23", "t": "Καὶ οὐ διέλειπον οἱ ἐμβάλλοντες αὐτοὺς ὑπηρέται τοῦ βασιλέως καίοντες τὴν κάμινον νάφθαν καὶ πίσσαν καὶ στιππύον καὶ κληματίδα."}, {"sp": "N", "st": "S3Y 24", "t": "καὶ διεχεῖτο ἡ φλὸξ ἐπάνω τῆς καμίνου ἐπὶ πήχεις τεσσεράκοντα ἐννέα,"}, {"sp": "N", "st": "S3Y 25", "t": "καὶ διώδευσεν καὶ ἐνεπύρισεν οὓς εὗρεν περὶ τὴν κάμινον τῶν Χαλδαίων."}, {"sp": "N", "st": "S3Y 26", "t": "ὁ δὲ ἄγγελος Κυρίου συνκατέβη ἄμα τοῖς περὶ τὸν Ἀζαρίαν εἰς τὴν κάμινον, καὶ ἐξετίναξεν τὴν φλόγα τοῦ πυρὸς ἐκ τῆς καμίνου,"}, {"sp": "N", "st": "S3Y 27", "t": "καὶ ἐποίησεν τὸ μέσον τῆς καμίνου ὡς πνεῦμα δρόσου διασυρίζον· καὶ οὐχ ἥψατο αὐτῶν τὸ καθόλου τὸ πῦρ, καὶ οὐκ ἐλύπησεν οὐδὲ παρηνώχλησεν αὐτοῖς."}, {"sp": "N", "st": "S3Y 28", "t": "Τότε οἱ τρεῖς ὡς ἐξ ἑνὸς στόματος ὕμνουν καὶ ἐδόξαζον καὶ εὐλόγουν τὸν θεὸν ἐν τῇ καμίνῳ λέγοντες"}, {"sp": "N", "st": "S3Y 29", "t": "⁵²Εὐλογητὸς εἶ, Κύριε ὁ θ??ὸς τῶν πατέρων ἡμῶν, καὶ αἰνετὸς καὶ ὑπερυψούμενος εἰς τοὺς αἰῶνας· καὶ εὐλογημένον τὸ ὄνομα τῆς δόξης σου τὸ ἅγιον, καὶ ὑπεραινετὸν καὶ ὑπερυψούμενον εἰς πάντας τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 30", "t": "⁵³εὐλογημένος εἶ ἐν τῷ ναῷ τῆς ἁγίας δόξης σου, καὶ ὑπερυμνητὸς καὶ ὑπερένδοξος εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 31", "t": "⁵⁴εὐλογημένος εἶ ὁ ἐπιβλέπων ἀβύσσους, καθήμενος ἐπὶ χερουβείν, καὶ αἰνετὸς καὶ ὑπερυψαωμένος εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 32", "t": "⁵⁵εὐλογημένος εἶ ἐπὶ θρόνου τῆς βασιλείας σου, καὶ ὑπερυμνητὸς καὶ ὑπερυψαωμένος εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 33", "t": "⁵⁶εὐλογητὸς εἶ ἐν τῷ στερεώματι τοῦ οὐρανοῦ, καὶ ὑμνητὸς καὶ δεδοξασμένος εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 34", "t": "⁵⁷εὐλογεῖτε, πάντα τὰ ἔργα Κυρίου, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 35", "t": "⁵⁹εὐλογεῖτε, οὐρανοί, τὸν κύριον ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 36", "t": "59 εὐλογεῖτε, ἄγγελοι Κυρίου, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 37", "t": "⁶0χὐλογεῖτε, ὕδατα καὶ πάντα τὰ ἐπάνω τοῦ οὐρανοῦ, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 38", "t": "⁶¹εὐλογείτω πᾶσα ἡ δύναμις τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 39", "t": "⁶²εὐλογεῖτε, ἥλιος καὶ σελήνη, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 40", "t": "⁶³εὐλογεῖτε, ἄστρα τοῦ οὐρανοῦ, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 41", "t": "⁶4εὐλογείτω πᾶς ὄμβρος καὶ δρόσος τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 42", "t": "⁶⁵εὐλογεῖτε, πάντα τὰ πνεύματα, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 43", "t": "⁶⁶τὐλογεῖτε, πῦρ καὶ καῦμα, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 44", "t": "67εὺλογεῖτε, νύκτες καὶ ἡμέραι, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 45", "t": "68εὐλογεῖτε, φῶς καὶ σκότος, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 46", "t": "⁶9εὐλογεῖτε, ψῦχος καὶ καῦμα, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 47", "t": "⁷⁰εὐλογεῖτε, πάχνη καὶ χιόνες, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 50", "t": "⁷³εὐλογεῖτε, ἀστραπαὶ καὶ νεφέλαι, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 51", "t": "⁷⁴εὐλογείτω ἡ γῆ τὸν κύριον· ὑμνείτω καὶ ὑπερυψούτω αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 52", "t": "⁷⁵εὐλογεῖτε, ὄρη καὶ βουνοί, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 53", "t": "7⁶εὐλογεῖτε, πάντα τὰ φυόμενα ἐν τῇ γῇ, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 55", "t": "7⁸κὺλογεῖτε, θάλασσαι καὶ ποταμοί, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 54", "t": "⁷⁷εὐλογεῖτε, αἱ πηγαί, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 56", "t": "⁷⁹εὐλογεῖτε, κήτη καὶ πάντα τὰ κινούμενα ἐν ὕδασιν, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 57", "t": "80κὐλογεῖτε, πάντα τὰ πετεινὰ τοῦ οὐρανοῦ, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 58", "t": "8¹εὐλογεῖτε, πάντα τὰ θηρία καὶ τὰ κτήνη, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 59", "t": "8²τὐλογεῖτε, οἱ υἱοὶ τῶν ἀνθρώπων, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 60", "t": "8³εὐλογεῖτε, Ἰσραήλ, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 61", "t": "8⁴εὐλογεῖτε, ἱερεῖς, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 62", "t": "8⁵εὐλογεῖτε, δοῦλοι, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 63", "t": "86κὺλογεῖτε, πνεύματα καὶ ψυχαὶ δικαίων, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 64", "t": "8⁷εὐλογεῖτε, ὅσιοι καὶ ταπεινοὶ τῇ καρδία, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας."}, {"sp": "N", "st": "S3Y 65", "t": "88εὐλογεῖτε, Ἀνανία, Ἀζαρία, Μεισαήλ, τὸν κύριον· ὑμνεῖτε καὶ ὑπερυψοῦτε αὐτὸν εἰς τοὺς αἰῶνας· ὅτι ἐξείλατο ἡμᾶς ἐξ ᾄδου, καὶ ἐκ χειρὸς θανάτου ἔσωσεν ἡμᾶς. καὶ ἐρύσατο ἡμᾶς ἐκ μέσου καμίνου καιομένης φλογός, καὶ ἐκ μέσου πυρὸς ἐρύσατο ἡμᾶς."}, {"sp": "N", "st": "S3Y 66", "t": "89ἐξομολοόεῖσθε τῷ κυρίᾳ. ὅτι χρηστός, ὅτι εἰς τὸν αἰῶνα τὸ ἔλεος αὐτοῦ."}, {"sp": "N", "st": "S3Y 67", "t": "90εὐλογεῖτε, πάντες οἱ σεβόμενοι τὸν κύριον, τὸν θεὸν τῶν θεῶν· ὑμνεῖτε καὶ ἐξομολογεῖσθε· ὅτι εἰς τὸν αἰῶνα τὸ ἔλεος αὐτοῦ."}, {"sp": "N", "st": "S3Y 68", "t": "Καὶ Ναβουχοδονοσὸρ ἤκουσεν ὑμνούντων αὐτῶν καὶ ἐθαύμασεν, καὶ ἐξανέστη ἐν σπουδῇ καὶ εἶπεν τοῖς μεγιστᾶσιν αὐτοῦ Οὐχὶ ἄνδρας τρεῖς ἐβάλομεν εἰς μέσον τοῦ πυρὸς πεπεδημένους; καὶ εἶπαν τῷ βασιλεῖ Ἀληθῶς, βασιλεῦ."}, {"sp": "HDR", "t": "ΣΟΥΣΑΝΝΑ"}, {"sp": "N", "st": "Sus 1:1", "t": "ΚΑΙ ἦν ἀνήρ οἰκῶν ἐν Βαβυλῶνι, καὶ ὄνομα αὐτῷ Ἰωακείμ."}, {"sp": "N", "st": "Sus 1:2", "t": "καὶ ἔλαβεν γυναῖκα ᾖ ὄνομα Σουσάννα, θυγάτηρ Χελκείου, καλὴ σφόδρα καὶ φοβουμένη τὸν κύριον."}, {"sp": "N", "st": "Sus 1:3", "t": "καὶ οἱ γονεῖς αὐτῆς δίκαιοι, καὶ ἐδίδαξαν τὴν θυγατέρα αὐτῶν κατὰ τὸν νόμον Μωυσῆ."}, {"sp": "N", "st": "Sus 1:4", "t": "καὶ ἦν Ἰωακεὶμ πλούσιος σφόδρα, καὶ ἦν αὐτῷ παράδεισος γειτνιῶν τῷ οἴκῳ αὐτοῦ· καὶ πρὸς αὐτὸν προσήγοντο οἱ Ἰουδαῖοι, διὰ τὸ εἶναι αὐτὸν ἐνδοξότερον πάντων."}, {"sp": "N", "st": "Sus 1:5", "t": "Καὶ ἀπεδείχθησαν δύο πρεσβύτεροι ἐκ τοῦ λαοῦ κριταὶ ἐν τῷ ἐνιαυτῷ ἐκείνῳ, περὶ ὧν ἐλάλησεν ὁ δεσπότης ὅτι ἐξῆλθεν ἀνομία ἐκ Βαβυλῶνος ἐκ πρεσβυτέρων κριτῶν οἳ ἐδόκουν κυβερνῶν τὸν λαόν."}, {"sp": "N", "st": "Sus 1:6", "t": "οὗτοι προσεκαρτέρουν ἐν τῇ οἰκίᾳ Ἰωακείμ, καὶ ἤρχοντο πρὸς αὐτοὺς πάντες οἱ κρινόμενοι."}, {"sp": "N", "st": "Sus 1:7", "t": "καὶ ἐγένετο ἡνίκα ἀπέτρεχεν ὁ λαὸς μέσον ἡμέρας, εἰσεπορεύετο Σουσάννα καὶ περιεπάτει ἐν τῷ παραδείσῳ τοῦ ἀνδρὸς αὐτῆς."}, {"sp": "N", "st": "Sus 1:8", "t": "καὶ ἐθεώρουν αὐτὴν οἱ δύο πρεσβύτεροι καθʼ ἡμέραν εἰσπορευομένην καὶ περιπατοῦσαν, καὶ ἐγένοντο ἐν ἐπιθυμίᾳ αὐτῆς."}, {"sp": "N", "st": "Sus 1:9", "t": "καὶ διέ. στρεψαν τὸν ἑαυτῶν νοῦν, καὶ ἐξέκλιναν τοὺς ὀφθαλμοὺς αὐτῶν τοῦ μὴ βλέπειν εἰς τὸν οὐρανὸν μηδὲ μνημονεύειν κριμάτων δικαίων."}, {"sp": "N", "st": "Sus 1:10", "t": "καὶ ἦσαν ἀμφότεροι κατανενυγμένοι περὶ αὐτῆς, καὶ οὐκ ἀνήγγειλαν ἀλλήλοις τὴν ὀδύνην ἑαυτῶν·"}, {"sp": "N", "st": "Sus 1:11", "t": "ὅτι ήσχύνοντο ἀναγγεῖλαι τὴν ἐπιθυμίαν αὐτῶν ὅτι ἤθελον συγγενέσθαι αὐτῇ."}, {"sp": "N", "st": "Sus 1:12", "t": "καὶ παρετηροῦσαν φιλοτίμως καθʼ ἡμέραν ὁρᾷν αὐτήν."}, {"sp": "N", "st": "Sus 1:13", "t": "καὶ εἶπαν ἕτερος τῷ ἑτέρῳ Πορευθῶμεν δὴ εἰς οἶκον, ὅτι ἀρίστου ὥρα ἐστίν· καὶ ἐξελθόντες διεχωρίσθησαν ἀπ᾿ ἀλλήλων."}, {"sp": "N", "st": "Sus 1:14", "t": "καὶ ἀνακάμψαντες ἦλθον ἐπὶ τὸ αὐτό, καὶ ἀνετάζοντες ἀλλήλους τὴν αἰτίαν ὡμολόγησαν τὴν ἐπιθυμίαν αὐτῶν· καὶ τότε κοινῇ συνετάξαντο καιρὸν ὅτε αὐτὴν δυνήσονται εὑρεῖν μόνην."}, {"sp": "N", "st": "Sus 1:15", "t": "καὶ ἐγένετο ἐν τῷ παρατηρεῖν αὐτοὺς ἡμέραν εὔθετον εἰσῆλθέν ποτε καθὼς ἐχθές καὶ τρίτης ἡμέρας μετὰ δύο μόνων κορασίων, καὶ ἐπεθύμησε λούσασθαι ἐν τῷ παραδείσω, ὅτι καῦμα ἣν."}, {"sp": "N", "st": "Sus 1:16", "t": "καὶ οὐκ ἣν ἐκεῖ οὐδεὶς πλὴν οἱ δύο πρεσβύτεροι κεκρυμμένοι καὶ παρατηροῦντες αὐτήν."}, {"sp": "N", "st": "Sus 1:17", "t": "καὶ εἶπεν τοῖς κορασίοις Ἐνέγκατε δὴ μοι ἔλαιον καὶ σμήγματα, καὶ τὰς θύρας τοῦ παραδείσου κλείσατε, ὅπως λούσωμαι."}, {"sp": "N", "st": "Sus 1:18", "t": "καὶ ἐποίησαν καθὼς εἶπεν, καὶ ἀπέκλεισαν τὰς θύρας τοῦ παραδείσου, καὶ ἐξῆλθαν κατὰ τὰς πλαγίας θύρας ἐνέγκαι τὰ προστεταγμένα αὐταῖς, καὶ οὐκ εἴδοσαν τοὺς πρεσβυτέρους, ὅτι ἦσαν κεκρυμμένοι."}, {"sp": "N", "st": "Sus 1:19", "t": "καὶ ἐγένετο ὡς ἐξήλθοσαν τὰ κοράσια, καὶ ἀνέστησαν οἱ δύο πρεσβῦται καὶ ἐπέδραμον αὐτῇ,"}, {"sp": "N", "st": "Sus 1:20", "t": "καὶ εἶπον Ἰδοὺ αἱ θύραι τοῦ παραδείσου κέκλεινται, καὶ οὐδεὶς θεωρεῖ ἡμᾶς, καὶ ἐν ἐπιθυμίᾳ σού ἐσμεν· διὸ συνκατάθου ἡμίν, καὶ γενοῦ μεθʼ ἡμῶν."}, {"sp": "N", "st": "Sus 1:21", "t": "εἰ δὲ μή, καταμαρτυρήσομέν σου ὅτι ἦν μετὰ σοῦ νεανίσκος, καὶ διὰ τοῦτο ἐξαπέστειλας τὰ κοράσια ἀπὸ σου."}, {"sp": "N", "st": "Sus 1:22", "t": "καὶ ἀνεστέναξεν Σουσάννα καὶ εἶπεν Στενά μοι πάντοθεν· ἐάν τε γὰρ τοῦτο πράξω, θάνατός μοί ἐστιν· ἐάν τε μὴ πράξω, οὐκ ἐκφεύξομαι τὰς χεῖρας ὑμῶν."}, {"sp": "N", "st": "Sus 1:23", "t": "αἱρετόν μοί ἐστιν μὴ πράξασαν ἐνπεσεῖν εἰς τὰς χεῖρας ὑμῶν ἤ ἁμαρτεῖν ἐνώπιον Κυρίου."}, {"sp": "N", "st": "Sus 1:24", "t": "καὶ ἀνεβόησεν φωνῇ μεγάλῃ Σουσάννα· ἐβόησαν δέ καὶ οἱ δύο πρεσβῦται κατέναντι αὐτῆς."}, {"sp": "N", "st": "Sus 1:25", "t": "καὶ δραμὼν ὁ εἶς ἤνοιξεν τὰς θύρας τοῦ παραδείσου."}, {"sp": "N", "st": "Sus 1:26", "t": "ὡς δὲ ἤκουσαν τὴν κραυγὴν ἐν τῷ παραδείσῳ οἱ ἐκ τῆς οἰκίας, εἰσεπήδησαν διὰ τῆς πλαγίας θύρας ἰδεῖν τὸ συμβεβηκὸς αὐτῇ."}, {"sp": "N", "st": "Sus 1:27", "t": "ἡνίκα δὲ εἶπαν οἱ πρεσβῦται τοὺς λόγους αὐτῶν, κατῃσχύνθησαν οἱ δοῦλοι σφόδρα, ὅτι πώποτε οὐκ ἐρρέθη λόγος τοι οῦτος περὶ Σουσάννης."}, {"sp": "N", "st": "Sus 1:28", "t": "καὶ ἐγένετο τῇ ἐπαύριον ὡς συνῆλθεν ὁ λαὸς πρὸς τὸν ἄνδρα αὐτῆς Ἰωακείμ, ἦλθον οἱ δύο πρεσβῦται πλήρεις τῆς ἀνόμου ἐννοίας κατὰ Σουσάννης τοῦ θανατῶσαι αὐτήν, καὶ εἶπαν ἔμπροσθεν τοῦ λαοῦ"}, {"sp": "N", "st": "Sus 1:29", "t": "Ἀποστείλατε ἐπὶ Σουσάνναν θυγατέρα Χελκίου ἥ ἐστιν γυνὴ Ἰωακείμ. οἱ δὲ ἀπέστειλαν."}, {"sp": "N", "st": "Sus 1:30", "t": "καὶ ἦλθεν αὐτὴ καὶ οἱ γονεῖς αὐτῆς καὶ τὰ τέκνα αὐτῆς καὶ πάντες οἱ συγγενεῖς αὐτῆς."}, {"sp": "N", "st": "Sus 1:31", "t": "ἡ δὲ Σουσάννα ἦν τρυφερὰ σφόδρα καὶ καλὴ τῷ εἴδει"}, {"sp": "N", "st": "Sus 1:32", "t": "οἱ δὲ παράνομοι ἐκέλευσαν ἀποκαλυφθῆναι αὐτήν, ἦν γὰρ κατακεκαλυμμένη, ὅπως ἐμπλησθῶσιν τοῦ κάλλους αὐτῆς."}, {"sp": "N", "st": "Sus 1:33", "t": "ἔκλαιον δὲ οἱ παρʼ αὐτῆς καὶ πάντες οἱ ἰδόντες αὐτήν."}, {"sp": "N", "st": "Sus 1:34", "t": "ἀναστάντες δὲ οἱ δύο πρεσβῦται ἐν μέσῳ τῷ λαῷ ἔθηκαν τὰς χεῖρας ἐπὶ τὴν κεφαλῆν αὐτῆς·"}, {"sp": "N", "st": "Sus 1:35", "t": "35 ἡ δὲ κλαίουσα ἀνέβλεψεν εἰς τὸν οὐρανόν, ὅτι ἦν ἡ καρδία αὐτῆς πεποιθυῖα ἐπὶ Κυρίῳ."}, {"sp": "N", "st": "Sus 1:36", "t": "εἶπαν δὲ οἱ πρεσβῦται Περιπατούντων ἡμῶν ἐν τῷ παραδείσῳ μόνων εἰσῆλθεν αὕτη μετὰ δύο παιδισκῶν, καὶ ἀπέκλεισεν τὰς θύρας τοῦ παραδείσου καὶ ἀπέλυσεν τὰς παιδίσκας."}, {"sp": "N", "st": "Sus 1:37", "t": "καὶ ἦλθεν πρὸς αὐτὴν νεανίσκος, ὃς ἦν κεκρυμμένος, καὶ ἀνέπεσε μετʼ αὐτῆς."}, {"sp": "N", "st": "Sus 1:38", "t": "ἡμεῖς δὲ ὄντες ἐν τῇ γωνίᾳ τοῦ παραδείσου ἰδόντες τὴν ἀνομίαν ἐδράμομεν ἐπʼ αὐτούς·"}, {"sp": "N", "st": "Sus 1:39", "t": "καὶ ἰδόντες συγγινομένους αὐτούς, ἐκείνου μέν οὐκ ἠδυνήθημεν ἐγκρατεῖς γενέσθαι διὰ τὸ ἰσχύειν αὐτὸν ὑπέρ ἡμᾶς καὶ ἀνοίξαντα τὰς θύρας ἐκπεπηδηκέναι,"}, {"sp": "N", "st": "Sus 1:40", "t": "ταύτης δὲ ἐπιλαβόμενοι ἐπηρωτῶμεν τίς ἦν ὁ νεανίσκος·"}, {"sp": "N", "st": "Sus 1:41", "t": "καὶ οὐκ ἠθέλησεν ἀναγγεῖλαι ἡμῖν. ταῦτα μαρτυροῦμεν. καὶ ἐπίστευσεν αὐτοῖς ἡ συναγωγὴ ὡς πρεσβυτέροις τοῦ λαοῦ καὶ κριταῖς, καὶ κατέκριναν αὐτὴν ἀποθανεῖν."}, {"sp": "N", "st": "Sus 1:42", "t": "ἀνεβόησεν δέ φωνῇ μεγάλῃ Σουσάννα καὶ εἶπεν Ὁ θεὸς ὁ αἰώνιος ὁ τῶν κρυπτῶν γνώστης, ὁ εἰδὼς τὰ πάντα πρὶν γενέσεως αὐτῶν,"}, {"sp": "N", "st": "Sus 1:43", "t": "σὺ ἐπίστασαι ὅτι ψευδῆ μου κατεμαρτύρησαν· καὶ ἰδοὺ ἀποθνήσκω, μὴ ποιήσασα μηδέν ὅν οὗτοι ἐπονηρεύσαντο κατʼ ἐμοῦ."}, {"sp": "N", "st": "Sus 1:44", "t": "Καὶ εἰσήκουσεν Κύριος τῆς φωνῆς αὐτῆς."}, {"sp": "N", "st": "Sus 1:45", "t": "καὶ ἀπαγομένης αὐτῆς ἀπολέσθαι, ἐξήγειρεν ὁ θεὸς τὸ πνεῦμα τὸ ἅγιον παιδαρίου νεωτέρου ᾧ ὄνομα Δανιὴλ."}, {"sp": "N", "st": "Sus 1:46", "t": "καὶ ἐβόησεν φωνῇ μεγάλῃ Ἀθῷος ἐγὼ ἀπὸ τοῦ αἵματος ταύτης."}, {"sp": "N", "st": "Sus 1:47", "t": "ἐπέστρεψεν δὲ πᾶς ὁ λαὸς πρὸς αὐτὸν καὶ εἶπαν Τίς ὁ λόγος οὗτος ὃν σὺ λελάληκας;"}, {"sp": "N", "st": "Sus 1:48", "t": "ὁ δὲ στὰς ἐν μέσῳ αὐτῶν εἶπεν Οὕτως μωροί, οἱ υἱοὶ Ἰσραήλ; οὐκ ἀνακρίναντες οὐδὲ τὸ σαφές ἐπιγνόντες κατεκρίνατε θυγατέρα Ἰσραήλ;"}, {"sp": "N", "st": "Sus 1:49", "t": "ἀναστρέψατε εἰς τὸ κριτήριον· ψευδῆ γὰρ οὖτοι κατεμαρτύρησαν αὐτῆς."}, {"sp": "N", "st": "Sus 1:50", "t": "καὶ ἀνέστρεψεν πᾶς ὁ λαὸς μετὰ σπουδῆς. καὶ εἶπαν αὐτῷ οἱ πρεσβύτεροι Δεῦρο κάθισον ἐν μέσῳ ἡμῶν καὶ ἀνάγγειλον ἡμῖν, ὅτι σοὶ δέδωκεν ὁ θεὸς τὸ πρεσβεῖον."}, {"sp": "N", "st": "Sus 1:51", "t": "καὶ εἶπεν πρὸς αὐτοὺς Δανιὴλ Διαχωρίσατε αὐτοὺς ἀπʼ ἀλλήλων μακράν, καὶ ἀνακρινῶ αὐτούς."}, {"sp": "N", "st": "Sus 1:52", "t": "ὡς δὲ διεχωρίσθησαν εἰς ἀπὸ τοῦ ἑνός, ἐκάλεσεν τὸν ἕνα αὐτῶν καὶ εἶπεν πρὸς αὐτόν Πεπαλαιωμένε ἡμερῶν κακῶν, νῦν ἥκασιν αἱ ἁμαρτίαι σου ἃς ἐποίεις τὸ πρότερον,"}, {"sp": "N", "st": "Sus 1:53", "t": "κρίνων κρίσεις ἀδίκους, καὶ τοὺς μέν ἀθῴους κατακρίνων, ἀπολύων δέ τοὺς αἰτίους, λέγοντος τοῦ κυρίου Ἀθῷον καὶ δίκαιον οὐκ ἀποκτενεῖς."}, {"sp": "N", "st": "Sus 1:54", "t": "νῦν οὗν ταύτην εἴπερ ἴδες, εἰπόν ῾ Υπὸ τί δένδρον ἴδες αὐτοὺς ὁμιλοῦντας ἀλλήλοις; ὁ δὲ εἶπ εν ῾ Υπὸ σχῖνον."}, {"sp": "N", "st": "Sus 1:55", "t": "εἶπεν δὲ Δανιὴλ Ὀρθῶς ἔψευσαι εἰς τὴν σεαυτοῦ κεφαλήν· ἥδη γὰρ ἄγγελος τοῦ θεοῦ λαβὼν φάσιν παρὰ τοῦ θεοῦ σχίσει σε μέσον."}, {"sp": "N", "st": "Sus 1:56", "t": "καὶ μεταστήσας αὐτὸν ἐκέλευσεν προσαγαγεῖν τὸν ἕτερον· καὶ εἶπεν αὐτῷ Σπέρμα Χανάαν καὶ οὐκ Ἰούδα, τὸ κάλλος ἐξηπάτησέν σε, καὶ ἐπιθυμία διέστρεψεν τὴν καρδίαν σου."}, {"sp": "N", "st": "Sus 1:57", "t": "οὕτως ἐποιεῖτε θυγατράσιν Ἰσραήλ, καὶ ἐκεῖναι φοβούμεναι ὡμίλουν ὑμῖν· ἀλλʼ οὐ θυγάτηρ Ἰούδα ὑπέμεινεν τὴν ἀνομίαν ὑμῶν."}, {"sp": "N", "st": "Sus 1:58", "t": "νῦν οὗν λέγε μοι ῾ Υπὸ τί δένδρον κατέλαβες αὐτοὺς ὁμιλοῦντας ἀλλήλοις; ὁ δὲ εἶπεν ῾ Υπὸ πρῖνον."}, {"sp": "N", "st": "Sus 1:59", "t": "εἶπ εν δὲ αὐτῷ Δανιὴλ ᾿Ορθῶς ἔψευσαι καὶ σὺ εἰς τὴν σεαυτοῦ κεφαλήν· μένει γὰρ ὁ ἄγγελος τοῦ θεοῦ τὴν ῥομφαίαν ἔχων πρίσαι σε μέσον, ὅπως ἐξολεθρεύσῃ ὑμᾶς."}, {"sp": "N", "st": "Sus 1:60", "t": "Καὶ ἀνεβόησεν πᾶσα ἡ συναγωγὴ φωνῇ μεγάλῃ, καὶ εὐλόγησαν τῷ θεῷ τῷ σώζοντι τοὺς ἐλπίζοντας ἐπʼ αὐτόν."}, {"sp": "N", "st": "Sus 1:61", "t": "καὶ ἀνέστησαν ἐπὶ τοὺς δύο πρεσβύτας, ὅτι συνέστησεν αὐτοὺς Δανιὴλ ἐκ τοῦ στόματος αὐτῶν ψευδομάρτυρας ὄντας, καὶ ἐποίησαν αὐτοῖς ὃν τρόπον ἐπονηρεύσαντο τῷ πλησίον,"}, {"sp": "N", "st": "Sus 1:62", "t": "ποιῆσαι κατὰ τὸν νόμον Μωυσῆ, καὶ ἀπέκτειναν οὐτούς· καὶ ἐσώθη αἶμα ἀναίτιον ἐν τῇ ἡμέρᾳ ἐκείνῃ."}, {"sp": "N", "st": "Sus 1:63", "t": "Xελκίας δὲ καὶ ἡ γυνὴ αὐτοῦ ἤνεσαν περὶ τῆς θυγατρὸς αὐτῶν μετὰ Ἰωακεὶμ τοῦ ἀνδρὸς αὐτῆς καὶ τῶν συνγενῶν πάντων, ὅτι οὐχ εἰρέθη ἐν αὐτῇ ἄσχημον πρᾶγμα."}, {"sp": "N", "st": "Sus 1:64", "t": "Καὶ Δανιὴλ ἐγένετο μέγας ἐνώπιον τοῦ λαοῦ ἀπὸ τῆς ἡμέρας ἐκείνης καὶ ἐπέκεινα."}, {"sp": "HDR", "t": "ΒΗΛ ΚΑΙ ΔΡΑΚΩΝ"}, {"sp": "N", "st": "Bel 1:1", "t": "ΚAI ὁ βασιλεὺς Ἀστυάγης προσετέθη πρὸς τοὺς πατέρας αὐτοῦ, καὶ παρέλαβεν Κῦρος ὁ Πέρσης τὴν βασιλείαν αὐτοῦ."}, {"sp": "N", "st": "Bel 1:2", "t": "καὶ ἦν Δανιὴλ συνβιωτὴς τοῦ βασιλέως καὶ ἔνδοξος ὑπέρ πάντας τοὺς φίλους αὐτοῦ."}, {"sp": "N", "st": "Bel 1:3", "t": "καὶ ἣν εἴδωλον τοῖς Βαβυλωνίοις ᾦ ὄνομα Βήλ, καὶ ἐδαπανῶντο εἰς αὐτὸν ἑκάστης ἡμέρας σεμιδάλεως ἀρτάβαι δώδεκα καὶ πρόβατα τεσσεράκοντα καὶ οἴνου μετρηταὶ ἕξ."}, {"sp": "N", "st": "Bel 1:4", "t": "καὶ ὁ βασιλεὺς ἐσέβετο αὐτόν, καὶ ἐπορεύετο καθʼ ἑκάστην ἡμέραν προσκυνεῖν αὐτῷ, Δανιὴλ δὲ προσεκύνει τῷ θεῷ αὐτοῦ· καὶ εἶπεν αὐτῷ ὁ βασιλεύς Διὰ τί οὐ προσκυνεῖς τῷ Βήλ;"}, {"sp": "N", "st": "Bel 1:5", "t": "ὁ δὲ εἶπ εν Ὅτι οὐ σέβομαι εἴδωλα χειροποίητα, ἀλλὰ τὸν ζῶντα θεόν, τὸν κτίσαντα τὸν οὐρανὸν καὶ τὴν γῆν καὶ ἔχοντα πάσης σαρκὸς κυρίαν."}, {"sp": "N", "st": "Bel 1:6", "t": "καὶ εἶπεν αὐτῷ ὁ βασιλεύς Οὐ δοκεῖ σοι Βὴλ εἶναι ζῶν θεός; ἡ οὐχ ὁρᾷς ὅσα ἐσθίει καὶ πίνει καθʼ ἑκάστην ἡμέραν ;"}, {"sp": "N", "st": "Bel 1:7", "t": "καὶ εἶπεν Δανιὴλ γελάσας Μὴ πλανῶ, βασιλεῦ· οὗτος γὰρ ἔσωθέν ἐστι πηλός, ἔξωθεν δὲ χαλκός, καὶ οὐ βέβρωκεν οὐδέποτε."}, {"sp": "N", "st": "Bel 1:8", "t": "καὶ θυμωθεὶς ὁ βασιλεὺς ἐκάλεσεν τοὺς ἱερεῖς αὐτοῦ καὶ εἶπεν αὐτοῖς Ἐὰν μὴ εἵπητέ μοι τίς ὁ κατέσθων τὴν δαπάνην ταύτην, ἀποθανεῖσθε·"}, {"sp": "N", "st": "Bel 1:9", "t": "ἐὸν δὲ δείξητε ὅτι Βὴλ κατεσθίει αὐτά, ἀποθανεῖται Δανιὴλ, ὅτι ἐβλασφήμησεν εἰς τὸν Βήλ. καὶ εἶπεν Δανιὴλ τῷ βασιλεῖ Γινέσθω κατὰ τὸ ῥῆμά σου."}, {"sp": "N", "st": "Bel 1:10", "t": "καὶ ἤσαν ἱερεῖς τοῦ Βὴλ ἑβδομήκοντα ἐκτὸς γυναικῶν καὶ τέκνων· καὶ ἦλθεν ὁ βασιλεὺς μετὰ Δανιὴλ εἰς τὸν οἶκον τοῦ Βήλ."}, {"sp": "N", "st": "Bel 1:11", "t": "καὶ εἶπαν οἰ ἱερεῖς τοῦ Βήλ Ἰδοὺ ἡμεῖς ἀποτρέχομεν ἔξω, σὺ δέ, βασιλεῦ, παράθες τὰ βρώματα καὶ τὸν οἶνον κεράσας θές, καὶ ἀπόκλεισον τὴν θύραν καὶ σφράγισον τῷ δακτυλίῳ σου."}, {"sp": "N", "st": "Bel 1:12", "t": "καὶ ἐλθὼν πρωὶ ἐὰν μὴ εὕρῃς πάντα βεβρωμένα ὑπὸ τοῦ Βήλ, ἀποθανούμεθα, ἡ Δανιὴλ ὁ ψευδόμένος καθʼ ἡμῶν."}, {"sp": "N", "st": "Bel 1:13", "t": "αὐτοὶ δὲ κατεφρόνουν, ὅτι πεποιήκεισαν ὑπὸ τὴν τράπεζαν κεκρυμμένην εἴσοδον, καὶ δι᾿ αὐτῆς εἰσεπορεύοντο διόλου καὶ ἀνήλουν αὐτά."}, {"sp": "N", "st": "Bel 1:14", "t": "καὶ ἐγένετο ὡς ἐξήλθοσαν ἐκεῖνοι, καὶ ὁ βασιλεὺς παρέθηκεν τὰ βρώματα τῷ Βήλ· καὶ ἐπέταξεν Δανιὴλ τοῖς παιδαρίοις αὐτοῦ καὶ ἤνεγκαν τέφραν, καὶ κατέσησαν ὅλον τὸν ναὸν ἐνώπιον τοῦ βασιλέως μόνου· καὶ ἐξελθόντες ἔκλεισαν τὴν θὑραν καὶ ἐσφραγίσαντο ἐν τῷ δακτυλίῳ τοῦ βασιλέως, καὶ ἀπῆλθον."}, {"sp": "N", "st": "Bel 1:15", "t": "οἱ δὲ ἱερεῖς ἦλθον τὴν νύκτα κατὰ τὸ ἔθος αὐτῶν καὶ αἱ γυναῖκες καὶ τὰ τέκνα αὐτῶν, καὶ κατέφαγον πάντα καὶ ἐξέπιον."}, {"sp": "N", "st": "Bel 1:16", "t": "καὶ ὤρθρίσεν ὁ βασιλεὺς πρωί, καὶ Δανιὴλ μετʼ αὐτοῦ."}, {"sp": "N", "st": "Bel 1:17", "t": "καὶ εἶπεν Σῷοι αἱ σφραγῖδες, Δανιὴλ; ὁ δὲ εἶπεν Σῷοι, βασιλεῦ."}, {"sp": "N", "st": "Bel 1:18", "t": "καὶ ἐγένετο ἄμα τῷ ἀνοῖξαι τὰς θύρας, ἐπιβλέψας ὁ βασιλεὺς ἐπὶ τὴν τράπεζαν ἐβόησεν φωνῇ μεγάλῃ Μέγας εἶ, Βήλ, καὶ οὐκ ἔστιν παρὰ σοὶ δόλος οὐδὲ εἰς."}, {"sp": "N", "st": "Bel 1:19", "t": "καὶ ἐγέλασεν Δανιὴλ, καὶ ἐκράτησεν τὸν βασιλέα τοῦ μὴ εἰσελθεῖν αὐτὸν ἔσω, καὶ εἶπ εν Ἴδε δὴ τὸ ἔδαφος καὶ γνῶθι τίνος τὰ ἴχνη ταῦτα."}, {"sp": "N", "st": "Bel 1:20", "t": "καὶ εἶπεν ὁ βασιλεύς Ὁρῶ τὰ ἴχνη ἀνδρῶν καὶ γυναικῶν καὶ παιδίων."}, {"sp": "N", "st": "Bel 1:21", "t": "καὶ ὀργισθεὶς ὁ βασιλεὺς τότε συνέλαβεν τοὺς ἱερεῖς καὶ τὰς γυναῖκας καὶ τὰ τέκνα αὐτῶν, καὶ ἔδειξαν αὐτῷ τὰς κρυπτὰς θύρας δι ὅν εἰσεπορεύοντο καὶ ἐδαπάνων τὰ ἐπὶ τῇ τραπέζῃ."}, {"sp": "N", "st": "Bel 1:22", "t": "καὶ ἀπέκτεινεν αὐτοὺς ὁ βασιλεύς, καὶ ἔδωκεν τὸν Βήλ ἔκδοτον τῷ Δανιὴλ· καὶ κατέστρεψεν αὐτὸν καὶ τὸ ἱερὸν αὐτοῦ."}, {"sp": "N", "st": "Bel 1:23", "t": "Καὶ ἦν δράκων μέγας, καὶ ἐσέβοντο αὐτὸν οἱ Βαβυλώνιοι."}, {"sp": "N", "st": "Bel 1:24", "t": "καὶ εἶπεν ὁ βασιλεὺς τῷ Δανιὴλ Οὐ δύνασαι εἰπεῖν ὅτι οὐκ ἔστιν οὗτος θεὸς ζῶν· καὶ προσκύνησον αὐτῷ."}, {"sp": "N", "st": "Bel 1:25", "t": "καὶ εἶπεν Δανιὴλ Κυρίῳ τῷ θεῷ μου προσκυνήσω, ὅτι· οὗτός ἐστιν θεὸς ζῶν·"}, {"sp": "N", "st": "Bel 1:26", "t": "οὺ δέ, βασιλεῦ, δός μοι ἐξουσίαν, καὶ ἀποκτενῶ τὸν δράκοντα ἄνευ μαχαίρας καὶ ῥάβδου. καὶ εἶπεν ὁ βασιλεύς Δίδωμί σοι."}, {"sp": "N", "st": "Bel 1:27", "t": "καὶ ἔλαβεν Δανιὴλ πίσσαν καὶ στῆρ καὶ τρίχας, καὶ ἥψησεν ἐπὶ τὸ αὐτὸ καὶ ἐποίησεν μάζας, καὶ ἔδωκεν εἰς τὸ στόμα τοῦ δράκοντος· καὶ φαγὼν διερράγη ὁ δράκων. καὶ εἶπεν Ἵδετε τὰ σεβάσματα ὑμῶν."}, {"sp": "N", "st": "Bel 1:28", "t": "καὶ ἐγένετο ὡς ἤκουσαν οἱ Βαβυλώνιοι, ἠγανάκτησαν καὶ συνεστράφησαν ἐπὶ τὸν βασιλέα καὶ εἶπαν Ἰουδαῖος γέγονεν ὁ βασιλεύς· τὸν Βὴλ κατέσπασεν καὶ τὸν δράκοντα ἀπέκτεινεν, καὶ τοὺς ἱερεῖς κατέσφαξεν."}, {"sp": "N", "st": "Bel 1:29", "t": "καὶ εἶπαν ἐλθόντες πρὸς τὸν βασιλέα ΙΙαράδος ἡμῖν τὸν Δανιὴλ· εἰ δὲ μή, ἀποκτενοῦμέν σε καὶ τὸν οἶκόν σου."}, {"sp": "N", "st": "Bel 1:30", "t": "καὶ ἴδεν ὁ βασιλεὺς ὅτι ἐπείγουσιν αὐτὸν σφόδρα, καὶ ἀναγκασθεὶς παρέδωκεν αὐτοῖς τὸν Δανιὴλ."}, {"sp": "N", "st": "Bel 1:31", "t": "οἱ δὲ ἔβαλον αὐτὸν εἰς τὸν λάκκον τῶν λεόντων, καὶ ἦν ἐκεῖ ἡμέρας ἔξ."}, {"sp": "N", "st": "Bel 1:32", "t": "ἦσαν δὲ ἐν τῷ λάκκῳ ἑπτὰ λέοντες, καὶ ἐδίδετο αὐτοῖς τὴν ἡμέραν δύο σώματα καὶ δύο πρόβατα· τότε δὲ οὐκ ἐδόθη αὐτοῖς, ἵνα καταφάγωσιν τὸν Δανιὴλ."}, {"sp": "N", "st": "Bel 1:33", "t": "καὶ ἦν Ἁμβακοὺμ ὁ προφήτης ἐν τῇ Ἰουδαίᾳ, καὶ αὐτὸς ἥψησεν ἕψεμα καὶ ἐνέθρυψεν ἄρτους εἰς σκάφην, καὶ ἐπορεύετο εἰς τὸ πεδίον ἀπενέγκαι τοῖς θερισταῖς."}, {"sp": "N", "st": "Bel 1:34", "t": "καὶ εἶπεν ἅγγελος Κυρίου τῷ Ἁμβακούμ Ἀπένεγκε τὸ ἄριστον ὁ ἔχεις εἰς Βαβυλῶνα τῷ Δανιὴλ εἰς τὸν λάκκον τῶν λεόντων."}, {"sp": "N", "st": "Bel 1:35", "t": "καὶ εἶπεν Ἁμβακούμ Κύριε, Βαβυλῶνα οὐχ ἑώρακα, καὶ τὸν λάκκον οὐ γινώσκω."}, {"sp": "N", "st": "Bel 1:36", "t": "καὶ ἐπελάβετο ὁ ἄγγελος Κυρίου τῆς κορυφῆς αὐτοῦ, καὶ βαστάσας τῆς κόμης τῆς κεφαλῆς αὐτοῦ ἔθηκεν αὐτὸν εἰς Βαβυλῶνα ἐπάνω τοῦ λάκκου, ἐν τῷ ῥοίζῳ τοῦ"}, {"sp": "HDR", "t": "ΠΡΟΣΕΥΧΗ ΜΑΝΑΣΣΗ"}, {"sp": "N", "st": "Pr Man", "t": "Προσευχὴ Μαννασσή. Κύριε παντοκράτωρ ἐπουράνιε, ὁ θεὸς τῶν πατέρων ἡμῶν, τοῦ Ἀβραὰμ καὶ Ἰσαὰκ καὶ Ἰακώβ καὶ τοῦ σπέρματος αὐτῶν τοῦ δικαίου· ὁ ποιήσας τὸν οὐρανὸν καὶ τὴν γῆν σὺν παντὶ τῷ κόσμῳ αὐτῶν, ὁ πεδήσας τὴν θάλασσαν τῷ λόγῳ τοῦ προστάγματός σου. ὁ κλείσας τὴν ἄβυσσον καὶ σφραγισάμενος τῷ φοβερῷ καὶ ἐνδόξῳ ὀνόματί σου, ὃν πάντα φρίττει καὶ τρέμει ἀπὸ προσώπου δυνάμεως σου· ὅτι ἄστεκτος ἡ μεγαλοπρεπία τῆς δόξης σου, καὶ ἀνυπόστατος ἡ ὀργὴ τῆς ἐπὶ ἁμαρτωλοὺς ἀπειλῆς σου· ἀμέτρητόν τε καὶ ἀνεξιχνίαστον τὸ ἔλεος τῆς ἐπαγγελίας ὅτι σὺ εἶ Κύριος ὕψιστος, εὔσπλαγχνος, μακρόθυμος, καὶ πολυέλεος, καὶ μετανοῶν ἐπὶ κακίαις ἀνθρώπων. σύ οὗν, Κύριε ὁ θεὸς τῶν δικαίων. οὐκ ἔθου μετάνοιαν δικαίοις, τῷ Ἀβραὰμ καὶ Ἰσαὰκ καὶ Ἰακώβ, τοῖς οὐχ ἡμαρτηκόσιν σοι, ἀλλ᾿ ἔθου μετάνοιαν ἐμοὶ τῷ ἁμαρτωλῷ. διότι ἥμαρτον ὑπέρ ἀριθμὸν ψάμμου θαλάσσης· ὅτι ἐπλήθυναν αἱ ἀνομίαι μου. καὶ οὐκ εἰμὶ ἄξιος ἀτενίσαι καὶ ἰδεῖν τὸ ὕψος τοὶ οὐρανοί ἀπὸ πλήθους τῶν ἀδικιῶν μου· κατικαμπτόμενος πολλῷ δεσμῷ σιδήρου, εἰς τὸ ἀνανεῦσαί με ὑτπὲρ ἁμαρτιίῶν μου, καὶ οὐκ ἔστιν μτοι ἄνεσις· διότι παρώργισα τὸν θυμόν σου, καὶ τὸ πονηρὸν ἐνώπιόν σου ἐποίησα, στήσας βδελύγματα καὶ πληθύνας προσοχθίσματα. καὶ νῦν κλίνω γόνυ καρδίας, δεόμενος τῆς παρὰ σοῦ χρηστότητος· ἡμάρτηκα, Κύριε. ἡμάρτηκα, καὶ τὰς ἀνομίας μου ἐγὼ γινώσκω· αἰτοῦμαι δεόμενός σου, ἄνες μοι, Κύριε, ἄνες μοι, μὴ συναπολέσῃς με ταῖς ἀνομίαις μου, μηδέ εἰς τὸν αἰῶνα μηνίσας τηρήσῃς τὰ κακά μοι, μηδέ καταδικάσῃς με ἐν τοῖς κατωτάτοις τῆς γῆς· ὅτι σὺ εἶ, Κύριε, ὁ θεὸς τῶν μετανοούντων, καὶ ἐν ἐμοὶ δείξῃς τὴν ἀγαθωσύνην σου· ὅτι ἀνάξιον ὄντα σώσεις με κατὰ τὸ πολὺ ἔλεός σου, καὶ αἰνέσω σε διὰ παντὸς ἐν ταῖς ἡμέραις τῆς ζωῆς μου. ὅτι σὲ ὑμνεῖ πᾶσα ἡ δύναμις τῶν οὐρανῶν, καὶ σοῦ ἐστιν ἡ δόξα εἰς τοὺς αἰῶνας. ἀμήν."}, {"sp": "HDR", "t": "ΜΑΚΚΑΒΑΙΩΝ Αʹ"}, {"sp": "N", "st": "1 Macc 1:1", "t": "ΚAI ἐγένετο μετὰ τὸ πατάξαι Ἀλέξανδρον τὸν Φιλίππου τὸν Μακεδόνα, ὃς ἐξῆλθεν ἐκ τῆς γῆς Χεττιείμ, καὶ ἐπάταξεν τὸν Δαρεῖον βασιλέα Περσῶν καὶ Μήδων, καὶ ἐβασίλευσεν ἀντʼ αὐτοῦ πρότερον ἐπὶ τὴν Ἑλλάδα."}, {"sp": "N", "st": "1 Macc 1:2", "t": "καὶ συνεστήσατο πολέμους πολλούς, καὶ ἐκράτησεν ὀχυρωμάτων, καὶ ἔσφαξεν βασιλεῖς,"}, {"sp": "N", "st": "1 Macc 1:3", "t": "καὶ διῆλθεν ἕως ἄκρων τῆς γῆς. καὶ ἔλαβεν σκῦλα πλήθους ἐθνῶν· καὶ ἡσύχασεν ἡ γῆ ἐνώπιον αὐτοῦ, καὶ ὑψώθη, καὶ ἐπήρθη ἡ καρδία αὐτοῦ·"}, {"sp": "N", "st": "1 Macc 1:4", "t": "καὶ συνῆξεν δυνάμιν ἰσχυρὰν σφόδρα, καὶ ἦρξεν χωρῶν καὶ ἐθνῶν καὶ τυραννιῶν, καὶ ἐγένοντο αὐτῷ εἰς φόρον."}, {"sp": "N", "st": "1 Macc 1:5", "t": "καὶ μετὰ ταῦτα ἔπεσεν ἐπὶ τὴν κοίτην, καὶ ἔγνω ὅτι ἀποθνήσκει."}, {"sp": "N", "st": "1 Macc 1:6", "t": "καὶ ἐκάλεσεν τοὺς παῖδας αὐτοῦ τοὺς ἐνδόξους τοὺς συνεκτρόφους αὐτοῦ ἀπὸ νεότητος, καὶ διεῖλεν αὐτοῖς τὴν βασιλείαν αὐτοῦ ἔτι ζῶντος αὐτοῦ."}, {"sp": "N", "st": "1 Macc 1:7", "t": "καὶ ἐβασίλευσεν Ἀλέξανδρος ἔτη δώδεκα, καὶ ἀπέθανεν."}, {"sp": "N", "st": "1 Macc 1:8", "t": "καὶ ἐπεκράτησαν οἱ παῖδες αὐτοῦ, ἕκαστος ἐν τῷ τόπῳ αὐτοῦ·"}, {"sp": "N", "st": "1 Macc 1:9", "t": "καὶ ἐπέθεντο πάντες διαδήματα μετὰ τὸ ἀποθανεῖν αὐτόν, καὶ οἱ υἱοὶ αὐτῶν ὀπίσω αὐτῶν ἔτη πολλά· καὶ ἐπλήθυναν κακὰ ἐν τῇ γῆ."}, {"sp": "N", "st": "1 Macc 1:10", "t": "Καὶ ἐξῆλθεν ἐξ αὐτῶν ῥίζα ἁμαρτωλὸς Ἀντίοχος Ἐπιφανής, υἱὸς Ἀντιόχου τοῦ βασιλέως, ὃς ἦν ὅμηρα ἐν τῆ Ῥώμῃ. καὶ ἐθασίλευσεν ἔτει ἑκατοστῷ καὶ ἑβδόμῳ καὶ τριακοστῷ βασιλείας Ἑλλήνων."}, {"sp": "N", "st": "1 Macc 1:11", "t": "Ἐν ταῖς ἡμέραις ἐκείναις ἐξῆλθεν ἐξ Ἰσραὴλ υἱὸς παράνομος, καὶ ἀνέπεισαν πολλοὺς λέγοντες Πορευθῶμεν καὶ διαθώμεθα διαθήκην μετὰ τῶν ἐθνῶν τῶν κύκλῳ ἡμῶν· ὅτι ἀφʼ ἧς ἐχωρίσθημεν ὑπʼ αὐτῶν, εὗρεν ἡμᾶς κακὰ πολλά."}, {"sp": "N", "st": "1 Macc 1:12", "t": "καὶ ἠγαθύνθη ὁ λόγος ἐν ὀφθαλμοῖς αὐτῶν·"}, {"sp": "N", "st": "1 Macc 1:13", "t": "καὶ προεθυμήθησάν τινες ἀπὸ τοῦ λαοῦ, καὶ ἐπορεύθησαν πρὸς τὸν βασιλέα· καὶ ἔδωκαν αὐτοῖς ἐξουσίαν ποιῆσαι τὰ δικαιώματα τῶν ἐθνῶν."}, {"sp": "N", "st": "1 Macc 1:14", "t": "καὶ ᾠκοδόμησαν γυμνάσιον ἐν Ἰεροσολύμοις κατὰ τὰ νόμιμα τῶν ἐθνῶν."}, {"sp": "N", "st": "1 Macc 1:15", "t": "καὶ ἐποίησαν ἑαυτοῖς ἀκροβυστίαν, καὶ ἀπέστησαν ἀπὸ διαθήκης ἁγίας· καὶ ἐζευγίσθησαν τοῖς ἔθνεσιν, καὶ ἐπράθησαν ποιῆσαι πονῃρόν."}, {"sp": "N", "st": "1 Macc 1:16", "t": "Καὶ ἡτοιμάσθη ἡ βασιλεία ἐνώπιον Ἀντιόχου· καὶ ὑπέλαβεν βασιλεῦσαι γῆς Αἰγύπτου, ὅπως βασιλεύσῃ ἐπὶ τὰς δύο βασιλείας."}, {"sp": "N", "st": "1 Macc 1:17", "t": "καὶ εἰσῆλθεν εἰς Αἴγυπτον ὄχλῳ βαρεῖ, ἐν ἅρμασιν καὶ ἐλέφανσιν καὶ ἐν ἱππεῦσιν καὶ ἐν στόλῳ μεγάλῳ."}, {"sp": "N", "st": "1 Macc 1:18", "t": "καὶ συνεστήσατο πόλεμον πρὸς Πτολεμαῖον τὸν βασιλέα Αἰγύπτου· καὶ ἐνετράπη Πτολεμαῖος ἀπὸ προσώπου αὐτοῦ καὶ ἔφυγεν, καὶ ἔπεσαν τραυματίαι πολλοί."}, {"sp": "N", "st": "1 Macc 1:19", "t": "καὶ κατελάβοντο τὰς πόλεις τὰς ὀχυρὰς ἐν γῇ Αἰγύπτῳ· καὶ ἔλαβεν τὰ σκῦλα γῆς Αἰγύπτου."}, {"sp": "N", "st": "1 Macc 1:20", "t": "Καὶ ἐπέστρεψεν Ἀντίοχος μετὰ τὸ πατάξαι Αἴγυπτον ἐν τῷ ἑκατοστῷ καὶ τεσσερακοστῷ καὶ τρίτῳ ἔτει· καὶ ἀνέβη ἐπὶ Ἰσραὴλ καὶ Ἰεροσόλυμα ἐν ὄχλῳ βαρεῖ"}, {"sp": "N", "st": "1 Macc 1:21", "t": "καὶ εἰσῆλθεν εἰς τὸ ἁγίασμα ἐν ὑπερηφανίᾳ, καὶ ἔλαβεν τὸ θυσιαστήριον τὸ χρυσοῦν, καὶ τὴν λυχνίαν τοῦ φωτὸς καὶ πάντα τὰ σκεύη αὐτῆς,"}, {"sp": "N", "st": "1 Macc 1:22", "t": "καὶ τὴν τράπεζαν τῆς προθέσεως καὶ τὰ σπόνδια καὶ τὰς φιάλας καὶ τὰς θυίσκας τὰς χρυσᾶς καὶ τὸ καταπέτασμα καὶ τοὺς στεφάνους καὶ τὸν κόσμον τὸν χρυσοῦν τὸν κατὰ πρόσωπον τοῦ ναοῦ, καὶ ἐλέπισεν πάντα·"}, {"sp": "N", "st": "1 Macc 1:23", "t": "καὶ ἔλαβεν τὸ ἀργύριον καὶ τὸ χρυσίον, καὶ τὰ σκεύη τὰ ἐπιθυμητά· καὶ ἔλαβεν τοὺς θησαυροὺς τοὺς ἀποκρύφους οὓς εὗρεν."}, {"sp": "N", "st": "1 Macc 1:24", "t": "καὶ λαβὼν πάντα ἀπῆλθεν εἰς τὴν γῆν αὐτοῦ. καὶ ἐποίησαν φονοκτονίαν, καὶ ἐλάλησαν ὑπερηφανίαν μεγάλην."}, {"sp": "N", "st": "1 Macc 1:25", "t": "καὶ ἐγένετο πένθος μέγα ἐπὶ Ἰσραὴλ ἐν παντὶ τόπῳ αὐτῶν· ²⁸καὶ ἐστέναξαν ἄρχοντες καὶ πρεσβύτεροι, παρθένοι καὶ νεανίσκοι ἠσθένησαν, καὶ τὸ κάλλος τῶν γυναικῶν ἠλλοιώθη."}, {"sp": "N", "st": "1 Macc 1:27", "t": "πᾶς νυμφίος ἀνέλαβεν θρῆνον· καθημένη ἐν παστῷ ἐγένετο ἐν πένθει."}, {"sp": "N", "st": "1 Macc 1:28", "t": "καὶ ἐσείσθη ἡ γῆ ἐπὶ τοὺς κατοικοῦντας αὐτήν· καὶ πᾶς ὁ οἶκος Ἰακὼβ ἐνεδύσατο αἰσχύνην."}, {"sp": "N", "st": "1 Macc 1:29", "t": "Μετὰ δύο ἔτη ἡμερῶν ἀπέστειλεν ὁ βασιλεὺς ἄρχοντα φορολογίας εἰς τὰς πόλεις Ἰούδα· καὶ ἦλθεν εἰς Ἰερουσαλὴμ ἐν ὄχλῳ βαρεῖ."}, {"sp": "N", "st": "1 Macc 1:30", "t": "καὶ ἐλάλησεν αὐτοῖς λόγους εἰρηνικοὺς ἐν δόλῳ, καὶ ἐπίστευσαν αὐτῷ, καὶ ἐπέπεσεν ἐπὶ τὴν πόλιν ἐξάπινα, καὶ ἐπάταξεν αὐτὴν πληγὴν μεγάλην, καὶ ἀπώλεσεν λαὸν πολὺν ἐξ Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 1:31", "t": "καὶ ἔλαβεν τὰ σκῦλα τῆς πόλεως καὶ ἐνεπύρισεν αὐτὴν πυρί, καὶ καθεῖλεν τοὺς οἴκους αὐτῆς καὶ τὰ τείχη αὐτῆς κύκλῳ,"}, {"sp": "N", "st": "1 Macc 1:32", "t": "καὶ ᾐχμαλώτευσεν τὰς γυναῖκας καὶ τὰ τέκνα· καὶ τὰ κτήνη ἐκληρονόμησαν."}, {"sp": "N", "st": "1 Macc 1:33", "t": "καὶ ᾠκοδόμησαν τὴν πόλιν Δαυεὶδ τείχει μεγάλῳ καὶ ὀχυρῷ, πύργοις ὀχυροῖς, καὶ ἐγένετο αὐτοῖς εἰς ἄκραν."}, {"sp": "N", "st": "1 Macc 1:34", "t": "καὶ ἔθηκαν ἐκεῖ ἔθνος ἁμαρτωλόν, ἄνδρας παρανόμους· καὶ ἐνίσχυσαν ἐν αὐτῇ."}, {"sp": "N", "st": "1 Macc 1:35", "t": "καὶ παρέθεντο ὅπλα καὶ τροφήν, καὶ συναγαγόντες τὰ σκῦλα Ἰερουσαλὴμ ἀπέθεντο ἐκεῖ καὶ ἐγένετο εἰς μεγάλην παγίδα,"}, {"sp": "N", "st": "1 Macc 1:36", "t": "καὶ ἐγένετο εἰς ἔνεδρον τῷ ἁγιάσματι, καὶ εἰς διάβολον πονηρὸν τῷ Ἰσραὴλ διὰ παντός."}, {"sp": "N", "st": "1 Macc 1:37", "t": "καὶ ἐξέχεαν αἷμα ἀθῷον κύκλῳ τοῦ ἁγιάσματος. καὶ ἐμόλυναν τὸ ἁγίασμα."}, {"sp": "N", "st": "1 Macc 1:38", "t": "καὶ ἔφυγον οἱ κάτοικοι Ἰερουσαλὴμ δι᾿ αὐτούς, καὶ ἐγένετο κατοικία ἀλλοτρίων· καὶ ἐγένετο ἀλλοτρία τοῖς γενήμασιν αὐτῆς, καὶ τὰ τέκνα αὐτῆς ἐγκατέλειπον αὐτήν."}, {"sp": "N", "st": "1 Macc 1:39", "t": "τὸ ἁγίασμα αὐτῆς ἠρημώθη ὡς ἔρημος· αἱ ἑορταὶ αὐτῆς ἐστράφησαν εἰς πένθος, τὰ σάββατα αὐτῆς εἰς ὀνειδισμόν, τιμὴ αὐτῆς εἰς ἐξουθένωσιν,"}, {"sp": "N", "st": "1 Macc 1:40", "t": "κατὰ τὴν δόξαν αὐτῆς ἐπληθύνθη ἀτιμασμὸς αὐτῆς, καὶ τὸ ὕψος αὐτῆς ἐστράφη εἰς πένθος."}, {"sp": "N", "st": "1 Macc 1:41", "t": "Καὶ ἔγραψεν ὁ βασιλεὺς πάσῃ τῇ βασιλείᾳ αὐτοῦ εἶναι πάντας εἰς λαὸν ἕνα,"}, {"sp": "N", "st": "1 Macc 1:42", "t": "καὶ ἐγκαταλείπειν ἕκαστον τὰ νόμιμα αὐτοῦ· καὶ ἐπεδέξαντο πάντα τὰ ἔθνη κατὰ τὸν λόγον τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 1:43", "t": "καὶ πολλοὶ ἀπὸ Ἰσραὴλ ηὐδόκησαν τῇ λατρίᾳ αὐτοῦ, καὶ ἔθυσαν τοῖς εἰδώλοις, καὶ ἐβεβήλωσαν τὸ σάββατον."}, {"sp": "N", "st": "1 Macc 1:44", "t": "καὶ ἀπέστειλεν ὁ βασιλεὺς βιβλία ἐν χειρὶ ἀγγέλων εἰς Ἰερουσαλὴμ καὶ τὰς πόλεις Ἰούδα, πορευθῆναι ὀπίσω νομίμων ἀλλοτρίων τῆς γῆς,"}, {"sp": "N", "st": "1 Macc 1:45", "t": "καὶ κωλῦσαι ὁλοκαυτώματα καὶ θυσίας καὶ σπονδὴν ἐκ τοῦ ἁγιάσματος, καὶ βεβηλῶσαι σάββατα καὶ ἑορτάς,"}, {"sp": "N", "st": "1 Macc 1:46", "t": "καὶ μιᾶναι ἁγίασμα καὶ ἁγίους·"}, {"sp": "N", "st": "1 Macc 1:47", "t": "οἰκοδομῆσαι βωμοὺς καὶ τεμένη καὶ εἴδωλα, καὶ θύειν ὕεια καὶ κτήνη κοινά,"}, {"sp": "N", "st": "1 Macc 1:48", "t": "καὶ ἀφιέναι τοὺς υἱοὺς αὐτῶν ἀπεριτμήτους, βδελύξαι τὰς ψυχὰς αὐτῶν ἐν παντὶ ἀκαθάρτῳ καὶ βεβηλῶσαι."}, {"sp": "N", "st": "1 Macc 1:49", "t": "ὥστε ἐπιλαθέσθαι τοῦ νόμου, καὶ ἀλλάξαι πάντα τὰ δικαιώματα.,"}, {"sp": "N", "st": "1 Macc 1:50", "t": "καὶ ὁς ἂν μὴ ποιήσῃ κατὰ τὸ ῤῆμα τοῦ βασιλέως ἀποθανεῖται."}, {"sp": "N", "st": "1 Macc 1:51", "t": "κατὰ πάντας τοὺς λόγους τούτους ἔγραψεν τῇ βασιλείᾳ αὐτοῦ, καὶ ἐποίησεν ἐπισκόπους ἐπὶ πάντα τὸν λαόν· καὶ ἐνετείλατο ταῖς πόλεσιν Ἰούδα θυσιάζειν κατὰ πόλιν καὶ πόλιν."}, {"sp": "N", "st": "1 Macc 1:52", "t": "καὶ συνηθροίσθησαν ἀπὸ τοῦ λαοῦ πρὸς αὐτοὺς πολλοί, πᾶς ὁ ἐνκαταλείπων τὸν νόμον· καὶ ἐποίησαν κακὰ ἐν τῇ γῇ,"}, {"sp": "N", "st": "1 Macc 1:53", "t": "καὶ ἔθεντο τὸν Ἰσραὴλ ἐν κρυφίοις ἐν παντὶ φυγαδευτηρίῳ αὐτῶν."}, {"sp": "N", "st": "1 Macc 1:54", "t": "Καὶ πεντεκαιδεκάτῃ ἡμέρᾳ Χασελεὺ τῷ πέμπτῳ καὶ τεσσερακοστῷ ἔτει ᾠκοδόμησαν βδέλυγμα ἐρημώσεως ἐπὶ τὸ θυσιαστήριον· καὶ ἐν πόλεσιν Ἰούδα κύκλῳ ᾠκοδόμησαν βωμούς,"}, {"sp": "N", "st": "1 Macc 1:55", "t": "καὶ ἐπὶ τῶν θυρίδων τῶν οἰκιῶν καὶ ἐν ταῖς πλατείαις ἐθυμίων."}, {"sp": "N", "st": "1 Macc 1:56", "t": "καὶ τὰ βιβλία τοῦ νόμου ἃ εὗρον, ἐνεπύρισαν πυρὶ κατασχίσαντες."}, {"sp": "N", "st": "1 Macc 1:57", "t": "καὶ ὅπου εὑρίσκετο παρά τινι βιβλίον διαθήκης, καὶ εἴ τις συνευδόκει τῷ νόμῳ, τὸ σύγκριμα τοῦ βασιλέως ἐθανάτου αὐτόν."}, {"sp": "N", "st": "1 Macc 1:58", "t": "ἐν ἰσχύι αὐτῶν ἐποίουν οὕτω τῷ Ἰσραήλ, τοῖς εὑρισκομένοις ἐν παντὶ μηνὶ καὶ μηνὶ ἐν ταῖς πόλεσιν."}, {"sp": "N", "st": "1 Macc 1:59", "t": "καὶ πέμπτῃ καὶ εἰκάδι τοῦ μηνὸς θυσιάζοντες ἐπὶ τὸν βωμὸν ὃς ἦν ἐπὶ τοῦ θυσιαστηρίου."}, {"sp": "N", "st": "1 Macc 1:60", "t": "καὶ τὰς γυναῖκας τὰς περιτετμηκυίας τὰ τέκνα αὐτῶν ἐθανάτωσαν κατὰ τὸ πρόσταγμα,"}, {"sp": "N", "st": "1 Macc 1:61", "t": "καὶ ἐκρέμασαν τὰ βρέφη ἐκ τῶν τραχήλων αὐτῶν, καὶ τοὺς οἰκείους αὐτῶν, καὶ τοὺς περιτετμηκότας αὐτούς·"}, {"sp": "N", "st": "1 Macc 1:62", "t": "καὶ πολλοὶ ἐν Ἰσραὴλ ἐκρεμάσθησαν. καὶ ὀχυρὠθησαν ἐν αὑτοῖς τοῦ μὴ φαγεῖν κοινά·"}, {"sp": "N", "st": "1 Macc 1:63", "t": "καὶ ἐπεδέξαντο ἀποθανεῖν, ἵνα μὴ μιανθῶσιν τοῖς βρώμασιν, καὶ μὴ βεβηλώσουσιν διαθήκην ἁγίαν· καὶ ἀπέθανον."}, {"sp": "N", "st": "1 Macc 1:64", "t": "καὶ ἐγένετο ἀργὴ μεγάλη ἐπὶ Ἰσραὴλ σφόδρα."}, {"sp": "N", "st": "1 Macc 2:1", "t": "Ἐν ταῖς ἡμέραις ἐκείναις ἀνέστη Ματταθίας Ἰωάννου τοῦ Συμεών, ἱερεὺς τῶν υἱῶν Ἰωαρείμ, ἀπὸ Ἰερουσαλήμ, καὶ ἐκάθισεν ἐν Μωδεείν."}, {"sp": "N", "st": "1 Macc 2:2", "t": "καὶ αὐτῷ υἱοὶ πέντε· Ἰωάννης ὁ ἐπικαλούμενος Γαδδίς,"}, {"sp": "N", "st": "1 Macc 2:3", "t": "Σίμων ὁ καλούμενος Θασσίς,"}, {"sp": "N", "st": "1 Macc 2:4", "t": "Ἰούδας ὁ καλούμενος Μακκαβαῖος,"}, {"sp": "N", "st": "1 Macc 2:5", "t": "Ἐλεαὰρ ὁ καλούμενος Αὑαράν, Ἰωνάθας ὁ καλούμενος Σαφφούς."}, {"sp": "N", "st": "1 Macc 2:6", "t": "Καὶ δεν τὰς βλασφημίας τὰς γινομένας ἐν Ἰούδα καὶ ἐν Ἰερουσαλήμ·"}, {"sp": "N", "st": "1 Macc 2:7", "t": "καὶ εἶπεν Οἴμοι, ἵνα τί τοῦτο ἐγενήθην ἰδεῖν τὰ συντρίμματα τοῦ λαοῦ μου καὶ τὸ σύντριμμα τῆς πόλεως τῆς ἁγίας, καὶ καθίσαι ἐκεῖ ἐν τῷ δοθῆναι αὐτὴν ἐν χειρὶ ἐχθρῶν, τὸ ἁγίασμα ἐν χειρὶ ἀλλοτρίων"}, {"sp": "N", "st": "1 Macc 2:8", "t": "ἐγένετο ὁ ναὸς αὐτῆς ὡς ἀνὴρ ἔνδοξος·"}, {"sp": "N", "st": "1 Macc 2:9", "t": "τὰ σκεύη τῆς δόξης αἰχμάλωτα ἀπήχθη· ἀπεκτάνθη τὰ νήπια αὐτῆς ἐν ταῖς πλατείαις αὐτῆς, οἱ νεανίσκοι αὐτῆς ἐν ῥομφαίᾳ ἐχθροῦ."}, {"sp": "N", "st": "1 Macc 2:10", "t": "ποῖον ἔθνος οὐκ ἐκληρονόμησεν βασίλεια καὶ οὐκ ἐκράτησεν τῶν σκύλων αὐτῆς;"}, {"sp": "N", "st": "1 Macc 2:11", "t": "πᾶς ὁ κόσμος αὐτῆς ἀφῃρέθη· ἀντὶ ἐλευθέρας ἐγενήθη εἰς δούλην."}, {"sp": "N", "st": "1 Macc 2:12", "t": "καὶ ἰδοὺ τὰ ἅγια ἡμῶν καὶ ἡ καλλονὴ ἡμῶν καὶ ἡ δόξα ἡμῶν ἠρημώθη. καὶ ἐβεβήλωσαν αὐτὰ ἔθνη·"}, {"sp": "N", "st": "1 Macc 2:13", "t": "ἵνα τί ἡμῖν ἔτι ζῆν"}, {"sp": "N", "st": "1 Macc 2:14", "t": "καὶ διέρρηξεν Ματταθίας καὶ οἱ υἱοὶ αὐτοῦ τὰ ἱμάτια αὐτῶν, καὶ περιεβάλοντο σάκκους, καὶ ἐπένθησαν σφόδρα."}, {"sp": "N", "st": "1 Macc 2:15", "t": "Καὶ ἦλθον οἱ παρὰ τοῦ βασιλέως οἱ καταναγκάζοντες τὴν ἀποστασίαν εἰς Μωδεεὶν τὴν πόλιν, ἴνα θυσιάσωσιν."}, {"sp": "N", "st": "1 Macc 2:16", "t": "καὶ πολλοὶ ἀπὸ Ἰσραὴλ πρὸς αὐτοὺς προσῆλθαν· καὶ Ματταθίας καὶ οἱ υἱοὶ αὐτοῦ συνήχθησαν."}, {"sp": "N", "st": "1 Macc 2:17", "t": "καὶ ἀπεκρίθησαν οἱ παρὰ τοῦ βασιλέως καὶ εἶπαν τῷ Ματταθίᾳ λέγοντες Ἄρχων καὶ ἔνδοξος καὶ μέγας εἶ ἐν τῇ πόλει ταύτῃ, καὶ ἐστηριγμένος ἐν υἱοῖς καὶ ἀδελφοῖς."}, {"sp": "N", "st": "1 Macc 2:18", "t": "νῦν πρόσελθε πρῶτος, καὶ ποίησον τὸ πρόσταγμα τοῦ βασιλέως, ὡς ἐποίησαν πάντα τὰ ἔθνη, καὶ οἱ ἄρχοντες Ἰούδα, καὶ οἱ καταλειφθέντες ἐν Ἰερουσαλήμ· καὶ ἔσῃ σὺ καὶ ὁ οἵκός σου τῶν φίλων τοῦ βασιλέως· καὶ σὺ καὶ οἱ υἱοί σου δοξασθήσεσθε ἀργυρίῳ καὶ χρυσίῳ καὶ ἀποστολαῖς πολλαῖς."}, {"sp": "N", "st": "1 Macc 2:19", "t": "καὶ ἀπεκρίθη Ματταθίας καὶ εἶπεν φωνῇ μεγάλῃ Εἰ πάντα τὰ ἔθνη τὰ ἐν οἴκῳ τῆς βασιλείας τοῦ βασιλέως ἀκούουσιν αὐτοῦ, ἀποστῆναι ἕκαστος ἀπὸ λατρίας πατέρων αὐτοῦ, καὶ ἡρετίσαντο ἐν ταῖς ἐντολαῖς αὐτοῦ·"}, {"sp": "N", "st": "1 Macc 2:20", "t": "κἀγὼ καὶ οἱ υἱοί μου καὶ οἱ ἀδελφοί μου πορευσώμεθα ἐν διαθήκῃ πατέρων ἡμῶν."}, {"sp": "N", "st": "1 Macc 2:21", "t": "ἵλεως ἡμῖν καταλείπειν νόμον καὶ δικαιώματα."}, {"sp": "N", "st": "1 Macc 2:22", "t": "τὸν νόμον τοῦ βασιλέως οὐκ ἀκουσόμεθα, παρελθεῖν τὴν λατρίαν ἡμῶν δεξιὰν ἡ ἀριστεράν."}, {"sp": "N", "st": "1 Macc 2:23", "t": "Καὶ ὡς ἐπαύσατο λαλῶν τοὺς λόγους τούτους, προσῆλθεν ἀνήρ Ἰουδαῖος ἐν ὀφθαλμοῖς πάντων, θυμιᾶσαι ἐπὶ τοῦ βωμοῦ ἐν Μωδεεὶμ κατὰ τὸ πρόσταγμα τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 2:24", "t": "καὶ ὄιν Ματταθίας καὶ ἐζήλωσεν, καὶ ἐτρόμησαν οἱ νεφροὶ αὐτοῦ, καὶ ἀνήνεγκεν θυμὸν κατὰ τὸ κρίμα, καὶ δραμὼν ἔσφαξεν αὐτὸν ἐπὶ τὸν βωμόν."}, {"sp": "N", "st": "1 Macc 2:25", "t": "καὶ τὸν ἄνδρα τοῦ βασιλέως τὸν ἀναγκάζοντα θύειν ἀπέκτεινεν ἐν τῷ καιρῷ ἐκείνῳ, καὶ τὸν βωμὸν καθεῖλεν,"}, {"sp": "N", "st": "1 Macc 2:26", "t": "καὶ ἐζήλωσεν τῷ νόμῳ, καθὼς ἐποίησεν Φινεὼς τῷ Ζαμβρὶ υἱῷ Σαλώμ."}, {"sp": "N", "st": "1 Macc 2:27", "t": "καὶ ἀνέκραξεν Ματταθίας ἐν τῇ πόλει φωνῇ μεγάλῃ, λέγων Πᾶς ὁ ζηλῶν τῷ νόμῳ καὶ ἱστῶν διαθήκην, ἐξελθέτω ὀπίσω μου."}, {"sp": "N", "st": "1 Macc 2:28", "t": "καὶ ἔφυγον αὐτὸς καὶ οἱ υἱοὶ αὐτοῦ εἰς τὰ ὄρη, καὶ ἐνκατέλειπον ὅσα εἶχον ἐν τῇ πόλει."}, {"sp": "N", "st": "1 Macc 2:29", "t": "Τότε κατέβησαν πολλοὶ ζητοῦντες δικαιοσύνην καὶ κρίμα εἰς τὴν ἔρημον καθίσαι ἐκεῖ,"}, {"sp": "N", "st": "1 Macc 2:30", "t": "αὐτοὶ καὶ οἱ υἱοὶ αὐτῶν καὶ αἱ γυναῖκες αὐτῶν καὶ τὰ κτήνη αὐτῶν· ὅτι ἐσκληρύνθη ἐπʼ αὐτοὺς τὰ κακά."}, {"sp": "N", "st": "1 Macc 2:31", "t": "καὶ ἀνηγγέλη τοῖς ἀνδράσιν τοῦ βασιλέως καὶ ταῖς δυνάμεσιν αἳ ἦσαν ἐν Ἰερουσαλὴμ πόλει Δαυείδ, ὅτι κατέβησαν ἄνδρες, οἵτινες διεσκέδασαν τὴν ἐντολὴν τοῦ βασιλέως, εἰς τοὺς κρυφοὺς ἐν τῇ ἐρήμῳ."}, {"sp": "N", "st": "1 Macc 2:32", "t": "καὶ ἔδραμον ὀπίσω αὐτῶν πολλοί, καὶ καταλαβόντες αὐτοὺς παρενέβαλον ἐπ᾿ αὐτηύς, καὶ συνεστείλαντο πρὸς αὐτοὺς πόλεμον ἐν τῇ ἡμέρᾳ τῶν σαββάτων·"}, {"sp": "N", "st": "1 Macc 2:33", "t": "καὶ εἶπαν πρὸς αὐτοὺς Ἕως τοῦ νῦν· ἐξελθόντες ποιήσατε κατὰ τὸν λόγον τοῦ βασιλέως, καὶ ζήσεοθε."}, {"sp": "N", "st": "1 Macc 2:34", "t": "καὶ εἶπαν Οὐκ ἐξελευσόμεθα, οὐδὲ ποιήσομεν τὸν λόγον τοῦ βασιλέως, βεβηλῶσαι τὴν ἡμέραν τῶν σαββάτων."}, {"sp": "N", "st": "1 Macc 2:35", "t": "καὶ ἐτάχυναν ἐπʼ αὐτοὺς πόλεμον."}, {"sp": "N", "st": "1 Macc 2:36", "t": "καὶ οὐκ ἀπεκρίθησαν αὐτοῖς, οὐδὲ λίθον ἐνετίναξον αὐτοῖς, οὐδὲ ἐνέφραξαν τοὺς κρυφούς,"}, {"sp": "N", "st": "1 Macc 2:37", "t": "λέγοντες Ἀποθάνωμεν οἱ πάντες ἐν τῆ ἁπλότητι ἡμῶν· μαρτυρεῖ ἐφʼ ἡμᾶς ὁ οὐρανὸς καὶ ἡ γῆ ὅτι ἀκρίτως ἀπόλλυτε ἡμᾶς."}, {"sp": "N", "st": "1 Macc 2:38", "t": "καὶ ἀνέστησαν ἐπʼ αὐτοὺς ἐν τῷ πολέμῳ τοῖς σάββασιν· καὶ ἀπέθανον αὐτοὶ καὶ αἱ γυναῖκες αὐτῶν καὶ τὰ τέκνα αὐτῶν καὶ τὰ κτήνη αὐτῶν, ἕως χιλίων ψυχῶν ἀνθράπων."}, {"sp": "N", "st": "1 Macc 2:39", "t": "Καὶ ἔγνω Ματταθίας καὶ οἱ φίλοι αὐτοῦ, καὶ ἐπένθησαν ἐπʼ αὐτοὺς ἕως σφόδρα."}, {"sp": "N", "st": "1 Macc 2:40", "t": "καὶ εἶπεν ἀνὴρ πρὸς τὸν πλησίον αὐτοῦ Ἐὰν πάντες ποιήσωμεν ὡς οἱ ἀδελφοὶ ἡμῶν ἐποίησαν, καὶ μὴ πολεμήσωμεν εἰς τὰ ἔθνη ὑπὲρ τῆς ψυχῆς ἡμῶν καὶ τῶν δικαιωμάτων ἡμῶν, νῦν τάχιον ἡμᾶς ὀλεθρεύσουσιν ἀπὸ τῆς γῆς."}, {"sp": "N", "st": "1 Macc 2:41", "t": "καὶ ἐβουλεύσαντο τῇ ἡμέρᾳ ἐκείνῃ, λέγοντες Πᾶς ἄνθρωπος ὃς ἐὰν ἔλθῃ πρὸς ἡμᾶς εἰς πόλεμον τῇ ἡμέρᾳ τῶν σαββάτων, πολεμήσωμεν κατέναντι αὐτοῦ, καὶ οὐ μὴ ἀποθάνωμεν πάντες καθὼς ἀπέθανον οἱ ἀδελφοὶ ἡμῶν ἐν τοῖς κρυφοῖς."}, {"sp": "N", "st": "1 Macc 2:42", "t": "τότε συνήχθησαν πρὸς αὐτοὺς συναγωγὴ Ἁσιδαίων, ἰσχυρᾷ δυνάμει ἀπὸ Ἰσραήλ, πᾶς ὁ ἑκουσιαζόμενος τῷ νόμῳ."}, {"sp": "N", "st": "1 Macc 2:43", "t": "καὶ πάντες οἱ φυγαδεύοντες ἀπὸ τῶν κακῶν προσετέθησαν αὐτοῖς, καὶ ἐγένοντο αὐτοῖς εἰς στήριγμα."}, {"sp": "N", "st": "1 Macc 2:44", "t": "καὶ συνεστήσαντο δύναμιν, καὶ ἐπάταξαν ἁμαρτωλοὺς ἐν ὀργῇ αὐτῶν, καὶ ἄνδρας ἀνόμους ἐν θυμῷ αὐτῶν· καὶ οἱ λοιποὶ ἔφυγον εἰς τὰ ἔθνη σωθῆναι."}, {"sp": "N", "st": "1 Macc 2:45", "t": "καὶ ἐκύκλωσεν Ματταθίας καὶ οἱ υἱοὶ αὐτοῦ, καὶ καθεῖλον τοὺς βωμοὺς αὐτῶν,"}, {"sp": "N", "st": "1 Macc 2:46", "t": "καὶ περιέτεμον τὰ παιδάρια τὰ ἀπερίτμητα ὅσα εὗρεν ἐν ὁρίοις Ἰσραὴλ ἐν ἰσχύι."}, {"sp": "N", "st": "1 Macc 2:47", "t": "καὶ ἐδίωξαν τοὺς υἱοὺς τῆς ὑπερηφανίας, καὶ κατευοδώθη τὸ ἔργον ἐν χειρὶ αὐτῶν."}, {"sp": "N", "st": "1 Macc 2:48", "t": "καὶ ἀντελάβοντο τοῦ νόμου ἐκ χειρὸς τῶν ἐθνῶν καὶ ἐκ χειρὸς τῶν βασιλέων, καὶ οὐκ ἔδωκαν κέρας τῷ ἁμαρτωλῷ."}, {"sp": "N", "st": "1 Macc 2:49", "t": "Καὶ ἤγγισαν αἱ ἡμέραι τοῦ Ματταθίου ἀποθανεῖν, καὶ εἶπεν τοῖς υἱοῖς αὐτοῦ Νῦν ἐστηρίχθη ὑπερηφανία καὶ ἐλέγμὸς καὶ καιρὸς καταστροφῆς καὶ ὀργὴ θυμοῦ."}, {"sp": "N", "st": "1 Macc 2:50", "t": "καὶ νῦν, τέκνα, ζηλώσατε τῷ νόμῳ, καὶ δότε τὰς ψυχὰς ὑμῶν ὑπὲρ διαθήκης πατέρων ἡμῶν."}, {"sp": "N", "st": "1 Macc 2:51", "t": "μνήσθητε τῶν πατέρων ἡμῶν τὰ ἔργα ἃ ἐποίησαν ταῖς γενεαῖς αὐτῶν, καὶ δέξασθε δόξαν μεγάλην καὶ δόξαν αἰώνιον."}, {"sp": "N", "st": "1 Macc 2:52", "t": "Ἀβραὰμ οὐκ ἐν πειρασμῷ εὑρέθη πιστός, καὶ ἐλογίσθη αὐτῷ δικαιοσύνη;"}, {"sp": "N", "st": "1 Macc 2:53", "t": "Ἰωσὴφ ἐν καιρῷ στενοχωρίας αὐτοῦ ἐφύλαξεν ἐντολήν, καὶ ἐγένετο κύριος Αἰγύπτου."}, {"sp": "N", "st": "1 Macc 2:54", "t": "Φινεὲς ὁ πατὴρ ἡμῶν ἐν τῷ ζηλῶσαι ζῆλον ἔλαβεν διαθήκην ἱερωσύνης ἁγίας."}, {"sp": "N", "st": "1 Macc 2:55", "t": "Ἰησοῦς ἐν τῷ πληρῶσαι λόγον ἐγένετο κριτὴς ἐν Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 2:56", "t": "Χαλὲβ ἐν τῷ ἐπιμαρτύρασθαι τῇ ἐκκλησίᾳ ἔλαβεν γῆν κληρονομίαν."}, {"sp": "N", "st": "1 Macc 2:57", "t": "Δαυεὶδ ἐν τῷ ἐλέει αὐτοῦ ἐκληρονόμησεν θρόνον βασιλείας αἰωνίας."}, {"sp": "N", "st": "1 Macc 2:58", "t": "Ἠλίας ἐν τῷ ζηλῶσαι ζῆλον νόμου ἀνελήμφθη ὡς εἰς τὸν οὐρανόν."}, {"sp": "N", "st": "1 Macc 2:59", "t": "Ἀνανίας, Ἀζαρίας. Μισαήλ, πιστεύσαντες ἐσώθησαν ἐκ φλογός."}, {"sp": "N", "st": "1 Macc 2:60", "t": "Δανιὴλ ἐν τῇ ἁπλότητι αὐτοῦ ἐρύσθη ἐκ στόματος λεόντων."}, {"sp": "N", "st": "1 Macc 2:61", "t": "καὶ οὕτως ἐνυοήθητε κατὰ γενεάν, ὅτι πάντες οἱ ἐλπίζοντες ἐπʼ αὐτὸν οὐκ ἀσθενήσουσιν."}, {"sp": "N", "st": "1 Macc 2:62", "t": "καὶ ἀπὸ λόγων ἀνδρὸς ἁμαρτωλοῦ μὴ φοβηθῆτε, ὅτι ἡ δόξα αὐτοῦ εἰς κόπρια καὶ εἰς σκώληκας."}, {"sp": "N", "st": "1 Macc 2:63", "t": "σήμερον ἐπαρθήσεται, καὶ οὐ μὴ εὑρεθῇ, ὅτι ἐπέστρεψεν εἰς τὸν χοῦν αὐτοῦ, καὶ ὁ διαλογισμὸς αὐτοῦ ἀπώλετο."}, {"sp": "N", "st": "1 Macc 2:64", "t": "καὶ ὑμεῖς, τέκνα, ἰσχύετε καὶ ἀνδρίζεσθε ἐν τῷ νόμῳ ὑμῶν, ὅτι ἐν αὐτῷ δοξασθήσεσθε."}, {"sp": "N", "st": "1 Macc 2:65", "t": "καὶ ἰδοὺ Συμεὼν ὁ ἀδελφὸς ὑμῶν, οἶδα ὅτι ἀνὴρ βουλῆς ἐστιν· αὐτοῦ ἀκούετε πάσας τὰς ἡμέρας, αὐτὸς ὑμῖν ἔσται εἰς πατέρα."}, {"sp": "N", "st": "1 Macc 2:66", "t": "καὶ Ἰούδας ὁ Μακκαβαῖος αὐτός, ἰσχυρὸς ἐν δυνάμει αὐτὸς ἐκ νεότητος αὐτοῦ, οὗτος ὑμῖν ἔσται εἰς ἄρχοντα στρατιᾶς· καὶ πολεμήσετε πόλεμον λαῶν."}, {"sp": "N", "st": "1 Macc 2:67", "t": "καὶ ὑμεῖς προσάξετε πρὸς ὑμᾶς πάντας τοὺς ποιητὰς τοῦ νόμου, καὶ ἐκδικησατε ἐκδίκησιν τοῦ λαοῦ ὑμῶν."}, {"sp": "N", "st": "1 Macc 2:68", "t": "ἀνταποδίδοτε ἀνταπόδομα τοῖς ἔθνεσιν, καὶ προσέχετε εἰς προστάγματα τοῦ νόμου."}, {"sp": "N", "st": "1 Macc 2:69", "t": "Καὶ ηὐλόγησεν αὐτούς· καὶ προσετέθη πρὸς τοὺς πατέρας αὐτοῦ."}, {"sp": "N", "st": "1 Macc 2:70", "t": "καὶ ἀπέθανεν ἐν τῷ ἕκτῳ καὶ τεσσερακοστῷ καὶ ἑκατοστῷ ἔτει· καὶ ἔθαψαν αὐτὸν οἱ υἱοὶ αὐτοῦ ἐν τάφοις πατέρων αὐτοῦ ἐν Μωδεείν, καὶ ἐκόψαντο αὐτὸν πᾶς Ἰσραὴλ κοπετὸν μέγαν."}, {"sp": "N", "st": "1 Macc 3:1", "t": "Καὶ ἀνέστη Ἰούδας ὁ καλούμενος Μακκαβαῖος υἱὸς αὐτοῦ ἀντʼ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 3:2", "t": "καὶ ἐβοήθουν αὐτῷ πάντες οἱ ἀδελφοὶ αὐτοῦ, καὶ πάντες ὅσοι ἐκολλήθησαν τῷ πατρὶ αὐτοῦ, καὶ ἐπολέμουν τὸν πόλεμον Ἰσραὴλ μετʼ εὐφροσύνης."}, {"sp": "N", "st": "1 Macc 3:3", "t": "καὶ ἐπλάτυνεν δόξαν τῷ λαῷ αὐτοῦ· καὶ ἐνεδύσατο θώρακα ὡς γίγας, καὶ συνεζώσατο τὰ σκεύη τὰ πολεμικὰ αὐτοῦ· πολέμους συνεστήσατο, σκεπάζων παρεμβολὴν ἐν ῥομφαίᾳ."}, {"sp": "N", "st": "1 Macc 3:4", "t": "καὶ ὡμοιώθη λέοντι ἐν τοῖς ἔργοις αὐτοῦ, καὶ ὡς σκύμνος ἐρευγόμενος εἰς θήραν."}, {"sp": "N", "st": "1 Macc 3:5", "t": "καὶ ἐδίωξεν ἀνόμους ἐξερευνῶν, καὶ τοὺς ταράσσοντας τὸν λαὸν αὐτοῦ ἐφλόγισεν·"}, {"sp": "N", "st": "1 Macc 3:6", "t": "καὶ συνεστάλησαν οἱ ἄνομοι ἀπὸ τοῦ φόβου αὐτοῦ, καὶ πάντες οἱ ἐργάται τῆς ἀνομίας συνεταράχθησαν, καὶ εὐοδώθη σωτηρία ἐν χειρὶ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 3:7", "t": "καὶ ἐπίκρανεν βασιλεῖς πολλούς, καὶ ηὔφρανεν τὸν Ἰακὼβ ἐν τοῖς ἔργοις αὐτοῦ, καὶ ἕως τοῦ αἰῶνος τὸ μνημόσυνον αὐτοῦ εἰς εὐλογίαν."}, {"sp": "N", "st": "1 Macc 3:8", "t": "καὶ διῆλθεν ἐν πόλεσιν Ἰούδα, καὶ ἐξωλέθρευσεν ἀσεβεῖς ἐπʼ αὐτῆς, καὶ ἀπέστρεψεν ὀργὴν ἀπὸ Ἰσραήλ·"}, {"sp": "N", "st": "1 Macc 3:9", "t": "καὶ ὠνομάσθη ἕως ἐσχάτου τῆς γῆς, καὶ συνήγαγεν ἀπολλυμένους."}, {"sp": "N", "st": "1 Macc 3:10", "t": "Καὶ συνήγαγεν Ἀπολλώνιος ἔθνη, καὶ ἀπὸ Σαμαρίας δύναμιν μεγάλην τοῦ πολεμῆσαι πρὸς Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 3:11", "t": "καὶ ἔγνω Ἰούδας, καὶ ἐξῆλθεν εἰς συνάντησιν αὐτῷ καὶ ἐπάταξεν αὐτὸν καὶ ἀπέκτεινεν· καὶ ἔπεσον τραυματίαι πολλοί, καὶ οἱ ἐπίλοιποι ἔφυγον."}, {"sp": "N", "st": "1 Macc 3:12", "t": "καὶ ἔλαβον τὰ σκεύη αὐτῶν, καὶ τὴν μάχαιραν Ἀπολλωνίου ἔλαβεν Ἰούδας, καὶ ἦν πολεμῶν ἐν αὐτῇ πάσας τὰς ἡμέρας."}, {"sp": "N", "st": "1 Macc 3:13", "t": "Καὶ ἤκουσεν Σήρων, ὁ ἄρχων τῆς δυνάμεως Συρίας, ὅτι ἤθροισεν Ἰούδας ἄθροισμα καὶ ἐκκλησίαν πιστῶν μεθʼ αὑτοῦ καὶ ἐκπορευομένων εἰς πόλεμον."}, {"sp": "N", "st": "1 Macc 3:14", "t": "καὶ εἶπεν Ποιήσω ἐμαυτῷ ὄνομα, καὶ δοξασθήσομαι ἐν τῇ βασιλείᾳ, καὶ πολεμήσω τὸν Ἰούδαν καὶ τοὺς σὺν αὐτῷ καὶ τοὺς ἐξουδενοῦντας τὸν λόγον τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 3:15", "t": "καὶ προσέθετο καὶ ἀνέβη μετʼ αὐτοῦ παρεμβολὴ ἀσεβῶν ἰσχυρὰ βοηθῆσαι αὐτῷ, ποιῆσαι τὴν ἐκδίκησιν ἐν υἱοῖς Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 3:16", "t": "καὶ ἤγγισεν ἕως ἀναβάσεως Μεθωρών· καὶ ἐξῆλθεν Ἰούδας εἰς συνάντησιν αὐτῷ ὀλιγοστός."}, {"sp": "N", "st": "1 Macc 3:17", "t": "ὡς δὲ ἴδαν τὴν παρεμβολὴν ἐρχομένην εἰς συνἀντησιν αὐτῷ, εἶπαν τῷ Ἰούδᾳ Τί δυνησόμεθα ὀλιγοστοὶ ὄντες πολεμῆσαι πρὸς πλῆθος τοσοῦτο; καὶ ἡμεῖς ἐκλελύμεθα ἀσιτοῦντες σήμερον."}, {"sp": "N", "st": "1 Macc 3:18", "t": "καὶ εἶπεν Ἰούδας Εὔκοπόν ἐστιν συνκλεισθῆναι πολλοὺς ἐν χερσὶν ὀλίγων· καὶ οὐκ ἔστιν διαφορὰ ἐναντίον τοῦ οὐρανοῦ σώζειν ἐν πολλοῖς ἢ ἐν ὀλίγοις."}, {"sp": "N", "st": "1 Macc 3:19", "t": "ὅτι οὐκ ἐν πλήθει δυνάμεως νίκη πολέμου ἐστίν, ἀλλ᾿ ἢ ἐκ τοῦ οὐρανοῦ ἰσχύς."}, {"sp": "N", "st": "1 Macc 3:20", "t": "αὐτοὶ ἔρχονται πρὸς ἡμᾶς πλήθει ὕβρεως καὶ ἀνομίας, τοῦ ἐξᾶραι ἡμᾶς καὶ τὰς γυναῖκας ἡμῶν καὶ τὰ τέκνα ἡμῶν, τοῦ σκυλεῦσαι ἡμᾶς."}, {"sp": "N", "st": "1 Macc 3:21", "t": "ἡμεῖς δὲ πολεμοῦμεν περὶ τῶν ψυχῶν ἡμῶν καὶ τῶν νομίμων ἡμῶν."}, {"sp": "N", "st": "1 Macc 3:22", "t": "καὶ αὐτὸς συντρίψει αὐτοὺς πρὸ προσώπου ἡμῶν· ὑμεῖς δέ μὴ φοβηθῆτε ἀπʼ αὐτῶν."}, {"sp": "N", "st": "1 Macc 3:23", "t": "ὡς δὲ ἐπαύσατο λαλῶν, ἐνήλατο ἐπʼ αὐτοὺς ἄφνω, καὶ συνετρίβη Σήρων καὶ ἡ παρεμβολὴ αὐτοῦ ἐνώπιον αὐτοῦ."}, {"sp": "N", "st": "1 Macc 3:24", "t": "καὶ ἐδίωκον αὐτοὺς ἐν τῇ καταβάσει Βαιθωρὼν ἕως τοῦ πεδίου· καὶ ἔπεσον ἀπʼ αὐτῶν εἰς ἄνδρας ὀκτακοσίους· οἱ δὲ λοιποὶ ἔφυγον εἰς γῆν Φυλιστείμ."}, {"sp": "N", "st": "1 Macc 3:25", "t": "καὶ ἤρξατο ὁ φόβος Ἰούδα καὶ τῶν ἀδελφῶν αὐτοῦ, καὶ ἡ πτόη ἔπιπτεν ἐπὶ τὰ ἔθνη τὰ κύκλῳ αὐτῶν."}, {"sp": "N", "st": "1 Macc 3:26", "t": "καὶ ἤγγισεν ἕως τοῦ βασιλέως τὸ ὄνομα αὐτοῦ, καὶ ὑπὲρ τῶν παρατάξεων Ἰούδα ἐξηγεῖτο πᾶν ἔθνος."}, {"sp": "N", "st": "1 Macc 3:27", "t": "Ὡς δὲ ἤκουσεν Ἀντίοχος ὁ βασιλεὺς τοὺς λόγους τούτους, ὠργίσθη θμμῷ· καὶ ἀπέστειλεν καὶ συνήγαγεν τὰς δυνάμεις πάσας τῆς βασιλείας αὐτοῦ, παρεμβολὴν ἰσχυρὰν σφόδρα·"}, {"sp": "N", "st": "1 Macc 3:28", "t": "καὶ ἤνοιξεν τὸ γαζοφυλάκιον αὐτοῦ, καὶ ἔδωκεν ὀψώνια ταῖς δυνάμεσιν αὐτοῦ εἰς τὸν ἐνιαυτόν· καὶ ἐνετείλατο αὐτοῖς εἰς ἐνιαυτὸν εἶναι ἑτοίμους εἰς πᾶσαν χρείαν."}, {"sp": "N", "st": "1 Macc 3:29", "t": "καὶ ἴδεν ὅτι ἐξέλειπεν τὸ ἀργύριον ἀπὸ τῶν θησαυρῶν· καὶ οἱ φόροι τῆς χώρας ὀλίγοι χάριν τῆς διχοστασίας καὶ πληγῆς ἧς κατεσκεύασεν ἐν τῇ γῆ. τοῦ ἆραι τὰ νόμιμα ἃ ἦσαν ἀφ᾿ ἡνερῶν τῶν πρώτων."}, {"sp": "N", "st": "1 Macc 3:30", "t": "καὶ εὐλαβήθὴ μὴ οὐκ ἔχει ὡς ἅπαξ καὶ δὶς εἰς τὰς δαπάνας καὶ τὰ δόματα ἃ ἐδίδου ἔμπροσθεν δα ιλῃ χειρί,"}, {"sp": "N", "st": "1 Macc 3:31", "t": "καὶ ἠπορεῖτο τῇ ψυχῇ αὐτοῦ σφόδρα· καὶ ἐβουλεύσατο τοῦ πορευθῆναι εἰς τὴν Περσίδα, καὶ λαβεῖν τοὺς φόρους τῶν χωρῶν, καὶ συναγαγεῖν ἀργύριον πολύ."}, {"sp": "N", "st": "1 Macc 3:32", "t": "καὶ κατέλειπεν Λυσίαν ἄνθρωπον ἔνδοξον καὶ ἀπὸ γένους τῆς βασιλείας ἐπὶ τῶν πραγμάτων τοῦ βασιλέως, ἀπὸ τοῦ ποταμοῦ Εὐφράτου ἕως τῶν ὁρίων Αἰγύπτου,"}, {"sp": "N", "st": "1 Macc 3:33", "t": "καὶ τρέφειν Ἀντίοχον τὸν υἱὸν αὐτοῦ ἕως τοῦ ἐπιστρέψαι αὐτόν."}, {"sp": "N", "st": "1 Macc 3:34", "t": "καὶ παρέδωκεν αὐτῷ τὰς ἡμίσεις τῶν δυνάμεων καὶ τοὺς ἐλέφαντας, καὶ ἐνετείλατο αὐτῷ περὶ πάντων ὦν ἐβούλετο, καὶ περὶ πάντων τῶν κατοικούντων τὴν Ἰουδαίαν καὶ Ἰερουσαλήμ,"}, {"sp": "N", "st": "1 Macc 3:35", "t": "ἀποστεῖλαι ἐπʼ αὐτοὺς δύναμιν, τοῦ ἐκρίψαι καὶ ἐξᾶραι τὴν ἰσχὺν Ἰσραὴλ καὶ τὸ κατάλιμμα Ἰερουσαλήμ, καὶ ἆραι τὸ μνημόσυνον αὐτοῦ ἀπὸ τοῦ τόπου,"}, {"sp": "N", "st": "1 Macc 3:36", "t": "καὶ κατοικῆσαι υἱοὺς ἀλλοτρίους ἐν πᾶσι τοῖς ὁρίοις αὐτῶν, καὶ κατακληρονομῆσαι τὴν γῆν αὐτῶν."}, {"sp": "N", "st": "1 Macc 3:37", "t": "καὶ ὁ βασιλεὺς παρέλαβεν τὰς ἡμίσεις τῶν δυνάμεων τὰς καταλειφθείσας· καὶ ἀπῆρεν ἀπὸ Ἀντιοχίας, ἀπὸ πόλεως βασιλείας αὐτοῦ, ἔτους ἑβδόμου καὶ τεσσερακοστοῦ καὶ ἑκατοστοῦ· καὶ διεπέρασεν τὸν Εὐφράτην ποταμόν, καὶ διεπορεύετο τὰς ἐπάνω χώρας."}, {"sp": "N", "st": "1 Macc 3:38", "t": "Καὶ ἐπέλεξεν Λυσίας Πτολεμαῖον τὸν Δορυμένους, Νικάνορα καὶ Γοργίαν, ἄνδρας δυνατοὺς τῶν φίλὼν τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 3:39", "t": "καὶ ἀπέστειλεν μετʼ αὐτῶν τεσσεράκοντα χιλιάδας ἀνδρῶν καὶ ἑπτακισχίλιον ἵππον, τοῦ ἐλθεῖν εἰς γῆν Ἰούδα καὶ καταφθεῖραι αὐτὴν κατὰ τὸν λόγον τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 3:40", "t": "καὶ ἀπῆραν σὺν πάσῃ τῇ δυνάμει αὐτῶν καὶ ἦλθον· καὶ παρέβαλον· πλησίον Ἀμμαοὺν ἐν τῇ γῇ τῇ πεδινῇ."}, {"sp": "N", "st": "1 Macc 3:41", "t": "καὶ ἤκουσαν οἱ ἔμποροι τῆς χώρας τὸ ὄνομα αὐτῶν, καὶ ἔλαβον ἀργύριον καὶ χρυσίον πολὺ σφόδρα καὶ παῖδας· καὶ ἦλθον εἰς τὴν παρεμβολὴν τοῦ λαβεῖν τοὺς υἱοὺς Ἰσραὴλ εἰς πταῖδας· καὶ προσεγενήθησαν πρὸς αὐτοὺς δυνάμεις Συρίας καὶ γῆς ἀλλοφύλων."}, {"sp": "N", "st": "1 Macc 3:42", "t": "Καὶ ἴδεν Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ ὅτι ἐπληθύνθη τὰ κακά, καὶ αἱ δυνάμεις παρεμβαλοῦσιν ἐν τοῖς ὁρίοις αὐτῶν· καὶ ἐπέγναωσαν τοὺς λόγους τῆς βασιλείας οὓς ἐνετείλατο ποιῆσαι τῷ λαῷ εἰς ἀπώλειαν καὶ συντέλειαν."}, {"sp": "N", "st": "1 Macc 3:43", "t": "καὶ εἶπαν ἕκαστος πρὸς τὸν πλησίον αὐτοῦ Ἀναστήσωμεν τὴν καθαίρεσιν τοῦ λαοῦ ἡμῶν καὶ τῶν ἁγίων."}, {"sp": "N", "st": "1 Macc 3:44", "t": "καὶ ἡθροίσθησαν ἡ συναγωγὴ τοῦ εἶναι ἐτοίμους εἰς πόλεμον, καὶ τοῦ προσεύξασθαι καὶ αἰτῆσαι ἔλεον καὶ οἰκτειρμούς."}, {"sp": "N", "st": "1 Macc 3:45", "t": "καὶ Ἰερουσαλὴμ ἦν ἀοίκητος ὡς ἔρημος· οὐκ ἦν ὁ εἰσπορευόμενος καὶ ἐκπορευόμενος ἐκ τῶν γενημάτων αὐτῆς· καὶ τὸ ἁγίασμα καταπατούμενον, καὶ υἱοὶ ἀλλογενῶν ἐν τῇ ἄκρᾳ, κατάλυμα ἐν τοῖε ἔθνεσιν· καὶ ἐξήρθη τέρψις ἐξ Ἰακώβ, καὶ ἐξέλειπεν αὐλὸς καὶ κινύρα."}, {"sp": "N", "st": "1 Macc 3:46", "t": "καὶ συνήχθησαν καὶ ἤλθοσαν εἰς Μασσηφὰ κατέναντι Ἰερουσαλήμ, ὅτι τόπος προσευχῆς εἰς Μασσηφὰ τὸ πρότερον τῷ Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 3:47", "t": "καὶ ἐνήστευσαν τῇ ἡμέρᾳ ἐκείνῃ, καὶ περιεβάλλοντο σάκκους καὶ σποδὸν ἐπὶ τὰς κεφαλὰς αὐτῶν, καὶ διέρρηξαν τὰ ἱμάτια αὐτῶν."}, {"sp": "N", "st": "1 Macc 3:48", "t": "καὶ ἐξεπέτασαν τὸ βιβλίον τοῦ νόμου, περὶ ὦν ἐξηρεύνων τὰ ἔθνη τὰ ὁμοιώματὰ τῶν εἰδώλων αὐτῶν."}, {"sp": "N", "st": "1 Macc 3:49", "t": "καὶ ἤνεγκαν τὰ ἱμάτια τῆς ἱερωσύνης καὶ τὰ πρωτογενήματα καὶ τὰς δεκάτας· καὶ ἤγειραν τοὺς Ναζιραίους, οἳ ἐπλήρωσαν τὰς ἡμέρας·"}, {"sp": "N", "st": "1 Macc 3:50", "t": "καὶ ἐβόησαν φωνῇ εἰς τὸν οὐρανὸν λέγοντες Τί ποιήσαρμεν τούτοις, καὶ ποῦ αὐτοὺς ἀπαγάγωμεν ;"}, {"sp": "N", "st": "1 Macc 3:51", "t": "καὶ τὰ ἅγιά σου καταπεπάτηται καὶ βεβήλωται, καὶ οἱ ἱερεῖς σου ἐν πένθει καὶ ταπεινώσει."}, {"sp": "N", "st": "1 Macc 3:52", "t": "καὶ ἰδοὺ τὰ ἔθνη συνῆκται ἐφʼ ἡμᾶς τοῦ ἐξᾶραι ἡμᾶς· σὺ οἶδας ἃ λογίζονται ἐφʼ ἡμᾶς."}, {"sp": "N", "st": "1 Macc 3:53", "t": "πῶς δυνησόμεθα ὑποστῆναι κατὰ πρόσωπον αὐτῶν, ἐὰν μὴ σὺ βοηθήσῃς ἡμῖν ;"}, {"sp": "N", "st": "1 Macc 3:54", "t": "καὶ ἐσάλπισαν ταῖς σάλπιγξιν, καὶ ἐβόησαν φωνῇ μεγάλῃ."}, {"sp": "N", "st": "1 Macc 3:55", "t": "Καὶ μετὰ τοῦτο κατέστησεν Ἰούδας ἡγουμένους τοῦ λαοῦ, χιλιάρχους καὶ ἑκατοντάρχους καὶ πεντηκοντάρχους καὶ δεκαδάρχους."}, {"sp": "N", "st": "1 Macc 3:56", "t": "καὶ εἶπεν τοῖς οἰκοδομοῦσιν οἰκίαν καὶ μνηστευομένοις γυναῖκας καὶ φυτεύουσιν ἀμπελῶνας καὶ δειλοῖς, ἀποστρέφειν ἕκαστον εἰς τὸν οἶκον αὐτοῦ κατὰ τὸν νόμον."}, {"sp": "N", "st": "1 Macc 3:57", "t": "καὶ ἀπῆρεν ἡ παρεμβολή, καὶ παρενεβάλοσαν κατὰ νότου Ἀμμαούμ."}, {"sp": "N", "st": "1 Macc 3:58", "t": "καὶ εἶπεν Ἰούδας Περιζώσασθε, καὶ γενέσθε εἰς υἱοὺς δυνατούς· καὶ γίνεσθε ἕτοιμοι εἰς τὸ πρωὶ τοῦ πολεμῆσαι ἐν τοῖς ἔθνεσιν τούτοις τοῖς ἐπισυνηγμένοις ἐφʼ ἡμᾶς ἐξᾶραι ἡμᾶς καὶ τὰ ἅγια ἡμῶν."}, {"sp": "N", "st": "1 Macc 3:59", "t": "ὅτι κρεῖσσον ἡμᾶς ἀποθανεῖν ἐν πολέμῳ, ἢ ἐφιδεῖν ἐπὶ τὰ κακὰ τοῦ ἔθνους ἡμῶν καὶ τῶν ἁγίων."}, {"sp": "N", "st": "1 Macc 3:60", "t": "ὡς δʼ ἂν ᾖ θέλημα ἐν οὐρανῷ, οὕτως ποιήσει."}, {"sp": "N", "st": "1 Macc 4:1", "t": "Καὶ παρέλαβεν Γοργίας πεντακισχιλίους ἄνδρας καὶ χιλίαν ἵππον ἐκλεκτήν, καὶ ἀπῆρεν ἡ παρεμβολὴ νυκτός,"}, {"sp": "N", "st": "1 Macc 4:2", "t": "ὥστε ἐπιβαλεῖν ἐπὶ τὴν παρεμβολὴν τῶν Ἰουδαίων καὶ πατάξαι αὐτοὺς ἄφνω· καὶ οἱ υἱοὶ τῆς ἄκρας ἦσαν αὐτῷ ὁδηγοί."}, {"sp": "N", "st": "1 Macc 4:3", "t": "καὶ ἤκουσεν Ἰούδας, καὶ ἀπῆρεν αὐτὸς καὶ οἱ δυνατοὶ πατάξαι τὴν δύναμιν τοῦ βασιλέως τὴν ἐν Ἐμμαούμ,"}, {"sp": "N", "st": "1 Macc 4:4", "t": "ἕως ἔτι αἱ δυνάμεις ἐσκορπισμέναι ἦσαν ἀπὸ τῆς παρεμβολῆς."}, {"sp": "N", "st": "1 Macc 4:5", "t": "καὶ ἦλθεν Γοργίας εἰς τὴν παρεμβολὴν Ἰούδα νυκτός, καὶ οὐδένα εὗρεν· καὶ ἐζήει αὐτοὺς ἐν τοῖς ὄρεσιν, ὅτι εἶπεν Φεύγουσιν οὗτοι ἀφʼ ἡμῶν."}, {"sp": "N", "st": "1 Macc 4:6", "t": "καὶ ἄμα ἡμέρᾳ ὤφθη Ἰούδας ἐν τῷ πεδίῳ ἐν τρισχιλίοις ἀνδράσιν· πλὴν καλύμματα καὶ μάχαιραν οὐκ εἶχόν καθὼς ἠββούλοντο. |"}, {"sp": "N", "st": "1 Macc 4:7", "t": "καὶ ἴδον παρεμβολὴν ἐθνῶν ἰσχυρὰν τεθωρακισμένην, καὶ ἵππον κυκλοῦσαν αὐτήν, καὶ οὗτοι διδακτοὶ πολέμου. ⁸καὶ εἶπεν Ἰούδας τοῖς ἀνδράσιν τοῖς μετʼ αὐτοῦ Μὴ φοβεῖσθε τὸ πλῆθος αὐτῶν, καὶ τὸ ὅρμημα αὐτῶν μὴ δειλωθῆτε."}, {"sp": "N", "st": "1 Macc 4:9", "t": "μνήσθητε ὡς ἐσώθησαν οἱ πατέρες ἡμῶν ἐν θαλάσσῃ ἐρυθρᾷ, ὅτε ἐδίωξεν αὐτοὺς Φαραὼ ἐν δυνάμει."}, {"sp": "N", "st": "1 Macc 4:10", "t": "καὶ νῦν βοήσωμεν εἰς οὐρανόν, εἰ θελήσει ἡμᾶς. καὶ μνησθήσεται διαθήκης πατέρων, καὶ συντρίψει τὴν παρεμβολὴν ταύτην κατὰ πρόσωπον ἡμῶν σήμερον."}, {"sp": "N", "st": "1 Macc 4:11", "t": "καὶ γνώσονται πάντα τὰ ἔθνη, ὅτι ἔστιν ὁ λυτρούμενος καὶ σώζων τὸν Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 4:12", "t": "καὶ ἦραν οἱ ἀλλόφυλοι τοὺς ὀφθαλμοὺς αὐτῶν, καὶ ἴδαν αὐτοὺς ἐχομένους ἐξ ἐναντίας,"}, {"sp": "N", "st": "1 Macc 4:13", "t": "καὶ ἐξῆλθαν ἐκ τῆς παρεμβολῆς εἰς πόλεμον, καὶ ἐσάλπισαν οἱ παρὰ Ἰούδου."}, {"sp": "N", "st": "1 Macc 4:14", "t": "καὶ συνῆψαν, καὶ συνετρίβησαν τὰ ἔθνη καὶ ἔφυγον εἰς τὸ πεδίον."}, {"sp": "N", "st": "1 Macc 4:15", "t": "οἱ δὲ ἔσχατοι πάντες ἔπεσαν ἐν ῥομφαίᾳ, καὶ ἐδίωξαν αὐτοὺς ἕως Γασήρων καὶ ἕως τῶν πεδίων τῆς Ἰουδαίας καὶ Ἀζώτου καὶ Ἰαννείας, καὶ ἔπεσαν ἐξ αὐτῶν εἰς ἄνδρας τρισχιλίους."}, {"sp": "N", "st": "1 Macc 4:16", "t": "Καὶ ἐπέστρεψεν Ἰούδας καὶ ἡ δύναμις ἀπὸ τοῦ διώκειν ὄπισθεν αὐτῶν,"}, {"sp": "N", "st": "1 Macc 4:17", "t": "καὶ εἶπεν πρὸς τὸν λαόν Μὴ ἐπιθυμήσητε τῶν σκύλων, ὅτι πόλεμος ἐξ ἐναντίας ἡμῶν,"}, {"sp": "N", "st": "1 Macc 4:18", "t": "καὶ Γοργίας καὶ ἡ δύναμις ἐν τῷ ὄρει ἐγγὺς ἡμῶν· ἀλλὰ στῆτε νῦν ἐναντίον τῶν ἐχθρῶν ἡμῶν καὶ πολεμήσατε αὐτούς, καὶ μετὰ ταῦτα λάβετε σκῦλα καὶ μετὰ παρρησίας."}, {"sp": "N", "st": "1 Macc 4:19", "t": "ἔτι πληροῦντος Ἰούδου ταῦτα, ὤφθη μέρος τι ἐκκύπτον ἐκ τοῦ ὄρους."}, {"sp": "N", "st": "1 Macc 4:20", "t": "καὶ ἴδεν ὅτι τετρόπωται, καὶ ἐνπυρίζουσιν τὴν παρεμβολήν· ὁ γὰρ καπνὸς ὁ θεωρούμενος ἐνεφάνιζε τὸ γεγονός."}, {"sp": "N", "st": "1 Macc 4:21", "t": "οἱ δὲ ταῦτα συνειδότες ἐδειλώθησαν σφόδρα· συνιδόντες δὲ καὶ τὴν Ἰούδα παρεμβολὴν ἐν τῷ πεδίῳ ἑτοίμην εἰς παράταξιν,"}, {"sp": "N", "st": "1 Macc 4:22", "t": "ἔφυγον πάντες εἰς γῆν ἀλλοφύλων."}, {"sp": "N", "st": "1 Macc 4:23", "t": "καὶ Ἰούδας ἀνέστρεψεν ἐπὶ τὴν σκυλίαν τῆς παρεμβολῆς· καὶ ἔλαβεν χρυσίον καὶ ἀργύριον πολὺ καὶ ὑάκινθον καὶ πορφύραν καὶ θαλασσίαν καὶ πλοῦτον μέγαν."}, {"sp": "N", "st": "1 Macc 4:24", "t": "καὶ ἐπιστρέψαντες ὕμνουν καὶ ηὐλόγουν εἰς οὐρανόν Ὅτι καλὸν εἰς τὸν αἰῶνα τὸ ἔλεος αὐτοῦ,"}, {"sp": "N", "st": "1 Macc 4:25", "t": "καὶ ἐγενήθη σωτηρία μεγάλη τῷ Ἰσραὴλ ἐν τῇ ἡμέρᾳ ἐκείνῃ."}, {"sp": "N", "st": "1 Macc 4:26", "t": "Ὅσοι δὲ τῶν ἀλλοφύλων διεσώθησαν, παραγενηθέντες ἀπήγγειλαν τῷ Λυσίᾳ πάντα τὰ συμβεβηκότα."}, {"sp": "N", "st": "1 Macc 4:27", "t": "ὁ δὲ ἀκούσας πάντα συνεχύθη καὶ ἠθύμει, ὅτι οὐχ οἷα ἤθελεν τοιαῦτα γέγονεν τῷ Ἰσραήλ, καὶ οὐχ οἷα ἐνετείλατο αὐτῷ ὁ βασιλεὺς ἐξέβη."}, {"sp": "N", "st": "1 Macc 4:28", "t": "Καὶ ἐν τῷ ἐρχομένῳ ἐνιαυτῷ συνελόχησεν ἀνδρῶν ἐπιλέκτων ἑξήκοντα χιλιάδας καὶ πεντακισχιλίαν ἵππονο, ὥστε ἐκπολεμῆσαι αὐτούς."}, {"sp": "N", "st": "1 Macc 4:29", "t": "καὶ ἦλθον εἰς τὴν Ἰδουμαίαν, καὶ παρενέβαλον ἐν Βεθσούροις, καὶ συνήντησεν αὐτοῖς Ἰούδας ἐν δέκα χιλιάσιν ἀνδρῶν."}, {"sp": "N", "st": "1 Macc 4:30", "t": "καὶ ἴδεν τὴν παρεμβολὴν ἰσχυράν, καὶ προσηύξατο καὶ εἶπεν Εὐλογητὸς εἶ ὁ σωτὴρ Ἰσραήλ, ὁ συντρίψας τὸ ὅρμημα τοῦ δυνατοῦ ἐν χειρὶ τοῦ δούλου σου Δαυείδ, καὶ παρέδωκας τὴν παρεμβολὴν τῶν ἀλλοφύλων εἰς χεῖρας Ἰωνάθου υἱοῦ Σαοὺλ καὶ τοῦ αἴροντος τὰ σκεύη αὐτοῦ."}, {"sp": "N", "st": "1 Macc 4:31", "t": "σύνκλεισον τὴν παρεμβολὴν ταύτην εἰς χεῖρας λαοῦ σου Ἰσραήλ, καὶ αἰσχυνθήτωσαν ἐπὶ τῇ δυνάμει καὶ τῇ ἵππῳ αὐτῶν."}, {"sp": "N", "st": "1 Macc 4:32", "t": "δὸς αὐτοῖς δειλίαν, καὶ τῆξον θράσος ἰσχύος αὐτῶν, καὶ σαλευθήτωσαν τῇ συντριβῇ αὐτῶν."}, {"sp": "N", "st": "1 Macc 4:33", "t": "κατάβαλε αὐτοὺς ῥομφαίᾳ ἀγαπώνταων σε, καὶ αἰνεσάτωσάν σε πάντες οἱ ἰδόντες τὸ ὄνομά σου ἐν ὕμνοις."}, {"sp": "N", "st": "1 Macc 4:34", "t": "καὶ συνέβαλλον ἀλλήλοις, καὶ ἔπεσον ἐκ τῆς παρεμβολῆς Λυσίου εἰς πεντακισχιλίους ἄνδρας, καὶ ἔπεσαν ἐξ ἐναντίας αὐτῶν."}, {"sp": "N", "st": "1 Macc 4:35", "t": "ἰδῲν δὲ Λυσίας τὴν γενομένην τροπὴν τῆς αὐτοῦ συντάξεως, τῆς δὲ Ἰούδα τὸ γεγενημένον θάρσος, καὶ ὡς ἕτοιμοί εἰσιν ἢ ζῆν ἢ τεθνηκέναι γενναίως, ἀπῆρεν εἰς Ἀντιοχίαν· καὶ ἐξενολόγει, καὶ πλεοναστὸν πάλιν γενηθέντα παραγενέσθαι εἰς τὴν Ἰουδαίαν."}, {"sp": "N", "st": "1 Macc 4:36", "t": "Εἶπεν δὲ Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ Ἰδοὺ συνετρίβησαν οἱ ἐχθροὶ ἡμῶν· ἀναβῶμεν καθαρίσαι τὰ ἅγια καὶ ἐνκαινίσαι."}, {"sp": "N", "st": "1 Macc 4:37", "t": "καὶ συνήχθη ἡ παρεμβολὴ πᾶσα, καὶ ἀνέβησαν εἰς ὄρος Σιών."}, {"sp": "N", "st": "1 Macc 4:38", "t": "καὶ ἴδον τὸ ἁγίασμα ἡμῶν ἠρημωμένον, καὶ τὸ θυσιαστήριον βεβηλωμένον, καὶ τὰς πύλας κατακεκαυμένας, καὶ ἐν ταῖς αὐλαῖς φυτὰ πεφυκότα ὡς ἐν δρυμῷ ἢ ὡς ἐν ἑνὶ τῶν ἀρέων, καὶ τὰ παστοφόρια καθῃρημένα."}, {"sp": "N", "st": "1 Macc 4:39", "t": "καὶ διέρρηξαν τὰ ἱμάτια αὐτῶν, καὶ ἐκόψαντο κοπετὸν μέγαν, καὶ ἐπέθεντο σποδὸν ἐπὶ τὴν κεφαλὴν αὐτῶν."}, {"sp": "N", "st": "1 Macc 4:40", "t": "καὶ ἔπεσον ἐπὶ πρόσωπον ἐπὶ τὴν γῆν, καὶ ἐσάλπισαν ταῖς σάλπιγξιν τῶν σημασιῶν, καὶ ἐβόησαν εἰς οὐρανόν."}, {"sp": "N", "st": "1 Macc 4:41", "t": "τότε ἐπέταξεν Ἰούδας ἀνδράσιν πολεμεῖν τοὺς ἐν τῇ ἄκρα, ἕως καθαρίσῃ τὰ ἅγια."}, {"sp": "N", "st": "1 Macc 4:42", "t": "Καὶ ἐπέλεξεν ἱερεῖς ἀμώμους θελητὰς νόμου·"}, {"sp": "N", "st": "1 Macc 4:43", "t": "καὶ ἐκαθάρισαν τὰ ἅγια, καὶ ἦραν τοὺς λίθους τοῦ μιασμοῦ εἰς τόπον ἀκάθαρτον."}, {"sp": "N", "st": "1 Macc 4:44", "t": "καὶ ἐβουλεύσαντο περὶ τοῦ θυσιαστηρίου τῆς ὁλοκαυτώσεως τοῦ βεβηλωμένου, τί αὐτῷ ποιήσωσιν."}, {"sp": "N", "st": "1 Macc 4:45", "t": "καὶ ἔπεσεν αὐτοῖς βουλὴ ἀγαθή, καθελεῖν αὐτό, μή ποτε γένηται αὐτοῖς εἰς ὄνειδος, ὅτι ἐμίαναν τὰ ἔθνη αὐτό· καὶ καθεῖλον τὸ θυσιαστήριον."}, {"sp": "N", "st": "1 Macc 4:46", "t": "καὶ ἀπέθεντο τοὺς λίθους ἐν τῷ ὄρει τοῦ οἰκου ἐν τόπῳ ἐπιτηδείῳ, μέχρι τοῦ παραγενηθῆναι προφήτην τοῦ ἀποκριθῆναι περὶ αὐτῶν."}, {"sp": "N", "st": "1 Macc 4:47", "t": "καὶ ἔλαβον λίθους ὁλοκλήρους κατὰ τὸν νόμον, καὶ ᾠκοδόμησαν θυσιαστήριον καινὸν κατὰ τὸ πρότερον."}, {"sp": "N", "st": "1 Macc 4:48", "t": "καὶ ᾠκοδόμησαν τὰ ἅγιὰ καὶ τὰ ἐντὸς τοῦ οἴκου, καὶ τὰς αὐλὰς ἡγίασεν."}, {"sp": "N", "st": "1 Macc 4:49", "t": "καὶ ἐποίησαν τὰ σκεύη τὰ ἅγια καινά, καὶ εἰσήνεγκαν τὴν λυχνίαν καὶ τὸ θυσιαστήριον τῶν ὁλοκαυτωμάτων καὶ θυμιαμάτων καὶ τὴν τράπεζαν εἰς τὸν ναόν."}, {"sp": "N", "st": "1 Macc 4:50", "t": "καὶ ἐθυμίασαν ἐπὶ τὸ θυσιαστήριον, καὶ ἐξῆψαν τοὺς λύχνους τοὺς ἐπὶ τῆς λυχνίας· καὶ ἐφαίνοσαν ἐν τῷ ναῷ."}, {"sp": "N", "st": "1 Macc 4:51", "t": "καὶ ἐπέθηκαν ἐπὶ τὴν τράπεζαν ἄρτους, καὶ ἐξεπέτασαν τὰ καταπετάσματα· καὶ ἐτέλεσαν πάντα τὰ ἔργα ἃ ἐποίησαν."}, {"sp": "N", "st": "1 Macc 4:52", "t": "Καὶ ὤρθρισαν τὸ πρωὶ τῇ πέμπτῃ καὶ εἰκάδι τοῦ μηνὸς τοῦ ἐνάτου· οὗτος ὁ μὴν Χασελεὺ τοῦ ὀγδόου καὶ τεσσερακοστοῦ καὶ ἑκατοστοῦ ἔτους."}, {"sp": "N", "st": "1 Macc 4:53", "t": "καὶ ἀνήνεγκαν θυσίαν κατὰ τὸν νόμον ἐπὶ τὸ θυήιαγνήριον τῶν ὁλοκαυτωμάτων τὸ καινὸν ὃ ἐποίησαυ·"}, {"sp": "N", "st": "1 Macc 4:54", "t": "κατὰ τὸν καιρὸν κατὰ τὴν ἡμέραν ἐν ᾗ ἐβεβήλωσαν αὐτὸ τὰ ἔθνη, ἐν ἐκείνῃ ἐνεκαινίσθη ἐν ᾠδαῖς καὶ κιθάραις καὶ κινύραις καὶ ἐν κυμβάλοις."}, {"sp": "N", "st": "1 Macc 4:55", "t": "καὶ ἔπεσον πᾶς ὁ λαὸς ἐπὶ πρόσωπον, καὶ προσεκύνησαν καὶ ηὐλόγησαν εἰς οὐρανὸν τὸν εὐοδώσαντα αὐτούς."}, {"sp": "N", "st": "1 Macc 4:56", "t": "καὶ ἐποίησαν τὸν ἐγκαινιασμον τοῦ θυσιαστηρίου ἡμέρας ὀκτώ, καὶ προσήνεγκαν ὁλοκαυτώματα μετʼ εὐφροσύνης, καὶ ἔθυσαν θυσίαν σωτηρίου καὶ αἰνέσεως."}, {"sp": "N", "st": "1 Macc 4:57", "t": "καὶ κατεκόσμησαν τὸ κατὰ πρόσωτπον τοῦ ναοῦ στεφάνοις χρυσοῖς καὶ ἀσπιδίσκαις, καὶ ἐνεκαίνισεν τὰς πύλας καὶ τὰ παστοφόρια, καὶ ἐθύρωσαν αὐτά."}, {"sp": "N", "st": "1 Macc 4:58", "t": "καὶ ἐγενήθη εὐφροσύνη μεγάλη ἐν τῷ λαῷ σφόδρα, καὶ ἀπεστράφη ὄνειδος ἐθνῶν."}, {"sp": "N", "st": "1 Macc 4:59", "t": "καὶ ἔστησεν Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ καὶ πᾶσα ἐκκλησία Ἰσραήλ, ἵνα ἄγωνται ἡμέραι ἐγκαινισμοῦ τοῦ θυσιαστηρίου ἐν τοῖς καιροῖς αὐτῶν ἐνιαυτὸν κατʼ ἐνιαυτὸν ἡμέρας ὀκτώ, ἀπὸ τῆς πέμπτης καὶ εἰκάδος τοῦ μηνὸς Χασελεύ, μετ᾿ εὐφροσύνης καὶ χαρᾶς."}, {"sp": "N", "st": "1 Macc 4:60", "t": "καὶ ᾠκοδόμησαν ἐν τῷ καιρῷ ἐκείνῳ τὸ ὄρος Σιών, κυκλόθεν τείχη ὑψηλὰ καὶ πύργους ἰσχυρούς, μή ποτε παραγενηθέντα τὰ ἔθνη καταπατήσωσιν αὐτά, ὡς ἐποίησαν τὸ πρότερον."}, {"sp": "N", "st": "1 Macc 4:61", "t": "καὶ ἀπέταξαν ἐκεῖ δύναμιν τηρεῖν αὐτό, καὶ ὠχύρωσαν αὐτὸ τηρεῖν τὴν Βεθσουρά, τοῦ ἔχειν τὸν λαὸν ὀχύρωμα κατὰ πρόσωπον τῆς Ἰδουμαίας."}, {"sp": "N", "st": "1 Macc 5:1", "t": "Καὶ ἐγένετο ὅτε ἤκουσαν τὰ ἔθνη κυκλόθεν ὅτι ᾠκοδομήθη τὸ θυσιαστήριον καὶ ἐνεκαινίσθη τὸ ἁγίασμα ὡς τὸ πρότερον, καὶ ὠργίσθη σφόδρα."}, {"sp": "N", "st": "1 Macc 5:2", "t": "καὶ ἐβουλεύσαντο τοῦ ἆραι τὸ γένος Ἰακὼβ τοὺς ὄντας ἐν μέσῳ αὐτῶν, καὶ ἤρξαντο τοῦ θανατοῦν ἐν τῷ λαῷ καὶ ἐξαίρειν."}, {"sp": "N", "st": "1 Macc 5:3", "t": "καὶ ἐπολέμει Ἰούδας πρὸς τοὺς υἱοὺς Ἠσαὺ ἐν τῇ Ἰοδαίᾳ τὴν Ἀκραβαττήνην, ὅτι περιεκάθηντο τὸν Ἰσραήλ· καὶ ἐπάταξεν αὐτοὺς πληγὴν μεγάλην, καὶ συνέστειλεν αὐτούς, καὶ ἔλαβεν τὰ σκῦλα αὐτῶν."}, {"sp": "N", "st": "1 Macc 5:4", "t": "καὶ ἐμνήσθη τῆς κακίας υἱῶν Βαιάν, οἳ ἦσαν τῷ λαῷ εἰς παγίδα καὶ εἰς σκάνδαλον ἐν τῷ ἐνεδρεύειν αὐτοὺς ἐν ταῖς ὁδοῖς."}, {"sp": "N", "st": "1 Macc 5:5", "t": "καὶ διεκλείσθησαν ὑπʼ αὐτοῦ εἰς τοὺς πύργους, καὶ παρέβαλεν ἐπʼ αὐτούς, καὶ ἀνεθεμάτισεν αὐτούς, καὶ ἐνεπύρισεν τοὺς πύργους αὐτῆς ἐν πυρὶ σὺν πᾶσιν τοῖς ἐνοῦσιν."}, {"sp": "N", "st": "1 Macc 5:6", "t": "καὶ διεπέρασεν. ἐπὶ τοὺς υἱοὺς Ἀμμών, καὶ εὗρεν χεῖρα κραταιὰν καὶ λαὸν πολύν, καὶ Τιμόθεον ἡγούμενον αὐτῶν."}, {"sp": "N", "st": "1 Macc 5:7", "t": "καὶ συνῆψεν πρὸς αὐτοὺς πολέμους πολλούς, καὶ συνετρίβησαν πρὸ προσώπου αὐτοῦ, καὶ ἐπάταξεν αὐτοὺς."}, {"sp": "N", "st": "1 Macc 5:8", "t": "καὶ προκατέλαβε τὴν Ἰάζην καὶ τὰς θυγατέρας αὐτῆς, καὶ ἀνέστρεψεν εἰς τὴν Ἰουδαίαν."}, {"sp": "N", "st": "1 Macc 5:9", "t": "Καὶ ἐπισυνήχθησαν τὰ ἔθνη τὰ ἐν τῇ Γαλααδίτιδι ἐπὶ τὸν Ἰσραὴλ τοὺς ὄντας ἐπὶ τοῖς ὁρίοις αὐτῶν τοῦ ἐξᾶραι αὐτούς· καὶ ἔφυγον εἰς Δάθεμα τὸ ὀχύρωμα."}, {"sp": "N", "st": "1 Macc 5:10", "t": "καὶ ἀπέστειλαν γράμματα πρὸς Ἰούδαν καὶ τοὺς ἀδελφοὺς αὐτοῦ, λέγοντες Ἐπισυνηγμένα ἐστὶν ἐφʼ ἡμᾶς τὰ ἔθνη τὰ κύκλῳ ἡμῶν τοῦ ἐξᾶραι ἡμᾶς,"}, {"sp": "N", "st": "1 Macc 5:11", "t": "καὶ ἑτοιμάζοντες ἐλθεῖν καὶ προκαταλαβέσθαι τὸ ὀχύρωμα εἰς ὃ κατεφύγομεν· καὶ Τιμόθεος ἡγεῖται τῆς παρεμβολῆς αὐτῶν."}, {"sp": "N", "st": "1 Macc 5:12", "t": "νῦν οὖν ἐλθὼν ἐξελοῦ ἡμᾶς ἐκ χειρὸς αὐτῶν, ὅτι πέπτωκεν ἐξ ἡμῶν πλῆθος."}, {"sp": "N", "st": "1 Macc 5:13", "t": "καὶ πάντες οἱ ἀδελφοὶ ἡμῶν οἱ ὄντες ἐν τοῖς Τονβίου τεθανάτωνται, καὶ αἰχμαλωτίκασι τὰς γυναῖκας αὐτῶν καὶ τὰ τέκνα αὐτῶν καὶ τὴν ἀποσκευήν, καὶ ἀπώλεσαν ἐκεῖ ὡς μίαν χιλιάδα ἀνδρῶν."}, {"sp": "N", "st": "1 Macc 5:14", "t": "Ἔτι αἱ ἐπιστολαὶ ἀνεγινώσκοντο, καὶ ἰδοὺ ἄγγελοι ἕτεροι παρεγένοντο ἐκ τῆς Γαλιλαίας διερρηχότες τὰ ἱμάτια, ἀπαγγέλλοντες κατὰ τὰ ῥήματα ταῦτα,"}, {"sp": "N", "st": "1 Macc 5:15", "t": "λέγοντες Ἐπισυνήχθη ἐπʼ αὐτοὺς ἐκ Πτολεμαίδος καὶ Τύρου καὶ Σιδῶνος καὶ πᾶσα Γαλιλαίᾳ ἀλλοφύλων, τοῦ ἐξαναλῶσαι ἡμᾶς."}, {"sp": "N", "st": "1 Macc 5:16", "t": "Ὡς δὲ ἤκουσεν Ἰούδας καὶ ὁ λαὸς τοὺς λόγους τούτους, ἐπισυνήχθη ἐκκλησία μεγάλη βουλεύεσθαι τί ποιήσωσιν τοῖς ἀδελφοῖς αὐτῶν τοῖς οὖσιν ἐν θλίψει καὶ πολεμουμένοις ὑπʼ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 5:17", "t": "καὶ εἶπεν Ἰούδας Σίμωνι τῷ ἀδελφῷ αὐτοῦ Ἐπίλεξον σεαυτῷ ἄνδρας. καὶ πορεύου καὶ ῥῦσαι τοὺς ἀδελφούς σου ἐν τῇ Γαλιλαία· ἐγὼ δὲ καὶ Ἰωναθὰν ὁ ἀδελφός μου πορευσόμεθα εἰς τὴν Γαλααδῖτιν."}, {"sp": "N", "st": "1 Macc 5:18", "t": "καὶ κατέλειπεν Ἰώσηφον τὸν τοῦ Ζαχαρίου καὶ Ἀζαρίαν ἡγούμενον τοῦ λαοῦ μετὰ τῶν ἐπιλοίπων τῆς δυνάμεως ἐν τῇ Ἰουδαίᾳ εἰς τήρησιν·"}, {"sp": "N", "st": "1 Macc 5:19", "t": "καὶ ἐνετείλατο αὐτοῖς λέγων ΙΙρόστητε τοῦ λαοῦ τούτου, καὶ μὴ συνάψητε πόλεμον πρὸς τὰ ἔθνη ἕως τοῦ ἐπιστρέψαι ἡμᾶς."}, {"sp": "N", "st": "1 Macc 5:20", "t": "καὶ ἐμερίσθησαν Σίμωνι ἄνδρες τρισχίλιοι τοῦ πορευθῆναι εἰς τὴν Γαλιλαίαν, Ἰούδᾳ δὲ ἄνδρες ὀκτακισχίλιοι εἰς τὴν Γαλααδῖτιν."}, {"sp": "N", "st": "1 Macc 5:21", "t": "Καὶ ἐπορεύθη Σίμων εἰς τὴν Γαλιλαίαν, καὶ συνῆψεν πολέμους πολλοὺς πρὸς τὰ ἔθνη· καὶ συνετρίβη τὰ ἔθνη ἀπὸ προσώπου αὐτοῦ."}, {"sp": "N", "st": "1 Macc 5:22", "t": "καὶ ἐδίωξεν αὐτοὺς ἕως τῶν πόλεων Πτολεμαίδος· καὶ ἔπεσον ἐκ τῶν ἐθνῶν εἰς τρισχιλίους ἄνδρας, καὶ ἔλαβεν τὰ σκῦλα αὐτῶν."}, {"sp": "N", "st": "1 Macc 5:23", "t": "καὶ παρέλαβεν αὐτοὺς ἐκ τῆς Γαλιλαίας καὶ ἐν Ἀρβάκτοις σὺν ταῖς γυναιξὶν καὶ τοῖς τέκνοις, καὶ πάντα ὅσα ἦν αὐτοῖς, καὶ ἤγαγον εἰς τὴν Ἰουδαίαν μετʼ εὐφροσύνης μεγάλης."}, {"sp": "N", "st": "1 Macc 5:24", "t": "Καὶ Ἰούδας ὁ Μακκαβαῖος καὶ Ἰωναθὰν ὁ ἀδελφὸς αὐτοῦ διέβησαν τὸν Ἰορδάνην, καὶ ἐπορεύθησαν ὁδὸν τριῶν ἡμερῶν ἐν τῇ ἐρήμῳ."}, {"sp": "N", "st": "1 Macc 5:25", "t": "καὶ συνήντησαν τοῖς Ναβαταίοις, καὶ ἀπήντησαν αὐτοῖς εἰρηνικῶς, καὶ διηγήσαντο αὐτοῖς ἅπαντα τὰ συμβεβηκότα τοῖς ἀδελφοῖς αὐτῶν ἐν τῇ Γαλααδίτιδι·"}, {"sp": "N", "st": "1 Macc 5:26", "t": "καὶ ὅτι πολλοὶ ἐξ αὐτῶν συνειλημμένοι εἰσὶν εἰς Βοσσορὰ καὶ Βοσσόρ, ἐν Ἀλάμοις, Κασφώρ, Μακέβ, καὶ Καρνέιν· πᾶσαι αἱ πόλεις αὗται ὀχυραὶ καὶ μεγάλαι."}, {"sp": "N", "st": "1 Macc 5:27", "t": "καὶ ἐν ταῖς λοιπαῖς πόλεσιν τῆς Γαλααδίτιδος εἰσὶν συνειλημμένοι· εἰς αὔριον τάσσονται παρεμβαλεῖν ἐπὶ τὰ ὀχυρώματα, καὶ καταλαβέσθαι καὶ ἐξᾶραι πάντας αὐτοὺς ἐν ἡμέρᾳ μιᾷ."}, {"sp": "N", "st": "1 Macc 5:28", "t": "καὶ ἀπέστρεψεν Ἰούδας καὶ ἡ παρεμβολὴ αὐτοῦ ὁδὸν εἰς τὴν ἔρημον εἰς Βοσὸρ ἄφνω· καὶ κατελάβετο τὴν πόλιν, καὶ ἀπέκτεινεν πᾶν ἀρσενικὸν ἐν στόματι ῥομφαίας, καὶ ἔλαβεν πάντα τὰ σκῦλα αὐτῶν, καὶ ἐνέπρησεν αὐτὴν πυρί"}, {"sp": "N", "st": "1 Macc 5:29", "t": "καὶ ἀπῆρεν ἐκεῖθεν νυκτός, καὶ ἐπορεύετο ἕως ἐπὶ τὸ ὀχύρωμα."}, {"sp": "N", "st": "1 Macc 5:30", "t": "καὶ ἐγένετο ἑωθινή, καὶ ἦραν τοὺς ὀφθαλμοὺς αὐτῶν καὶ ἰδοὺ λαὸς πολὺς οὗ οὐκ ἦν ἀριθμός, αἴροντες κλίμακας καὶ μηχανὰς καταλαβέσθαι τὸ ὀχύρωμα· καὶ ἐπολέμουν αὐτούς."}, {"sp": "N", "st": "1 Macc 5:31", "t": "καὶ ἴδεν Ἰούδας ὅτι ἦρκται ὁ πόλεμος, καὶ ἡ κραυγὴ τῆς πόλεως ἀνέβη ἕως οὐρανοῦ σάλπιγξιν καὶ κραυγῇ μεγάλῃ·"}, {"sp": "N", "st": "1 Macc 5:32", "t": "καὶ εἶπεν τοῖς ἀνδράσιν τῆς δυνάμεως Πολεμήσατε σήμερον ὑπὲρ τῶν ἀδελφῶν ἡμῶν."}, {"sp": "N", "st": "1 Macc 5:33", "t": "καὶ ἐξῆλθεν ἐν τρισὶν ἀρχαῖς ἐξόπισθεν αὐτῶν· καὶ ἐσάλπισεν ταῖς σάλπιγξιν, καὶ ἐβόησαν ἐν προσευχῆ."}, {"sp": "N", "st": "1 Macc 5:34", "t": "καὶ ἐπέγνω ἡ παρεμβολὴ Τιμοθέου ὅτι ὁ Μακκαβαός ἐστιν, καὶ ἔφυγον ἀπὸ προσώπου αὐτοῦ, καὶ ἐπάταξεν αὐτοὺς πληγῇ μεγάλῃ· καὶ ἔπεσον ἐξ αὐτῶν ἐν ἐκείνῃ τῇ ἡμέρᾳ εἰς ὀκτακισχιλίους ἄνδρας."}, {"sp": "N", "st": "1 Macc 5:35", "t": "καὶ ἀπέκλινεν εἰς Μααφὰ καὶ ἐπολέμησεν αὐτήν, καὶ κατελάβετο αὐτὴν καὶ ἀπέκτεινεν πᾶν ἀρσενικὸν αὐτῆς, καὶ ἔλαβεν τὰ σκῦλα αὐτῆς, καὶ ἐνέπρησει αὐτὴν ἐν πυρί."}, {"sp": "N", "st": "1 Macc 5:36", "t": "ἐκεῖθεν ἀπῆρεν καὶ προκατελάβετο τὴν Χασφώθ, Μακέδ, Βοσόρ, καὶ τὰς λοιπὰς πόλεις τῆς Γαλααδίτιδος."}, {"sp": "N", "st": "1 Macc 5:37", "t": "δὲ τὰ ῥήματα ταῦτα συνήγαγεν Τιμόθεος παρεμβολὴν ἄλλην, καὶ παρενέβαλεν κατὰ πρόσωπον Ῥαφὼν ἐκ πέραν τοῦ χειμάρρου."}, {"sp": "N", "st": "1 Macc 5:38", "t": "καὶ ἀπέστειλεν Ἰούδας κατασκοπῆσαι τὴν παρεμβολήν· καὶ ἀπήγγειλαν αὐτῷ λέγοντες Ἐπισυνηγμένοι εἰσὶν πρὸς αὐτοὺς πάντα τὰ ἔθνη τὰ κύκλῳ ὑμῶν, δύναμις πολλὴ σφόδρα."}, {"sp": "N", "st": "1 Macc 5:39", "t": "καὶ Ἄραβες μεμίσθωνται εἰς βοήθειαν αὐτοῖς, καὶ παρεμβάλλουσιν πέραν τοῦ χειμάρρου, ἕτοιμοι τοῦ ἐλθεῖν ἐπὶ σέ εἰς πόλεμον. καὶ ἐπορεύθη Ἰούδας εἰς συνάντησιν αὐτῶν."}, {"sp": "N", "st": "1 Macc 5:40", "t": "καὶ εἶπεν Τιμόθεος τοῖς ἄρχουσιν τῆς δυνάμεως αὐτοῦ ἐν τῷ ἐγγίζειν Ἰούδαν καὶ τὴν παρεμβυλὴν αὐτοῦ ἐπὶ τὸν χειμάρρουν τοῦ ὕδατος Ἐὰν διαβῇ πρὸς ἡμᾶς πρότερος, οὐ δυνησόμεθα ὑποστῆναι αὐτόν, ὅτι δυνάμενος δυνήσεται πρὸς ἡμᾶς."}, {"sp": "N", "st": "1 Macc 5:41", "t": "ἐὰν δὲ δειλωθῇ καὶ παρεμβάλῃ πέραν τοῦ ποταμοῦ, διαπεράσομεν πρὸς αὐτόν."}, {"sp": "N", "st": "1 Macc 5:42", "t": "ὡς δὲ ἤγγισεν Ἰούδας ἐπὶ τὸν χειμάρρουν τοῦ ὕδατος, ἔστησεν τοὺς γραμματεῖς τοῦ λαοῦ ἐπὶ τοῦ χειμάρρου, καὶ ἐνετείλατο αὐτοῖς, λέγων Μὴ ἀφῆτε ἄνθρωπον παρεμβαλεῖν, ἀλλὰ ἐρχέσθωσαν πάντες εἰς τὸν πόλεμον."}, {"sp": "N", "st": "1 Macc 5:43", "t": "καὶ διεπέρασεν πρὸς αὐτοὺς πρότερον, καὶ πᾶς ὁ λαὸς αὐτοῦ ἔμπροσθεν αὐτοῦ· καὶ συνετρίβησαν πρὸ προσώπου αὐτοῦ πάντα τὰ ἔθνη, καὶ ἔριψαν πάντα τὰ ὅπλα αὐτῶν, καὶ ἔφυγον εἰς τὸ τέμενος ἐν Καρνάιν."}, {"sp": "N", "st": "1 Macc 5:44", "t": "καὶ προκατελάβοντο τὴν πόλιν, καὶ τὸ τέμενος ἐνεπύρισαν ἐν πυρὶ σὺν πᾶσιν τοῖς οὖσιν ἐν αὐτῷ· καὶ ἐτροπώθη ἡ Καρνάιν, καὶ οὐκ ἐδύνατο ἔτι ὑποστῆναι κατὰ πρόσωπον Ἰούδα."}, {"sp": "N", "st": "1 Macc 5:45", "t": "Καὶ συνήγαγεν Ἰούδας πάντα Ἰσραὴλ τοὺς ἐν τῇ Γαλααδίτιδι ἀπὸ μικροῦ ἕως μεγάλου, καὶ τὰς γυναῖκας αὐτῶν καὶ τὰ τέκνα αὐτῶν καὶ τὴν ἀποσκευὴν, παρεμβολὴν μεγάλην σφόδρα, ἐλθεῖν εἰς γῆν Ἰούδα."}, {"sp": "N", "st": "1 Macc 5:46", "t": "καὶ ἦλθον ἕως Ἐφρών, καὶ αὕτη ἡ πόλις μεγάλη ἡ τῆς εἰσόδου, ἰσχυρὰ σφόδρα· οὐκ ἦν ἐκκλῖναι ἀπʼ αὐτῆς δεξιὰν ἢ ἀριστεράν, ἀλλ᾿ ἢ διὰ μέσου αὐτῆς πορεύεσθαι."}, {"sp": "N", "st": "1 Macc 5:47", "t": "καὶ ἀπέκλεισαν αὐτοὺς οἱ ἐκ τῆς πόλεως, καὶ ἐνέφραξαν τὰς πύλας λίθοις."}, {"sp": "N", "st": "1 Macc 5:48", "t": "καὶ ἀπέστειλεν πρὸς αὐτοὺς Ἰούδας λόγοις εἰρηνικοῖς λέγων Διελεύσομαι εἰς τὴν γῆν σου, τοῦ ἀπελθεῖν εἰς τὴν γῆν ἡμῶν· καὶ οὐδεὶς κακοποιήσει ὑμᾶς, πλὴν τοῖς ποσὶν παρελευσόμεθα. καὶ οὐκ ἠβούλοντο ἀνοῖξαι αὐτῷ."}, {"sp": "N", "st": "1 Macc 5:49", "t": "καὶ ἐπέταξεν Ἰούδας κηρῦξαι ἐν τῇ παρεμβολῇ τοῦ παρεμβαλεῖν ἕκαστον ἐν ᾧ ἐστιν τόπῳ."}, {"sp": "N", "st": "1 Macc 5:50", "t": "καὶ παρενέβαλον οἱ ἄνδρες τῆς πόλεως. καὶ ἐπολέμησαν τὴν πόλιν ὅλην τὴν ἡμέραν ἐκείνην καὶ ὅλην τὴν νύκτα, καὶ παρεδόθη ἡ πόλις ἐν χερσὶν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 5:51", "t": "καὶ ἀπώλεσεν πᾶν ἀρσενικὸν ἐν στόματι ῥομφαίας, καὶ ἐξεφίζωσευ αὐτήν, καὶ ἔλαβεν τὰ σκῦλα τῆς πόλεως, καὶ διῆλθεν διὰ τῆς πόλεως ἐπάνω τῶν ἀπεκταμμένων."}, {"sp": "N", "st": "1 Macc 5:52", "t": "καὶ διέβησαν τὸν Ἰορδάνην εἰς τὸ πεδίον τὸ μέγα κατὰ πρώσωπον Βαιθσάν."}, {"sp": "N", "st": "1 Macc 5:53", "t": "καὶ ἦν Ἰούδας ἐπισυνάγων τοὺς ἐσχατίζοντας καὶ παρακαλῶν τὸν λαὸν κατὰ πᾶσαν τὴν ὁδόν, ἕως ἦλθεν εἰς γῆν Ἰούδα."}, {"sp": "N", "st": "1 Macc 5:54", "t": "καὶ ἀνέβησαν εἰς τὸ ὄρος Σιὼν ἐν εὐφροσύνῃ καὶ χαρᾷ· καὶ προσήγαγον ὁλοκαυτώματα, ὅτι οὐκ ἔπεσεν ἐξ αὐτῶν οὐθεὶς ἕως τοῦ ἐπιστρέψαι ἐν εἰρήνῃ."}, {"sp": "N", "st": "1 Macc 5:55", "t": "Καὶ ἐν ταῖς ἡμέραις αἷς ἦν Ἰούδας καὶ Ἰωναθὰν ἐν τῇ Γαλαάδ, καὶ Σίμων ὁ ἀδελφὸς αὐτοῦ ἐν τῇ Γαλιλαίᾳ κατὰ πρόσωπον Πτολεμαίδος,"}, {"sp": "N", "st": "1 Macc 5:56", "t": "ἤκουσεν Ἰωσὴφ ὁ τοῦ Ζαχαρία καὶ Ζαχαρίας ἄρχοντες τῶν δυνάμεων τῶν ἀνδραγαθέσεων καὶ τοῦ πολέμου οἶα ἐποίησαν·"}, {"sp": "N", "st": "1 Macc 5:57", "t": "καὶ εἶπαν Ποιήσομεν καὶ αὐτοὶ ἑαυτοῖς ὄνομα, καὶ πορευθῶμεν πολεμῆσαι πρὸς τὰ ἔθνη τὰ κύκλῳ ἡμῶν."}, {"sp": "N", "st": "1 Macc 5:58", "t": "καὶ παρήγγειλαν τοῖς ἀπὸ τῆς δυνάμεως τῆς μετʼ αὐτῶν, καὶ ἐπορεύθησαν ἐπὶ Ἰαμνίαν."}, {"sp": "N", "st": "1 Macc 5:59", "t": "καὶ ἐξῆλθεν Γοργίας ἐκ τῆς πόλεως, καὶ οἱ ἄνδρες αὐτοῦ εἰς συνάντησιν αὐτοῖς εἰς πόλεμον."}, {"sp": "N", "st": "1 Macc 5:60", "t": "καὶ ἐτροπώθη Ἰώσηφος καὶ Ἀζαρίας. καὶ ἐδιώχθησαν ἕως τῶν ὁρίων τῆς Ἰουδαίας καὶ ἔπεσον ἐν τῇ ἡμἐρᾳ ἐκείνῃ ἐκ τοῦ λαοῦ τοῦ Ἰσραὴλ εἰς δισχιλίους ἄνδρας·"}, {"sp": "N", "st": "1 Macc 5:61", "t": "καὶ ἐγενήθη τροπὴ μεγάλη ἐν τῷ λαῷ, ὅτι οὐκ ἤκουσαν Ἰούδου καὶ τῶν ἀδελφῶν αὐτοῦ, οἰόμενοι ἀνδραγαθῆσαι αὐτόν."}, {"sp": "N", "st": "1 Macc 5:62", "t": "αὐτοὶ δὲ οὐκ ἦσαν ἐκ τοῦ σπέρματος τῶν ἀνδρῶν ἐκείνων, οἷς ἐδόθη σωτηρία Ἰσραὴλ διὰ χειρὸς αὐτῶν."}, {"sp": "N", "st": "1 Macc 5:63", "t": "καὶ ὁ ἀνήρ Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ ἐδοξάσθησαν σφόδρα ἐναντίον παντὸς Ἰσραὴλ καὶ τῶν ἐθνῶν πάντων, οὗ ἡκούετο τὸ ὄνομα αὐτῶν·"}, {"sp": "N", "st": "1 Macc 5:64", "t": "καὶ ἐπισυνήγοντο πρὸς αὐτοὺς εὐφημοῦντες."}, {"sp": "N", "st": "1 Macc 5:65", "t": "Καὶ ἐξῆλθεν Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ, καὶ ἐπολέμουν τοὺς υἱοὺς Ἠσοὺ ἐν τῇ γῇ τῇ πρὸς νότον, καὶ ἐπάταξεν τὴν Χεβρὼν καὶ τὰς θυγατέρας αὐτῆς· καὶ καθεῖλεν τὸ ὀχύρωμα αὐτῆς, καὶ τοὺς πύργους αὐτῆς ἐνεπύρισεν κυκλόθεν."}, {"sp": "N", "st": "1 Macc 5:66", "t": "καὶ ἀπῆρεν τοῦ πορευθῆναι εἰς γῆν ἀλλοφύλων, καὶ διεπορεύετο τὴν Σαμαρίαν."}, {"sp": "N", "st": "1 Macc 5:67", "t": "ἐν τῇ ἡμέρᾳ ἐκείνῃ ἔπεσαν ἱερεῖς πολέμῳ βουλομένου αὐτοῦ ἀνδραγαθῆσαι, ἐν τῷ αὐτὸν ἐξελθεῖν εἰς τὸν πόλεμον ἀβουλεύτως."}, {"sp": "N", "st": "1 Macc 5:68", "t": "καὶ ἐξέκλινεν Ἰούδας εἰς Ἄζωτον γῆν ἀλλοφύλων, καὶ καθεῖλεν τοὺς βωμοὺς αὐτῶν, καὶ τὰ γλυπτὰ τῶν θεῶν αὐτῶν κοτέκαυσεν, καὶ ἐσκύλευσεν τὰ σκῦλα τῶν πόλεων, καὶ ἐπέστρεψεν εἰς τὴν Ἰουδαίαν."}, {"sp": "N", "st": "1 Macc 6:1", "t": "Καὶ ὁ βασιλεὺς Ἀντίοχος διεπορεύετο τὰς ἐπάνω χώρας, καὶ ἤκουσεν ὅτι ἐστὶν ἐν Ἐλύμοις ἐν τῇ Περσίδι πόλις ἔνδοξος πλούτῳ, ἀργυρίῳ, καὶ χρυσίῳ·"}, {"sp": "N", "st": "1 Macc 6:2", "t": "καὶ τὸ ἱερὸν τὸ ἐν αὐτῇ πλούσιον σφόδρα, καὶ ἐκεῖ καλύμματα χρυσᾶ, καὶ θώρακες καὶ ὅπλα, ἃ κατέλειπεν ἐκεῖ Ἀλέξανδρος ὁ τοῦ Φιλίππου ὁ βασιλεὺς ὁ Μακεδών, ὃς ἐβασίλευσεν τοῖς Ἕλλησι πρῶτος."}, {"sp": "N", "st": "1 Macc 6:3", "t": "καὶ ἦλθεν καὶ ἐζήτει καταλαβεῖν τὴν πόλιν καὶ προνομεῦσαι αὐτήν, καὶ οὐκ ἠδυνάσθη, ὅτι ἐγνώσθη ὁ λόγος τοῖς ἐκ τῆς πόλεως."}, {"sp": "N", "st": "1 Macc 6:4", "t": "καὶ ἀνέστησαν αὐτῷ εἰς πόλεμον, καὶ ἔφυγεν καὶ ἀπῆλθεν ἐκεῖθεν μετὰ λύπης μεγάλης ἀποστρέψαι εἰς Βαβυλῶνα."}, {"sp": "N", "st": "1 Macc 6:5", "t": "καὶ ἦλθεν ἀπαγγέλλων τις αὐτῷ εἰς τὴν Περσίδα, ὅτι τετρόπωνται αἱ παρεμβολαὶ αἱ πορευθεῖσαι εἰς γῆν Ἰούδα·"}, {"sp": "N", "st": "1 Macc 6:6", "t": "καὶ ἐπορεύθη Λυσίας δυνάμει ἰσχυρᾷ ἐν πρώτοις καὶ ἀνετράπη ἀπὸ προσώπου αὐτῶν, καὶ ἐπίσχυσαν ὅπλοις οἷς ἔλαβον ἀπὸ τῶν παρεμβολῶν ὧν ἐξέκοψαν·."}, {"sp": "N", "st": "1 Macc 6:7", "t": "καὶ καθεῖλαν τὸ βδέλυγμα ᾠκοδόμησεν ἐπὶ τὸ θυσιαστήριον τὸ ἐν Ἰερουσαλήμ, καὶ τὸ ἁγίασμ καθὼς τὸ πρότερον ἐκύκλωσαν τείχεσιν ὑψηλοῖς, καὶ τὴν Βεθσουρὰ πόλιν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 6:8", "t": "καὶ ἐγένετο ὡς ἤκουσεν ὁ βασιλεὺς τοὺς λόγους τούτους, ἐθαμβήθη καὶ ἐσαλεύθη σφόδρα· καὶ ἔπεσεν ἐπὶ τὴν κοίτην. καὶ ἐνέπεσεν εἰς ἀρρωστίαν ἀπὸ τῆς λύπης, ὅτι οὐκ ἐγένετο αὐτῷ καθὼς ἐνεθυμεῖτο."}, {"sp": "N", "st": "1 Macc 6:9", "t": "καὶ ἦν ἐκεῖ ἡμέρας πλείους, ὅτι ἀνεκαινίσθη ἐπʼ αὐτὸν λύπη μεγάλη, καὶ ἐλογίσατο ὅτι ἀποθνήσκει."}, {"sp": "N", "st": "1 Macc 6:10", "t": "καὶ ἐκάλεσεν πάντας τοὺς φίλους αὐτοῦ, καὶ εἶπεν πρὸς αὐτοὺς Ἀφίσταται ἀπὸ τῶν ὀφθαλμῶν μου ὁ ὕπνος, καὶ συνπέπτωκα τῇ καρδίᾳ ἀπὸ τῆς μερίμνης."}, {"sp": "N", "st": "1 Macc 6:11", "t": "καὶ εἶπα τῇ καρδίᾳ Ἕως τίνος θλίψεως ἦλθον καὶ κλύδωνος μεγάλου, ἐν ᾧ νῦν εἰμι ; ὅτι χρηστὸς καὶ ἀγαπώμενος ἤμην ἐν τῇ ἐξουσίᾳ μου."}, {"sp": "N", "st": "1 Macc 6:12", "t": "νῦν δέ μνήσκομαι τῶν κακῶν ὧν ἐποίησα ἐν Ἰερουσαλήμ· καὶ ἔλαβον πάντα τὰ σκεύη τὰ ἀργυρᾶ καὶ τὰ χρυσᾶ τὰ ἐν αὐτῇ, καὶ ἐξαπέστειλα τοῦ ἐξᾶραι τοὺς κατοικοῦντας Ἰούδα διὰ κενῆς."}, {"sp": "N", "st": "1 Macc 6:13", "t": "ἔγνων ὅτι χάριν τούτων εὗρόν με τὰ κακὰ ταῦτα καὶ ἰδοὺ ἀπόλλυμαι λύπῃ μεγάλῃ ἐν γῇ ἀλλοτρίᾳ."}, {"sp": "N", "st": "1 Macc 6:14", "t": "καὶ ἐκάλεσεν Φίλιππον ἕνα τῶν φίλων αὐτοῦ, καὶ κατέστησεν αὐτὸν ἐπὶ πάσης τῆς βασιλείας αὐτοῦ."}, {"sp": "N", "st": "1 Macc 6:15", "t": "καὶ ἔδωκεν αὐτῷ τὸ διάδημα καὶ τὴν στολὴν αὐτοῦ καὶ τὸν δακτύλιον, τοῦ ἀγαγεῖν Ἀντίοχον τὸν υἱὸν αὐτοῦ καὶ ἐκθρέψαι αὐτὸν τοῦ βασιλεύειν."}, {"sp": "N", "st": "1 Macc 6:16", "t": "καὶ ἀπέθανεν ἐκεῖ Ἀντίοχος ὁ βασιλεύς, ἔτους ἐνάτου καὶ τεσσερακοστοῦ καὶ ἑκατοστοῦ."}, {"sp": "N", "st": "1 Macc 6:17", "t": "καὶ ἐπέγνω Λυσίας ὅτι τέθνηκεν ὁ βασιλεύς, καὶ κατέστησεν βασιλεύειν Ἀντίοχον τὸν υἱὸν αὐτοῦ ἀντʼ αὐτοῦ ὃν ἐξέθρεψεν νεώτερον, καὶ ἐκάλεσεν τὸ ὄνομα αὐτοῦ, Εὐπάτωρ."}, {"sp": "N", "st": "1 Macc 6:18", "t": "Καὶ οἱ ἐκ τῆς ἄκρας ἦσαν συγκλείοντες τὸν Ἰσραὴλ κύκλῳ τῶν ἁγίων, καὶ ζητοῦντες κακὰ δι᾿ ὅλου καὶ στήρισμα τοῖς ἔθνεσιν."}, {"sp": "N", "st": "1 Macc 6:19", "t": "καὶ ἐλογίσατο Ἰούδας ἐξᾶραι αὐτούς· καὶ ἐξεκκλησίασεν πάντα τὸν λαὸν τοῦ περικαθίσαι ἐπʼ αὐτοὺς"}, {"sp": "N", "st": "1 Macc 6:20", "t": "ἔτους πεντηκοστοῦ καὶ ἑκατοστοῦ· καὶ ἐποίησεν ἐπʼ αὐτοὺς βελοστασίας καὶ μηχανάς."}, {"sp": "N", "st": "1 Macc 6:21", "t": "καὶ ἐξῆλθον ἐξ αὐτοῦ ἐκ τοῦ συνκλεισμοῦ, καὶ ἐκολλήθησαν αὐτοῖς τινὲς τῶν ἀσεβῶν ἐξ Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 6:22", "t": "καὶ ἐπορεύθησαν πρὸς τὸν βασιλέα καὶ εἶπαν Ἕως πότε οὐ ποιήσεις κρίσιν, καὶ ἐκδικήσεις τοὺς ἀδελφοὺς ἡμῶν ;"}, {"sp": "N", "st": "1 Macc 6:23", "t": "ἡμεῖς εὐδοκοῦμεν δουλεύειν τῷ πατρί σου, καὶ πορεύεσθαι τοῖς ὑπʼ αὐτοῦ λεγομένοις, καὶ κατακολουθεῖν τοῖς προστάγμασιν αὐτοῦ·"}, {"sp": "N", "st": "1 Macc 6:24", "t": "ὅτι οἱ τοῦ λαοῦ ἡμῶν χάριν τούτου ἠλλοτριοῦντο ἀφʼ ἡμῶν· πλὴν ὅσοι εὑρίσκοντο ἀφʼ ἡμῶν ἐθανατοῦντο, καὶ αἱ κληρονομίαι ἡμῶν διηρπάζοντο."}, {"sp": "N", "st": "1 Macc 6:25", "t": "καὶ οὐκ ἐφʼ ἡμᾶς μόνον ἐξέτειναν χεῖρα, ἀλλὰ καὶ ἐπὶ πάντα τὰ ὅρια αὐτῶν."}, {"sp": "N", "st": "1 Macc 6:26", "t": "καὶ ἰδοὺ παρεμβεβλήκασι σήμερον ἐπὶ τὴν ἄκραν ἐν Ἰερουσαλήμ, τοῦ καταλαβέσθαι αὐτὴν καὶ τὸ ἁγίασμα, καὶ τὴν Βεθσούραν ὀχύρωσαν."}, {"sp": "N", "st": "1 Macc 6:27", "t": "καὶ ἐὰν μὴ προκαταλάβῃ αὐτοὺς διὰ τάχους, μείζονα τούτων ποιήσουσιν, καὶ οὐ δυνήσει τοῦ κατασχεῖν αὐτῶν."}, {"sp": "N", "st": "1 Macc 6:28", "t": "Καὶ ὠργίσθη ὁ βασιλεύς, ὅτε ἤκουσεν· καὶ συνήγαγεν πάντας τοὺς φίλους αὐτοῦ, ἄρχοντας δυνάμεως αὐτοῦ, καὶ τοὺς ἐπὶ τῶν ἡνιῶν·"}, {"sp": "N", "st": "1 Macc 6:29", "t": "καὶ ἀπὸ βασιλέων ἑτέρων καὶ ἀπὸ νήσων θαλασσῶν ἦλθον πρὸς αὐτὸν δυνάμεις μισθωταί."}, {"sp": "N", "st": "1 Macc 6:30", "t": "καὶ ἦν ὁ ἀριθμὸς τῶν δυνάμεων αὐτοῦ ἑκατὸν χιλιάδες πεζῶν, καὶ εἴκοσι χιλιάδες τῶν ἵππων, καὶ ἐλέφαντες δύο καὶ τριάκοντα εἰδότες πόλεμον."}, {"sp": "N", "st": "1 Macc 6:31", "t": "καὶ ἤλθοσᾳν διὰ τῆς Ἰδουμαίας, καὶ παρενεβάλοσαν ἐπὶ Βεθσουρά, καὶ ἐπολέμησαν ἐπὶ ἡμέρας πολλάς, καὶ ἐποίησαν μηχανάς· καὶ ἐξῆλθαν καὶ ἐνεπύρισαν αὐτοὺς ἐν πυρί, καὶ ἐπολέμησαν ἀνδρωδῶς."}, {"sp": "N", "st": "1 Macc 6:32", "t": "καὶ ἀπῆρεν Ἰούδας ἀπὸ τῆς ἄκρας. καὶ παρενέβαλεν εἰς Βεθζαχαριά, ἀπέναντι τῆς παρεμβολῆς τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 6:33", "t": "καὶ ὤρθρισεν ὁ βασιλεὺς τὸ πρωί, καὶ ἀπῆρεν τὴν παρεμβολὴν ἐν ὁρμήματι αὐτῆς κατὰ τὴν ὁδὸν Βεθζαχαριά, καὶ διεσκευάσθησαν αἱ δυνάμεις εἰς τὸν πόλεμον, καὶ ἐσάλπισαν ταῖς σάλπιγξιν."}, {"sp": "N", "st": "1 Macc 6:34", "t": "καὶ τοῖς ἐλέφανσιν ἔδειξαν αἷμα σταφυλῆς καὶ μόρων, τοῦ παραστῆσαι αὐτοὺς εἰς τὸν πόλεμον."}, {"sp": "N", "st": "1 Macc 6:35", "t": "καὶ διεῖλον τὰ θηρία εἰς τὰς φάραγγας. καὶ παρέστησαν ἐφʼ ἑκάστῳ ἐλέφαντι χιλίους ἄνδρας τεθωρακισμένους ἐν ἁλυσιδαωτοῖς, καὶ περικεφαλαῖαι χαλκαῖ ἐπὶ τῶν κεφαλῶν αὐτῶν, καὶ πεντακοσία ἵππος διατεταγμένη ἑκάστῳ θηρίῳ ἐκλελεγμένη."}, {"sp": "N", "st": "1 Macc 6:36", "t": "οὗτοι πρὸ καιροῦ, οὗ ἂν ᾖ τὸ θηρίον, ἦσαν· καὶ οὗ ἂν ἐπορεύετο, ἐπορεύοντο ἅμα, οὐκ ἀφίσταντο ἐπʼ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 6:37", "t": "καὶ πύργοι ξύλινοι ἐπʼ αὐτοὺς ὀχυροὶ σκεπαζόμενοι, ἐφʼ ἑκάστου θηρίου, ἐζωσμένοι ἐπʼ αὐτοὺς μηχαναῖς· καὶ ἐφʼ ἑκάστου ἄνδρες δύο καὶ τριάκοντα οἱ πολεμοῦντες ἐπʼ αὐτούς, καὶ ὁ Ἰνδὸς αὐτοῦ."}, {"sp": "N", "st": "1 Macc 6:38", "t": "καὶ τὴν ἐπίλοιπον ἵππον ἔνθεν καὶ ἔνθεν ἔστησεν ἐπὶ τὰ δύο μέρη τῆς παρεμβολῆς, κατασείοντες καὶ καταφρασσόμενοι ἐν ταῖς φάλαγξιν."}, {"sp": "N", "st": "1 Macc 6:39", "t": "ὡς δὲ ἔστιλβεν ὁ ἥλιος ἐπὶ τὰς χρυσᾶς ἀσπίδας, ἔστιλβεν τὰ ὄρη ἀπʼ αὐτῶν, καὶ κατηύγαζεν ὡς λαμπάδες πυρός."}, {"sp": "N", "st": "1 Macc 6:40", "t": "καὶ ἐξετάθη μέρος τι τῆς παρεμβολῆς τοῦ βασιλέως ἐπὶ τὰ ὑψηλὰ ὄρη, καί τινες ἐπὶ τὰ ταπεινά· καὶ ἤρχοντο ἀσφαλῶς καὶ τεταγμένως."}, {"sp": "N", "st": "1 Macc 6:41", "t": "καὶ ἐσαλεύοντο πάντες οἱ ἀκούοντες φωνῆς πλήθους αὐτῶν καὶ ὁδοιπσορίας τοῦ πλήθους καὶ συνκρουσμοὺς τῶν ὅπλων· ἦν γὰρ ἡ παρεμβολὴ μεγάλη σφόδρα καὶ ἰσχυρά."}, {"sp": "N", "st": "1 Macc 6:42", "t": "καὶ ἤγγισεν Ἰούδας καὶ ἡ παρεμβολὴ αὐτοῦ εἰς παράταξιν, καὶ ἔπεσαν ἀπὸ τῆς παρεμβολῆς τοῦ βασιλέως ἑξακόσιοι ἄνδρες."}, {"sp": "N", "st": "1 Macc 6:43", "t": "καὶ εἶδεν Ἐλεαζὰρ ὁ Σαυαρὰν ἓν τῶν θηρίων τεθωρακισμένον θώραξιν βασιλικοῖς, καὶ ἦν ὑπεράγον πάντα τὰ θηρία, καὶ ὤφθη ὅτι ἐν αὐτῷ ἐστιν ὁ βασιλεύς."}, {"sp": "N", "st": "1 Macc 6:44", "t": "καὶ ἔδωκεν ἑαυτὸν τοῦ σῶσαι τὸν λαὸν αὐτοῦ, καὶ περιποιῆσαι αὐτῷ ὄνομα αἰώνιον."}, {"sp": "N", "st": "1 Macc 6:45", "t": "καὶ ἐπέδραμεν αὐτῷ θράσει εἰς μέσον τῆς φάλαγγος, καὶ ἐθανάτου δεξιὰ καὶ εὐώνυμα, καὶ ἐσχίζοντο ἀπʼ αὐτοῦ ἔνθα καὶ ἔνθα."}, {"sp": "N", "st": "1 Macc 6:46", "t": "καὶ εἰσέδυ ὑπὸ τὸν ἐλέφαντα, καὶ ὑπέθηκεν αὐτῷ καὶ ἀνεῖλεν αὐτόν· καὶ ἔπεσεν ἐπὶ τὴν γῆν ἐπάνω αὐτοῦ, καὶ ἀπέθανεν ἐκεῖ"}, {"sp": "N", "st": "1 Macc 6:47", "t": "καὶ εἶδον τὴν ἰσχὺν τῆς βασιλείας καὶ τὰ ὁρμήματα τῶν δυνάμεων, καὶ ἐξέκλιναν ἀπʼ αὐτῶν."}, {"sp": "N", "st": "1 Macc 6:48", "t": "Καὶ ἐκ τῆς παρεμβολῆς τοῦ βασιλέως ἀνέβεννον εἰς συνάντησιν αὐτῶν εἰς Ἰερουσαλήμ, καὶ παρενέβαλεν ὁ βασιλεὺς εἰς τὴν Ἰουδαίαν καὶ εἰς τὸ ὄρος Σιών."}, {"sp": "N", "st": "1 Macc 6:49", "t": "καὶ ἐποίησεν μετὰ τῶν ἐκ Βεθσούρων· καὶ ἐξῆλθεν ἐκ τῆς πόλεως, ὅτι οὐκ ἦν αὐτοῖς ἐκεῖ διατροφὴ τοῦ συνκεκλεῖσθαι ἐν αὐτῇ, ὅτι σάββατον ἦν τῇ γῆ."}, {"sp": "N", "st": "1 Macc 6:50", "t": "καὶ κατελάβετο ὁ βασιλεὺς τὴν Βεθσούραν, καὶ ἐπέταξεν ἐκεῖ φρουρὰν τηρεῖν αὐτήν."}, {"sp": "N", "st": "1 Macc 6:51", "t": "καὶ παρενέβαλεν ἐπὶ τὸ ἁγίασμα ἡμέρας πολλάς, καὶ ἔστησεν ἐκεῖ βελοστάσεις καὶ μηχανὰς καὶ πυροβόλα καὶ λιθοβόλα καὶ σκορπίδια εἰς τὸ βάλλεσθαι βέλη καὶ σφενδόνας."}, {"sp": "N", "st": "1 Macc 6:52", "t": "καὶ ἐποίησαν καὶ αὐτοὶ μηχανὰς πρὸς τὰς μηχανὰς αὐτῶν, καὶ ἐπολέμησαν ἡμέρας πολλάς."}, {"sp": "N", "st": "1 Macc 6:53", "t": "βρώματα δὲ οὐκ ἦν ἐν τοῖς ἁγίοις, διὰ τὸ ἕβδομον ἔτος εἶναι, καὶ οἱ ἀνασωζόμενοι εἰς τὴν Ἰουδαίαν ἀπὸ τῶν ἐθνῶν κατέφαγον τὸ ὑπόλιμμα τῆς παραθέσεως·"}, {"sp": "N", "st": "1 Macc 6:54", "t": "καὶ ὑπελείφθησαν ἐν τοῖς ἁγίοις ἄνδρες ὀλίγοι, ὅτι κατεκράτησεν αὐτῶν ὁ λιμός· καὶ ἐσκορπίσθησαν ἕκαστος εἰς τὸν τόπον αὐτοῦ."}, {"sp": "N", "st": "1 Macc 6:55", "t": "Καὶ ἤκουσεν Λυσίας ὅτι Φίλιππος, ὃν κατέστησεν ὁ βασιλεὺς Ἀντίοχος ἔτι ζῶντος αὐτοῦ ἐκθρέψαι Ἀντίοχον τὸν υἱὸν αὐτοῦ εἰς τὸ βασιλεῦσαι αὐτόν,"}, {"sp": "N", "st": "1 Macc 6:56", "t": "ἀπέστρεψεν ἀπὸ τῆς Περσίδος καὶ Μηδίας, καὶ αἱ δυνάμεις αἱ πορευθεῖσαι τοῦ βασιλέως μετʼ αὐτοῦ, καὶ ὅτι ζητεῖ παραλαβεῖν τὰ τῶν πραγμάτων."}, {"sp": "N", "st": "1 Macc 6:57", "t": "καὶ κατέσπευδον καὶ ἐπενύσσοντο τοῦ ἀπελθεῖν· καὶ εἶπεν πρὸς τὸν βασιλέα καὶ τοὺς ἡγεμόνας τῆς δυνάμεως καὶ τοὺς ἄνδρας Ἐκλείπομεν καθʼ ἡμέραν, καὶ ἡ τροφὴ ἡμῖν ὀλίγη, καὶ ὁ τόπος, οὗ παρεμβάλλομεν, ἐστὶν ὀχυρός, καὶ ἐπίκειται ἡμῖν τὰ τῆς βασιλείας."}, {"sp": "N", "st": "1 Macc 6:58", "t": "νῦν οὖν δῶμεν δεξιὰν τοῖς ἀνθρώποις τούτοις, καὶ ποιήσωμεν μετʼ αὐτῶν εἰρήνην, καὶ μετὰ παντὸς ἔθνους αὐτῶν·"}, {"sp": "N", "st": "1 Macc 6:59", "t": "καὶ στήσωμεν αὐτοῖς τοῦ πορεύεσθαι τοῖς νομίμοις αὐτῶν, ὡς τὸ πρότερον· χάριν γὰρ τῶν νομίμων αὐτῶν, ὧν διεσκεδάσαμεν, ὠργίσθησαν καὶ ἐποίησαν ταῦτα πάντα."}, {"sp": "N", "st": "1 Macc 6:60", "t": "καὶ ἤρεσεν ὁ λόγος ἐναντίον τοῦ βασιλέως καὶ τῶν ἀρχόντων, καὶ ἀπέστειλεν πρὸς αὐτοὺς εἰρηνεῦσαι, καὶ ἐπεδέξαντο."}, {"sp": "N", "st": "1 Macc 6:61", "t": "καὶ ὤμοσεν αὐτοῖς ὁ βασιλεὺς καὶ οἱ ἄρχοντες ἐπὶ τούτοις· ἐξῆλθεν ἐκ τοῦ ὀχυρώματος,"}, {"sp": "N", "st": "1 Macc 6:62", "t": "καὶ εἰσῆλθεν ὁ βασιλεὺς εἰς τὸ ὄρος Σιών, καὶ ἴδεν τὸ ὀχύρωμα τοῦ τόπου· καὶ ἠθέτησεν τὸν ὁρκισμὸν ὃν ὤμοσεν, καὶ ἐνετείλατο καὶ καθεῖλεν τὸ τεῖχος κυκλόθεν."}, {"sp": "N", "st": "1 Macc 6:63", "t": "καὶ ἀπῆραν κατὰ σπουδὴν καὶ ἀπέστρεψεν εἰς Ἀντιοχίαν, καὶ εὗρεν Φίλιππον κυριεύοντα τῆς πόλεως, καὶ ἐπολέμησεν πρὸς αὐτόν, καὶ κατελάβετο τὴν πόλιν βίᾳ."}, {"sp": "N", "st": "1 Macc 7:1", "t": "Ἔτους ἑνὸς καὶ πεντηκοστοῦ ἐξῆλθεν Δημήτριος ὁ τοῦ Σελεύκου ἐκ Ῥώμης, καὶ ἀνέβη σὺν ἀνδράσιν ὀλίγοις εἰς πόλιν παραθαλασσίαν, καὶ ἐβασίλευσεν ἐκεῖ."}, {"sp": "N", "st": "1 Macc 7:2", "t": "καὶ ἐγένετο ὡς εἰσεπορεύετο εἰς οἶκον βασιλείας πατέρων αὐτοῦ, συνέλαβον αἱ δυνάμεις τὸν Ἀντίοχον καὶ τὸν Λυσίαν ἀγαγεῖν αὐτοὺς αὐτῷ."}, {"sp": "N", "st": "1 Macc 7:3", "t": "καὶ ἐγνώσθη αὐτῷ τὸ πρᾶγμα καὶ εἰπεν Μή μοι δείξητε τὰ πρόσαωπα αὐτῶν."}, {"sp": "N", "st": "1 Macc 7:4", "t": "καὶ ἀπέκτειναν αὐτοὺς αἱ δυνάμεις, καὶ ἐκάθισεν Δημήτριος ἐπὶ θρόνου βασιλείας αὐτοῦ."}, {"sp": "N", "st": "1 Macc 7:5", "t": "καὶ ἦλθον πρὸς αὐτὸν πάντες ἄνδρες ἄνομοι καὶ ἀσεβεῖς ἐξ Ἰσραήλ, καὶ Ἄλκιμος ἡγεῖται αὐτῶν βουλόμενος ἱερατεύειν."}, {"sp": "N", "st": "1 Macc 7:6", "t": "καὶ κατηγόρησαν τοῦ λαοῦ πρὸς τὸν βασιλέα, λέγοντες Ἀπώλεσεν Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ πάντας τοὺς φίλους σου, καὶ ἡμᾶς ἐσκόρπισεν ἀπὸ τῆς γῆς ἡμῶν."}, {"sp": "N", "st": "1 Macc 7:7", "t": "νῦν οὖν ἀπόστειλον ἄνδρα ᾧ πιστεύεις, καὶ πορευθεὶς ἰδέτω τὴν ἐξολέθρευσιν ἅπασαν ἣν ἐποίησεν ἡμῖν καὶ τῇ χώρᾳ τοῦ βασιλέως, καὶ ἐκολάσατο αὐτοὺς καὶ πάντας τοὺς ἐπιβοηθοῦντας αὐτοῖς."}, {"sp": "N", "st": "1 Macc 7:8", "t": "Καὶ ἐπέλεξεν ὁ βασιλεὺς τὸν Βακχίδην τῶν φίλων τοῦ βασιλέως κυριεύοντα ἐν τῷ πέραν τοῦ ποταμοῦ καὶ μέγαν ἐν τῇ βασιλείᾳ καὶ πιστὸν τῷ βασιλεῖ·"}, {"sp": "N", "st": "1 Macc 7:9", "t": "καὶ ἀπέστειλεν αὐτὸν καὶ Ἄλκιμον τὸν ἀσεβῆ, καὶ ἔστησαν αὐτῷ τὴν ἱερωσύνην, καὶ ἐνετείλατο αὐτῷ ποιῆσαι τὴν ἐκδίκησιν ἐν τοῖς υἱοῖς Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 7:10", "t": "καὶ ἀπῆλθεν καὶ ἦλθεν μετὰ δυνάμεως πολλῆς εἰς γῆν Ἰούδα· καὶ ἀπέστειλεν ἀγγέλους πρὸς Ἰούδαν καὶ πρὸς τοὺς ἀδελφοὺς αὐτοῦ λόγοις εἰρηνικοῖς μετὰ δόλου."}, {"sp": "N", "st": "1 Macc 7:11", "t": "καὶ οὐ προσεῖχον τοῖς λόγοις αὐτῶν· ἴδον γὰρ ὅτι ἦλθον μετὰ δυνάμεως πολλῆς."}, {"sp": "N", "st": "1 Macc 7:12", "t": "καὶ ἐπισυνήχθησαν πρὸς Ἄλκιμον καὶ Βακχίδην συναγωγὴ γραμματέων, ἐκζητῆσαι δίκαια."}, {"sp": "N", "st": "1 Macc 7:13", "t": "καὶ πρῶτοι οἱ Ἁσιδαῖοι ἦσαν ἐν υἱοῖς Ἰσραήλ, καὶ ἐπεζήτουν παρʼ αὐτῶν εἰρήνην·"}, {"sp": "N", "st": "1 Macc 7:14", "t": "εἶπαν γάρ Ἄνθρωπος ἱερεὺς ἐκ τοῦ σπέρματος Ἀαρὼν ἦλθεν ἐν ταῖς δυνάμεσιν, καὶ οὐκ ἀδικήσει ἡμᾶς."}, {"sp": "N", "st": "1 Macc 7:15", "t": "καὶ ἐλάλησεν μετʼ αὐτῶν εἰρηνικοὺς λόγους, καὶ ὤμοσεν αὐτοῖς λέγων Οὐκ ἐκζητήσομεν ὑμῖν κακόν, καὶ τοῖς φίλοις ὑμῶν."}, {"sp": "N", "st": "1 Macc 7:16", "t": "καὶ ἐνεπίστευσαν αὐτῷ, καὶ συνέλαβεν ἐξ αὐτῶν ἑξήκοντα ἄνδρας, καὶ ἀπέκτεινεν αὐτοὺς ἐν ἡμέρᾳ μιᾷ κατὰ τοὺς λόγους οὓς ἔγραψεν"}, {"sp": "N", "st": "1 Macc 7:17", "t": "¹⁷Σάρκας ὁσίων σου καὶ αἵματα αὐτῶν ἐξέχεαν κύκλῳ Ἰερουσαλήμ, καὶ οὐκ ἦν αὐτοῖς ὁ θάπτων."}, {"sp": "N", "st": "1 Macc 7:18", "t": "Καὶ ἐπέπεσεν αὐτῶν ὁ φόβος καὶ ὁ τρόμος εἰς πάντα τὸν λαόν, ὅτι εἶπαν Οὐκ ἔστιν ἐν αὐτοῖς ἀλήθεια καὶ κρίσις· παρέβησαν γὰρ τὴν στάσιν καὶ τὸν ὅρκον ὃν ὤμοσαν."}, {"sp": "N", "st": "1 Macc 7:19", "t": "καὶ ἀπῆρεν Βακχίδης ἀπὸ Ἰερουσαλήμ, καὶ παρενέβαλεν ἐν Βηζέθ, καὶ ἀπέστειλεν καὶ συνέλαβεν πολλοὺς ἀπὸ τῶν μετʼ αὐτοῦ αὐτομολησάντων ἀνδρῶν καί τινας τοῦ λαοῦ, καὶ ἔθυσεν αὐτοὺς εἰς τὸ φρέαρ τὸ μέγα."}, {"sp": "N", "st": "1 Macc 7:20", "t": "καὶ κατέστησεν τὴν χώραν τῷ Ἀλκίμῳ, καὶ ἀφῆκεν μετʼ αὐτοῦ δύναμιν τοῦ βοηθεῖν αὐτῷ· καὶ ἀπῆλθεν Βακχίδης πρὸς τὸν βασιλέα."}, {"sp": "N", "st": "1 Macc 7:21", "t": "καὶ ἠγωνίσατο Ἄλκιμος περὶ τῆς ἀρχιερωσύνης."}, {"sp": "N", "st": "1 Macc 7:22", "t": "καὶ συνήχθησαν πρὸς αὐτὸν πάντες οἱ ταράσσοντες τὸν λαὸν αὐτῶν, καὶ κατεκράτησαν γῆν Ἰούδα, καὶ ἐποίησαν πληγὴν μεγάλην ἐν Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 7:23", "t": "καὶ ἴδεν Ἰούδας πᾶσαν τὴν κακίαν ἣν ἐποίησεν Ἄλκιμος καὶ οἱ μετʼ αὐτοῦ ἐν υἱοῖς Ἰσραὴλ ὑπὲρ τὰ ἔθνη·"}, {"sp": "N", "st": "1 Macc 7:24", "t": "καὶ ἐξῆλθεν εἰς πάντα τὰ ὅρια τῆς Ἰουδαίας καὶ κυκλόθεν, καὶ ἐποίησεν ἐκδίκησιν ἐν τοῖς ἀνδράσιν καὶ τοῖς αὐτομολήσασιν, καὶ ἀνεστάλησαν τοῦ πορευθῆναι εἰς χώραν."}, {"sp": "N", "st": "1 Macc 7:25", "t": "ὡς δὲ ἴδεν Ἅλκιμος ὅτι ἐνίσχυσεν Ἰούδας καὶ οἱ μετʼ αὐτοῦ, καὶ ἔγνω ὅτι δύναται ὑποστῆναι αὐτούς, καὶ ἐπέστρεψεν πρὸς τὸν βασιλέα καὶ κατηγόρησεν αὐτῶν πονηρά."}, {"sp": "N", "st": "1 Macc 7:26", "t": "Καὶ ἀπέστειλεν ὁ βασιλεὺς Νικάνορα ἕνα τῶν ἀρχόντων αὐτοῦ τῶν ἐνδόξων, καὶ μισοῦντα καὶ ἐχθραίνοντα τῷ Ἰσραήλ, καὶ ἐνετείλατο αὐτῷ ἐξᾶραι τὸν λαόν."}, {"sp": "N", "st": "1 Macc 7:27", "t": "καὶ ἦλθεν Νικάνωρ εἰς Ἰερουσαλὴμ δυνάμει πολλῇ, καὶ ἀπέστειλεν πρὸς Ἰούδαν καὶ τοὺς ἀδελφοὺς αὐτοῦ μετὰ δόλου λόγοις εἰρηνικοῖς λέγων"}, {"sp": "N", "st": "1 Macc 7:28", "t": "Μὴ ἔστω μάχη ἀνὰ μέσον ἐμοῦ καὶ ὑμῶν· ἥξω ἐν ἀνδράσιν ὀλίγοις, ἵνα ἴδω ὑμῶν τὰ πρόσωπα μετʼ εἰρήνης."}, {"sp": "N", "st": "1 Macc 7:29", "t": "καὶ ἦλθεν πρὸς Ἰούδαν, καὶ ἠσπάσαντο ἀλλήλους εἰρηνικῶς· καὶ οἱ πολέμιοι ἦσαν ἕτοιμοι ἐξαρπάσαι τὸν Ἰούδαν."}, {"sp": "N", "st": "1 Macc 7:30", "t": "καὶ ἐγνώσθη ὁ λόγος τῷ Ἰούδᾳ, ὅτι μετὰ δόλου ἦλθεν ἐπʼ αὐτόν· καὶ ἐπτοήθη ἀπʼ αὐτοῦ, καὶ οὐκ ἠβουλήθη ἔτι ἰδεῖν τὸ πρόσωπον αὐτοῦ."}, {"sp": "N", "st": "1 Macc 7:31", "t": "καὶ ἔγνω Νικάνωρ ὅτι ἀπεκαλύφθη ἡ βουλὴ αὐτοῦ, καὶ ἐξῆλθεν εἰς συνάντησιν τῷ Ἰούδα κατὰ Χαρφαρσαραμά."}, {"sp": "N", "st": "1 Macc 7:32", "t": "καὶ ἔπεσαν τῶν παρὰ Νικάνορος ὡς πεντακισχίλιοι ἄνδρες, καὶ ἔφυγον εἰς τὴν πόλιν Δαυείδ."}, {"sp": "N", "st": "1 Macc 7:33", "t": "Καὶ μετὰ τοὺς λόγους τούτους ἀνέβη Νικάνωρ εἰς τὸ ὄρος Σιών· καὶ ἐξῆλθαν ἀπὸ τῶν ἱερέων ἐκ τῶν ἁγίων καὶ ἀπὸ τῶν πρεσβυτέρων τοῦ λαοῦ ἀσπάσασθαι αὐτὸν εἰρηνικῶς, καὶ δεῖξαι αὐτῷ τὴν ὁλοκαύτωσιν τὴν προσφερομένην ὑπὲρ τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 7:34", "t": "καὶ ἐμυκτήρισεν αὐτούς, καὶ κατεγέλασεν αὐτῶν καὶ ἐμίανεν αὐτούς, καὶ ἐλάλησεν ὑπερηφάνως."}, {"sp": "N", "st": "1 Macc 7:35", "t": "καὶ ὤμοσεν μετὰ θυμοῦ λέγων Ἐὰν μὴ παραδοθῇ Ἰούδας καὶ ἡ παρεμβολὴ αὐτοῦ τὸ νῦν εἰς χεῖράς μου, καὶ ἔσται ἐὰν ἐπιστρέψω ἐν εἰρήνῃ, ἐνπυριῶ τὸν οἶκον τοῦτον. καὶ ἐξῆλθεν μετὰ θυμοῦ."}, {"sp": "N", "st": "1 Macc 7:36", "t": "καὶ εἰσῆλθον οἱ ἱερεῖς καὶ ἔστησαν κατὰ πρόσωπον τοῦ θυσιαστηρίου καὶ τοῦ ναοῦ, καὶ ἔκλαυσαν καὶ εἶπαν"}, {"sp": "N", "st": "1 Macc 7:37", "t": "Σὺ ἐξελέξω τὸν οἶκον τοῦτον ἐπικληθῆναι τὸ ὄνομά σου ἐπʼ αὐτόν, εἶναι οἶκον προσευχῆς καὶ δεήσεως τῷ λαῷ σου."}, {"sp": "N", "st": "1 Macc 7:38", "t": "ποίησον ἐκδίκησιν ἐν τῷ ἀνθρώπῳ τούτῳ καὶ ἐν τῇ παρεμβολῇ αὐτοῦ, καὶ πεσάτωσαν ἐν ῥομφαίᾳ· μνήσθητι τῶν δυσφημιῶν αὐτῶν, καὶ μὴ δῷς αὐτοῖς μονὴν."}, {"sp": "N", "st": "1 Macc 7:39", "t": "Καὶ ἐξῆλθεν Νικάνωρ ἐξ Ἰερουσαλὴμ καὶ παρενέβαλον ἐν Βεθώρων, καὶ συνῆντησεν αὐτῷ δύναμις Συρίας."}, {"sp": "N", "st": "1 Macc 7:40", "t": "καὶ Ἰούδας παρενέβαλεν ἐν Ἀδασὰ ἐν τρισχιλίοις ἀνδράσιν· καὶ προσηύξατο Ἰούδας καὶ εἶπεν"}, {"sp": "N", "st": "1 Macc 7:41", "t": "Οἱ παρὰ τοῦ βασιλέως ὅτε ἐδυσφήμησαν, ἐξῆλθεν ἄγγελός σου καὶ ἐπάταξεν ἐν αὐτοῖς ἑκατὸν ὀγδοήκοντα πέντε χιλιάδας."}, {"sp": "N", "st": "1 Macc 7:42", "t": "οὕτως σύντριψον τὴν παρεμβολὴν ταύτην ἐνώπιον ἡμῶν σήμερον· καὶ γνώτωσαν οἱ ἐπίλοιποι ὅτι κακῶς ἐλάλησεν ἐπὶ τὰ ἅγιά σου, καὶ κρῖνον αὐτὸν κατὰ τὴν κακίαν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 7:43", "t": "καὶ συνῆψαν αἱ παρεμβολαὶ εἰς πόλεμον τῇ τρισκαιδεκάτῃ τοῦ μηνὸς Ἄδάρ, καὶ συνετρίβη ἡ παρεμβολὴ Νικάνορος· καὶ ἔπεσεν αὐτὸς πρῶτος ἐν τῷ πολέμῳ."}, {"sp": "N", "st": "1 Macc 7:44", "t": "ὡς δὲ ἴδεν ἡ παρεμβολὴ αὐτοῦ ὅτι ἔπεσεν Νικάνωρ, ῥίψαντες τὰ ὅπλα αὐτῶν ἔφυγον."}, {"sp": "N", "st": "1 Macc 7:45", "t": "καὶ κατεδίωκον αὐτοὺς ὁδὸν ἡμέρας μιᾶς ἀπὸ Ἀδασὰ ἕως τοῦ ἐλθεῖν εἰς Γαζηρά, καὶ ἐσάλπισαν ὀπίσω αὐτῶν ταῖς σάλπιγξιν τῶν σημασιῶν."}, {"sp": "N", "st": "1 Macc 7:46", "t": "καὶ ἐξῆλθον ἐκ πασῶν τῶν κωμῶν τῆς Ἰουδαίας κυκλόθεν, καὶ ὑπερεκέρων αὐτοὺς· καὶ ἀνέστρεφον οὖτοι πρὸς τούτους, καὶ ἔπεσαν πάντες ῥομφαίᾳ, καὶ οὐ κατελείφθη ἐξ αὐτῶν οὐδὲ εἰς."}, {"sp": "N", "st": "1 Macc 7:47", "t": "καὶ ἔλαβον τὰ σκῦλα καὶ τὴν προνομήν, καὶ τὴν κεφαλὴν Νικάνορος ἀφεῖλαν καὶ τὴν δεξιὰν αὐτοῦ, ἣν ἐξέτεινεν ὑπερηφάνως. καὶ ἤνεγκαν καὶ ἐξέτειναν παρὰ τὴν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Macc 7:48", "t": "καὶ ηὐφράνθη ὁ λαὸς σφόδρα, καὶ ἤγαγον τὴν ἡμέραν ἐκείνην ἡμέραν εὐφροσύνης μεγάλην."}, {"sp": "N", "st": "1 Macc 7:49", "t": "καὶ ἔστησαν τοῦ ἀγαγεῖν κατʼ ἐνιαυτὸν τὴν ἡμέραν ταύτην τῇ τρισκαιδεκάτῃ τοῦ Ἀδάρ."}, {"sp": "N", "st": "1 Macc 7:50", "t": "καὶ ἡσύχασεν ἡ γῆ Ἰούδα ἡμέρας ὀλίγας."}, {"sp": "N", "st": "1 Macc 8:1", "t": "Καὶ ἤκουσεν Ἰούδας τὸ ὄνομα τῶν Ῥωμαίων, ὅτι εἰσὶν δυνατοὶ ἐν ἰσχύι, καὶ αὐτοὶ εὐδοκοῦσιν ἐν πᾶσιν τοῖς προστεθειμένοις αὐτοῖς, καὶ ὅσοι ἐὰν προστεθῶσιν αὐτοῖς, καὶ ὅσοι ἐὰν προσέλθωσιν αὐτοῖς, ἱστῶσιν αὐτοῖς φιλίαν,"}, {"sp": "N", "st": "1 Macc 8:2", "t": "καὶ ὅτι εἰσὶν δυνατοὶ ἰσχύι· καὶ διηγήσαντο αὐτῷ τοὺς πολέμοις αὐτῶν καὶ τὰς ἀνδραγαθίας ἃς ποιοῦσιν ἐν τοῖς Γαλάταις, καὶ ὅτι κατεκράτησαν αὐτῶν, καὶ ἤγαγον αὐτοὺς ὑπὸ φόρον·"}, {"sp": "N", "st": "1 Macc 8:3", "t": "καὶ ὅσα ἐποίησαν ἐν χώρᾳ Σπανίας, τοῦ κατακρατῆσαι τῶν μετάλλων τοῦ ἀργυρίου καὶ τοῦ χρυσίου τοῦ ἐκεῖ,"}, {"sp": "N", "st": "1 Macc 8:4", "t": "καὶ κατεκράτησαν τοῦ τόπου παντὸς τῇ βουλῇ αὐτῶν καὶ τῇ μακροθυμίᾳ—καὶ ὁ τόπος ἦν μακρὰν ἀπέχων ἀπʼ αὐτῶν σφόδρα—καὶ τῶν βασιλέων τῶν ἐπελθόντων ἐπʼ αὐτοὺς ἀπʼ ἄκρου τῆς γῆς, ἕως συνέτριψαν αὐτοὺς καὶ ἐπάταξαν ἐν αὐτοῖς πληγὴν μεγάλην, καὶ οἱ ἐπίλοιποι διδόασιν αὐτοῖς φόρον κατʼ ἐνιαυτόν·"}, {"sp": "N", "st": "1 Macc 8:5", "t": "καὶ τὸν Φίλιππον καὶ τὸν Περσέα Κιτιέων βασιλέα καὶ τοὺς ἐπηρμένους ἐπʼ αὐτούς, συνέτριψαν αὐτοὺς πολέμῳ καὶ κατεκράτησαν αὐτῶν·"}, {"sp": "N", "st": "1 Macc 8:6", "t": "καὶ Ἀντίοχον τὸν μέγαν βασιλέα τῆς Ἀσίας τὸν πορευθέντα ἐπʼ αὐτοὺς εἰς πόλεμον ἔχοντα ἑκατὸν εἴκοσι ἐλέφαντας καὶ ἵππον καὶ ἅρματα καὶ δύναμιν πολλὴν σφόδρα, καὶ συνετρίβη ἀπʼ αὐτῶν·"}, {"sp": "N", "st": "1 Macc 8:7", "t": "καὶ ἔλαβον αὐτὸν ζῶντα, καὶ ἔστησαν αὐτοῖς διδόναι αὐτόν τε καὶ τοὺς βασιλεύοντας μετʼ αὐτὸν φόρον μέγαν. καὶ διδόναι ὅμηρα καὶ διαστολήν,"}, {"sp": "N", "st": "1 Macc 8:8", "t": "καὶ χώραν τὴν Ἰνδικὴν καὶ Μηδίαν καὶ Λυδίαν, καὶ ἀπὸ τῶν καλλίστων χωρῶν αὐτῶν, καὶ λαβόντες αὐτὰς παρʼ αὐτοῦ ἔδωκαν αὐτὰς Εύμενεῖ τῷ βασιλεῖ·"}, {"sp": "N", "st": "1 Macc 8:9", "t": "καὶ ὅτι οἱ ἐκ τῆς Ἑλλάδος ἐβουλεύσαντο ἐλθεῖν καὶ ἐξᾶραι αὐτούς,"}, {"sp": "N", "st": "1 Macc 8:10", "t": "καὶ ἐγνώσθη ὁ λόγος αὐτοῖς, καὶ ἀπέστειλαν ἐπʼ αὐτοὺς στρατηγὸν ἕνα, καὶ ἐπολέμησαν πρὸς αὐτούς, καὶ ἔπεσαν ἐξ αὐτῶν τραυματίαι πολλοί, καὶ ᾐχμαλώτισαν τὰς γυναῖκας αὐτῶν καὶ τὰ τέκνα αὐτῶν, καὶ ἐπρονόμενσαν αὐτούς, καὶ κατεκράτησαν τῆς γῆς αὐτῶν, καὶ καθεῖλον τὰ ἀχυρώματα αὐτῶν, καὶ ἐπρονόμευσαν αὐτούς καὶ κατεδουλώσαντο αὐτοὺς ἕως τῆς ἡμέρας ταύτης."}, {"sp": "N", "st": "1 Macc 8:11", "t": "καὶ τὰς ἐπιλοίπους βασιλείας, καὶ τὰς νήσους, ὅσοι ποτὲ ἀνέστησαν αὐτοῖς, κατεφθειραν καὶ ἐδούλωσαν αὐτοῖς·"}, {"sp": "N", "st": "1 Macc 8:12", "t": "μετὰ δέ τῶν φίλων αὐτῶν καὶ τῶν ἐπαναπαυομένων αὐτοῖς συνετήρησαν αὐτοῖς φιλίαν, καὶ κατεκράτησαν τῶν βασιλειῶν τῶν ἐγγὺς καὶ τῶν μακράν· καὶ ὅσοι ἤκουσαν τὸ ὄνομα αὐτῶν ἐφοβοῦντο ἀπʼ αὐτῶν·"}, {"sp": "N", "st": "1 Macc 8:13", "t": "οἷς δʼ ἂν βούλωνται βοηθεῖν καὶ βασιλεύειν, βασιλεύσουσιν· οὓς δ᾿ ἃν βούλωνται, μεθιστῶσιν, καὶ ὑψώθησαν σφόδρα."}, {"sp": "N", "st": "1 Macc 8:14", "t": "καὶ ἐν ἅποσιν τούτοις οὐκ ἐπέθεντο οὐδεὶς αὐτῶν διάδημα, καὶ οὐ περιεβάλοντο πορφύραν, ὥστε ἁδρυνθῆναι ἐν αὐτῇ."}, {"sp": "N", "st": "1 Macc 8:15", "t": "καὶ βουλευτήριον ἐποίησαν ἑαυτοῖς, καὶ καθʼ ἡμέραν ἐβουλεύοντο τριακόσιοι καὶ εἴκοσι, βουλευόμενοι διὰ παντὸς περὶ τοῦ πλήθους, τοῦ εὐκοσμεῖν ἑαυτούς."}, {"sp": "N", "st": "1 Macc 8:16", "t": "καὶ πιστεύουσιν ἑνὶ ἀνθρώπῳ ἄρχειν αὐτῶν κατʼ ἐνιαυτὸν καὶ κυριεύειν πάσης τῆς γῆς αὐτῶν, καὶ πάντες ἀκούουσιν τοῦ ἑνός, καὶ οὐκ ἔστιν φθόνος οὔτε ζῆλος ἐν αὐτοῖς."}, {"sp": "N", "st": "1 Macc 8:17", "t": "Καὶ ἐπέλεξεν Ἰούδας τὸν Εὐπόλεμον υἱὸν Ἰωάννου τοῦ Ἁκχὼς καὶ Ἰάσονα υἱὸν Ἐλεαζάρου, καὶ ἀπέστειλεν αὐτοὺς εἰς Ῥώμην, στῆσαι αὐτοῖς φιλίαν καὶ συμμαχίαν,"}, {"sp": "N", "st": "1 Macc 8:18", "t": "καὶ τοῦ ἆραι τὸν ζυγὸν αὐτῶν, ὅτι ἴδον τὴν βασιλείαν τῶν Ἐλλήνων καταδουλουμένους τὸν Ἰσραὴλ δουλίαν."}, {"sp": "N", "st": "1 Macc 8:19", "t": "καὶ ἐπορεύθησαν εἰς Ῥώμην, καὶ ἡ ὁδὸς πολλὴ σφόδρα· καὶ εἰσῆλθον εἰς τὸ βουλευτήριον, καὶ ἀπεκρίθησαν"}, {"sp": "N", "st": "1 Macc 8:20", "t": "Ἰούδας ὁ καὶ Μακκαβαῖος καὶ οἱ ἀδελφοὶ αὐτοῦ καὶ τὸ πλῆθος τῶν Ἰουδαίων απέστειλαν ἡμᾶς πρὸς ὑμᾶς, στῆσαι μεθʼ ὑμῶν συμμαχίαν καὶ εἰρήνην, καὶ γραφῆναι ἡμᾶς συμμάχους καὶ φίλους ὑμῶν."}, {"sp": "N", "st": "1 Macc 8:21", "t": "καὶ ἤρεσεν ὁ λόγος ἐνώπιον αὐτῶν."}, {"sp": "N", "st": "1 Macc 8:22", "t": "καὶ τοῦτο τὸ ἀντίγραφον τῆς γραφῆς ἧς ἀντέγραψαν ἐπὶ δέλτοις χαλκαῖς καὶ ἀπέστειλαν εἰς Ἰερουσαλὴμ εἶναι παρʼ αὐτοῖς ἐκεῖ μνημόσυνον εἰρήνης καὶ συμμαχίας"}, {"sp": "N", "st": "1 Macc 8:23", "t": "Καλῶς γένοιτο Ῥωμαίοις καὶ τῷ ἔθνει τῶν Ἰουδαίων ἐν τῇ θαλάσσῃ καὶ ἐπὶ τῆς ξηρᾶς εἰς τὸν αἰῶνα, καὶ ῥομφαία καὶ ἐχθρὸς μακρυχθείη ἀπʼ αὐτῶν."}, {"sp": "N", "st": "1 Macc 8:24", "t": "ἐὰν δὲ ἐνστῇ πόλεμος Ῥώμῃ προτέρᾳ ἢ πᾶσι τοῖς συμμάχοις αὐτῶν ἐν πάσῃ κυρίᾳ αὐτῶν·"}, {"sp": "N", "st": "1 Macc 8:25", "t": "συμμαχήσει τὸ ἔθνος τῶν Ἰουδαίων, ὡς ἂν ὁ καιρὸς ὑπογραφῇ αὐτοῖς, καρδίᾳ πλήρει."}, {"sp": "N", "st": "1 Macc 8:26", "t": "καὶ τοῖς πολεμοῦσιν οὐ δώσουσιν οὐδὲ ἐπαρκέσουσιν σῖτον, ὅπλα, ἀργύριον, πλοῖα, ὡς ἔδοξεν Ῥώμῃ· καὶ φυλάξονται τὰ φυλάγματα αὐτῶν οὐθὲν λαβόντες."}, {"sp": "N", "st": "1 Macc 8:27", "t": "κατὰ τὰ αὐτὰ δέ, ἐὰν ἔθνει Ἰουδαίων συμβῇ προτέροις πόλεμος, συμμαχήσουσιν οἱ Ῥωμαῖοι ἐκ ψυχῆς, ὡς ἂν αὐτοῖς ὁ καιρὸς ὑπογράφῃ."}, {"sp": "N", "st": "1 Macc 8:28", "t": "καὶ τοῖς συμμαχοῖσιν οὐ δοθήσεται σῖτος, ὅπλα, ἀργύριον, ὡς ἔδοξεν Ῥώμῃ· καὶ φυλάξονται τὰ φυλάγματα ταῦτα, καὶ οὐ μετὰ δόλου."}, {"sp": "N", "st": "1 Macc 8:29", "t": "κατὰ τοὺς λόγους τούτους οὕτως ἔστησαν Ῥωμαῖοι τῷ δήμῳ τῶν Ἰουδαίων."}, {"sp": "N", "st": "1 Macc 8:30", "t": "ἐὰν δὲ μετὰ τοὺς λόγους τούτους βουλεύσωνται οὗτοι καὶ οὗτοι προσθεῖναι ἢ ἀφελεῖν, ποιήσονται ἐξ αἰρέσεως αὐτῶν, καὶ ὃ ἐὰν προσθῶσιν ἢ ἀφέλωσιν ἔσται κύρια."}, {"sp": "N", "st": "1 Macc 8:31", "t": "καὶ περὶ τῶν κακῶν ὧν ὁ βασιλεὺς Δημήτριος συντελεῖται εἰς αὐτούς, ἐγράψαμεν αὐτῷ λέγοντες Διὰ τί ἐβάρυνας τὸν ζυγόν σου ἐπὶ τοὺς φίλους ἡμῶν τοὺς συμμάχους Ἰουδαίους;"}, {"sp": "N", "st": "1 Macc 8:32", "t": "ἐὰν οὖν ἔτι ἐντύχωσιν κατὰ σοῦ, ποιήσομεν αὐτοῖς τὴν κρίσιν, καὶ πολεμήσομέν σε διὰ τῆς θαλάσσης καὶ διὰ τῆς ξηρᾶς."}, {"sp": "N", "st": "1 Macc 9:1", "t": "Καὶ ἤκουσεν Δημήτριος ὅτι ἐποίησεν Νικάνωρ καὶ αἱ δυνάμεις αὐτοῦ πόλεμον, καὶ προσέθετο τὸν Βακχίδην καὶ τὸν Ἄλκιμον ἐκ δευτέρου ἀποστεῖλαι εἰς γῆν Ἰούδα, καὶ τὸ δεξιὸν κέρας μετʼ αὐτῶν."}, {"sp": "N", "st": "1 Macc 9:2", "t": "καὶ ἐπορεύθησαν ὁδὸν τὴν εἰς Γάλγαλα, καὶ παρενεβάλοσαν ἐπὶ Μεσσαλὼθ τὴν ἐν Ἀρβήλοις, καὶ προκατελάβοντο αὐτήν. καὶ ἀπῶλεσεν ψυχας ἀνθρώπων πολλάς."}, {"sp": "N", "st": "1 Macc 9:3", "t": "καὶ τοῦ μηνὸς τοῦ πρώτου ἔτους δευτέρου καὶ πεντηκοστοῦ καὶ ἑκατοστοῦ παρενέβαλλον εἰς Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Macc 9:4", "t": "καὶ ἀπῆραν καὶ ἐπορεύθησαν εἰς Βερέαν ἐν εἴκοσι χιλιασιν ἀνδρῶν καὶ δισχιλιάσιν ἵππων."}, {"sp": "N", "st": "1 Macc 9:5", "t": "καὶ Ἰούδας ἦν παρεμβεβληκὼς ἐν Ἀλασά, καὶ τρισχίλιοι ἄνδρες ἐκλεκτοὶ μετʼ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 9:6", "t": "καὶ ἴδον τὸ πλῆθος τῶν δυνάμεων, ὅτι πολλοί εἰσιν, καὶ ἐφοβήθησαν σφόδρα· καὶ ἐξερύησαν πολλοὶ ἀπὸ τῆς παρεμβολῆς, οὐ κατελείφθησαν ἐξ αὐτῶν ἀλλ᾿ ἢ ὀκτακόσιοι ἄνδρες."}, {"sp": "N", "st": "1 Macc 9:7", "t": "καὶ ἴδεν Ἰούδας ὅτι ἀπερρύη ἡ παρεμβολὴ αὐτοῦ. καὶ ὁ πόλεμος ἔθλιβεν αὐτόν· καὶ συνετρίβη τῇ καρδίᾳ, ὅτι οὐκ εἶχεν καιρὸν συναγαγεῖν αὐτούς."}, {"sp": "N", "st": "1 Macc 9:8", "t": "καὶ ἐξελύθη καὶ εἶπεν τοῖς καταλειφθεῖσιν Ἀναστῶμεν καὶ ἀναβῶμεν ἐπὶ τοὺς ὑπεναντίους ἡμῖν, ἐὰν ἄρα δυνώμεθα πολεμῆσαι αὐτούς."}, {"sp": "N", "st": "1 Macc 9:9", "t": "καὶ ἀπέστρεψαν αὐτόν, λέγοντες Οὐ μὴ δυνησώμεθα, ἀλλʼ ἢ σώζωμεν τὰς ἑαυτῶν ψυχάς τὸ νῦν· ἐπιστρέψωμεν μετὰ τῶν ἀδελφῶν ἡμῶν, καὶ πολεμήσωμεν πρὸς αὐτούς· ἡμεῖς δὲ ὀλίγοι."}, {"sp": "N", "st": "1 Macc 9:10", "t": "καὶ εἶπεν Ἰούδας Μή μοι γένοιτο ποιῆσαι τὸ πράγμα τοῦτο, φυγεῖν ἀπʼ αὐτῶν· καὶ ἤγγικεν ὁ καιρὸς ἡμῶν, καὶ ἀποθάνωμεν ἀνδρίᾳ χάριν τῶν ἀδελφῶν ἡμῶν, καὶ μὴ καταλείπωμεν αἰτίαν τῇ δόξῃ ἡμῶν."}, {"sp": "N", "st": "1 Macc 9:11", "t": "καὶ ἀπῆρεν ἡ δύναμις ἀπὸ τῆς παρεμβολῆς, καὶ ἔστησαν εἰς συνάντησιν αὐτοῖς, καὶ ἐμερίσθη ἡ ἵππος εἰς δύο μέρη, καὶ οἱ σφενδονῆται καὶ οἱ τοξόται προεπορεύοντο τῆς δυνάμεως, καὶ οἱ πρωταγωνισταὶ πάντες οἱ δυντοί."}, {"sp": "N", "st": "1 Macc 9:12", "t": "Βακχίδης δὲ ἦν ἐν τῷ δεξιῷ κέρατι, καὶ ἤγγισεν ἡ φάλαγξ ἐκ τῶν δύο μερῶν, καὶ ἐφώνουν ταῖς σάλπιγξιν, καὶ ἐσάλπισαν καὶ οἱ παρὰ Ἰούδου καὶ αὐτοὶ ταῖς σάλπιγξιν·"}, {"sp": "N", "st": "1 Macc 9:13", "t": "καὶ ἐσείσθη ἡ γῆ ἀπὸ τῶν παρεμβολῶν αὐτῶν· καὶ ἐγένετο ὁ πόλεμος συνηγμένος ἀπὸ πρωίθεν ἕως ἑσπέρας."}, {"sp": "N", "st": "1 Macc 9:14", "t": "καὶ ἴδεν Ἰούδας ὅτι Βακχίδης καὶ τὸ στερέωμα τῆς παρεμβολῆς ἐν τοῖς δεξιοῖς, καὶ συυῆλθον αὐτο πάντες οἱ εὔψυχοι τῃ καρδίᾳ."}, {"sp": "N", "st": "1 Macc 9:15", "t": "καὶ συνετρίβη τὸ δεξιον κέρας ἀπʼ αὐτῶν, καὶ ἐδίωκεν ὀπίσω αὐτῶν ἕως Ἀζώτου ὄρους."}, {"sp": "N", "st": "1 Macc 9:16", "t": "καὶ οἱ εἰς τὸ ἀριστερον κέρας ἴδον ὅτι συνετρίβη τὸ δεξιὸν κέρας, καὶ ἐπέστρεψαν κατὰ πόδας Ἰούδα καὶ τῶν μετʼ αὐτοῦ ἐκ τῶν ὄπισθεν."}, {"sp": "N", "st": "1 Macc 9:17", "t": "καὶ ὁ πόλεμος, καὶ ἔπεσαν τραυματίαι πολλοὶ ἐκ τούτων καὶ ἐκ τούτων."}, {"sp": "N", "st": "1 Macc 9:18", "t": "καὶ Ἰούδας ἔπεσεν καὶ οἱ λοιποὶ ἔφυγον."}, {"sp": "N", "st": "1 Macc 9:19", "t": "καὶ ἦραν Ἰωναθὰν καὶ Σίμων Ἰούδαν τὸν ἀδελφὸν αὐτοῦ καὶ ἔθαψαν αὐτὸν ἐν τῷ τάφῳ τῶν πατέρων αὐτοῦ ἐν Μωδεείμ."}, {"sp": "N", "st": "1 Macc 9:20", "t": "καὶ ἔκλαυσαν αὐτὸν ἐκεῖ, καὶ ἐκόψαντο αὐτὸν πᾶς Ισραὴλ κοπετὸν μέγαν, καὶ ἐπένθουν ἡμέρας πολλὰς καὶ εἶπαν"}, {"sp": "N", "st": "1 Macc 9:21", "t": "Πῶς ἔπεσεν δυνατός, σώζων τὸν Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 9:22", "t": "Καὶ τὰ περισσὰ τῶν λόγων Ἰούδου καὶ τῶν πολέμων καὶ τῶν ἀνδραγαθιῶν ὦν ἐποίησεν καὶ τῆς μεγαλωσύνης αὐτοῦ οὐ κατεγράφη· πολλὰ γὰρ ἦν σφόδρα."}, {"sp": "N", "st": "1 Macc 9:23", "t": "Καὶ ἐγένετο μετὰ τὴν τελευτὴν Ἰούδου, ἐξέκυψαν οἱ ἄνομοι ἐν πᾶσιν τοῖς ὁρίοις Ἰσραήλ, καὶ ἀνέτειλαν πάντες οἱ ἐργαζόμενοι τὴν ἀδικίαν."}, {"sp": "N", "st": "1 Macc 9:24", "t": "ἐν ταῖς ἡμέραις ἐκείναις ἐγενήθη λιμὸς μεγάλη σφόδρα, καὶ αὐτομόλησεν ἡ χώρα μετʼ αὐτῶν. ²⁵καὶ ἐξέλεξεν Βακχίδης τοὺς ἀσεβεῖς ἄνδρας, καὶ κατέστησεν αὐτοὺς κυρίους τῆς χώρας."}, {"sp": "N", "st": "1 Macc 9:25", "t": "καὶ ἐξεζήτουν καὶ ἐξηραύνων τοὺς φίλους Ἰούδου, καὶ ἦγον αὐτοὺς πρὸς Βακχίδην· καὶ ἐξεδίκα αὐτούς, καὶ ἐνέπαιζον αὐτοῖς."}, {"sp": "N", "st": "1 Macc 9:26", "t": "καὶ ἐγένετο θλίψις μεγάλη ἐν τῷ Ἰσραήλ, ἥτις οὐκ ἐγένετο ἀφʼ ἧς ἡμέρας οὐκ ὤφθη προφήτης αὐτοῖς."}, {"sp": "N", "st": "1 Macc 9:28", "t": "καὶ ἡθροίσθησαν πάντες οἱ φίλοι Ἰούδου καὶ εἶπον τῷ Ἰωναθάν"}, {"sp": "N", "st": "1 Macc 9:29", "t": "Ἀφʼ οὗ ὁ ἀδελφός σου Ἰούδας τετελεύτηκεν, καὶ ἀνὴρ ὅμοιος αὐτῷ οὐκ ἔστιν ἐξελθεῖν πρὸς τοὺς ἐχθροὺς καὶ Βακχίδην, καὶ ἐν τοῖς ἐχθραίνουσιν τοῦ ἔθνους ἡμῶν."}, {"sp": "N", "st": "1 Macc 9:30", "t": "νῦν οὖν σε ᾑρετισάμεθα σήμερον τοῦ εἶναι ἀντʼ αὐτοῦ ἡμῖυ εἰς ἄρχοντα καὶ ἡγούμενον, τοῦ πολεμῆσαι τὸν πόλεμον ἡμῶν."}, {"sp": "N", "st": "1 Macc 9:31", "t": "καὶ ἐπεδέξατο Ἰωναθὰν ἐν τῷ καιρῷ ἐκείνῳ τὴν ἥγησιν· καὶ ἀνέστη ἀντὶ Ἰούδου τοῦ ἀδελφοῦ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 9:32", "t": "Καὶ ἔγνω Βακχίδης, καὶ ἐζήτει αὐτὸν ἀποκτεῖναι."}, {"sp": "N", "st": "1 Macc 9:33", "t": "καὶ ἔγνω Ἰωναθὰν καὶ Σίμων ὁ ἀδελφὸς αὐτοῦ καὶ πάντες οἱ μετʼ αὐτοῦ, καὶ ἔφυγον εἰς τὴν ἔρημον Θεκῶε, καὶ παρενέβαλον ἐπὶ τὸ ὕδωρ λάκκου Ἀσφάλ."}, {"sp": "N", "st": "1 Macc 9:34", "t": "καὶ ἔγνω Βακχίδης τῇ ἡμέρᾳ τῶν σαββάτων, καὶ ἧλθεν αὐτὸς καὶ πᾶν τὸ στράτευμα αὐτοῦ πέραν τοῦ Ἰορδάνη."}, {"sp": "N", "st": "1 Macc 9:35", "t": "καὶ ἀπέστειλεν τὸν ἀδελφὸν αὐτοῦ ἡγούμενον τοῦ ὄχλου· καὶ παρεκάλεσεν τοὺς Ναβαταίους φίλους αὐτοῦ παραθέσθαι αὐτοῖς τὴν ἀποσκευὴν αὐτῶν τὴν πολλήν."}, {"sp": "N", "st": "1 Macc 9:36", "t": "καὶ ἐξῆλθον οἱ υἱοὶ Ἰαμβρεὶν ἐκ Μηδαβά, καὶ συνέλαβον Ἰωάννην καὶ πάντα ὅσα εἶχεν, καὶ ἀπῆλθον ἔχοντες."}, {"sp": "N", "st": "1 Macc 9:37", "t": "μετὰ δὲ τοὺς λόγους τούτους ἀπήγγειλαν Ἰωναθὰν καὶ Σίμωνι τῷ ἀδελφῷ αὐτοῦ ὅτι Υὁοὶ Ἰαμβρὶν ποιοῦσιν γάμον μέγαν, καὶ ἄγουσιν τὴν νύμφην ἀπὸ Ναδαβάθ, θυγατέρα ἑνὸς τῶν μεγάλων μεγιστάνων Χανάαν, μετὰ παραπομτπῆς μεγάλης."}, {"sp": "N", "st": "1 Macc 9:38", "t": "καὶ ἐμνήσθησαν Ἰωάννου τοῦ ἀδελφοῦ αὐτῶν, καὶ ἀνέβησαν καὶ ἐκρύβησαν ὑπὸ τὴν σκέπην τοῦ ὄρους."}, {"sp": "N", "st": "1 Macc 9:39", "t": "καὶ ἦραν τοὺς ὀφθαλμοὺς αὐτῶν καὶ ἴδαν, καὶ ἰδοὺ θροῦς καὶ ἀποσκευὴ πολλή, καὶ ὁ νυμφίος ἐξῆλθεν καὶ οἱ φίλοι αὐτοῦ καὶ οἱ ἀδελφοὶ αὐτοῦ εἰς συνάντησιν αὐτῶν μετὰ τυμπάνων καὶ μουσικῶν καὶ ὅπλων πολλῶν."}, {"sp": "N", "st": "1 Macc 9:40", "t": "καὶ ἐξανέστησαν ἐπʼ αὐτοὺς ἀπὸ τοῦ ἐνέδρου καὶ ἀπέκτειναν αὐτοὺς· καὶ ἔπεσαν τραυματίαι πολλοί, καὶ οἱ ἐπίλοιποι ἔφυγον εἰς τὸ ὄρος, καὶ ἔλαβον πάντα τὰ σκεύη αὐτῶν."}, {"sp": "N", "st": "1 Macc 9:41", "t": "καὶ μετεστράφη ὁ γάμος εἰς πένθος, καὶ φωνὴ μουσικῶν αὐτῶν εἰς θρῆνον."}, {"sp": "N", "st": "1 Macc 9:42", "t": "καὶ ἐξεδίκησαν τὴν ἐκδίκησιν αἵματος ἀδελφοῦ αὐτῶν, καὶ ἀπέστρεψαν εἰς τὸ ὄρος τοῦ Ἰορδάνου."}, {"sp": "N", "st": "1 Macc 9:43", "t": "Καὶ ἤκουσεν Βακχίδης, καὶ ἦλθεν τῇ ἡμέρᾳ τῶν σαβββάτων ἕως τῶ, κρηπίδων τοῦ Ἰορδάνου ἐν δυνάμει πολλῇ."}, {"sp": "N", "st": "1 Macc 9:44", "t": "καὶ εἶπεν Ἰωναθὰν τοῖς ἀδελφοῖς αὐτοῦ Ἀναστῶμεν νῦν καὶ πολεμήσωμεν ὑπὲρ τῶν ψυχῶν ἡμῶν· οὐ γάρ ἐστιν σήμερον ὡς ἐχθὲς καὶ τρίτην ἡμέραν."}, {"sp": "N", "st": "1 Macc 9:45", "t": "ἰδοὺ γὰρ ὁ πόλεμος ἐξ ἐναντίας ἡμῶν καὶ ἐξόπισθεν ἡμῶν· τὸ δὲ ὕδωρ τοῦ Ἰορδάνου ἔνθεν καὶ ἔνθεν καὶ ἕλος καὶ δρυμός. καὶ οὐκ ἔστιν τόπος τοῦ ἐκκλῖναι."}, {"sp": "N", "st": "1 Macc 9:46", "t": "νῦν οὖν κεκράξατε εἰς οὐρανόν, ὅπως διασωθῆτε ἐκ χειρὸς ἐχθρῶν ἡμῶν."}, {"sp": "N", "st": "1 Macc 9:47", "t": "καὶ συνῆψεν ὁ πόλεμος· καὶ ἐξέτεινεν Ἰωναθὰν τὴν χεῖρα αὐτοῦ πατάξαι τὸν Βακχίδην, καὶ ἐξέκλινεν ἀπʼ αὐτοῦ εἰς τὰ ὀπίσω."}, {"sp": "N", "st": "1 Macc 9:48", "t": "καὶ ἐνεπήδησεν Ἰωναθὰν καὶ οἱ μετʼ αὐτοῦ εἰς τὸν Ἰορδάνην, καὶ διεκολύμβησαν εἰς τὸ πέραν· καὶ οὐ διέβησαν ἐπʼ αὐτοὺς τὸν Ἰορδάνην."}, {"sp": "N", "st": "1 Macc 9:49", "t": "καὶ διέπεσαν παρὰ Βακχίδα τῇ ἡμέρᾳ ἐκείνῃ εἰς χιλίους ἄνδρας."}, {"sp": "N", "st": "1 Macc 9:50", "t": "Καὶ ἀπέστρεψαν εἰς Ἰερουσαλήμ, καὶ ᾠκοδόμησαν πόλεις ἀχυρὰς ἐν τῇ Ἰουδαία, τὸ ὀχύρωμα τὸ ἐν Ἰεριχὼ καὶ τὴν Ἐμμαοὺμ καὶ τὴν Βεθωρὼν καὶ τὴν Βεθὴλ καὶ τὴν Θαμνάθα Φαραθὼν καὶ τὴν Τεφών, ἐν τείχεσιν ὑψηλοῖς καὶ πύλαις καὶ μοχλοῖς."}, {"sp": "N", "st": "1 Macc 9:51", "t": "καὶ ἔθεντο φρουρὰν ἐν αὐτοῖς τοῦ ἐχθραίνειν τῷ Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 9:52", "t": "καὶ ὠχύρωσαν τὴν πόλιν καὶ Βεθσούραν καὶ Γαζάραν καὶ τὴν ἄκραν, καὶ ἔθεντο ἐν αὐταῖς δυνάμεις καὶ παραθέσεις βραωμάτων."}, {"sp": "N", "st": "1 Macc 9:53", "t": "καὶ ἔλαβον τοὺς υἱοὺς τῶν ἡγουμένων τῆς χώρας ὅμηρα, καὶ ἔθεντο αὐτοὺς ἐν τῇ ἄκρᾳ ἐν Ἰερουσαλὴμ ἐν φυλακῆ."}, {"sp": "N", "st": "1 Macc 9:54", "t": "Καὶ ἐν ἔτει τρίτῳ καὶ πεντηκοστῷ καὶ ἑκατοστῷ, τῷ μηνὶ τῷ δευτέρῳ, ἐπέταξεν Ἄλκιμος καθαιρεῖν τὸ τεῖχος τῆς αὐλῆς τῶν ἁγίων τῆς ἐσωτέρας, καὶ καθεῖλεν τὰ ἔργα τῶν προφητῶν, καὶ ἐνήρξατο τοῦ καθαιρεῖν."}, {"sp": "N", "st": "1 Macc 9:55", "t": "ἐν τῷ καιρῷ ἐκείνῳ ἐπλήγη Ἄλκιμος, καὶ ἐνεποδίσθη τὰ ἔργα αὐτοῦ, καὶ ἀπεφράγη τὸ στόμα αὐτοῦ, καὶ παρελύθη, καὶ οὐκ ἠδύνατο ἔτι λαλῆσαι λόγον καὶ ἐντείλασθαι περὶ τοῦ οἴκου αὐτοῦ."}, {"sp": "N", "st": "1 Macc 9:56", "t": "καὶ ἀπέθανεν Ἄλκιμος ἐν τῷ καιρῷ ἐκείνῃ μετὰ βασάνου μεγάλης."}, {"sp": "N", "st": "1 Macc 9:57", "t": "καὶ ἴδεν Βακχίδης ὅτι ἀπέθανεν Ἄλκιμος, καὶ ἀπέστρεψεν πρὸς τὸν βασιλέα, καὶ ἡσύχασεν ἡ γῆ Ἰούδα ἔτη δύο."}, {"sp": "N", "st": "1 Macc 9:58", "t": "Καὶ ἐβουλεύσαντο οἱ ἄνομοι πάντες λύγοντες Ἰδοὺ Ἰωναθὰν καὶ οἱ παρʼ αὐτοῦ ἐν ἡσυχίᾳ κατοικοῦσιν πεποιθότες· νῦν οὖν ἄξομεν τὸν Βακχίδην, καὶ συλλήμψεται αὐτοὺς πάντας ἐν νυκτὶ μιᾷ."}, {"sp": "N", "st": "1 Macc 9:59", "t": "καὶ πορευθέντες συνεβουλεύσαντο αὐτῷ."}, {"sp": "N", "st": "1 Macc 9:60", "t": "καὶ ἀπῆρεν τοῦ ἐλθεῖν μετὰ δυνάμεως πολλῆς, καὶ ἀπέστειλεν ἐπιστολὰς λάθρα πᾶσι τοῖς συμμάχοις αὐτοῦ τοῖς ἐν τῇ Ἰουδαία, ὅπως συλλάββωσιν τὸν Ἰωναθὰν καὶ τοὺς σὺν αὐτῷ· καὶ οὐκ ἠδύνατο, ὅτι ἐγνώσθη αὐτοῖς ἡ βουλὴ αὐτῶν."}, {"sp": "N", "st": "1 Macc 9:61", "t": "καὶ συνέλαβον ἀπὸ τῶν ἀνδρῶν τῆς χώρας τῶν ἀρχηγῶν τῆς κακίας εἰς πεντήκοντα ἄνδρας, καὶ ἀπέκτεινεν αὐτούς."}, {"sp": "N", "st": "1 Macc 9:62", "t": "καὶ ἐξεχώρησεν Ἰωναθὰν καὶ Σίμων καὶ οἱ μετʼ αὐτοῦ εἰς Βεθβασὶ τὴν ἐν τῇ ἐρήμῳ, καὶ ᾠκοδόμησεν τὰ καθῃρημένα αὐτῆς, καὶ ἐστερέωσεν αὐτήν."}, {"sp": "N", "st": "1 Macc 9:63", "t": "καὶ ἔγνω Βακχίδης καὶ συνήγαγεν πᾶν τὸ πλῆθος αὐτοῦ, καὶ τοῖς ἐκ τῆς Ἰουδαίας παρήγγειλεν."}, {"sp": "N", "st": "1 Macc 9:64", "t": "καὶ ἐλθὼν παρενέβαλεν ἐπὶ Βεθβασί, καὶ ἐπολέμησεν αὐτὴν ἡμέρας πολλὰς καὶ ἐποίησεν μηχανάς."}, {"sp": "N", "st": "1 Macc 9:65", "t": "καὶ ἀπέλειπεν Ἰωναθὰν Σίμωνα τὸν ἀδελφὸν αὐτοῦ ἐν τῇ πόλει, καὶ ἐξῆλθεν εἰς τὴν χώραν. καὶ ἦλθεν ἀριθμῷ."}, {"sp": "N", "st": "1 Macc 9:66", "t": "καὶ ἐπάταξεν Ὀδομηρὰ καὶ τοὺς ἀδελφοὺς αὐτοῦ καὶ τοὺς υἱοὺς Φασιρὼν ἐν τῷ σκηνώματι αὐτῶν, καὶ ἐξήρξατο τύπτειν καὶ ἀναβαίνειν ἐν ταῖς δυνάμεσιν."}, {"sp": "N", "st": "1 Macc 9:67", "t": "καὶ Σίμων καὶ οἱ μετʼ αὐτοῦ ἐξῆλθον ἐκ τῆς πόλεως, καὶ ἐνεπύρισαν τὰς μηχανάς."}, {"sp": "N", "st": "1 Macc 9:68", "t": "καὶ ἐπολέμησαν πρὸς τὸν Βακχίδην, καὶ συνετρίβη ὑπʼ αὐτῶν, καὶ ἔθλιββον αὐτὸν σφόδρα, ὅτι ἦν ἡ βουλὴ αὐτοῦ καὶ ἡ ἔφοδος αὐτοῦ κενή."}, {"sp": "N", "st": "1 Macc 9:69", "t": "καὶ ὠργίσθησαν θυμῷ τοῖς ἀνδράσιν τοῖς ἀνόμοις τοῖς συμβουλεύσασιν αὐτῷ ἐλθεῖν εἰς τὴν χώραν, καὶ ἀπέκτειναν ἐξ αὐτῶν πολλούς, καὶ ἐβουλεύσατο τοῦ ἀπελθεῖν εἰς τὴν γῆν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 9:70", "t": "καὶ ἐπέγνω Ἰωναθάν, καὶ ἀπέστειλεν πρὸς αὐτὸν πρέσβεις, τοῦ συνθέσθαι πρὸς αὐτὸν εἰρήνην καὶ ἀποδοῦναι αὐτοῖς τὴν αἰχμαλωσίαν."}, {"sp": "N", "st": "1 Macc 9:71", "t": "καὶ ἀπεδέξατο, καὶ ἐποίησεν κατὰ τοὺς λόγους αὐτοῦ, καὶ ὤμοσεν αὐτῷ μὴ ἐκζητῆσαι αὐτῷ κακὸν πάσας τὰς ἡμέρας τῆς ζωῆς αὐτοῦ."}, {"sp": "N", "st": "1 Macc 9:72", "t": "καὶ ἀπέδωκεν αὐτῷ τὴν αἰχμαλωσίαν ἣν ᾐχμαλώτευσεν τὸ πρότερον ἐκ γῆς Ἰούδα· καὶ ἀποστρέψας ἀπῆλθεν εἰς τὴν γῆν αὐτοῦ, καὶ οὐ προσέθετο ἔτι ἐλθεῖν εἰς τὰ ὅρια αὐτῶν."}, {"sp": "N", "st": "1 Macc 9:73", "t": "καὶ κατέπαυσεν ῥομφαία ἐξ Ἰσραήλ, καὶ ᾤκησεν Ἰωναθὰν ἐν Μαχμάς· καὶ ἤρξατο Ἰωναθὰν κρίνειν τὸν λαὸν καὶ ἠφάνισεν τοὺς ἀσεβεῖς ἐξ Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 10:1", "t": "Καὶ ἐν ἔτει ἑξηκοστῷ καὶ ἑκατοστῷ ἀνέβη Ἀλέξανδρος ὁ τοῦ Ἀντιόχου ὁ Ἐπιφανής, καὶ κατελάβετο Πτολεμαίδα, καὶ ἐπεδέξαντο αὐτὸν καὶ ἐβασίλευσεν ἐκεῖ"}, {"sp": "N", "st": "1 Macc 10:2", "t": "καὶ ἤκουσεν Δημήτριος ὁ βασιλεύς, καὶ συνήγαγεν δυνάμεις πολλὰς σφόδρα, καὶ ἐξῆλθεν εἰς συνάντησιν αὐτῷ εἰς πόλεμον."}, {"sp": "N", "st": "1 Macc 10:3", "t": "καὶ ἀπέστειλεν πρὸς Ἰωναθὰν ἐπιστολὰς Δημήτριος λόγοις εἰρηνικοῖς, ὥστε μεγαλῦναι αὐτόν,"}, {"sp": "N", "st": "1 Macc 10:4", "t": "εἶπεν γάρ Προφθάσωμεν τοῦ εἰρήνην θεῖναι μετʼ αὐτῶν, πρὶν ἢ θεῖναι αὐτὸν μετὰ Ἀλεξάνδρου καθʼ ἡμῶν."}, {"sp": "N", "st": "1 Macc 10:5", "t": "μνησθήσεται γὰρ πάντων τῶν κακῶν ὧν συνετελέσαμεν πρὸς αὐτόν, καὶ εἰς τοὺς ἀδελφοὺς αὐτοῦ καὶ εἰς τὸ ἔθνος αὐτοῦ."}, {"sp": "N", "st": "1 Macc 10:6", "t": "καὶ ἔδωκεν αὐτῷ ἐξουσίαν συναγαγεῖν δυνάμεις, καὶ κατασκευάζειν ὅπλα, καὶ εἶναι αὐτὸν σύμμαχον αὐτοῦ, καὶ τὰ ὅμηρα τὰ ἐν τῇ ἄκρᾳ εἶπεν παραδοῦναι αὐτῷ."}, {"sp": "N", "st": "1 Macc 10:7", "t": "Καὶ ἦλθεν Ἰωναθὰν ἐν Ἰερουσαλήμ, καὶ ἀνέγνω τὰς ἐπιστολὰς εἰς τὰ ὦτα παντὸς τοῦ λαοῦ καὶ τῶν ἐκ τῆς ἄκρας."}, {"sp": "N", "st": "1 Macc 10:8", "t": "καὶ ἐφοβήθησαν φόβον μέγαν, ὅτε ἤκουσαν ὅτι ἔδωκεν αὐτοῖς ὁ βασιλεὺς ἐξουσίαν συναγαγεῖν δυνάμεις."}, {"sp": "N", "st": "1 Macc 10:9", "t": "καὶ παρέδωκαν οἱ ἐκ τῆς ἄκρας Ἰωναθὰν τὰ ὅμηρα, καὶ ἀπέδωκαν αὐτοὺς τοῖς γονεῦσιν αὐτῶν."}, {"sp": "N", "st": "1 Macc 10:10", "t": "καὶ ᾤκησεν Ἰωναθὰν ἐν Ἰερουσαλήμ, καὶ ἤρξατο οἰκοδομεῖν καὶ καινίζειν τὴν πόλιν."}, {"sp": "N", "st": "1 Macc 10:11", "t": "καὶ εἶπεν πρὸς τοὺς ποιοῦντας τὰ ἔργα οἰκοδομεῖν τὰ τείχη καὶ τὸ ὄρος Σιὼν κυκλόθεν ἐκ λίθων τετραγώνων εἰς ὀχύρωσιν, καὶ ἐποίησαν οὕτως."}, {"sp": "N", "st": "1 Macc 10:12", "t": "καὶ ἔφυγον οἱ ἀλλογενεῖς οἱ ὄντες ἐν τοῖς ὀχυρώμασιν οἷς οἰκοδόμησεν ὁ Βακχίδης."}, {"sp": "N", "st": "1 Macc 10:13", "t": "καὶ κατέλειπεν ἕκαστος τὸν τόπον αὐτοῦ, καὶ ἀπῆλθεν εἰς τὴν γῆν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 10:14", "t": "πλὴν ἐν Βεθσούροις ὑπελείφθησάν τινες τῶν καταλειπόντων τὸν νόμον καὶ τὰ προστάγματα· ἦν γὰρ αὐτοῖς φυγαδευτήριον."}, {"sp": "N", "st": "1 Macc 10:15", "t": "Καὶ ἤκουσεν ὁ βασιλεὺς Ἀλέξανδρος τὰς ἐπαγγελίας ὅσας ἀπέστειλεν Δημήτριος τῷ Ἰωναθάν, καὶ διηγήσαντο αὐτῷ τοὺς πολέμους καὶ τὰς ἀνδραγαθίας ἂς ἐποίησεν αὐτὸς καὶ οἱ ἀδελφοὶ αὐτοῦ, καὶ τοὺς κόπους οὓς ἔσχοσαν."}, {"sp": "N", "st": "1 Macc 10:16", "t": "καὶ εἶπεν Μὴ εὑρήσομεν ἄνδρα τοιοῦτον ἕνα; καὶ νῦν ποιήσαωμεν αὐτὸν φίλον καὶ σύμμαχον ἡμῶν."}, {"sp": "N", "st": "1 Macc 10:17", "t": "καὶ ἔγραψεν ἐπιστολὰς καὶ ἀπέστειλεν αὐτῷ κατὰ τοὺς λόγους τούτους λέγων"}, {"sp": "N", "st": "1 Macc 10:18", "t": "Βασιλεὺς Ἀλέξανδρος τῷ ἀδελφῷ Ἰωναθὰν χαίρειν."}, {"sp": "N", "st": "1 Macc 10:19", "t": "ἀκηκόαμεν περὶ σοῦ, ὅτι ἀνὴρ ἀγαθὸς ἰσχύι καὶ ἐπιτήδειος εἶ τοῦ εἶναι ἡμῶν φίλος."}, {"sp": "N", "st": "1 Macc 10:20", "t": "καὶ νῦν καθεστάκαμέν σε σήμερον ἀρχιερέα τοῦ ἔθνους σου, καὶ φίλον βασιλέως καλεῖσθαι— καὶ ἀπέστειλαν αὐτῷ πορφύραν καὶ στέφανον χρυσοῦν—καὶ φρονεῖν τὰ ἡμῶν καὶ συντηρεῖν φιλίαν πρὸς ἡμᾶς."}, {"sp": "N", "st": "1 Macc 10:21", "t": "καὶ ἐνεδύσατο Ἰωναθὰν τὴν ἁγίαν στολὴν τῷ ἑβδόμῳ μηνὶ ἔτους ἐξηκοστοῦ καὶ ἑκατοστοῦ ἐν ἑορτῇ σκηνοπηγίας, καὶ συνήγαγεν δυνάμεις, καὶ κατεσκεύασεν ὅπλα πολλά."}, {"sp": "N", "st": "1 Macc 10:22", "t": "Καὶ ἤκουσεν Δημήτριος τοὺς λόγους τούτους, καὶ. ἐλυπήθη, καὶ εἶπεν"}, {"sp": "N", "st": "1 Macc 10:23", "t": "Τί τοῦτο ἐποιήσαμεν, ὅτι προέφθακεν ἡμᾶς ὁ Ἀλέξανδρος τοῦ φιλίαν καταλαβέσθαι τοῖς Ἰουδαίοις εἰς στήριύμας"}, {"sp": "N", "st": "1 Macc 10:24", "t": "γράψω κἀγὼ αὐτοῖς λόγους παρακλήσεως καὶ ὕψους καὶ δομάτων, ὅπως ὦσιν σὺν ἐμοὶ εἰς βοήθειαν."}, {"sp": "N", "st": "1 Macc 10:25", "t": "καὶ ἀπέστειλεν αὐτοῖς κατὰ τοὺς λόγους τούτους Βασιλεὺς Δημήτριος τῷ ἔθνει τῶν Ἰουδαίων χαίρειν."}, {"sp": "N", "st": "1 Macc 10:26", "t": "ἐπεὶ συνετηρήσατε τὰς πρὸς ἡμᾶς συνθήκας καὶ ἐνεμείνατε τῇ φιλίᾳ ἡμῶν καὶ οὐ προσεχωρήσατε τοῖς ἐχθροῖς ἡμῶν, ἠκούσαμεν καὶ ἐχάρημεν."}, {"sp": "N", "st": "1 Macc 10:27", "t": "καὶ νῦν ἐνμείνατε ἔτι τοῦ συντηρῆσαι πρὸς ἡμᾶς πίστιν, καὶ ἀνταποδώσομεν ὑμῖν ἀγαθὰ ἀνθʼ ὦν ποιεῖτε μεθʼ ἡμῶν."}, {"sp": "N", "st": "1 Macc 10:28", "t": "καὶ ἀφήσομεν ὑμῖν ἀφέματα πολλά, καὶ δώσομεν ὑμῖν δόματα."}, {"sp": "N", "st": "1 Macc 10:29", "t": "καὶ νῦν ἀπολύω ὑμᾶς καὶ ἀφίημι πάντας τοὺς Ἰουδαίους ἀπὸ τῶν φόρων καὶ τῆς τιμῆς τοῦ ἁλός, καὶ ἀπὸ τῶν στεφάνων·"}, {"sp": "N", "st": "1 Macc 10:30", "t": "καὶ ἀντὶ τοῦ τρίτου τῆς σπορᾶς, καὶ ἀντὶ τοῦ ἡμίσους τοῦ καρποῦ τοῦ ξυλίνου τοῦ ἐπιβάλλοντός μοι λαβεῖν, ἀφίημι ἀπὸ τῆς σήμερον καὶ ἐπέκεινα, τοῦ λαβεῖν ἀπὸ τῆς γῆς Ἰούδα, καὶ ἀπὸ τῶν τριῶν νομῶν τῶν προστιθεμένων αὐτῇ ἀπὸ τῆς Σαμαρίτιδος καὶ Γαλιλαίας, ἀπὸ τῆς σήμερον ἡμέρας καὶ εἰς τὸν ἅπαντα χρόνον."}, {"sp": "N", "st": "1 Macc 10:31", "t": "καὶ Ἰερουσαλὴμ ἤτω ἁγία καὶ ἀφιεμένη καὶ τὰ ὅρία αὐτῆς, αἱ δεκάται καὶ τὰ τέλη."}, {"sp": "N", "st": "1 Macc 10:32", "t": "ἀφίημι καὶ τὴν ἐξουσίαν τῆς ἄκρας τῆς ἐν Ἰερουσαλήμ, καὶ δίδωμι τῷ ἀρχιερεῖ ὅπως ἂν καταστῇ ἐν αὐτῇ ἄνδρας, οὓς ἂν ἐκλέξηται αὐτός, τοῦ φυλάσσειν αὐτήν."}, {"sp": "N", "st": "1 Macc 10:33", "t": "καὶ πᾶσαν ψυχὴν Ἰουδαίων τὴν αἰχμαλωτισθεῖσαν ἀπὸ γῆς Ἰούδα εἰς πᾶσαν βασιλείαν μου ἀφίημι ἐλευθέραν δωρεάν· καὶ πάντες ἀφιέτωσαν τοὺς φόρους καὶ κτηνῶν αὐτῶν."}, {"sp": "N", "st": "1 Macc 10:34", "t": "καὶ πᾶσαι αἱ ἑορταὶ καὶ τὰ σάββατα καὶ νουμηνίαι καὶ ἡμέραι ἀποδεδιγμέναι, καὶ τρεῖς ἡμέραι πρὸ ἑορτῆς καὶ τρεῖς ἡμέραι μετὰ ἑορτήν, ἔστωσαν πᾶσαι αἱ ἡμέραι ἀτελείας καὶ ἀφέσεως πᾶσι τοῖς Ἰουδαίοις τοῖς οὖσιν ἐν πάσῃ τῇ βασιλείᾳ μου."}, {"sp": "N", "st": "1 Macc 10:35", "t": "καὶ οὐχ ἕξει ἐξουσίαν οὐδεὶς πράσσειν καὶ παρενοχλεῖν τινα αὐτῶν περὶ παντὸς πράγματος."}, {"sp": "N", "st": "1 Macc 10:36", "t": "καὶ προγραφήτωσαν τῶν Ἰουδαίων εἰς τὰς δυνάμεις τοῦ βασιλέως εἰς τριάκοντα χιλιάδας ἀνδρῶν, καὶ δοθήσεται αὐτοῖς ξένιά, ὡς καθήκει πάσαις ταῖς δυνάμεσιν τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 10:37", "t": "καὶ κατασταθήσεται ἐξ αὐτῶν ἐν τοῖς ὀχυρώμασιν τοῦ βασιλέως τοῖς μεγάλοις, καὶ ἐκ τούτων κατασταθήσεται ἐπὶ χρειῶν τῆς βασιλείας τῶν οὐσῶν εἰς πίστιν· καὶ οἱ ἐπʼ αὐτῶν καὶ οἱ ἄρχοντες ἐξ αὐτῶν ἔστωσαν, καὶ πορευέσθωσαν τοῖς νόμοις αὐτῶν, καθὰ καὶ προσέταξεν ὁ βασιλεὺς ἐν γῇ Ἰούδα."}, {"sp": "N", "st": "1 Macc 10:38", "t": "καὶ τοὺς τρεῖς νομοὺς τοὺς προστεθέντας τῇ Ἰουδαίὰ ἀπὸ τῆς χώρας Σαμαρίας, προστεθήτω τῇ Ἰουδαίᾳ πρὸς τὸ λογισθῆναι τοῦ γενέσθαι ὑφʼ ἕνα, τοῦ μὴ ὑπακοῦσαι ἄλλης ἐξουσίας ἀλλ᾿ ἢ τοῦ ἀρχιερέως."}, {"sp": "N", "st": "1 Macc 10:39", "t": "Πτολεμαίδα καὶ τὴν προσκυροῦσαν αὐτῇ δέδωκα δόμα τοῖς ἁγίοις τοῖς ἐν Ἰερουσαλὴμ εἰς τὴν προκαθήκουσαν δαπάνην τοῖς ἁγίοις."}, {"sp": "N", "st": "1 Macc 10:40", "t": "κἀγὼ δίδωμι κατʼ ἐνιαυτὸν δέκα πέντε χιλιάδας σίκλων ἀργυρίου| ἀπὸ τῶν λόγων τοῦ βασιλέως, ἀπὸ τῶν τόπων τῶν ἀνηκόντων."}, {"sp": "N", "st": "1 Macc 10:41", "t": "καὶ πᾶν τὸ πλεονάζον ὃ οὐκ ἀπεδίδοσαν ἀπὸ τῶν χρειῶν, ὡς ἐν τοῖς πρώτοις ἔτεσιν, ἀπὸ τοῦ νῦν δώσωσιν εἰς τὰ ἔργα τοῦ οἴκου."}, {"sp": "N", "st": "1 Macc 10:42", "t": "καὶ ἐπὶ τούτοις πεντακισχιλίους σίκλους ἀργυρίου οὓς ἐλάμβανον ἀπὸ τῶν χρειῶν, ὡς ἐν τοῖς πρώτοις ἔτεσιν, τοῦ ἁγίου ἀπὸ τοῦ λόγου κατʼ ἐνιαυτόν, καὶ ταῦτα ἀφίεται, διὰ τὸ ἀνήκειν αὐτὰ τοῖς ἱερεῦσιν τοῖς λειτουργοῦσιν."}, {"sp": "N", "st": "1 Macc 10:43", "t": "καὶ ὅσοι ἐὰν φύγωσιν εἰς τὸ ἱερὸν τὸ ἐν Ἰεροσολύμοις καὶ ἐν πᾶσιν τοῖς ὁρίοις αὐτοῦ, ὀφίλων βασιλικὰ καὶ πᾶν πρᾶγμα, ἀπολελύσθωσαν, καὶ πάντα ὅσα ἐστὶν αὐτοῖς ἐν τῇ βασιλείᾳ μου."}, {"sp": "N", "st": "1 Macc 10:44", "t": "καὶ τοῦ οἰκοδομηθῆναι καὶ τοῦ ἐπικαινισθῆναι τὰ ἔργα τῶν ἁγἰων, καὶ ἠ δαπάνη δοθήσεται ἐκ τοῦ λόγου τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 10:45", "t": "καὶ τοῦ οἰκοδομηθῆναι τὰ τείχη Ἰερουσαλήμ, καὶ ὀχυρῶσαι κυκλόθεν, καὶ ἡ δαπάνη δοθήσεται ἐκ τοῦ λόγου τοῦ βασιλέως, καὶ τοῦ οἰκοδομῆσαι τὰ τείχη ἐν τῇ Ἰουδαίᾳ."}, {"sp": "N", "st": "1 Macc 10:46", "t": "Ὡς δὲ ἤκουσεν Ἰωναθὰν καὶ ὁ λαὸς τοὺς λόγους τούτους, οὐκ ἐπίστευσεν αὐτοῖς οὐδὲ ἐπεδέξαντο, ὅτι ἐπεμνήσθησαν τῆς κακίας τῆς μεγάλης ἧς ἐποίησεν ἐν Ἰσραήλ, καὶ ἔθλιψεν αὐτοὺς σφόδρα."}, {"sp": "N", "st": "1 Macc 10:47", "t": "καὶ εὐδόκησαν ἐν Ἀλεξάνδρῳ, ὅτι αὐτὸς ἐγένετο αὐτοῖς ἀρχηγὸς λόγων εἰρηνικῶν, καὶ συνεμάχουν αὐτῷ πάσας τὰς ἡμέρας."}, {"sp": "N", "st": "1 Macc 10:48", "t": "καὶ συνήγαγεν Ἀλέξανδρος ὁ βασιλεὺς δυνάμεις μεγάλας, καὶ παρενέβαλεν ἐξ ἐναντίας Δημητρίου."}, {"sp": "N", "st": "1 Macc 10:49", "t": "καὶ συνῆψαν πόλεμον οἱ δύο βασιλεῖς, καὶ ἔφυγεν ἡ παρεμβολὴ Δημητρίου, καὶ ἐδίωξεν αὐτὸν ὁ Ἀλέξανδρος, καὶ ἴσχυσεν ἐπʼ αὐτούς."}, {"sp": "N", "st": "1 Macc 10:50", "t": "καὶ ἐστερέωσεν πόλεμον σφόδρα ἕως ἔδυ ὁ ἥλιος, καὶ ἔπεσεν ὁ Δημήτριος ἐν τῇ ἡμέρᾳ ἐκείνῃ."}, {"sp": "N", "st": "1 Macc 10:51", "t": "Καὶ ἀπέστειλεν Ἀλέξανδρος πρὸς Πτολεμαῖον βασιλέα Αἰγύπτου πρέσβεις κατὰ τοὺς λόγους τούτους λέγων"}, {"sp": "N", "st": "1 Macc 10:52", "t": "Ἐπεὶ ἀνέστρεψα εἰς τὴν βασιλείαν μου καὶ ἐκάθισα ἐπὶ θρόνου πατέρων μου καὶ ἐκράτησα τῆς ἀρχῆς, καὶ συνέτριψα τὸν Δημήτριον καὶ ἐπεκράτησα τῆς χώρας ἡμῶν·"}, {"sp": "N", "st": "1 Macc 10:53", "t": "καὶ συνῆψα πρὸς αὐτὸν μάχην, καὶ συνετρίβη αὐτὸς καὶ ἡ παρεμβολὴ αὐτοῦ ὑφʼ ἡμῶν, καὶ ἐκαθίσαμεν ἐπὶ θρόνου βασιλείας αὐτοῦ·"}, {"sp": "N", "st": "1 Macc 10:54", "t": "καὶ συνστήσωμεν πρὸς αὐτὸν φιλίαν· καὶ νῦν δός μοι τὴν θυγατέρα σου εἰς γυναῖκα, καὶ ἐπιγαμβρεύσω σοι, καὶ δώσω σοι δόματα καὶ αὐτῇ ἄξιά σου."}, {"sp": "N", "st": "1 Macc 10:55", "t": "καὶ ἀπεκρίθη Πτολεμαῖος ὁ βασιλεὺς λέγων Ἀγαθὴ ἡμέρα, ἐν ᾗ ἀνέστρεψας εἰς γῆν πατέρων σου, καὶ ἐκάθισας ἐπὶ θρόνου βασιλείας αὐτῶν."}, {"sp": "N", "st": "1 Macc 10:56", "t": "καὶ νῦν ποιήσω σοι ἃ ἔγραψας· ἀλλὰ ἀπάντησον εἰς Πτολεμαίδα, ὅπως ἴδωμεν ἀλλήλους, καὶ ἐπιγαμβρεύσω σοι καθὼς εἴρηκας."}, {"sp": "N", "st": "1 Macc 10:57", "t": "καὶ ἐξῆλθεν Πτολεμαῖος ἐξ Αἰγύπτου αὐτὸς καὶ Κλεοπάτρα ἡ θυγάτηρ αὐτοῦ, καὶ ἦλθεν εἰς Πτολεμαίδα ἔτους δευτέρου καὶ ἑξηκοστοῦ καὶ ἑκατοστοῦ."}, {"sp": "N", "st": "1 Macc 10:58", "t": "καὶ ἀπήντησεν αὐτῷ Ἀλέξανδρος ὁ βασιλεύς, καὶ ἐξέδετο αὐτῷ Κλεοπάτραν τὴν θυγατέρα αὐτοῦ, καὶ ἐποίησεν τὸν γάμον αὐτῆς ἐν Πτολεμαίδι, καθὼς οἱ βασιλεῖς, ἐν δόξῃ μεγάλῃ."}, {"sp": "N", "st": "1 Macc 10:59", "t": "Καὶ ἔγραψεν ὁ βασιλεὺς Ἀλέξανδρος Ἰωνάθῃ ἐλθεῖν εἰς συνάντησιν αὐτῷ."}, {"sp": "N", "st": "1 Macc 10:60", "t": "καὶ ἐπορεύθη μετὰ δόξης εἰς Πτολεμαίδα, καὶ ἀπήντησεν τοῖς δυσὶν βασιλεῦσιν· καὶ ἔδωκεν αὐτοῖς ἀργύριον καὶ χρυσίον καὶ τοῖς φίλοις αὐτῶν καὶ δόματα πολλά, καὶ εὗρεν χάριν ἐναντίον αὐτῶν."}, {"sp": "N", "st": "1 Macc 10:61", "t": "καὶ συνήχθησαν ἐπʼ αὐτὸν ἄνδρες λοιμοὶ ἐξ Ἰσραήλ, ἄνδρες παράνομοι, ἐντυχεῖν κατʼ αὐτοῦ· καὶ οὐ προσέσχεν αὐτοῖς ὁ βασιλεύς"}, {"sp": "N", "st": "1 Macc 10:62", "t": "καὶ προσέταξεν αὐτοῖς ὁ βασιλεύς, καὶ ἐξέδυσεν Ἰωναθὰν τὰ ἱμάτια αὐτοῦ, καὶ ἐνέδυσεν αὐτὸν πορφύραν· καὶ ἐποίησαν οὕτως."}, {"sp": "N", "st": "1 Macc 10:63", "t": "καὶ ἐκάθισεν αὐτὸν ὁ βασιλεὺς μετʼ αὐτοῦ, καὶ εἶπεν τοῖς ἄρχουσιν αὐτοῦ Ἐξέλθατε μετʼ αὐτοῦ εἰς μέσον τῆς πόλεως, καὶ κηρύξατε τοῦ μηδένα ἐντυγχάνειν κατὰ τούτου περὶ μηδενὸς πράγματος. καὶ μηδεὶς αὐτῷ ἐνοχλείτω περὶ παντὸς λόγου."}, {"sp": "N", "st": "1 Macc 10:64", "t": "καὶ ἐγένετο ὡς εἶδον οἱ ἐντυγχάνοντες τὴν δόξαν αὐτοῦ καθὼς ἐκήρυξεν, καὶ περιβεβλημένον αὐτὸν σινδόνα, καὶ ἔφυγον πάντες."}, {"sp": "N", "st": "1 Macc 10:65", "t": "καὶ ἐδόξασεν αὐτὸν ὁ βασιλεύς, καὶ ἔγραψεν αὐτὸν τῶν πρώτων φίλων, καὶ ἔθετο αὐτὸν στρατηγὸν καὶ μεριδάρχην."}, {"sp": "N", "st": "1 Macc 10:66", "t": "καὶ ἐπέστρεψεν Ἰωναθὰν εἰς Ἰερουσαλὴμ μετ εἰρήνης καὶ εὐφροσύνης."}, {"sp": "N", "st": "1 Macc 10:67", "t": "Καὶ ἐν ἔτει πέμπτῳ καὶ ἑξηκοστῷ καὶ ἑκατοστῷ ἦλθεν Δημήτριος ὁ υἱὸς Δημητρίου ἐκ Κρήτης εἰς τὴν γῆν τῶν πατέρων αὐτοῦ."}, {"sp": "N", "st": "1 Macc 10:68", "t": "καὶ ἤκουσεν Ἀλέξανδρος ὁ βασιλεύς, καὶ ἐλυπήθη σφόδρα, καὶ ἀπέστρεψεν εἰς Ἀντιοχίαν."}, {"sp": "N", "st": "1 Macc 10:69", "t": "καὶ κατέστησεν Δημήτριος Ἀπολλώνιον τὸν ὄντα ἐπὶ Κοίλης Συρίας, καὶ συνήγαγεν δύναμιν μεγάλην, καὶ παρενέβαλεν ἐν Ἰάμνείᾳ· καὶ ἀπέστειλεν πρὸς Ἰωναθὰν τὸν ἀρχιερέα, λέγων"}, {"sp": "N", "st": "1 Macc 10:70", "t": "Σὺ μονώτατος ἐπαίρῃ ἐφʼ ἡμᾶς, ἐγὼ δὲ ἐγενήθην εἰς καταγέλωτα καὶ ὀνειδισμὸν διὰ σέ· καὶ διὰ τί ἐξουσιάζῃ ἐφʼ ἡμᾶς ἐν τοῖς ὄρεσιν"}, {"sp": "N", "st": "1 Macc 10:71", "t": "νῦν οὖν εἰ πέποιθας ἐπὶ ταῖς δυνάμεσίν σου, κατάβηθι πρὸς ἡμᾶς εἰς τὸ πεδίον, καὶ συνκριθώμεν ἑαυτοῖς ἐκεῖ, ὅτι μετʼ ἐμοῦ ἐστιν δύναμις τῶν πόλεων."}, {"sp": "N", "st": "1 Macc 10:72", "t": "ἐρώτησον καὶ μάθε τίς εἰμι καὶ οἱ λοιποὶ οἱ βοηθοῦντες ἡμῖν· καὶ λέγουσιν Οὐκ ἔστιν ὑμῖν στάσις ποδὸς κατὰ πρόσωπον ημῶν, ὅτι δὶς ἐτροπώθησαν οἱ πατέρες σου ἐν τῇ γῇ αὐτῶν."}, {"sp": "N", "st": "1 Macc 10:73", "t": "καὶ νῦν οὐ δυνήσῃ ὑποστῆναι τὴν ἵππον καὶ δύναμιν τοιαύτην ἐν τῷ πεδίῳ, ὅπου οὐκ ἔστιν λίθος οὐδὲ κόχλαξ οὐδὲ τόπος τοῦ φυγεῖν."}, {"sp": "N", "st": "1 Macc 10:74", "t": "Ὡς δε ἤκουσεν Ἰωναθὰν τῶν λόγων Ἀπολλωνίου, ἐκινήθη τῇ διανοίᾳ. καὶ ἐπέλεξεν δέκα χιλιάδας ἀνδρῶν, καὶ ἐξῆλθεν ἐξ Ἰερουσαήμ, καὶ συνήντησεν αὐτῷ Σίμων ὁ ἀδελφὸς αὐτοῦ ἐπὶ βοήθειαν αὐτου."}, {"sp": "N", "st": "1 Macc 10:75", "t": "καὶ παρενέβαλεν ἐπὶ Ἰόππην, καὶ ἀπέκλεισαν αὐτὸν οἱ ἐκ τῆς πόλεως, ὅτι φρουρὰ Ἀπολλωνίου ἐν Ἰόππης. καὶ ἐπολέμησαν αὐτήν."}, {"sp": "N", "st": "1 Macc 10:76", "t": "καὶ φοβηθέντες ἤνοιξαν οἱ ἐκ τῆς πόλεως, καὶ ἐκυρίευσεν Ἰωναθὰν Ἰόππης."}, {"sp": "N", "st": "1 Macc 10:77", "t": "καὶ ἤκουσεν Ἀπολλώνιος, καὶ παρενέβαλεν τρισχιλίαν ἵππον καὶ δύναμιν πολλήν, καὶ ἐπορεύθη εἰς Ἀζωτον ὡς διοδεύων, καὶ ἅμα προσῆγεν εἰς τὸ πεδίον, καὶ διὰ τὸ ἔχειν αὐτὸν πλῆθος ἵππου καὶ πεποιθέναι ἐπʼ αὐτήν."}, {"sp": "N", "st": "1 Macc 10:78", "t": "καὶ κατεδίωξεν ὀπίσω αὐτοῦ εἰς Ἄζωτον, καὶ συνῆψαν αἱ παρεμβολαὶ ὀπίσω αὐτοῦ εἰς πόλεμον."}, {"sp": "N", "st": "1 Macc 10:79", "t": "καὶ ἀπέλειπεν Ἀπολλώνιος χιλίαν ἵππον κρυπτῶς κατόπισθεν αὐτῶυ·"}, {"sp": "N", "st": "1 Macc 10:80", "t": "καὶ ἔγνω Ἰωναθὰν ὅτι ἔστιν ἔνεδρον κατόπισθεν αὐτοῦ. καὶ ἐκύκλωσαν αὐτοῦ τὴν παρεμβολήν, καὶ ἐξετίναξον τὰς σχίζας εἰς τὸν λαὸν ἐκ πρωίθεν ἕως δείλης."}, {"sp": "N", "st": "1 Macc 10:81", "t": "ὁ δὲ λαὸς ἱστήκει καθὼς ἐπέταξεν Ἰωναθάν, καὶ ἐκοπίασαν οἱ ἵπποι αὐτῶν."}, {"sp": "N", "st": "1 Macc 10:82", "t": "καὶ εἵλκυσεν Σίμων τὴν δύναμιν αὐτοῦ, καὶ συνῆψεν πρὸς τὴν φάλαγγα, ἡ γὰρ ἵππος ἐξελύθη· καὶ συνετρίβησαν ἀπʼ αὐτοῦ, καὶ ἔφυγαν."}, {"sp": "N", "st": "1 Macc 10:83", "t": "καὶ ἡ ἵππος ἐσκορπίσθη ἐν τῷ πεδίῳ, καὶ ἔφυγον εἰς Ἄζωτον, καὶ εἰσῆλθον εἰς Βηθδαγὼν τὸ εἰδώλιον αὐτῶν τοῦ σωθῆναι."}, {"sp": "N", "st": "1 Macc 10:84", "t": "καὶ ἐνεπύρισεν Ἰωναθὰν τὴν Ἄζωτον καὶ τὰς πόλεις τὰς κύκλῳ αὐτῆς, καὶ ἔλαβεν τὰ σκῦλα αὐτῶν, καὶ τὸ ἱερὸν Δαγὼν καὶ τὸ ἱερὸν αὐτῆς ἐνεπύρισεν ἐν πυρί."}, {"sp": "N", "st": "1 Macc 10:85", "t": "καὶ ἐγένοντο οἱ πεπτωκότες μαχαίρᾳ σὺν τοῖς ἐνπυρισθεῖσιν εἰς ἄνδρας ὀκτακισχιλίους."}, {"sp": "N", "st": "1 Macc 10:86", "t": "καὶ ἀπῆρεν ἐκεῖθεν Ἰωναθάν, καὶ παρενέβαλεν εἰς Ἀσκάλωνα, καὶ ἐξῆλθον οἱ ἐκ τῆς πόλεως εἰς συνάντησιν αὐτῷ ἐν δόξῃ μεγάλῃ."}, {"sp": "N", "st": "1 Macc 10:87", "t": "καὶ ἐπέστρεψεν Ἰωναθὰν σὺν τοῖς παρʼ αὐτοῦ ἔχοντες σκῦλα πολλά."}, {"sp": "N", "st": "1 Macc 10:88", "t": "καὶ ἐγένετο ὡς ἤκουσεν Ἀλέξανδρος ὁ βασιλεὺς τοὺς λόγους τούτους, καὶ προσέθετο δοξάσαι τὸν Ἰωναθάν."}, {"sp": "N", "st": "1 Macc 10:89", "t": "καὶ ἀπέστειλεν αὐτῷ πόρπην χρυσῆν, ὡς ἔθος ἐστὶν δίδοσθαι τοῖς συγγενεῦσιν τῶν βασιλέων· καὶ ἔδωκεν αὐτῷ τὴν Ἀκκαρὼν καὶ πάντα τὰ ὅρια αὐτῆς εἰς κληροδοσίαν."}, {"sp": "N", "st": "1 Macc 11:1", "t": "Καὶ ὁ βασιλεὺς Αἰγύπτου ἤθροισεν δυνάμεις πολλὰς ὡς ἡ ἄμμος ἡ παρὰ τὸ χεῖλος τῆς θαλάσσης, καὶ πλοῖα πολλά· καὶ ἐζήτησεν κατακρατῆσαι τῆς βασιλείας Ἀλεξάνδρου δόλῳ, καὶ προσθεῖναι αὐτὴν τῆ βασιλείᾳ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 11:2", "t": "καὶ ἐξῆλθεν εἰς Συρίαν λόγοις εἰρηνικοῖς. καὶ ἤνοιγον αὐτῷ οἱ ἀπὸ τῶν πόλεων, καὶ συνήντων αὐτῷ, ὅτι ἐντολή ἦν Ἀλεξάνδρου τοῦ βασιλέως συναντᾷν αὐτῷ διὰ τὸ πενθερὸν αὐτοῦ εἶναι."}, {"sp": "N", "st": "1 Macc 11:3", "t": "ὡς δὲ εἰσεπορεύετο εἰς τὰς πόλεις Πτολεμαίδος, ἀπέτασσε τὰς δυνάμεις φρουρὰν ἐν ἑκάστῃ πόλει."}, {"sp": "N", "st": "1 Macc 11:4", "t": "ὡς δὲ ἤγγισεν Ἀζώτου,. ἔδειξαν αὐτῷ τὸ ἱερὸν Δαγὼν ἐνεπυρισμένον καὶ Ἄζωτον καὶ τὰ περιπόλια αὐτῆς καθῃρημένα καὶ τὰ σώματα ἐρριμμένα, καὶ τοὺς ἐνπεπυρισμένους οὓς ἐνεπύρισεν ἐν τῷ πολέμῳ, ἐποίησαν γὰρ θιμωνιὰς. αὐτῶν ἐν τῇ ὁδῷ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 11:5", "t": "καὶ διηγήσαντο τῷ βασιλεῖ ἃ ἐποίησεν Ἰωναθάν, εἰς τὸ ψογίσαι αὐτόν· καὶ ἐσίγησεν ὁ βασιλεύς."}, {"sp": "N", "st": "1 Macc 11:6", "t": "καὶ συνήντησεν Ἰωναθὰν τῷ βασιλεῖ εἰς Ἰόππην μετὰ δόξης, καὶ ἠσπάσαντο ἀλλήλους, καὶ ἐκοιμήθησαν ἐκεῖ."}, {"sp": "N", "st": "1 Macc 11:7", "t": "καὶ ἐπορεύθη Ἰωναθὰν μετὰ τοῦ βασιλέως ἕως τοῦ ποταμοῦ τοῦ καλουμένου Ἐλευθέρου, καὶ ἐπέστρεψεν εἰς Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Macc 11:8", "t": "ὁ δὲ βασιλεὺς Πτολεμαῖος ἐκυρίευσεν τῶν πόλεων τῆς παραλίας ἕως Σελευκίας τῆς παραθαλασσίας, καὶ διελογίζετο περὶ Ἀλεξάνδρου λογισμοὺς πονηρούς."}, {"sp": "N", "st": "1 Macc 11:9", "t": "καὶ ἀπέστειλεν πρέσβεις πρὸς Δημήτριον βασιλέα, λέγων Δεῦρο συνθώμεθα πρὸς ἑαυτοὺς διαθήκην, καὶ δώσω σοι τὴν θυγατέρα μου ἣν ἔχει Ἀλέξανδρος, καὶ βασιλεύσεις τῆς βασιλείας τοῦ πατρός σου·"}, {"sp": "N", "st": "1 Macc 11:10", "t": "μεταμεμέλημαι γὰρ δοὺς αὐτῷ τὴν θυγατέρα μου, ἐζήτησεν γὰρ ἀποκτεῖναί με."}, {"sp": "N", "st": "1 Macc 11:11", "t": "καὶ ἐψόγισεν αὐτὸν χάριν τοῦ ἐπιθυμῆσαι αὐτὸν τῆς βασιλείας αὐτοῦ."}, {"sp": "N", "st": "1 Macc 11:12", "t": "καὶ ἀφελόμενος αὐτοῦ τὴν θυγατέρα, ἔδωκεν αὐτὴν τῷ Δημητρίῳ, καὶ ἠλλοιώθη τὸ πρόσωπον Ἀλεξάνδρου, καὶ ἐφάνη ἔχθρα αὐτῶν."}, {"sp": "N", "st": "1 Macc 11:13", "t": "Καὶ εἰσῆλθεν Πτολεμαῖος εἰς Ἀντιοχίαν, καὶ περιέθετο τὸ διάδημα τῆς Ἀσίας, καὶ περιέθετο δύο διαδήματα περὶ τὴν κεφαλὴν αὐτοῦ, τὸ τῆς Ἀσίας καὶ Αἰγύπτου."}, {"sp": "N", "st": "1 Macc 11:14", "t": "Ἀλέξανδρος δὲ ὁ βασιλεὺς ἧν εἰς Κιλικίαν κατὰ τοὺς καιροὺς ἐκείνους, ὅτι ἀπεστάτουν οἱ ἀπὸ τῶν τόπων ἐκείνων."}, {"sp": "N", "st": "1 Macc 11:15", "t": "καὶ ἤκουσεν Ἀλέξανδρος, καὶ ἦλθεν ἐπʼ αὐτὸν ἐν πολέμῳ· καὶ ἐξήγαγεν Πτολεμαῖος καὶ ἀπήντησεν αὐτῷ ἐν χειρὶ ἰσχυρῷ, καὶ ἐτροπώσατο αὐτόν."}, {"sp": "N", "st": "1 Macc 11:16", "t": "καὶ ἔφυγεν Ἀλέξανδρος εἰς τὴν Ἀραβίαν, τοῦ σκεπασθῆναι αὐτὸν ἐκεῖ· ὁ δὲ βασιλεὺς Πτολεμαῖος ὑψώθη."}, {"sp": "N", "st": "1 Macc 11:17", "t": "καὶ ἀφεῖλεν Ζαβδιὴλ ὁ Ἄραψ τὴν κεφαλὴν Ἀλεξάνδρου, καὶ ἀπέστειλεν τῷ Πτολεμαίῳ."}, {"sp": "N", "st": "1 Macc 11:18", "t": "καὶ ὁ βασιλεὺς Πτολεμαῖος ἀπέθανεν ἐν τῇ ἡμέρᾳ τῇ τρίτῃ, καὶ οἱ ὄντες ἐν τοῖς ὀχυρώμασιν αὐτοῦ ἀπώλοντο ὑπὸ τῶν ἐν τοῖς ὀχυρώμασιν."}, {"sp": "N", "st": "1 Macc 11:19", "t": "καὶ ἐβασίλευσεν Δημήτριος ἔτους ἑβδόμου καὶ ἑξηκοστοῦ καὶ ἑκατοστοῦ."}, {"sp": "N", "st": "1 Macc 11:20", "t": "Ἐν ταῖς ἡμέραις ἐκείναις συνήγαγεν Ἰωναθὰν τοὺς ἐκ τῆς Ἰουδαίας, τοῦ ἐκπολεμῆσαι τὴν ἄκραν τὴν ἐν Ἰερουσαλήμ· καὶ ἐποίησαν ἐπʼ αὐτὴν μηχανὰς πολλάς."}, {"sp": "N", "st": "1 Macc 11:21", "t": "καὶ ἐπορεύθησάν τινες μισοῦντες τὸ ἔθνος αὐτῶν, ἄνδρες παράνομοι, πρὸς τὸν βασιλέα, καὶ ἀπήγγειλαν αὐτῷ ὅτι Ἰωναθὰν περικάθηται τὴν ἄκραν."}, {"sp": "N", "st": "1 Macc 11:22", "t": "καὶ ἀκούσας ὠργίσθη· ὡς δὲ ἤκουσεν, εὐθέως ἀναζεύξας ἦλθεν εἰς Πτολεμαίδα, καὶ ἔγραψεν Ἰωναθὰν τοῦ μὴ περικαθῆσθαι καὶ τοῦ ἀπαντῆσαι αὐτὸν αὐτῷ συνμίσγειν εἰς Πτολεμαίδα τὴν ταχίστην."}, {"sp": "N", "st": "1 Macc 11:23", "t": "ὡς δὲ ἤκουσεν Ἰωναθάν, ἐκέλευσεν περικαθῆσθαι· καὶ ἐπέλεξεν τῶν πρεσβυτέρων Ἰσραὴλ καὶ τῶν ἱερέων, καὶ ἔδωκεν αὐτὸν τῷ κινδύνῳ."}, {"sp": "N", "st": "1 Macc 11:24", "t": "καὶ λαβὼν ἀργύριον καὶ χρυσίον καὶ ἱματισμὸν καὶ ἕτερα ξένια πλείονα, καὶ ἐπορεύθη πρὸς τὸν βασιλέα εἰς Πτολεμαίδα, καὶ εὗρεν χάριν ἐναντίον αὐτοῦ."}, {"sp": "N", "st": "1 Macc 11:25", "t": "καὶ ἐνετύγχανον κατʼ αὐτοῦ τινες ἄνομοι τῶν ἐκ τοῦ ἔθνους."}, {"sp": "N", "st": "1 Macc 11:26", "t": "καὶ ἐποίησεν αὐτῷ ὁ βασιλεὺς καθὼς ἐποίησαν αὐτῷ οἱ πρὸ αὐτοῦ, καὶ ὕψωσεν αὐτὸν ἐναντίον πάντων τῶν φίλων αὐτοῦ."}, {"sp": "N", "st": "1 Macc 11:27", "t": "καὶ ἔστησεν αὐτῷ τὴν ἀρχιερωσύνην, καὶ ὅσα ἄλλα εἶχεν τίμια τὸ πρότερον, καὶ ἐποίησεν αὐτὸν τῶν πρώτων φίλων ἡγεῖσθαι."}, {"sp": "N", "st": "1 Macc 11:28", "t": "καὶ ἠξίωσεν Ἰωναθὰν τὸν βασιλέα ποιῆσαι τὴν Ἰουδαίαν ἀφορολόγητον καὶ τὰς τρεῖς τοπαρχίας καὶ τὴν Σαμαρῖτιν, καὶ ἐπηγγείλαντο αὐτῷ τάλαντα τριακόσια."}, {"sp": "N", "st": "1 Macc 11:29", "t": "καὶ εύδόκησεν ὁ βασιλεύς, καὶ ἔγραψεν τῷ Ἰωναθὰν ἐπιστολὰς περὶ πάντων τούτων ἐχούσας τὸν τρόπον τοῦτον"}, {"sp": "N", "st": "1 Macc 11:30", "t": "Βασιλεὺς Δημήτριος Ἰωναθὰν τῷ ἀδελφῷ χαίρειν, καὶ ἔθνει Ἰουδαίῳ."}, {"sp": "N", "st": "1 Macc 11:31", "t": "τὸ ἀντίγραφον τῆς ἐπιστολῆς, ἧς ἐγράψαμεν Λασθένει τῷ συγγενεῖ ἡμῶν περὶ ὑμῶν, γεγράφαμεν καὶ πρὸς ὑμᾶς, ὅπως ἴδητε"}, {"sp": "N", "st": "1 Macc 11:32", "t": "Βασιλεὺς Δημήτριος Λασθένει τῷ πατρὶ χαίρειν."}, {"sp": "N", "st": "1 Macc 11:33", "t": "τῷ ἔθνει τῶν Ἰουδαίων φίλοις ἡμῶν καὶ συντηροῦσι τὰ πρὸς ἡμᾶς δίκαια ἐκρίναμεν ἀγαθοποιῆσαι, χάριν τῆς ἑαυτῶν εὐνοίας πρὸς ἡμᾶς."}, {"sp": "N", "st": "1 Macc 11:34", "t": "θστάκαμεν οὖν αὐτοῖς τὰ ὅρια τῆς Ἰουδαίας καὶ τοὺς τρεῖς νομούς, Ἀφαίρεμα καὶ Λύδδα καὶ Ῥαθαμείν· προσετέθησαν τῇ Ἰουδαίᾳ ἀπὸ τῆς Σαμαρίτιδος· καὶ πάντα τὰ συγκυροῦντα αὐτοῖς πᾶσιν τοῖς θυσιάζουσιν εἰς Ἰεροσόλυμα, ἀντὶ τῶν βασιλικῶν ὧν ἐλάμβανεν ὁ βασιλεὺς παρʼ αὐτῶν τὸ πρότερον κατʼ ἐνιαυτὸν ἀπὸ τῶν γενημάτων τῆς γῆς καὶ τῶν ἀκροδρύων."}, {"sp": "N", "st": "1 Macc 11:35", "t": "καὶ τὰ ἄλλα τὰ ἀνήκοντα ἡμῖν ἀπὸ τοῦ νῦν τῶν δεκατῶν καὶ τῶν τελῶν τῶν ἀνηκόντων ἡμίν, καὶ τὰς τοῦ ἁλὸς λίμνας, καὶ τοὺς ἀνήκοντας ἡμῖν στεφάνους, πάντα ἐπαρκέσομεν αὐτοῖς."}, {"sp": "N", "st": "1 Macc 11:36", "t": "καὶ οὐκ ἀθετήσεται οὐδέν τούτων ἀπὸ τοῦ νῦν ἐπὶ τὸν ἅπαντα χρόνον."}, {"sp": "N", "st": "1 Macc 11:37", "t": "νῦν οὖν ἐπιμελεῖσθε τοῦ ποιῆσαι τούτων ἀντίγραφον, καὶ δοθήτω Ἰωναθάν, καὶ, τεθήτω ἐν ὄρει τῷ ἁγίῳ ἐν τόπῳ ἐπιτηδείῳ ἐπισήμῳ."}, {"sp": "N", "st": "1 Macc 11:38", "t": "Καὶ ἴδεν Δημήτριος ὁ βασιλεὺς ὅτι ἡσύχασεν ἡ γῆ ἐνώπιον αὐτοῦ καὶ οὐθὲν αὐτῷ ἀνθεστήκει, καὶ ἀπέλυσεν πάσας τὰς δυνάμεις αὐτοῦ, ἕκαστον εἰς τὸν ἴδιον τόπον, πλὴν τῶν ξένων δυνάμεων ὧν ἐξενολόγησεν ἀπὸ τῶν νήσων τῶν ἐθνῶν· καὶ ἤχθρασαν αὐτῶν πᾶσαι αἱ δυνάμεις αἱ ἀπὸ τῶν πατέρων."}, {"sp": "N", "st": "1 Macc 11:39", "t": "Γρύφαων δὲ ἦν τῶν παρὰ Ἀλεξάνδρου τὸ πρότερον, καὶ ἴδεν ὅτι πᾶσαι αἱ δυνάμεις καταγογγύζουσιν κατὰ τοῦ Δημητρίου, καὶ ἐπορεύθη πρὸς Σινμαλκουὴ τὸν Ἄραβα, ὃς ἔτρεφεν τὸν Ἀντίοχον τὸ παιδάριον τὸ τοῦ Ἀλεξάνδρου·"}, {"sp": "N", "st": "1 Macc 11:40", "t": "καὶ προσήδρευεν αὐτῷ, ὅπως παραδοῖ αὐτὸν αἰτῷ, ὅπως βασιλεύσῃ ἀντὶ τοῦ πατρὸς αὐτοῦ· καὶ ἀπἡγγειλαν αὐτῷ ὅσα συνετέλεσεν Δημήτριος, καὶ τὴν ἔχθραν ἣν ἐχθραίνουσιν αὐτῷ αἱ δυνάμεις αὐτοῦ· καὶ ἔμεινεν ἐκεῖ ἡμέρας πολλάς."}, {"sp": "N", "st": "1 Macc 11:41", "t": "Καὶ ἀπέστειλεν Ἰωναθὰν πρὸς Δημήτριον τὸν βασιλέα, ἵνα ἐκβάλῃ τοὺς ἐκ τῆς ἄκρας ἐξ Ἰερουσαλὴμ καὶ τοὺς ἐν τοῖς ὀχυρώμασιν· ἦσαν γὰρ πολεμοῦντες τὸν Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 11:42", "t": "καὶ ἀπέστειλεν Δημήτριος πρὸς Ἰωναθὰν λέγων Οὐ μόνον ταῦτα ποιήσω σοι καὶ τῷ ἔθνει σου, ἀλλ᾿ ἢ δόξῃ δοξάσω σε καὶ τὸ ἔθνος σου, ἐὰν εὐκαιρίας τύχω."}, {"sp": "N", "st": "1 Macc 11:43", "t": "νῦν οὖν ὀρθῶς ποιήσεις ἀποστείλας ἡμῖν ἄνδρας οἳ συμμαχήσουσίν μοι, ὅτι ἀπέστησαν πᾶσαι αἱ δυνάμεις μου."}, {"sp": "N", "st": "1 Macc 11:44", "t": "καὶ ἀπέστειλεν Ἰωναθὰν ἄνδρας τρισχιλίους δυνατοὺς ἰσχύι αὐτῶν εἰς Ἀντιοχίαν, καὶ ἤλθοσαν πρὸς τὸν βασιλέι, καὶ ηὐφράνθη ὁ βασιλεὺς ἐπὶ τῇ ἐφόδῳ αὐτῶν."}, {"sp": "N", "st": "1 Macc 11:45", "t": "καὶ ἐπισυνήχθησαν οἱ ἐκ τῆς πόλεως εἰς μέσον τῆς πόλεως εἰς ἄνδρας δώδεκα μυριάδας, καὶ ἠβούλοντο ἀνελεῖν τὸν βασιλέα."}, {"sp": "N", "st": "1 Macc 11:46", "t": "καὶ ἔφυγεν ὁ βασιλεὺς εἰς τὴν αὐλήν, καὶ κατελάβοντο οἱ ἐκ τῆς πόλεως τὰς διόδους δῆς πόλεως, καὶ ἤρξαντο ἐκπολεμεῖν."}, {"sp": "N", "st": "1 Macc 11:47", "t": "καὶ ἐκάλεσεν ὁ βασιλεὺς τοὺς Ἰουδαίους ἐπὶ βοήθειαν, καὶ ἐπισυνήχθησαν πρὸς αὐτὸν πάντες ἅμα· καὶ διεσπάρησαν ἐν τῇ πόλει· καὶ ἀπέκτειναν ἐν τῇ πόλει ἐν τῇ ἡμέρᾳ ἐκείνῃ εἰς μυριάδας δέκα."}, {"sp": "N", "st": "1 Macc 11:48", "t": "καὶ ἐνεπύρισαν τὴν πόλιν, καὶ ἐλάβοσαν σκῦλα πολλὰ ἐν ἐκείνῃ τῇ ἡμέρᾳ, καὶ ἔσωσαν τὸν βασιλέα."}, {"sp": "N", "st": "1 Macc 11:49", "t": "καὶ ἴδον οἱ ἀπὸ τῆς πόλεως ὅτι κατεκράτησαν οἱ Ἰουδαῖοι τῆς πόλεως ὡς ἠβούλοντο, καὶ ἠσθένησαν ταῖς διανοίαις αὐτῶν, καὶ ἐκέκραξαν πρὸς τὸν βασιλέα μετὰ δεήσεως, λέγοντες"}, {"sp": "N", "st": "1 Macc 11:50", "t": "Δὸς ἡμῖν δεξιάς, καὶ παυσάσθωσαν οἱ Ἰουδαῖοι πολεμοῦντες ἡμᾶς καὶ τὴν πόλιν."}, {"sp": "N", "st": "1 Macc 11:51", "t": "καὶ ἔριψαν τὰ ὅπλα, καὶ ἐποίησαν εἰρήνην· καὶ ἐδοξάσθησαν οἱ Ἰουδαῖοι ἐναντίον τοῦ βασιλέως καὶ ἐνώπιον πάντων τῶν ἐν τῇ βασιλειᾳ αὐτοῦ· καὶ ἐπέστρεψαν εἰς Ἰερουσαλὴμ ἔχοντες σκῦλα πολλά."}, {"sp": "N", "st": "1 Macc 11:52", "t": "καὶ ἐκάθισεν ὁ βασιλεὺς Δημήτριος ἐπὶ θρόνου τῆς βασιλείας αὐτοῦ, καὶ ἡσύχασεν ἡ γῆ ἐνώπιον αὐτοῦ·"}, {"sp": "N", "st": "1 Macc 11:53", "t": "καὶ ἐψεύσατο πάντα ὅσα εἶπεν, καὶ ἠλλοτριώθη τῷ Ἰωναθὰν καὶ οὐκ ἀνταπέδωκεν τὰς εὐνοίας ἃς ἀνταπέδωκεν αὐτῷ, καὶ ἔθλιψεν αὐτὸν σφόδρα."}, {"sp": "N", "st": "1 Macc 11:54", "t": "Μετὰ δὲ ταῦτα ἀπέστρεψεν Τρύφων καὶ Ἀντίοχος μετʼ αὐτοῦ, παιδάριον νεώτερον· καὶ ἐβασίλευσεν, καὶ ἐπέθετο διάδημα."}, {"sp": "N", "st": "1 Macc 11:55", "t": "καὶ ἐπισυνήχθησαν πρὸς αὐτὸν πᾶσαι αἱ δυνάμεις ἃς ἀπεσκοράκισεν Δημήτριος, καὶ ἐπολέμησαν πρὸς αὐτόν, καὶ ἔφυγεν καὶ ἐτροπώθη·"}, {"sp": "N", "st": "1 Macc 11:56", "t": "καὶ ἔλαβεν Τρύφων τὰ θηρία, καὶ κατεκράτησεν Ἀντιοχίας."}, {"sp": "N", "st": "1 Macc 11:57", "t": "καὶ ἔγραψεν Ἀντίοχος ὁ νεώτερος Ἰωνάθα λέγων Ἵστημί σοι τὴν ἀρχιερωσύνην, καὶ καθίστημί σε ἐπὶ τῶν τεσσάρων νομῶον, καὶ εἶυαί σε τῶν φίλων τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 11:58", "t": "καὶ ἀπέστειλεν αὐτῷ χρυσώματα καὶ διακονίαν, καὶ ἔδωκεν αὐτῷ ἐξουσίαν πίνειν ἐν χρυσώμασιν καὶ εἶναι ἐν πορφύρᾳ καὶ ἔχειν πόρπην χρυσῆν."}, {"sp": "N", "st": "1 Macc 11:59", "t": "καὶ Σίμωνα τὸν ἀδελφὸν αὐτοῦ κατέστησεν στρατηγὸν ἀπὸ τῆς κλίμακος Ἰύρου ἔως τῶν ὁρίων Αἰγύπτου."}, {"sp": "N", "st": "1 Macc 11:60", "t": "καὶ ἐξῆλθεν Ἰωναθάν, καὶ διεπορεύετο πέραν τοῦ ποταμοῦ καὶ ἐν ταῖς πόλεσιν, καὶ ἡθροίσθησαν πρὸς αὐτὸν πᾶσαι αἱ δυνάμεις Συρίας εἰς συμμαχίαν· καὶ ἦλθεν εἰς Ἀσκάλωνα, καὶ ἀπήντησαν αὐτῷ οἱ ἐκ τῆς πόλεως ἐνδόξως."}, {"sp": "N", "st": "1 Macc 11:61", "t": "καὶ ἀπῆλθεν ἐκεῖθεν εἰς Γάζαν, καὶ ἀπέκλεισαν οἱ ἀπὸ Γάζης· καὶ περιεκάθισεν περὶ αὐτήν, καὶ ἐνεπύρισεν τὰ περιπόλια αὐτῆς ἐν πυρί, καὶ ἐσκύλευσεν αὐτάς·"}, {"sp": "N", "st": "1 Macc 11:62", "t": "καὶ ἠξίωσαν οἱ ἀπὸ Γάζης Ἰωναθάν, καὶ ἔδωκεν αὐτοῖς δεξιάς· καὶ ἔλαβεν τοὺς υἱοὺς τῶν ἀρχόντων αὐτῶν εἰς ὅμηρα, καὶ ἐξαπέστειλεν αὐτοὺς εἰς Ἰερουσαλήμ, καὶ διῆλθεν τὴν χώραν ἕως Δαμασκοῦ."}, {"sp": "N", "st": "1 Macc 11:63", "t": "Καὶ ἤκουσεν Ἰωναθὰν ὅτι παρῆσαν οἱ ἄρχοντες Δημητρίου εἰς Κῆδες τὴν ἐν τῇ Γαλιλαίᾳ μετὰ δυνάμεως πολλῆς, βουλόμενοι μεταστῆσαι αὐτὸν τῆς χρείας."}, {"sp": "N", "st": "1 Macc 11:64", "t": "καὶ συνήντησεν αὐτοῖς, τὸν δὲ ἀδελφὸν αὐτοῦ Σίμωνα κατέλειπεν ἐν τῇ χώρᾳ."}, {"sp": "N", "st": "1 Macc 11:65", "t": "καὶ παρενέβαλεν Σίμων ἐν Βεθσούρᾳ, καὶ ἐπολέμει αὐτὴν ἡμέρας πολλὰς καὶ συνέκλεισεν αὐτήν."}, {"sp": "N", "st": "1 Macc 11:66", "t": "καὶ ἠξίωσαν αὐτὸν τοῦ δεξιὰς λαβεῖν, καὶ ἔδωκεν αὐτοῖς· καὶ ἐξέβαλεν αὐτοὺς ἐκεῖθεν καὶ κατελάβετο τὴν πόλιν, καὶ ἔθετο ἐπʼ αὐτὴν φρουράν."}, {"sp": "N", "st": "1 Macc 11:67", "t": "καὶ Ἰωναθὰν καὶ ἡ παρεμβολὴ αὐτοῦ παρενέβαλον ἐπὶ τὸ ὕδωρ τοῦ Γεννησάρ· καὶ ὤρθρισαν τὸ πρωὶ εἰς τὸ πεδίον Νασώρ·"}, {"sp": "N", "st": "1 Macc 11:68", "t": "καὶ ἰδοὺ παρεμβολὴ ἀλλοφύλων ἀπήντα αὐτῷ ἐν τῷ πεδίῳ, καὶ ἐξέβαλον ἔνεδρον ἐπʼ αὐτὸν ἐν τοῖς ὄρεσιν, αὐτοὶ δὲ ἀπήντησαν ἐξ ἐναντίας."}, {"sp": "N", "st": "1 Macc 11:69", "t": "τὰ δὲ ἔνεδρα ἐξανέστησαν ἐκ τῶν τόπων ἑαυτῶν, καὶ συνῆψαν πόλεμον· καὶ ἔφυγον οἱ παρὰ Ἰωνάθου πάντες·"}, {"sp": "N", "st": "1 Macc 11:70", "t": "οὐδὲ εἰς κατελείφθη ἀπʼ αὐτῶν, πλὴν Ματταθίας ὁ τοῦ Ἀψαλώμου καὶ Ἰούδας ὁ τοῦ Χαλφεί, ἄρχοντες τῆς στρατιᾶς τῶν δυνάμεων."}, {"sp": "N", "st": "1 Macc 11:71", "t": "καὶ διέρρηξεν Ἰωναθὰν τὰ ἱμάτια αὐτοῦ, καὶ ἐπέθετο γῆν ἐπὶ τὴν κεφαλὴν αὐτοῦ, καὶ προσηύξατο."}, {"sp": "N", "st": "1 Macc 11:72", "t": "καὶ ἐπέστρεψεν πρὸς αὐτοὺς πολέμῳ, καὶ ἐτροπώσατο αὐτούς, καὶ ἔφυγον."}, {"sp": "N", "st": "1 Macc 11:73", "t": "καὶ ἴδον οἱ φυγόντες παρʼ αὐτοῦ, καὶ ἐπέστρεψαν πρὸς αὐτόν, καὶ ἐδίωκον μετʼ αὐτοῦ ἕως Κάδης ἕως τῆς παρεμβολῆς αὐτῶν, καὶ παρενέβαλον ἐκεῖ"}, {"sp": "N", "st": "1 Macc 11:74", "t": "καὶ ἔπεσον ἐκ τῶν ἀλλοφύλων ἐν τῇ ἡμἐρᾳ ἐκείνῃ εἰς ἄνδρας τρισχιλίους· καὶ ἐπέστρέψεν Ἰωναθὰν εἰς Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Macc 12:1", "t": "Καὶ ἴδεν Ἰωναθὰν ὅτι ὁ καιρὸς αὐτῷ συνεργεῖ, καὶ ἐπέλεξεν ἄνδρας, καὶ ἀπέστειλεν εἰς Ῥώμην στῆσαι καὶ ἀνανεῶσαι τὴν πρὸς αὐτοὺς φιλίαν·"}, {"sp": "N", "st": "1 Macc 12:2", "t": "καὶ πρὸς Σπαρτιάτας καὶ τόπους ἑτέρους ἀπέστειλεν ἐπιστολὰς κατὰ ταὐτά."}, {"sp": "N", "st": "1 Macc 12:3", "t": "καὶ ἐπορεύθησαν εἰς Ρώμην, καὶ ἐπορεύθησαν εἰς τὸ βουλευτήριον, καὶ εἶπαν Ἰωναθὰν ὁ ἀρχιερεὺς καὶ τὸ ἔθνος τῶν Ἰουδαίων ἀπέστειλαν ἡμᾶς ἀνανεώσασθαι τὴν φιλίαν αὐτοῖς καὶ τὴν συμμαχίαν κατὰ τὸ πρότερον."}, {"sp": "N", "st": "1 Macc 12:4", "t": "καὶ ἔδωκαν ἐπιστολὰς αὐτοῖς πρὸς αὐτοὺς κατὰ τόπον, ὅπως προπέμπωσιν αὐτοὺς εἰς γῆν Ἰούδα μετ᾿ εἰρήνης."}, {"sp": "N", "st": "1 Macc 12:5", "t": "καὶ τοῦτο ἀντίγραφον τῶν ἐπιστολῶν ὦν ἔγραψεν Ἰωναθὰν τοῖς Σπαρτιάταις"}, {"sp": "N", "st": "1 Macc 12:6", "t": "Ἰωναθὰν ἀρχιερεὺς τοῦ ἔθνους καὶ ἡ γερουσία καὶ οἱ ἱερεῖς καὶ ὁ λοιπὸς δῆμος τῶν Ἰουδαίων Σπαρτιάταις τοῖς ἀδελφοῖς χαίρειν."}, {"sp": "N", "st": "1 Macc 12:7", "t": "ἔτι πρότερον ἀπεστάλησαν ἐπιστολαὶ πρὸς Ὀνίαν τὸν ἀρχιερέα, παρὰ δʼ Ἀρείου τοῦ βασιλεύοντος ἐν ὑμῖν, ὅτι ἐστὲ ἀδελφοὶ ἡμῶν, ὡς τὸ ἀντίγραφον ὑπόκειται."}, {"sp": "N", "st": "1 Macc 12:8", "t": "καὶ ἐπεδέξατο Ὀνίας τὸν ἄνδρα τὸν ἀπεσταλμένον ἐνδόξως, καὶ ἔλαβεν τὰς ἐπιστολάς, ἐν αἷς διεσαφεῖτο περὶ συμμαχίας καὶ φιλίας."}, {"sp": "N", "st": "1 Macc 12:9", "t": "καὶ ἡμεῖς οὗν ἀπροσδεεῖς τούτων ὄντες, παράκλησιν ἔχοντες τὰ βιβλία τὰ ἅγια τὰ ἐν ταῖς χερσὶν ἡμῶν,"}, {"sp": "N", "st": "1 Macc 12:10", "t": "ἐπειράθημεν ἀποστεῖλαι τὴν πρὸς ὑμᾶς ἀδελφότητα καὶ φιλίαν ἀνανεώσασθαι, πρὸς τὸ μὴ ἐξαλλοτριωθῆναι ὑμῶν· πολλοὶ γὰρ καιροὶ διῆλθον ἀφʼ οὗ ἀπεστείλατε πρὸς ἡμᾶς."}, {"sp": "N", "st": "1 Macc 12:11", "t": "ἡμεῖς οὗν ἐν παντὶ καιρῷ ἀδιαλείπτως ἐν ταῖς ἑορταῖς καὶ ἐν ταῖς λοιπαῖς καθηκούσαις ἡμέραις μιμνησκόμεθα ὑμῶν, ἐφʼ ὧν προσφέρομεν θυσιῶν καὶ ἐν ταῖς προσευχαῖς, ὡς δέον ἐστὶν καὶ πρέπον μνημονεύειν ἀδελφῶν."}, {"sp": "N", "st": "1 Macc 12:12", "t": "εὐφραινόμεθα δὲ ἐπὶ τῇ δόξῃ ὑμῶν."}, {"sp": "N", "st": "1 Macc 12:13", "t": "ἡμᾶς δὲ ἐκύκλωσαν πολλαὶ θλίψεις καὶ πόλεμοι πολλοί, καὶ ἐπολέμησαν ἡμᾶς οἱ βασιλεῖς οἱ κύκλῳ ἡμῶν."}, {"sp": "N", "st": "1 Macc 12:14", "t": "οὐκ ἠβουλόμεθα οὖν παρενοχλεῖν ὑμῖν καὶ τοὺς λοιποὺς συμμάχους καὶ φίλους ἡμῶν ἐν τοῖς πολέμοις τούτοις."}, {"sp": "N", "st": "1 Macc 12:15", "t": "ἔχομεν γὰρ τὴν ἐξ οὐρανῶν βοηθίαν βοηθοῦσαν ἡμῖν, καὶ ἐρύσθημεν ἀπὸ τῶν ἐχθρῶν ἡμῶν, καὶ ἐταπεινώθησαν οἱ ἐχθροὶ ἡμῶν."}, {"sp": "N", "st": "1 Macc 12:16", "t": "ἐπελέξαμεν οὗν Νουμήνιον Ἀντιόχου καὶ Ἀντίπατρον Ἰάσονος, καὶ ἀπεστάλκαμεν πρὸς Ῥωμαίους ἀνανεώσασθαι τὴν πρὸς αὐτοὺς φιλίαν καὶ συμμαχίαν τὴν πρότερον."}, {"sp": "N", "st": "1 Macc 12:17", "t": "ἐνετειλάμεθα οὖν αὐτοῖς καὶ πρὸς ὑμᾶς πορευθῆναι καὶ ἀσπάσασθαι ὑμᾶς, καὶ ἀποδοῦναι ὑμῖν τὰς παρʼ ἡμῶν ἐπιστολὰς περὶ τῆς ἀνανεώσεως καὶ τῆς ἀδελφότητος ἡμῶν."}, {"sp": "N", "st": "1 Macc 12:18", "t": "καὶ νῦν καλῶς ποιήσετε ἀντιφωνήσαντες ἡμῖν πρὸς ταῦτα."}, {"sp": "N", "st": "1 Macc 12:19", "t": "Καὶ τοῦτο τὸ ἀντίγραφον τῶν ἐπιστολῶν ὧν ἀπέστειλαν Ὀνείᾳ"}, {"sp": "N", "st": "1 Macc 12:20", "t": "Ἄρης βασιλεὺς Σπαρτιατῶν Ὀνείᾳ ἱερεῖ μεγάλῳ χαίρειν."}, {"sp": "N", "st": "1 Macc 12:21", "t": "εὑρέθη ἐν γραφῇ περί τε τῶν Σπαρτιατῶν καὶ Ἰουδαίων, ὅτι ἀδελφοὶ εἰσίν, καὶ ὅτι εἰσὶν ἐκ γένους Ἀβραάμ."}, {"sp": "N", "st": "1 Macc 12:22", "t": "καὶ νῦν ἀφʼ οὐ ἔγνωμεν ταῦτα, καλῶς ποιήσετε γράφοντες ἡμῖν περὶ τῆς εἰρήνης ὑμῶν."}, {"sp": "N", "st": "1 Macc 12:23", "t": "καὶ ἡμεῖς δὲ ἀντιγράφομεν ὑμῖν Tὰ κτήνη ὑμῶν καὶ ἡ ὕπαρξις ὑμῶν ἡμῖν ἐστιν, καὶ τὰ ἡμῶν ὑμῖν ἐστιν· ἐντελλόμεθα οὗν ὅπως ἀπαγγείλωσιν ὑμῖν κατὰ τὰ αὐτά."}, {"sp": "N", "st": "1 Macc 12:24", "t": "Καὶ ἤκουσεν Ἰωναθὰν ὅτι ἐπέστρεψαν οἱ ἄρχοντες Δημητρίου μετὰ δυνάμεως πολλῆς ὑπέρ τὸ πρότερον τοῦ πολεμῆσαι πρὸς αὐτόν."}, {"sp": "N", "st": "1 Macc 12:25", "t": "καὶ ἀπῆρεν ἐξ Ἰερουσαλήμ, καὶ ἀπήντησεν αὐτοῖς εἰς τὴν Ἁμαθειτιν χώραν· οὐ γὰρ ἔδωκεν αὐτοῖς ἀνοχὴν τοῦ ἐμβατεῦσαι εἰς τὴν χώραν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 12:26", "t": "καὶ ἀπέστειλεν κατασκόπους εἰς τὴν παρεμβολὴν αὐτοῦ· καὶ ἐπέστρεψαν, καὶ ἀπήγγειλαν αὐτῷ ὅτι Οὕτως τάσσονται ἐπιπεσεῖν ἐπʼ αὐτοὺς τὴν νύκτα."}, {"sp": "N", "st": "1 Macc 12:27", "t": "ὡς δὲ ἔδυ ὁ ἥλιος, ἐπέταξεν Ἰωναθὰν τοῖς παρʼ αὐτοῦ γρηγορεῖν καὶ εἶναι ἐπὶ τοῖς ὅπλαις, ἑτοιμάζεσθαι εἰς πόλεμον δι᾿ ὅλης τῆς νυκτός· καὶ ἐξέβαλεν προφύλακας κύκλῳ τῆς παρεμβολῆς."}, {"sp": "N", "st": "1 Macc 12:28", "t": "καὶ ἤκουσαν οἱ ὑπεναντίοι ὅτι ἡτοίμασται Ἰωναθὰν καὶ οἱ παρʼ αὐτοῦ εἰς πόλεμον, καὶ ἐφοβήθησαν καὶ ἔπτηξαν τὴν καρδίαν αὐτῶν, καὶ ἀνέκαυσαν πυρὰς ἐν τῇ παρεμβολῇ αὐτῶν."}, {"sp": "N", "st": "1 Macc 12:29", "t": "Ἰωναθὰν δὲ καὶ οἱ παρʼ αὐτοῦ οὐκ ἔγνωσαν ἕως πρωί ἔβλεπον γὰρ τὰ φῶτα καιόμενα."}, {"sp": "N", "st": "1 Macc 12:30", "t": "καὶ κατεδίωξεν ὀπίσω αὐτῶν, καὶ οὐκ ἐκατελαβεν αὐτούς, διέβησαν γὰρ τὸν Ἐλεύθερον ποταμόν."}, {"sp": "N", "st": "1 Macc 12:31", "t": "καὶ ἐξέκλινεν Ἰωναθὰν ἐπὶ τοὺς Ἄραβας τοὺς καλουμένους Ζαβαδαίους, καὶ ἐπάταξεν αὐτούς, καὶ ἔλαβεν τὰ σκῦλα αὐτῶν."}, {"sp": "N", "st": "1 Macc 12:32", "t": "καὶ ἀναζεύξας ᾖλθεν εἰς Δαμασκόν, καὶ διώδευσεν ἐν πάσῃ τῇ χώρᾳ."}, {"sp": "N", "st": "1 Macc 12:33", "t": "καὶ Σίμων ἐξῆλθεν καὶ διώδευσεν ἕως Ἀσκάλωνος, καὶ τὰ πλησίον ὀχυρώματα, καὶ ἐξέκλινεν εἰς Ἰόππην καὶ προκατελάβετο αὐτήν."}, {"sp": "N", "st": "1 Macc 12:34", "t": "ἤκουσεν γὰρ ὅτι βούλονται τὸ ὀχύρωμα παραδοῦναι τοῖς παρὰ Δημητρίου, καὶ ἔθετο ἐκεῖ φρουράν, ὅπως φυλάσσωσιν αὐτήν."}, {"sp": "N", "st": "1 Macc 12:35", "t": "Καὶ ἐπέστρεψεν Ἰωναθὰν καὶ 'ξεκκλησίασεν τοὺς πρεσβυτέρους τοῦ λαοῦ, καὶ ἐβουλεύσατο μετʼ αὐτῶν τοῦ οἰκοδομῆσαι ὀχυρώματα ἐν τῇ Ἰουδαία,"}, {"sp": "N", "st": "1 Macc 12:36", "t": "καὶ προσυψῶσαι τὰ τείχη Ἰερουσαλήμ, καὶ ὑψῶσαι ὕψος μέγα ἀνὰ μέσον τῆς ἄκρας καὶ τῆς πόλεως εἰς τὸ διαχωρίσαι αὐτὴν τῆς πόλεως, ἵνα ἡ αὕτη κατὰ μόνας, ὅπως μήτε ἀγοράζωσιν μήτε πωλῶσιν."}, {"sp": "N", "st": "1 Macc 12:37", "t": "καὶ συνήχθησαν τοῦ οἰκοδομεῖν, καὶ ἔπεσεν τοῦ τείχους τοῦ χειμάρρου τοῦ ἐξ ἀπηλιώτου, καὶ ἐπεσκεύασεν τὸ καλούμενον Χαφεναθά."}, {"sp": "N", "st": "1 Macc 12:38", "t": "καὶ Σίμων ᾠκοδόμησεν τὴν Ἁδιδὰ ἐν τῆ σεφηλά, καὶ ὠχύρωσεν θύρας καὶ μοχλούς."}, {"sp": "N", "st": "1 Macc 12:39", "t": "Καὶ ἐζήτησεν Τρύφων βασιλεῦσαι τῆς Ἀσίας καὶ περιθέσθαι τὸ διάδημα καὶ ἐκτεῖναι χεῖρας ἐπὶ Ἀντίοχον τὸν βασιλέα."}, {"sp": "N", "st": "1 Macc 12:40", "t": "καὶ ηὐλαβήθη μή ποτε οὐκ ἐάσῃ αὐτὸν Ἰωναθὰν καὶ μὴ ποτε πολεμήσῃ πρὸς αὐτόν, καὶ ἐζήτει πόρον τοῦ συλλαββεῖν αὐτὸν τοῦ ἀποκτεῖναι· καὶ ἀπάρας ἦλθεν εἰς Βεθσά."}, {"sp": "N", "st": "1 Macc 12:41", "t": "καὶ ἐξῆλθεν Ἰωναθὰν εἰς ἀπάντησιν αὐτῷ ἐν τεσσεράκοντα χιλιάσιν ἀνδρῶν ἐπιλελεγμέναις εἰς παράταξιν, καὶ ἦλθεν εἰς Βεθσά."}, {"sp": "N", "st": "1 Macc 12:42", "t": "καὶ εἶδεν Τρύφων ὅτι πάρεστιν μετὰ δυνάμεως πολλῆς, καὶ ἐκτεῖναι χεῖρας ἐπʼ αὐτὸν ηὐλαβήθη."}, {"sp": "N", "st": "1 Macc 12:43", "t": "καὶ ἐπεδέξατο αὐτὸν ἐνδόξως, καὶ συνέστησεν αὐτὸν πᾶσιν τοῖς φίλοις αὐτοῦ, καὶ ἔδωκεν αὐτῷ δόματα, καὶ ἐπέταξεν τοῖς φίλοις αὐτοῦ καὶ ταῖς δυνάμεσιν αὐτοῦ ὑπακούειν αὐτῷ ὡσαύτως."}, {"sp": "N", "st": "1 Macc 12:44", "t": "καὶ εἶπεν τῷ Ἰωναθάν Ἵνα τί ἔκοψας πάντα τὸν λαὸν τοῦτον πολέμου μὴ ἐνεστηκότος ἡμῖν;"}, {"sp": "N", "st": "1 Macc 12:45", "t": "καὶ νῦν ἀπόστειλον αὐτοὺς εἰς τοὺς οἴκους αὐτῶν, ἐπίλεξον δέ σεαυτῷ ἄνδρας ὀλίγους οἴτιωες ἔσονται μετὰ σοῦ· καὶ δεῦρο μετʼ ἐμοῦ εἰς Πτολεμαίδα, καὶ παραδώσω σοι αὐτὴν καὶ τὰ λοιπὰ ὀχυρώματα καὶ τὰς δυνάμεις τὰς πολλὰς καὶ πάντας τοὺς ἐπὶ τῶν χρειῶν, καὶ ἐπιστρέψας ἀπελεύσομαι· τούτου γὰρ χάριν πάρειμι."}, {"sp": "N", "st": "1 Macc 12:46", "t": "καὶ ἐμπιστεύσας αὐτῷ ἐποίησεν καθὼς εἶπεν, καὶ ἐξαπέστειλεν τὰς δυνάμεις, καὶ ἀπῆλθον εἰς γῆν Ἰούδα."}, {"sp": "N", "st": "1 Macc 12:47", "t": "κατέλειπεν δὲ μεθʼ ἑαυτοῦ ἄνδρας τρισχιλίους· ὡς δισχιλίους ἀφῆκεν ἐν τῇ Γαλιλαίᾳ, χίλιοι δὲ συνῆλθον αὐτῷ."}, {"sp": "N", "st": "1 Macc 12:48", "t": "Ὡς δὲ εἰσῆλθεν Ἰωναθὰν εἰς Πτολεμαίδα, ἀπέκλεισαν οἱ Πτολεμαῖται τὰς πύλας, καὶ συνέλαβον αὐτόν, καὶ πάντας τοὺς συνελθόντας μετʼ αὐτοῦ ἀπέκτειναν ἐν ῥομφαίᾳ."}, {"sp": "N", "st": "1 Macc 12:49", "t": "καὶ ἀπέστειλεν Τρύφων δυνάμεις καὶ ἵππον εἰς Γαλιλαίαν εἰς τὸ πεδίον τὸ μέγα, τοῦ ἀπολέσαι πάντας τοὺς παρὰ Ἰωνάθου."}, {"sp": "N", "st": "1 Macc 12:50", "t": "καὶ ἐπέγνωσαν ὅτι συνελήμφθη καὶ ἀπόλωλεν, καὶ οἱ μετʼ αὐτοῦ· καὶ παρεκάλεσαν ἑαυτούς, καὶ ἐπορεύοντο συνεστραμμένοι ἕτοιμοι εἰς πόλεμον."}, {"sp": "N", "st": "1 Macc 12:51", "t": "καὶ ἴδον οἱ διώκοντες ὅτι περὶ ψυχῆς ἐστιν αὐτοῖς· καὶ ἐπέστρεψαν."}, {"sp": "N", "st": "1 Macc 12:52", "t": "καὶ ἦλθον πάντες μετ᾿ εἰρήνης εἰς γῆν Ἰούδα, καὶ ἐπένθησαν τὸν Ἰωναθὰν καὶ τοὺς μετʼ αὐτοῦ, καὶ ἐφοβήθησαν σφόδρα· καὶ ἐπένθησεν Ἰσραὴλ πένθος μέγα."}, {"sp": "N", "st": "1 Macc 12:53", "t": "καὶ ἐζήτησαν πάντα τὰ ἔθνη τὰ κύκλῳ αὐτῶν ἐκτρίψαι αὐτοὺς· εἶπαν γάρ Οὐκ ἔχουσιν ἄνδρα ἄρχοντα καὶ βοηθοῦντα· νῦν οὖν πολεμήσωμενν αὐτούς, καὶ ἐξαροῦμεν ἐξ ἀνθρόπων τὸ μνημόσυνον αὐτῶν."}, {"sp": "N", "st": "1 Macc 13:1", "t": "Καὶ ἤκουσεν Σίμων ὅτι συνήγαγεν Τρύφων δύναμιν πολλὴν τοῦ ἐλθεῖν εἰς γῆν Ἰούδα τοῦ ἐκτρίψαι αὐτὴν."}, {"sp": "N", "st": "1 Macc 13:2", "t": "καὶ εἶδεν τὸν λαὸν ὅτι ἐστὶν ἔντρομος καὶ ἔκφοβος, καὶ ἀνέβη εἰς Ἰερουσαλὴμ καὶ ἤθροισεν τὸν λαόν·"}, {"sp": "N", "st": "1 Macc 13:3", "t": "καὶ παρεκάλεσεν αὐτούς, καὶ εἶπεν αὐτοῖς Αὐτοὶ οἴδατε ὅσα ἐγὼ καὶ οἱ ἀδελφοί μου καὶ οἶκος τοῦ πατρός μου ἐποιήσαμεν περὶ τῶν νόμων καὶ τῶν ἁγίων, καὶ τοὺς πολέμους καὶ τὰς στενοχαωρίας."}, {"sp": "N", "st": "1 Macc 13:4", "t": "τούτου χάριν ἀπώλοντο οἱ ἀδελφοί μου πάντες χάριν τοῦ Ἰσραήλ, καὶ κατελείφθην ἐγὼ μόνος."}, {"sp": "N", "st": "1 Macc 13:5", "t": "καὶ νῦν μὴ μοι γένοιτο φείσασθαί μου τῆς ψυχῆς ἐν παντὶ καιρῷ θλίψεως· οὐ γάρ εἰμι κρείσσων τῶν ἀδελφῶν μου."}, {"sp": "N", "st": "1 Macc 13:6", "t": "πλὴν ἐκδικήσω περὶ τοῦ ἔθνους μου καὶ περὶ τῶν ἁγίων καὶ περὶ τῶν γυναικῶν καὶ τῶν τέκνων ἡμῶν, ὅτι συνήχθησαν πάντα τὰ ἔθνη ἐκτρίψαι ἡμᾶς ἔχθρας χάριν."}, {"sp": "N", "st": "1 Macc 13:7", "t": "καὶ ἀνεζωπύρισεν τὸ πνεῦμα τοῦ λαοῦ αὐτοῦ ἀκοῦσαι τῶν λόγων τούτων·"}, {"sp": "N", "st": "1 Macc 13:8", "t": "καὶ ἀπεκρίθησαν φωνῇ μεγάλῃ λέγοντες Σὺ εἶ ἡμῶν ἡγούμενος ἀντὶ Ἰούδου καὶ Ἰωνάθου τοῦ ἀδελφοῦ σου·"}, {"sp": "N", "st": "1 Macc 13:9", "t": "πολέμησον τὸν πόλεμον ἡμῶν, καὶ πάντα ὅσα ἐὰν εἴπῃς ἡμῖν ποιήσομεν."}, {"sp": "N", "st": "1 Macc 13:10", "t": "καὶ συνήγαγεν πάντας τοὺς ἄνδρας τοὺς πολεμιστάς, καὶ ἐτάχυνεν τοῦ τελέσαι τὰ τείχη Ἰερουσαλήμ, καὶ ὀχύρωσεν αὐτὴν κυκλόθεν."}, {"sp": "N", "st": "1 Macc 13:11", "t": "καὶ ἀπέστειλεν Ἰωναθὰν τὸν τοῦ Ἀψαλώμου καὶ μετʼ αὐτοῦ δύναμιν ἱκανὴν εἰς Ἰόππην, καὶ ἐξέβαλεν τοὺς ἐν αὐτῇ ὄντας, καὶ ἔμεινεν ἐκεῖ ἐν αὐτῇ."}, {"sp": "N", "st": "1 Macc 13:12", "t": "Καὶ ἀπῆρεν Τρύφων ἀπὸ Πτολεμαίδος μετὰ δυνάμεως πολλῆς εἰσελθεῖν εἰς γῆν Ἰούδα, καὶ Ἰωναθὰν μετʼ αὐτοῦ ἐν φυλακῇ·"}, {"sp": "N", "st": "1 Macc 13:13", "t": "Σίμων δὲ παρενέβαλεν ἐν Ἀδίδοις κατὰ προσώπου τοῦ πεδίου."}, {"sp": "N", "st": "1 Macc 13:14", "t": "καὶ ἐπέγνω Τρύφων ὅτι ἀνέστη Σίμων ἀντὶ Ἰωνάθου τοῦ ἀδελφοῦ αὐτοῦ, καὶ ὅτι συνάπτειν αὐτῷ μέλλει εἰς πόλεμον· καὶ ἀπέστειλεν πρὸς αὐτὸν πρέσβεις, λέγων"}, {"sp": "N", "st": "1 Macc 13:15", "t": "Περὶ ἀργυρίου οὗ ὥφειλεν Ἰωναθὰν ἀδελφός σου εἰς τὸ βασιλικόν, δι᾿ ἃς εἶχεν χρείας. συνέχομεν αὐτόν."}, {"sp": "N", "st": "1 Macc 13:16", "t": "καὶ νῦν ἀπόστειλον ἀργυρίου ἑκατὸν τάλαντα καὶ δύο τῶν υἱῶν αὐτοῦ ὅμηρα, ὅπως μὴ ἀφεθεὶς ἀποστατήσει ἀφʼ ἡμῶν, καὶ ἀφήσομεν αὐτόν."}, {"sp": "N", "st": "1 Macc 13:17", "t": "καὶ ἔγνω Σίμων ὅτι δόλῳ λαλοῦσιν πρὸς αὐτόν, καὶ πέμπει τὸ ἀργύριον καὶ τὰ παιδάρια, καὶ μὴ ποτε ἔχθραν ἄρῃ μεγάλην πρὸς τὸν λαόν,"}, {"sp": "N", "st": "1 Macc 13:18", "t": "λέγοντες Ὅτι οὐκ ἀπέστειλα αὐτῷ τὸ ἀργύριον καὶ τὰ παιδάρια, ἀπώλετο·"}, {"sp": "N", "st": "1 Macc 13:19", "t": "καὶ ἀπέστειλεν τὰ παιδάρια καὶ τὰ ἑκατὸν τάλαντα· καὶ διεψεύσατο, καὶ οὐκ ἀφῆκεν τὸν Ἰωναθάν."}, {"sp": "N", "st": "1 Macc 13:20", "t": "καὶ μετὰ ταῦτα ἦλθεν Τρύφων τοῦ ἐμβατεῦσαι εἰς τὴν πόλιν καὶ ἐκτρίψαι αὐτήν, καὶ ἐκύλωσεν ὁδὸν τὴν εἰς Ἀδωρά· καὶ Σίμων καὶ ἡ παρεμβολὴ αὐτοῦ ἀντιπαρῆγεν αὐτῷ εἰς πάντα τόπον οὗ ἐπορεύετο."}, {"sp": "N", "st": "1 Macc 13:21", "t": "οἱ δὲ ἐκ τῆς ἄκρας ἀπέστελλον πρεσβευτὰς καὶ κατασπεύδοντας αὐτὸν τοῦ ἐλθεῖν πρὸς αὐτὸν διὰ τῆς ἐρήμου καὶ ἀποστεῖλαι αὐτοῖς τροφάς."}, {"sp": "N", "st": "1 Macc 13:22", "t": "καὶ ἡτοίμασεν Τρύφων πᾶσαν τὴν ἵππον αὐτοῦ ἐλθεῖν· καὶ ἐν τῇ νυκτὶ ἐκείνῃ ἤν χιὼν πολλὴ σφόδρα, καὶ οὐκ ἦλθεν διὰ τὴν χιόνα· καὶ ἀπῆρεν καὶ ἦλθεν εἰς τὴν Γαλααδῖτιν."}, {"sp": "N", "st": "1 Macc 13:23", "t": "ὡς δὲ ἤγγισεν τῆς Βασκαμά, ἀπέκτεινεν τὸν Ἰωναθάν, καὶ ἐτάφη ἐκεῖ"}, {"sp": "N", "st": "1 Macc 13:24", "t": "καὶ ἐπέστρεψεν Τρύφων καὶ ἀπῆλθεν εἰς τὴν γῆν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 13:25", "t": "Καὶ ἀπέστειλεν Σίμων, καὶ ἔλαβεν τὰ ὀστᾶ Ἰωναθὰν τοῦ ἀδελφοῦ αὐτοῦ, καὶ ἔθαψεν αὐτὸν ἐν Μωδεείμ πόλει τῶν πατέρων αὐτοῦ."}, {"sp": "N", "st": "1 Macc 13:26", "t": "καὶ ἐκόψαντο αὐτὸν πᾶς Ἰσραὴλ κοπετὸν μέγαν, καὶ ἐπένθησαν αὐτὸν ἡμέρας πολλάς."}, {"sp": "N", "st": "1 Macc 13:27", "t": "καὶ ᾠκοδόμησεν Σίμων ἐπὶ τὸν τάφον τοῦ πατρὸς αὐτοῦ καὶ τῶν ἀδελφῶν αὐτοῦ, καὶ ὕψωσεν αὐτὸν τῇ ὁράσει λίθῳ ξυστῷ ἐκ τῶν ὄπισθεν καὶ ἐκ τῶν ἔμπροσθεν."}, {"sp": "N", "st": "1 Macc 13:28", "t": "καὶ ἔστησεν ἑπτὰ πυραμίδας, μίαν κατέναντι τῆς μιᾶς, τῷ πατρὶ καὶ τῇ μητρὶ καὶ τέσσαρσιν ἀδελφοῖς."}, {"sp": "N", "st": "1 Macc 13:29", "t": "καὶ ταύταις ἐποίησεν μηχανήματα περιθεὶς στύλους μεγάλους, καὶ ἐποίησεν ἐπὶ τοῖς στύλοις πανοπλίας εἰς ὄνομα αἰώνιον, καὶ παρὰ ὁ ταῖς πανοπλίαις πλοῖα ἐπιγεγλυμμένα, εἰς τὸ θεωρεῖσθαι ὑπὸ πάντων τῶν πλεόντων τὴν θάλασσαν."}, {"sp": "N", "st": "1 Macc 13:30", "t": "οὗτος ὁ τάφος ὃν ἐποίησεν ἐν Μωδεεὶμ ἕως τῆς ἡμέρας ταύτης."}, {"sp": "N", "st": "1 Macc 13:31", "t": "Ὁ δὲ Τρύφων ἐπορεύετο δόλῳ μετὰ Ἀντιόχου τοῦ βασιλέως τοῦ νεωτέρου, καὶ ἀπέκτεινεν αὐτόν,"}, {"sp": "N", "st": "1 Macc 13:32", "t": "καὶ ἐβασίλευσεν ἀντʼ αὐτοῦ, καὶ περιέθετο τὸ διάδημα τῆς Ἀσίας, καὶ ἐποίησεν πληγὴν μεγάλην ἐπὶ τῆς γῆς."}, {"sp": "N", "st": "1 Macc 13:33", "t": "Καὶ ᾠκοδόμησεν Σίμων τὸ ὀχύρωμα τῆς Ἰουδαίας, καὶ περιετείχισεν πύργοις ὑψηλοῖς καὶ τείχεσιν μεγάλοις καὶ πύργοις καὶ πύλαις καὶ μοχλοῖς, καὶ ἔθετο βρώματα ἐν τοῖς ὀχυρώμασιν."}, {"sp": "N", "st": "1 Macc 13:34", "t": "καὶ ἐπελέξατο Σίμων ἄνδρας, καὶ ἀπέστειλεν πρὸς Δημήτριον τὸν βασιλέα τοῦ ποιῆσαι ἄφεσιν τῇ χώρᾳ, ὅτι πᾶσαι αἱ πράξεις Τρύφωνος ἦσαν ἁρπάσαι."}, {"sp": "N", "st": "1 Macc 13:35", "t": "καὶ ἀπέστειλεν αὐτῷ Δημήτριος ὁ βασιλεὺς κατὰ τοὺς λόγους τούτους, καὶ ἀπεκρίθη αὐτῷ, καὶ ἔγραψεν αὐτῷ ἐπιστολὴν τοιαύτην"}, {"sp": "N", "st": "1 Macc 13:36", "t": "Βασιλεὺς Δημήτριος Σίμωνι ἀρχιερεῖ καὶ φίλῳ βασιλέων καὶ πρεσβυτέροις καὶ ἔθνει Ἰουδαίων χαίρειν."}, {"sp": "N", "st": "1 Macc 13:37", "t": "τὸν στέφανον τὸν χρυσοῦν, καὶ τὴν βάιν ἣν ἀπεστείλατε, κεκομίσμεθα, καὶ ἕτοιμοί ἐσμεν τοῦ ποιεῖν ὑυῖν εἰρήνην μεγάλην, καὶ γράφειν τοῖς ἐπὶ τῶν χρειῶν τοῦ ἀφεῖναι ὑμῖν ἀφέματα."}, {"sp": "N", "st": "1 Macc 13:38", "t": "καὶ ὅσα ἐστήσαμεν πρὸς ὑμᾶς ἕστηκεν, καὶ τὰ ὀχυρώματα, ἃ ᾠκοδομήσατε, ὑπαρχέτω ὑμῖν."}, {"sp": "N", "st": "1 Macc 13:39", "t": "ἀφίεμεν δέ ὑμῖν ἀγνοήματα καὶ τὰ ἁμαρτήματα ἕως τῆς σήμερον ἡμέρας, καὶ τὸν στέφανον ὃν ὠφείλετε· καὶ εἵ τι ἄλλο ἐτελωνεῖτο ἐν Ἰερουσαλήμ, μηκέτι τελωνείσθω·"}, {"sp": "N", "st": "1 Macc 13:40", "t": "καὶ εἵ τινες ἐπιτήδειοι ὑμῶν γραφῆναι εἰς τοὺς περὶ ἡμᾶς, ἐνγραφέσθωσαν, καὶ γινέσθω ἀνὰ μέσον ἡμῶν εἰρήνη."}, {"sp": "N", "st": "1 Macc 13:41", "t": "Ἔτους ἑκατοστοῦ ἑβδομηκοστοῦ ἤρθη ὁ ζυγὸς τῶν ἐθνῶν ἀπὸ τοῦ Ἰσραήλ."}, {"sp": "N", "st": "1 Macc 13:42", "t": "καὶ ἤρξατο ὁ λαὸς Ἰσραὴλ γράφειν ἐν ταῖς συνγραφαῖς καὶ συναλλάγμασιν Ἔτους πρώτου ἐπὶ Σίμωνος ἀρχιερέως μεγάλου καὶ στρατηγοῦ καὶ ἡγουμένου Ἰουδαίων."}, {"sp": "N", "st": "1 Macc 13:43", "t": "Ἐν ταῖς ἡμέραις ἐκείναις παρενέβαλεν ἐπὶ Γάζαν, καὶ ἐκύκλωσεν αὐτὴν παρεμβολαῖς, καὶ ἐποίησεν ἑλέπολιν καὶ προσήγαγεν τῇ πόλει, καὶ ἐπάταξεν πύργον ἕνα, καὶ κατελάβετο."}, {"sp": "N", "st": "1 Macc 13:44", "t": "καὶ ἐξήλλοντο οἱ ἐν τῇ ἑλεπόλει εἰς τὴν πόλιν, καὶ ἐγένετο κίνημα μέγα ἐν τῇ πόλει."}, {"sp": "N", "st": "1 Macc 13:45", "t": "καὶ ἀνέβησαν οἱ ἐν τῇ πόλει σὺν ταῖς γυναιξὶ καὶ τοῖς τέκνοις ἐπὶ τὸ τεῖχος διερρηχότες τὰ ἱμάτια αὐτῶν, καὶ ἐβόησαν φωνῇ μεγάλῃ ἀξιοῦντες Σίμωνα δεξιὰς αὐτοῖς δοῦναι."}, {"sp": "N", "st": "1 Macc 13:46", "t": "καὶ εἶπαν Μὴ ἡμῖν χρήσῃ κατὰ τὰς πονηρίας ἡμῶν, ἀλλὰ κατὰ τὸ ἔλεὸς σου."}, {"sp": "N", "st": "1 Macc 13:47", "t": "καὶ συνελύθη αὐτοῖς Σίμων, καὶ οὐκ ἐπολέμησεν αὐτούς· καὶ ἐξέβαλεν αὐτοὺς ἐκ τῆς πόλεως, καὶ ἐκαθέρισεν τὰς οἰκίας ἐν αἷς ἦν τὰ εἴδωλα, καὶ οὕτως εἰσῆλθεν εἰς αὐτὴν ὑμνῶν καὶ εὐλογῶν."}, {"sp": "N", "st": "1 Macc 13:48", "t": "καὶ ἐξέβαλεν ἐξ αὐτῆς πᾶσαν ἀκαθαρσίαν, καὶ κατοίκισεν ἐν αὐτῇ ἄνδρας οἵτινες τὸν νόμον ποιοῦσιν· καὶ προσοχύρώσεν αὐτήν, καὶ ᾠκοδόμησεν ἑαυτῷ ἐν αὐτῇ οἴκησιν."}, {"sp": "N", "st": "1 Macc 13:49", "t": "Οἰ δὲ ἐκ τῆς ἄκρας ἐν Ἰερουσαλὴμ ἐκωλύοντο ἐκπορεύεσθαι εἰς τὴν χώραν καὶ ἀγοράζειν καὶ πωλεῖν· καὶ ἐπείνασαν σφόδρα, καὶ ἀπώλοντο ἐξ αὐτῶν ἱκανοὶ τῇ λιμῷ."}, {"sp": "N", "st": "1 Macc 13:50", "t": "καὶ ἐβόησαν πρὸς Σίμωνα δεξιὰς λαβεῖν, καὶ ἔδωκεν αὐτοῖς, καὶ ἐξέβαλεν αὐτοὺς ἐκεῖθεν, καὶ ἐκαθέρισεν τὴν ἄκραν ἀπὸ τῶν μιασμάτων."}, {"sp": "N", "st": "1 Macc 13:51", "t": "καὶ εἰσῆλθεν εἰς αὐτὴν τῇ τρίτῃ καὶ εἰκάδι τοῦ δευτέρου μηνὸς ἔτους ἑνὸς καὶ ἑβδομηκοστοῦ καὶ ἑκατοστοῦ μετὰ αἰνέσεως καὶ βαίων καὶ ἐν κινύραις καὶ ἐν κυμβάλοις καὶ ἐν νάβλαις καὶ ἐν ὕμνοις καὶ ἐν ᾠδαῖς, ὅτι συνετρίβη ἐχθρὸς μέγας ἐξ Ἰσραήλ·"}, {"sp": "N", "st": "1 Macc 13:52", "t": "καὶ ἔστησεν κατʼ ἐνιαυτὸν τοῦ ἄγειν τὴν ἡμέραν ταύτην. καὶ προσωχύρωσεν τὸ ὄρος τοῦ ἱεροῦ τὸ παρὰ τὴν ἄκραν, καὶ ᾤκει ἐκεῖ αὐτὸς καὶ οἱ παρʼ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 13:53", "t": "καὶ ἴδεν Σίμων τὸν Ἰωάννην τὸν υἱὸν αὐτοῦ, ὅτι ἀνήρ ἐστιν, καὶ ἔθετο αὐτὸν ἡγούμενον τῶν δυνάμεων πασῶν· καὶ ᾤκει ἐν Γαζάροις."}, {"sp": "N", "st": "1 Macc 14:1", "t": "Καὶ ἐν ἔτει δευτέρῳ καὶ ἑβδομηκοστῷ καὶ ἑκατοστῷ συνήγαγεν Δημήτριος ὁ βασιλεὺς τὰς δυνάμεις αὐτοῦ, καὶ ἐπορεύθη εἰς Μηδίαν, τοῦ ἐπισπᾶσθαι βοήθειαν ἑαυτῷ, ὄπως πολεμήσῃ τὸν Τρύφωνα."}, {"sp": "N", "st": "1 Macc 14:2", "t": "καὶ ἤκουσεν Ἀρσάκης ὁ βασιλεὺς Περσίδος καὶ Μηδίας ὅτι ἦλθεν Δημήτριος εἰς τὰ ὅρια αὐτοῦ, καὶ ἀπέστειλεν ἕνα τῶν ἀρχόντων αὐτοῦ συλλαβεῖν αὐτὸν ζῶντα."}, {"sp": "N", "st": "1 Macc 14:3", "t": "καὶ ἐπορεύθη καὶ ἐπάταξεν τὴν παρεμβολὴν Δημητρίου καὶ συνέλαβεν αὐτόν, καὶ ἤγαγεν αὐτὸν πρὸς Ἀρσάκην, καὶ ἔθετο αὐτὸν ἐν φυλακῆ."}, {"sp": "N", "st": "1 Macc 14:4", "t": "Καὶ ἡσύχασεν ἡ γῆ πάσας τὰς ἡμέρας Σίμωνος, καὶ ἐζήτησεν ἀγαθὰ τῷ ἔθνει αὐτοῦ· καὶ ἤρεσεν αὐτοῖς ἡ ἐξουσία αὐτοῦ καὶ ἡ δόξα αὐτοῦ πάσας τὰς ἡμέρας"}, {"sp": "N", "st": "1 Macc 14:5", "t": "καὶ μετὰ πάσης τῆς δόξης αὐτοῦ ἔλαβεν τὴν Ἰόππην εἰς λιμένα, καὶ ἐποίησεν εἴσοδον ταῖς νήσοις τῆς θαλάσσης."}, {"sp": "N", "st": "1 Macc 14:6", "t": "καὶ ἐπλάτυνεν τὰ ὅρια τῷ ἔθνει αὐτοῦ, καὶ ἐκράτησεν τῆς χώρας."}, {"sp": "N", "st": "1 Macc 14:7", "t": "καὶ συνήγαγεν αἰχμαλωσίαν πολλήν, καὶ ἐκυρίευσεν Γαζάρων καὶ Βεθσούρων καὶ τῆς ἄκρας· καὶ ἐξῆρεν τὰς ἀκαθαρσίας ἐξ αὐτῆς, καὶ οὐκ ἦν ὁ ἀντικείμενος αὐτῷ."}, {"sp": "N", "st": "1 Macc 14:8", "t": "καὶ ἦσαν γεωργοῦντες τὴν γῆν αὐτῶν μετʼ εἰρήνης, καὶ ἡ γῆ ἐδίδου τὰ γενήματα αὐτῆς, καὶ τὰ ξύλα τῶν πεδίων τὸν καρπὸν αὐτῶν."}, {"sp": "N", "st": "1 Macc 14:9", "t": "πρεσβύτεροι ἐν ταῖς πλατείαις ἐκάθηντο, πάντες περὶ ἀγαθῶν ἐκοινολόγουν, καὶ οἱ νεανίσκοι ἐνεδύσαντο δόξας καὶ στολὰς πολέμου."}, {"sp": "N", "st": "1 Macc 14:10", "t": "ταῖς πόλεσιν ἐχορήγησεν βρώματα, καὶ ἔταξεν αὐτὰς ἐν σκεύεσιν ὀχυρώσεως, ἕως ὅτου ὀνομάσθη τὸ ὄνομα τῆς δόξης αὐτοῦ ἕως ἄκρου γῆς·"}, {"sp": "N", "st": "1 Macc 14:11", "t": "ἐποίησεν τὴν εἰρήνην ἐπὶ τῆς γῆς, καὶ ηὐφράνθη Ἰσραὴλ εὐφροσύνην μεγάλην."}, {"sp": "N", "st": "1 Macc 14:12", "t": "καὶ ἐκάθισεν ἕκαστος ὑπὸ τὴν ἄμπελον αὐτοῦ καὶ τὴν συκῆν αὐτοῦ, καὶ οὐκ ἦν ὁ ἐκφοβῶν αὐτούς·"}, {"sp": "N", "st": "1 Macc 14:13", "t": "καὶ ἐξέλειπεν πολεμῶν αὐτοὺς ἐπὶ τῆς γῆς, καὶ οἱ βασιλεῖς αὐτῶν συνε τρίβησαν ἐν ταῖς ἡμέραις ἐκείναις."}, {"sp": "N", "st": "1 Macc 14:14", "t": "καὶ ἐστήρισεν πάντας τοὺς ταπεινοὺς τοῦ λαοῦ αὐτοῦ· τὸν νόμον ἐξεζήτησεν, καὶ ἐξῆρεν πάντα ἄνομον καὶ πονηρόν·"}, {"sp": "N", "st": "1 Macc 14:15", "t": "τὰ ἅγια ἐδόξασεν, καὶ ἐπλήθυνεν τὰ σκεύη τῶν ἁγίων."}, {"sp": "N", "st": "1 Macc 14:16", "t": "Καὶ ἤκουσεν ἐν Ῥώμῃ ὅτι ἀπέθανεν Ἰωναθάν, καὶ ἕως Σπάρτης. καὶ ἐλυπήθησαν σφόδρα."}, {"sp": "N", "st": "1 Macc 14:17", "t": "ὡς δὲ ἤκουσαν ὅτι Σίμων ὁ ἀδελφὸς αὐτοῦ γέγονεν ἀντʼ αὐτοῦ ἀρχιερεὺς καὶ ἐπικρατεῖ τῆς χώρας καὶ τῶν πόλεων τῶν ἐν αὐτῇ,"}, {"sp": "N", "st": "1 Macc 14:18", "t": "καὶ ἔγραψαν πρὸς αὐτὸν δέλτοις χαλκαῖς τοῦ ἀνανεώσασθαι πρὸς αὐτὸν φιλίαν καὶ τὴν συμμαχίαν ἣν ἔστησαν πρὸς Ἰούδαν καὶ Ἰωναθὰν τοὺς ἀδελφοὺς αὐτοῦ."}, {"sp": "N", "st": "1 Macc 14:19", "t": "καὶ ἀνεγνώσθησαν ἐνώπιον ἐκκλησίας ἐν Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Macc 14:20", "t": "καὶ τοῦτο τὸ ἀντίγραφον τῶν ἐπιστολῶν ὧν ἀπέστειλαν οἱ Σπαρτιᾶται Σπαρτιατῶν ἄρχοντες καὶ ἡ πόλις Σίμωνι ἱερεῖ μεγάλῳ καὶ τοῖς πρεσβυτέροις καὶ τοῖς ἱερεῦσι καὶ τῷ λοιπῷ δήμῳ τῶν Ἰουδαίων ἀδελφοῖς χαίρειν."}, {"sp": "N", "st": "1 Macc 14:21", "t": "οἱ πρεσβευταὶ οἱ ἀποσταλέντες πρὸς τὸν δῆμον ἡμῶν ἀπήγγειλαν ἡμῖν περὶ τῆς δόξης ὑμῶν καὶ τιμῆς, καὶ ηὐφράνθημεν ἐπὶ τῇ ἐφόδῳ αὐτῶν."}, {"sp": "N", "st": "1 Macc 14:22", "t": "καὶ ἀναγραψάμενοι τὰ ὑπʼ αὐτῶν εἰρημένα ἐν ταῖς βουλαῖς τοῦ δήμου οὕτως Νουμήνιος Ἀντιόχου καὶ Ἀντίπατρος Ἰάσονος πρεσβευταὶ Ἰουδαίων ἤλθοσαν πρὸς ἡμᾶς ἀνανεούμενοι τὴν πρὸς ἡμᾶς φιλίαν·"}, {"sp": "N", "st": "1 Macc 14:23", "t": "καὶ ἤρεσεν τῷ δήμῳ ἐπιδέξασθαι τοὺς ἄνδρας ἐνδόξως, καὶ τοῦ θέσθαι τὸ ἀντίγραφον τῶν λόγων αὐτῶν ἐν τοῖς ἀποδεδιγμένοις τῷ δήμῳ βιβλίοις, τοῦ μνημόσυνον ἔχειν τὸν δῆμον τῶν Σπαρτιατῶν· τὸ δὲ ἀντίγραφον τούτων ἔγραψαν Σίμωνι τῷ ἀρχιερεῖ."}, {"sp": "N", "st": "1 Macc 14:24", "t": "Μετὰ ταῦτα ἀπέστειλεν Σίμων τὸν Νουμήνιον εἰς Ῥώμην ἔχοντα ἀσπίδα χρυσῆν μεγάλην ὁλκὴν μνῶν χιλίων, εἰς τὸ στῆσαι πρὸς αὐτοὺς τὴν συμμαχίαν."}, {"sp": "N", "st": "1 Macc 14:25", "t": "Ὡς δὲ ἤκουσεν ὁ δῆμος τῶν λόγων τούτων, εἶπαν Τίνα χάριν ἀποδώσομεν Σίμωνι καὶ τοῖς υἱοῖς αὐτοῦ;"}, {"sp": "N", "st": "1 Macc 14:26", "t": "ἐστήρισεν γὰρ αὐτὸς καὶ οἱ ἀδελφοὶ αὐτοῦ καὶ ὁ οἶκος τοῦ πατρὸς αὐτοῦ, καὶ ἐπολέμησαν τοὺς ἐχθροὺς Ἰσραὴλ ἀπʼ αὐτῶν. καὶ ἔστησαν αὐτῷ ἐλευθερίαν, καὶ κατέγραψεν ἐν δέλτοις χαλκαῖς, καὶ ἔθεντο ἐν στήλῃ ἐν ὄρει Σιών."}, {"sp": "N", "st": "1 Macc 14:27", "t": "καὶ τοῦτο τὸ ἀντίγραφον τῆς γραφῆς Ὀκτωκαιδεκάτῃ Ἐλούλ, ἔτους δευτέρου ἑβδομηκοστοῦ καὶ ἑκατοστοῦ, καὶ τοῦτο τρίτον ἔτος ἐπὶ Σίμωνος τοῦ ἀρχιερέως,"}, {"sp": "N", "st": "1 Macc 14:28", "t": "ἐν Σαραμέλ, ἐπὶ συναγωγῆς μεγάλης τῶν ἱερέων καὶ λαοῦ καὶ ἀρχόντων ἔθνους καὶ τῶν πρεσβυτέρων τῆς χώρας ἐγνώρισεν ἡμῖν."}, {"sp": "N", "st": "1 Macc 14:29", "t": "ἐπεὶ πολλάκις ἐγενήθησαν πόλεμοι ἐν τῇ χώρᾳ, Σίμων δὲ ὁ υἱὸς Ματταθίου ὁ υἱὸς τῶν υἱῶν Ἰωαρίβ καὶ οἱ ἀδελφοὶ αὐτοῦ ἔδωκαν ἐαυτοὺς τῷ κινδύνῳ, καὶ ἀντέστησαν τοῖς ὑπεναντίοις τοῦ ἔθνους αὐτῶν, ὅπως σταθῇ τὰ ἅγια αὐτῶν καὶ ὁ νόμος, καὶ δόξῃ μεγάλῃ ἐδόξασαν τὸ ἔθνος αὐτῶν·"}, {"sp": "N", "st": "1 Macc 14:30", "t": "καὶ ἤθροισεν Ἰωναθὰν τὸ ἔθνος αὐτῶν, καὶ ἐγενήθη αὐτοῖς ἀρχιερεύς, καὶ προσετέθη πρὸς τὸν λαὸν αὐτοῦ·"}, {"sp": "N", "st": "1 Macc 14:31", "t": "καὶ ἐβουλήθησαν οἱ ἐχθροὶ αὐτῶν ἐμβατεῦσαι εἰς τὴν χώραν αὐτῶν τοῦ ἐκτρίψαι τὴν χώραν αὐτῶν, καὶ ἐκτεῖναι τὰς χεῖρας ἐπὶ τὰ ἅγια αὐτῶν·"}, {"sp": "N", "st": "1 Macc 14:32", "t": "τότε ἀνέστη Σίμων, καὶ ἐπολέμησεν περὶ τοῦ ἔθνους αὐτοῦ, καὶ ἐδαπάνησεν χρήματα πολλὰ τῶν ἑαυτοῦ, καὶ ὁπλοδότησεν τοὺς ἄνδρας τῆς δυνάμεως τοῦ ἔθνους αὐτοῦ, καὶ ἔδωκεν αὐτοῖς ὀψώνια·"}, {"sp": "N", "st": "1 Macc 14:33", "t": "καὶ ὠχύρωσεν τὰς πόλεις τῆς Ἰουδαίας καὶ τὴν Βεθσούραν τὴν ἐπὶ τῶν ὁρίων τῆς Ἰουδαίας, οὗ ἦν τὰ ὅπλα τῶν πολεμίων τὸ πρότερον, καὶ ἔθετο ἐκεῖ φρουρὰν ἄνδρας Ἰουδαίους·"}, {"sp": "N", "st": "1 Macc 14:34", "t": "καὶ Ἰόππην ὠχύρωσεν τὴν ἐπὶ τῆς θαλάσσης, καὶ τὴν Γαζάραν τὴν ἐπὶ τῶν ὁρίων Ἀζώτου, ἐν ᾗ ᾠκοῦσαν οἱ πολέμιοι τὸ πρότερον ἐκεῖ, καὶ κατῴκισεν ἐκεῖ Ἰουδαίους, καὶ ὅσα ἐπιτήδεια πρὸς τῇ τούτων ἐπανορθώσει ἔθετο ἐν αὐτοῖς."}, {"sp": "N", "st": "1 Macc 14:35", "t": "καὶ εἶδεν ὁ λαὸς τὴν πίστιν τοῦ Σίμωνος καὶ τὴν δόξαν ἣν ἐβουλεύσατο ποιῆσαι τῷ ἔθνει αὐτοῦ, καὶ ἔθεντο αὐτὸν ἡγούμενον αὐτῶν καὶ ἀρχιερέα, διὰ τὸ πεποιηκέναι αὐτὸν ταῦτα πάντα, καὶ τὴν δικαιοσύνην καὶ τὴν πίστιν ἣν συνετήρησεν τῷ ἔθνει αὐτοῦ, καὶ ἐξεζήτησεν παντὶ τρόπῳ ὑψῶσαι τὸν λαὸν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 14:36", "t": "καὶ ἐν ταῖς ἡμέραις αὐτοῦ εὐοδώθη ἐν ταῖς χερσὶν αὐτοῦ, τοῦ ἐξαρθῆναι τὰ ἔθνη ἐκ τῆς χώρας αὐτῶν, καὶ τοὺς ἐν τῇ πόλει Δαυεὶδ τοὺς ἐν Ἰερουσαλὴμ οἳ ἐποίησαν ἑαυτοῖς ἄκραν ἐξ ἧς ἐξεπορεύοντο, καὶ ἐμίαινον κύκλῳ τῶν ἁγίων, καὶ ἐποιοῦσαν πληγὴν μεγάλην ἐν τῇ ἁγνείᾳ·"}, {"sp": "N", "st": "1 Macc 14:37", "t": "καὶ κατῴκισεν ἐν αὐτῇ ἄνδρας Ἰουδαίους, καὶ ὠχύρωσεν αὐτὴν πρὸς ἀσφάλειαν τῆς χώρας καὶ τῆς πόλεως, καὶ ὕψωσεν τὰ τείχη Ἰερουσαλήμ."}, {"sp": "N", "st": "1 Macc 14:38", "t": "καὶ ὁ βασιλεὺς Δημήτριος ἔστησεν αὐτῷ τὴν ἀρχιερωσύνην κατὰ ταῦτα,"}, {"sp": "N", "st": "1 Macc 14:39", "t": "καὶ ἐποίησεν αὐτὸν τῶν φίλων αὐτοῦ, καὶ ἐδόξασεν αὐτὸν δόξῃ μεγάλῃ·"}, {"sp": "N", "st": "1 Macc 14:40", "t": "ἠκούσθη γὰρ ὅτι προσαγορεύονται Ἰουδαῖοι ὑπὸ Ῥωμαίων φίλοι καὶ σύμμαχοι καὶ οἱ ἀδελφοί, καὶ ὅτι ἀπήντησαν τοῖς πρεσβευταῖς Σίμωνος ἐνδόξως·"}, {"sp": "N", "st": "1 Macc 14:41", "t": "καὶ ὅτι οἱ Ἰουδαῖοι καὶ οἱ ἱερεῖς εὐδόκησαν τοῦ εἶναι αὐτῶν Σίμωνα ἡγούμενον καὶ ἀρχιερέα εἰς τὸν αἰῶνα, ἕως τοῦ ἀναστῆναι προφήτην πιστόν·"}, {"sp": "N", "st": "1 Macc 14:42", "t": "καὶ τοῦ εἶναι ἐπʼ αὐτῶν στρατηγόν, καὶ ὅπως μέλῃ αὐτῷ περὶ τῶν ἁγίων, καθιστάναι δι᾿ αὐτοῦ ἐπὶ τῶν ἔργων αὐτῶν καὶ ἐπὶ τῆς χώρας καὶ ἐπὶ τῶν ὅπλων καὶ ἐπὶ τῶν ὀχυρωμάτων·"}, {"sp": "N", "st": "1 Macc 14:43", "t": "καὶ ὅπως μέλη αὐτῷ περὶ τῶν ἁγίων, καὶ ὅπως ἀκούηται ὑπὸ πάντων, καὶ ὅπως γράφωνται ἐπὶ τῷ ὀνόματι αὐτοῦ πᾶσαι συγγραφαὶ ἐν τῇ χώρᾳ, καὶ ὅπως περιβάλληται πορφύραν καὶ χρυσοφορῇ."}, {"sp": "N", "st": "1 Macc 14:44", "t": "καὶ οὐκ ἔξεστιν οὐδενὶ τοῦ λαοῦ καὶ τῶν ἱερέων ἀθετῆσαί τι τούτων καὶ ἀντειπεῖν τοῖς ὑπʼ αὐτοῦ ῥηθησομένοις, καὶ ἐπισυστρέψαι συστροφὴν ἐν τῇ χώρᾳ ἄνευ αὐτοῦ, καὶ περιβαλέσθαι πορφύραν καὶ ἐνπορποῦσθαι πόρπην χρυσῆν·"}, {"sp": "N", "st": "1 Macc 14:45", "t": "ὃ δʼ ἂν παρὰ ταῦτα ποιήσῃ ἡ ἀθετήσῃ τι τούτων, ἔνοχος ἔσται."}, {"sp": "N", "st": "1 Macc 14:46", "t": "καὶ εὐδόκησεν πᾶς ὁ λαὸς θέσθαι Σίμωνι ποιῆσαι κατὰ τοὺς λόγους τούτους."}, {"sp": "N", "st": "1 Macc 14:47", "t": "καὶ ἐπεδέξατο Σίμων, καὶ εὐδόκησεν ἀρχιερατεῦσαι καὶ εἶναι στρατηγὸς καὶ ἐθνάρχης τῶν Ἰουδαίων καὶ ἱερέων καὶ τοῦ προστατῆσαι πάντων."}, {"sp": "N", "st": "1 Macc 14:48", "t": "Καὶ τὴν γραφὴν ταύτην εἶπαν θέσθαι ἐν δέλτοις χαλκαῖς, καὶ στῆσαι αὐτὰς ἐν περιβόλῳ τῶν ἁγίων ἐν τόπῳ πιστῷ·"}, {"sp": "N", "st": "1 Macc 14:49", "t": "τὰ δὲ ἀντίγραφα αὐτῶν θέσθαι ἐν τῷ γαζοφυλακίῳ, ὅπως ἔχῃ Σίμων καὶ οἱ υἱοὶ αὐτοῦ."}, {"sp": "N", "st": "1 Macc 15:1", "t": "Καὶ ἀπέστειλεν Ἀντίοχος υἱὸς Δημητρίου τοῦ βασιλέως ἐπιστολὰς ἀπὸ τῶν νήσων τῆς θαλάσσης Σίμωνι ἱερεῖ καὶ ἐθνάρχῃ τῶν Ἰουδαίων καὶ παντὶ τῷ ἔθνει."}, {"sp": "N", "st": "1 Macc 15:2", "t": "καὶ ἦσαν περιέχουσαι τὸν τρόπον τοῦτον Βασιλεὺς Ἀντίοχος Σίμωνι ἱερεῖ μεγάλῳ καὶ ἐθνάρχῃ καὶ ἔθνει Ἰουδαίων χαίρειν."}, {"sp": "N", "st": "1 Macc 15:3", "t": "ἐπειδή τινες λοιμοὶ κατεκράτησαν τῆς βασιλείας τῶν πατέρων ἡμῶν, βουλεύομαι δὲ ἀντιποιήσασθαι τῆς βασιλείας, ὅπαως ἀποκαταστήσω αὐτὴν ὡς ἦν τὸ πρότερον· ἐξενολόγησα δὲ πλῆθος δυνάμεων καὶ κατεσκεύασα πλοῖα πολεμικά·"}, {"sp": "N", "st": "1 Macc 15:4", "t": "βούλομαι δὲ ἐκβῆναι κατὰ τὴν χώραν, ὅπως μετέλθω τοὺς κατεφθαρκότας τὴν χώραν ἡμῶν καὶ τοὺς ἠρημωκότας πόλεις πολλὰς ἐν τῇ βασιλεία·"}, {"sp": "N", "st": "1 Macc 15:5", "t": "νῦν οὗν ἵστημί σοι πάντα τὰ ἀφαιρέματα ἃ ἀφῆκάν σοι οἱ πρὸ ἐμοῦ βασιλεῖς, καὶ ὅσα ἄλλα ἀφαιρέματα ἀφῆκάν σοι"}, {"sp": "N", "st": "1 Macc 15:6", "t": "ποιῆσαι κόμμα ἴδιον νόμισμα τῆς χώρας σου·"}, {"sp": "N", "st": "1 Macc 15:7", "t": "Ἰερουσαλὴμ δέ καὶ τὰ ἅγια εἶναι ἐλεύθερα· καὶ πάντα τὰ ὅπλα ὅσα κατεσκεύασας, καὶ τὰ ὀχυρώματα ἃ ᾠκοδόμησας, ὅν κρατεῖς, μενέτω σοι."}, {"sp": "N", "st": "1 Macc 15:8", "t": "καὶ πᾶν ὀφείλημα βασιλικὸν καὶ τὰ ἐσόμενα βασιλικά, ἀπὸ τοῦ νῦν καὶ εἰς τὸν ἅπαντα χρόνον, ἀφιέσθω σοι."}, {"sp": "N", "st": "1 Macc 15:9", "t": "ὡς δʼ ἃν καταστήσωμεν τὴν βασιλείαν ἡμῶν, δοξάσωμέν σε καὶ τὸ ἔθνος σου καὶ τὸ ἱερὸν δόξῃ μεγάλῃ, ὥστε φανερὰν γενέσθαι τὴν δόξαν ὑμῶν ἐν πάσῃ τῇ ῆ."}, {"sp": "N", "st": "1 Macc 15:10", "t": "Ἔτους τετάρτου καὶ ἑβδομηκοστοῦ καὶ ἑκατοστοῦ ἐξῆλθεν Ἀντίοχος εἰς τὴν γῆν τῶν πατέρων αὐτοῦ, καὶ συνῆλθον πρὸς αὐτὸν πᾶσαι αἱ δυνάμεις, ὥστε ὀλίγους εἶναι σὺν Τρύφωνι."}, {"sp": "N", "st": "1 Macc 15:11", "t": "καὶ ἐδίωξεν αὐτὸν Ἀντίοχος ὁ βασιλεύς, καὶ ἦλθεν εἰς Δωρὰ φεύγων τὴν ἐπὶ τὴν θάλασσαν."}, {"sp": "N", "st": "1 Macc 15:12", "t": "ᾔδει γὰρ ὅτι ἐπισυνῆκται ἐπʼ αὐτὸν κακά, καὶ ἀφῆκαν αὐτὸν αἱ δυνάμεις."}, {"sp": "N", "st": "1 Macc 15:13", "t": "καὶ παρενέβαλεν Ἀντίοχος ἐπὶ Δωρά, καὶ σὺν αὐτῷ δώδεκα μυριάδες ἀνδρῶν πολεμιστῶν καὶ ὀκτακισχιλία ἵππος."}, {"sp": "N", "st": "1 Macc 15:14", "t": "καὶ ἐκύκλωσεν τὴν πόλιν, καὶ τὰ πλοῖα ἀπὸ θαλάσσης συνῆψαν· καὶ συνέθλιβεν τὴν πόλιν ἀπὸ τῆς γῆς καὶ ἀπὸ τῆς θαλάσσης, καὶ οὐκ εἴασεν οὐδένα ἐκπορεύεσθαι καὶ εἰσπορεύεσθαι."}, {"sp": "N", "st": "1 Macc 15:15", "t": "Καὶ ἦλθεν Νουμήνιος καὶ οἱ παρʼ αὐτοῦ ἐκ Ῥώμης ἔχοντες ἐπιστολὰς τοῖς βασιλεῦσι καὶ ταῖς χώραις, ἐν αἷς ἐγέγραπτο τάδε"}, {"sp": "N", "st": "1 Macc 15:16", "t": "Λεύκιος ὕπατος Ῥωμαίων Πτολεμαίῳ βασιλεῖ χαίρειν."}, {"sp": "N", "st": "1 Macc 15:17", "t": "οἱ πρεσβευταὶ τῶν Ἰουδαίων ἦλθαν πρὸς ἡμᾶς φίλοι ἡμῶν καὶ σύμμαχοι, ἀνανεούμενοι τὴν ἐξ ἀρχῆς φιλίαν ακὶ συμμαχίαν, ἀπεσταλμένοι ἀπὸ Σίμωνος τοῦ ἀρχιερέως καὶ τοῦ δήμου τῶν Ἰουδαίων·"}, {"sp": "N", "st": "1 Macc 15:18", "t": "ἤνεγκαν δὲ ἀσπίδα χρυσῆν ἀπὸ μνῶν πεντακισχιλίων."}, {"sp": "N", "st": "1 Macc 15:19", "t": "ἤρεσεν οὖν ἡμῖν γράψαι τοῖς βασιλεῦσιν καὶ ταῖς χώραις, ὅπως μὴ ἐκζητήσωσιν αὐτοῖς κακά, καὶ μὴ πολεμήσωσιν αὐτοὺς καὶ τὰς πόλεις αὐτῶν καὶ τὰς χώρας αὐτῶν, καὶ ἵνα μὴ συμμαχῶσιν τοῖς πολεμοῦσιν αὐτοὺς."}, {"sp": "N", "st": "1 Macc 15:20", "t": "ἔδοξεν δὲ ἡμῖν δέξασθαι τὴν ἀσπίδα παρʼ αὐτῶν."}, {"sp": "N", "st": "1 Macc 15:21", "t": "εἴ τινες οὗν λοιμοὶ διαπεφεύγασιν ἐκ τῆς χώρας αὐτῶν πρὸς ὑμᾶς, παράδοτε αὐτοὺς τῷ Σίμωνι τῷ ἀρχιερεῖ, ὅπως ἐκδικήσει αὐτοὺς κατὰ τὸν νόμον αὐτῶν."}, {"sp": "N", "st": "1 Macc 15:22", "t": "καὶ ταὐτὰ ἔγραψεν Δημητρίῳ τῷ βασιλεῖ καὶ Ἀττάλῳ καὶ Ἀράθῃ καὶ Ἀρσάκῃ,"}, {"sp": "N", "st": "1 Macc 15:23", "t": "καὶ εἰς πάσας τὰς χώρας, καὶ Σαμψάκῃ, καὶ Σπαρτιάταις, καὶ εἰς Δῆλον καὶ εἰς Μύνδον καὶ εἰς Σικυῶνα καὶ εἰς τὴν Καρίδα καὶ εἰς Σάμον καὶ εἰς τὴν Παμφυλίαν καὶ Λυκίαν καὶ εἰς Ἀλικαρνασσὸν καὶ εἰς Κῶ καὶ εἰς Σίδην καὶ εἰς Ἄραδον καὶ εἰς Ῥόδον καὶ εἰς τὴν Φασήλιδα καὶ Γόρτυναν καὶ Κνίδον καὶ Κύπρον καὶ Κυρήνην."}, {"sp": "N", "st": "1 Macc 15:24", "t": "τὸ δὲ ἀντίγραφον αὐτῶν ἔγραψεν Σίμωνι τῷ ἀρχιερεῖ."}, {"sp": "N", "st": "1 Macc 15:25", "t": "Ἀντίοχος δὲ ὁ βασιλεὺς παρενέβαλεν ἐπὶ Δωρὰ ἐν τῇ δευτέρᾳ, προσάγων διὰ παντὸς αὐτῇ τὰς χεῖρας καὶ μηχανὰς ποιούμενος, καὶ συνέκλεισεν τὸν Τρὺφωνα τοῦ εἰσπορεύεσθαι καὶ ἐκπορεύεσθαι"}, {"sp": "N", "st": "1 Macc 15:26", "t": "καὶ ἀπέστειλεν αὐτῷ Σίμων δισχιλίους ἄνδρας ἐκλεκτοὺς συμμαχῆσαι αὐτῷ καὶ ἀργύριον καὶ χρυσίον καὶ σκεύη ἱκανά."}, {"sp": "N", "st": "1 Macc 15:27", "t": "καὶ οὐκ ἠβούλετο αὐτὰ δέξασθαι, ἀλλὰ ἠθέτησεν πάντα ὅσα ἐσυνέθετο αὐτῷ τὸ πρότερον, καὶ ἠλλοτριοῦτο αὐτῷ."}, {"sp": "N", "st": "1 Macc 15:28", "t": "καὶ ἀπέστειλεν πρὸς αὐτὸν Ἀθηνόβιον ἕνα τῶν φίλων αὐτοῦ κοινολογησόμενον αὐτῷ, λέγων Ὑμεῖς κατακρατεῖτε τῆς Ἰόππης καὶ Γαζαρηνῶν καὶ τῆς ἄκρας ἐν Ἰερουσαλήμ, πόλεις τῆς βασιλείας μου."}, {"sp": "N", "st": "1 Macc 15:29", "t": "τὰ ὅρια αὐτῶν ἠρημώσατε, καὶ ἐποιήσατε πληγὴν μεγάλην ἐπὶ τῆς γῆς, καὶ ἐκυριεύσατε τόπων πολλῶν ἐν τῇ βασιλείᾳ μου."}, {"sp": "N", "st": "1 Macc 15:30", "t": "νῦν οὖν παράδοτε τὰς πόλεις ἃς κατελάβεσθε, καὶ τοὺς φόρους τῶν τόπων ὧν κατεκυριεύσατε, τῶν ὁρίων τῶν ἐκ τῆς Ἰουδαίας."}, {"sp": "N", "st": "1 Macc 15:31", "t": "εἰ δὲ μή, δότε ἀντʼ αὐτῶν πεντακόσια τάλαντα ἀργυρίου, καὶ τῆς καταφθορᾶς ἧς κατεφθάρκατε καὶ τῶν φόρων τῶν πόλεων ἄλλα τάλαντα πεντακόσια· εἰ δέ μή, παραγενόμενοι ἐκπολεμήσουσιν ὑμᾶς."}, {"sp": "N", "st": "1 Macc 15:32", "t": "Καὶ ἦλθεν Ἀθηνόβιος φίλος τοῦ βασιλέως εἰς Ἰερουσαλήμ, καὶ εἶδεν τὴν δόξαν Σίμωνος καὶ κυλίκιον μετὰ χρυσωμάτων καὶ ἀργυρωμάτων καὶ παράστασιν ἱκανὴν· καὶ ἐξιστάτο, καὶ ἀπήγγειλεν αὐτοῖς τοὺς λόγους τοῦ βασιλέως."}, {"sp": "N", "st": "1 Macc 15:33", "t": "καὶ ἀποκριθεὶς Σίμων εἶπεν αὐτῷ Οὔτε γῆν ἀλλοτρίαν εἰλήφαμεν, οὕτε ἀλλοτρίων κεκρατήκαμεν, ἀλλὰ τῆς κληρονομίας τῶν πατέρων ἡμῶν· ὑπὸ δέ ἐχθρῶν ἡμῶν ἀκρίτως ἔν τινι καιρῷ κατεκρατήθη."}, {"sp": "N", "st": "1 Macc 15:34", "t": "ἡμεῖς δέ καιρὸν ἔχοντες ἀντεχόμεθα τῆς κληρονομίας ἡμῶν καὶ τῶν πατέρων ἡμῶν."}, {"sp": "N", "st": "1 Macc 15:35", "t": "περὶ δὲ Ἰόππης καὶ Γαζαρηνῶν αἰτεῖς· αὗται ἐποίουν ἐν τῷ λαῷ πληγὴν μεγάλην καὶ τῇ γῇ ἡμῶν· τούτων δώσομεν τάλαντα ἑκατόν. καὶ υὐκ ἀπεκρίθη αὐτῷ λόγον."}, {"sp": "N", "st": "1 Macc 15:36", "t": "ἀπέστρεψεν δὲ μετὰ θυμοῦ πρὸς τὸν βασιλέα, καὶ ἀπήγγειλεν αὐτῷ τοὺς λόγους τούτους καὶ τὴν δόξαν Σίμωνος καὶ πάντα ὅσα εἶδεν· καὶ ὠργίσθη ὁ βασιλεὺς ὀργὴν μεγάλην."}, {"sp": "N", "st": "1 Macc 15:37", "t": "Γρύφων δὲ ἐμβὰς εἰς πλοῖον ἔφυγεν εἰς Ὀρθωσίαν."}, {"sp": "N", "st": "1 Macc 15:38", "t": "καὶ κατέστησεν ὁ βασιλεὺς τὸν Κενδεβαῖον ἐπιστράτηγον τῆς παραλίας, καὶ δυνάμεις πεζικὰς καὶ ἱππικὰς ἔδωκεν αὐτῷ."}, {"sp": "N", "st": "1 Macc 15:39", "t": "καὶ ἐνετείλατο αὐτῷ παρεμβάλλειν κατὰ πρόσωπον τῆς Ἰουδαίας· καὶ ἐνετείλατο αὐτῷ οἰκοδομῆσαι τὴν Κεδρὼν καὶ ὀχυρῶσαι τὰς πόλεις, καὶ ὅπως πολεμῇ τὸν λαόν· ὁ δὲ βασιλεὺς ἐδίωκε τὸν Τρύφωνα."}, {"sp": "N", "st": "1 Macc 15:40", "t": "καὶ παρεγενήθη Κεωδεβαῖος εἰς Ἰαμνείαν, καὶ ἤρξατο τοῦ ἐρεθίζειν τὸν λαὸν καὶ ἐμβατεύειν εἰς τὴν Ἰουδαίαν καὶ αἰχμαλωτίζειν τὸν λαὸν καὶ φονεύειν."}, {"sp": "N", "st": "1 Macc 15:41", "t": "καὶ ᾠκοδόμησεν τὴν Κεδρὼν· καὶ ἔταξεν ἐκεῖ ἱππεῖς καὶ δυνάμεις ὅπως ἐκπορευόμενοι ἐξοδεύωσιν τὰς ὁδοὺς τῆς Ἰουδαίας, καθὰ συνέταξεν αὐτῷ ὁ βασιλεύς."}, {"sp": "N", "st": "1 Macc 16:1", "t": "Καὶ ἀνέβη Ἰωάννης ἐκ Γαζάρων, καὶ ἀπήγγειλεν Σίμωνι τῷ πατρὶ αὐτοῦ ἃ συνετέλει Κενδεβαῖος."}, {"sp": "N", "st": "1 Macc 16:2", "t": "καὶ ἐκάλεσεν Σίμων τοὺς δύο υἱοὺς αὐτοῦ τοὺς πρεσβυτέρους Ἰούδαν καὶ Ἰωάννην, καὶ εἶπεν αὐτοῖς Ἐγὼ καὶ οἱ ἀδελφοί μου καὶ ὁ οἶκος τοῦ πατρός μου ἐπολεμήσαμεν τοὺς πολέμους Ἰσραὴλ ἀπὸ νεότητος ἕως τῆς σήμερον ἡμέρας, καὶ εὐοδώθη ἐν ταῖς χερσὶν ἡμῶν ῥύσασθαι τὸν Ἰσραὴλ πλεονάκις."}, {"sp": "N", "st": "1 Macc 16:3", "t": "νῦν δὲ γεγήρακα, καὶ ὑμεῖς δὲ ἐν τῷ ἐλέει ἱκανοί ἐστε ἐν τοῖς ἔτεσιν· γίνεσθε ἀντʼ ἐμοῦ καὶ τοῦ ἀδελφοῦ μου, καὶ ἐξελθόντες ὑπερμαχεῖτε ὑπέρ τοῦ ἔθνους ἡμῶν, ἡ δὲ ἐκ τοῦ οὐρανοῦ βοήθεια ἤτω μεθʼ ὑμῶν."}, {"sp": "N", "st": "1 Macc 16:4", "t": "καὶ ἐπέλεξεν ἐκ τῆς χώρας εἴκοσι χιλιάδας ἀνδρῶν πολεμιστῶν καὶ ἱππεῖς, καὶ ἐπορεύθησαν ἐπὶ τὸν Κενδεβαῖον, καὶ ἐκοιμήθησαν ἐν Μωδαείμ."}, {"sp": "N", "st": "1 Macc 16:5", "t": "καὶ ἀναστάντες τὸ πρωὶ ἐπορεύοντο εἰς τὸ πεδίον· καὶ ἰδοὺ δύναμις πολλὴ εἰς συνάντησιν αὐτοῖς, πεζικοὶ καὶ ἱππεῖς, καὶ χειμάρρους ἦν ἀνὰ μέσον αὐτῶν."}, {"sp": "N", "st": "1 Macc 16:6", "t": "καὶ παρενέβαλεν κατὰ πρόσωπον αὐτῶν αὐτὸς καὶ ὁ λαὸς αὐτοῦ· καὶ εἶδεν τὸν λαὸν δειλούμενον διαπερᾶσαι τὸν χειμάρρουν, καὶ διεπέρασεν πρῶτος· καὶ εἶδον αὐτὸν οἱ ἄνδρες, καὶ διεπέρασαν κατόπισθεν αὐτοῦ."}, {"sp": "N", "st": "1 Macc 16:7", "t": "καὶ διεῖλεν τὸν λαὸν καὶ τοὺς ἱππεῖς ἐν μέσῳ τῶν πεζῶν· ἡ δὲ ἵππος τῶν ὑπεναντίων πολλὴ σφόδρα."}, {"sp": "N", "st": "1 Macc 16:8", "t": "καὶ ἐσάλπισαν ταῖς σάλπιγξιν, καὶ ἐτροπώθη Κενδεβαῖος καὶ ἡ παρεμβολὴ αὐτοῦ, καὶ ἔπεσον ἐξ αὐτοῦ τραυματίαι πολλοί οἱ δὲ καταλειφθέντες ἔφυγον εἰς τὸ ὀχύρωμα."}, {"sp": "N", "st": "1 Macc 16:9", "t": "τότε ἐτραυματίσθη Ἰούδας ὁ ἀδελφὸς Ἰωάννου· Ἰωάννης δέ κατεδίωξεν αὐτοὺς ἕως ἐλθεῖν εἰς Κεδρών, ἣν οἰκοδόμησεν."}, {"sp": "N", "st": "1 Macc 16:10", "t": "καὶ ἔφυγον εἰς τοὺς πύργους τοὺς ἐν τῷ ἀγρῷ Ἀζώτου, καὶ ἐνεπύρισεν αὐτὴν ἐν πυρί καὶ ἕπεσαν ἐξ αὐτῶν εἰς ἄνδρας χιλίους, καὶ ἀπέστρεψεν εἰς τὴν Ἰουδαίαν μετʼ εἰρήνης."}, {"sp": "N", "st": "1 Macc 16:11", "t": "Καὶ Πτολεμαῖος ὁ τοῦ Ἀβούβου ἦν καθεσταμένος στρατηγὸς εἰς τὸ πεδίον Ἰεριχώ, καὶ ἔσχεν ἀργύριον καὶ χρυσίον πολύ·"}, {"sp": "N", "st": "1 Macc 16:12", "t": "ᾖν γὰρ γαμβρὸς τοῦ ἀρχιερέως."}, {"sp": "N", "st": "1 Macc 16:13", "t": "καὶ ὑψώθη ἡ καρδία αὐτοῦ, καὶ ἠβουλήθη κατακρατῆσαι τῆς χώρας. καὶ ἐβουλεύετο δόλῳ κατὰ Σίμωνος καὶ κατὰ τῶν υἱῶν αὐτοῦ ἄραι αὐτούς."}, {"sp": "N", "st": "1 Macc 16:14", "t": "Σίμων δὲ ἦν ἐφοδεύων τὰς πόλεις τὰς ἐν τῇ χώρᾳ καὶ φροντίζων τὰς ἐπιμελίας αὐτῶν, καὶ κατέβη εἰς Ἰεριχῶ αὐτὸς καὶ Ματταθίας καὶ Ἰούδας καὶ οἱ υἱοὶ αὐτοῦ ἔτους ἑβδόμου καὶ ἑβδομηκοστοῦ καὶ ἑκατοστοῦ ἐν μηνὶ ἑνδεκάτῳ· οὗτος ὁ μὴν Σαβάτ."}, {"sp": "N", "st": "1 Macc 16:15", "t": "καὶ ὑπεδέξατο αὐτοὺς ὁ τοῦ Ἀβούβου εἰς τὸ ὀχυρωμάτιον τὸ καλούμενον Δὼκ μετὰ δόλου, ὃ ᾠκοδόμησεν, καὶ ἐποίησεν αὐτοῖς πότον μέγαν· καὶ ἐνέκρυψεν ἐκεῖ ἄνδρας."}, {"sp": "N", "st": "1 Macc 16:16", "t": "καὶ ὅτε ἐμεθύσθη Σίμων καὶ οἱ υἱοὶ αὐτοῦ, ἐξανέστη Πτολεμαῖος καὶ οἱ μετʼ αὐτοῦ, καὶ ἐλάβοσαν τὰ ὅπλα αὐτῶν, καὶ ἐπεισήλθοσαν τῷ Σίμωνι εἰς τὸ συμπόσιον, καὶ ἀπέκτειναν αὐτὸν καὶ τοὺς υἱοὺς αὐτοῦ, καί τινας τῶν παιδαρίων αὐτοῦ."}, {"sp": "N", "st": "1 Macc 16:17", "t": "καὶ ἐποίησεν ἀθείαν μεγάλην, καὶ ἀνταπέδωκεν κακὰ ἀντὶ ἀγαθῶν."}, {"sp": "N", "st": "1 Macc 16:18", "t": "καὶ ἔγραψεν ταῦτα Πτολεμαῖος. καὶ ἀπέστειλεν τῷ βασιλεῖ ὅπως ἀποστείλῃ αὐτῷ δυνάμεις εἰς βοήθειαν, καὶ παραδῷ τὴν Χώραν αὐτῶν καὶ τὰς πόλεις."}, {"sp": "N", "st": "1 Macc 16:19", "t": "καὶ ἀπέστειλεν ἑτέρους εἰς Γάζαρα ἆραι τὸν Ἰωάννην, καὶ τοῖς χιλιάρχοις ἀπέστειλεν ἐπιστολὰς παραγενέσθαι πρὸς αὐτόν, ὅπως δῷ αὐτοῖς ἀργύριον καὶ χρυσίον καὶ δόματα."}, {"sp": "N", "st": "1 Macc 16:20", "t": "καὶ ἑτέρους ἀπέστειλεν καταλαβέσθαι τὴν Ἰερουσαλὴμ καὶ τὸ ὄρος τοῦ ἱεροῦ."}, {"sp": "N", "st": "1 Macc 16:21", "t": "καὶ προδραμὼν ἀπήγγειλεν Ἰωάννῃ εἰς Γάζαρα, ὅτι ἀπώλετο ὁ πατὴρ αὐτοῦ καὶ οἱ ἀδελφοὶ αὐτοῦ, καὶ ὅτι Ἀπέσταλκε καὶ σέ ἀποκτεῖναι."}, {"sp": "N", "st": "1 Macc 16:22", "t": "καὶ ἀκούσας ἐξέστη σφόδρα, καὶ συνέλαβεν τοὺς ἄνδρας τοὺς ἐλθόντας ἀπολέσαι αὐτόν· καὶ ἀπέκτεινεν αὐτούς, ἔγνω γὰρ ὅτι ἐζητοῦσαν αὐτὸν ἀπολέσαι."}, {"sp": "N", "st": "1 Macc 16:23", "t": "Καὶ τὰ λοιπὰ τῶν λόγων Ἰωάννου καὶ τῶν πολέμων αὐτοῦ καὶ τῶν ἀνδραγαθιῶν αὐτοῦ ὧν ἠνδραγάθησεν καὶ τῆς οἰκοδομῆς τῶν τειχέων ὧν ᾠκοδόμησεν καὶ τῶν πράξεων αὐτοῦ,"}, {"sp": "N", "st": "1 Macc 16:24", "t": "ἰδοὺ ταῦτα γέγραπται ἐπὶ βιβλίου ἡμερῶν ἀρχιερωσύνης αὐτοῦ, ἀφʼ οὗ ἐγενήθη ἀρχιερεὺς μετὰ τὸν πατέρα αὐτοῦ."}, {"sp": "HDR", "t": "ΜΑΚΚΑΒΑΙΩΝ Βʹ"}, {"sp": "N", "st": "2 Macc 1:1", "t": "A ΤΟΙΣ ἀδελφοῖς τοῖς κατʼ Αἴγυπτον Ἰουδαίοις χαίρειν οἱ ἀδελφοὶ οἱ ἐν Ἰεροσολύμοις Ἰουδαῖοι καὶ οἱ ἐν τῇ χώρᾳ τῆς Ἰουδαίας. εἰρήνην ἀγαθήν·"}, {"sp": "N", "st": "2 Macc 1:2", "t": "καὶ ἀγαθοποιῆσαι ὑμῖν ὁ θεός, καὶ μνησθῆναι τῆς διαθήκης αὐτοῦ τῆς πρὸς Ἀβραὰμ καὶ Ἰσαὰκ καὶ Ἰακὼβ τῶν δούλων αὐτοῦ τῶν πιστῶν."}, {"sp": "N", "st": "2 Macc 1:3", "t": "καὶ δώῃ ὑμῖν καρδίαν πᾶσιν εἰς τὸ σέβεσθαι αὐτὸν καὶ ποιεῖν αὐτοῦ τὰ θελήματα καρδίᾳ μεγάλῃ καὶ ψυχῇ βουλομένῃ·"}, {"sp": "N", "st": "2 Macc 1:4", "t": "καὶ διανοίξαι τὴν καρδίαν ὑμῶν ἐν τῷ νόμῳ αὐτοῦ καὶ ἐν τοῖς προστάγμασιν, καὶ εἰρήνην ποιήσαι"}, {"sp": "N", "st": "2 Macc 1:5", "t": "καὶ ὑπακούσαι ὑμῶν τῶν δεήσεων, καὶ καταλλαγείη ὑμῖν, καὶ μὴ ὑμᾶς ἐγκαταλείποι ἐν καιρῷ πονηρῷ."}, {"sp": "N", "st": "2 Macc 1:6", "t": "Καὶ νῦν ὧδέ ἐσμεν προσευχόμενοι περὶ ὑμῶν."}, {"sp": "N", "st": "2 Macc 1:7", "t": "βασιλεύοντος Δημητρίου, ἔτους ἐκατοστοῦ ἑξηκοστοῦ ἐνάτου, ἡμεῖς οἱ Ἰουδαῖοι γεγράφαμεν ὑμῖν ἐν τῆ θλίψει καὶ ἐν τῇ ἀκμῇ τῇ ἐπελθούσῃ ἡμῖν ἐν τοῖς ἔτεσιν τούτοις, ἀφʼ οὖ ἀπέστη Ἰάσων καὶ οἱ μετ᾿ αὐτοῦ ἀπὸ τῆς ἁγίας γῆς καὶ τῆς βασιλείας·"}, {"sp": "N", "st": "2 Macc 1:8", "t": "καὶ ἐνεπύρισαν τὸν πυλῶνα, καὶ ἐξέχεαν ἀἷμα ἀθῷον· καὶ ἐδεήθημεν τοῦ κυρίου καὶ εἰσηκούσθημεν· προσηνέγκαμεν θυσίαν καὶ σεμίδαλιν, καὶ ἐξηγάγομεν τοὺς λύχνους, καὶ προεθήκαμεν τοὺς ἄρτους."}, {"sp": "N", "st": "2 Macc 1:9", "t": "καὶ νῦν ἴνα ἄγητε τὰς ἡμέρας τῆς σκηνοπηγίας τοῦ Χασελεὺ μηνός."}, {"sp": "N", "st": "2 Macc 1:10", "t": "ἔτους ὀγδοηκοστοῦ καὶ ὀγδόου ἐν Ἰεροσολύμοις. Καὶ οἱ ἐν τῇ Ἰουδαίᾳ καὶ ἡ γερουσία καὶ Ἰούδας Ἀριστοβούλῳ διδασκάλῳ Πτολεμαίου τοῦ βασιλέως, ὄντι δὲ ἀπὸ τοῦ τῶν χριστῶν ἱερέων γένους, καὶ τοῖς ἐν Αἰγύπτῳ Ἰουδαίοις, χαίρειν καὶ ὑγιαίνειν."}, {"sp": "N", "st": "2 Macc 1:11", "t": "ἐκ μεγάλων κιωδύνων ὑπὸ τοῦ θεοῦ σεσωσμένοι μεγάλως εὐχαριστοῦμεν αὐτῷ, ὡς ἂν πρὸς βασιλέα παρατασσόμενοι."}, {"sp": "N", "st": "2 Macc 1:12", "t": "αὐτὸς γὰρ ἐξέβρασεν τοὺς παρατασσομένους ἐν τῇ ἁγίᾳ πόλει εἰς τὴν Περσίδα."}, {"sp": "N", "st": "2 Macc 1:13", "t": "γενόμενος γὰρ ὁ ἡγεμὼν καὶ ἡ περὶ αὐτὸν ἀνυπόστατος δοκοῦσα εἶναι δύναμις, κατεκόπησαν ἐν τῷ τῆς Ναναίας ἱερῷ, παραλογισμῷ χρησαμένων τῶν περὶ τὴν Ναναίαν ἱερέων."}, {"sp": "N", "st": "2 Macc 1:14", "t": "ὡς γὰρ συνοικῶν αὐτῇ παρεγένετο εἰς τὸν τόπον ὅ τε Ἀντίοχος καὶ οἱ σὺν αὐτῷ φίλοι, χάριν τοῦ λαβεῖν τὰ χρήματα πλείονα εἰς φερνῆς λόγον·"}, {"sp": "N", "st": "2 Macc 1:15", "t": "καὶ προθέντων αὐτὰ τῶν ἱερέων τοῦ Ναναίου, κἀκείνου προσελθόντος μετʼ ὀλίγων εἰς τὸν περίβολον τοῦ τεμένους, συγκλείσαντες τὸ ἱερόν, ὡς εἰσῆλθεν Ἀντίοχος,"}, {"sp": "N", "st": "2 Macc 1:16", "t": "ἀνοίξαντες τὴν τοῦ φατνώματος κρυπτὴν θύραν, βάλλοντες πέτρους συνεκεραύνωσαν τὸν ἡγεμόνα, καὶ μέλη ποιήσαντες καὶ τὰς κεφαλὰς τοῖς ἔξω παραρίψαντες."}, {"sp": "N", "st": "2 Macc 1:17", "t": "κατὰ πάντα εὐλογητὸς ἡμῶν ὁ θεός, ὃς ἔδωκεν τοὺς ἀσεβήσαντας."}, {"sp": "N", "st": "2 Macc 1:18", "t": "Μέλλοντεςς ἅγειν ἐν τῷ Κασελεὺ πέμπτῃ καὶ εἰκάδι τὸν καθαρισμὸν τοῦ ἱεροῦ, δέον ἡγησάμεθα διασαφῆσαι ὑμῖν, ἴνα καὶ αὐτοὶ ἄγητε σκηνοπηγίας καὶ τοῦ πυρός, ὅτε Νεεμίας, ὁ οἰκοδομήσας τότε τὸ ἱερὸν καὶ τὸ θυσιαστήριον, ἀνήνεγκεν θυσίας."}, {"sp": "N", "st": "2 Macc 1:19", "t": "καὶ γὰρ ὅτε εἰς τὴν Περσικὴν ἥγοντο ἡμῶν οἱ πατέρες, οἵ τε εὐσεβεῖς ἱερεῖς λαβόντες ἀπὸ τοῦ πυρὸς τοῦ θυσιαστηρίου λαθραίως, κατέκρυψαν ἐν κοιλώματι φρέατος τάξιν ἔχοντος ἄνυδρον, ἐν ᾧ κατησφαλίσαντο, ὥστε πᾶσιν ἄγνωστον εἶναι τὸν τόπον."}, {"sp": "N", "st": "2 Macc 1:20", "t": "διελθόντων δέ ἐτῶν ἱκανῶν, ὅτε ἔδοξεν τῷ θεῷ, ἀποσταλεὶς Νεεμίας ἀπὸ τοῦ βασιλέως τῆς Περσίδος τοὺς ἐκγόνους τῶν ἱερέων τῶν ἀποκρυψάντων ἔπεμψεν ἐπὶ τὸ πῦρ."}, {"sp": "N", "st": "2 Macc 1:21", "t": "ὡς διεσάφισαν ἡμῖν μὴ εὑρηκέναι πῦρ ἀλλὰ ὕδωρ παχύ, ἐκέλευσεν αὐτοὺς ἀποβάψαντας φέρειν· ὡς δὲ ἀνηνέχθη τὰ τῶν θυσιῶν, ἐκέλευσεν τοὺς ἱερεῖς Νεεμίας ἐπιρᾶναι τῷ ὕδατι τά τε ξύλα καὶ τὰ ἐπικείμενα."}, {"sp": "N", "st": "2 Macc 1:22", "t": "ὡς δὲ ἐγένετο καὶ χρόνος διῆλθεν ὅ τε ἥλιος ἀνέλαμψεν ἐπινεφὴς ὤν, ἀνήφθη πυρὰ μεγάλη, ὥστε θαυμάσαι πάντας."}, {"sp": "N", "st": "2 Macc 1:23", "t": "προσευχὴν δὲ ἐποιήσαντο οἱ ἱερεῖς δαπανωμένης τῆς θυσίας, οἵ τε ἱερεῖς καὶ πάντες, καταρχομένου Ἰωνάθου τῶν τε λοιπῶν ἐπιφωνούντων, ὡς Νεεμίου."}, {"sp": "N", "st": "2 Macc 1:24", "t": "ἦν δὲ ἡ προσευχὴ τὸν τρόπον ἔχουσα τοῦτον Κύριε ὁ θεός, ὁ πάντων κτίστης, ὁ φοβερὸς καὶ ὁ ἰσχυρὸς καὶ δίκαιος καὶ ἐλεήμων, ὁ μόνος βασιλεὺς καὶ χρηστός,"}, {"sp": "N", "st": "2 Macc 1:25", "t": "ὁ μόνος χορηγός, ὁ μόνος δίκαιος καὶ παντοκράτωρ καὶ αἰώνιος, ὁ διασώζων τὸν Ἰσραὴλ ἐκ παντὸς κακοῦ, ὁ ποιήσας τοὺς πατέρας ἐκλεκτούς, καὶ ἁγιάσας αὐτοὺς·"}, {"sp": "N", "st": "2 Macc 1:26", "t": "πρόσδεξαι τὴν θυσίαν ὑπέρ παντὸς τοῦ λαοῦ σου Ἰσραήλ, καὶ διαφύλαξον τὴν μερίδα σου καὶ καθαγίασον."}, {"sp": "N", "st": "2 Macc 1:27", "t": "ἐπισυνάγαγε τὴν διασπορὰν ἡμῶν, ἐλευθέρωσον τοὺς δουλεύοντας ἐν τοῖς ἔθνεσιν, τοὺς ἐξουθενημένους καὶ βδελυκτοὺς ἔφιδε· καὶ γνώτωσαν τὰ ἔθνη ὅτι σὺ ὁ θεὸς ἡμῶν."}, {"sp": "N", "st": "2 Macc 1:28", "t": "βασάνισον τοὺς καταδυναστεύοντας καὶ ἐξυβρίζοντας ἐν ὑπερηφανία·"}, {"sp": "N", "st": "2 Macc 1:29", "t": "καταφύτευσον τὸν λαόν σου εἰς τὸν τόπον τὸν ἅγιόν σου, καθὼς εἶπεν Μωσῆς."}, {"sp": "N", "st": "2 Macc 1:30", "t": "Οἱ δὲ ἱερεῖς ἐπέψαλλον τοὺς ὕμνους."}, {"sp": "N", "st": "2 Macc 1:31", "t": "καθὼς δὲ ἀνηλώθη τὰ τῆς θυσίας, καὶ τὸ περιλειπόμενον ὕδωρ ὁ Νεεμίας ἐκέλευσεν λίθους μείζονας καταχεῖν."}, {"sp": "N", "st": "2 Macc 1:32", "t": "ὡς δὲ τοῦτο ἐγενήθη, φλὸξ ἀνήφθη· τοῦ δὲ ἀπὸ τοῦ θυσιαστηρίου ἀντιλάμψαντος φωτὸς ἐδαπανήθη."}, {"sp": "N", "st": "2 Macc 1:33", "t": "ὡς δὲ φανερὸν ἐγενήθη τὸ πρῆγμα, καὶ διηγγέλη τῷ βασιλεῖ τῶν Περσῶν ὅτι εἰς τὸν τόπον οὗ τὸ πῦρ ἔκρυψαν οἱ μεταχθέντες ἱερεῖς τὸ ὕδωρ ἐφάνη, ἀφʼ οὖ καὶ οἱ περὶ τὸν Νεεμίαν ἥγνισαν τὰς θυσίας,"}, {"sp": "N", "st": "2 Macc 1:34", "t": "περιφράξας δὲ ὁ βασιλεὺς ἱερὸν ἐποίησεν, δοκιμάσας τὸ πρᾶγμα·"}, {"sp": "N", "st": "2 Macc 1:35", "t": "καὶ οἷς ὁ βασιλεὺς πολλὰ διάφορα ἐλάμβανεν, καὶ μετεδίδου."}, {"sp": "N", "st": "2 Macc 1:36", "t": "προσηγόρευσαν δὲ οἱ περὶ τὸν Νεεμίαν τοῦτο Νεφθάρ, ὁ διερμηνεύεται Καθαρισμός· καλεῖται δὲ παρὰ τοῖς πολλοῖς Νεφθάρ."}, {"sp": "N", "st": "2 Macc 2:1", "t": "Εὑρίσκεται δὲ ἐν ταῖς ἀπογραφαῖς Ἰερεμίας ὁ προφήτης ὅτι ἐκέλευσεν τοῦ πυρὸς λαβεῖν τοὺς μεταγενομένους, ὡς σεσήμανται·"}, {"sp": "N", "st": "2 Macc 2:2", "t": "καὶ ὡς ἐνετείλατο τοῖς μεταγενομένοις ὁ προφήτης, δοὺς αὐτοῖς τὸν νόμον, ἵνα μὴ ἐπιλάθωνται τῶν προσταγμάτων τοῖ κυρίου, καὶ ἴνα μὴ ἀποπλανηθῶσιν ταῖς διανοίαις, βλέποντες ἀγάλματα χρυσᾶ καὶ ἀργυρᾶ καὶ τὸν περὶ αὐτὰ κόσμον."}, {"sp": "N", "st": "2 Macc 2:3", "t": "καὶ ἕτερα τοιαῦτα λέγων, παρεκάλει μὴ ἀποστῆναι τὸν νόμον ἀπὸ τῆς καρδίας αὐτῶν."}, {"sp": "N", "st": "2 Macc 2:4", "t": "ἦν δὲ ἐν τῇ γραφῇ, ὡς τὴν σκηνὴν καὶ τὴν κιβωτὸν ἐκέλευσεν ὁ προφήτης χρηματισμοῦ γενηθέντος αὐτῷ συνακολουθεῖν, ὡς δὲ ἐξῆλθεν εἰς τὸ ὄρος οὗ ὁ Μωυσῆς ἀναβὰς ἐθεάσατο τὴν τοῦ θεοῦ κληρονομίαν."}, {"sp": "N", "st": "2 Macc 2:5", "t": "καὶ ἐλθὼν ὁ Ἱερεμίας εὗρεν οἶκον ἀντρώδη, καὶ τὴν σκηνὴν καὶ τὴν κιβωτὸν καὶ τὸ θυσιαστήριον τοῦ θυμιάματος εἰσήνεγκεν ἐκεῖ, καὶ τὴν θύραν ἐνέφραξεν·"}, {"sp": "N", "st": "2 Macc 2:6", "t": "καὶ προσελθόντες τινές τῶν συνακολουθούντων ὥστε ἐπισημάνασθαι τὴν ὁδόν, καὶ οὐκ ἐδυνήθησαν εὑρεῖν."}, {"sp": "N", "st": "2 Macc 2:7", "t": "ὡς δὲ ὁ Ἱερεμίας ἔγνω, μεμψάμενος αὐτοῖς εἶπεν ὅτι Καὶ ἄγνωστοι ὁ τόπος ἔσται, ἕως ἂν συνάγῃ ὁ θεὸς ἐπισυναγωγὴν τοῦ λαοῦ, καὶ ἔλεος γένηται."}, {"sp": "N", "st": "2 Macc 2:8", "t": "καὶ τότε ὁ κύριος ἀναδείξει ταῦτα, καὶ ὀφθήσεται ἡ δόξα τοῦ κυρίου καὶ ἡ νεφέλη, ὡς ἐπὶ Μωσῇ ἐδηλοῦτο, ὡς καὶ ὁ Σαλωμὼν ἠξίωσεν, ἵνα ὁ τόπος καθαγιασθῇ μεγάλως."}, {"sp": "N", "st": "2 Macc 2:9", "t": "διεσαφεῖτο δὲ καὶ ὡς σοφίαν ἔχων ἀνήνεγκεν θυσίαν ἐγκαινισμοῦ καὶ τῆς τελειώσεως τοῦ ἱεροῦ."}, {"sp": "N", "st": "2 Macc 2:10", "t": "καθὼς καὶ Μωυσῆς προσηύξατο πρὸς Κύριον, καὶ κατέβη πῦρ ἐκ τοῖ οὐρανοῦ καὶ τὰ τῆς θυσίας ἐδαπάνησεν, οὕτως Σαλωμὼν προσηύξατο πρὸς Κύριον, καὶ καταβὰν τὸ πῦρ ἀνήλωσεν τὰ ὁλοκαυτώματα·"}, {"sp": "N", "st": "2 Macc 2:11", "t": "καὶ εἶπεν Μωσῆς Διὰ τὸ μὴ βεβρῶσθαι τὸ περὶ τῆς ἁμαρτίας ἀνηλώθη."}, {"sp": "N", "st": "2 Macc 2:12", "t": "ὡσαύς καὶ ὁ Σαλωμὼν τὰς ὀκτὼ ἡμέρας ἤγαγεν."}, {"sp": "N", "st": "2 Macc 2:13", "t": "Ἐξηγοῦντο δὲ καὶ ἐν ταῖς ἀναγραφαῖς καὶ ἐν τοῖς ὑπομνηματισμοῖς τοῖς κατὰ τὸν Νεεμίαν τὰ αὐτά, καὶ ὡς καταβαλλόμενος βιβλιοθήκην ἐπισυνήγαγεν τὰ περὶ τῶν βασιλέων καὶ προφητῶν βιβλία, καὶ τὰ τοῦ Δαυείδ, καὶ ἐπιστολὰς βασιλέων περὶ ἀναθεμάτων."}, {"sp": "N", "st": "2 Macc 2:14", "t": "ὡσαύτως δὲ καὶ Ἰούδας τὰ διαπεπτωκότα διὰ τὸν γεγονότα πόλεμον ἡμῖν ἐπισυνήγαγεν ταῦτα, καὶ ἔστιν παρʼ ἡμῖν."}, {"sp": "N", "st": "2 Macc 2:15", "t": "ὧν οὖν ἐὰν χρείαν ἔχητε, τοὺς ἀποκομιοῦντας ὑμῖν ἀποστέλλετε."}, {"sp": "N", "st": "2 Macc 2:16", "t": "Μέλλοντες οὗν ἄγειν τὸν καθαρισμὸν ἐγράψαμεν ὑμῖν· καλῶς οὗν ποιήσετε ἄγειν τὰς ἡμέρας."}, {"sp": "N", "st": "2 Macc 2:17", "t": "ὁ δὲ θεὸς ὁ σώσας τὸν πάντα λαὸν αὐτοῦ, καὶ ἀποδοὺς τὴν κληρονομίαν αὐτοῦ πᾶσιν καὶ τὸ βασίλειον καὶ τὸ ἱεράτευμα καὶ τὸν ἁγιασμόν,"}, {"sp": "N", "st": "2 Macc 2:18", "t": "καθὼς ἐπηγγείλατο διὰ τοῦ νόμου· ἐλπίζομεν γὰρ ἐπὶ τῷ θεῷ, ὅτι ταχέως ἡμᾶς ἐλεήσει, καὶ ἐπισυνάξει ἐκ τῆς ὑπὸ τὸν οὐρανὸν εἰς τὸν ἅγιον τόπον· ἐξείλατο γὰρ ἡμᾶς ἐκ μεγάλων κακῶν, καὶ τὸν τόπον ἐκαθέρισεν."}, {"sp": "N", "st": "2 Macc 2:19", "t": "Τὰ δὲ κατὰ τὸν Ἰούδαν τὸν Μακκαβαῖον καὶ τοὺς τούτου ἀδελφοὺς καὶ τὸν τοῦ ἱεροῦ τοῦ μεγίστου καθαρισμὸν καὶ τὸν τοῦ βωμοῦ ἐγκαινισμόν,"}, {"sp": "N", "st": "2 Macc 2:20", "t": "ἔτι τε τοὺς πρὸς Ἀντίοχον τὸν Ἐπιφανῆ καὶ τὸν τούτου υἱὸν Εὐπάτορα πολέμους,"}, {"sp": "N", "st": "2 Macc 2:21", "t": "καὶ τὰς ἐξ οὐρανοῦ γενομένας ἐπιφανείας τοῖς ὑπέρ τοῦ Ἰουδαισμοῦ φιλοτίμως ἀνδραγαθήσασιν, ὡς τὴν ὅλην χώραν ὀλίγους ὄντας λεηλατεῖν, καὶ τὰ βάρβαρα πλήθη διώκειν,"}, {"sp": "N", "st": "2 Macc 2:22", "t": "καὶ τὸ περιβόητον καθʼ ὅλην τὴν οἰκουμένην ἱερὸν ἀνακομίσασθαι, καὶ τὴν πόλιν ἐλευθερῶσαι, καὶ τοὺς μέλλοντας καταλύεσθαι νόμους ἐπανορθῶσαι, τοῦ κυρίου μετὰ πάσης ἐπιεικίας ἵλεω γενομένου αὐτοῖς,"}, {"sp": "N", "st": "2 Macc 2:23", "t": "ὑπὸ Ἰάσωνος τοῦ Κυρηναίου δεδηλωμένα διὰ πέντε βιβλίων, πειρασόμεθα δι᾿ ἑνὸς συντάγματος ἐπιτεμεῖν."}, {"sp": "N", "st": "2 Macc 2:24", "t": "συνορῶντες γὰρ τὸ χύμα τῶν ἀριθμῶν, καὶ τὴν οὖσαν δυσχέρειαν τοῖς θέλουσιν εἰσκυκλεῖσθαι τοῖς τῆς ἱστορίας διηγήμασιν διὰ τὸ πλῆθος τῆς ὕλης,"}, {"sp": "N", "st": "2 Macc 2:25", "t": "ἐφροντίσαμεν τοῖς μέν βουλομένοις ἀναγινώσκειν ψυχαγωγίαν, τοῖς δέ φιλοφρονοῦσιν εἰς τὸ διὰ μνήμης ἀναλαβεῖν εὐκοπίαν, πᾶσιν δὲ τοῖς ἐντυγχάνουσιν ὡφέλειαν."}, {"sp": "N", "st": "2 Macc 2:26", "t": "καὶ ἡμῖν μέν τοῖς τὴν κακοπάθειαν ἐπιδεδιγμένοις τῆς ἐπιτομῆς οὐ ῥᾴδιον, ἱδρῶτος δὲ καὶ ἀγρυπνίας τὸ πρᾶγμα·"}, {"sp": "N", "st": "2 Macc 2:27", "t": "καθάπερ τῷ παρασκευάζοντι συμπόσιον, καὶ ζητοῦντι τὴν ἑτέρων λυσιτέλειαν, οὐκ εὐχερές· ὅμως διὰ τὴν τῶν πολλῶν εὐχαριστίαν ἡδέως τὴν κακοπάθειαν ὑποίσομεν·"}, {"sp": "N", "st": "2 Macc 2:28", "t": "τὸ μέν διακριβοῦν περὶ ἑκάστων τῷ συγγραφεῖ παραχωρήσαντες, τὸ δὲ ἐπιπορεύεσθαι τοῖς ὑπογραμμοῖς τῆς ἐπιτομῆς ἀτονοῦντες."}, {"sp": "N", "st": "2 Macc 2:29", "t": "καθάπερ γὰρ τῆς καινῆς οἰκίας ἀρχιτέκτονι τῆς ὅλης καταβολῆς φροντιστέον, τῷ δὲ ἐνκαινίζειν καὶ ζωγραφεῖν ἐπιχειροῦντι τὰ ἐπιτήδεια πρὸς διακόσμησιν ἐξεταστέον, οὕτως δοκῶ καὶ ἐπὶ ἡμῶν."}, {"sp": "N", "st": "2 Macc 2:30", "t": "τὸ μέν ἐμβατεύειν καὶ περίπατον ποιεῖσθαι λόγῳ καὶ πολυπραγμονεῖν ἐν τοῖς κατὰ μέρος, τῷ τῆς ἱστορίας ἀρχηγενέτῃ καθήκει·"}, {"sp": "N", "st": "2 Macc 2:31", "t": "τὸ δὲ σύντομον τῆς λέξεως μεταδιώκειν, καὶ τὸ ἐξεργαστικὸν τῆς πραγματίας παραιτεῖσθαι, τῷ τὴν μετάφρασιν ποιουμένῳ συνχωρητέον."}, {"sp": "N", "st": "2 Macc 2:32", "t": "Ἐντεῦθεν οὖν 'ρξώμεθα τῆς διηγήσεως, τοῖς προειρημένοις τοσοῦτον ἐπιζεύξαντες· εὔηθες γὰρ τὸ μὲν πρὸ τῆς ἱστορίας πλεονάζειν, τὴν δὲ ἱστορίαν ἐπιτέμνειν."}, {"sp": "N", "st": "2 Macc 3:1", "t": "Γῆς ἁγίας πόλεως κατοικουμένης μετὰ πάσης εἰρήνης, καὶ τῶν νόμων ὅτι κάλλιστα συντηρουμένων διὰ τὴν Ὀνείον τοῦ ἀρχιερέως εὐσέβειάν τε καὶ μισοπονηρίαν,"}, {"sp": "N", "st": "2 Macc 3:2", "t": "συνέβαινεν καὶ αὐτοὺς τοὺς βασιλεῖς τιμᾷν τὸν τόπον, καὶ τὸ ἱερὸν ἀποστολαῖς ταῖς κρατίσταις δοξάζειν·"}, {"sp": "N", "st": "2 Macc 3:3", "t": "ὥστε καὶ Σέλευκον τὸν τῆς Ἀσίας βασιλέα χορηγεῖν ἐκ τῶν ἰδίων προσόδων πάντα τὰ πρὸς τὰς λειτουργίας τῶν θυσιῶν ἐπιβάλλοντα δαπανήματα."}, {"sp": "N", "st": "2 Macc 3:4", "t": "Σίμων δέ τις ἐκ τῆς Βενιαμεὶν φυλῆς προστάτης τοῦ ἱεροῦ καθεσταμένος, διηνέχθη τῷ ἀρχιερεῖ περὶ τῆς κατὰ τὴν πόλιν ἀγορανομίας."}, {"sp": "N", "st": "2 Macc 3:5", "t": "καὶ νικῆσαι τὸν Ὀνίαν μὴ δυνάμενος, ἦλθεν πρὸς Ἀπολλώνιον Θρασαίου, τὸν κατʼ ἐκεῖνον τὸν καιρὸν Κοίλης Συρίας καὶ Φοινίκης στρατηγόν."}, {"sp": "N", "st": "2 Macc 3:6", "t": "καὶ προσήγγειλεν περὶ τοῦ χρημάτων ἀμυθήτων γέμειν τὸ ἐν Ἰεροσολύμοις γαζοφυλάκιον, ὥστε τὸ πλῆθος τῶν διαφόρων ἀναρίθμητον εἶναι, καὶ μὴ προσενεγκεῖν αὐτὰ πρὸς τὸν τῶν θυσιῶν λόγον, εἶναι δὲ δυνατὸν ὑπὸ τὴν τοῦ βασιλέως ἐξουσίαν πεσεῖν ταῦτα."}, {"sp": "N", "st": "2 Macc 3:7", "t": "συμμίξας δὲ Ἀπολλώνιος τῷ βασιλεῖ, περὶ τῶν μηνυθέντων αὐτῷ χρημάτων ἐνεφάνισεν· ὁ δέ προχειρισάμενος Ἡλιόδωρον τὸν ἐπὶ τῶν πραγμάτων ἀπέστειλεν, δοὺς ἐντολὰς τὴν τῶν προειρημένων χρημάτων ἐκκομιδὴν ποιήσασθαι."}, {"sp": "N", "st": "2 Macc 3:8", "t": "εὐθέως δὲ ὁ Ἡλιόδωρος ἐποιεῖτο τὴν πορίαν, τῇ μέν ἐνφάσει ὡς τὰς κατὰ Κοίλην Συρίαν καὶ Φοινίκην πόλεις ἐφοδεῦσαι, τῷ πράγματι δὲ τὴν τοῦ βασιλέως πρόθεσιν ἐπιτελεῖν."}, {"sp": "N", "st": "2 Macc 3:9", "t": "παραγενηθεὶς δὲ εἰς Ἰεροσόλυμα, καὶ φιλοφρόνως ὑπὸ τοῦ ἀρχιερέως τῆς πόλεως ἀποδεχθείς, ἀνέθετο περὶ τοῦ γεγονότος ἐμφανισμοῦ, καὶ τίνος ἕνεκεν πάρεστιν διεσαφήνισεν· ἐπυνθάνετο δὲ εἰ ταῖς ἀληθείαις ταῦτα οὕτως ἔχοντα τυγχάνει."}, {"sp": "N", "st": "2 Macc 3:10", "t": "τοῦ δὲ ἀρχιερέως ὑποδείξαντος παρακαταθήκας εἶναι χηρῶν τε καὶ ὀρφανῶν,"}, {"sp": "N", "st": "2 Macc 3:11", "t": "τινὰ δὲ καὶ Ὑρκανοῦ τοῦ Γωβίου σφόδρα ἀνδρὸς ἐν ὑπεροχῇ κειμένου—οὐχ οὕτως διαβάλλων ὁ δυσσεβὴς Σίμων—τὰ δὲ πάντα ἀργυρίου τετρακόσια τάλαντα, χρυσίου δὲ διακόσια·"}, {"sp": "N", "st": "2 Macc 3:12", "t": "ἀδικῆσαί τε τοὺς πεπιστευκότας τῇ τοῦ τόπου ἁγιωσύνῃ καὶ τῇ τοῦ τετιμημένου κατὰ τὸν σύμπαντα κόσμον ἱεροῦ σεμνότητι καὶ ἀσυλία, παντελῶς ἀμήχανον εἶναι"}, {"sp": "N", "st": "2 Macc 3:13", "t": "ὁ δ᾿ ἕτερος, δι᾿ ἂς εἶχεν βασιλικὰς ἐντολάς, πάντως ἔλεγεν εἰς τὸ βασιλικὸν ἀναλημπτέα ταῦτα εἶναι."}, {"sp": "N", "st": "2 Macc 3:14", "t": "Ταξάμενος δέ ἡμέραν εἰσῄει τὴν περὶ τούτων ἐπίσκεψιν οἰκονομήσων· ἦν δὲ οὐ μικρὰ καθʼ ὅλην τὴν πόλιν ἀγωνία."}, {"sp": "N", "st": "2 Macc 3:15", "t": "οἱ δὲ ἱερεῖς πρὸ τοῦ θυσιαστηρίου ἐν ταῖς ἱερατικαῖς στολαῖς ῥίψαντες ἑαυτοὺς ἐπεκαλοῦντο εἰς οὐρανὸν τὸν περὶ παρακαταθήκης νομοθετήσαντα τοῖς παρακαταθεμένοις ταῦτα σῷα διαφυλάξαι."}, {"sp": "N", "st": "2 Macc 3:16", "t": "ἦν δὲ ὁρῶντα τὴν τοῦ ἀρχιερέως εἰδέαν τιτρώσκεσθαι τὴν διάνοιαν· ἡ γὰρ ὄψις καὶ τὸ τῆς χρόας παρηλλαγμένον ἐνέφαινεν τὴν κατὰ ψυχὴν ἀγωνίαν·"}, {"sp": "N", "st": "2 Macc 3:17", "t": "περιεκέχυτο γὰρ ἐπὶ τὸν ἄνδρα δέος τι καὶ φρικασμὸς σώματος, δι᾿ ὧν πρόδηλον ἐγίνετο τοῖς θεωροῦσιν τὸ κατὰ καρδίαν ἐνεστὸς ἄλγος."}, {"sp": "N", "st": "2 Macc 3:18", "t": "οἱ δὲ ἐκ τῶν οἰκιῶν ἀγεληδὸν ἐξεπήδων ἐπὶ πάνδημον ἱκετίαν, διὰ τὸ μὴ μέλλειν εἰς καταφρόνησιν ἔρχεσθαι τὸν τόπον."}, {"sp": "N", "st": "2 Macc 3:19", "t": "ὑπεζωσμέναι δὲ ὑπὸ τοὺς μαστοὺς αἱ γυναῖκες σάκκους κατὰ τὰς ὁδοὺς ἐπλήθυνον· αἱ δὲ κατάκλειστοι τῶν παρθένων, αἱ μέν συνέτρεχον ἐπὶ τοῖς πυλῶνας, αἱ δὲ ἐπὶ τὰ τείχη, τινὲς δὲ διὰ τῶν θυρίδων διέκυπτον."}, {"sp": "N", "st": "2 Macc 3:20", "t": "πᾶσαι δέ προτείνουσαι τὰς χεῖρας εἰς τὸν οὐρανὸν ἐποιοῦντο τὴν λιτανείαν·"}, {"sp": "N", "st": "2 Macc 3:21", "t": "ἐλεεῖν δὲ τὴν τοῦ πλήθους πανμιγῆ πρόπτωσιν, τὴν τε τοῦ μεγάλως ἀγωνιῶντος ἀρχιερέως προσδοκίον."}, {"sp": "N", "st": "2 Macc 3:22", "t": "Ιἱ μέν οὗν ἐπεκαλοῦντο τὸν πανκρατῆ κύριον τὰ πεπιστευμένα τοῖς πεπιστευκόσιν σῶα διαφυλάσσειν μετὰ πάσης ἀσφαλείας."}, {"sp": "N", "st": "2 Macc 3:23", "t": "ὁ δὲ Ἡλιόδωρος τὸ διεγνωσμένον ἐπετέλει."}, {"sp": "N", "st": "2 Macc 3:24", "t": "αὐτόθι δὲ αὐτοῦ σὺν τοῖς δορυφόροις κατὰ τὸ γαζοφυλάκιον ἤδη παρόντος, ὁ τῶν πνευμάτων καὶ πάσης ἐξουσίας δυνάστης ἐπιφανίαν μεγάλην ἐποίησεν, ὥστε πάντας τοὺς κατατολμήσαντας συνελθεῖν, καταπλαγέντας τὴν τοῦ θεοῦ δύναμιν, εἰς ἔκλυσιν καὶ δειλίαν τραπῆναι."}, {"sp": "N", "st": "2 Macc 3:25", "t": "ὤφθη γάρ τις ἵππος αὐτοῖς φοβερὸν ἔχων τὸν ἐπιβάτην, καὶ καλλίστῃ σαγῇ διακεκοσμημένος, φερόμενος δὲ Ῥύθην ἔσεισεν τῷ Ἡλιοδώρῳ τὰς ἐνπροθεσίους ὁπλάς· ὁ δὲ ἐπικαθήμενος ἐφαίνετο χρυσῆν πανοπλίαν ἔχων."}, {"sp": "N", "st": "2 Macc 3:26", "t": "ἕτεροι δὲ δύο ἐφάνησαν αὐτῷ νεανίαι τῇ ῥώμῃ μέν ἐκπρεπεῖς, κάλλιστοι δέ τὴν γλῶσσαν, διαπρεπεῖς δὲ τὴν περιβολήν· οἳ καὶ παριστάντες ἐξ ἑκατέρου μέρους ἐμαστίγουν αὐτὸν ἀδιαλείπτως, πολλὰς ἐπιριπτοῦντες αὐτῷ πληγάς."}, {"sp": "N", "st": "2 Macc 3:27", "t": "ἄφνω δέ πεσόντα πρὸς τὴν γῆν καὶ πολλῷ σκότει περιχυθέντα συναρπάσαντες καὶ εἰς φόριον ἐνθέντες,"}, {"sp": "N", "st": "2 Macc 3:28", "t": "τὸν ἄρτι μετὰ πολλῆς παραδρομῆς καὶ πάσης δορυφορίας εἰς τὸ προειρημένον εἰσελθόντα γαζοφυλάκιον, ἔφερον ἀβοήθητον αὐτὸν τοῖς ὅλοις καθεστῶτα, φανερῶς τὴν δυναστίαν ἐπεγνωωκότα."}, {"sp": "N", "st": "2 Macc 3:29", "t": "καὶ ὁ μέν διὰ τὴν θείαν ἐνέργειαν ἄφωνος καὶ πάσης ἐστερημένος ἐλπίδος καὶ σωτηρίας ἔριπτο·"}, {"sp": "N", "st": "2 Macc 3:30", "t": "οἱ δὲ τὸν κύριον εὐλόγουν τὸν παραδοξάζοντα τὸν ἑαυτοῦ τόπον· καὶ τὸ μικρῷ πρότερον δέους καὶ ταραχῆς γέμον ἱερόν, τοῦ παντοκράτορος ἐπιφανέντος κυρίου, χαρᾶς καὶ εὐφροσύνης ἐπλήρωτο."}, {"sp": "N", "st": "2 Macc 3:31", "t": "Ταχὺ δέ τινες τῶν τοῦ Ἡλιοδώρου συνήθων ἠξίουν τὸν Ὀνίαν ἐπικαλέσασθαι τὸν ὕψιστον, καὶ τὸ ζῆν χαρίσασθαι τῷ παντελῶς ἐν ἐσχάτῃ πνοῇ κειμένῳ."}, {"sp": "N", "st": "2 Macc 3:32", "t": "ὕποπτος δέ γενόμενος ὁ ἀρχιερεὺς μή ποτε διάλημψιν ὁ βασιλεὺς σχῇ κακουργίαν τινὰ περὶ τὸν Ἡλιόδωρον ὑπὸ τῶν Ἰουδαίων συντετελέσθαι, προσήγαγεν θυσίαν ὑπέρ τῆς τοῦ ἀνδρὸς σωτηρίς."}, {"sp": "N", "st": "2 Macc 3:33", "t": "ποιουμένου δὲ τοῦ ἀρχιερέως τὸν ἱλασμὸν οἱ αὐτοὶ νεανίαι πάλιν ἐφάνησαν τῷ Ἡλιοδώρῳ ἐν ταῖς αὐταῖς ἐσθήσεσιν ἐστολισμένοι, καὶ στάντες εἶπαν Πολλὰ Ὀνίᾳα τῷ ἀρχιερεῖ χάριτας ἔχε, διὰ γὰρ αὐτὸν σοὶ κεχάρισται τὸ ζῆν Κύριος."}, {"sp": "N", "st": "2 Macc 3:34", "t": "σὺ δὲ ἐξ οὐρανοῦ μεμαστιγωμένος διάγγελλε πᾶσι τὸ μεγαλεῖον τοῦ θεοῦ κράτος. ταῦτα δὲ εἰπόντες ἀφανεῖς ἐγένοντο."}, {"sp": "N", "st": "2 Macc 3:35", "t": "ὁ δὲ Ἡλιόδωρος θυσίαν ἀνενεγκὼν τῷ θεῷ, καὶ εὐχὰς μεγίστας εὐξάμενος τῷ τὸ ζῆν περιποιήσαντι, καὶ τὸν Ὀνίαν ἀποδεξάμενος, ἀνεστρατοπέδευσεν πρὸς τὸν βασιλέα·"}, {"sp": "N", "st": "2 Macc 3:36", "t": "ἐξεμαρτύρει δὲ πᾶσιν ἅπερ ἦν ὑπʼ ὄψιν τεθεαμένος ἔργα τοῦ μεγίστου θεοῦ."}, {"sp": "N", "st": "2 Macc 3:37", "t": "Τοῦ δὲ βασιλέως ἐπερωτήσαντος τὸν Ἡλιόδωραν ποῖός τις εἴη ἐπιτήδειος ἔτι ἅπαξ διαπεμφθῆναι εἰς Ἰεροσόλυμα, ἔφησεν"}, {"sp": "N", "st": "2 Macc 3:38", "t": "Εἴ τινα ἔχεις πολέμιον ἡ πραγμάτων ἐπίβουλον, πέμψον αὐτὸν ἐκεῖ, καὶ μεμαστιγωμένον αὐτὸν προσδέξῃ, ἐάνπερ καὶ διασωθῇ, διὰ τὸ περὶ τὸν τόπον ἀληθῶς εἶναί τινα θεοῦ δύναμιν."}, {"sp": "N", "st": "2 Macc 3:39", "t": "αὐτὸς γὰρ ὁ τὴν κατοικίαν ἐπουράνιον ἔχων ἐπόπτης ἐστὶν καὶ βοηθὸς ἐκείνου τοῦ τόπου, καὶ τοὺς παραγινομένους ἐπὶ κακώσει τύπτων ἀπολλύει."}, {"sp": "N", "st": "2 Macc 3:40", "t": "καὶ τὰ μέν καθʼ Ἡλιόδωρον καὶ τὴν τοῦ γαζοφυλακίου τήρησιν οὕτως ἐχώρησεν."}, {"sp": "N", "st": "2 Macc 4:1", "t": "Ὁ δὲ προειρημένος Σίμων, ὁ τῶν χρημάτων καὶ τῆς πατρίδος ἐνδείκτης γεγονώς, ἐκακολόγει τὸν Ὀνίαν ὡς οὗτός τε εἴη τὸν Ἡλιόδωρον ἐπισεσεικὼς καὶ τῶν κακῶν δημιουργὸς καθεστηκώς·"}, {"sp": "N", "st": "2 Macc 4:2", "t": "καὶ τὸν εὐεργέτην τῆς πόλεως καὶ τὸν κηδεμόνα τῶν ὁμοεθνῶν καὶ ζηλωτὴν τῶν νόμων, ἐπίβουλον τῶν πραγμάτων ἐτόλμα λέγειν."}, {"sp": "N", "st": "2 Macc 4:3", "t": "τῆς δέ ἔχθρας ἐπὶ τοσοῦτον προβαινούσης, ὥστε καὶ διά τινος τῶν ὑπὸ τοῦ Σίμωνος δεδοκιμασμένων φόνους συντελεῖσθαι,"}, {"sp": "N", "st": "2 Macc 4:4", "t": "συνορῶν Ὄνίας τὸ χαλεπὸν τῆς φιλονεικίας καὶ Ἀπολλώνιον Μενεσθέως, τῶν Κοίλης Φοινίκης καὶ Συρίας στρατηγόν, συναύξοντα τὴν κακίαν τοῦ Σίμωνος,"}, {"sp": "N", "st": "2 Macc 4:5", "t": "πρὸς τὸν βασιλέα διεκοσμήθη, οὐ γινόμενος τῶν πολιτῶν κατήγορος, τὸ δὲ σύμφορον κοινῇ καὶ κατʼ ἰδίαν παντὶ τῷ πλήθει σκοπῶν."}, {"sp": "N", "st": "2 Macc 4:6", "t": "ἑώρα γὰρ ἄνευ βασιλικῆς προνοίας ἀδύνατον εἶναι τυχεῖν εἰρήνης ἐπὶ τὰ πράγματα, καὶ τὸν Σίμωνα παῦλαν οὐ λημψόμενον τῆς ἀνοίας."}, {"sp": "N", "st": "2 Macc 4:7", "t": "Μεταλλάξαντος δέ τὸν βίον Σελεύκου, καὶ παραλαβόντος τὴν βασιλείαν Ἀντιόχου τοῦ προσαγορευθέντος Ἐπιφανοῦς, ὑπενόθευσεν Ἰάσων ὁ ἀδελφὸς Ὀνίου τὴν ἀρχιερωσύνην·"}, {"sp": "N", "st": "2 Macc 4:8", "t": "ἐπαγγειλάμενος τῷ βασιλεῖ δι᾿ ἐντεύξεως ἀργυρίου τάλαντα ἑξήκοντα πρὸς τοῖς τριακοσίοις, καὶ προσόδου τινὸς ἄλλης τάλαντα ὀγδοήκοντα."}, {"sp": "N", "st": "2 Macc 4:9", "t": "πρὸς δέ τούτοις ὑπισχνεῖτο καὶ ἕτερα διαγράφειν πεντήκοντα πρὸς τοῖς ἑκατόν, ἐὰν ἐπιχορηγηθῇ διὰ τῆς ἐξουσίας αὐτοῦ γυμνάσιον καὶ ἐφηβίαν αὐτῷ συστήσασθαι, καὶ τοὺς ἐν Ἰεροσολύμοις Ἀντιοχεῖς ἀναγράψαι."}, {"sp": "N", "st": "2 Macc 4:10", "t": "ἐπινεύσαντος δὲ τοῦ βασιλέως καὶ τῆς ἀρχῆς κρατήσας, εὐθέως πρὸς τὸν Ἑλληνικὸν χαρακτῆρα τοὺς ὁμοφύλους μετέστησε."}, {"sp": "N", "st": "2 Macc 4:11", "t": "καὶ τὰ κείμενα τοῖς Ἰουδαίοις φιλάνθρωπα βασιλικὰ διὰ Ἰωάννου τοῦ πατρὸς Εὐπολέμου, τοῦ ποιησαμένου τὴν πρεσβίαν ὑπέρ φιλίας καὶ συμμαχίας πρὸς τοὺς Ῥωμαίους, παρώσας, καὶ τὰς μέν νομίμας καταλύων πολιτίας, παρανόμους ἐθισμοὺς ἐκαίνιζεν."}, {"sp": "N", "st": "2 Macc 4:12", "t": "ἀσμένως γὰρ ὑπʼ αὐτὴν ἀκρόπολιν γυμνάσιον καθίδρυσεν, καὶ τοὺς κρατίστους τῶν ἐφʼ ἡμῶν ὑποτάσσων ὑπὸ πέτασον ἤγαγεν."}, {"sp": "N", "st": "2 Macc 4:13", "t": "ἧυ δʼ οὕτως ἀκμὴ τοῦ Ἑλληνισμοῦ καὶ πρόσβασις ἀλλοφυλισμοῦ διὰ τὴν τοῦ ἀσεβοῦς καὶ οὐκ ἀρχιερέως Ἰάσονος ὑπερβάλλουσαν ἀναγνείαν,"}, {"sp": "N", "st": "2 Macc 4:14", "t": "ὥστε μηκέτι περὶ τὰς τοῦ θυσιαστηρίου λειτουργίας προθύμους εἶναι τοὺς ἱερεῖς, ἀλλὰ τοῦ μέν νεὼ καταφρονοῦντες καὶ τῶν θυσιῶν ἀμελοῦντες ἔσπευδον μετέχειν τῆς ἐν παλαίστρῃ παρανόμου χορηγίας, μετὰ τὴν τοῦ δίσκου πρόσκλησιν·"}, {"sp": "N", "st": "2 Macc 4:15", "t": "καὶ τὰς μέν πατρῴας τιμὰς ἐν οὐδενὶ τεθειμένοι, τὰς δὲ Ἐλληνικὰς δόξας καλλίστας ἡγούμενοι."}, {"sp": "N", "st": "2 Macc 4:16", "t": "ὦς καὶ χάριν περιέσχεν αὐτοὺς χαλεπὴ περίστασις, καὶ ὧν ἐζήλουν τὰς ἀγωγὰς καὶ καθʼ ὃ ἅπαν ἤθελον ἐξομοιοῦσθαι, τοὺς πολεμίους καὶ τιμωρητάς ἔσχον."}, {"sp": "N", "st": "2 Macc 4:17", "t": "ἀσεβεῖν γὰρ εἰς τοὺς θείους νόμους οὐ ῥᾴδιον· ἀλλὰ ταῦτα ὁ ἀκόλουθος καιρὸς δηλώσει."}, {"sp": "N", "st": "2 Macc 4:18", "t": "Ἀγομένου δέ πενταετηρικοῦ ἀγῶνος ἐν Τύρῳ, καὶ τοῦ βασιλέως παρόντος,"}, {"sp": "N", "st": "2 Macc 4:19", "t": "ἀπέστειλεν Ἰάσων ὁ μιερὸς θεωροὺς ὡς ἀπὸ Ἰεροσολύμων Ἀντιοχέας παρακομίζοντας ἀργυρίου δραχμὰς τριακοσίους εἰς τὴν τοῦ Ἡρακλέους θυσίαν, ἃς καὶ ἠξίωσαν οἱ παρακομίζοντες μὴ χρῆσθαι εἰς θυσίαν,"}, {"sp": "N", "st": "2 Macc 4:20", "t": "ἕνεκα δὲ τῶν παρόντων εἰς τὰς τῶν τριηρέων κατασκευάς."}, {"sp": "N", "st": "2 Macc 4:21", "t": "Ἀποσταλέντος δέ εἰς Αἴγυπτον Ἀπολλωνίου τοῦ Μενεσθέως διὰ τὰ πρωτοκλήσια ξοῦ Φιλομήτορος βασιλέως, μεταλαβὼν Ἀντίοχος ἀλλότριον αὐτὸν τῶν αὐτοῦ γεγονότων πραγμάτων, τῆς καθʼ αὐτὸν ἀσφαλίας ἐφρόντιζεν· ὅθεν εἰς Ἰόππην παραγενόμενος. κατήντησεν εἰς Ἰεροσόλυμα."}, {"sp": "N", "st": "2 Macc 4:22", "t": "μεγαλομερῶς δὲ ὑπὸ τοῦ Ἰάσονος καὶ τῆς πόλεως ἀποδεχθεὶς μετὰ δᾳδουχίας καὶ βοῶν εἰσεδέχθη· εἶθ᾿ οὕτως εἰς τὴν Φοινίκην κατεστρατοπέδευσεν."}, {"sp": "N", "st": "2 Macc 4:23", "t": "Μετὰ δὲ τριετῆ χρόνον ἀπέστειλεν Ἰάσων Μενέλαον, τὸν τοῦ προσημαινομένου Σίμωνος ἀδελφόν, παρακομίζοντα τὰ χρήματα τῷ βασιλεῖ, καὶ περὶ πραγμάτων ἀναγκαίων ὑπομνηματισμοὺς τελέσοντα."}, {"sp": "N", "st": "2 Macc 4:24", "t": "ἡ δὲ συσταθεὶς τῷ βασιλεῖ καὶ δοξάσας αὐτὸν τῷ προσώπῳ τῆς ἐξουσίας, εἰς ἑαυτὸν κατήντησεν ἀρχιερωσύνην, ὑπερβάλλων τὸν Ἰάσονα τάλαντα ἀργυρίου τριακόσια."}, {"sp": "N", "st": "2 Macc 4:25", "t": "λαβὼν δὲ τὰς βασιλικὰς ἐντολὰς παρεγίνετο, τῆς μέν ἀρχιερωσύνης οὐδὲν ἄξιον φέρων, θυμοὺς δὲ ὠμοῦ τυράννου καὶ θηρὸς βαρβάρου ὀργὰς ἔχων."}, {"sp": "N", "st": "2 Macc 4:26", "t": "καὶ ὁ μέν Ἰάσων ὁ τὸν ἴδιον ἀδελφὸν ὑπονοθεύσας, ὑπονοθευθεὶς ὑφʼ ἑτέρου φυγὰς εἰς τὴν Ἀμμανῖτιν χώραν συνήλαστο."}, {"sp": "N", "st": "2 Macc 4:27", "t": "ὁ δὲ Μενέλαος τῆς μέν ἀρχῆς ἐκράτει, τῶν δὲ ἐπηγγελμένων τῷ βασιλεῖ χρημάτων οὐδὲν εὐτάκτει·"}, {"sp": "N", "st": "2 Macc 4:28", "t": "ποιουμένου δὲ τὴν ἀπαίτησιν Σωστράτου τοῦ τῆς ἀκροπόλεως ἐπάρχου· πρὸς τοῦτον γὰρ ἦν ἡ τῶν διαφόρων πρᾶξις· δι᾿ ἣν αἰτίαν οἱ δύο ὑπὸ τοῦ βασιλέως προσεκλήθησαν·"}, {"sp": "N", "st": "2 Macc 4:29", "t": "καὶ ὁ μέν Μενέλαος ἀπέλειπεν τῆς ἀρχιερωσύνης διάδοχον λυσίμαχον τὸν ἑαυτοῦ ἀδελφόν, Σώστρατος δέ Κράτητα τὸν ἐπὶ τῶν Κυπρίων."}, {"sp": "N", "st": "2 Macc 4:30", "t": "Τοιούτων δὲ συνεστηκότων, συνέβη Ταρσεῖς καὶ Μαλλώτας στασιάζειν, διὰ τὸ Ἀντιοχίδι τῇ παλλακῇ τοῦ βασιλέως ἐν δωρεᾷ δίδοσθαι."}, {"sp": "N", "st": "2 Macc 4:31", "t": "θᾶττον οὖν ὁ βασιλεὺς ἧκεν καταστεῖλαι τὰ πράγματα, καταλείπων τὸν διαδεχόμενον Ἀνδρόνικον, τῶν ἐν ἀξιώματι κεμένων."}, {"sp": "N", "st": "2 Macc 4:32", "t": "νομίσας δὲ ὁ Μενέλαος εἰληφέναι καιρὸν εὐφυῆ, χρυσώματά τινα τῶν τοῦ ἱεροῦ νοσφισάμενος ἐχαρίσατο τῷ Ἀνδρονίκῳ, καὶ ἕτερα ἐτύγχανεν πεπρακὼς εἰς τε Τύρον καὶ τὰς κύκλῳ πόλεις."}, {"sp": "N", "st": "2 Macc 4:33", "t": "καὶ σαφῶς ἐπεγνωκὼς ὁ Ὀνείας, ἀπήνεγκεν ἀποκεχωρηκώς εἰς ἄσυλον τόπον, ἐπὶ Δάφνης τῆς πρὸς Ἀντιοχείας κειμένης."}, {"sp": "N", "st": "2 Macc 4:34", "t": "ὅθεν ὁ Μενέλαος λαβὼν ἰδίᾳ τὸν Ἀνδρόνικον, παρεκάλει χειρώσασθαι τὸν Ὀνίαν· ὁ δὲ παραγενόμενος ἐπὶ τὸν Ὀνίαν καὶ πεισθεὶς ἐπὶ δόλῳ καὶ δεξιασθεὶς μεθʼ ὅρκων, δοὺς δεξιάν, καίπερ ἐν ὑποψίᾳ κείμενος, ἔπεισεν ἐκ τοῦ ἀσύλου προελθεῖν· ὃν καὶ παραχρῆμα παρέκλεισεν, οὐκ αἰδεσθεὶς τὸ δίκαιον."}, {"sp": "N", "st": "2 Macc 4:35", "t": "δι᾿ ἣν αἰτίαν οὐ μόνον Ἰουδαῖοι, πολλοὶ δὲ καὶ τῶν ἄλλων ἐθνῶν ἐδείναζον καὶ ἐδυσφόρουν ἐπὶ τῷ τοῦ ἀνδρὸς ἀδίκῳ φόνῳ."}, {"sp": "N", "st": "2 Macc 4:36", "t": "τοῦ δὲ βασιλέως ἐπανελθόντος ἀπὸ τῶν κατὰ Κιλικίαν τόπων, ἐνετύγχανον οἱ κατὰ πόλιν Ἰουδαῖοι, συνμισοπονηρούντων καὶ τῶν Ἐλλήνων, ὑπέρ τοῦ παρὰ λόγον τὸν Ὀνίαν ἀπεκτονῆσθαι."}, {"sp": "N", "st": "2 Macc 4:37", "t": "ψυχικῶς οὗν ὁ Ἀντίοχος ὑπολυπηθεὶς καὶ τραπεὶς ἐπὶ ἔλεος, καὶ δακρύσας διὰ τὴν τοῦ μετηλλαχότος σωφροσύνην καὶ πολλὴν εὐταξίαν,"}, {"sp": "N", "st": "2 Macc 4:38", "t": "καὶ πυρωθεὶς τοῖς θυμοῖς, παραχρῆμα τὴν τοῦ Ἀνδρονίκου πορφύραν περιελόμενος καὶ τοὺς χιτῶνας περιρήξας, περιαγαγὼν καθʼ ὁλην τὴν πόλιν ἐπʼ αὐτὸν τὸν τόπον οὕπερ τὸν Ὀνίαν ἠσέβησεν, ἐκεῖτὸν μιαιφόνον ἀπεκόσμησεν, τοῦ κυρίου τὴν ἀξίαν αὐτῷ κόλασιν ἀποδόντος."}, {"sp": "N", "st": "2 Macc 4:39", "t": "Γενομένων δὲ πολλῶν ἱεροσυλημάτων κατὰ τὴν πόλιν ὑπὸ τοῦ Λυσιμάχου μετὰ τῆς τοῦ Μενελάου γνώμης. καὶ διαδοθείσης ἔξω τῆς φήμης. ἐπισυνήχθη τὸ πλῆθος ἐπὶ τὸν Λυσίμαχον. χρυσωμάτων ἤδη πολλῶν διενηνεγμένων."}, {"sp": "N", "st": "2 Macc 4:40", "t": "ἐπεγειρομένων δὲ τῶν ὄχλων καὶ ταῖς ὀργαῖς διεμπιπλαμένων, καθοπλίσας ὁ Λυσίμαχος πρὸς τρισχιλίους, κατήρξατο χειρῶν ἀδίκων, προηγησαμένου τινὸς Αὑρανοῦ προβεβηκότος τὴν ἡλικίαν, οὐδὲν δὲ ἧττον καὶ τὴν ἄγνοιαν."}, {"sp": "N", "st": "2 Macc 4:41", "t": "συνειδότες δὲ καὶ τὴν ἐπίθεσιν τοῦ λυσιμάχου, συναρπάσαντες οἱ μέν πέτρους, οἱ δὲ ξύλων πάχη, τινὲς δὲ ἐκ τῆς παρακειμένης σποδοῦ δρασσόμενοι, φύρδην ἐνετίνασσον εἰς τοὺς περὶ τὸν Λυσίμαχον."}, {"sp": "N", "st": "2 Macc 4:42", "t": "δι᾿ ἣν αἰτίαν πολλοὺς μέν αὐτῶν τραυματίας ἐποίησαν, τινὰς δέ κατέβαλον, πάντας δὲ εἰς φυγὴν συνήλασαν, αὐτὸν δὲ τὸν ἱερόσυλον παρὰ τὸ γαζοφυλάκιον ἐχειρώσαντο."}, {"sp": "N", "st": "2 Macc 4:43", "t": "Περὶ δὲ τούτων ἐνέστη κρίσις ἐπὶ τὸν Μενέλαον."}, {"sp": "N", "st": "2 Macc 4:44", "t": "καταντήσαντος δὲ τοῦ βασιλέως εἰς Τύρον, ἐπʼ αὐτοῦ τὴν δικαιολογίαν ἐποιήσαντο οἱ πεμφθέντες τρεῖς ἄνδρες ὑπὸ τῆς γερουσίας."}, {"sp": "N", "st": "2 Macc 4:45", "t": "ἤδη δὲ λελιμμένος ὁ Μενέλαος ἐπηγγείλατο χρήματα ἱκανὰ τῷ Πτολεμαίῳ Δορυμένους, πρὸς τὸ πεῖσαι τὸν βασιλέα."}, {"sp": "N", "st": "2 Macc 4:46", "t": "ὅθεν ἀπολαβὼν ὁ Πτολεμαῖος εἰς τι περίστυλον ὡς ἀναψύχοντα τὸν βασιλέα μετέθηκεν."}, {"sp": "N", "st": "2 Macc 4:47", "t": "καὶ τὸν μέν τῆς ὅλης κακίας αἴτιον Μενέλαον ἀπέλυσεν τῶν κατηγορημένων, τοῖς δὲ ταλαιπώροις, οἵτινες εἰ καὶ ἐπὶ Σκυθῶν ἔλεγον ἀπελύθησαν ἀκατάγνωστοι, τούτοις θάνατον ἀπέκρινεν."}, {"sp": "N", "st": "2 Macc 4:48", "t": "ταχέως οὗν τὴν ἄδικον ζημίαν ὑπέσχον οἱ περὶ πόλεως καὶ δήμων καὶ τῶν ἱερῶν σκευῶν προηγορήσαντες."}, {"sp": "N", "st": "2 Macc 4:49", "t": "δι᾿ ἣν αἰτίαν καὶ Τύριοι μισοπονηρεύσαντες τὰ πρὸς τὴν κηδίαν αὐτῶν μεγαλομερῶς ἐχορήγησαν."}, {"sp": "N", "st": "2 Macc 4:50", "t": "ὁ δὲ Μενέλαος διὰ τὰς τῶν κρατούντων πλεονεξίας ἔμενεν ἐπὶ τῇ ἀρχῇ, ἐπιφυόμενος τῇ κακίᾳ, μέγας τῶν πολιτῶν ἐπίβουλος καθεστώς."}, {"sp": "N", "st": "2 Macc 5:1", "t": "Περὶ δὲ τὸν καιρὸν τοῦτον τὴν δευτέραν ἄφοδον ὁ Ἀντίοχος εἰς Αἴγυπτον ἐστείλατο."}, {"sp": "N", "st": "2 Macc 5:2", "t": "συνέβη δὲ καθʼ ὅλην τὴν πόλιν σχεδὸν ἐφʼ ἡμέρας τεσσεράκοντα φαίνεσθαι διὰ τῶν ἀέρων τρέχοντας ἱππεῖς διαχρύσους στολὰς ἔχοντας, καὶ λόγχας σπειρηδὸν ἐξωπλισμένους,"}, {"sp": "N", "st": "2 Macc 5:3", "t": "καὶ μαχαιρῶν σπασμούς, καὶ εἴλας ἵππων διατεταγμένας, καὶ προσβολὰς γινομένας καὶ καταδρομὰς ἑκατέραων, καὶ ἀσπίδων κινήσεις, καὶ καμάτων πλήθη, καὶ βελῶν βολάς, καὶ χρυσέων κόσμων ἐκλάμψεις, καὶ παντοίους θωρακισμούς."}, {"sp": "N", "st": "2 Macc 5:4", "t": "διὸ πάντες ἠξίουν ἐπʼ ἀγαθῷ τὴν ἐπιφανίαν γεγενῆσθαι."}, {"sp": "N", "st": "2 Macc 5:5", "t": "Γενομένης δὲ λάλας ψευδοῦς, ὡς μετηλλαχότος Ἀντιόχου τὸν βίον, παραλαβὼν ὁ Ἰάσων οὐκ ἐλάττους τῶν χιλίων, ἐφνιδίως ἐπὶ τὴν πόλιν συνετελέσατο ἐπίθεσιν· τῶν δὲ ἐπὶ τῷ τείχει συνελασθέντων, καὶ τέλος ἤδη κταταλαμβανομένης τῆς πόλεως, ὁ Μενέλαος εἰς τὴν ἀκρόπολιν ἐφυγάδευκεν."}, {"sp": "N", "st": "2 Macc 5:6", "t": "ὁ δὲ Ἰάσων ἐποιεῖτο σφαγὰς τῆς πόλεως τῶν ἰδίων ἀφειδῶς, οὐ συννοῶν τὴν εἰς τοὺς συγγενεῖς εὐημερίαν δυσημερίαν εἶναι τὴν μεγίστην, δοκῶν δὲ πολεμίων καὶ οὐχ ὁμοεθνῶν τρόπαια καταβάλλεσθαι."}, {"sp": "N", "st": "2 Macc 5:7", "t": "τῆς μέν ἀρχῆς οὐκ ἐκράτησεν, τὸ δέ τέλος τῆς ἐπιβουλῆς αἰσχύνην λαβών, φυγὰς πάλιν εἰς τὴν Ἀμμανῖτιν παρῆλθεν."}, {"sp": "N", "st": "2 Macc 5:8", "t": "πέρας οὖν κακῆς καταστροφῆς ἔτυχεν, ἐγκλεισθεὶς πρὸς Ἀρέταν τὸν τῶν Ἀράβων τύραννον, πόλιν ἐκ πόλεως φεύγων, διωκόμενος ὑπὸ πάντων, στυγούμενος ὡς τῶν νόμων ἀποστάτης καὶ βδελυσσόμενος ὡς πατρίδος καὶ πολιτῶν δήμιος, εἰς Αἴγυπτον ἐξεβράσθη."}, {"sp": "N", "st": "2 Macc 5:9", "t": "ὁ συχνοὺς τῆς πατρίδος ἀποξενώσας ἐπὶ ξένης ἀπώλετο, πρὸς Λακεδαιμονίους ἀναχθείς, ὡς διὰ τὴν συγγενίαν τευξόμενος σκέπης·"}, {"sp": "N", "st": "2 Macc 5:10", "t": "καὶ ὁ πλῆθος ἀτάφων ἐκρίψας ἀπένθητος ἐγενήθη, καὶ κηδίας οὐδ’ ἥστινος οὔτε πατρῴου νόμου μετέσχεν."}, {"sp": "N", "st": "2 Macc 5:11", "t": "Προσπεσόντων δέ τῷ βασιλεῖ περὶ τῶν γεγονότων, διέλαβεν ἀποστάτιν τὴν Ἰουδαίαν· ὅθεν ἀναζεύξας ἐξ Αἰγύπτου τεθηριωμένος τῇ ψυχῇ, ἔλαβεν τὴν μέν πόλιν δοριάλωτον."}, {"sp": "N", "st": "2 Macc 5:12", "t": "καὶ ἐκέλευσεν τοῖς στρατιώταις κόπτειν ἀφειδῶς τοὺς ἐνπίπτοντας, καὶ τοὺς ἐν ταῖς οἰκίαις ἀναβαίνοντας κατασφάζειν."}, {"sp": "N", "st": "2 Macc 5:13", "t": "ἐγίνετο δὲ νέων καὶ πρεσβυτέρων ἀναίρεσις, ἀνήβων τε καὶ γυναικῶν καὶ τέκνων ἀφανισμός, παρθένων τε καὶ νηπίων σφαγαί."}, {"sp": "N", "st": "2 Macc 5:14", "t": "ὀκτὼ δὲ μυριάδες ἐν ταῖς πάσαις ἡμέραις τρισὶν κατεφθάρησαν, τέσσαρες μέν ἐν χεῖρῶν νόμοις, οὐχ ἧττον δὲ τῶν ἐσφαγμένων ἐπράθησαν."}, {"sp": "N", "st": "2 Macc 5:15", "t": "οὐκ ἄρκεσθεὶς δέ τούτοις, κατετόλμησεν εἰς τὸ πάσης τῆς γῆς ἁγιώτατον ἱερὸν εἰσελθεῖν, ὁδηγὸν ἔχων τὸν Μενέλαον, τὸν καὶ τῶν νόμων καὶ τῆς πατρίδος προδότην γεγονότα,"}, {"sp": "N", "st": "2 Macc 5:16", "t": "καὶ ταῖς μιεραις χερσὶν τὰ ἱερὰ σκεύη λαμβάνων, καὶ τὰ ὑπὸ πολλῶν βασιλέων ἀνασταθέντα πρὸς αὔξησιν καὶ δόξαν τοῦ τόπου καὶ τιμήν, ταῖς βεβήλοις χερσὶν συνσύρων."}, {"sp": "N", "st": "2 Macc 5:17", "t": "καὶ ἐμετεωρίζετο τὴν διάνοιαν ὁ Ἀντίοχος, οὐ συνορῶν ὅτι διὰ τὰς ἁμαρτίας τῶν τὴν πόλιν οἰκούντων ἀπώργισται βραχέως ὁ δεσπότης, διὸ γέγονεν περὶ τὸν τόπον παρόρασις."}, {"sp": "N", "st": "2 Macc 5:18", "t": "εἰ δέ μὴ συνέβη προσενέχεσθαι πολλοῖς ἁμαρτήμασιν, καθάπερ ἦν ὁ Ἡλιόδωρος ὁ πεμφθεὶς ὑπὸ Σελεύκου τοῦ βασιλέως ἐπὶ τὴν ἐπίσκέψιν τοῦ γαζοφυλακίου, οὗτος προαχθεὶς παραχρῆμα μαστιγωθεὶς ἀνετράπη τοῦ θράσους."}, {"sp": "N", "st": "2 Macc 5:19", "t": "ἀλλʼ οὐ διὰ τὸν τόπον τὸ ἔθνος, ἀλλὰ διὰ τὸ ἔθνος τὸν τόπον ὁ κύριος ἐξελέξατο."}, {"sp": "N", "st": "2 Macc 5:20", "t": "διόπερ καὶ αὐτὸς ὁ τόπος συνμετασχῶν τοῦ ἔθνους δυσπετημάτων γενομένων, ὕστερον εὐεργετημάτων ἐκοινώνησεν· καὶ ὁ καταληφθεὶς ἐν τῇ τοῦ παντοκράτορος ὀργῇ, πάλιν ἐν τῇ τοῦ μεγάλου δεσπότου καταλλαγῇ μετὰ πάσης δόξης ἐπανωρθώθη."}, {"sp": "N", "st": "2 Macc 5:21", "t": "Ὁ οὖν Ἀντίοχος ὀκτακόσια πρὸς τοῖς χιλίοις ἀπενεγκάμενος ἐκ τοῦ ἱεροῦ τάλαντα θᾶττον εἰς τὴν Ἀντιοχίαν ἐχωρίσθη, οἰόμενος ἀπὸ τῆς ὑπερηφανίας τὴν μέν γῆν πλωτὴν καὶ τὸ πέλαγος πορευτὸν θέσθαι, διὰ τὸν μετεωρισμὸν τῆς καρδίας."}, {"sp": "N", "st": "2 Macc 5:22", "t": "κατέλειπεν δέ καὶ ἐπιστάτας τοῦ κακοῦν τὸ γένος, ἐν μέν Ἰεροσολύμοις Φίλιππον τὸ μέν γένος Φρύγα, τὸν δὲ τρόπον βαρβαρώτερον ἔχοντα τοῦ καταστήσαντος·"}, {"sp": "N", "st": "2 Macc 5:23", "t": "ἐν δὲ Γαριζεὶν Ἀνδρόνικον· πρὸς δὲ τούτοις Μενέλαος χείριστα τῶν ἄλλων ὑπερῄρετο τοῖς πολίταις, ἀπεχθῆ δὲ πρὸς τοὺς πολίτας Ἰουδαίους ἔχων διάθεσιν."}, {"sp": "N", "st": "2 Macc 5:24", "t": "ἔπεμψεν δὲ τὸν μυσάρχην Ἀπολλώνιον μετὰ στρατεύματος, δισμυρίους δὲ τοῖς δισχιλίοις, προστάξας τοὺς ἐν ἡλικίᾳ πάντας κατασφάξαι, τὰς δέ γυναῖκας καὶ τοὺς νεωτέρους πωλεῖν."}, {"sp": "N", "st": "2 Macc 5:25", "t": "οὗτος δὲ παραγενόμενος εἰς Ἰεροσόλυμα καὶ τὸν εἰρηνικὸν ὑποκριθείς, ἐπέσχεν ἕως τῆς ἁγίας ἡμέρας τοῦ σαββάτου· καὶ λαβὼν ἀργοῦντας τοὺς Ἰουδαίους τοῖς ὑφʼ ἑαυτὸν ἐξοπλισίαν παρήγγειλεν,"}, {"sp": "N", "st": "2 Macc 5:26", "t": "καὶ τοὺς ἐλθόντας πάντας ἐπὶ τὴν θεωρίαν συνεξεκέντησεν, καὶ εἰς τὴν πόλιν σὺν τοῖς ὅπλοις εἰσδραμὼν ἱκανὰ κατέστησεν πλήθη."}, {"sp": "N", "st": "2 Macc 5:27", "t": "Ἰούδας δὲ ὁ καὶ Μακκαβαῖος, δέκατός που γενηθεὶς καὶ ἀναχωρήσας, ἐν τοῖς ὄρεσιν θηρίων τρόπον διέζη σὺν τοῖς μετʼ αὐτοῦ· καὶ τὴν χορτώδη τροφὴν σιτούμενοι διετέλουν, πρὸς τὸ μὴ μετασχεῖν τοῦ μολυσμοῦ."}, {"sp": "N", "st": "2 Macc 6:1", "t": "Μετʼ οὐ πολὺν δέ χρόνον ἐξαπέστειλεν ὁ βασιλεὺς γέροντα Ἀθηναῖον, ἀναγκάζειν τοὺς Ἰουδαίους μεταβαίνειν ἀπὸ τῶν πατρίων νόμων, καὶ τοῖς τοῦ θεοῦ νόμοις μὴ πολιτεύεσθαι·"}, {"sp": "N", "st": "2 Macc 6:2", "t": "μολῦναι δὲ καὶ τὸν ἐν Ἰεροσολύμοις νεὼ καὶ προσονομάσαι Διὸς Ὀλυμπίου, καὶ τὸν ἐν ΓΑριζει ν , καθὼς ἐτύγχανον οἱ τὸν τόπον οἰκοῦντες, Διὸς ξενίου."}, {"sp": "N", "st": "2 Macc 6:3", "t": "χαλεπὴ δὲ καὶ τοῖς ὅλοις ἦν δυσχερὴς ἡ ἐπίστασις τῆς κακίας."}, {"sp": "N", "st": "2 Macc 6:4", "t": "τὸ μέν γὰρ ἱερὸν ἀσωτίας καὶ κώμαον ὑπὸ τῶν ἐθνῶν ἐπεπληροῦτο ῥᾳθυμούντων μεθʼ ἑταιρῶν, καὶ ἐν τοῖς ἱεροῖς περιβόλων γυναιξὶ πλησιαζόντων, ἔτι δὲ τὰ μὴ καθήκοντα ἔνδον εἴσφερόντων."}, {"sp": "N", "st": "2 Macc 6:5", "t": "τὸ δὲ θυσιαστήριον τοῖς ἀποδιεσταλμένοις ἀπὸ τῶν νόμων ἀθεμίτοις ἐπεπλήρωτο."}, {"sp": "N", "st": "2 Macc 6:6", "t": "ἦν δʼ οὔτε σαββατίζειν, οὔτε πατρῴους ἑορτὰς διαφυλάττειν, οὔτε ἀπλῶς Ἰουδαῖον ὁμολογεῖν εἶναι."}, {"sp": "N", "st": "2 Macc 6:7", "t": "ἦγον δὲ μετὰ πικρᾶς ἀνάγκης εἰς τὴν κατὰ μῆνα τοῦ βασιλέως γενέθλιον ἡμέραν ἐπὶ σπλαγχνισμόν· γενομένης δέ Διονυσίων ἑορτῆς ἠναγκάζοντο κισσοὺς ἔχοντες πομπεύειν τῷ Διονύσῳ."}, {"sp": "N", "st": "2 Macc 6:8", "t": "ψήφισμα δὲ ἐξέπεσεν εἰς τὰς ἀστυγείτονας Ἑλληνίδας πόλεις, Πτολεμαίου ὑποθεμένου, τὴν αὐτὴν ἀγωγὴν κατὰ τῶν Ἰουδαίων ἄγειν καὶ σπλαγχνίζειν,"}, {"sp": "N", "st": "2 Macc 6:9", "t": "τοὺς δέ μὴ προαιρουμένους μεταβαίνειν ἐπὶ τὰ Ἑλληνικὰ κατασφάζειν. παρῆν οὖν ὁρᾷν τὴν ἐνεστῶσαν ταλαιπωρίαν."}, {"sp": "N", "st": "2 Macc 6:10", "t": "δύο γὰρ γυναῖκες ἀνήχθησαν περιτετμηκυῖαι τὰ τέκνα· τούτων δὲ ἐκ τῶν μαστῶν κρεμάσαντες τὰ βρέφη, καὶ δημοσίᾳ περιαγαγόντες αὐτὰς τὴν πόλιν, κατὰ τοῦ τείχους ἐκρήμνισαν."}, {"sp": "N", "st": "2 Macc 6:11", "t": "ἕτεροι δὲ πλησίον συνδραμόντες εἰς τὰ σπήλαια λεληθότως ἅγειν τὴν ἑβδομάδα, μηνυθέντες τῷ Φιλίππῳ συνεφλογίσθησαν, διὰ τὸ εὐλαβῶς ἔχειν βοηθῆσαι αὐτοῖς κατὰ δόξαν τῆς σεμνοτάτης ἡμέρας."}, {"sp": "N", "st": "2 Macc 6:12", "t": "Παρακαλῶ οὗν τοῖς ἐντυγχάνοντας τῇδε τῇ βίβλῳ μὴ συστέλλεσθαι διὰ τὰς συμφοράς, λογίζεσθαι δὲ τὰς τιμωρίας μὴ πρὸς ὄλεθρον, ἀλλὰ πρὸς παιδίαν τοῦ γένους ἡμῶν εἶναι."}, {"sp": "N", "st": "2 Macc 6:13", "t": "καὶ γὰρ τὸ μὴ πολὺν χρόνον ἐᾶσθαι τοὺς δυσσεβοῦντας, ἀλλʼ εὐθέως περιπίπτειν τοῖς ἐπιτίμοις, μεγάλης εὐεργεσίας σημεῖόν ἐστιν."}, {"sp": "N", "st": "2 Macc 6:14", "t": "οὐ γὰρ καθάπερ καὶ ἐπὶ τῶν ἄλλων ἐθνῶν ἀναμένει μακροθυμῶν ὁ δεσπότης μέχρι τοῦ καταντήσαντας αὐτοὺς πρὸς ἐκπλήρωσιν ἁμαρτιῶν κολάσῃ, οὕτως καὶ ἐφʼ ἡμῶν ἔκρινεν εἶναι·"}, {"sp": "N", "st": "2 Macc 6:15", "t": "ἴνα μὴ πρὸς τέλος ἀφικομένων ἡμῶν τῶν ἁμαρτιῶν ὕστερον ἡμᾶς ἐκδικᾷ."}, {"sp": "N", "st": "2 Macc 6:16", "t": "διόπερ οὐδέποτε μέν τὸν ἔλεον ἀφʼ ἡμῶν ἀφίστησιν· παιδεύων δέ μετὰ συμφορᾶς οὐκ ἐνκαταλείπει τὸν ἑαυτοῦ λαόν."}, {"sp": "N", "st": "2 Macc 6:17", "t": "πλὴν ἕως ὑπομνήσεως ταῦθʼ ἡμῖν εἰρήσθω· δι᾿ ὀλίγων δὲ ἐλευστέον ἐπὶ τὴν διήγησιν."}, {"sp": "N", "st": "2 Macc 6:18", "t": "Ἐλεάζαρός τις τῶν πρωτευόντων γραμματέων, ἀνήρ ἤδη προβεβηκὼς τὴν ἡλικίαν καὶ τὴν πρόσοψιν τοῦ προσώπου κάλλιστος, ἀναχαίνων ἠναγκάζετο φαγεῖν ὕειον κρέας."}, {"sp": "N", "st": "2 Macc 6:19", "t": "ὁ δὲ τὸν μετʼ εὐκλείας θάνατον μᾶλλον ἡ τὸν μετὰ μύσους βίον ἀναδεξάμενος αὐθαιρέτως ἐπὶ τὸ τύμπανον προσῆγεν,"}, {"sp": "N", "st": "2 Macc 6:20", "t": "προπτύσας δέ, καθʼ ὃν ἔδει τρόπον προσέρχεσθαι τοὺς ὑπομένοντας ἀμύνασθαι ὦν οὐ θέμις γεύσασθαι διὰ τὴν πρὸς τὸ ζῆν φιλοστοργίαν."}, {"sp": "N", "st": "2 Macc 6:21", "t": "οἱ δὲ πρὸς τῷ παρανόμῳ σπλαγχνισμῷ τεταγμένοι διὰ τὴν ἐκ τῶν παλαιῶν χρόνων πρὸς τὸν ἄνδρα γνῶσιν ἀπολαμβάνοντες αὐτὸν κατʼ ἰδίαν ἐνεκάλουν, ἐνεγκόντα κρέα, οἷς καθῆκον αὐτῷ χρᾶσθαι, δι᾿ αὐτοῦ παρασκευασθέντα, ὑποκρῖναι δὲ ὡς ἐσθίοντα τὰ ὑπὸ τοῦ βασιλέως τεταγμένα τῶν ἀπὸ τῆς θυσίας κρεῶν,"}, {"sp": "N", "st": "2 Macc 6:22", "t": "ἴνα τοῦτο πράξας ἀπολυθῇ τοῦ θανάτου, καὶ διὰ τὴν ἀρχαίαν πρὸς αὐτοὺς φιλίαν τύχοι φιλανθρωπίας."}, {"sp": "N", "st": "2 Macc 6:23", "t": "ὁ δὲ λογισμὸν ἀστεῖον ἀναλαβὼν καὶ ἄξιον τῆς ἡλικίας καὶ τῆς τοῦ γήρους ὑπεροχῆς καὶ τῆς ἐπικτήτου καὶ ἐπιφανοῦς πολιτείας καὶ τῆς ἐκ παιδὸς καλλίστης ἀναστροφῆς, μᾶλλον δὲ τῆς ἁγίας καὶ θεοκτίστου νομοθεσίας ἀκολούθως ἀπεφήνατο, ταχέως λέγων προπέμπειν εἰς τὸν ᾄδην"}, {"sp": "N", "st": "2 Macc 6:24", "t": "Οὐ γὰρ τῆς ἡμετέρας ἡλικίας ἄξιόν ἐστιν ὑποκριθῆναι, ἵνα πολλοὶ τῶν νέων ὑπολαβόντες Ἐλεάζαρον τὸν ἐνενηκονταετῆ μεταβεβηκέναι εἰς ἀλλοφυλισμόν,"}, {"sp": "N", "st": "2 Macc 6:25", "t": "καὶ αὐτοὶ διὰ τὴν ἐμὴν ὑπόκρισιν καὶ δᾶ τὸ μικρὸν καὶ ἀκαριαῖον ζῇν πλανηθῶσιν δι᾿ ἐμέ, καὶ μύσος καὶ κηλῖδα τοῦ γήρως κατακτήσωμαι."}, {"sp": "N", "st": "2 Macc 6:26", "t": "εἰ γὰρ καὶ ἐπὶ τοῦ παρόντος ἐξελοῦμαι τὴν ἐξ ἀνθρώπων τιμωρίαν, ἀλλὰ τὰς τοῦ παντοκράτορος χεῖρας οὔτε ζῶν οὔτε ἀποθανὼν ἐκφεύξομαι."}, {"sp": "N", "st": "2 Macc 6:27", "t": "διόπερ ἀνδρείως μέν νῦν διαλλάξας τὸν βίον τοῦ μέν γήρως ἄξιος φανήσομαι,"}, {"sp": "N", "st": "2 Macc 6:28", "t": "τοῖς δὲ νέοις ὑπόδιγμα γενναῖον καταλελοιπὼς εἰς τὸ προθύμως καὶ γενναίως ὑπέρ τῶν σεμνῶν καὶ ἁγίων νόμων ἀπευθανατίζειν. τοσαῦτα δὲ εἰπὼν ἐπὶ τὸ τύμπανον εὐθέως ἦλθεν,"}, {"sp": "N", "st": "2 Macc 6:29", "t": "τῶνδε ἀγόντων πρὸς αὐτὸν τὴν μικρῷ πρότερον εὐμένειαν δυσμένειαν διὰ τὴν τῶν προειρημένων λόγων, ὡς αὐτοὶ ὑπελάμβανον, ἀπόνοιαν."}, {"sp": "N", "st": "2 Macc 6:30", "t": "μέλλων δὲ ταῖς πληγαῖς τελευτᾷν, ἀναστενάξας εἶπεν Τῷ κυρίῳ τῷ τὴν ἁγίαν γνῶσιν ἔχοντι φανερόν ἐστιν ὅτι δυνάμενος ἀπολυθῆναι τοῦ θανάτου, σκληρὰς ὑποφέρω κατὰ σῶμα ἀλγηδόνας μαστιγούμενος, κατὰ ψυχὴν δὲ ἡδέως διὰ τὸν αὐτοῦ φόβον ταῦτα πάσχω."}, {"sp": "N", "st": "2 Macc 6:31", "t": "καὶ οὗτος οὗν τοῦτον τὸν τρόπον μετήλλαξεν, οὐ μόνον τοῖς νέοις, ἀλλὰ καὶ τοῖς πλείστοις τοῦ ἔθνους τὸν ἑαυτοῦ θάνατον ὑπόδιγμα γενναιότητος καὶ μνημόσυνον ἀρετῆς καταλείπων."}, {"sp": "N", "st": "2 Macc 7:1", "t": "Συνέβη δὲ καὶ ἑπτὰ ἀδελφοὺς μετὰ τῆς μητρὸς συλλημφθέντας ἀναγκάζεσθαι ὑπὸ τοῦ βασιλέως ἀπὸ τῶν ἀθεμίτων ὑείων κρεῶν ἐφάπτεσθαι, μάστιξιν καὶ νευραῖς αἰκιζομένους."}, {"sp": "N", "st": "2 Macc 7:2", "t": "εἰς δὲ αὐτῶν γενόμενος προήγορος εἶπεν Μέλλεις ἐρωτᾶν καὶ μανθάνειν ἡμῶν; ἕτοιμοι γὰρ ἀποθνήσκειν ἐσμὲν ἢ πατρῴους νόμους παραβαίνειν."}, {"sp": "N", "st": "2 Macc 7:3", "t": "ἔκθυμος δὲ γενόμενος ὁ βασιλεὺς προσέταξεν τήγανα καὶ λέβητας ἐκπυροῦν."}, {"sp": "N", "st": "2 Macc 7:4", "t": "τῶν δὲ παραχρῆμα ἐκπυρωθέντων, τὸν γενόμενον αὐτῶν προήγορον προσέταξεν γλωσσοτομεῖν, καὶ περισκυθίσαντας ἀκρωτηριάζειν, τῶν λοιπῶν ἀδελφῶν καὶ τῆς μητρὸς συνορώντων."}, {"sp": "N", "st": "2 Macc 7:5", "t": "ἄχρηστον δὲ αὐτὸν τοῖς λοιποῖς γενόμενον ἐκέλευσεν τῇ πῦρ προσάγειν ἔνπνουν καὶ τηγανίζειν. τῆς δὲ ἀτμίδος ἐφʼ ἱκανὸν διδούσης τοῦ τηγάνου ἀλλήλους παρεκάλουν σὺν τῇ μητρὶ γενναίως τελευτᾷν, λέγοντες οὕτως"}, {"sp": "N", "st": "2 Macc 7:6", "t": "Ὁ κύριος ὁ θεὸς ἐφορᾷ, καὶ ταῖς ἀληθείαις ἐφʼ ἡμῖν παρακαλεῖται, καθάπερ διὰ τῆς κατὰ πρόσωπον ἀντιμαρτυρούσης ᾠδῆς διεσάφησεν Μωσῆς, λέγων Καὶ ἐπὶ τοῖς δούλοις αὐτοῦ παρακληθήσεται."}, {"sp": "N", "st": "2 Macc 7:7", "t": "Μεταλλάξαντος δὲ τοῦ πρώτου τὸν τρόπον τοῦτον, τὸν δεύτερον ἦγον ἐπὶ τὸν ἐμπαιγμόν· καὶ τὸ τῆς κεφαλῆς δέρμα σὺν ταῖς θριξὶν περισύροντες ἐπηρώτων Εἰ φάγεσθαι πρὸ τοῦ τιμωρηθῆναι κατὰ μέλος τὸ σῶμα;"}, {"sp": "N", "st": "2 Macc 7:8", "t": "ὁ δὲ ἀποκριθεὶς τῇ πατρίῳ φωνῇ προσεῖπεν Οὐχί. διόπερ καὶ οὗτος τὴν ἐξῆς ἔλαβεν βάσανον, ὡς ὁ πρῶτος."}, {"sp": "N", "st": "2 Macc 7:9", "t": "ἐν ἐσχάτῃ δέ πνοῇ γενόμενος εἶπεν Σύ μέν, ἀλάστωρ, ἐκ του παρόντος ἡμᾶς ζῆν ἀπολύεις, ὁ δὲ τοῦ κόσμου βασιλεὺς ἀποθανόντας ἡμᾶς ὑπέρ τῶν αὐτοῦ νόμων εἰς αἰώνιον ἀναβίωσιν ζωῆς ἡμᾶς ἀναστήσει."}, {"sp": "N", "st": "2 Macc 7:10", "t": "Μετὰ δὲ τοῦτον ὁ τρίτος ἐνεπαίζετο, καὶ τὴν γλῶσσαν αἰτηθεὶς ταχέως προέβαλλεν καὶ τὰς χεῖρας εὐθαρσέως προέτεινεν·"}, {"sp": "N", "st": "2 Macc 7:11", "t": "καὶ γενναίως εἶπεν Ἐξ οὐρανοῦ ταῦτα κέκληται, καὶ διὰ τοὺς αὐτοῦ νόμους ὑπερορῶ ταῦτα, καὶ παρʼ αὐτοῦ ταῦτα πάλιν ἐλπίζω κομίζεσθαι"}, {"sp": "N", "st": "2 Macc 7:12", "t": "ὥστε αὐτὸν τὸν βασιλέα καὶ τοὺς σὺν αὐτῷ ἐκπλήσσεσθαι τὴν τοῦ νεανίσκου ψυχήν, ὡς ἐν οὐδενὶ τὰς ἀλγηδόνας ἐτίθετο."}, {"sp": "N", "st": "2 Macc 7:13", "t": "Καὶ τούτου δὲ μεταλλάξαντος τὸν τέταρτον ὡσαύτως ἐβασάνιζον αἰκιζόμενοι."}, {"sp": "N", "st": "2 Macc 7:14", "t": "καὶ γενόμενος πρὸς τῷ τελευτᾶν οὕτως ἔφη Αίρετὸν μεταλλάσσοντας ἀπὸ ἀνθρώπων τὰς ὑπὸ τοῦ θεοῦ προσδοκᾷν ἐλπίδας πάλιν ἀναστήσεσθαι ὑπʼ αὐτοῦ· σοὶ μέν γὰρ ἀνάστασις εἰς ζωὴν οὐκ ἔσται."}, {"sp": "N", "st": "2 Macc 7:15", "t": "Ἐχι μένως δὲ τὸν πέμπτον προσάγοντες ᾐκίζοντο."}, {"sp": "N", "st": "2 Macc 7:16", "t": "ὁ δὲ πρὸς αὐτὸν ἰδὸν εἶπεν Ἐξουσίαν ἐν ἀνθρώποις ἔχων ὃ θέλεις ποιεῖς, φθαρτὸς ὤν· μὴ δόκει δὲ τὸ γένος ἡμῶν ὑπὸ τοῦ θεοῦ καταλελεῖφθαι."}, {"sp": "N", "st": "2 Macc 7:17", "t": "σὺ δὲ καρτέρει, καὶ θεώρει τὸ μεγαλεῖον αὐτοῦ κράτος, ὡς σέ καὶ τὸ σπέρμα σου βασανιεῖ."}, {"sp": "N", "st": "2 Macc 7:18", "t": "Μετὰ δὲ τοῦτον ἦγον τὸν ἕκτον, καὶ μέλλων ἀποθνήσκειν ἔφη Μὴ πλανῶ μᾶλλον, ἡμεῖς γὰρ διʼ ἑαυτοὺς ταῦτα πάσχομεν, ἁμαρτόντες εἰς τὸν ἑαυτῶν θεόν· ἄξια θαυμασμοῦ γέγονεν·"}, {"sp": "N", "st": "2 Macc 7:19", "t": "σὺ δέ μὴ νομίσῃς ἀθῷος ἔσεσθαι θεομαχεῖν ἐπιχειρήσας."}, {"sp": "N", "st": "2 Macc 7:20", "t": "Ὑπεραγόντως δέ ἡ μήτηρ ἀγαθὴ καὶ μνήμης ἀγαθῆς ἀξία, ἥτις ἀπολλυμένους υἱοὺς ἑπτὰ συνορῶσα μιᾶς ὑπὸ καιρὸν ἡμέρας εὐψύχως ἔφερεν διὰ τὰς ἐπὶ Κύριον ἐλπίδας."}, {"sp": "N", "st": "2 Macc 7:21", "t": "ἕκαστον δὲ τῶν ἀνθρώπων παρεκάλει τῇ πατρίῳ φωνῇ, γενναίῳ πεπληρωμένη φρονήματι καὶ τὸν θῆλυν λογισμὸν ἄρσενι θυμῷ διεγείρασα, λέγουσα πρὸς αὐτοὺς"}, {"sp": "N", "st": "2 Macc 7:22", "t": "Οὐκ οἶδ᾿ ὅπως εἰς τὴν ἐμὴν ἐφάνητε κοιλίαν, οὐδὲ ἐγὼ τὸ πνεὐμα καὶ τὴν ζωὴν ὑμῖν ἐχαρισάμην, καὶ τὴν ἐκάστου στοιχείωσιν οὐκ ἐγὼ διερύθμισα."}, {"sp": "N", "st": "2 Macc 7:23", "t": "τοιγαροῦν ὁ τοῦ κόσμου κτίστης, ὁ πλάσας ἀνθρώπου γένεσιν καὶ πάντων ἐξευρὼν γένεσιν, καὶ τὸ πνεῦμα καὶ τὴν ζωὴν ὑμῖν πάλιν ἀποδίδωσιν μετʼ ἐλέους, ὡς νῦν ὑπερορᾶτε ἑαυτοὺς διὰ τοὺς αὐτοῦ νόμους."}, {"sp": "N", "st": "2 Macc 7:24", "t": "Ὁ δὲ Ἀντίοχος οἰόμενος καταφρονεῖσθαι καὶ τὴν ὀνειδίζουσαν ὑφορώμενος φωνήν, ἔτι τοῦ νεωτέρου περιόντος, οὐ μόνον διὰ λόγων ἐποιεῖτο τὴν παράκλησιν, ἀλλὰ καὶ δι᾿ ὅρκων ἐπίστου ἅμα πλουτιεῖν καὶ μακαριστὸν ποιήσειν καὶ μεταθέμενον ἀπὸ τῶν πατρίων, καὶ φίλον ἕξειν καὶ χρείας ἐμπιστεύσειν."}, {"sp": "N", "st": "2 Macc 7:25", "t": "τοῦ δὲ νεανίου μηδαμῶς προσέχοντος, προσκαλεσάΠενος ὁ βασιλεὺς τὴν μητέρα παρῄνει γενέσθαι τοῦ μειρακίου σύμβουλον ἐπὶ σωτηρίᾳ."}, {"sp": "N", "st": "2 Macc 7:26", "t": "πολλὰ δὲ αὐτοῦ παραινέσαντος, ἐπεδέξατο πείσειν τὸν υἱόν."}, {"sp": "N", "st": "2 Macc 7:27", "t": "προσκύψασα δὲ αὐτῷ, χλευάσασα τὸν ὡμὸν τύραννον, οὕτως ἔφησεν τῇ πατρίῳ φωνῇ Υἱέ, ἐλέησόν με τὴν ἐν γαστρὶ περιενέγκασάν σε μῆνας ἐννέα, καὶ θηλάσασάν σε ἔτη τρία, καὶ ἐκθρέψασάν σε καὶ ἀγαγοῦσαν εἰς τὴν ἡλικίαν ταύτην καὶ τροφοφορήσασαν."}, {"sp": "N", "st": "2 Macc 7:28", "t": "ἀξιῶ σε, τέκνον, ἀναβλέψαντα εἰς τὸν οὐρανὸν καὶ τὴν γῆν καὶ τὰ ἐν αὐτοῖς πάντα ἰδόντα γνῶναι, ὅτι οὐκ ἐξ ὄντων ἐποίησεν αὐτὰ ὁ θεός, καὶ τὸ τῶν ἀνθρώπων γένος οὕτω γίνεται."}, {"sp": "N", "st": "2 Macc 7:29", "t": "μὴ φοβηθῇς τὸν δήμιον τοῦτον, ἀλλὰ τῶν ἀδελφῶν σου ἄξιος γενόμενος ἐπίδεξαι τὸν θάνατον, ἴνα ἐν τῷ ἐλέει σὺν τοῖς ἀδελφοῖς σου κομίσωμαί σε."}, {"sp": "N", "st": "2 Macc 7:30", "t": "Ἔτι δὲ ταύτης καταληγούσης ὁ νεανίας εἶπεν Τίνα μένετε; οὐχ ὑπακούω τοῦ προστάγματος τοῦ βασιλέως· τοῦ δὲ προστάγματος ἀκούω τοῦ νόμου τοῦ δοθέντος τοῖς πατράσιν ἡμῶν διὰ Μωσῇ."}, {"sp": "N", "st": "2 Macc 7:31", "t": "σὺ δὲ πάσης κακίας εὑρετὴς γενόμενος εἰς τοὺς Ἐβραίους οὐ μὴ διαφύγῃς τὰς χεῖρας τοῦ θεοῦ."}, {"sp": "N", "st": "2 Macc 7:32", "t": "ἡμεῖς γὰρ διὰ τὰς ἑαυτῶν ἁμαρτίας πάσχομεν·"}, {"sp": "N", "st": "2 Macc 7:33", "t": "εἰ δὲ χάριν ἐπιπλήξεως καὶ παιδίας ὁ ζῶν κύριος ἡμῶν βραχέως ἐπώργισται, καὶ πάλιν καταλλαγήσεται τοῖς ἑαυτοῦ δούλοις."}, {"sp": "N", "st": "2 Macc 7:34", "t": "σὺ δέ, ὦ ἀνόσιε καὶ πάντων ἀνθρώπων μιαρώτατε, μὴ μάτην μετεωρίζου φρυττόμενος αδήλοις ἐλπίσιν, ἐπὶ τοὺς οὐρανίους παῖδας ἐπαράμενος χεῖρα·"}, {"sp": "N", "st": "2 Macc 7:35", "t": "οὔπω γὰρ τὴν τοῦ παντοκράτορος ἐπόπτου θεοῦ κρίσιν ἐκπέφευγας. ³⁶οἱ μέν γὰρ νῦν ἡμέτεροι ἀδελφοὶ βραχὺν ἐπενέγκαντες πόνον ἀενάου ζωῆς ὑπὸ διαθήκην θεοῦ πεπτώκασιν· σὺ δὲ τῇ τοῦ θεοῦ κρίσει δίκαια τὰ πρόστιμα τῆς ὑπερηφανίας ἀποίσῃ."}, {"sp": "N", "st": "2 Macc 7:36", "t": "ἐγὼ δὲ καθάπερ οἱ ἀδελφοὶ καὶ σῶμα καὶ τύχην προδίδωμι περὶ τῶν πατρίων νόμων, ἐπικαλούμενοι τὸν θεὸν ἵλεων ταχὺ τῷ ἔθνει γενέσθαι, καὶ σέ μετὰ ἐτασμῶν καὶ μαστίγων ἐξομολογήσασθαι διότι μόνος αὐτὸς θεός ἐστιν·"}, {"sp": "N", "st": "2 Macc 7:38", "t": "ἐν ἐμοὶ δὲ καὶ τοῖς ἀδελφοῖς μου στῆσαι τὴν τοῦ παντοκράτορος ὀρχὴνμ τὴν ἐπὶ τὸ σύμπαν ἡμῶν γένος δικαίως ἐπημμένην."}, {"sp": "N", "st": "2 Macc 7:39", "t": "ἔκθυμος δὲ γενόμενος ὁ βασιλεὺς τούτῳ παρὰ τοὺς ἄλλους χειρίστως ἀπήντησεν, πικρῶς φέρων ἐπὶ τῷ μυκτηρισμῷ."}, {"sp": "N", "st": "2 Macc 7:40", "t": "καὶ οὗτος οὖν καθαρῶς μετήλλαξεν, παντελῶς ἐπὶ τῷ κυρίῳ πεποιθώς."}, {"sp": "N", "st": "2 Macc 7:41", "t": "ἐσχάτη δὲ τῶν υἱῶν ἡ μήτηρ ἐτελεύτησεν."}, {"sp": "N", "st": "2 Macc 7:42", "t": "Τὰ μὲν οὖν περὶ τοὺς σπλαγχνισμοὺς καὶ τὰς ὑπερβαλλούσας αἰκίας ἐπὶ τοσοῦτον δεδηλώσθω."}, {"sp": "N", "st": "2 Macc 8:1", "t": "Ἰούδας δὲ ὁ καὶ Μακκαβαῖος καὶ οἱ σὺν αὐτῷ παρεισπορευόμενοι λεληθότως εἰς τὰς κώμας προσεκαλοῦντο τοὺς συγγενεῖς, καὶ τοὺς μεμενηκότας ἐν τῷ Ἰουδαισμῷ προσλαμβανόμενοι συνήγαγον εἰς ἑξάκισχιλίους."}, {"sp": "N", "st": "2 Macc 8:2", "t": "καὶ ἐπεκαλοῦντο τὸν κύριον ἐφιδεῖν τὸν ὑπὸ πάντων καταπονούμενον λαόν, οἰκτεῖραι δὲ καὶ τὸν ναὸν τὸν ὑπὸ τῶν ἀσεβῶν ἀνθρώπων βεβηλωθέντα·"}, {"sp": "N", "st": "2 Macc 8:3", "t": "ἐλεῆσαι δὲ καὶ τὴν κΠταφθειρομένην πόλιν καὶ μέλλουσαν ἰσόπεδον γίνεσθαι, καὶ τῶν καταβοώντων πρὸς αὐτὸν αἱμάτων εἰσακοῦσαι·"}, {"sp": "N", "st": "2 Macc 8:4", "t": "καὶ μνησθῆναι δέ καὶ τῆς τῶν ἀναμαρτήτων νηπίων παρανόμου ἀπωλίας, καὶ περὶ τῶν γενομένων εἰς τὸ ὄνομα αὐτοῦ βλασφημιῶν, καὶ μισοπονηρῆσαι."}, {"sp": "N", "st": "2 Macc 8:5", "t": "γενόμενος δὲ ὁ Μακκαβαῖος ἐν συστέματι, ἀνυπόστατος ἤδη τοῖς ἔθνεσιν ἐγίνετο, τῆς ὀργῆς τοῦ κυρίου εἰς ἔλεον τραπείσης."}, {"sp": "N", "st": "2 Macc 8:6", "t": "πόλεις δὲ καὶ χώρας ἀπροσδοκήτως ἐρχόμενος ἐνεπίμπρα· καὶ τοὺς ἐπικαίρους τόπους ἀπολαμβάνων, οὐκ ὀλίγους τῶν πολεμίων τροπούμενος,"}, {"sp": "N", "st": "2 Macc 8:7", "t": "μάλιστα τὰς νύκτας πρὸς τὰς τοιαύτας ἐπιβολὰς συνεργοὺς ἐλάμβανεν· καὶ λαλιὰ τῆς εὐανδρείας αὐτοῦ διηχεῖτο πανταχῇ."}, {"sp": "N", "st": "2 Macc 8:8", "t": "Συωορῶν δὲ ὁ Φίλιππος κατὰ μικρὸν εἰς προκοπὴν ἐρχόμενον τὸν ἄνδρα, πυκνότερον δὲ ἐν ταῖς εὐημερίαις προβαίνοντα, πρὸς Πτολεμαῖον τὸν Κοίλης Συρίας καὶ Φοινίκης στρατηγὸν ἔγραψεν ἐπιβοηθεῖν τοῖς τοῦ βασιλέως πράγμασιν."}, {"sp": "N", "st": "2 Macc 8:9", "t": "ὁ δὲ ταχέως προχειρισάμενος Νικάνορα τὸν τοῦ Πατρόκλου, τῶν πρώτων φίλων, ἀπέστειλεν, ὑποτάξας πανφύλων ἔθνη οὐκ ἐλάττους τῶν δισμυρίων, τὸ πᾶν τῆς Ἰουδαίας ἐξᾶραι γένος συνέστησαν δὲ αὐτῷ καὶ Γοργίαν ἄνδρα στρατηγὸν καὶ εὖ πολεμικαῖς χρείαις ἔχοντα πεῖραν."}, {"sp": "N", "st": "2 Macc 8:10", "t": "διεστήσατο δὲ ὁ Νικάνωρ τὸν φόρον τῷ βασιλεῖ τοῖς Ῥωμαίοις, ὄντα ταλάντων δισχιλίων, ἐκ τῆς τῶν Ἰουδαίων αἰχμαλωσίας ἐκπληρώσειν."}, {"sp": "N", "st": "2 Macc 8:11", "t": "εὐθέως δὲ εἰς τὰς παραθαλασσίους πόλεις ἀπέστειλεν προκαλούμενος ἐπʼ ἀγορασμὸν Ἰουδαίων σωμάτων, ὑπισχνούμενος ἐνενήκοντα σώματα ταλάντου παραχωρήσειν· οὐ προσδεχόμενος τὴν παρὰ τοῦ παντοκράτορος μέλλουσαν παρακολουθοῦσαν αὐτῷ δίκην."}, {"sp": "N", "st": "2 Macc 8:12", "t": "τῷ δὲ Ἰούδᾳ προσέπεσεν περὶ τῆς τοῦ Νικάνορος ἐφόδου· καὶ μεταδόντος τοῖς σὺν αὐτῷ τὴν παρουσίαν τοῦ στρατοπέδου,"}, {"sp": "N", "st": "2 Macc 8:13", "t": "οἱ δειλανδροῦντες καὶ ἀπιστοῦντες τὴν τοῦ θεοῦ δίκην διεδίδρασκον ἑαυτοὺς καὶ ἐξετόπιζον·"}, {"sp": "N", "st": "2 Macc 8:14", "t": "οἱ δὲ τὰ περιλελιμμένα πάντα ἐπώλουν, ὁμοῦ δὲ τὸν κύριον ἠξίουν ῥύσασθαι τοὺς ὑπὸ τοῦ δυσσεβοῦς Νικάνορος πρὶν συντυχεῖν πεπραμένους·"}, {"sp": "N", "st": "2 Macc 8:15", "t": "καὶ εἰ μὴ δι᾿ αὐτούς, ἀλλὰ διὰ τὰς πρὸς τοὺς πατέρας αὐτῶν διαθήκας, καὶ ἕνεκα τῆς ἐπʼ αὐτοὺς ἐπικλήσεως τοῦ σεμνοῦ καὶ μεγαλοπρεποῦς ὀνόματος αὐτοῦ."}, {"sp": "N", "st": "2 Macc 8:16", "t": "Συναγαγὼν δὲ ὁ Μακκαβαῖος τοὺς περὶ αὐτὸν ὄντας ἀριθμὸν ἑξακισχιλίους παρεκάλει μὴ καταπλαγῆναι τοῖς δεσμίο μηδὲ εὐλαβεῖσθαι τὴν τῶν ἀδίκως παραγενομένων ἐπʼ αὐτοὺς ἐθνῶν πολυπληθείαν, ἀγωνίσασθαι δὲ γενναίως,"}, {"sp": "N", "st": "2 Macc 8:17", "t": "πρὸ ὀφθαλμῶν λαβόντας τὴν ἀνόμως εἰς τὸν ἅγιον τόπον συντετελεσμένην ὑπʼ αὐτῶν ὕβριν καὶ τὸν τῆς ἐμπεπαιγμένης πόλεως αἰκισμόν, ἔτι δὲ τὴν τῆς προγονικῆς πολιτίας κατάλυσιν."}, {"sp": "N", "st": "2 Macc 8:18", "t": "οἱ μέν γὰρ ὅπλοις πεποίθασιν ἄμα καὶ τόλμαις, ἔφησεν, ἡμεῖς δὲ ἐπὶ τῷ παντοκράτορι θεῷ, δυναμένῳ καὶ τοὺς ἐρχομένους ἐφʼ ἡμᾶς καὶ τὸν ὅλον κόσμον ἑνὶ νεύματι καταλαβεῖν, πεποίθαμεν."}, {"sp": "N", "st": "2 Macc 8:19", "t": "προσαναλεξάμενος δὲ αὐτοῖς καὶ τὰς ἐπὶ τῶν προγόνων γενομένας ἀντιλήμψεις, καὶ τὴν ἐπὶ Σενναχηρείμ, ἑκατὸν ὀγδοήκοντα πέντε χιλιάδες ὡς ἀπώλοντο,"}, {"sp": "N", "st": "2 Macc 8:20", "t": "καὶ τὴν ἐν τῇ Βαβυλωνίᾳ τὴν πρὸς τοὺς Γαλάτας παράταξιν γενομένην, ὡς οἱ πάντες ἐπὶ τὴν χρείαν ἦλθον ὀκτακισχίλιοι σὺν Μακεδόσιν τετρακισχιλίοις, τῶν Μακεδόνων ἀπορουμένων, οἱ ἑξακισχιλιοι τὰς δώδεκα μυριάδας ἀπώλεσαν διὰ τὴν γινομένην αὐτοῖς ἀπʼ οὐρανοῦ βοήθειαν, καὶ ὠφέλειαν πολλὴν ἔλαβον."}, {"sp": "N", "st": "2 Macc 8:21", "t": "ἐφ᾿ οἷς εὐθαρσεῖς αὐτοὺς παραστήσας καὶ ἑτοίμους ὑπέρ τῶν νόμων καὶ τῆς πατρίδος ἀποθνήσκειν τετραμερές τι ἐποίησεν τὸ στράτευμα·"}, {"sp": "N", "st": "2 Macc 8:22", "t": "τάξας ἀδελφοὺς αὐτοῦ προηγουμένους ἑκατέρας τάξεως, Σίμωνα καὶ Ἰώσηπον καὶ Ἰωνάθην, ὑποτάξας ἑκάστῳ χιλίους πρὸς τοῖς πεντακοσίοις,"}, {"sp": "N", "st": "2 Macc 8:23", "t": "ἔτι δὲ καὶ Ἐλεάζαρον· παραναγνοὺς τὴν ἱερὰν βίβλον, καὶ δοὺς σύνθημα ΘεοΥ ΒΟΗΘεαc, τῆς πρώτης σπείρης αὐτὸς προηγούμενος συνέβαλε τῷ Νικάνορι."}, {"sp": "N", "st": "2 Macc 8:24", "t": "γενομένου δὲ αὐτοῖς τοῦ παντοκράτορος συμμάχου κατέσφαξαν τῶν πολεμίων ὑπέρ τοὺς ἐννακισχιλίους, τραυματίας δὲ καὶ τοῖς μέλεσιν ἀναπήρους τὸ πλεῖον μέρος τῆς τοῦ Νικάνορος στρατείας, πάντας δὲ φεύγειν ἡνάγκασαν."}, {"sp": "N", "st": "2 Macc 8:25", "t": "τὰ δέ χρήματα τῶν παραγενομένων ἐπὶ τὸν ἀγορασμὸν αὐτῶν ἔλαβον συνδιώξαντες δὲ αὐτοὺς ἐφʼ ἱκανὸν ἀνέλυσαν ἀπὸ τῆς χώρας συνκλειόμενοι·"}, {"sp": "N", "st": "2 Macc 8:26", "t": "ἦν γὰρ ἡ πρὸ τοῦ σαββάτου δίκη, δι᾿ ἣν αἰτίαν οὐκ ἐμακροτόνησαν κατατρέχοντες αὐτούς."}, {"sp": "N", "st": "2 Macc 8:27", "t": "ὁπ λολογήσαντες δὲ αὐτοὺς καὶ τὰ σκῦλα ἐκδύσαντες τῶν πολεμίων περὶ τὸ σάββατον ἐγίνοντο, περισσῶς εὐλογοῦντες καὶ ἐξομολογούμενοι τῷ κυρίῳ τῷ διασώσαντι εἰς τὴν ἡμέραν ταύτην, ἀρχὴν ἐλέους τάξαντος αὐτοῖς."}, {"sp": "N", "st": "2 Macc 8:28", "t": "μετὰ δὲ τὸ σάββατον τοῖς ᾐκισμένοις καὶ ταῖς χήραις καὶ τοῖς ὀρφανοῖς μερίσαντες ἀπὸ τῶν σκύλων, τὰ λοιπὰ αὐτοὶ καὶ τὰ παιδία διεμερίσαντο."}, {"sp": "N", "st": "2 Macc 8:29", "t": "ταῦτα δὲ διαπραξάμενοι, καὶ κοινὴν ἱκετίαν ποιησάμενοι, τὸν ἐλεήμονα κύριον ἠξίουν εἰς τέλος καταλλαγῆναι τοῖς αὐτοῦ δούλοις."}, {"sp": "N", "st": "2 Macc 8:30", "t": "καὶ τοῖς περὶ Τιμόθεον καὶ Βακχίδην συνερείσαντες ὑπέρ τοὺς δισμυρίους αὐτῶν ἀνεῖλον, καὶ ὀχυρωμάτων ὑψηλῶν εἶ μάλα ἐνκρατεῖς ἐγένοντο, καὶ λάφυρα πλείονος ἐμερίσαντο, ἰσομοίρους αὐτοὺς καὶ τοῖς ᾐκισμένοις καὶ ὀρφανοῖς καὶ χήραις ἔτι δὲ καὶ πρεσβυτέροις ποιήσαντες."}, {"sp": "N", "st": "2 Macc 8:31", "t": "ὁπλολογήσαντες δὲ αὐτοὺς ἐπιμελῶς πάντα συνέθηκαν εἰς τοὺς ἐπικαίρους τόπους, τὰ δὲ λοιπὰ τῶν σκύλων ἤνεγκαν εἰς Ἰεροσόλυμα·"}, {"sp": "N", "st": "2 Macc 8:32", "t": "τὸν δὲ φυλάρχην τῶν περὶ Τιμοθεον ἀνεῖλον, ἀνοσιώτατον ἄνδρα καὶ πολλὰ τοὺς Ἰουδαίους ἐπιλελυπηκότα."}, {"sp": "N", "st": "2 Macc 8:33", "t": "ἐπινίκια δὲ ἄγοντες ἐν τῇ πατρίδι τοὺς ἐμπρήσαντας τοὺς ἱεροὺς πυλῶνας καὶ Καλλισθένην ὑφῆψαν εἰς ἐνοίκιον πεφευγότα· καὶ τὸν ἄξιον τῆς δυσσεβείας ἐκομίσατο μισθόν."}, {"sp": "N", "st": "2 Macc 8:34", "t": "ὁ δὲ τρισαλιτήριος Νικάνωρ, ὁ τρισχιλίους ἐμπόρους ἐπὶ τὴν πρᾶσιν τῶν Ἰουδαίων ἀγαγών,"}, {"sp": "N", "st": "2 Macc 8:35", "t": "ταπεινωθεὶς ὑπὸ τῶν καθʼ αὑτὸν νομιζομένων ἐλαχίστων εἶναι, τῇ τοῦ κυρίου βοηθείᾳ, τὴν δοξικὴν ἀποθέμενος ἐσθῆτα, διὰ τῆς μεσογείου, δραπέτου τρόπον ἔρημον ἑαυτὸν ποιήσας, ἧκεν εἰς Ἀντιόχειαν, ὑπέρ ἅπαν εὐημερηκὼς ἐπὶ τῇ τοῦ στρατοῦ διαφθορᾷ."}, {"sp": "N", "st": "2 Macc 8:36", "t": "καὶ ὁ τοῖς Ῥωμαίοις ἀναδεξάμενος φόρον ἀπὸ τῆς τῶν ἐν Ἰεροσολύμοις αἰχμαλωσίας κατορθώσασθαι, κατήγγελλεν ὑπέρμαχον ἔχειν τοὺς Ἰουδαίους, καὶ διὰ τὸν τρόπον τοῦτον ἀτρώτους εἶναι τοὺς Ἰουδαίους, διὰ τὸ ἀκολουθεῖν τοῖς ἑαυτοῦ προστεταγμένοις νόμοις."}, {"sp": "N", "st": "2 Macc 9:1", "t": "Περὶ δὲ τὸν καιρὸν ἐκεῖνον ἐτύγχανεν Ἀντίοχος ἀναλελυκὼς ἀκόσμως ἐκ τῶν περὶ τὴν Περσίδα τόπων."}, {"sp": "N", "st": "2 Macc 9:2", "t": "εἰσεληλύθει γὰρ εἰς τὴν λεγομένην Περσέπολιν, καὶ ἐπεχείρησεν ἱεροσυλεῖν καὶ τὴν πόλιν συνέχειν· διὸ δὴ τῶν πληθῶν ὁρμησάντων, ἐπὶ τὴν τῶν ὅπλων βαήθειαν ἐτράπησαν· καὶ συνέβη τροπωθέντα τὸν Ἀντίοχον ὑπὸ τῶν ἐγχωρίων ἀσχήμονα τὴν ἀναζυγὴν ποιήσασθαι."}, {"sp": "N", "st": "2 Macc 9:3", "t": "ὄντι δὲ αὐτῷ κατʼ Ἐκβάτανα προσέπεσεν τὰ κατὰ Νικάνορα καὶ τοὺς περὶ Τιμόθεον γεγονότα."}, {"sp": "N", "st": "2 Macc 9:4", "t": "ἐπαρθεὶς δὲ τῷ θυμῷ ᾤετο καὶ τῶν πεφυγαδευκότων αὐτὸν κακίαν εἰς τοὺς Ἰουδαίους ἐναπερείσασθαι· διὸ συνέταξεν τὸν ἁρματηλάτην ἀδιαλείπτως ἐλαύνοντα καταλύειν τὴν πορίαν, τῆς ἐξ οὐρανοῦ δὴ κρίσεως συνούσης αὐτῷ· οὕτως γὰρ ὑπερηφάνως εἶπεν Πολυάνδροιν Ἰουδαίων Ἰεροσόλυμα ποιήσω, παραγενόμενος ἐκεῖ."}, {"sp": "N", "st": "2 Macc 9:5", "t": "ὁ δὲ παντεπόπτης κύριος ὁ θεὸς τοῦ Ἰσραὴλ ἐπάταξεν αὐτὸν ἀνιάτῳ καὶ ἀοράτῳ πληγῇ· ἄρτι δὲ αὐτοῦ καταλήξαντος τὸν λόγον, ἔλαβεν αὐτὸν ἀνήκεστος τῶν σπλάγχνων ἀλγηδὼν καὶ πικραὶ τῶν ἔνδον βάσανοι,"}, {"sp": "N", "st": "2 Macc 9:6", "t": "πάνυ δικαίως, τὸν πολλαῖς καὶ ξενιζούσαις συμφοραῖς ἑτέρων σπλάγχνα βασανίσαντα."}, {"sp": "N", "st": "2 Macc 9:7", "t": "ὁ δʼ οὐδαμῶς τῆς ἀγερωχίας ἔληγεν, ἔτι δὲ καὶ τῆς ὑπερηφανίας ἐπεπλήρωτο, πῦρ πνέων τοῖς θυμοῖς ἐπὶ τοὺς Ἰουδαίους, καὶ κελεύων ἐποξύνειν τὴν πορίαν· συνέβη δὲ καὶ πεσεῖν αὐτὸν ἀπὸ τοῦ ἄρματος φερομένου ῥοιζῳ, καὶ δυσχερεῖ πτώματι περιπεσόντα πάντα τὰ μέλη τοῦ σώματος ἀποστρεβλοῦσθαι"}, {"sp": "N", "st": "2 Macc 9:8", "t": "ὁ δʼ ἀντιδοκῶν τοῖς τῆς θαλάσσης κύμασιν διὰ τὴν ὑπέρ ἀνθρώπων ὑπερηφανίαν, καὶ πλάστιγγι τῶν ὀρέων οἰόμενος ὕψη στήσειν, κατὰ γῆν γενόμενος ἐν φορίῳ παρεκομίζετο, φανερὰν τοῦ θεοῦ πᾶσιν τὴν δύναμιν ἐνδεικνύμενος·"}, {"sp": "N", "st": "2 Macc 9:9", "t": "ὥἐστε καὶ ἐκ τοῦ σώματος τοῦ δυσσεβοῦς σκώληκας ἀναζεῖν, καὶ ζῶντος ἐν ὀδύναις καὶ ἀλγηδόσιν τὰς σάρκας αὐτοῦ διαπίπτειν, ὑπὸ δὲ τῆς ὀσμῆς αὐτοῦ πᾶν τὸ στρατόπεδον βαρύνεσθαι τὴν σαπρίαν."}, {"sp": "N", "st": "2 Macc 9:10", "t": "καὶ τὸν μικρῷ πρότερον τῶν οὐρανίων ἄστρων ἄπτεσθαι δοκοῦντα, παρακομίζειν οὐδεὶς ἐδύνατο, διὰ τὸ τῆς ὀσμῆς ἀφόρητον βάρος."}, {"sp": "N", "st": "2 Macc 9:11", "t": "ἐνταῦθα οὗν ἤρξατο τὸ πολὺ τῆς ὑπερηφανίας λήγειν τεθραυσμένος, καὶ εἰς ἐπίγνωσιν ἔρχεσθαι θείᾳ μάστιγι, κατὰ στιγμὴν ἐπιτεινόμενος ταῖς ἀλγηδόσιν."}, {"sp": "N", "st": "2 Macc 9:12", "t": "καὶ μηδέ τῆς ὀσμῆς αὐτοῦ ἀνέχεσθαι δυνάμενος, ταῦτʼ ἔφη Δίκαιον ὑποτάσσεσθαι τῷ θεῷ, καὶ μὴ θνητὸν ὄντα ὑπερήφανα φρονεῖν."}, {"sp": "N", "st": "2 Macc 9:13", "t": "ηὔχετο δὲ ὁ μιερὸς πρὸς τὸν οὐκέτι αὐτὸν ἐλεήσοντα δεσπότην, οὕτως λέγων·"}, {"sp": "N", "st": "2 Macc 9:14", "t": "τὴν μέν ἁγίαν πόλιν, ἣν σπεύδων παρεγίνετο ἰσόπεδον ποιῆσαι καὶ πολυάνδριον οἰκοδομῆσαι, ἐλευθέραν ἀναδεῖξαι"}, {"sp": "N", "st": "2 Macc 9:15", "t": "τοὺς δὲ Ἰουδαίους, ὡς διεγνώκει μηδέ ταφῆς ἀξιῶσαι, οἰωνοβρώτους σὺν τοῖς νηπίοις ἐκτρίψαι θηρίοις, πάντας αὐτοὺς ἴσους Ἀθηναίοις ποιήσειν·"}, {"sp": "N", "st": "2 Macc 9:16", "t": "ὂν δὲ πρότερον ἐσκύλευσεν ἅγιον νεὼ καλλίστοις ἀναθήμασιν κοσμήσειν, καὶ τὰ ἱερὰ σκεύη πολυπλάσια πάντα ἀποδώσειν, τὰς δὲ ἐπιβαλλούσας πρὸς τὰς θυσίας συντάξεις ἐκ τῶν ἰδίων προσόδων χορηγήσειν·"}, {"sp": "N", "st": "2 Macc 9:17", "t": "πρὸς δὲ τούτοις καὶ Ἰουδαῖος ἔσεσθαι, καὶ πάντα τόπον οἰκητὸν ἐπελεύσεσθαι καταγγέλλοντα τὸ τοῦ θεοῦ κράτος."}, {"sp": "N", "st": "2 Macc 9:18", "t": "οὺδαμῶς δὲ ληγόντων τῶν πόνων, ἐπεληλύθει γὰρ ἐπʼ αὐτὸν δικαία ἡ τοῦ θεοῦ κρίσις, τὰ κατʼ αὐτὸν ἀπελπίσας ἔγραψεν πρὸς τοὺς Ἰουδαίους τὴν ὑπογεγραμμένην ἐπιστολήν, ἔχουσαν ἱκετηρίας τάξιν, περιέχουσαν δὲ οὕτως"}, {"sp": "N", "st": "2 Macc 9:19", "t": "Τοῖς χρηστοῖς Ἰουδαίοις τοῖς πολίταις πολλὰ χαίρειν καὶ ὑγιαίνειν καὶ εὖ πράττειν βασιλεὺς Ἀντίοχος καὶ στρατηγός·"}, {"sp": "N", "st": "2 Macc 9:20", "t": "ἔρρωσθε, καὶ τὰ τέκνα· καὶ τὰ ἴδια κατὰ γνώμην ἔσται ὑμῖν. εἰς οὐρανὸν τὴν ἐλπίδα ἔχων,"}, {"sp": "N", "st": "2 Macc 9:21", "t": "ὑμῶν τὴν τιμὴν καὶ τὴν εὔνοιαν ἐμνημόνευον φιλοστόργως ἐπαναγαγὼν ἐκ τῶν κατὰ τὴν Περσίδα τόπαων, καὶ περιπεσὼν ἀσθενείᾳ δυσχερίαν ἐχούσῃ, ἀναγκαῖον ἡγησάμην φροντίσαι τῆς κοινῆς πάντων ὑμῶν ἀσφαλείας·"}, {"sp": "N", "st": "2 Macc 9:22", "t": "οὐκ ἀπογινώσκων τὰ κατ᾿ ἐμαυτόν, ἀλλὰ ἔχων πολλὴν ἐλπίδα ἐκφεύξεσθαι τὴν ἀσθένειαν."}, {"sp": "N", "st": "2 Macc 9:23", "t": "θεωρῶν δὲ ὅτι καὶ ὁ πατήρ, καθʼ οὓς καιροὺς εἰς τοὺς ἄνω τόπους ἐστρατοπέδευσεν, ἀνέδειξεν τὸν διαδεξάμενον,"}, {"sp": "N", "st": "2 Macc 9:24", "t": "ὅπως ἐάν τι παράδοξον ἀποβαίη καὶ προσαπέλθῃ τι δυσχερές, εἰδότες οἱ κατὰ τὴν χώραν ᾦ καταλέλειπται τὰ πράγματα, μὴ ἐπιταράσσωνται·"}, {"sp": "N", "st": "2 Macc 9:25", "t": "πρὸς δὲ τούτοις κατανοῶν τοὺς παρακειμένους δυνάστας καὶ γειτνιῶντας τῆς βασιλείας τοῖς καιροῖς ἐπέχοντας καὶ προσδοκῶντας τὸ ἀποβησόμενον, ἀναδέδειχα τὸν υἱὸν Ἀντίοχον βασιλέα, ὃν πολλάκις ἀνατρέχων εἰς τὰς ἐπάνω σατραπείας τοῖς πλείστοις ὑμῶν παρεκατετιθέμην καὶ συνίστων· γέγραφα δὲ πρὸς αὐτὸν τὰ ὑπογεγραμμένα."}, {"sp": "N", "st": "2 Macc 9:26", "t": "παρακαλῶ οὖν ὑμᾶς καὶ ἀξιῶ, μεμνημένους τῶν εὐεργεσιῶν κοινῇ καὶ κατʼ ἰδίαν, ἕκαστον συντηρεῖν τὴν οὖσαν εὔνοιαν εἰς ἐμέ καὶ τὸν υἱόν·"}, {"sp": "N", "st": "2 Macc 9:27", "t": "πέπεισμαι γὰρ αὐτὸν ἐπιεικῶς καὶ φιλανθρώπως συωσταθένται τῇ ἐμῇ προαιρέσει συνπεριενεχθήσεσθαι ὑμῖν."}, {"sp": "N", "st": "2 Macc 9:28", "t": "Ὁ μέν οὗν ἀνδροφόνος καὶ βλάσφημος τὰ χείριστα παθών, ὡς ἑτέρους διέθηκεν, ἐπὶ ξένης ἐν τοῖς ὄρεσιν οἰκτίστῳ μόρῳ κατέστρεψεν τὸν βίον,"}, {"sp": "N", "st": "2 Macc 9:29", "t": "παρεκομίζετο δὲ τὸ σῶμα Φίλιππος ὁ σύντροφος αὐτοῦ· ὃς καὶ εὐλαβηθεὶς τὸν υἱὸν Ἀντιόχου πρὸς Πτολεμαῖον τὸν Φιλομήτορα εἰς Αἴγυπτον διεκομίσθη."}, {"sp": "N", "st": "2 Macc 10:1", "t": "Μακκαβαῖος δὲ καὶ οἱ σὺν αὐτῷ, τοῦ κυρίου προάγοντος αὐτούς, τὸ μέν ἱερὸν ἐκομίσαντο καὶ τὴν πόλιν·"}, {"sp": "N", "st": "2 Macc 10:2", "t": "τοὺς δὲ κατὰ τὴν ἀγορὰν βωμοὺς ὑπὸ τῶν ἀλλοφύλων δεδημιουργημένους, ἔτι δὲ τεμένη, καθεῖλαν."}, {"sp": "N", "st": "2 Macc 10:3", "t": "καὶ τὸν νεὼ καθαρίσαντες, ἕτερον θυσιαστήριον ἐποίησαν· καὶ πυρώσαντες λίθους, καὶ πῦρ ἐκ τούτων λαβόντες, ἀνήνεγκαν θυσίας μετὰ διετῆ χρόνον καὶ θυμίαμα καὶ λύχνους, καὶ τῶν ἄρτων τὴν πρόθεσιν ἐποιήσαντο."}, {"sp": "N", "st": "2 Macc 10:4", "t": "ταῦτα δὲ ποιήσαντες, ἡξίωσαν τὸν κύριον πεσόντες ἐπὶ κοιλίαν, μηκέτι παραπεσεῖν τοιούτοις κακοῖς, ἀλλʼ ἐάν ποτε καὶ ἁμάρτωσιν, ὑπʼ αὐτοῦ μετὰ ἐπιεικείας, μὴ βλασφήμοις καὶ βαρβάροις ἔθνεσιν παραδίδοσθαι"}, {"sp": "N", "st": "2 Macc 10:5", "t": "ἐν ἧ δὲ ἡμέρᾳ ὁ νεὼς ὑπὸ ἀλλοφύλων ἐβεβηλώθη, συνέβη κατὰ τὴν αὐτὴν ἡμέραν τὸν καθαρισμὸν γενέσθαι τοῦ ναοῦ, τῇ πέμπτῃ καὶ εἰκάδι τοῦ οὐτοῦ μηνός, τοῦ Χασελεύ."}, {"sp": "N", "st": "2 Macc 10:6", "t": "καὶ μετʼ εὐφροσύνης ἦγον ἡμέρας ὁκτὼ σκηνωμάτων τρόπον, μνημονεύοντες ὡς πρὸ μικροῦ χρόνου τὴν τῶν σκηνῶν ἑορτὴν ἐν τοῖς ὄρεσιν καὶ ἐν τοῖς σπηλαίοις θηρίων τρόπον ἧσαν νεμόμενοι."}, {"sp": "N", "st": "2 Macc 10:7", "t": "διὸ θύρσους καὶ κλάδους ὡραίους, ἔτι δε καὶ φοίνιας ἔχοντες, ηὐχαρίστουν τῷ εὐοδώσαντι καθαρίσαι τὸν ἑαυτοῦ τόπον."}, {"sp": "N", "st": "2 Macc 10:8", "t": "ἐδογμάτισάν τε μετὰ κοινοῦ προστάγματος καὶ ψηφίσματος παντὶ τῷ τῶν Ἰουδαίων ἔθνει κατʼ ἐνιαυτὸν ἅγειν τὰς δεκάτας ἡμέρας."}, {"sp": "N", "st": "2 Macc 10:9", "t": "Καὶτὰ μέν τῆς Ἀντιόχου τοῦ προσαγορευθέντος Ἐπιφανοῦς τελευτῆς οὕτως εἶχεν."}, {"sp": "N", "st": "2 Macc 10:10", "t": "νυνὶ δὲ τὰ κατὰ τὸν ὕπατον Ἀντίοχον, υἱὸν δὲ τοῦ ἀσεβοῦς γενόμενον, δηλώσομεν αὐτά, συντέμνοντες τὰ συνέχοντα τῶν πόλεων κακά."}, {"sp": "N", "st": "2 Macc 10:11", "t": "οὗτος γὰρ παραλαβὼν τὴν βασιλείαν, ἀνέδειξεν ἐπὶ τῶν πραγμάτων Λυσίαν τινά, Κοίλης δὲ Συρίας καὶ Φοινίκης στρατηγὸν πρώταρχον."}, {"sp": "N", "st": "2 Macc 10:12", "t": "Πτολεμαῖιος γὰρ ὁ καλούμενος Μάκρων, τὸ δίκαιον συντηρεῖν προηγούμενος πρὸς τοὺς Ἰουδαίους διὰ τὴν γεγονυῖαν πρὸς αὐτοὺς ἀδικίαν, ἐπειρᾶτο τὰ πρὸς αὐτοὺς εἰρηνικῶς διεξάγειν."}, {"sp": "N", "st": "2 Macc 10:13", "t": "ὅθεν κατηγορούμενος ὑπὸ τῶν φίλων πρὸς τὸν Εὐπάτορα, καὶ προδότης παρʼ ἕκαστα ἀκούων, διὰ τὸ τὴν Κύπρον ἐμπιστευθέντα ὑπὸ τοῦ Φιλομήτορος ἐκλιπεῖν καὶ πρὸς Ἀντίοχον τὸν Ἐπιφανῆ ἀναχωρῆσαι, μήτε εὐγενῆ τὴν ἐξουσίαν εὐγενναίσας, φαρμακεύσας ἑαυτὸν ἐξέλειπεν τὸν βίον."}, {"sp": "N", "st": "2 Macc 10:14", "t": "Γοργίας δὲ γενόμενος στρατηγὸς τῶν τόπων, ἐξενοτρόφει, καὶ παρʼ ἕκαστα πρὸς τοὺς ἰδίους ἐπολεμοτρόφει."}, {"sp": "N", "st": "2 Macc 10:15", "t": "ὁμοῦ δὲ τούτων καὶ οἱ Ἰδουμαῖοι ἐγκρατεῖς ἐπικαίρων ὁχυρωμάτων ὄντες, ἐγύμναζον τοὺς Ἰουδαίους, καὶ τοὺς φυγαδεύσαντας ἀπὸ Ἰεροσολύμων προσλαβόμενοι πολεμοτροφεῖν ἐπεχείρουν."}, {"sp": "N", "st": "2 Macc 10:16", "t": "οἱ δὲ περὶ τὸν Μακκαβαῖον, ποιησάμενοι λιτανίαν καὶ ἀξιώσαντες τὸν θεὸν σύμμαχον αὐτοῖς γενέσθαι, ἐπὶ τὰ τῶν Ἰδουμαίων ἀχυρώματα ὥρμησαν·"}, {"sp": "N", "st": "2 Macc 10:17", "t": "οἷς καὶ προσβαλόντες εὐρώστως, ἐνκρατεῖς ἐγένοντο τῶν τόπων, πάντας τε τοὺς ἐπὶ τῷ τείχει μαχομένους ἡμύναντο, κατέσφαζόν τε τοὺς ἐνπίπτοντας, ἀνεῖλον δὲ οὐχ ἧττον τῶν δισμυρίων."}, {"sp": "N", "st": "2 Macc 10:18", "t": "συνφυγόντων δὲ οὐκ ἔλαττον τῶν ἐννακισχιλίων εἰς δύο πύργους ὀχυροὺς εὗ μάλα, καὶ πάντα τὰ πρὸς πολιορκίαν ἔχοντας,"}, {"sp": "N", "st": "2 Macc 10:19", "t": "ὁ Μακκαβαῖος εἰς ἐπείγοντας τόπους, ἀπολείπων Σίμωνα καὶ Ἰώσηπον, ἔτι δὲ Ζακχαῖονμ καὶ τοὺς σὺν αὐτῷ ἱκανοὺς πρὸς τὴν τούτων πολιορκίαν, αὐτὸς ἐχωρίσθη."}, {"sp": "N", "st": "2 Macc 10:20", "t": "οἱ δὲ περὶ τὸν Σίμωνα φιλαργυρήσαντες ὑπό τινων τῶν ἐν τοῖς πύργοις ἐπείσθησαν ἀργυρίῳ· ἑπτάκις δὲ μυρίας δραχμὰς λαβόντες, εἴασάν τινας διαρρυῆναι."}, {"sp": "N", "st": "2 Macc 10:21", "t": "προσαγγέλλοντες δὲ τῷ Μακκαβαίαῳ περὶ τοῦ γεγονότος, συναγαγὼν τοὺς ἡγουμένους τοῦ λαοῦ, κατηγόρησεν ὡς ἀργυρίου πέπρακαν τοὺς ἀδελφούς, τοὺς πολεμίους κατʼ αὐτῶν ἀπολύσαντες."}, {"sp": "N", "st": "2 Macc 10:22", "t": "τούτους μέν οὖν προδότας γενομένους ἀπέκτεινεν, καὶ παραχρῆμα τοὺς δύο πύργους κατελάβετο."}, {"sp": "N", "st": "2 Macc 10:23", "t": "τοῖς δὲ ὅπλοις τὰ πάντα ἐν ταῖς χερσὶν εὐοδούμενος, ἀπώλεσεν ἐν τοῖς δυσὶν ὀχυρώμασινμ πλείους τῶν δισμυρίων."}, {"sp": "N", "st": "2 Macc 10:24", "t": "Τιμόθεος δὲ ὁ πρῶτον ἡττηθεὶς ὑπὸ τῶν Ἰουδαίων, συναγαγὼν ξένας δυνάμεις πανπληθεῖς καὶ τοὺς τῆς Ἀσίας γενομένους ἵππους συναθροίσας οὐκ ὀλίγους, παρῆν ὡς δοριάλωτον λημψόμενος τὴν Ἰουδαίαν."}, {"sp": "N", "st": "2 Macc 10:25", "t": "οἱ δὲ περὶ τὸν Μακκαβαῖον, συνεγγίζοντος αὐτοῦ, πρὸς ἱκεσίαν τοῦ θεοῦ γῇ τὰς κεφαλὰς καταπάσαντες καὶ τὰς ὀσφύας σάκκοις ζώσαντες,"}, {"sp": "N", "st": "2 Macc 10:26", "t": "ἐπὶ τὴν ἀπέναντι τοῦ θυσιαστηρίου κρηπῖδα προσπεσόντες, ἠξίουν ἵλεων αὐτοῖς γενόμενον ἐχθρεῦσαι τοῖς ἐχθροῖς αὐτῶν, καὶ ἀντικεῖσθαι τοῖς ἀντικειμένοις, καθὼς καὶ ὁ νόμος διασαφεῖ"}, {"sp": "N", "st": "2 Macc 10:27", "t": "γενόμενοι δὲ ἀπὸ τῆς δεήσεως, ἀναλαβόντες τὰ ὅπλα, προῆγον ἀπὸ τῆς πόλεως ἐπὶ πλεῖον· συνεγγίσαντες δὲ τοῖς πολεμίοις, ἐφʼ ἑαυτῶν ἦσαν."}, {"sp": "N", "st": "2 Macc 10:28", "t": "ἄρτι δὲ τῆς ἀνατολῆς διαχεομένης, προσέβαλλον ἑκάτεροι· οἱ μέν οὖν ἔγγυον ἔχοντες εὐημερίας καὶ νίκης μετὰ ἀρετῆς τὴν ἐπὶ τὸν κύριον καταφυγήν, οἱ δὲ καθηγεμόνα τῶν ἀγώνων ταττόμενοι τὸν θυμόν."}, {"sp": "N", "st": "2 Macc 10:29", "t": "γινομένης δέ καρτεράς μάχης, ἐφάνησαν τοῖς ὑπεναντίοις ἐξ οὐρανοῦ ἐφʼ ἵππων χρυσοχαλίνων πέντε ἄνδρες διαπρεπεῖς, καὶ ἀφηγούμενοι τῶν Ἰουδαίων οἱ δύο"}, {"sp": "N", "st": "2 Macc 10:30", "t": "καὶ τὸν Μακκαβαῖον μέσον λαβόντες, καὶ σκεπάζοντες ταῖς ἑαυτῶν πανοπλίαις, ἄτρωτον διεφύλασσον· εἰς δὲ τοὺς ἐναντίους τοξεύματα καὶ κεραυνοὺς ἐξερίπτουν· διὸ συγχυθέντες ἀορασία, διεκόπτοντο ταραχῆς πεπληρωμένοι."}, {"sp": "N", "st": "2 Macc 10:31", "t": "κατεσφάγησαν δὲ δισμύριοι πρὸς τοῖς πεντακοσίοις, ἱππεῖς δέ ἑξακόσιοι."}, {"sp": "N", "st": "2 Macc 10:32", "t": "Αὐτὸς δὲ ὁ Τιμόθεος συνέφυγεν εἰς Γάζαρα λεγόμενον ὁχύρωμα, εὖ μάλα φρούριον, στρατηγοῦντος ἐκεῖ Χαιρέου."}, {"sp": "N", "st": "2 Macc 10:33", "t": "οἱ δὲ περὶ τὸν Μακκαβαῖον ἀσμένως περιεκάθισαν τὸ φρούριον ἡμέρας τεσσεράκοντα."}, {"sp": "N", "st": "2 Macc 10:34", "t": "οἱ δὲ ἔνδον τῇ ἐρυμνότητι τοῦ τοπου πεποιθότες, ὑπεράγαν ἐβλασφήμουν, καὶ λόγους ἀθεμίτους προιέντες."}, {"sp": "N", "st": "2 Macc 10:35", "t": "ὑποφαινούσης δέ τῆς πέμπτης ἡμέρας καὶ εἰκοστῆς, νεανίαι τῶν περὶ τὸν Μακκαβαῖον πυρωθέντες τοῖς θυμοῖς διὰ τὰς βλασφημίας, προσβαλόντες τῷ τείχει, ἀρρενωδῶς καὶ θηριώδει θυμῷ τὸν ἐμπίπτοντα ἔκοπτον."}, {"sp": "N", "st": "2 Macc 10:36", "t": "ἕτεροι δὲ ὁμοίως προσαναβάντες ἐν τῷ περισπασμῷ πρὸς τοὺς ἔνδον, ἐνεπίμπρων τοὺς πύργους, καὶ πυρὰς ἀνάπτοντες, ζῶντας τοὺς βλασφήμους κατέκαιον· οἱ δὲ τὰς πύλας διέκοπτον, εἰσδεξάμενοι δὲ τὴν λοιπὴν τάξιν προκατελάβοντο τὴν πόλιν,"}, {"sp": "N", "st": "2 Macc 10:37", "t": "καὶ τὸν Τιμόθεον ἀποκεκρυμμένον ἔν τινι λάκκῳ κατέσφαξαν καὶ τὸν τούτου ἀδελφὸν Χαιρέαν καὶ τὸν Ἀπολλοφάνην."}, {"sp": "N", "st": "2 Macc 10:38", "t": "ταῦτα δὲ διαπραξάμενοι, μεθʼ ὕμνων καὶ ἐξομολογήσεως εὐλόγουν τῷ κυρίῳ τῷ μεγάλως εὐεργετοῦντι τὸν Ἰσραὴλ καὶ τὸ νῖκος αὐτοῖς διδόντι."}, {"sp": "N", "st": "2 Macc 11:1", "t": "Μετʼ ὀλίγον δὲ παντελῶς χρονίσκον Λυσίας ἐπίτροπος τοῦ βασιλέως καὶ συγγενὴς καὶ ἐπὶ τῶν πραγμάτων, λίαν βαρέως φέρων ἐπὶ τοῖς γεγονόσι,"}, {"sp": "N", "st": "2 Macc 11:2", "t": "συναθροίσας περὶ τὰς ὀκτὼ μυριάδας καὶ τὴν ἵππον ἅπασαν παρεγίνετο ἐπὶ τοὺς Ἰουδαίους, λογιζόμενος τὴν μὲν πόλιν Ἕλλησιν οἰκητήριον ποιήσειν,"}, {"sp": "N", "st": "2 Macc 11:3", "t": "τὸ δὲ ἱερὸν ἀργυρολόγητον, καθὼς τὰ λοιπὰ τῶν ἐθνῶν τεμένη, πρατὴν δὲ κατὰ ἔτος τὴν ἀρχιερωσύνην ποιήσειν·"}, {"sp": "N", "st": "2 Macc 11:4", "t": "οὐδαμῶς ἐπιλογιζόμενος τὸ τοῦ θεοῦ κράτος, πεφρενωμένος δὲ ταῖς μυριάσιν τῶν πεζῶν καὶ ταῖς χιλιάσιν τῶν ἱππέων καὶ τοῖς ἐλέφασιν τοῖς ὀγδοήκοντα."}, {"sp": "N", "st": "2 Macc 11:5", "t": "εἰσελθὼν δὲ εἰς τὴν Ἰουδαίαν καὶ συνεγγίσας Βεθσουρών, ὄντι μὲν ἐρυμνῷ χωρίῳ, Ἰεροσολύμων δὲ ἀπέχοντι ὡσεὶ σχοίνους πέντε, τοῦτο ἔθλιβεν."}, {"sp": "N", "st": "2 Macc 11:6", "t": "ὡς δὲ μετέλαβον οἱ περὶ τὸν Μακκαβαῖον πολιορκοῦντα αὐτὸν τὰ ὀχυρώματα, μετὰ ὀδυρμῶν καὶ δακρύων ἱκέτευον σὺν τοῖς ὄχλοις τὸν κύριον ἀγαθὸν ἄγγελον ἀποστεῖλαι πρὸς σωτηρίαν τῷ Ἰσραήλ."}, {"sp": "N", "st": "2 Macc 11:7", "t": "αὐτὸς δὲ πρῶτος ὁ Μακκαβαῖος ἀναλαβὼν τὰ ὅπλα προετρέψατο τοὺς ἄλλους, ἅμα αὐτῷ διακινδυνεύοντας, ἐπιβοηθεῖν τοῖς ἀδελφοῖς αὐτῶν· ὁμοῦ δὲ καὶ προθύμως ἐξώρμησαν."}, {"sp": "N", "st": "2 Macc 11:8", "t": "αὐτόθι δὲ πρὸς τοῖς Ἰεροσολύμοις ὄντων, ἐφάνη προηγούμενος αὐτῶν ἔφιππος ἐν λευκῇ ἐσθῆτι πανοπλίαν χρυσῆν κραδαίνων."}, {"sp": "N", "st": "2 Macc 11:9", "t": "ὁμοῦ δὲ πάντες εὐλόγησαν τὸν ἐλεήμονα θεόν, καὶ ἐπερρώσθησαν ταῖς ψυχαῖς· οὐ μόνον ἀνθρώπους θῆρας δὲ τοὺς ἀγριωτάτους καὶ σιδηρᾶ τείχη τιτρώσκειν ὄντες ἕτοιμοι,"}, {"sp": "N", "st": "2 Macc 11:10", "t": "προῆγον ἐν διασκευῇ τὸν ἀπʼ οὐρανοῦ σύμμαχον ἔχοντες, ἐλεήσαντος αὐτοὺς τοῦ κυρίου."}, {"sp": "N", "st": "2 Macc 11:11", "t": "λεόντινον δὲ ἐντινάξαντες εἰς τοὺς πολεμίους, κατέστρωσαν αὐτῶν χιλίους πρὸς τοῖς μυρίοις, ἱππεῖς δὲ ἑξακοσίους πρὸς χιλίοις· τοὺς δὲ πάντας ἠνάγκασαν φεύγειν."}, {"sp": "N", "st": "2 Macc 11:12", "t": "οἱ πλείονες δὲ αὐτῶν τραυματίαι γυμνοὶ διεσώθησαν· καὶ αὐτὸς δὲ ὁ Λυσίας αἰσχρῶς φεύγων διεσώθη."}, {"sp": "N", "st": "2 Macc 11:13", "t": "οὐκ ἄνους δὲ ὑπάρχων, πρὸς ἑαυτὸν ἀντιβάλλων τὸ γεγονὸς περὶ αὐτὸν ἐλάττωμα καὶ συννοήσας ἀνικήτους εἶναι τοὺς Ἐβραίους, τοῦ δυναμένου θεοῦ συμμαχοῦντος αὐτοῖς, προσαποστείλας"}, {"sp": "N", "st": "2 Macc 11:14", "t": "ἔπεισεν συλλύεσθαι ἐπὶ πᾶσι τοῖς δικαίοις, καὶ διότι καὶ τὸν βασιλέα πείσει, φίλον αὐτοῖς ἀναγκάζων γενέσθαι."}, {"sp": "N", "st": "2 Macc 11:15", "t": "ἐπένευσεν δὲ ὁ Μακκαβαῖος ἐπὶ πᾶσιν οἷς ὁ Λυσίας παρεκάλει, τοῦ συμφέροντος φροντίζων· ὅσα γὰρ ὁ Μακκαβαῖος ἐπέδωκεν τῷ Λυσίᾳ διὰ γραπτῶν περὶ τῶν Ἰουδαίων, συνεχώρησεν ὁ γραμματεύς."}, {"sp": "N", "st": "2 Macc 11:16", "t": "ἦσαν γὰρ γεγραμμέναι τοῖς Ἰουδαίοις ἐπιστολαὶ παρὰ μὲν Λυσίου, περιέχουσαι τὸν τρόπον τοῦτον Λυσίας τῷ πλήθει τῶν Ἰουδαίων χαίρειν."}, {"sp": "N", "st": "2 Macc 11:17", "t": "Ἰωάννης καὶ Ἀβεσσαλὼμ οἱ πεμφθέντες παρʼ ὑμῶν, ἐπιδόντες τὸν ὑπογεγραμμένον χρηματισμόν, ἠξίουν περὶ τῶν δι᾿ αὐτοῦ σημαινομένων."}, {"sp": "N", "st": "2 Macc 11:18", "t": "ὅσα μὲν οὖν ἔδει καὶ τῷ βασιλεῖ προσενεχθῆναι διεσάφησα, ἃ δὲ ἦν ἐνδεχόμενα συνεχώρησεν."}, {"sp": "N", "st": "2 Macc 11:19", "t": "ἐὰν μὲν οὖν συντηρήσητε τὴν εἰς τὰ πράγματα εὔνοιαν, καὶ εἰς τὸ λοιπὸν πειράσομαι παραίτιος ἀγαθῶν γενέσθαι."}, {"sp": "N", "st": "2 Macc 11:20", "t": "ὑπὲρ δὲ τούτων κατὰ μέρος ἐντέταλμαι τούτοις τε καὶ τοῖς παρʼ ἐμοῦ διαλεχθῆναι ὑμῖν."}, {"sp": "N", "st": "2 Macc 11:21", "t": "ἔρρωσθε. ἔτους ἑκατοστοῦ τεσσερακοστοῦ ὀγδόου, Διὸς Κορινθίου τετράδι καὶ εἰκάδι."}, {"sp": "N", "st": "2 Macc 11:22", "t": "Ἡ δὲ τοῦ βασιλέως ἐπιστολὴ περιεῖχεν οὕτως Βασιλεὺς Ἀντίοχος τῷ ἀδελφῷ Λυσίᾳ χαίρειν."}, {"sp": "N", "st": "2 Macc 11:23", "t": "τοῦ πατρὸς ἡμῶν εἰς θεοὺς μεταστάντος, βουλομένου τοὺς ἐκ τῆς βασιλείας ἀταράχους ὄντας γενέσθαι πρὸς τὴν τῶν Ἰουδαίων ἐπιμελίαν,"}, {"sp": "N", "st": "2 Macc 11:24", "t": "ἀκηκοότες τοὺς Ἰουδαίους μὴ συνευδοκοῦντας τῇ τοῦ πατρὸς εἰς τὰ Ἑλληνικὰ μεταθέσει, ἀλλὰ τὴν ἑαυτῶν ἀγωγὴν αἱρετίζοντας ἀξιοῦν συνχωρηθῆναι αὐτοῖς τὰ νόμιμα·"}, {"sp": "N", "st": "2 Macc 11:25", "t": "αἱρούμενοι οὖν καὶ τοῦτο τὸ ἔθνος ἐκτὸς ταραχῆς εἶναι, κρίνομεν τό τε ἱερὸν ἀποκατασταθῆναι αὐτοῖς, καὶ πολιτεύεσθαι κατὰ τὰ ἐπὶ τῶν προγόνων αὐτῶν ἔθη."}, {"sp": "N", "st": "2 Macc 11:26", "t": "εὖ οὖν ποιήσεις διαπεμψάμενός πρὸς αὐτοὺς καὶ δοὺς δεξιάς, ὅπως εἰδότες τὴν ἡμετέραν προαίρεσιν εὔθυμοί τε ᾦσιν, καὶ ἡδέως διαγίνωνται πρὸς τῇ τῶν ἰδίων ἀντιλήμψει."}, {"sp": "N", "st": "2 Macc 11:27", "t": "Πρὸς δὲ τὸ ἔθνος ἡ τοῦ βασιλέως ἐπιστολὴ τοιάδε ἦν Βασιλεὺς Ἀντίοχος τῇ γερουσίᾳ τῶν Ἰουδαίων καὶ τοῖς ἄλλοις Ἰουδαίοις χαίρειν."}, {"sp": "N", "st": "2 Macc 11:28", "t": "ἔρρωσθε, εἴη ἂν ὡς βουλόμεθα· καὶ αὐτοὶ δὲ ὑγιαίνομεν."}, {"sp": "N", "st": "2 Macc 11:29", "t": "ἐνεφάνισεν ἡμῖν Μενέλαος βουλόμενος κατελθόντας ὑμᾶς γίνεσθαι πρὸς τοῖς ἰδίοις. 30τοῖς οὖν καταπορευομένοις μέχρι τριακάδος Ξανθικοῦ ὑπάρξει δεξιὰ μετὰ τῆς ἀδείας,"}, {"sp": "N", "st": "2 Macc 11:31", "t": "χρῆσθαι τοὺς Ἰουδαίους τοῖς ἑαυτῶν δαπανήμασιν καὶ νόμοις καθὰ καὶ τὸ πρότερον· καὶ οὐδεὶς αὐτῶν κατʼ οὐδένα τρόπον παρενοχληθήσεται περὶ τῶν ἠγνοημένων."}, {"sp": "N", "st": "2 Macc 11:32", "t": "πέπομφα δὲ καὶ τὸν Μενέλαον παρακαλέσοντα ὑμᾶς."}, {"sp": "N", "st": "2 Macc 11:33", "t": "ἔρρωσθε. ἔτους ἑκατοστοῦ τεσσερακοστοῦ ὀγδόου, Ξανθικοῦ πεντεκαιδεκάτῃ."}, {"sp": "N", "st": "2 Macc 11:34", "t": "Ἔπεμψαν δὲ καὶ οἱ Ῥωμαῖοι πρὸς αὐτοὺς ἐπιστολὴν ἔχουσαν οὕτως Κόιντος Μέμμιος, Τίτος Μάνιος, πρεσβῦται Ῥωμαίων, τῷ δήμῳ τῶν Ἰουδαίων χαίρειν."}, {"sp": "N", "st": "2 Macc 11:35", "t": "ὑπὲρ ὧν Λυσίας ὁ συγγενὴς τοῦ βασιλέως συνεχώρησεν ὑμῖν, καὶ ἡμεῖς συνευδοκοῦμεν."}, {"sp": "N", "st": "2 Macc 11:36", "t": "ἃ δὲ ἔκρινεν προσανενηνέχθαι τῷ βασιλεῖ, πέμψατέ τινα παραχρῆμα ἐπισκεψάμενοι περὶ τούτων, ἵνʼ ἔχωμεν ὡς καθήκει ἡμῖν· ἡμεῖς γὰρ προσάγομεν πρὸς Ἀντιοχίαν."}, {"sp": "N", "st": "2 Macc 11:37", "t": "διὸ σπεύσατε, καὶ πέμψατέ τινας, ὅπως καὶ ἡμεῖς ἐπιγνῶμεν ὁποίας ἐστὲ γνώμης."}, {"sp": "N", "st": "2 Macc 11:38", "t": "ὑγιαίνετε. ἔτους ἑκατοστοῦ τεσσερακοστοῦ ὀγδόου, Ξανθικοῦ πεντεκαιδεκάτῃ."}, {"sp": "N", "st": "2 Macc 12:1", "t": "Γενομένων δὲ τῶν συνθηκῶν τούτων, ὁ μέν Λυσίας ἀπῄει πρὸς τὸν βασιλέα, οἱ δὲ Ἰουδαῖοι περὶ τὴν γεωργίαν ἐγίνοντο."}, {"sp": "N", "st": "2 Macc 12:2", "t": "τῶν δὲ κατὰ τόπον στρατηγῶν Τιμόθεος καὶ Ἀπολλώνιος ὁ τοῦ Γενναίου, ἔτι δὲ Ἱερώνυμος καὶ Δημοφών, πρὸς δὲ τούτοις Νικάνωρ ὁ Κυπριάρχης, οὐκ εἴων αὐτοὺς εὐσταθεῖν καὶ τὰς ἡσυχίας ἄγειν."}, {"sp": "N", "st": "2 Macc 12:3", "t": "Ἰοπποῖται δὲ τηλικοῦτο συνετελέσαντο δυσσέβημα, παρακαλέσαντες τοὺς ἐν ἑαυτοῖς οἰκοῦντας Ἰουδαίους ἐμβῆναι εἰς τὰ παρακατασταθέντα ὑπʼ αὐτῶν σκάφη σὺν γυναιξὶν καὶ τέκνοις, ὡς μηδεμιᾶς ἐνεστώσης πρὸς αὐτοὺς δυσμενείας·"}, {"sp": "N", "st": "2 Macc 12:4", "t": "μετὰ δὲ τὸ κοινὸν τῆς πόλεως ψήφισμα καὶ τούτων ἐπιδεξαμένων, ὡς ἂν εἰρηνεύειν θελόντων καὶ μηδὲν ὕποπτον ἐχόντων, ἀχθέντας αὐτους ἐβύθισαν ὄντας οὐκ ἔλαττον τῶν διακοσίων."}, {"sp": "N", "st": "2 Macc 12:5", "t": "μεταλαβὼν δὲ ὁ Ἰούδας τὴν γεγονυῖαν εἰς τοὺς ὁμοεθνεῖς ὠμότητα, παραγγείλας τοῖς περὶ αὐτὸν ἀνδράσιν"}, {"sp": "N", "st": "2 Macc 12:6", "t": "καὶ ἐπικαλεσάμενος τὸν δίκαιον κριτὴν θεόν, παραγενόμενος ἐπὶ τοὺς μιαιφόνους τῶν ἀδελφῶν, τὸν μὲν λιμένα νύκτωρ ἐνέπρησεν καὶ τὰ σκάφη κατέφλεξεν, τοὺς δὲ ἐκεῖ συμφυγόντας ἐξεκέντησεν."}, {"sp": "N", "st": "2 Macc 12:7", "t": "τοῦ δὲ χωρίου συνκλεισθέντος, ἀνέλυσεν, πάλιν ἥξων καὶ τὸ σύμπαν τῶν Ἰοππιτῶν ἐκριζῶσαι πολίτευμα."}, {"sp": "N", "st": "2 Macc 12:8", "t": "μεταλαβὼν δὲ καὶ τοὺς ἐν Ἰαμνίᾳ τὸν αὐτὸν ἐπιτελεῖν βουλομένους τρόπον τοῖς κατοικοῦσιν Ἰουδαίοις,"}, {"sp": "N", "st": "2 Macc 12:9", "t": "καὶ τοῖς Ἰαμνίταις νυκτὸς ἐπιβαλὼν ὑφῆψεν τὸν λιμένα σὺν τῷ στόλῳ, ὥστε ἐπιφαίνεσθαι τὰς αὐγὰς τοῦ φέγγους εἰς τὰ Ἰεροσόλυμα, σταδίων ὄντων διακοσίων τεσσεράκοντα."}, {"sp": "N", "st": "2 Macc 12:10", "t": "Ἐκεῖθεν δὲ ἀποσπάσαντες σταδίους ἐννέα, ποιουμένων τὴν πορίαν ἐπὶ τὸν Τιμόθεον, ἐπέβαλλον Ἄραβες αὐτῷ οὐκ ἐλάττους τῶν πεντακισχιλίων, ἱππεῖς δὲ πεντακόσιοι."}, {"sp": "N", "st": "2 Macc 12:11", "t": "γενομένης δὲ καρτερᾶς μάχης καὶ τῶν περὶ τὸν Ἰούδαν διὰ τὴν παρὰ τοῦ θεοῦ βοήθειαν εὐημερησάντων, ἐλαττονωθέντες οἱ νομάδες ἠξίουν δοῦναι τὸν Ἰούδαν δεξιὰν αὐτοῖς, ὑπισχνούμενοι καὶ βοσκήματα δώσειν καὶ ἐν τοῖς λοιποῖς ὠφελήσειν αὐτούς."}, {"sp": "N", "st": "2 Macc 12:12", "t": "Ἰούδας δὲ ὑπολαβὼν ὡς ἀληθῶς ἐν πολλοῖς αὐτοὺς χρησίμους, ὑπεχώρησεν εἰρήνην ἄξειν πρὸς αὐτούς· καὶ λαβόντες δεξιὰς εἰς τὰς σκηνὰς ἐχωρίσθησαν."}, {"sp": "N", "st": "2 Macc 12:13", "t": "Ἐπέβαλεν δὲ καὶ ἐπί τινα πόλιν γεφυροῦν, ὀχυρὰν καὶ τείχεσιν περιπεφραγμένην καὶ πανμιγέσιν ἔθνεσιν κατοικουμένην, ὄνομα δὲ Κασπείν."}, {"sp": "N", "st": "2 Macc 12:14", "t": "οἱ δὲ ἔνδον πεποιθότες τῇ τῶν τειχέων ἐρυμνότητι τῇ τε τῶν βρωμάτων παραθέσει, ἀναγωγότερον ἐχρῶντο τοῖς περὶ τὸν Ἰούδαν, λοιδοροῦντες, καὶ προσέτι βλασφημοῦντες καὶ λαλοῦντες ἃ μὴ θέμις."}, {"sp": "N", "st": "2 Macc 12:15", "t": "οἱ δὲ περὶ τὸν Ἰούδαν ἐπικαλεσάμενοι τὸν μέγαν τοῦ κόσμου δυνάστην, τὸν ἄτερ κριῶν καὶ μηχανῶν ὀργανικῶν κατακρημνίσαντα τὴν Ἰεριχὼ κατὰ τοὺς Ἰησοῦ χρόνους, ἐνέσεισαν θηριωδῶς τῷ τείχει·"}, {"sp": "N", "st": "2 Macc 12:16", "t": "καταλαβόμενοί τε τὴν πόλιν τῇ τοῦ θεοῦ θελήσει ἀμυθήτους ἐποιήσαντο σφαγάς, ὥστε τὴν παρακειμένην λίμνην τὸ πλάτος ἔχουσαν σταδίους δύο καταρρεῖν τὸ αἷμα πεπληρωμένην φαίνεσθαι."}, {"sp": "N", "st": "2 Macc 12:17", "t": "Ἐκεῖθεν δὲ ἀποσπάσαντες σταδίους ἑπτακοσίους πεντήκοντα διήνυσαν εἰς τὸν Χάρακα καὶ πρὸς τοὺς λεγομένους Τουβεινοὺς Ἰουδαίους."}, {"sp": "N", "st": "2 Macc 12:18", "t": "καὶ Τιμόθεον μὲν ἐπὶ τῶν τόπων οὐ κατέλαβον, ἄπρακτον τότε ἐκ τῶν τόπων ἐκλελυκότα, καταλελοιπότα δὲ φρουρὰν ἔν τινι τόπῳ καὶ μάλα ὀχυράν."}, {"sp": "N", "st": "2 Macc 12:19", "t": "Δωσίθεος δὲ καὶ Σωσίπατρος, τῶν περὶ τὸν Μακκαβαῖον ἡγεμόνων, ἐξοδεύσαντες τοὺς ὑπὸ Τιμοθέου ἀπώλεσαν καταλειφθέντας ἐν τῷ ὀχυρώματι, πλείους τῶν μυρίων ἀνδρῶν·"}, {"sp": "N", "st": "2 Macc 12:20", "t": "ὁ δὲ Μακκαβαῖος, διατάξας τὴν περὶ αὐτὸν στρατιὰν σπειρηδόν, κατέστησεν αὐτοὺς ἐπὶ τῶν σπειρῶν· καὶ ἐπὶ τὸν Τιμόθεον ὥρμησαν ἔχοντα περὶ αὐτὸν μυριάδας δώδεκα πεζῶν, ἱππεῖς δὲ δισχιλίους καὶ πρὸς τοῖς ἑπτακισχιλίοις."}, {"sp": "N", "st": "2 Macc 12:21", "t": "τὴν δὲ ἔφοδον μεταλαβὼν Ἰούδου, προεξαπέστειλεν ὁ Τιμόθεος τὰς γυναῖκας καὶ τὴν ἄλλην ἀποσκευὴν εἰς τὸ λεγόμενον Κάρνιον· ἦν γὰρ δυσπολιόρκητον καὶ δυσπρόσιτον τὸ χωρίον διὰ τὴν πάντων τῶν τόπων στενότητα."}, {"sp": "N", "st": "2 Macc 12:22", "t": "ἐπιφανείσης δὲ τῆς Ἰούδου σπείρης πρώτου, καὶ γενομένου δέους ἐπὶ τοὺς πολεμίους, φόβου τε ἐκ τῆς τοῦ τὰ πάντα ἐφορῶντος ἐπιφανίας γενομένης ἐπʼ αὐτούς, εἰς φυγὴν ὥρμησαν ἄλλος ἀλλαχῇ φερόμενος, ὥστε πολλάκις ὑπὸ τῶν ἰδίων βλάπτεσθαι καὶ ταῖς τῶν ξιφῶν ἀκμαῖς ἀναπείρεσθαι."}, {"sp": "N", "st": "2 Macc 12:23", "t": "ἐποιεῖτο δὲ τὸν διωγμὸν εὐτονώτερον Ἰούδας, συνκεντῶν τοὺς ἀλιτηρίους, διέφθειρεν δὲ εἰς μυριάδας τρεῖς ἀνδρῶν."}, {"sp": "N", "st": "2 Macc 12:24", "t": "αὐτὸς δὲ ὁ Τιμόθεος ἐμπεσὼν τοῖς περὶ τὸν Δωσίθεον καὶ Σωσίπατρον ἠξίου μετὰ πολλῆς γοητίας ἐξαφεῖναι ὡς σῷον αὐτόν, διὰ τὸ πλειόνων μὲν γονεῖς, ὧν δὲ ἀδελφοὺς ἔχειν, καὶ τούτους ἀλογηθῆναι συμβήσεται·"}, {"sp": "N", "st": "2 Macc 12:25", "t": "πιστώσαντος δὲ αὐτοῦ διὰ πλειόνων τὸν ὁρισμὸν ἀποκαταστῆσαι τούτους ἀπημάντους, ἀπέλυσαν αὐτὸν ἕνεκα τῆς τῶν ἀδελφῶν σωτηρίας."}, {"sp": "N", "st": "2 Macc 12:26", "t": "Ἐξελθὼν δὲ ἐπὶ τὸ Κάρνιον καὶ τὸ Ἀτεργάτιον, κατέσφαξεν μυριάδας σωμάτων δύο πεντακισχιλίους."}, {"sp": "N", "st": "2 Macc 12:27", "t": "μετὰ δὲ τὴν τούτων τροπὴν καὶ ἀπώλειαν ἐπεστράτευσεν καὶ ἐπὶ Ἐφρών, πόλιν ὀχυράν, ἐν ᾗ πάμφυλα ἐν αὐτῇ πλήθη· νεανίαι δὲ ῥωμαλέοι πρὸ τῶν τειχέων καθεστῶτες εὐρώστως ἀπεμάχοντο· ἔνθα ὀργάνων καὶ βελῶν πολλαὶ παραθέσεις ὑπῆρχον."}, {"sp": "N", "st": "2 Macc 12:28", "t": "ἐπικαλεσάμενοι δὲ τὸν δυνάστην τὸν μετὰ κράτους συντρίβοντα τὰς τῶν πολεμίων ὁλκάς, ἔλαβον τὴν πόλιν ὑποχείριον, κατέστρωσαν δὲ τῶν ἔνδον εἰς μυριάδας δύο πεντακισχιλίους."}, {"sp": "N", "st": "2 Macc 12:29", "t": "ἀναζεύξαντές τε ἐκεῖθεν, ὥρμησαν ἐπὶ Σκυθῶν πόλιν, ἀπέχουσαν ἀπὸ Ἰεροσολύμων σταδίους ἑξακοσίους."}, {"sp": "N", "st": "2 Macc 12:30", "t": "ἀπομαρτυρησάντων δὲ τῶν ἐκεῖ καθεστώτων Ἰουδαίων ἣν οἱ Σκυθοπολεῖται ἔσχον πρὸς αὐτοὺς εὔνοιαν, καὶ ἐν τοῖς τῆς ἀτυχίας καιροῖς ἥμερον ἀπάντησιν,"}, {"sp": "N", "st": "2 Macc 12:31", "t": "εὐχαριστήσαντες καὶ προσπαρακαλέσαντες καὶ εἰς τὰ λοιπὰ πρὸς τὸ γένος εὐμενεῖς εἶναι, παρεγενήθησαν εἰς Ἰεροσόλυμα, τῆς τῶν ἑβδομάδων ἑορτῆς οὔσης ὑπογύου."}, {"sp": "N", "st": "2 Macc 12:32", "t": "Μετὰ δὲ τὴν λεγομένην πεντηκοστὴν ὥρμησαν ἐπὶ Γοργίαν τὸν τῆς Ἰδουμαίας στρατηγόν."}, {"sp": "N", "st": "2 Macc 12:33", "t": "ἐξῆλθεν δὲ μετὰ πεζῶν τρισχιλίων, ἱππέων δὲ τετρακοσίων·"}, {"sp": "N", "st": "2 Macc 12:34", "t": "παραταξαμένους δὲ συνέβη πεσεῖν ὀλίγους τῶν Ἰουδαίων."}, {"sp": "N", "st": "2 Macc 12:35", "t": "Δωσίθεος δέ τις τῶν τοῦ Βακήνορος, ἔφιππος ἀνὴρ καὶ καρτερός, εἴχετο τοῦ Γοργίου, καὶ λαβόμενος τῆς χλαμύδος, ἦγεν αὐτὸν εὐρώστως, καὶ βουλομένου τὸν κατάρατον λαβεῖν ζωγρείαν, τῶν ἱππέων τινὸς Θρᾳκῶν ἐπενεχθέντος αὐτῷ καὶ τὸν ὦμον καθελόντος, διέφυγεν Γοργίας εἰς Μαρισά."}, {"sp": "N", "st": "2 Macc 12:36", "t": "τῶν δὲ περὶ τὸν Ἔσδριν ἐπὶ πλεῖον μαχομένων καὶ κατακόπων ὄντων, ἐπικαλεσάμενος Ἰούδας τὸν κύριον σύμμαχον φανῆναι καὶ προοδηγὸν φανῆναι τοῦ πολέμου,"}, {"sp": "N", "st": "2 Macc 12:37", "t": "καταρξάμενος τῇ πατρίῳ φωνῇ τὴν μεθʼ ὕμνων κραυγήν, ἐνσείσας ἀπροσδοκήτως τοῖς περὶ τὸν Γοργίαν τροπὴν ἐποιήσατο αὐτῶν."}, {"sp": "N", "st": "2 Macc 12:38", "t": "Ἰούδας δὲ ἀναλαβὼν τὸ στράτευμα ἧκεν εἰς Ὀδολλὰμ πόλιν· τῆς δὲ ἑβδομάδος ἐπιβαλλούσης, κατὰ τὸν ἐθισμὸν ἁγνισθέντες αὐτόθι τὸ σάββατον διῆγεν."}, {"sp": "N", "st": "2 Macc 12:39", "t": "τῇ δὲ ἐχομένῃ ἦλθον οἱ περὶ τὸν Ἰούδαν, καθʼ ὃν χρόνον τὸ τῆς χρείας ἐγεγόνει, τὰ σώματα τῶν προπεπτωκότων ἀνακομίσασθαι καὶ μετὰ τῶν συγγενῶν ἀποκαταστῆσαι εἰς τοὺς πατρῴους τάφους."}, {"sp": "N", "st": "2 Macc 12:40", "t": "εὗρον δὲ ἑκάστου τῶν τεθνηκότων ὑπὸ τοὺς χιτῶνας ἱερώματα τῶν ἀπὸ Ἰαμνίας εἰδώλων, ἀφʼ ὧν ὁ νόμος ἀπήργει τοὺς Ἰουδαίους· τοῖς δὲ πᾶσι σαφὲς ἐγένετο διὰ τήνδε τὴν αἰτίαν τούσδε πεπτωκέναι."}, {"sp": "N", "st": "2 Macc 12:41", "t": "πάντες οὖν εὐλογησαντες τὰ τοῦ δικαιοκρίτου κυρίου τοῦ τὰ κεκρυμμένα φανερὰ ποιοῦντος,"}, {"sp": "N", "st": "2 Macc 12:42", "t": "εἰς ἱκεσίαν ἐτράπησαν, ἀξιώσαντες τὸ γεγονὸς ἁμάρτημα τελείως ἐξαλειφθῆναι· ὁ δὲ γενναῖος Ἰούδας παρεκάλεσε τὸ πλῆθος συντηρεῖν αὑτοὺς ἀναμαρτήτους εἶναι, ὑπ᾿ ὄψιν ἑωρακότας τὰ γεγονότα διὰ τὴν τῶν προπεπτωκότων ἁμαρτίαν."}, {"sp": "N", "st": "2 Macc 12:43", "t": "ποιησάμενός τε κατʼ ἀνδρολογεῖον εἰς ἀργυρίου δραχμὰς δισχιλίας ἀπέστειλεν εἰς Ἰεροσόλυμα προσαγαγεῖν περὶ ἁμαρτίας θυσίαν, πάνυ καλῶς καὶ ἀστείως πράττων, ὑπὲρ ἀναστάσεως ἀναλογιζόμενος."}, {"sp": "N", "st": "2 Macc 12:44", "t": "εἰ μὴ γὰρ τοὺς προπεπτωκότας ἀναστῆναι προσεδόκα, περισσὸν καὶ ληρῶδες ὑπὲρ νεκρῶν εὔχεσθαι·"}, {"sp": "N", "st": "2 Macc 12:45", "t": "εἴτε ἐμβλέπων τοῖς μετʼ εὐσεβίας κοιμωμένοις κάλλιστον ἀποκείμενον εὐχαριστήριον, ὁσία καὶ εὐσεβὴς ἡ ἐπίνοια. ὅθεν περὶ τῶν τεθνηκότων τὸν ἐξιλασμὸν ἐποιήσατο, τῆς ἁμαρτίας ἀπολυθῆναι."}, {"sp": "N", "st": "2 Macc 13:1", "t": "Τῷ δὲ ἐνάτῳ καὶ τεσσερακοστῷ καὶ ἑκατοστῷ ἔτει προσέπεσεν τοῖς περὶ τὸν Ἰούδαν Ἀντίοχον τὸν Εὐπάτορα παραγενέσθαι σὺν πλήθεσιν ἐπὶ τὴν Ἰουδαίαν,"}, {"sp": "N", "st": "2 Macc 13:2", "t": "καὶ σὺν αὐτῷ Λυσίαν τὸν ἐπίτροπον καὶ ἐπὶ τῶν πραγμάτων, ἕκαστον ἔχοντα δύναμιν Ἑλληνικὴν πεζῶν μυριάδας ἕνδεκα καὶ ἱππέων πεντακισχιλίους τριακοσίους καὶ ἐλεφάντας εἴκοσι δύο, ἅρματα δὲ δρεπανηφόρα τριακόσια."}, {"sp": "N", "st": "2 Macc 13:3", "t": "συνέμιξεν δὲ αὐτοῖς καὶ Μενέλαος, καὶ παρεκάλει μετὰ πολλῆς εἰρωνίας τὸν Ἀντίοχον, οὐκ ἐπὶ σωτηρίας τῆς πατρίδος, οἰόμενος δὲ ἐπὶ τῆς ἀρχῆς κατασταθήσεσθαι."}, {"sp": "N", "st": "2 Macc 13:4", "t": "ὁ δὲ βασιλεὺς τῶν βασιλέων ἐξήγειρεν τὸν θυμὸν τοῦ Ἀντιόχου ἐπὶ τὸν ἀλιτήριον, καὶ Λυσίου ὑποδείξαντος τοῦτον αἴτιον τῶν κακῶν εἶναι καὶ πάντων προσέταξεν, ὡς ἔθος ἐστὶν ἐν τῷ τόπῳ, προσαπολέσαι, ἀγαγόντας εἰς Βέροιαν."}, {"sp": "N", "st": "2 Macc 13:5", "t": "ἔστιν δὲ ἐν τῷ τόπῳ πύργος πεντήκοντα πήχεων πλήρης σποδοῦ, ὄργανον δὲ εἶχεν περιφερὲς πάντοθεν ἀπόκρημνον εἰς τὴν σποδόν."}, {"sp": "N", "st": "2 Macc 13:6", "t": "ἐνταῦθα τὸν ἱεροσυλίας ἔνοχον, ἢ καί τινων ἄλλων κακῶν ὑπεροχὴν πεποιημένον, ἅπαντες προσωθοῦσιν εἰς ὄλεθρον."}, {"sp": "N", "st": "2 Macc 13:7", "t": "τοιούτῳ μόρῳ τὸν παράνομον συνέβη θανεῖν, μηδὲ τῆς γῆς τυγχάνοντα Μενέλαον·"}, {"sp": "N", "st": "2 Macc 13:8", "t": "πάνυ δικαίως· ἐπεὶ γὰρ συνετελέσατο πολλὰ περὶ τὸν βωμὸν ἁμαρτήματα, οὗ τὸ πῦρ ἁγνὸν ἦν καὶ ἡ σποδός, ἐν σποδῷ τὸν θάνατον ἐκομίσατο."}, {"sp": "N", "st": "2 Macc 13:9", "t": "Τοῖς δὲ φρονήμασιν ὁ βασιλεὺς βεβαρημένος ἤρχετο, τὰ χείριστα τῶν ἐπὶ τοῦ πατρὸς αὐτοῦ γεγονότων ἐνδειξόμενος τοῖς Ἰουδαίοις."}, {"sp": "N", "st": "2 Macc 13:10", "t": "μεταλαβὼν δὲ Ἰούδας ταῦτα, παρήγγειλεν τῷ πλήθει δι᾿ ἡμέρας καὶ νυκτὸς ἐπικαλέσασθαι τὸν κύριον, εἴ ποτε καὶ ἄλλοτε, καὶ νῦν ἐπιβοηθεῖυ"}, {"sp": "N", "st": "2 Macc 13:11", "t": "τοῖς τοῦ νόμου καὶ πατρίδος καὶ ἱεροῦ ἁγίου στερεῖσθαι μέλλουσιν, καὶ τὸν ἄρτι βραχέως ἀνεψυχότα λαὸν μὴ ἐᾶσαι τοῖς δυσφήμοις ἔθνεσιν ὑποχειρίους γενέσθαι."}, {"sp": "N", "st": "2 Macc 13:12", "t": "πάντων δὲ τὸ αὐτὸ ποιησάντων ὁμοῦ καὶ καταξιωσάντων τὸν ἐλεήμονα κύριον μετὰ κλαυθμοῦ καὶ νηστειῶν καὶ προπτώσεως ἐπὶ ἡμέρας τρεῖς ἀδιαλείπτως, παρακαλέσας αὐτοὺς ὁ Ἰούδας ἐκέλευσεν παραγίνεσθαι."}, {"sp": "N", "st": "2 Macc 13:13", "t": "καθʼ ἑαυτὸν δὲ σὺν τοῖς πρεσβυτέροις γενόμενος ἐβουλεύσατο πρὶν εἰσβαλεῖν τὸ στράτευμα τοῦ βασιλέως ἐπὶ τὴν Ἰουδαίαν καὶ γενέσθαι τῆς πόλεως ἐγκρατεῖς, ἐξελθόντας κρῖναι τὰ πράγματα τῇ τοῦ θεοῦ βοηθείᾳ."}, {"sp": "N", "st": "2 Macc 13:14", "t": "δοὺς δὲ τὴν ἐπιτροπὴν τῷ κυρίῳ τοῦ κόσμου, παρακαλέσας τοὺς σὺν αὐτῷ γενναίως ἀγωνίσασθαι μέχρι θανάτου περὶ νόμων, ἱεροῦ, πόλεως, πατρίδος, πολιτίας· περὶ δὲ Μωδιεὶμ ἐποιήσατο τὴν στρατιάν."}, {"sp": "N", "st": "2 Macc 13:15", "t": "ἀναδοὺς δὲ τοῖς περὶ αὐτὸν σύνθημα ΘΕΟΥ ΝΙΚΗΝ, μετὰ νεανίσκων ἀρίστων κεκριμένων ἐπιβαλὼν νύκτωρ ἐπὶ τὴν βασιλικὴν αὐλήν, τὴν παρεμβολὴν ἀνεῖλεν εἰς ἄνδρας δισχιλίους, καὶ τὸν πρωτεύοντα τῶν ἐλεφάντων σὺν τῷ κατʼ οἰκίαν ὄντι συνέθηκεν·"}, {"sp": "N", "st": "2 Macc 13:16", "t": "καὶ τὸ τέλος τὴν παρεμβολὴν δέους καὶ ταραχῆς ἐπλήρωσαν, καὶ ἐξέλυσαν εὐημεροῦντες."}, {"sp": "N", "st": "2 Macc 13:17", "t": "ὑποφαινούσης δὲ ἤδη τῆς ἡμέρας τοῦτο ἐγεγόνει, διὰ τὴν ἐπαρήγουσαν αὐτῷ τοῦ κυρίου σκέπην."}, {"sp": "N", "st": "2 Macc 13:18", "t": "Ὁ δὲ βασιλεὺς εἰληφὼς γεῦμα τῆς τῶν Ἰουδαίων εὐτολμίας, κατεπείρασεν διὰ μεθόδων τοὺς τόπους,"}, {"sp": "N", "st": "2 Macc 13:19", "t": "καὶ ἐπὶ Βαιθσούροις φρούριον ὀλίγον τῶν Ἰουδαίων· προσῆγεν, ἐτροποῦτο, προσενέκρουσεν, ἠλαττονοῦτο."}, {"sp": "N", "st": "2 Macc 13:20", "t": "τοῖς δὲ ἔνδον Ἰούδας τὰ δέοντα εἰσέπεμψεν."}, {"sp": "N", "st": "2 Macc 13:21", "t": "προσήγγειλεν δὲ τὰ μυστήρια τοῖς πολεμίοις Ῥόδοκος ἐκ τῆς Ἰουδαικῆς τάξεως· ἀνεζητήθη καὶ κατελήμφθη καὶ κατεκλείσθη."}, {"sp": "N", "st": "2 Macc 13:22", "t": "ἐδευτερολόγησεν ὁ βασιλεὺς τοῖς ἐν Βαιθσούροις, δεξιὰν ἔδωκεν, ἔλαβεν, ἀπῄει,"}, {"sp": "N", "st": "2 Macc 13:23", "t": "προσέβαλεν τοῖς περὶ τὸν Ἰούδαν, ἥττων ἐγένετο, μετέλαβεν ἀπονενοῆσθαι τὸν Φίλιππον ἐν Ἀντιοχίᾳ τὸν ἀπολελιμμένον ἐπὶ τῶν πραγμάτων, συνεχύθη, τοὺς Ἰουδαίους παρεκάλεσεν, ὑπετάγη, καὶ ὤμοσεν ἐπὶ πᾶσι τοῖς δικαίοις, συνελύθη καὶ θυσίαν προσήγαγεν, ἐτίμησεν τὸν νεὼ καὶ τὸν τόπον, ἐφιλανθρώπησεν"}, {"sp": "N", "st": "2 Macc 13:24", "t": "καὶ τὸν Μακκαβαῖον ἐπεδέξατο, κατέλειπεν στρατηγὸν ἀπὸ Πτολεμαίδος ἕως τῶν Γεννήρων Ἡγεμονίδην,"}, {"sp": "N", "st": "2 Macc 13:25", "t": "ἦλθεν εἰς Πτολεμαίδα· ἐδυσφόρουν περὶ τῶν συνθηκῶν οἱ Πτολεμαεῖς, ἐδειλίαζον γὰρ ὑπεράγαν· ἠθέλησαν ἀθετεῖν τὰς διαστάλσεις."}, {"sp": "N", "st": "2 Macc 13:26", "t": "προσῆλθεν ἐπὶ τὸ βῆμα Λυσίας, ἀπελογήσατο ἐνδεχομένως, συνέπεισεν καὶ κατεπρᾴυνεν, εὐμενεῖς ἐποίησεν, ἀνέζευξεν εἰς Ἀντιοχίαν. οὕτω τὰ τῆς ἐφόδου τοῦ βασιλέως καὶ τῆς ἀναζυγῆς ἐχώρησεν."}, {"sp": "N", "st": "2 Macc 14:1", "t": "Μετὰ δὲ τριετῆ χρόνον προσέπεσεν τοῖς π ερὶ τὸν Ἰούδαν, Δημήτριον τὸν τοῦ Σελεύκου διὰ τοῦ κατὰ Τρίπολιν λιμένος εἰσπλεύσαντα μετὰ πλήθους ἰσχυροῦ καὶ στόλου"}, {"sp": "N", "st": "2 Macc 14:2", "t": "κεκρατηκέναι τῆς χώρας, ἐπανελόμενον Ἀντίοχον καὶ τὸν τούτου ἐπίτροπον Λυσίαν."}, {"sp": "N", "st": "2 Macc 14:3", "t": "Ἄλκιμος δέ τις προγεγονὼς ἀρχιερεύς, ἑκουσίως δὲ μεμολυσμένος ἐν τοῖς τῆς ἀμιξίας χρόνοις, συννοήσας ὅτι καθʼ ὁντιναοῦν τρόπον οὐκ ἔστιν αὐτῷ σωτηρία οὐδέ πρὸς τὸ ἅγιον θυσιαστήριον ἔτι πρόσοδος,"}, {"sp": "N", "st": "2 Macc 14:4", "t": "ἦλθεν πρὸς τὸν βασιλέα Δημήτριον ὡς πρώτῳ καὶ ἑκατοστῷ καὶ πεντηκοστῷ ἔτει, προσάγων αὐτῷ στέφανον χρυσοῦν καὶ φοίνικα, πρὸς δὲ τούτοις τοῖς νομιζομένοις θαλλῶν τοῦ ἱεροῦ· καὶ τὴν ἡμέραν ἐκείνην ἡσυχίαν ἔσχεν."}, {"sp": "N", "st": "2 Macc 14:5", "t": "καιρὸν δὲ λαβὼν τῆς ἰδίας ἀνοίας συνεργόν, προσκληθεὶς εἰς συνέδριον ὑπὸ τοῦ Δημητρίου καὶ ἐπερωτηθεὶς ἐν τίνι διαθέσει καὶ βουλῇ καθέστηκαν οἱ Ἰουδαῖοι, πρὸς ταῦτα ἔφη"}, {"sp": "N", "st": "2 Macc 14:6", "t": "Οἱ λεγόμενοι τῶν Ἰουδαίων Ἁσιδαῖοι, ὧν ἀφηγεῖται Ἰούδας ὁ Μακκαβαῖος, πολεμοτροφοῦσιν καὶ στασιάζουσιν, οὐκ ἐῶντες τὴν βασιλείαν εὐσταθείας τυχεῖν."}, {"sp": "N", "st": "2 Macc 14:7", "t": "ὅθεν ἀφελόμενος τὴν προγονικὴν δόξαν, λέγων δὲ τὴν ἀρχιερωσύνην, δεύτερον νῦν ἐλήλυθα,"}, {"sp": "N", "st": "2 Macc 14:8", "t": "πρῶτον μὲν ὑπὲρ τῶν ἀνηκόντων τῷ βασιλεῖ γνησίως φρονῶν, δεύτερον δὲ καὶ τῶν ἰδίων πολιτῶν στοχασάμενος· τῇ μὲν γὰρ τῶν προειρημένων ἀλογιστίᾳ τὸ σύμπαν ἡμῶν γένος οὐ μικρῶς ἀκληρεῖ."}, {"sp": "N", "st": "2 Macc 14:9", "t": "ἕκαστα δὲ τούτων ἐπεγνωκὼς σύ, βασιλεῦ, καὶ τῆς χώρας καὶ τοῦ περιισταμένου γένους ἡμῶν προσνοήθητι, καθʼ ἣν ἔχεις πρὸς ἅπαντας εὐαπάντητον φιλανθρωπίαν."}, {"sp": "N", "st": "2 Macc 14:10", "t": "ἄχρι γὰρ Ἰούδας περίεστιν, ἀδύνατον εἰρήνης τυχεῖν τὰ πράγματα."}, {"sp": "N", "st": "2 Macc 14:11", "t": "τοιούτων δὲ ῥηθέντων ὑπὸ τούτου, θᾶττον οἱ λοιποὶ φίλοι δυσμενῶς ἔχοντες τὰ πρὸς τὸν Ἰούδαν προσεπύρωσαν τὸν Δημήτριον."}, {"sp": "N", "st": "2 Macc 14:12", "t": "προχειρισάμενος δὲ εὐθέως τὸν Νικάνορα τὸν γενόμενον ἐλεφαντάρχην, καὶ στρατηγὸν ἀναδείξας τῆς Ἰουδαίας, ἐξαπέστειλεν·"}, {"sp": "N", "st": "2 Macc 14:13", "t": "δοὺς ἐπιστολάς, αὐτὸν μὲν τὸν Ἰουδὰ ἐπανελέσθαι, τοὺς δὲ σὺν αὐτῷ σκορπίσαι, καταστῆσαι δὲ Ἄλκιμον ἀρχιερέα τοῦ μεγίστου ἱεροῦ."}, {"sp": "N", "st": "2 Macc 14:14", "t": "οἱ δὲ ἐπὶ τῆς Ἰουδαίας πεφυγαδευκότες τὸν Ἰούδαν ἔθνη συνέμισγον ἀγεληδὸν τῷ Νικάνορι, τὰς τῶν Ἰουδαίων ἀτυχίας καὶ συμφορὰς ἰδίας εὐημερίας δοκοῦντες ἔσεσθαι."}, {"sp": "N", "st": "2 Macc 14:15", "t": "Ἀκούσαντες δὲ τὴν τοῦ Νικάνορος ἔφοδον καὶ τὴν ἐπίθεσιν τῶν ἐθνῶν, καταπασάμενοι γῆν ἐλιτάνευσαν τὸν ἄχρι αἰῶνος συστήσαντα τὸν αὑτοῦ λαόν, ἀεὶ δὲ μετʼ ἐπιφανείας ἀντιλαμβανόμενον τῆς ἑαυτοῦ μερίδος."}, {"sp": "N", "st": "2 Macc 14:16", "t": "προστάξαντος δὲ τοῦ ἡγουμένου, ἐκεῖθεν εὐθέως ἀναζεύξας συνμίσγει αὐτοῖς ἐπὶ κώμην Λεσσαού."}, {"sp": "N", "st": "2 Macc 14:17", "t": "Σίμων δὲ ὁ ἀδελφὸς Ἰούδα συμβεβληκὼς ἦν τῷ Νικάνορι, βραδέως δέ, διὰ τὴν ἐφνίδιον τῶν ἀντιπάλων ἀφασίαν ἐπταικώς."}, {"sp": "N", "st": "2 Macc 14:18", "t": "ὅμως δὲ ἀκούων ὁ Νικάνωρ ἣν εἶχον οἱ περὶ τὸν Ἰούδαν ἀνδραγαθίαν καὶ ἐν τοῖς περὶ τῆς πατρίδος ἀγῶσιν εὐψυχίαν, ὑπευλαβεῖτο τὴν κρίσιν δι᾿ αἱμάτων ποιήσασθαι."}, {"sp": "N", "st": "2 Macc 14:19", "t": "διόπερ ἔπεμψεν Ποσιδώνιον καὶ Θεόδοτον καὶ Ματταθίαν, δοῦναι καὶ λαβεῖν δεξιάς."}, {"sp": "N", "st": "2 Macc 14:20", "t": "πλείονος δὲ γενομένης περὶ τούτων ἐπισκέψεως, καὶ τοῦ ἡγουμένου τοῖς πλήθεσιν ἀνακοινωσαμένου, καὶ φανείσης ὁμοιοψήφου συγγνώμης, ἐπένευσαν ταῖς συνθήκαις."}, {"sp": "N", "st": "2 Macc 14:21", "t": "ἐτάξαντο δὲ ἡμέραν ἐν ᾗ κατʼ ἰδίαν ἥξουσιν εἰς τὸ αὐτό· καὶ προῆλθεν παρʼ ἑκάστου δίφραξ, ἔθεσαν δίφρους."}, {"sp": "N", "st": "2 Macc 14:22", "t": "διέταξεν Ἰούδας ἐνόπλους ἑτοίμους ἐν τοῖς ἐπικαίροις τόποις, μή ποτε ἐκ τῶν πολεμίων ἐφνιδίως κακουργία γένηται· τὴν ἁρμόζουσαν ἐποιήσαντο κοινολογίαν."}, {"sp": "N", "st": "2 Macc 14:23", "t": "διέτριβεν ὁ Νικάνωρ ἐν Ἰεροσολύμοις, καὶ ἔπραττεν οὐθὲν ἄτοπον· τοὺς δὲ συναχθέντας ἀγελαίους ὄχλους ἀπέλυσεν."}, {"sp": "N", "st": "2 Macc 14:24", "t": "καὶ εἶχεν τὸν Ἰούδαν διὰ παντὸς ἐν προσωπῳ· ψυχικῶς τῷ ἀνδρὶ προσεκέκλιτο."}, {"sp": "N", "st": "2 Macc 14:25", "t": "παρεκάλεσεν αὐτὸν γῆμαι καὶ παιδοποιήσασθαι· ἐγάμησεν, εὐστάθησεν, ἐκοινώνησεν βίου."}, {"sp": "N", "st": "2 Macc 14:26", "t": "Ο δὲ Ἄλκιμος συνιδὼν τὴν πρὸς ἀλλήλους εὔνοιαν καὶ τὰς γενομένας συνθήκας λαβὼν ἦκεν πρὸς τὸν Δημήτριον, καὶ ἔλεγεν τὸν Νικάνορα ἀλλότρια φρονεῖν τῶν πραγμάτων· τὸν γὰρ ἐπίβουλον τῆς βασιλείας αὐτοῦ Ἰούδαν διάδοχον ἀπέδειξεν."}, {"sp": "N", "st": "2 Macc 14:27", "t": "ὁ δὲ βασιλεὺς ἔκθυμος γενόμενος καὶ ταῖς τοῦ πανπονήρου διαβολαῖς ἐρεθισθείς, ἔγραψεν Νικάνορι ὑπὲρ μὲν τῶν συνθηκῶν φάσκων βαρέως φέρειν, κελεύων δὲ τὸν Μακκαβαῖον δέσμιον ἐξαποστέλλειν εἰς Ἀντιοχίαν ταχέως"}, {"sp": "N", "st": "2 Macc 14:28", "t": "προσπεσόντων δὲ τούτων τῷ Νικάνορι, συνεκέχυτο, καὶ δυσφόρως ἔφερεν, εἰ τὰ διεσταλμένα ἀθετήσει μηδὲν τἀνδρὸς ἠδικηκότος."}, {"sp": "N", "st": "2 Macc 14:29", "t": "ἐπεὶ δὲ τῷ βασιλεῖ ἀντιπράττειν οὐκ ἦν, εὔκαιρον ἐτήρει στρατηγήματι τοῦ ἐπιτελέσαι."}, {"sp": "N", "st": "2 Macc 14:30", "t": "ὁ δὲ Μακκαβαῖος αὐστηρότερον διεξαγαγόντα συνιδὼν τὸν Νικάνορα τὰ πρὸς αὐτόν, καὶ τὴν ἠθισμένην ἀπάντησιν ἀγροικότερον ἐσχηκότα, νοήσας οὐκ ἀπὸ τοῦ βελτίστου τὴν αὐστηρίαν εἶναι, συστρέψας οὐκ ὀλίγους τῶν περὶ αὐτόν, συνεκρύπτετο τὸν Νικάνορα."}, {"sp": "N", "st": "2 Macc 14:31", "t": "Συγγνοὺς δὲ ὁ ἕτερος ὅτι γενναίως ὑπὸ τοῦ ἀνδρὸς ἐστρατήγηται, παραγενόμενος ἐπὶ τὸ μέγιστον καὶ ἅγιον ἱερόν, τῶν ἱερέων τὰς καθηκούσας θυσίας προσαγόντων, ἐκέλευσεν παραδιδόναι τὸν ἄνδρα."}, {"sp": "N", "st": "2 Macc 14:32", "t": "τῶν δὲ μεθʼ ὅρκων φασκόντων μὴ γινώσκειν ποῦ ποτʼ ἐστὶν ὁ ζητούμενος,"}, {"sp": "N", "st": "2 Macc 14:33", "t": "προτείνας τὴν δεξιὰν ἐπὶ τὸν νεώ, ὤμοσεν ταῦτα Ἐὰν μὴ δέσμιόν μοι τὸν Ἰούδαν παραδῶτε, τόνδε τὸν τοῦ θεοῦ σηκὸν εἰς πεδίον ποιήσω, καὶ τὸ θυσιαστήριον κατασκάψω, καὶ ἱερὸν ἐνταῦθα τῷ Διονύσῳ ἐπιφανὲς ἀναστήσω."}, {"sp": "N", "st": "2 Macc 14:34", "t": "τοσαῦτα δὲ εἰπὼν ἀπῆλθεν· οἱ δε ἱερεῖς προτείναντες τὰς χεῖρας εἰς τὸν οὐρανὸν ἐπεκαλοῦντο τὸν διὰ παντὸς ὑπέρμαχον τοῦ ἔθνους ἡμῶν, ταῦτα λέγοντες"}, {"sp": "N", "st": "2 Macc 14:35", "t": "Σύ, Κύριε, τῶν ὅλων ἀπροσδεὴς ὑπάρχων, ηὐδόκησας ναὸν τῆς σῆς σκηνώσεως ἐν ἡμῖν γενέσθαι."}, {"sp": "N", "st": "2 Macc 14:36", "t": "καὶ νῦν, ἅγιε παντὸς ἁγιασμοῦ κύριε, διατήρησον εἰς αἰῶνα ἀμίαντον τόνδε τὸν προσφάτως κεκαθερισμένον οἶκον."}, {"sp": "N", "st": "2 Macc 14:37", "t": "Ῥαζεὶς δέ τις τῶν ἀπὸ Ἰεροσολύμων πρεσβυτέρων ἐμηνύθη τῷ Νικάνορι ἀνὴρ φιλοπολίτης καὶ σφόδρα καλῶς ἀκούων, καὶ κατὰ τὴν εὔνοιαν πατὴρ τῶν Ἰουδαίων προσαγορευόμενος."}, {"sp": "N", "st": "2 Macc 14:38", "t": "ἦν γὰρ ἐν τοῖς ἔμπροσθεν χρόνοις τῆς ἀμιξίας κρίσεις εἰσενηνεγμένος Ἰουδαισμοῦ, καὶ σῶμα καὶ ψυχὴν ὑπέρ τοῦ Ἰουδαισμοῦ παραβεβλημένος μετὰ πάσης ἐκτενίας."}, {"sp": "N", "st": "2 Macc 14:39", "t": "βουλόμενος δὲ Νικάνωρ πρόδηλον ποιῆσαι ἣν εἶχεν πρὸς τοὺς Ἰουδαίους δυσμενίαν, ἀπέστειλεν στρατιώτας ὑπὲρ τοὺς πεντακοσίους συλλαβεῖν αὐτόν."}, {"sp": "N", "st": "2 Macc 14:40", "t": "ἔδοξεν γὰρ ἐκεῖνον συλλαβὼν τούτοις ἐνεργάσασθαι συμφοράν."}, {"sp": "N", "st": "2 Macc 14:41", "t": "τῶν δὲ πληθῶν μελλόντων τὸν πύργον καταλαβέσθαι καὶ τὴν αὐλαίαν θύραν βιαζομένων καὶ κελευόντων πῦρ προσάγειν καὶ τὰς θύρας ὑφάπτειν, περικατάλημπτος γενόμενος ὑπέθηκεν ἑαυτῷ τὸ ξίφος·"}, {"sp": "N", "st": "2 Macc 14:42", "t": "εὐγενῶς θέλων ἀποθανεῖν ἤπερ τοῖς ἀλιτηρίοις ὑποχείριος γενέσθαι, καὶ τῆς ἰδίας εὐγενείας ἀναξίως ὑβρισθῆναι."}, {"sp": "N", "st": "2 Macc 14:43", "t": "τῇ δὲ πληγῇ μὴ κατευθικτήσας διὰ τὴν τοῦ ἀγῶνος σπουδήν, καὶ τῶν ὄχλων ἔσω τῶν θυρωμάτων εἰσβαλλόντων, ἀναδραμὼν γενναίως ἐπὶ τὸ τεῖχος, κατεκρήμνισεν ἑαυτὸν ἀνδρωδῶς εἰς τοὺς ὄχλους."}, {"sp": "N", "st": "2 Macc 14:44", "t": "τῶν δὲ ταχέως ἀναποδισάντων, γενομένου διαστήματος, ἦλθεν κατὰ μέσον τὸν κενεῶνα."}, {"sp": "N", "st": "2 Macc 14:45", "t": "ἔτι δὲ ἔμπνους ὑπάρχων καὶ πεπυρωμένος τοῖς θυμοῖς, ἐξαναστὰς φερομένων κρουνηδὸν τῶν αἱμάτων, καὶ δυσχερῶν τῶν τραυμάτων ὄντων, δρόμῳ τοὺς ὄχλους διελθών, καὶ στὰς ἐπί τινος πέτρας ἀπορρῶγος,"}, {"sp": "N", "st": "2 Macc 14:46", "t": "παντελῶς ἔξαιμος ἤδη γινόμενος, προβαλὼν τὰ ἔντερα καὶ λαβὼν ἑκατέραις ταῖς χερσίν, ἐνέσεισε τοῖς ὄχλοις· καὶ ἐπικαλεσάμενος τὸν δεσπόζοντα τῆς ζωῆς καὶ τοῦ πνεύματος τὰ αὐτὰ αὐτῷ πάλιν ἀποδοῦναι, τόνδε τὸν τρόπον μετήλλαξεν."}, {"sp": "N", "st": "2 Macc 15:1", "t": "Ὁ δὲ Νικάνωρ μεταλαβὼν τοὺς περὶ τὸν Ἰούδαν ὄντας ἐν τοῖς κατὰ Σαμάρειαν τόποις, ἐβουλεύσατο τῇ τῆς καταπαύσεως ἡμέρᾳ μετὰ πάσης ἀσφαλείας αὐτοῖς ἐπιβαλεῖν."}, {"sp": "N", "st": "2 Macc 15:2", "t": "τῶν δὲ κατὰ ἀνάγκην συνεπομένων αὐτῷ Ἰουδαίων λεγόντων Μηδαμῶς οὕτως ἀγρίως καὶ βαρβάρως ἀπολέσῃς, δόξαν δὲ ἀπομέρισον τῇ προτετιμημένῃ ὑπὸ τοῦ πάντα ἐφορῶντος μεθʼ ἁγιότητος ἡμέρᾳ·"}, {"sp": "N", "st": "2 Macc 15:3", "t": "ὁ δὲ τρισαλιτήριος ἐπηρώτησεν εἰ ἔστιν ἐν οὐρανῷ ὁ δυνάστης ὁ προστεταχὼς ἄγειν τὴν τῶν σαβάτων ἡμέραν·"}, {"sp": "N", "st": "2 Macc 15:4", "t": "τῶν δʼ ἀποφηναμένων Ἔστιν ὁ κύριος ζῶν αὐτὸς ἐν οὐρανῷ δυνάστης ὁ κελεύσας ἀσκεῖν τὴν ἑβδομάδα·"}, {"sp": "N", "st": "2 Macc 15:5", "t": "ὁ δὲ ἕτερος Κἀγώ, φησίν, δυνάστης ἐπὶ τῆς γῆς, ὁ προστάσσων αἴρειν τὰ ὅπλα καὶ τὰς βασιλικὰς χρείας ἐπιτελεῖν. ὅμως οὐ κατέσχεν ἐπιτελέσαι τὸ σχέτλιον αὐτοῦ βούλημα."}, {"sp": "N", "st": "2 Macc 15:6", "t": "Καὶ ὁ μὲν Νικάνωρ μετὰ πάσης ἀσφαλείας ὑψαυχενῶν, διεγνώκει κοινὸν τῶν περὶ τὸν Ἰούδαν συστήσασθαι τρόπον."}, {"sp": "N", "st": "2 Macc 15:7", "t": "ὁ δὲ Μακκαβαῖος ἦν ἀδιαλείπτως πεποιθὼς μετὰ πάσης ἐλπίδος ἀντιλήμψεως τεύξασθαι παρὰ τοῦ κυρίου."}, {"sp": "N", "st": "2 Macc 15:8", "t": "καὶ παρεκάλει τοὺς σὺν αὐτῷ μὴ δειλιᾶν τὴν τῶν ἐθνῶν ἔφοδον, ἔχοντας δὲ κατὰ νοῦν τὰ προγεγονότα αὐτοῖς ἀπʼ οὐρανοῦ βοηθήματα, καὶ τὰ νῦν προσδοκᾷν τὴν παρὰ τοῦ παντοκράτορος ἐσομένην αὐτοῖς νίκην."}, {"sp": "N", "st": "2 Macc 15:9", "t": "καὶ παραμυθούμενος αὐτοὺς ἐκ τοῦ νόμου καὶ τῶν προφητῶν, προσυμνήσας δὲ αὐτοὺς καὶ τοὺς ἀγῶνας οὓς ἦσαν ἐκτετελεκότες, προθυμοτέρους αὐτοὺς κατέστησεν."}, {"sp": "N", "st": "2 Macc 15:10", "t": "καὶ τοῖς θυμοῖς διεγείρας αὐτοὺς παρήγγειλεν, ἅμα παρεπιδεικνὺς τὴν τῶν ἐθνῶν ἀθεσίαν καὶ τὴν τῶν ὅρκων παράβασιν."}, {"sp": "N", "st": "2 Macc 15:11", "t": "ἕκαστον δὲ αὐτῶν καθοπλίσας οὐ τὴν ἀσπίδων καὶ λογχῶν ἀσφαλίαν, ὡς τὴν ἐν τοῖς ἀγαθοῖς λόγοις παράκλησιν, καὶ προσηγησάμενος ὄνειρον ἀξιόπιστον ὑπέρ τι πάντας ηὔφρανεν."}, {"sp": "N", "st": "2 Macc 15:12", "t": "ἦν δὲ ἡ τούτου θεωρία τοιάδε· Ὀνίαν τὸν γενόμενον ἀρχιερέα ἄνδρα καλὸν καὶ ἀγαθόν, αἰδήμονα μὲν τὴν ἀπάντησιν, πρᾷον δὲ τὸν τρόπον, καὶ λαλιὰν προιέμενον πρεπόντως καὶ ἐκ παιδὸς ἐκμεμελετηκότα πάντα τὰ τῆς ἀρετῆς ἴδια, τοῦτον τὰς χεῖρας προτείναντά κατεύχεσθαι τῷ παντὶ τῶν Ἰουδαίων συστήματι·"}, {"sp": "N", "st": "2 Macc 15:13", "t": "εἶθ᾿ οὕτως ἐπιφανῆναι ἄνδρα πολιᾷ καὶ δόξῃ διαφέροντα, θαυμαστὴν δέ τινα καὶ μεγαλοπρεπεστάτην εἶναι τὴν περὶ αὐτὸν ὑπεροχήν·"}, {"sp": "N", "st": "2 Macc 15:14", "t": "ἀποκριθέντα δὲ τὸν Ὀνίαν εἰπεῖν Ὁ φιλάδελφος οὗτός ἐστιν ὁ πολλὰ προσευχόμενος περὶ τοῦ λαοῦ καὶ τῆς ἁγίας πόλεως Ἰερεμίας ὁ τοῦ θεοῦ προφήτης."}, {"sp": "N", "st": "2 Macc 15:15", "t": "προτείναντα δὲ Ἰερεμίαν τὴν δεξιὰν παραδοῦναι τῷ Ἰούδᾳ ῥομφαίαν χρυσῆν, διδόντα δὲ προσφωνῆσαι τάδε"}, {"sp": "N", "st": "2 Macc 15:16", "t": "Λάβε τὴν ἁγίαν ῥομφαίαν δῶρον παρὰ τοῦ θεοῦ, δι᾿ ἧς θραύσεις τοὺς ὑπεναντίους."}, {"sp": "N", "st": "2 Macc 15:17", "t": "Παρακληθέντες δὲ τοῖς Ἰούδου λόγοις πάνυ καλοῖς καὶ δυναμένοις ἐπʼ ἀρετὴν παρορμῆσαι καὶ ψυχὰς νέων ἐπανδρῶσαι, διέγνωσαν μὴ στρατεύεσθαι, γενναίως δὲ ἐνφέρεσθαι, καὶ μετὰ πάσης εὐανδρείας ἐμπλακέντες κρῖναι τὰ πράγματα, διὰ τὸ καὶ τὴν πόλιν καὶ τὰ ἅγια καὶ τὸ ἱερὸν κινδυνεύειν."}, {"sp": "N", "st": "2 Macc 15:18", "t": "ἦν γὰρ ὁ περὶ γυναικῶν καὶ τέκνων, ἔτι δὲ ἀδελφῶν καὶ συγγενῶν, ἐν ἥττονι μέρει κείμενος αὐτοῖς, μέγιστος δὲ καὶ πρῶτος ὁ περὶ τοῦ καθηγιασμένου ναοῦ φόβος."}, {"sp": "N", "st": "2 Macc 15:19", "t": "ἦν δὲ καὶ τοῖς ἐν τῇ πόλει κατειλημμένοις οὐ πάρεργος ἀγωνία, ταρασσομένοις τῆς ἐν ὑπαίθρῳ προσβολῆς."}, {"sp": "N", "st": "2 Macc 15:20", "t": "Καὶ πάντων ἤδη προσδοκώντων τὴν ἐσομένην κρίσιν, καὶ ἤδη προσμιξάντων τῶν πολεμίων καὶ τῆς στρατιᾶς ἐκταγείσης, καὶ τῶν θηρίων ἐπὶ μέρος εὔκαιρον ἀποκατασταθέντων, τῆς δὲ ἵππου κατὰ κέρας τεταγμένης·"}, {"sp": "N", "st": "2 Macc 15:21", "t": "συνιδὼν ὁ Μακκαβαῖος τὴν τῶν πληθῶν παρουσίαν καὶ τῶν ὅπλων τὴν ποικίλην παρασκευήν, τήν τε τῶν θηρίων ἐπὶ μέρος εὔκαιρον ἀγριότητα, ἀνατείνας χεῖρας εἰς τὸν οὐρανόν, ἐπεκαλέσατο τὸν τερατοποιὸν κύριον, γινώσκων ὅτι οὐκ ἔστιν δι᾿ ὅπλων, καθὼς δὲ ἐὰν αὐτῷ κριθῇ, τοῖς ἀξίοις περιποιεῖται τὴν νίκην."}, {"sp": "N", "st": "2 Macc 15:22", "t": "ἔλεγεν δὲ ἐπικαλούμενος τόνδε τὸν τρόπον Σύ, δέσποτα, ἀπέστειλας τὸν ἄγγελόν σου ἐπὶ Ἑζεκίου τοῦ βασιλέως τῆς Ἰουδαίας, καὶ ἀνεῖλεν ἐκ τῆς παρεμβολῆς Σενναχηρεὶμ εἰς ἑκατὸν ὀγδοήκοντα πέντε χιλιάδας."}, {"sp": "N", "st": "2 Macc 15:23", "t": "καὶ νῦν, δυνάστα τῶν οὐρανῶν, ἀπόστειλον ἄγγελον ἀγαθὸν ἔμπροσθεν ἡμῶν εἰς δέος καὶ τρόμον·"}, {"sp": "N", "st": "2 Macc 15:24", "t": "μεγέθει βραχίονός σου καταπλαγείησαν οἱ μετὰ βλασφημίας παραγινόμενοι ἐπὶ τὸν ἅγιόν σου λαόν. καὶ οὗτος μὲν ἐν τούτοις ἔληξεν."}, {"sp": "N", "st": "2 Macc 15:25", "t": "Οἱ δὲ περὶ τὸν Νικάνορα μετὰ σαλπίγγων καὶ παιάνων προσῆγον·"}, {"sp": "N", "st": "2 Macc 15:26", "t": "οἱ δὲ περὶ τὸν Ἰούδαν μετὰ ἐπικλήσεως καὶ εὐχῶν συνέμιξαν τοῖς πολεμίοις."}, {"sp": "N", "st": "2 Macc 15:27", "t": "καὶ ταῖς μὲν χερσὶν ἀγωνιζόμενοι, ταῖς δὲ καρδίαις πρὸς τὸν θεὸν εὐχόμενοι, κατέστρωσαν οὐδὲν ἧττον μυριάδων τριῶν καὶ πεντακισχιλίων, τῇ τοῦ θεοῦ μεγάλως εὐφρανθέντες ἐπιμελείᾳ."}, {"sp": "N", "st": "2 Macc 15:28", "t": "Γενόμενοι δὲ ἀπὸ τῆς χρείας καὶ μετὰ χαρᾶς ἀναλύοντες, ἐπέγνωσαν προπεπτωκότα Νικάνορα σὺν τῇ πανοπλίᾳ."}, {"sp": "N", "st": "2 Macc 15:29", "t": "γενομένης δὲ κραυγῆς καὶ ταραχῆς, εὐλόγουν τὸν δυνάστην τῇ πατρίῳ φωνῇ."}, {"sp": "N", "st": "2 Macc 15:30", "t": "καὶ προσέταξεν ὁ καθʼ ἅπαν σώματι καὶ ψυχῇ πρωταγωνιστὴς ὑπέρ τῶν πολιτῶν, ὁ τὴν τῆς ἡλικίας εὔνοιαν εἰς ὁμοεθνεῖς διαφυλάξας, τὴν τοῦ Νικάνορος κεφαλὴν ἀποτεμόντας, καὶ τὴν χεῖρα σὺν τῷ ὤμῳ, περιφέρειν εἰς Ἰεροσόλυμα."}, {"sp": "N", "st": "2 Macc 15:31", "t": "παραγενόμενος δὲ ἐκεῖ, καὶ συνκαλεσάμενος τοὺς ὁμοεθνεῖς καὶ τοὺς ἱερεῖς πρὸ τοῦ θυσιαστηρίου στήσας, μετεπέμψατο τοὺς ἐκ τῆς ἄκρας."}, {"sp": "N", "st": "2 Macc 15:32", "t": "καὶ ἐπιδεξάμενος τὴν τοῦ μιεροῦ Νικάνορος κεφαλὴν καὶ τὴν χεῖρα τοῦ δυσφήμου, ἣν ἐκτείνας ἐπὶ τὸν ἅγιον τοῦ παντοκράτορος οἶκον ἐμεγαλαύχησεν,"}, {"sp": "N", "st": "2 Macc 15:33", "t": "καὶ τὴν γλῶσσαν τοῦ δυσσεβοῦς Νικάνορος ἐκτεμών, ἔφη μετὰ μέρος τοῖς ὀρνέοις, τὰ δʼ ἐπίχειρα τῆς ἀνοίας κατέναντι τοῦ ναοῦ κρεμάσαι."}, {"sp": "N", "st": "2 Macc 15:34", "t": "οἱ δὲ πάντες εἰς τὸν οὐρανὸν εὐλόγησαν τὸν ἐπιφανῆ κύριον, λέγοντες Εὐλογητὸς ὁ διατηρήσας τὸν ἑαυτοῦ τόπον ἀμίαντον."}, {"sp": "N", "st": "2 Macc 15:35", "t": "ἐξέδησεν δὲ τὴν τοῦ Νικάνορος προτομὴν ἐκ τῆς ἄκρας ἐπίδηλον πᾶσιν, καὶ φανερὸν τῆς τοῦ κυρίου βοηθείας σημεῖον."}, {"sp": "N", "st": "2 Macc 15:36", "t": "ἐδογμάτισαν δὲ πάντες μετὰ κοινοῦ ψηφίσματος μηδαμῶς ἐᾶσαι ἀπαρασήμαντον τήνδε τὴν ἡμέραν· (37)ἔχειν δὲ ἐπίσημον τὴν τρισκαιδεκάτην τοῦ δωδεκάτου μηνός —Ἀδὰρ λέγεται τῇ κυριακῇ φωνῇ —πρὸ μιᾶς ἡμέρας τῆς Μαρδοχαικῆς ἡμέρας."}, {"sp": "N", "st": "2 Macc 15:37", "t": "Τῶν οὖν κατὰ Νικάνορα χωρησάντων οὕτως, καὶ ἀπʼ ἐκείνων τῶν καιρῶν κρατηθείσης τῆς πόλεως ὑπὸ τῶν Ἐβραίων, καὶ αὐτὸς αὐτόθι τὸν λόγον καταπαύσω."}, {"sp": "N", "st": "2 Macc 15:38", "t": "καὶ εἰ μὲν καλῶς, εὐθίκτως τῇ συντάξει, τοῦτο καὶ αὐτὸς ἤθελον· εἰ δὲ εὐτελῶς καὶ μετρίως, τοῦτο ἐφικτὸν ἦν μοι."}, {"sp": "N", "st": "2 Macc 15:39", "t": "καθάπερ οἶνον κατὰ μόνας πίνειν, ὡσαύτως δὲ καὶ ὕδωρ πάλιν πολέμιον· ὃν δὲ τρόπον οἶνος ὕδατι συνκερασθεὶς ἤδη καὶ ἐπιτερπῆ τὴν χάριν ἀποτελεῖ, οὕτως καὶ τὸ τῆς κατασκευῆς τοῦ λόγου τέρπει τὰς ἀκοὰς τῶν ἐντυγχανόντων τῇ συντάξει. Ἐνταῦθα δὲ ἔσται ἡ τελευτή."}, {"sp": "N", "t": "<i>Greek text: H. B. Swete, The Old Testament in Greek according to the Septuagint, as prepared by the Open Greek and Latin project (CC BY-SA 4.0).</i>"}],[]);})();